[63265205]="انتظر... لا مزيد!",
[63620574]="أنا أبكي هنا! أرجوك، أوقف المضحك!",
[63656593]="لقد كان محقًا، كما تعلم. سأضطر لأخذ هذه العبارة لنفسي... ليس كما لو كان سيحتاجها بعد الآن!",
[63831901]="فقط وجهني نحو العدو!",
[63941581]="أنا جائع جدًا! يم!",
[64161009]="أيتها القدماء، أرشدوا يدي... استيقظوا من سباتكم! استيقظوا واختموا هذا المكان الملعون!",
[64479496]="انتظر لحظة...",
[65078907]="إي، مون! خذني إلى إخواني الترولز!",
[65573742]="واهيهي! سوف أنزلك معاي!",
[66427442]="ما الأمر الآن، غراڤل؟",
[66483174]="ما معنى هذا؟ حراس!",
[66581238]="انظر، مورادين، خلاصنا، فروستمورن.",
[67239935]="هجومي سوف يغمر قوات الـليتش كينغ!",
[67575474]="ساندويتش؟ ماذا؟ أتصنع لي ساندويتشًا يا أبي؟",
[67632318]="لماذا جلبك غوريجيك أصلًا؟ أنت عديم الفائدة.",
[68687796]="استسلم لخوفك.",
[69162335]="آخر سوف يأخذ مكاني. عالمك محكوم عليه...",
[69523240]="أنا مكرم... $Gملك:ملكة; يقتلني.",
[69846988]="هاه، السماوات ليست صديقة جدًا مع $N يحلقها!",
[70305012]="الآن أين وضعت تركيبات شركة فينتشر؟",
[70515477]="سننتشر عبر هذه الأرض القاحلة!",
[70544216]="هاه!",
[70624179]="لا بأس يا أولاد. تراجعوا. لقد فعلتم ما يكفي. سألتقي بكم لاحقًا.",
[71135649]="كنت أنتظرك أيها الصغير. اقترب - عيناي لم تعد حادتين كما كانتا.",
[71510956]="هذا كل شيء! هذا ما وصلت إليه... ما رأيك؟",
[71523032]="أيها الأكياس البائسة من لحم الديدان، يمكنكم أن تفعلوا أفضل من ذلك، الآن أثبتوا ذلك!",
[71645966]="المنشآت الدفاعية الأساسية تتكون من إنشاءات حديدية ومنارات العاصفة، والتي ستولد إنشاءات إضافية عند الحاجة. الأنظمة الثانوية تتكون من منشآت دفاعية مدارية.",
[72342041]="أوه، يا إلهي!",
[72468150]="فليبدأ!",
[73445373]="قاتل!",
[73666590]="أناثيرا!",
[73673197]="هذا سيعلمك أن تترك الأعشاب، $R.",
[73740458]="سأتفقد ذلك فورًا.",
[73835908]="لن تؤذي $Gولد:بنت;، مورغور! بسرعة، $N، تسلق على ظهري!",
[73946282]="المزيد من الطعام! المزيد من النبيذ!",
[73965619]="لا مكان للهرب، أيها الوحش!",
[74112947]="مخبأ دون بالدار الجنوبي يتعرض لهجوم! إذا تُرك دون رد، سيدمره الأليانس!",
[74728615]="انتبه! $N يهاجم!",
[75324608]="أتجرؤون على وضع أقدامكم على أرض الهاكاري المقدسة؟ أتباع هاكار، دمروا الكفار!",
[75671912]="أخرجوني من هنا!",
[75741416]="%s يمتص الطاقة السحرية للهجوم.",
[75755909]="هل تظنون أنفسكم مستحقين لمجرد أنكم هزمتم حراسي؟ عملنا هنا لن يتعرض للخطر!",
[75780949]="وحاول ألا تضيع هذه المرة...",
[75817302]="حسنًا...",
[75842629]="ديجا فو. للحظة، ظننت أنني عدت إلى المنزل... قبل الطاعون...",
[75943855]="لتنزل النار من السماء!",
[76179059]="قوات الـليتش كينغ تتزايد. من الضروري أن يدعم جدولنا الزمني خططه.",
[77017482]="كلهم يذهبون إلى الـسباير لكن لا أحد يعود... تمامًا مثل بيجو.",
[77325108]="هذه السادسة عشرة وما زلت أسهّل عليك!",
[77627511]="اسمع، أيها الديث نايت... اسمع صوت سيدك. إنه يناديك الآن.",
[78343196]="أنت تضيع وقتي!",
[78724756]="حسنًا. قبل أن ننزل إلى هناك، خذ لحظة لتجهيز نفسك.",
[79139504]="قرودك فشلوا في إنهاء المهمة، أيها نارو. مضرورون لكن أحياء... لم نكرر نفس الخطأ عندما استولينا على سفينتك.",
[80333793]="مرحبًا. السيد فراس سيابي غير موجود حاليًا. يرجى العودة غدًا إلى تبغ سيابي الفاخر! بيب!",
[80510248]="%s يتنهد.",
[80814375]="يا للصدف. أعتقد أن هذا يستدعي بعض النبيذ.",
[80882360]="آها! وجدت واحدة!",
[80902919]="حان وقت نصيحة داجيك الذكية! الكريستالات تجسوف الظهر شوي. لا تجرب.",
[81190407]="يبدو أن هناك مكانًا لواحد إضافي... لا، أخطأت. هذا سبعة وليس واحدًا. أتمنى أن تكون بارعًا بالسيف - توجّه إلى الثكنات.",
[81645014]="كلاب الأليانس الغادرة! تستدعون سيد شياطين ضد محاربي الـهورد؟ موتكم سريع!",
[82667168]="تبدو مغرمًا. شخص مميز يثقل عليك، أليس كذلك؟ لا تقلق، لا تقلق. خذ هذه الميدالية مني، والبسها عندما تراه، وسيهتم بك تمامًا، $Gيا رجل:يا عزيزتي;!",
[83293010]="نعم يا جندي! وقت الإقلاع!",
[83652517]="جنودك يُستخدمون كدروع بشرية لصد نيران المدفعية في وادي الأصداء، مما يسمح لقوات الـليتش كينغ بمهاجمة قاعدتك دون عائق.",
[83709569]="وداعًا.",
[84215112]="أزيروث قد اختبأ تحت ظلنا طويلاً! الآن، اشعر بقوة البيرنينغ كروسيد وايأس!",
[84507962]="اعتني بذلك اللمعان، $C.",
[84634997]="ماذا يحدث؟",
[84819329]="أعلن أنك عدو لعشائر أوقر. العقوبة هي الموت!",
[85120433]="هذه هي اللحظة التي كنا ننتظرها جميعًا! وارمول تشامبيون على وشك الظهور لأول مرة في حلبة الدم منذ أسابيع! هل سينهزم $N بسهولة مثل خصوم البطل الآخرين؟ سنرى...",
[85139582]="قريب جدًا هذه المرة. أعتقد أننا أوشكنا على إتقانها.",
[85467346]="أرِ هذا الوافد الجديد كيف يقاتل بلود نايت الحقيقي، سويفت بليد!",
[85883511]="كل شيء جاهز، يا محارب الحرب.",
[86335809]="اطرد هذه الحثالة من موطن الفيريكول!",
[86783967]="بدء تحليل معبد الاختراع.",
[86836896]="%s يحدق بك في دهشة محضة.",
[86840487]="لا يمكن أن يكون هذا الخام قد صُنع إلا بقوة خبيثة هائلة. محاولة الوصول إلى قواعد البيانات لمزيد من المعلومات...",
[86934898]="أراك!",
[87164851]="أتساءل إن كنا سنحل لغز الخام الغريب يومًا. لا بد أن له فائدة!",
[87510744]="ها نحن ذا، $N. السم جاهز.",
[87591345]="آرثاس مستعد لمنحك قوة تفوق خيالك. الجيش التافه الذي تقوده هنا سيبدو ضئيلًا مقارنة بالكتائب التي ستكون تحت إمرتك إذا عدت إلى أحضان الـسكورج.",
[87722051]="خائن!",
[88470847]="يا للروعة، يا رجل. هذه الخردة ممكن تنجح في النهاية...",
[88874938]="ألن تحب أن تعرف؟",
[88947363]="إطلاق.",
[88960503]="حتى أقوى أتباع الـليتش كينغ لا يمكنهم الصمود أمام الأليانس. المجد لفائزينا!",
[89235632]="ملل؟ كان على وشك الموت!",
[89481099]="سأحتاج إلى تنظيف ومساعد جديد هنا!",
[89504758]="الكل جاهز؟",
[89756450]="ششش... عندي سر صغير كنت أخفيه.",
[90144380]="استرخِ، سبارك! كل شيء تحت السيطرة. سنقوم بتجريد إكسودار من تحت أرجلهم - مما يجعلني وإياك أغنياء جدًا جدًا في هذه العملية.",
[90435650]="همم، أعتقد أنها قد تنجح. لكنها تحتاج إلى القليل من القوة الإضافية!",
[90529185]="مبارزتك ضعيفة!",
[91106664]="مقبرة آيس بلود تم الاستيلاء عليها من قبل الـهورد!",
[91399815]="ملعونون إلى الأبد!",
[91630524]="يا له من قوة عجيبة! جعلتني كرة الظلام الخالدة لا يُقهر!",
[91807801]="أقول نشغلها. اقطع الحبل.",
[91863355]="كل شيء أصبح غريبًا مؤخرًا...",
[91882413]="برج آيسبلود سقط بيد الـهورد!",
[92228668]="هل حياتك بهذه القلة؟ فقط أخبرني ما أريد معرفته عن \"كرايمن داون\" وسأنهي معاناتك بسرعة.",
[92533973]="بابا يقدر يصيد سمك أكثر من باباك!",
[92550845]="انتهى وقتك، يا عبد الماضي.",
[92802871]="نعم؟",
[92915402]="حان وقت لقاء خالقك!",
[93540861]="%s يموت.",
[93567100]="واو! هذا حقًا يدهن مقابس البخار!",
[93642259]="ألم أخبرك أن تقنياتي الجديدة في السيطرة ستعمل؟",
[93802796]="%s تومئ بالشكر.",
[93856548]="المعركة على وشك البدء! هل أقرأ هذه البطاقة بشكل صحيح؟ إنها... إنها سيد الماغناتور الخبيث، ستينكبيرد! نعم، يا ناس، ستينكبيرد! $N ليس لديه فرصة!",
[93986392]="بال، لامر زيتا!",
[94290754]="تذكري يا عزيزتي، نحتاج للحصول على قطعة أرض بها ينبوع حار جميل.",
[94392362]="لن أكذب عليكم أيها الجنود. نحن نتلقى ضربات موجعة هناك! الآن من منكم أورك بما يكفي ليفعل شيئًا حيال ذلك؟",
[94894897]="لقد تخلت عنا الآلهة! يجب أن نتخلص منه قبل أن يتم إبلاغ يميرون!",
[95213603]="سمعت أن تيري باع واحدة من تلك اللوحات بألف قطعة ذهبية. ربما يمكنني الدخول في تجارة الأعمال الفنية أيضًا!",
[95218517]="هذه آخر مرة أشتري فيها معدات مستعملة من إثيري!",
[95465648]="أعتقد أنني سأتغذى على لحم $R ولحم الأوغر الليلة.",
[95530935]="يجب ألا يُسمح لقبيلة بلاكوود بالتدخل في تقدم الطبيعة.",
[95539765]="[فوربولق] نذهب الآن، معًا. سنبحث عن فارك.",
[96216380]="إنهم جائعون....",
[96632292]="احذروا: أنا حي!",
[96801116]="سألتهمك!",
[97285931]="آه آه آه...",
[97528363]="آه! مواد ممتازة.",
[97775167]="الهيكل بالأعلى بدأ يطن بالطاقة.",
[98172839]="باكستر! تعال إلى هنا وساعد! الآن!",
[98184950]="فقط الأقوياء يجب أن يبقوا. ناهيك عن...",
[98205924]="عندما يطير الدوارف! هل يفعلون؟ إذن نعم!",
[98691606]="يجب أن نواصل الآن.",
[98931289]="كابتن، سيدي، عندنا مشكلة بسيطة.",
[99945991]="لا شيء يقول الحب مثل ضربة خفيفة على الرأس.",
[100151378]="أجل، تورتة. مهما تشتهي نفسك...",
[100431102]="على ماذا تتحدق؟ هل رأيت عبقريًا من قبل؟",
[100500634]="الآن ستبقى... للأبد.",
[100537801]="طمعك وحماقتك أوصلاك لهذه النهاية.",
[100811749]="تم اكتشاف تحميل زائد في القلب. إعادة شحن...",
[100865291]="أمير، الخروج والانتهاء.",
[100951566]="قد تكون قتلت فالدوران، لكن ذلك لن يمنعني من إكمال الكولوسس.",
[101329771]="الأليانس لا يحتاج مساعدة سيد شيطان للتعامل مع قذارة الـهورد! تعال، أيها الخنزير!",
[101528713]="لا تقلق، ستحتفظ بكل أصابع يديك وقدميك.",
[102089990]="بالفعل، هذا ليس طلبًا.",
[102303471]="هل أنت مستعد، مستر فلوبي؟ ابقَ قريبًا مني واحترس من تلك الذئاب!",
[103326274]="يجب جمع جوهر الرياح العاتية لحُراس كيتزلون المتوفين لاستدعائه. يجب تسليم هاتين الندرة إلى هاركوا.",
[103419273]="دخلاء! اقتلوهم!",
[103899252]="ما الذي ترغب فيه، $Gسيدي:آنسة;؟",
[103982540]="%s يضع الدمعة في وعاء من الحساء.",
[104063175]="سأخدم السيد... في الموت!",
[104328498]="تحلل الكوكب والكائنات الحية فيه إلى عناصر أساسية: معادن، صخور، غازات. يلي ذلك فترة إعادة تكوين كل عنصر إلى المخطط الكوكبي الأصلي.",
[104332014]="أتفهم يا صديقي. سأجد من يساعد سيدك. ارجع إليه الآن، أو على الأقل ابقَ قريبًا.",
[104339754]="إنه $N! احنوا رؤوسكم!",
[105410355]="هل تتخيل؟",
[105899685]="أيها الفاني الأحمق، سأمزق روحك إربًا حالما أتحرر!",
[106081620]="هل أنت متأكد أن أحدًا لم يتتبعك إلى هنا؟ لدي شعور سيء جدًا فجأة...",
[106910017]="و... إن لم نفعل؟",
[107069568]="أستسلم! أرجوك لا تقتلني!",
[107556790]="سنبدأ عند أول برج طاقة هناك، أمامك مباشرة. تذكر، حاول إبعادهم عني.",
[107887077]="الـ بيست قُتل! كل شيء بخير في داركشاير!",
[108686101]="المسارات الزمنية مرتبة حاليًا من الأقل كارثية إلى الأكثر كارثية. لاحظ أنها جميعًا مصنفة ككارثية، مما يعني أن انهيار أي مسار منها سينهي عالمك. نحن نصنفها بهذه الطريقة فقط ليعرف الأبطال والمغامرون الذين يُرسلون إلى هنا أي مسار يناسب قدراتهم.",
[108769107]="أخبر إمبيريان أنني سأفكر في وقف الأعمال العدائية. لكن أولاً، على تشيرن أن يوقف اقتحاماته المائية على مرتفعي!",
[108981009]="ششش... كل شيء سينتهي قريبًا.",
[109382771]="%s يموت متأثرًا بجراحه.",
[109669341]="بعد تفكير، احتفظ بالحقيبة كلها. يجب أن، آه، أمضي.",
[110436709]="%s يقضم الطعم بنهم.",
[110541301]="كل شيء... يعود إليّ....",
[110799969]="نار! نار، يا كلاب البحر الصفراء!",
[111143613]="لا نحتاج أمثالك هنا.",
[111537671]="%s يصيح ويتجه نحو فيل شالاس. أسرع واتبع!",
[111545537]="يمكنني بيع هذه الأشياء لبقية الجوبلنز؟ سأصبح غنيًا! غني، أقول!",
[111698369]="أنا أملكك!",
[112136166]="إنه هنا في نورثرند يا أخي، يبحث عنك. أحد العرافين في وينترغارد أخبره أنك لم تمت، وغادر فورًا إلى آيرونفورج ليأتي إليك.",
[112789544]="لقد خيبت ظني يا تايلان. كان لدي خطط لك... خطط عظيمة. للأسف، كانت مسألة وقت فقط قبل أن يلحق بك سلالتك القذرة.",
[113391986]="شكرًا لك يا $N. لقد هدأت الغضب البارد في قلبي.",
[113445287]="العشاء... قد حضر.",
[113989353]="أغبياء! لا يمكنكم فهم القوى التي أطلقتموها. لن يتم تعطيل قناة خطوط الطاقة! هزيمتكم ستكون مطلقة!",
[114505979]="تم التحقق من سلامة معبد النظام.",
[114551803]="لا! لقد قتلت ستينكي! ستدفع الثمن!",
[114679969]="صراخ المحتضرين سيملأ الأجواء. سيمفونية الرعب على وشك البدء!",
[115335057]="أوتش! انتبه أين تسحب!",
[115415943]="تاريثا يجب أن يكون في النزل. لنذهب.",
[116380010]="ريش، هوكتا!",
[116518973]="حجر الربط يتحطم، محررًا الروح التي كان يحتجزها.",
[116559583]="لقد تم تدمير اشعاري كريستالز! المسلخ أصبح ضعيفًا!",
[116580825]="اشهدوا على القوة التي لا تُقهر لسيدنا المظلم!",
[117164644]="احتضن الظلام... الظلام الأبدي.",
[117259989]="أنا أشم رائحة الأحياء!",
[117467308]="لا، لا - هذا قد ينجح!",
[117529675]="لا بأس، لقد اكتفيت من هذا المكان.",
[117890720]="العدالة تحققت!",
[118724511]="أيها $N التافهون! أصدقاؤكم سيلحقون بكم قريبًا!",
[119249642]="ساندرز، ماذا لديك في ذلك الصندوق؟",
[119550599]="حسنًا، حسنًا... أعطني دقيقة لأرتاح الآن. لقد ضربتني جيدًا.",
[119847014]="هذه برقية غنائية لـ$N: الورود حمراء، والبنفسج أزرق، سأقتل أي $R أراه، بمن فيهم أنت!",
[119998010]="دع غيوم العاصفة ترتفع وتمطر الموت من الأعلى!",
[120531981]="برج القلعة الجنوبي الشرقي قد تضرر!",
[121373552]="نهّابون! مدنّسون!",
[122121056]="$N، لقد تأكدت أن هذا الدم من عشيرة بونكيو من الأوركس، ملوث بقوة شيطانية. لكني أخشى أن معداتي الحالية لا تستطيع التعمق أكثر في هذا اللغز...",
[122179923]="نحن محاصرون!",
[122645457]="كيف تأمل في الصمود أمام هذه القوة الساحقة؟",
[122881305]="لقد كنت أنتظر هنا منذ الأبد منذ لقائنا الأخير! متى سينتهي غوراموش من طقسه؟",
[123368702]="جزار! موت!",
[123382119]="حسنًا، لست متأكدًا كم سأصمد بهذه الحالة... أشعر بدوار...",
[123383805]="%s يبدو أنه يبحث عن شيء. يريدك أن تتبعه.",
[123580430]="شكرًا لتحريري، $N! سأتوجه إلى شاتراث!",
[123939466]="حسنًا. سأسمح بذلك. قاتل بشرف!",
[123954105]="أنا أجيب الألم!",
[124035270]="سيدتي.",
[124115729]="ثبّت يدك، أيها الأحمق! تلك مكونات نادرة تسكبها على الأرض!",
[124271954]="%s يخفض صوته إلى همس.",
[124383251]="%s يصوب نحو الزجاجات مرة أخرى...",
[124808512]="لقد انتهيت!",
[124879832]="قواي تجددت!",
[125346799]="ما... لم يعد لدي وقت. لقد انتهيت. اقضِ عليّ، $N. افعلها وإلا سيقتلوننا كلينا. $N... تذكر قرية سينجين، مون! هذا العالم يستحق الإنقاذ.",
[125417711]="اترك هذا المكان الملعون فورًا!",
[125453778]="دع الجحيم يلتهمك!",
[125585485]="احموا الأبرياء!",
[126146698]="الخلود يمكن أن يكون لك، لكن فقط إذا التزمت كليًا بـ يوق سارون!",
[126148525]="%s يزأر اعترافًا بـ تيرينثيس.",
[126466505]="واو، ظننت أنني هالك! شكرًا يا صديق!",
[126510344]="أصدقاؤك سيلحقون بك قريبًا!",
[126847476]="ستحترقون جميعًا في النيران!",
[127139914]="لماذا حدث هذا؟ لماذا أتيتم إلى هنا؟",
[127215009]="تخلصت منك.",
[127407045]="رحلة سريعة إلى العالم السفلي لك، وضحكة لي. تبدو صفقة عادلة!",
[127445966]="الـسكورج يركضون بحرية في الشوارع!",
[127690814]="كفى!",
[128015321]="غوثيك، الحاصد. سيد النكرومانسي والاستحضار، يُقال أن غوثيك قادر على استدعاء جحافل من الأنديد في لحظة. بتوجيهه، حتى أضعف الـديث نايتز يمكنه إحياء الموتى.",
[128895586]="حياتي لك، أيها العظيم...",
[128904214]="حان وقت الموت، أيها الأحمق!",
[129594976]="الألم بدأ للتو...",
[130105467]="لن تحقق شيئًا!",
[130139222]="لا يمكنك إيقاف المد!",
[130554577]="لقد نجحت! مذهل! أعتقد أنني لم أفقد لمستي...",
[130701125]="دوارف من الحديد الأسود!",
[130955229]="ناكسماراس رحل؟ من يهتم! أكيروس هنا الآن والديث نايتس يقتلون الجميع!",
[131198494]="سأمزق قلبك الذابل بيدي قبل أن يصيب $N أي أذى، أيها النيكرومانسر.",
[132588060]="آو! هذا ليس صحيحًا!",
[132637059]="العجلة... تدور... مجددًا.",
[132648943]="بسرعة، أحضر لي بعضًا من...",
[132988197]="كن حذرًا من المتسللين.",
[133512770]="افعلها، أيها الجبان!",
[133721088]="أورقريمار تشامبيون يضحك.",
[134325680]="من يجرؤ على إزعاج سيدنا؟",
[134414968]="لقد أجبروني على هذا....",
[134522181]="أنا لا أشعر بتحسن.",
[134711386]="لقد سمعت كفاية من تذمرك. اسكت فمك قبل أن أغلقه لك!",
[135015612]="ير نلييث... شول أناغ!",
[135211578]="هاه! ربما تعلمت شيئًا بعد كل شيء!",
[135620709]="أنا أشعر بالأسف تجاهك، أيها الفورسيكن. روحك خالية من النور.",
[135808492]="اقضِ عليهم ثم سنتحرك جنوبًا لقتل إخوانهم!",
[135900029]="أين \"قارونا: دراسة في التخفي والخيانة!\" يجب إعادة هذه النصوص!",
[136344665]="لكن بدلاً من القتال كما يفعل شعبي، كما ينبغي لشعبي، أجد نفسي بعمود طويل غير عملي، أحاول إقناع ذئبي بالهجوم على خصمي دون أن يهاجمه.",
[136501769]="تريده؟ حسنًا، خذه!",
[136903773]="واحد إضافي للعشاء هذا المساء.",
[137468086]="الأعماق ستبتلعك!",
[137534935]="ماذا؟ أين في الـ... لا تقفوا فقط يا رفاق؛ اقتلوا أحدًا!",
[137721175]="سأكون سعيدًا عندما ينتهي الاختبار النهائي لهذه الوحدة.",
[137762236]="لم آتِ لهذا الحد لأُوقف! المستقبل الذي خططت له لن يُعرض للخطر! الآن ستذوقون القوة الحقيقية!!",
[137883170]="أحتاج وقتًا للتفكير... سأساعد قضيتك إذا احتجت ذلك. أنا مدين لك بهذا على الأقل. وداعًا.",
[137968560]="للأسف لا، يا صديقي. إليك سيفك ودرعك. تقدّم للثكنات للخدمة.",
[138175010]="التالي، سأتحدث عن أقوى الكيانات في قمة ناكسماراس. حقًا، هذان اثنان من أعظم التهديدات لكل نورثريند.",
[138408758]="احترق في نيران غضبي!",
[139342783]="سأريك: هذا الكلب المهزوم لا يزال لديه أسنان!",
[139557980]="نار! آآآآآه!",
[139624783]="حر!!! قريبًا ستشعر بغضب ملك العاصفة!",
[139816864]="لا تدع المستويات تنخفض كثيرًا.",
[140394238]="أوه! ماذا يفعل هذا الوغد بإرسال حشراته إلي؟ ابتعد عن نظري قبل أن آخذ ما تبقى من حياتك. وخذ هذا معك.",
[140589384]="حسنًا، الآن. يا له من تطور لطيف للأحداث.",
[141123272]="أعتقد أنني فهمتها هذه المرة...",
[142189523]="حان الوقت لنا كممالك وكأفراد أن نضع خلافاتنا الطويلة جانبًا ونتحد. أمواج حرب لا يمكن كسبها تقترب منا، ويجب أن نبحث عن ملاذ في أرض مرتفعة، لئلا تجرفنا فيضان الظلام.",
[142756304]="مولفيريك!",
[143341255]="بالنور! هذا الجاسوس الملعون كان ماهرًا! أنا سعيد بموته.",
[143887043]="انهض وادافع عن سيدك!",
[144006671]="كيف قتلت جو المسكين العاجز؟ ولماذا أعدت اللحم؟",
[144468033]="لا أريد المغادرة! أريد البقاء هنا!",
[145076438]="%s يسكب الماء الملوث على القطة.",
[145148725]="%s يطير إلى المنصة بالأسفل! الأفضل أن تقفز إذا أردت اللحاق به. أسرع!",
[145201601]="لا شيء أقل من الكمال سيفي بالغرض.",
[145316334]="تتعزز الخزائن الشخصية للأمل والإيمان، وتزداد قدرة المرء على النور الأعظم.",
[145353824]="جودفري! اسمعني أيها الشرير! اسمعني، فأنا النور، جئت لأنقذك من الشر!",
[145474861]="الحمد للنور على رؤيتك هنا بأمان! لدينا الكثير من العمل لنفعله إذا أردنا هزيمة الـليتش كينغ والقضاء على الـسكورج.",
[145718776]="%s يبدأ بإلقاء السم نوفا!",
[145909607]="هذا راية الكلب وهذه جثته. ما هذا؟ لقد هجم علينا!",
[146377124]="منذ زمن بعيد، كنت رفيقًا لشعبي. أسلمنا أنفسنا للشر وتم نسيانك.",
[146712185]="لقد أزعجت راحتي، $C. الآن واجه غضبي!",
[147845532]="أطعمك للسيد!",
[147994027]="خطأ، بالارغارد. أنت ستقبل هذا التحدي!",
[148045077]="%s يعوي بسرور عند رؤية غدائه!",
[148195119]="تخلصنا منه... الآن لن يستطيع أحد تكرار أخطائي!",
[148796222]="في الموت نحن إخوة.",
[149006582]="الـدَن بَلدَر ساوث بنكر تم الاستيلاء عليه من قبل الأليانس!",
[149012062]="انهضوا من الأرض، يا إخوتي!",
[149621425]="شعلة حياتك... انطفأت.",
[150281774]="النقابة لن يعيقها الحشرات.",
[150589067]="كن مستعدًا، $N. أسمع المجلس يعود. استعد للكمين!",
[150636056]="لقد عبرت حافة النسيان!",
[150755374]="إذا لم تغادر الترآك فالي بمفردك، فـالـفروستوولفز سيجبرونك على الخروج!",
[150885760]="فورًا، يا سيدتي!",
[151364213]="أصحاب النزل مجانين ليعطوا الحلوى مجانًا.",
[151469961]="مت، أيها المتعدي!",
[151687694]="مزيد من القطع الأثرية للمصادرة.",
[152479347]="حسنًا، أيها المجندون، أدّوا التحية العسكرية!",
[152657815]="الخلاص الوحيد للخونة المسؤولين عن هذا سيكون موتًا مؤلمًا. انتقامي سيكون سريعًا وبدون رحمة.",
[152903611]="دماء وأرواح لـهاكار! هاهاها!",
[152965669]="تعالوا، يا سكان الظلام! التجئوا لندائي!",
[153114637]="الحمد للنور أن بيرثا ليست هنا...",
[153715390]="البوابة قد اخترقت! بسرعة، وجهوا القوات للتعامل مع هؤلاء الغزاة!",
[153845324]="أنا لا أخاف من أي شيء — هيا!",
[153885966]="الأمور تزداد سوءًا.",
[154052074]="مخبأ دون بالدار الشمالي يتعرض لهجوم! إذا تُرك دون رد، سيدمره الـهورد!",
[154086216]="مقبرة آيس بلود تتعرض لهجوم! إذا تُركت دون رقابة، سيستولي عليها الأليانس!",
[154200116]="من يزعج نومي؟ تلك الرمح... ما زلت أحمل الندبة!",
[154374962]="بيلور...",
[154399139]="%s يطلق النار من الحزام على الزجاجات...",
[155109323]="لقد تحركت! أقسم، رأيتها تتحرك!",
[155204655]="ليس لدي خيار سوى الطاعة!",
[155554585]="نفس أفكاري بالضبط.",
[156159273]="السماء تتحول إلى الأحمر بدماء الساقطين! الـليتش كينغ تراقبنا، أيها الأتباع! اتركوا فقط رمادًا وبؤسًا في أعقابكم المدمرة!",
[156454957]="الحفاظ على هذا الحاجز سيتطلب كل تركيزي. اقتلوهم جميعًا!",
[156669142]="أنا سعيد أن الاضطرابات هدأت بعض الشيء هنا. آخر ما تحتاجه هذه المنطقة هو شجار آخر.",
[156733180]="سلاحي عطشان!",
[156744893]="إذا كانت قسمتي صحيحة... يجب أن تكون ميتًا تمامًا.",
[156986477]="وقتي انتهى... لقد قدمت نفسي لـألكسترازا في الحياة، لكن لم يعد لدي ما أقدمه في الموت. ستحتاج إلى حارس جديد لمقامها.",
[156987455]="أتجرؤ؟! أين بارون سليفر؟ أريد التحدث معه!",
[157199430]="لم آتِ إلى هنا لأشاهد حيوانات تمزق بعضها بلا وعي، تيريون.",
[157470079]="العمل بهذه المبادئ، هذه الفضائل، يساعد في جعل العالم مكانًا نقدره جميعًا. عالم من الشرف والعدالة.",
[157613237]="أستطيع إصلاح ذلك... أو ربما لا! يا إلهي، يا لها من فوضى...",
[158311377]="نازان ينزل من السماء.",
[158455923]="%s يتجمد!",
[158864027]="احترسوا من ظهوركم: لقد حاصرونا في هذه القاعة.",
[159581931]="رقم ٥٤! مستحيل أسمح لك تغلبني!",
[160576104]="لا شيء.",
[160906116]="أعمل كل ما بوسعي!",
[161093324]="%s يحدق بك للحظة، ويجد صعوبة واضحة في تصديق أنك حقيقي.",
[162056007]="لنتحرك من هنا بأسرع ما يمكن. إن لم يقتلنا الأنديد، فقد تقتلنا النيران.",
[162781663]="أقل من اللازم، متأخر جدًا. السد انكسر. نحن مجرد عثرة في الطريق في أحسن الأحوال.",
[162909172]="سحرك المظلم من الـسكورج لن يحميك من النور!",
[163038175]="أوه! عدت لنفسي الجميلة؟ كم هذا رائع! ظننت أنني سأبقى ضفدعة للأبد.",
[163339757]="استمتعوا بهذا النصر الصغير، أيها المخلوقات الصغيرة الحمقاء. لقد ربحتم أنتم وحلفاؤكم التنانين هذه المعركة، لكننا سنربح... حرب النيكسس.",
[163417412]="تقع كليف سبرينغ فولز على طول الجبال شرقًا وشمالًا.",
[163507328]="اصبها بين العينين! تلك الوحوش ضعيفة هناك!",
[163696530]="أقسم أن هذا صحيح! أرجوك، لا تقتلني!!",
[163794466]="لا أستطيع الحفاظ على هذا الحاجز لفترة أطول... أين ذلك الجبان؟",
[163844011]="سأمزق روحك إلى قطع وأشويها ببطء على نار شيطانية!",
[163869280]="إذا تحدثنا كواحد، لا يمكن تجاهلنا!",
[164170906]="أرجوك قل لي أنك لم تفعل ما أعتقد أنك فعلته. أرجوك قل لي أنني لن أضطر لإيذائك...",
[164387116]="انتشار البلاك روك كثيف في هذه المناطق. سأبذل قصارى جهدي لمواكبة السرعة. هيا بنا!",
[164725946]="لم نحقق حصتنا بعد من الطلب على الخشب. والآن عد إلى العمل.",
[164831672]="ريمولوس، يا صديقي القديم. من الجيد رؤيتك مرة أخرى. كنت أعلم أن الرسالة ستصل إليك - بطريقة أو بأخرى.",
[165291024]="هذا ما يسمى كسب العشاء!",
[165465029]="ارحم حياتي! سأغادر هذا المكان للأبد! أرجوك!",
[165545593]="لكنك لن تكون وحيدًا هناك. أنا ورجالي جهزنا بغالًا تحمل الإمدادات التي ستحتاجها أكثر.",
[165699671]="أيها الغزاة، توقفوا عن هذه المغامرة الحمقاء فورًا! انصرفوا بينما لا تزالون قادرين!",
[165741113]="لا... لا... شعبنا... ويرمسكل... بعضهم نجا...",
[166016231]="لا أستطيع. لست الرجل الذي يظنونه في المنزل. بالإضافة إلى ذلك، لم أحضرهم إلى هنا.",
[166113741]="لم يعد يؤلم بعد الآن، أليس كذلك؟",
[166351038]="إيليدان أحمق متكبر! سأسحقه وأستعيد أوتلاند كملكي!",
[166397802]="ماذا؟ هذا ليس ناكسماراس! نحن لا نحب هذا المكان... دمر!",
[166631504]="الآن بعد أن أُعدت تجميعي، يمكننا العودة إلى زمن الكمال... زمن التايتنز!",
[166661285]="%s يصفر بصوت عالٍ ويستعد للهجوم.",
[166766463]="اشرب باعتدال يا صديقي الدوارف، لكن قد ترغب في تسليم رمحك ولجامك في الوقت الحالي. امضِ مع النور.",
[167621526]="ترولباين وحده لا يستطيع صد قوة هورد الأوركس مجتمعة. لقد انتهينا...",
[167808523]="أتلاعب اليوم، كما أرى... حسنًا، ربما أجدك بمزاج أفضل لاحقًا.",
[168139018]="قواتنا، أيها الجنرال، تتكون في الغالب من قرويين وفلاحين. رجال طيبون، لكنهم لم يتخلصوا بعد من تحيزات وخرافات نشأتهم. إنهم ليسوا مستعدين للقتال إلى جانب حلفائنا الأكثر غرابة.",
[168142493]="أقل ما يمكنك فعله هو المقاومة!",
[168508010]="مرحبًا، كوكي! ماذا سنأكل على العشاء الليلة؟ ولا تقل دجاج!",
[168558494]="دع هذه التضحية تكون شهادة على ولائي.",
[169402273]="ربما ننضم إلى الرقص لاحقًا.",
[169891359]="%s يتلاشى في الضباب...",
[170158078]="هاهاها! نحن قادمون إليكم أيها الجوبلنز الصغار!",
[170257430]="أوه، أستطيع رؤية ليلادريس من هنا... أخبرها أنني هنا، حسنًا؟",
[170651238]="هل تحتاج إلى تلميع حذاء، $C؟",
[171199738]="سعيد بالخروج من ذلك الخندق البائس. لكن ليس أفضل كثيرًا هنا بالأعلى!",
[171675793]="من يجرؤ على الاقتراب من هذه المرجل؟ ذق نصلتي المظلمة!",
[171807717]="إخوتي وأخواتي. اسمعوني. يجب أن نتحدث عن بقاء شعبنا. لقد نجونا بالكاد من كارثة واحدة، لكنني أخشى أن الكارثة القادمة ستدمرنا.",
[172005293]="%s يفتح فمه واسعًا!",
[172035581]="لا تدفع الأمر أيها المواطن!",
[172189076]="سيعيشون، ولو فقط ليروا ثمار عملهم: الدمار والفوضى التي ستنشأ حتمًا عندما يغزو ليجيون بلاكروك الوادي.",
[172451539]="لقد تأخرت جدًا في إيقاف خطتنا.",
