[240867615]="سيدي، بالتأكيد لا تتوقع مني أن أتركك دون مراقبة. سيقوم اللورد إيليدان بقطع رأسي إذا حدث لك أي شيء.",
[241393520]="لن تكون هذه نهاية السكارلت كروسيد! لن تكسر صفنا!",
[241561015]="مثير للإعجاب، أيها الديث نايت. عد إلي في عالم الأحياء لمكافأتك.",
[241729758]="كانت تلك قريبة! حسنًا، لننطلق، نحن على وشك الوصول.",
[241749863]="غير معروف. تشير البيانات إلى أن الدافع للصراع العالمي نشأ من الهدف الأساسي لوكين، الذي حيد جميع الآيسير والفانير المتبقين، مما أدى إلى إنهاء الصراع. ثم بدأ الهدف الأساسي لوكين في تجميد عدة أعراق بذور، بلا يوجد ذلك الإيرذن والعمالقة والفيريكول، في مرافق احتجاز مخصصة.",
[242628286]="المفتاح... احصل على المفتاح... جيرستان لديها... المفتاح.",
[243100933]="ماكسنا، وُلدت في أعماق جبال نورثريند منذ عصور، تم أسرها داخل القلعة المرعبة ناكسماراس، حيث تلد نسلها، وتطعمهم جثث كل من يجرؤ على المغامرة عميقًا في ناكسماراس.",
[243608732]="مهما قلتِ، أيتها الأميرة. لكنكِ فقط تؤجلين المحتوم...",
[243623574]="%s يعيد البلورة إلى داخل الصندوق.",
[244283876]="ومن خلال ذلك الأمل، نقوّي جانبنا في المعركة؟",
[244459675]="فيل أوركس!",
[244517397]="%s يطلق النار بسرعة على دمية الأورك...",
[244626417]="احصلوا عليهم وهم طازجون! أرغفة خبز هنا!",
[245176157]="أنا أعيش من أجل هذا!",
[245221418]="طهّروا قاعاتنا المقدسة بالنار!",
[245251252]="لا تقلقي، أختي... لا أحد يستطيع إيذاءك الآن.",
[245520860]="%s يشير إلى الرق على الأرض.",
[245964710]="اقرأ هذا الكتاب الذي وضعته أمامك، وقل الكلمات بصوت عالٍ.",
[245985000]="أمسكتك جيدًا!",
[246242994]="لا يمكنكم قتلي أيها الحمقى! سأعود، سأ...",
[246259290]="قضيتكم خاسرة!",
[246285136]="انجح، وستكون لك قوة أعظم!",
[247257587]="خياطة، يا سيدي.",
[247338583]="%s يقفز من الخوف!",
[247792267]="خصلة شعر أخرى من الـسكورج أكتسبها، وكرامة أخرى أفقدها...",
[247930974]="أنتم يا بحارة أقوى مما ظننت! سأضطر للارتجال!",
[248278247]="الموت للحارس الأخير!",
[248794341]="ما كان طعامي!",
[249272839]="%s يرمي جرثومة فطر على $N.",
[249379095]="شعامور آرا مشال؟",
[249548332]="تبحث عن هذه؟؟؟؟ لن تحصل عليها أبدًا!",
[250600521]="وكيرين تور؟ ماذا لديهم ليقولوه عن النكرومانسي؟",
[251212757]="أناثيرا... لا أستطيع تحمل مواجهة بقية الأبدية بدونك بجانبي... إذا أُخذت مني، فليكن هذا اليوم الذي أعود فيه إلى الأرض أيضًا...",
[251316377]="فشل آخر...",
[251572746]="دافع عن نفسك!",
[251914032]="هناك شيء ما بالخارج. أطلق طلقة تحذيرية!",
[252757190]="سترتاح مع الموتى المكرمين.",
[253399689]="لم تتم دعوتك!",
[253748197]="أنت كبير وقح! من الذي دفعك لهذا؟",
[253769597]="تم هزيمة مجموعة الوحوش البشعة!",
[254002425]="الموت قادم! افرحوا!",
[254135209]="أهاهاهاها... ستنضم إلينا قريبًا!",
[254836460]="يجب أن أرى السيد فورًا!",
[254987073]="سأمسحك من على حذائي لاحقًا!",
[255059285]="تجرؤ على لمسي؟! لن تمنعني من إثبات نفسي للـليتش كينغ!",
[255133157]="لصوص! أوغاد! أوشاق! تعالوا واجهوني أيتها الأعمدة العملاقة!",
[255190688]="%s يضحك بجنون وهو يخلط المزيجين في يديه.",
[255886822]="لقد التهم النور!",
[256078362]="%s يطلق النار بسرعة على الهدف الأوسط في المركز تمامًا...",
[256283899]="همم، زوار غير معلنين. يجب أن تُتخذ الاستعدادات...",
[256502397]="هذا يكفي. لا تعرف أبدًا ما قد يحتاجه بعد ذلك...",
[256570404]="سأخرج من هنا!",
[256830507]="لقد انقلبوا ضدك. الآن... خذ انتقامك.",
[257279525]="الآن اسبح عائدًا بالمعرفة التي منحتها لك. افعل لا تستطيع من أجلهم، $R.",
[257282521]="لنذهب.",
[257332100]="حتى هذا اليوم، أتساءل لماذا تم اختياري أنا بالذات لهذه المهمة. أستطيع فقط أن أتخيل أن رئيسي شعر أنني مناسب بشكل فريد للمهمة وسأعتاد بسرعة على الثقافة البسيطة للـهورد الموجودة هنا، لكنني سمعت إشاعة خبيثة حقًا أنها قد تكون لأنني أتحدث كثيرًا.",
[258389718]="ليس مرة أخرى! ليس مرة أخرى...",
[259147575]="قواي في قراءة الطالع لا تُقاس - فرصك لكن: لا فرصة",
[259585733]="شكرًا لك، $R! خدمتك للماغهار لن تُنسى.",
[259666597]="حاجبي! لقد أحرقت حاجبي!",
[259819894]="غولدان. ليس اسمًا سمعه كثيرون في أزيروث.$B$Bللأسف، ليست الإجابة الصحيحة.",
[260688258]="اثنتا عشرة خطوة هذا أقرب!",
[261050564]="النار تقتلك بنفس السرعة!",
[261807025]="هذا ليس شيئًا كان ليمبي جو ليسأله! لكن أجل، أعرف لوكين.",
[261988591]="أنا لا أستحق، $Gسيدي:سيدتي;.",
[262060677]="لن تعيق هروبنا، أيها الشرير! أبقِ الأنديد عني بينما أُسقط هذا الحاجز.",
[262205673]="أيها الفاني المتهور!",
[262490627]="يا للصدفة... كنا نتحدث عنك للتو، $N!",
[262551251]="لا يحق لـ$R تافه مثلك، $N، أن يمشي في هذه الأراضي!",
[262579991]="يا إلهي، تلك الجعة السوداء كلو قوية جدًا!",
[263569343]="نيران تغطية، الآن!",
[263691131]="يا نور! لا تخذلني!",
[264091079]="كانت تلك مجرد البداية.",
[264806196]="اجلب لحمًا جيدًا وسيعاملك المخيم كشامان أعلى ليوم واحد. صفقة جيدة.",
[265720424]="ما زلت جائعًا. ما زلت... أنا... عطشان.",
[265945536]="أشكرك، أكاماً. لقد شرفتني بالسماح لي بهذه اللحظة، موضعًا بإخوتي. وداعًا يا صديق. أرشد شعبنا جيدًا.",
[266275027]="لقد تم الأمر!",
[266278876]="ما كان غلطي يا ماستر مازن!",
[266359521]="الآن سوف نرفع المستوى بالخلطة السرية... الخلطة... الخلطة السرية!",
[266946780]="وما كنا لنرى تلك الأخطاء تتكرر. ارجع إلى منفاك.",
[267062817]="انتظرت وقتًا طويلًا لهذا، ثرال. في كل مرة أُلقيت فيها في إحدى حلباتك الملعونة... وفي كل مرة قتلت فيها شاذًا أخضر البشرة مثلك... لم أستطع التفكير إلا في شيء واحد.",
[267261450]="%s يقفز في بئر القمر ويغوص تحت الماء...",
[267316792]="هذا هو بطلك؟",
[267330773]="أنا مستيقظ، أخيرًا!",
[267354630]="انتهى وقت المرح!",
[267492807]="وهكذا كنا - أنا والكتيبة، نقوم باستطلاع روتيني على طريق العظام. أرسلنا الكشاف للأمام ليتفقد المنطقة في حال ظهر أي خطر.",
[267562834]="والدك كان ضعيفًا، ساشا... ما كانت عنده الجرأة ليفعل ما يجب فعله.",
[267706066]="لقد نهضت!",
[267980723]="هل يمكن أن يكون حقيقياً؟ حر بعد كل هذه السنين؟",
[268026792]="توسل من أجل الحياة.",
[268365884]="ممم... عيناي ليست ثقيلة الآن يا أبي. هل يمكننا الخروج واللعب؟",
[268702051]="أرواح ستونيتالون لا تزال غاضبة، $N.",
[268712910]="عالمك قد انتهى.",
[268772570]="هذا أصعب قليلاً من قبل... أوه، اللعنة—قادم!",
[269332430]="%s مسلح الآن!",
[270365750]="آشبرينغر يعصيني...",
[270825908]="ما هذا!؟ هذه ليست شجرة على الإطلاق! حراس! حراس!",
[271290003]="إنه لشرف أن أخدم إلى جانبك، $Gسيدي:سيدتي;.",
[271396658]="واحتفظ بالباقي، أيها الحيوان القذر!",
[271516582]="كائنات دنيا، تتطفلون هنا! من العار أن شجاعتكم الزائدة لا تعوض عن غبائكم!",
[272025158]="سيتم تطهيرك!",
[272092689]="ما كان ذلك الصوت؟ بدا وكأنه زئير.",
[272297975]="أنت هناك! نعم، أنت أيها الفلاح $Gولد:بنت;. تعال بسرعة، يجب أن أخبرك بشيء... يجب أن أخبرك عن عظمتي، لئلا تضيع هذه الأمور في الفراغ!",
[272616237]="يبدو أنك ستضطر للمضي قدمًا إلى راتشيت وإخبار سباتر فالف أنني حطمت الممزقة.",
[272682949]="سأمزق روحك إلى قطع صغيرة وأشويها ببطء على نار شيطانية.",
[272738547]="دع غضب العاصفة يلتهمك!",
[272761799]="إعادة أصل الكوكب؟ تكلم بوضوح، أيتها الآلة الملعونة!",
[273250980]="%s تناثر عليه الدم وأصبح مشعًا!",
[273701008]="عندك شيء تقوله في وجهي؟",
[273862339]="الموت لك، $N. كيف تجرؤ على الاقتراب مني على مسافة قوس!",
[274296875]="اهدأوا أيها الفانون، وأصغوا لكلماتي.",
[274755834]="ستكون وجبة شهية للصغار.",
[274800192]="قابلني عند البستان—فقط أريد أن أضع بندقيتي.",
[275518873]="اعمل بجدية أكبر!",
[275968902]="كانت معركة جيدة. أستسلم لك.",
[276022113]="هل تشعر به أيها الفاني؟ الموت يتسرب مني، يغلف كل ما ألمسه. بمجرد طرفة إصبع ستعاني روحك في الجحيم إلى الأبد.",
[276164189]="حياتك ستكون ملكي!",
[276354656]="حمقى غير أكفاء! كان يجب أن تكون أوشندون لنا... انظروا إلى أنفسكم تتخبطون كالفئران!",
[276719977]="تريد الذهاب لتنفيذ المكافأة من هذا الملصق بعد انتهاء المناوبة؟",
[277505786]="أيها الصغير!",
[277537225]="مرحبًا، هارولد. لدي جلودك!",
[278601961]="أوه، ليست أفعى!",
[278674297]="سأسرع بالعودة إلى فالارييل. أنهِ من تستطيع—يجب أن أكون بخير وحدي من هنا.",
[278874839]="توقف! قف!",
[279162926]="سنحرر العناصر من قبضتك بالقوة!",
[279937027]="ننتظر دفعة من بيض التنين الأسود من بيرنينق ستبس. نعتقد أنه من خلال دراستها، سنطور معرفتنا بشكل كبير.",
[280154059]="زيمبو يجب أن يعيش ليقتل خائننا!",
[280398345]="اصرخ وأنت تحترق!",
[280621851]="لقد انتهيت!",
[280668670]="انفجارات! المزيد من الانفجارات! لا بد أن أحصل على المزيد من الانفجارات!",
[280880611]="آه، للتو حصلت على رقم 48. هذا بدأ يصبح صعبًا.",
[281143517]="لا! لن تهزمني!",
[281682228]="قل مرحباً لصديقي الصغير!",
[282036898]="ربما لم تلاحظ، لكن الدجاجة تتحرك بسرعة نوعًا ما.",
[282120120]="صانع السفن، يا سيدي.",
[282200043]="أنت تتدرب وكأنك لا تزال نائماً.",
[283131502]="أتساءل. لقد أرشدنا هامول جيداً، وتعلمت منه الكثير. تقول الأساطير أن شعبنا كانوا درويدز منذ بداية الزمن...",
[283442815]="مذهل. أيها الأطفال، عندما نعود إلى المدرسة، سيقدم كل منكم تقريرًا شفهيًا عن واحد من هؤلاء الأشخاص الأسطوريين.",
[284369848]="نحن نتوق للانتقام.",
[284474051]="النهاية قادمة إليك!",
[285120947]="كانت أفضل خدعة على الإطلاق! حسنًا، يا رفاق، لنذهب ونحتسي شرابًا.",
[285293323]="لقد استخدمت حكمًا سليمًا عندما لم تُظهر أنت أيًا منه. لا أريد أن أراك تقودنا إلى الخراب، كرينا!",
[285891161]="يا فرسان التنانين، امتطوا ظهور تنانينكم!",
[285921042]="لقد فعلناها! قابلني عند جيركاي فوق معسكر غريم توتيم.",
[286708888]="أشعر أن الحرب تقترب بسرعة. لقد استعان بائع الفاكهة بأوغر. سأضطر إلى طلب المساعدة أيضًا.",
[286958551]="الموت... لن يوقفني.",
[287102301]="مصيرك محتوم. نهاية الأيام حلت أخيرًا بك وبكل من يسكن هذه الشتيلة البائسة. أولوي إفيس هالاهس غاغ إرهونغ واش.",
[287438073]="غبي! غبي جدًا!",
[287864028]="البوابات اخترقت! دافعوا عن القلعة!",
[288123269]="لورد سالثيريل، عزيزي، هل لاحظت أن مؤن الحفلة قليلة؟ يجب أن نرسل أحد سعاة فيربريز فيليج لجلب المزيد. أحب بشكل خاص تلك المقبلات الملفوفة بالسيكون المدخن. ماذا تسمى؟",
[288373299]="ها! هذا المكان لا يستحق بعد معاناتي!",
[288398600]="ليس ما خططت له.",
[288432509]="$N اجتاز الممر! ثلاث هتافات لـ $N!",
[288722457]="شكرًا لك، $N. ليباركك النور، $Gأخي:أختي;، ويهدي طريقك.",
[288762814]="لا تدع واحدًا منهم يبقى على قيد الحياة.",
[290521695]="يبدو أنها ضلوع خنزير طرية مغطاة بعصائرها اللذيذة وجانب من صلصة الكابتن ساندر السرية - للتغميس.",
[290647862]="لقد وجدت طريقك إلى هنا، لأنك من القلائل الموهوبين برؤية حقيقية في عالم ملعون بالعمى.",
[290827346]="آرغ! سأمزق روحك وأطحنها حتى تصبح غبارًا!",
[290983366]="أنا... الغضب... غير المقيد!",
[291310761]="ارحل أيها الفاني. أنت لست أهلاً لمعرفتي.",
[291626903]="أنا متعب. أنت اقتل الذي يليه!",
[291652499]="أن حياتنا... حياتنا تستحق أن نعيشها.",
[292014695]="ماذا يفترض بهاكمود أن يفعل الآن يا صاح؟",
[292218196]="أتساءل إن كانت لعبتك تستطيع السباحة!",
[292489098]="لنفعلها... فقط غطني وسأوصل الطرد.",
[292704117]="الأرض بدأت تتشقق!",
[293427792]="لا، جاينا! آرررررغ... هو... هو قادم. أنت... أنت يجب...",
[293513816]="تيدون، جرب العامل المعادل على المخلوق المتحور.",
[293644965]="قاتل العجول! قاتل! ستدفع ثمن هذا!",
[293683715]="أوه أوه...",
[294164158]="كل حقائبي محزومة، أنا مستعد للذهاب.",
[294302402]="من فضلك، اتبعني.",
[294327250]="الـسولفلاير قادم!",
[294555399]="الفروستبورن كانوا طيبين معي جدًا. إنهم شعب قوي.",
[295099761]="بمجرد أن يفعل ذلك، أخبره أن يغادر هذه الأرض بسلام. إنه لا ينتمي هنا.",
[295362127]="بغض النظر عن أي شيء، لا يمكنك الموت، لأن ذلك يعني أنني سأتوقف عن الوجود، صحيح؟ لكن، كنت هنا من قبل عندما كنت أنت. أنا في حيرة من أمري!",
[295552341]="إذن هذا ما جئت من أجله؟ لتحاول المطالبة بذلك الذي هو سبب وجود الفجر وسقوط الحملة الصليبية؟ أنت تفتح جروحًا قديمة بكلماتك، أيها القائد!",
[295624269]="وا... ماذا يحدث؟",
[295808337]="هانترز، إليّ! لنُري هؤلاء الشياطين معنى القتال والموت في أزيروث!",
[295971283]="هذه إجابة خاطئة، $N. اذهب عني.",
[296017681]="الآن سأكبر وأسحقك!",
[296124307]="جنود، انتظموا! يبدو أن الـهورد قادمون لمحاولة أخرى!",
[296255319]="هل صحيح أن البالادنز يتدربون هنا؟",
[296458238]="هل يمكن ذلك، لورد فوردرينغ؟ إذا كان بولفار حيًا، فلربما هناك أمل للسلام بين الأليانس والـهورد. يجب أن نصل إلى قمة هذا المكان الملعون ونحرر البالادن!",
[297115066]="قد تريد الابتعاد. تنظيف فيش عمل قذر.",
[297129253]="مرحبًا، $N، لا تنزعج. إنه أنا... أنت... من المستقبل. أنا هنا للمساعدة.",
