[299465577]="ها أنا ذااااااااا!",
[300740600]="حاول أن تكون مفيدًا يا $R. أَخْرِجْنِي مِنْ هُنَا! المحقق الأعلى لديه المفتاح.",
[301901072]="بكل سرور...",
[302660339]="لا تجرؤ...",
[303199746]="لقد تعرضت ورشة حصار ويستسبارك لهجوم من الـهورد!",
