[304302818]="هل أحد يعرف شيئًا عن ثيلزان؟ من هو؟ كيف أصبح قائدًا لجيوش الـسكورج على الأرض؟",
[304431121]="رجلي تؤلمني...",
[304580887]="يمكنك الرؤية عبر الضباب الذي يغطي هذا العالم مثل الكفن، وتدرك أين تكمن القوة الحقيقية.",
