[304828439]="سيدي، إنهم قادمون...",
[304989012]="آآآآآآه!",
[305727129]="لا أريد حتى التفكير في ما سيحدث هنا إذا قرر $N ألا يعود يومًا.",
[305735752]="قادمون!",
[305893922]="اقتلوهم! لا يجب أن يتوقف عملي!",
[306075946]="عمل رائع!",
[306189846]="كفى تمهيد. لنبدأ بالعمل.",
[307102431]="%s يصنع سمه...",
[308012193]="جاهز!",
[308580440]="ابقَ كما تشاء، $N. قلوري في ثمار عملك!",
[308851995]="آسف، ساندرز. لم أرَ مثل هذه الوفرة من قبل. فاجأتني.",
[308978076]="سيدتنا ستكون... نهايتك.",
[309708180]="شكرًا! لا تنسوا إكرام النُدُل! تصبحون على خير يا رفاق.",
[309864966]="لكن شيئًا واحدًا مؤكد: حجم هذه الصفيحة وسماكتها وثقوب المسامير تشير إلى استخدامها كدرع لهيكل ضخم.",
[310183748]="يا للقفز من النومز المجذومين! لقد علقت هناك لأشهر. شكرًا، يا جماعة.",
[310507203]="لا تدع هذا التمثال يكون رفيقي الوحيد. اخرج والعب!",
[310571075]="تنين الأسود سيقهر الجميع!",
[311120492]="أنا متمكن من أكثر من 4 لغات.",
[311132163]="$R لحم... يجب أن يتغذى!",
[311480488]="انتبهوا، $N، أحد أفضلنا، هنا!",
[311498551]="واو، جميل ومخيف!",
[311622469]="لقد ارتكبت خطأً قاتلاً، أيها الفاني... لا مفر...",
[312041043]="حان وقت نصيحة داجيك الذكية! تأكد أن الشيء ميت قبل أن تمد يدك في فمه للغنايم.",
[312048398]="بحب النور، أخرجوني من هنا!",
[312575006]="يوثر استدعى قواتي؟ اللعنة! إذا تخلى عني محاربي، لن أهزم مالقانيس أبدًا. يجب حرق السفن قبل أن يصل الرجال إلى الشاطئ!",
[312686950]="هو الذي يأمر أبناء الحديد في حربهم ضدنا.",
[312763928]="انظر... إلى الفراغ.",
[312835383]="النور يشتعل فيك بقوة يا ديفيل. سأستمتع بإطفائه!",
[313238961]="الألم انتهى أخيرًا.",
[314113767]="آسف، لكن كرومي قالت إنني لا أستطيع إخبارك بأي شيء عن مستقبلك. قالت إنني لو فعلت، لاختفيت.",
[314903591]="لن أرحل!",
[315439017]="اخدم توبتك!",
[315834633]="%s يبدأ في توجيه الطاقة الأركانية...",
[315916283]="الـليتش كينغ يجب أن يجيب على ما فعله، ولا يجب السماح له بالتسبب في مزيد من الدمار في عالمنا.",
[316535735]="تم الهجوم على ورشة حصار المعبد المكسور من قبل الـهورد!",
[316666134]="حصلت على واحدة!",
[316685023]="الماء يمكنه أن يأخذ أي شكل، أي هيئة... ويتغلب على أي عقبة.",
