[317477144]="أتمنى أن تتاح لي فرصة زيارة غريت فاذر وينتر قبل انتهاء وينتر فيل.",
[317701714]="تتجاسر وتتدخل في مساعي السيد؟ ستدفع الثمن أيها الفاني الأحمق!",
[318246430]="أعتقد أني سأستريح لحظة لألتقط أنفاسي قبل العودة إلى راتشت. شكرًا على كل المساعدة!",
[318552392]="مقبرة آيس بلود تتعرض لهجوم! إذا تُركت دون رقابة، سيستولي عليها الـهورد!",
[319188731]="موتي لا يهم كثيرًا... المطرقة ستسقط على أي حال!",
[319543024]="السعادة إجبارية أيها المواطن.",
[319587568]="هذا لن يأخذ وقتًا طويلًا...",
[319879102]="كيك، معجنات، حتى خبز - أي شيء إلا الجبن!",
[320298673]="نرحب بفرصة القتال إلى جانبك، أيها ثوريم العظيم.",
[320521210]="كل شيء واضح على تلة سينتينل، أيها اللورد ستاوت مانتل. لكن تم الإبلاغ عن تحركات كثيفة للـديفياس في مونبروك.",
[320835852]="برج القلعة الجنوبي الغربي قد دُمّر!",
