[321411575]="جهودكم... تذهب سدى.",
[321579746]="لم أنتهِ بعد.",
[321710303]="دخلاء! ستحل عليكم المطرقة.",
[321860602]="أرجوك، ساعدني لأعبر هذه الغابة الملعونة، أيها $R.",
[322469797]="تذكر هذا اليوم، $N، لأنه اليوم الذي ستنهزم فيه تمامًا.",
[322588642]="توقف!! توقف!!! الخردة تتحرك بنفسها الآن؟",
[322603416]="بإعجاب؟ هاه! سأستمتع بمشاهدة أبطالك الضعفاء الصغار يفشلون، أيها الهيومن.",
