[322899408]="أعود من القبر لأؤدي أمر سيدي.",
[323132902]="[فوربولق] تعال، $N. دعنا نغادر الماء معًا، مطهرين.",
[323355649]="هل كان بإمكانهم النجاة؟",
[324823412]="نريد مساعدتك أيها الروح. نطلب حكمتك.",
[325331666]="ها أنت ذا...",
[325601149]="سأستمتع كثيرًا بإنهاء حياة هذا البائس! لم يفت الأوان بعد، لا داعي لأن تعاني عبثًا. تراجع وموتها سيكون رحيمًا!",
[325750681]="شوفهم كيف يطيرون!",
[326905085]="حان الوقت، فراي! اهجم!",
[326917288]="أخ.",
[327147112]="الـلوفلي ميرشنت ينتظر ذلك. أسرع!",
[327265630]="الأفضل ما أطلع حذاء ريجي ثاني...",
[327591582]="للأسف لا، $N. الآن، اشعر بالعار الذي جلبته على نفسك.",
[327655363]="اعتني بنفسك! أنا بطّلع من هنا.",
[327726982]="أنا خايف! أنا هرب الآن!",
[328556258]="كنت دائمًا صانع المشاكل في العائلة، نوغل. دائمًا!",
[328578003]="لحم من عظم!",
[329475942]="أنا أعتبر ذلك بداية جيدة.",
[329735755]="تم تفعيل إجراءات مكافحة الهروب. التدمير الذاتي بعد 20 ثانية...",
[329768058]="لك مني الشكر على التخلص من الدوارف الحديديين. لكن لماذا تهتم الـهورد بي؟",
[330190239]="أخيرًا، جمهور أسير!",
[330200575]="أبناء ثوريسان سيشاهدونك تهلك في حلقة القانون!",
