[330964131]="أخيرًا، أنا حر! سأعود قريبًا إلى البيت يا عزيزتي!",
[331076236]="هل أحد يريد استراحة؟ حسنًا، يا للأسف! اعملوا أيها البلهاء!",
[331081434]="اذهب بسرعة يا $N. مصيري بين يديك.",
[331465025]="أنت أيها الجندي، أبلغ كارغاث فورًا!",
[331743122]="أيها البشر المتهورون! لا أحد يتحدى أبناء ليفينق فليم!",
[331843948]="%s يزداد حجمًا!",
[331847129]="اسمعوا يا أتباع شركة فينتشر! القاعدة الأولى: لا تضعوا السجين قرب المتفجرات أبدًا.",
[332026836]="لقد فعلناها!",
[332571711]="أيها النبي!",
[332809827]="وماذا عنه؟",
[333137949]="مرحبًا بكم أيها المسافرون من دسكوود! بضاعتي الرائعة معروضة للبيع لفترة قصيرة في داركشاير. أسرعوا!",
[333205785]="والآن لنبدأ الإصلاحات.",
[333689243]="لقد مات كأعظم أبطالنا. كان غروم هو من حررنا جميعًا... كنت إلى جانبه عندما قتل مانوروث وأنهى اللعنة إلى الأبد.",
[333763775]="غوريفيند سيأخذ رأسك أيها المتطفل!",
[334344495]="ما كان يجب أن تفعل هذا! هو لن يعجبه.",
