[334986869]="لدي خمسة أطفال، $Gرجل:سيدتي;! سيموتون بدوني!",
[335005428]="اغفر لي يا أميري! لقد... فشلت.",
[335085754]="أجل. تايدهنتر سيسر بهذا التطور. سيطرة فايرلورد ستصبح أضعف.",
[335218808]="جنود هوروس، تيلينغ، روكويل...",
[335413516]="ماذا؟! بيرنينغ بليد ينتشر! يجب أن نتحرى!",
[335541340]="أنا لحم ودم مرة أخرى! شكراً لك، $C!",
[335664749]="كل الخليقة يجب أن تُفنى!",
[336706847]="افسحوا الطريق لـ نالوراك!",
[336837256]="طبيب!",
[336901948]="منادي الضباب ماهر جدًا في التحكم بالطقس باستخدام المزار. يعرفون أي البلورات يستخدمون! ماهرون جدًا!",
[337818018]="هناك ضوضاء من خلفك!",
[337890904]="كفى! سأعلمك بعض الأدب، أيتها الوقحة!",
[338324484]="ماذا تفعل هناك؟",
[338448732]="لا تقلق، كيكيك. ستنمو وتصبح قويًا من أجل فرينزي هارت. ستقود الناس للعودة للبيت القديم، حيث لا يوجد أطفال ذوو ألسنة كبيرة.",
[338513869]="هم ينامون بعدها. أما أنا، فأنام أثناءها...",
[338704766]="ذوق في قوتي!",
[339037354]="ماذا يمكنني أن أفعل لك؟",
[339406593]="%s يبدأ الترجمة...",
[339596223]="أنا لا أخاف منك!",
[341129616]="سيتم معاقبتك!",
[341209932]="هل جننت؟ تتوقع مني أن أترك طبلًا دون أن أضرب علماذا؟ ليس هذا ابن آيرونفورج! لا يا سيدي!",
[341352306]="لقد ربحت هذه المعركة، لكن ليس... الحرب.",
[341396353]="ابقَ قريبًا...",
[341425518]="بات ناجل! فريق تصميم العالم! كوري ستوكتون، بول سي، جيم تشادويك، ستاتس، إد هانز، موريس، غوتشر، جيسي!، سارة بي، فيكتور سي، ديف إي! كل فنانينا الخارجيين الرائعين!",
[341778243]="حان الوقت لمواجهة تحديكم النهائي أيها المحاربون الصغار! استعدوا لأصعب معركة لكم حتى الآن.",
[342351023]="ستغذي جثتك التربة.",
[342716216]="لزج لزج!",
[342740028]="لقد أعطيتنا وعدك أيها الخائن!",
[342764516]="سيأتي إخوتي من أجلي وعندها سترى ما هي القوة الحقيقية!",
[343149505]="حسنًا، $R، فقط احفظنا من الأذى ونحن نعمل. سندفع لك عندما نعود.",
[343448978]="أنا فقط أتأكد أننا لم نُتبع! *هق*",
[344573961]="عظيمة هي قوة الشفاء والبركة لأكثر أتباع النور اجتهادًا.",
[344910113]="لقد تعرضنا للخيانة من أحدنا. عار....",
[344946694]="%s ينشق!",
[345033772]="الدمار يجدنا جميعًا!",
[345062014]="لا أمل لمستقبلنا...",
[345932708]="ظننت أنني سمعت شيئًا.",
[346518580]="لن تغادر هذه المغارة حيًا!",
[346559082]="فقط الأقوياء—كا-رااك—ينجون!",
[346858756]="حسنًا، الآن لدينا منافسة بين أيدينا.",
[347346379]="%s يسرع إلى مزروعه.",
[347700475]="أنا أتذوق دم الحياة.",
[347842205]="أرني ما عندك!",
[348048779]="مووووو...",
[348236592]="شكرًا على الجبن!",
[348500601]="سأولد من جديد أيها البشر! إنسنديوس سيرفعني من هذا الرماد!",
[349008819]="جميل أن أعود بين الأنديد، بفضلك.",
[349816483]="سعيكم سيكون بلا جدوى، أيها الدخلاء، لأن الـليتش كينغ وضع جيشًا من الأنديد تحت أمري! انظروا!",
[349848370]="حسنًا، هذا ما أحصل عليه عندما أفرط في النوم!",
[349958386]="لا فائدة! سأوقف تشغيله...",
[350199421]="هذا اليوم نحارب!! بكل ما تعزونه في هذه الأراضي الطيبة، أطلب منكم الوقوف، أبطال أزيروث!",
[350402197]="ذهب داغان العجوز إلى الأراضي الوبيعة، ليرد الـسكورج إلى الأرض.",
[350480359]="هل لي أن أستظل بظلك إلى الأبد!",
[350530846]="ستظهر الاحترام الواجب!",
[350886843]="الآن بعد أن أتيحت لك فرصة دراسة الشيطان الصغير، دعنا ننتقل إلى التابع التالي الذي ستتمكن من استدعائه، وهو الفويد ووكر.",
[351018451]="نحن محاصرون!",
[351711779]="أنت لا تواجه مالتشازار وحده، بل الجيوش التي أقودها!",
[351803699]="لقد عدت، يا جريتموذر. قاروش وجد قلبه وغضبه.",
[351965386]="شكرًا لتغطيتنا من الخلف! سنمسك البوابة لحين وصول التعزيزات.",
[352418469]="لا أستطيع تتبع الآثار للخروج، هناك الكثير من الوحوش اللحمية في الطريق. أرسلوا أحدًا... اتبعوا الآثار... ياسيكس، خروج.",
[352780263]="أمسكنا بك الآن، ماتيس الـ كرويل!",
[352943781]="شكرًا لك مرة أخرى، $N. هذه التربة النادرة ستساعدني كثيرًا في تجاربي.",
[353171528]="هناك حقيقتان فقط هنا: الأولى، أن الزمن فوضوي، دائم التغير، وقابل للتشكيل بالكامل، والثانية، الإدراك لا يُملي الواقع.",
[353922528]="اهربوووا!",
[354098904]="أرجوك، أخرجني من هنا!",
[354403383]="لكن أنا المسؤول هنا...",
[355076456]="بينما تتجسس على مواقف كثيرة غير مهمة داخل آيس كراون، تصادف شيئًا مثيرًا للاهتمام...",
[355675069]="برودة هذا المكان... أشعر أن دمي يتجمد.",
[355734578]="موتك عبثي أيها الفاني الصغير.",
[355739349]="أنت لا تفهم! إذا لم أكن مستعدًا للذهاب قريبًا، فستؤخذ كل الأراضي الجيدة للاستيطان!",
[355866966]="أراك لاحقًا.",
[357629725]="آه، الكثير من الألم...",
[357785527]="إن آي أوف أشيروس ينطلق نحو وجهته.",
[357988214]="هذا الوعاء فارغ.",
[358684753]="نيبي، أنت أحمق.",
[358865842]="انتصار الديك الرومي!",
[359038408]="واو - كدت أموت هناك. شكرًا لك، $R!",
[359334343]="يمكنني إصلاحها، بوب. دعني ألقي نظرة عليها.",
[359366594]="شوهد الدوارف الحديديون وهم يخرجون من المخابئ عند قاعدة الأعمدة التي أمامك مباشرة! دمر المخابئ، وسيضطرون للتراجع!",
[359469068]="يا ستون، لنذهب إلى المضمار في وقت ما. يمكننا الجري بضع لفات ونرى من يفوز؟",
[359925883]="سأقطعك إربًا!",
[359988262]="غضب ايشاموهالي يجري في عروقك، $N.",
[360026425]="كنت أدخر هذا المكان لشيء مميز. لا أعتقد أن هناك ما هو أكثر تميزًا من هذا، $N.",
[360100626]="قريك احضر شرابًا!",
[360363072]="أيها البالادن المزيف، أظهر نفسك! استعد لتذوق غضب خدام النور الحقيقيين!",
