[429768947]="هذا مسار تفكير خطير. لو كان هناك خطأ حقيقي، فستكون سوريدورمي أول من يعرف.",
[430664883]="اقترب. سأجعل الأمر سريعًا.",
[430870141]="أي كلاب تجرؤ على اقتحام هنا؟ انتبهوا، يا إخوتي! وليمة لمن يجلب لي رؤوسهم!",
[430908508]="في شيء غلط... أحس بوجود مظلم.",
[431114525]="يمكنك أن تموت!",
[431968021]="%s يرمي نظرة من حارس لآخر.",
[432070526]="أنت... سوف... تدفع الثمن.",
[432813899]="هممم، هذا الشكل يبدو كشيء أفضل لو كان جرس ريح. خذوا ملاحظات يا صف... هذا ليس ما تريد استدعاءه في حرارة المعركة.",
[432888218]="بيرسيستنس أم غباء؟ لا يهم. لتكن هذه عبرة لك أيها الفاني!",
[432930215]="أرجنت كونفسور باليتريس يرسل قبلة إلى سيلفرمون تشامبيون.",
[433271367]="أنا سعيد بأنك بأمان، تاريثا. ما كان لهذا أن يتحقق لولا أصدقاؤك. هم من جعلوا كل هذا يحدث.",
[433504342]="قد يأخذون حياتنا، لكنهم لن يأخذوا أبدًا...",
[434331629]="موت! لن تحرر مايزريل!",
[434660150]="كنت أنتظرك، $N. سعيد برؤيتك وصلت. هل معك الشحنة؟",
[435935435]="%s يستعد لتحطيم بريتل قولمز!",
[435949589]="يجب أن أعود. صيد موفق لك.",
[435993168]="حافظوا على النظام داخل هذه الجدران.",
[436381289]="ليتني أملك بعض النبيذ لأشربه مع جبنتي...",
[436783732]="اصحى! قوم وارجع للشغل!",
[437076098]="لا شيء. لا شيء يمكنك فعله بينما النور يقيدك. يتحكم بك بالكامل، ويقيدك بالأرض بفضائله.",
[437694070]="الآن، أنادي أرواح هذا المكان. سأعطي أي شيء أو أدفع أي ثمن، فقط إذا ساعدتموني في إنقاذ شعبي.",
[438036209]="لن نفشل!",
[438207373]="ألست قصيرًا بعض الشيء بالنسبة لنوعك؟",
[438586879]="بدء جمع الطاقة.",
[438878538]="سأراك في معبد العواصف. يبدو أنني سأضطر لتدريبها من جديد.",
[439113210]="أورك قذر!",
[439653758]="وجهت تلك الكراهية نحو الإلیداري والبيرنينغ ليجيون... لكنهم لم يكونوا من خانونا. نحن من اختارهم نارو! عشنا ومتنا من أجلهم!",
[440078903]="بالنار يُطهر!",
[440750943]="فزت!!",
[440927648]="روحي ليست لعبة! أيها الفاني، يجب أن تحررني من هذه السلاسل!",
[441616113]="ارجع إلى بلود واتش. سأراك هناك...",
[442057981]="حسنًا، يعود إلى الملك متظاهرًا باللطف، يسحب سيفه، ويطعن الملك من المرفق إلى... حسنًا، أنت تعرف... يقتله في الحال.",
[442204468]="القاعة الرئيسية من هنا! لنذهب!",
[442377824]="أنو دوريني تالا، رو شالورا إنودوريل.",
[442473284]="أليست هي أجمل اختراع صغير؟",
[442559261]="لا تقف هناك فقط! ساعد $Gإياه:إياها;!",
[443138882]="هيا إذن، أيها $R $C، ليس لدي كل اليوم!",
[443726069]="نعم $Gسيدي:سيدتي;.",
[443907665]="مارينز، رقباء، هجوم!",
[444146455]="كم كان الأمر بسيطًا لإخراج الـتيريون فوردرينق العظيم من مخبئه. لقد تركت نفسك مكشوفًا، أيها البالادن. لا شيء سينقذك.",
[444162252]="أسحق الضعفاء مثلك كل يوم! تفضل!",
[444469869]="سأحطمك...!!",
[444597985]="جاينا! هل يمكن أن تكوني أنت حقًا؟",
[444802996]="وبعدها عض الأرنب رأسه... أقسم.",
[444865527]="كيف حالك، مون!",
[444984945]="سموتس! هي، سموتس!! اخرج والعب!",
[445277563]="أنت لست مستعدًا!",
[445394057]="الآن وبما أن الـداركسبير يعودون إلى هذه الجزر، ربما حان الوقت لنكشف عن أنفسنا.",
[445841559]="لا الشارب! الآن أنا غير متماثل!",
[446179539]="$N، تعال إلي من فضلك. أنا هنا في زيم تورغا الآن.",
[446495679]="لا بد أن هناك طريقة...",
[446512366]="فروستمورن: النصل الذي دمر مملكتنا...",
[448170850]="أتباع هاكار، اسمعوا إلهكم. قداسة هذا المعبد قد تم اختراقها. غزاة يتعدون على الأرض المقدسة! مذبح الدم يجب حمايته. اقتلوهم جميعًا!",
[448675359]="قوتك تغذيني، $N!",
[448899884]="هناك طريق هناك... فقط بعض الألغام في النهاية بيننا وبين الأدوات.",
[449333175]="هل من فلس، $Gسيدي:سيدتي;؟",
[450162769]="%s يبدأ في العبث بالنظارات أمام الحجر.",
[450455961]="هل يمكنك تفصيل طبيعة أنظمة الدفاع هذه؟",
[450776288]="قل لي عندما تكون مستعدًا. سنهاجم بأمرك.",
[451612519]="وقت التقمص!! أسمي هذا \"التاورن السخيف\".",
[451996090]="غويل. أنت غويل، ابن دوروتان - الزعيم الشرعي لذئاب الجليد. هذا اليوم، حفيدي - أنت فرحة قلبي العظيمة.",
[452160673]="يجب أن يكون لدي بعض النقود الإضافية من هذا البيع. ربما سأشتري لنفسي بعض الغداء...",
[452357940]="إذاً أنا على جبل مع شجرة كبيرة عجوز. مجموعة من الإلفز يركضون في كل مكان...",
[452638874]="دودة مثيرة للشفقة!",
[452662483]="%s يضحك ضحكة سريعة وساخرة على حظه.",
[452794279]="ربنا يأمرنا بالتجهيز للحرب!",
[452813110]="الآن لا تمسكنا وظهرنا لك! الآن سنؤلمك يا أنديد. وجع!",
[453865120]="$N، سأعرف هذه الأنياب في أي مكان... ماذا... ماذا فعلوا بك مون؟",
[453880926]="داليا تبصق على الأرض لمجرد ذكر الاسم.",
[453921510]="نحن ذراع إرادته. وسنسحق أعداءه حتى يصبحوا تراب القبور!",
[454161278]="الرينجرز بالتأكيد لديهم رأي عالٍ بأنفسهم.",
[454426051]="تم كل شيء!",
[454625480]="لن تجد إلا المعاناة داخل عالم الشفق! ادخل إن كنت تجرؤ!",
[454775792]="ميميرونز إنفيرنو متصل. جاري تحديد الهدف.",
[455070021]="موتك سيكون مؤلماً.",
[455340373]="$N! النجدة!",
[455397730]="أي- أين أنا...؟ يا له من كابوس عشته.... لكن هذا ليس وقت التأمل، لدي الكثير من المعلومات لأبلغ عنها!",
[455589143]="للأسف، أيها المغامرون الشجعان، تدخلكم قد وصل إلى نهايته. هل تسمعون قعقعة العظام والحديد قادمة من النفق خلفكم؟ هذا هو صوت زوالكم الوشيك.",
[456520916]="خذ $Gإياه:إياها; بعيدًا وجهز $Gإياه:إياها; لإعادة الإنعاش.",
[457185475]="رجال القلب تورن يعطون أسلحتهم لـإيرثمندر تورلوك.",
[457329910]="أسرع بها! كلما طال وقتك، زاد الألم الذي سأوقعه بك!",
[457772047]="سيكون هناك وقت للمعركة، دورم. لكن أولاً، يجب أن نجد طريقة لموازنة الفرص. ماذا تريد مني أن أفعل، آير؟",
[458004796]="ستدفع ثمن هذا الانتهاك.",
[458009792]="وضعية دفاعية! احمِ نفسك من ضرباتهم ورد الهجوم!",
[458238671]="هناك بعض التعليمات الغامضة في هذه المذكرة. لا بد أن بران كان لديه خطة احتياطية، لكنه لا يستطيع تجنب الأسر إلى الأبد...",
[458402731]="أتوقع موتًا مؤلمًا.",
[458939251]="كيريل ناراك!",
[459010620]="آه، ونتر وندرڤولت. ماذا سنبتكر بعد ذلك؟",
[459370499]="ما الذي تأمل في الحصول عليه من هذا؟",
[459631115]="إذا اكتشف جنرال كراكورك الأمر، سيلتهمنا أحياءً. لا تفعل.",
[459812352]="لكن... مالفوريون، سيناريوس، يسيرا... ما زالوا يقاتلون. يحتاجونني. يجب أن أعود إلى الحلم فورًا.",
[459866043]="أنا عطشان.",
[459919026]="تم الاستيلاء على ورشة حصار ويستسبارك من قبل الـهورد!",
[460192108]="$N يتحدى الـ بلاك نايت في محاكمة بالقتال!",
[460497447]="إنه يتجه نحو مستر فلوبي!",
[460535618]="لن تهزم الـليتش كينغ أبدًا بدون قواتي. سأنتقم... منه ومنك!",
[460666979]="برج ويست فروست وولف يتعرض للهجوم! إذا تُرك دون رقابة، سيدمره الأليانس!",
[460942589]="من رحلة الأمس الميدانية، أظهر لنا ماردوك أن التنانين ستتحمل لحم البشر المقتولين حديثًا، ولكن فقط إذا ماتوا ببطء وألم.",
[460988156]="ريمولوس، أنا أُسحب للخلف... تيراندي... أرسل لها حبي... أخبرها أني بأمان. أخبرها... أخبرها أني سأعود... وداعًا...",
[461554635]="لا يزال لدي بعض... القتال... في داخلي-ي-ي...",
[461661955]="تم إنقاذ سد ستونرايت! ثلاث هتافات لـ$N!",
[461898535]="هاي، إنه طيارنا الماهر، $N!",
[461924024]="المقاومة فقط تزيد الأمر سوءًا.",
[462576806]="سيقتلك فرينزي هارت إن عدت. لم تعد مرحبًا بك هنا!",
[462834299]="هذا المرض يغشى بصري، لكني أعرف أنك لا بد أنك تروق. مت أيها الغازي الحقير!",
[464045148]="لا تؤذي بيتسي، أيها الحقير!",
[464807077]="استدعوا المهرجين! لقد تحولت إلى سيرك هناك!",
[464832019]="آه، ها نحن ذا! حسنًا، لنبدأ العمل، أليس كذلك...؟",
[464915417]="بدأت المعركة. $N، استعد للقتال!",
[465289204]="لقد تم قياسك ووجدت ناقصًا...",
[466019867]="ظهرت العناكب الصغيرة على الشبكة!",
[466655452]="هذا ما أردت معرفته. الآن فقط أحتاج أن أجد أين تتم مناقشة تباين التدفق.",
[467204496]="أنا أستمتع بالسخرية.",
[467218440]="التحدي يكمن في النظر إلى ما وراء المظاهر وفهم أوجه التشابه بيننا. من خلال هذا الفهم، يمكنك أن تشعر بالتعاطف مع الخسائر التي عانى منها الآخرون...",
[467502685]="لا تتركني وحدي!",
[467638641]="على الأقل لم تفسد هذه الدفعة.",
[467675495]="قلب %s مكشوف ويسرب الطاقة.",
[467798450]="الجميع إلى مواقع القتال! ناغا قادمون!",
[468429665]="أغبياء! ضعفاء! تزراك لا يحتاج مساعدتكم!",
[468523950]="تقاتل كالفتاة!",
[468940142]="<زئير غاضب>",
[469319372]="تم الأمر. الطوطم صُنع.",
[469511361]="يجب أن تتخلى! يجب أن تصبح ما كنت مقدرًا له دائمًا! الوقت الآن أنفينا!",
[469825515]="لا شيء كالكأس الممتلئ لابتلاع كعكاتي الرائعة.",
[469862292]="الأشياء التي أريكم إياها الآن يجب ألا تُذكر خارج فولتاروس. سيعرف العالم سرنا قريبًا!",
[470342119]="يوثر! عزيزي يوثر! أنا... أنا آسف جدًا.",
[470414508]="ابتعد عن تلك البراميل!",
[470845385]="كان ذلك قريبًا! لقد أخفتني.",
[471443798]="أنت لحم!",
[471975889]="أنت! فييند، لست حبيبي! ارحل!",
[472083972]="المدينة لا تزال تحترق، نار تطهير! الوقت قصير، سأتقاعد قريبًا!",
[472473621]="لم تكن لنا فرصة. بينما كان إخوتي يموتون حولي، تمكنت من التراجع إلى هنا وسد المدخل.",
[472483735]="نضرب!",
[472925125]="أنجب أطفالي.",
[473059200]="ألا تستطيع على الأقل أن تقاتل؟",
[473773619]="وهناك أورقريمار، ضخم ومخيف كالعادة. خذوا استراحة سريعة يا رفاق، ثم نعود إلى الـبلاف!",
[473906628]="اللحم... يا له من عائق.",
[473926291]="آه، كان يجب أن أعرف.",
[474730828]="استمر في التفكيك.",
[474769067]="فيكسالاس زيادة تحميل!",
[475229514]="تذكر، إذا ضايقت الممثل أو أرسلت سبام في القناة، قد يتم طرد حسابك، حظره أو ما هو أسوأ.",
[475571882]="هذا صحيح، $N. عجلات الهلاك الآن تدور، لا محالة، نحو العودة الحقيقية لـهاكار!",
[475994249]="حزمة روكيت نشطة!",
[477410539]="أيها الجبناء عديمو العمود الفقري! ستغرقون في أنهار من الدم!",
[477817550]="سيف... هل كانت سيف هنا؟ مستحيل--لقد ماتت على يد أخي. كابوس مظلم حقًا....",
[478412842]="هل يمكن لأحد أن يخرجني من هنا؟ أحتاج للعودة إلى فينومسبايت وإنهاء نوبتي.",
[478874769]="ورشة حصار الحلقة الغارقة تم الاستيلاء عليها من قبل الـهورد!",
[479047575]="هذا كل ما لدي لأقوله الآن. ابقوا مركزين، يا أولاد وبنات.",
[480117934]="حراس، تحركوا! مين اللي خايفين منه أكتر، منهم... ولا مني؟",
[480437959]="أبطال، أنتم أحياء! لم تهزموا كل تحديات الـترايل اوف الـ كروزيدر فحسب، بل أحبطتم أيضًا خطط آرثاس! مهاراتكم ودهائكم ستكون سلاحًا قويًا ضد الـسكورج. أحسنتم! اسمحوا لأحد ميجز الحملة بنقلكم إلى السطح!",
[480864218]="توقفوا... يجب أن ألتقط... أنفاسي.",
[480968270]="ما عدنا نقدر نطلع من بيوتنا! الهجمات ما بتخلص!",
[480994273]="أخبار سيئة، يا سيدي.",
[481479855]="الخطر انتهى! $N أنقذونا كلنا!",
[481630717]="ها هي، رون القيادة... أتمنى. ليس شرسة قد قريبتها الـآيرن دوارف، لكنها شغالة.",
[482852615]="أوه لا... قيدوا روحه!",
[483096826]="السجناء لن يتحرروا! كلمة ماليقوس هي القانون!",
[483118280]="أنا أتكلم معك أيضًا، يا صاحب البنطلون الفاخر موغراين! اسكت!",
[483128979]="مستحيل!",
[484390764]="بام!",
[484610467]="دخلاء! هاجموا الدخلاء!",
[485814946]="ادرس بجد وربلا تستطيع يومًا استدعاء واحد بنفسك، لكن الآن حان الوقت للانتقال إلى الفيلهانتر.",
[486941529]="لحرق مملكتي، لا يمكنك استخدام النار! تعالوا يا خدمي، أنا لست مستعدًا للتقاعد!",
[487162851]="نعم، تعال. أنا وسيدي سننتظر.",
[487200463]="مليء بالحياة...",
[487222663]="استخدم عصا القيادة هذه على ريز عندما تكون بالقرب من شادوسيلك بوشرز وسيجعلهم يندمون على اليوم الذي قرروا فيه الصيد غير المشروع في هذه الأراضي.",
[487342032]="مرحبًا، بنجامين! هل تمانع لو أخذت تفاحة من أجل العجوز بيسي؟",
[487809726]="انظر هنا، $C! عندي شيء لك. بالضبط ما تحتاجه. إنه صابون، صحيح... وهو على حبل! لا تهين، $Gرجل:عزيزتي;، لكنك نتن قليلاً، فهمت قصدي؟",
[487962429]="%s يسقط على ركبة واحدة - منهك.",
[487971662]="أي، أعرف. شاهدته يتحول... شاهدته يتخلى عن كل ما هو صحيح ولم أرفع يدًا... لم أفكر في الأمر حتى فات الأوان.",
[488543271]="حلفاؤك وصلوا، جاينا، كما وعدت. ستصبحون جميعًا عملاء أقوياء للسكورج.",
[488931194]="أشعر بخطر عميق داخل البستان...",
[489010630]="أهلاً. هل يمكنني مساعدتك في العثور على شيء؟",
[489080155]="آه، أرى أنك تعبث بآثار الماضي.",
[489307433]="اصعد إلى هناك. تقدم نحو معقل بليدسباير. أريد أن أزين برجي برأس قورديم!",
[489332496]="هذا في الماضي، مورادين. الندم لن يغير شيئًا.",
[489556081]="الغضب المشتعل بداخلك سيجد قريبًا وقودًا في أعدائنا.",
[489612883]="القوى السماوية هي ملكي لأتحكم بها.",
[489830919]="جهزوا أسلحتكم يا إخوتي الأرجنت. الفيريكول سيحمون ملكة الجليد بحياتهم.",
[490010092]="كفى! سأهبط وأسحقكم بنفسي!",
[490490519]="أنا حُر أيها الدراكاري الصغير. حان وقت الدفع مقابل تعدياتك الكثيرة!",
[490618846]="توينكل ينظر إلى فييرا سنويسبر بعيون جائعة جدًا.",
[490866906]="الموت لأي $R يقف في طريقي!",
[490962550]="%s يردد كلمات القوة...",
