[672771614]="ستقطع رؤوسنا إذا تم القبض علينا!",
[672970895]="لقد قُتلت! استدعوا فيروق!",
[673293185]="مرحباً! أنت قوي ولطيف وأشياء من هذا القبيل. أنا معجب بك. لنبقى أصدقاء، حسناً؟",
[673593165]="تعالوا، أيها الصغار.",
[673658133]="أينما أنظر أرى لصوصاً. نحن، ميليشيا الشعب، يجب أن نعيد هذه الأرض إلى المزارعين.",
[673870673]="حُرِّيَّـــــــــــــــــــــــــــــة!",
[674029903]="العمود فخ، يا وارتشيف. السقوط يعني الموت المحقق.",
[674105572]="هل يستطيع أحد أن يمنح قطتي الصغيرة اللطيفة جداً منزلاً؟",
[674550911]="الكرة العين الضخمة الطافية في وسط الغرفة توجّه نظرها إليك. أنت تقف أمام إله.",
[674841534]="$N، تحت الطحلب، هذا القلب يبدو كبذرة!",
[674955409]="أرى أن دقة التصور تفوق أمثالك من البدائيين.",
[674969319]="اختراق أمني قيد التنفيذ. تحليل الأرشيفات التاريخية نُقل إلى قائمة أولويات أقل. تم تفعيل الإجراءات المضادة.",
[675497580]="تعاويذك... كي-كاو... سحر ضعيف... سهل قلبه ضدك...",
[675592788]="ابن دوروتان... حفيد غاراد وغيا... احنوا رؤوسكم، فوارتشيف بيننا...",
[675688698]="تم عقد اتفاق، $Gأخي:أختي;! أقسمنا بالانتقام من الـليتش كينغ! على ما فعله بنا! حاربنا الـسكورج كفورسيكن، ودفعناهم إلى الأراضي الموبوءة وحررنا تيريسيفال! أنت وأنا كنا أبطال الفورسيكن!",
[675913401]="أنا من أحضر كويلديلار إلى هنا، لأعيده إلى صانعيه. بكسر السلاح، كسرت قوته.",
[676349018]="$N قبل تحدّي خيتريكس الـ دارك ماستر. لترحم الآلهة $Gإياه:إياها;، فخيتريكس بالتأكيد لن يرحم.",
[676914838]="%s يحس بوجودك ويفتح بوابة نيذرية!",
[677136040]="لا، ليس التروس! أي شيء إلا التروس!",
[677146895]="%s أصيب بالصمت من جوهرة الروح!",
[677247783]="المخبأ الجنوبي لدون بالدار يتعرض لهجوم! إذا تُرك دون رقابة، سيدمره الـهورد!",
[677504431]="هل أتيت لتقديم آرثاس للعدالة؟ لترى الـليتش كينغ مدمرًا؟",
[677855535]="ها نحن ذا، $N. اللفيفة أُصلحت! مرحى!",
[677884402]="دروعك لا فائدة منها ضد جرادي!",
[677941365]="الأرواح من الهاي بورن! يمكنك الآن الراحة! لعنة الكريستال تطلق سراحك!",
[678169360]="هذا العالم سيحترق!",
[678272751]="%s يسقط على ركبة واحدة.",
[678451823]="استعدوا! الناغا لن تنتظر طويلاً لاستغلال الميزة بمجرد أن يعلموا أننا على قيد الحياة.",
[679057263]="هناك طائر!",
[679250025]="الطاقات الناتجة قد تنهار مع ذلك، وهذا قد يسبب تدفق طاقة يسبب لك صداعًا لأسابيع.",
[679438131]="أحمق! لن تهزمني أبدًا!",
[679466942]="سأقاتل... حتى النهاية!",
[679833993]="%s يطعم بيسي التفاحة الحمراء الزاهية.",
[680136122]="أنا متوتر كما أنا... والناس يصرون على إخافتي... في المرة القادمة، سأكون مستعدًا!",
[680140267]="%s يتبع $N بسعادة كشتلة جديدة لـ$Gخاصته:خاصتها;.",
[680290956]="يبدو ذلك! وأنت لم تفقد شيئًا من قوتك. هل تتذكر أي شيء مما حدث، مورادين؟ لقد تحول القدر إلى سوء في غيابك.",
[680431762]="أوه، عرض آخر بالفعل؟ حسنًا إذن...",
[680477477]="أكثر ملا تستطيع التعامل معه، أيها المستكشف؟",
[681035088]="جين سيعشق هذه!",
[681266667]="مرة أخرى نسمع نداءك، خوفو. لدينا حكمة لك ولـ$N. تواجهون خطرًا عظيمًا ويجب أن تتصرفوا بسرعة وإلا ستموتون أنتم وهاركوا.",
[681426055]="يجب أن أتغذى...",
[681870503]="%s يتحول إلى الوضع الدفاعي!",
[682485256]="استرخاء؟ هل تعلم ماذا يفعل كيل'ثاس بمن يخذلونه، جيزل؟ معاناة وألم أبديان... لا تفسد الأمر، أيها الأحمق.",
[682500349]="وكأنك تقرأ أفكاري.",
[682743296]="خذ حجرًا من الطاولة، $N. ستحتاجه لمهمتك.",
[682954844]="من منكم مخلص؟",
[683381344]="أتمنى ألا ينسى أزيروث أبدًا الثمن الباهظ الذي دفعناه لضعفنا... لكبريائنا.",
[685207639]="أعتقد أنه من الأفضل أن أفعل شيئًا حيال هذا!",
[685239590]="%s يحشد المقاتلين الآخرين بزئير حرب!",
[685639397]="%s يبدأ في إلقاء |cFFFFFFFFالنور فورتكس!|r تحول إلى |cFFFFFFFFالنور|r الجوهر!",
[686291624]="حسنًا، مهما كان، فهو يعمل بشكل جيد!",
[686325689]="أنت مستيقظ؟؟ لا بد أن علاجك قد نجح! شكرًا لك، $N.",
[686403086]="ممل...",
[686915833]="أنا أعيش فقط لأخدم الـليتش كينغ!",
[687163543]="الآن هو وقت الانتقام.",
[687292968]="الزقورة ضاعت! اهربوا إلى المعبد!",
[687331983]="لقد جعلت أطفالي يتامى في هذا اليوم، أيها الشرير!",
[687581680]="أليثيس! نيرانك تشتعل في داخلي!",
[687752449]="كيف يمكن أن يكون في خطر؟ كل ما أراده هو أن يمنحنا السيطرة على العناصر التي جعلت الحياة قاسية لنا هنا.",
[687851526]="\"ياااااااار... هذا يقودني للجنون!\" لحظة... ليست هكذا تمامًا...",
[687954222]="السيد سقط! انتقموا له يا إخوتي!",
[687979836]="ماذا ربحتم من هزيمتي؟ أنتم لستم أقل حتمية الهلاك، أيها البشر.",
[688899288]="الكل يحيي $N، الـ$Gملك:ملكة; الجديد للأوغرز!!!",
[689464254]="لقد استسلموا وخضعوا - طواعية - لنا.",
[689575472]="شيء ما نتن هنا! بالتأكيد ليس أنا. النومز رائحتهم زبدة وأشعة شمس. ليس مثل أولئك الدوارف الذين رائحتهم كأنهم ولدوا من إبط تروق! لا أحد منكم دوارف، أليس كذلك؟",
[689923159]="متوقع جدًا...",
[690754913]="%s يضيف الضباب إلى براعم بلودبيتال.",
[690850014]="أنا الحلم الواضح.",
[690949790]="شكرًا!",
[691205937]="خيتريكس الـ دارك ماستر يزحف إلى فالهالاس من الجنوب الشرقي!",
[691721002]="موت المحارب.",
[691773085]="فرياز وارد متصل. جاري تحديد الهدف.",
[692131533]="بالكاد يشكل تحديًا.",
[692220225]="رايت، هل أنهيت تلك الجرعة الجديدة التي كنت تعمل عليها؟ لقد تعبت من هذه الجراثيم التي تملأ متجري!",
[692785023]="ديث نايتز... تعال إلى هنا!",
[692942198]="تحرك يا زيبيك! ليس لدينا كل اليوم!",
[694548808]="لمرة واحدة أوافقك الرأي... أيها الحقير.",
[695090365]="مرحبًا أيها الأبطال. اليوم، أمام أعين قادتكم ونظرائكم، ستثبتون أنكم مقاتلون جديرون.",
[695819235]="اسجدوا أمام إله الموت!",
[695963005]="لا أستطيع النوم دون قصة قبل النوم جيدة. الآن أنا متأكد أنني سأرتاح جيدًا.",
[695984358]="ماما؟ هل يمكنني مداعبة فيزلز؟",
[696608338]="ماذا تظن أنك تفعل يا رجل؟ ليبرونسكي لا يحب أن تسحب أجزاءك المعدنية السائبة على سجادته.",
[696619361]="أنا آسف...",
[696917346]="اطلب أي شيء وسوف تحصل عليه! فقط أبقني على قيد الحياة!",
[697377245]="أيها الأوغاد الحقيرون! ابتعدوا عن الجثث!",
[697938394]="تعالوا إلي أيها الصليبيون. سأعيد تشكيلكم!",
[697993086]="إنهم مصرون جدًا.",
[698025503]="البرج الشرقي قد دُمر!",
[698597913]="برينس آرثاس، ليُحمد النور! بدأ الكثير من الناس في البلدة يمرضون بشدة، هل يمكنك مساعدتنا؟",
[698626331]="%s يتجه نحو الجنوب الشرقي ويئن قبل أن ينظر إليك.",
[698710909]="امنحني الحماية، $N. يجب أن أخترق سحرهم الخبيث!",
[699163247]="لقد حانت النهاية!",
[699723579]="%s يهتف لك.",
[700218443]="حان وقت لقاء خالقك، $N!",
[700251905]="هذا آخر خطأ سترتكبه، أيها الهيكل العظمي.",
[700808276]="%s يغمى عليه.",
[700960346]="رايمفانغ، دمر هذا الأحمق!",
[701219488]="مستحيل.",
[701249241]="ارتجفوا يا ديدان!",
[701960719]="ماذا ستختار؟",
[702310798]="أين وضعت تلك الأحفورة الغامضة؟ آه، ربما هناك في الأعلى...",
[702612793]="برج القلعة الجنوبي الغربي قد تضرر!",
[702948114]="هذا الصندوق لن يوصل نفسه يا صديقي. تحرك!",
[703402560]="تسمع صدى خافتاً...",
[703740419]="لماذا أسرتمونا؟",
[703887367]="أخيراً، لدينا القطع لإصلاح سبيريت أوف نوميريغان.",
[704898141]="$N قادم بهذه الطريق بسرعة! حان وقت الانتقام!",
[705258730]="%s يجهز حقنته.",
[705476766]="<شم، شم> أستطيع شم رائحتهم، مون.",
[705599035]="هذا. خلصت من ردائك، $N.",
[706049084]="كفى من هذه المهزلة!",
[706256929]="مالقانيس ما يسهل الأمور.",
[706388309]="أنا زي إله الصيد...",
[706442572]="هجوم الخاتم الأرضي يبدأ.",
[706742128]="اشربوا بعمق يا إخوتي!",
[707233807]="%s يدخل في غضب بعد رؤية $N يسقط في المعركة!",
[707458284]="أتدرب أفضل ضد دمية هدف.",
[707489611]="في الحال!",
[708077520]="ستطير مجددًا أيها الوحش...",
[708318619]="يصرخ الجمهور من الرعب.",
[708341804]="فقط الأقوياء سينجون.",
[708477147]="أين هم أبطال هذا العالم المزعومون؟ خائفون جدًا من الخروج واللعب؟",
[708694135]="هذا العالم لديه ما يكفي من الأبطال.",
[708778099]="أتعلم، $N، إنه لشرف لي العمل معك!$B$Bعندما لا تكون مشغولًا بالسيطرة، ربما يمكننا $Gنخرج للعشاء في مكان ما؟:نجتمع لسهرة بنات؟;$B$Bأوه، هل ذكرت أنه يمكننا الآن إيصالك إلى قاعدتنا في جبال سكيثيل بسرعة؟ إذا أردت، تحدث مع سكاي غارد هاندلر ايرينا بخصوص ذلك.",
[708894823]="تريد قتلي؟ أنت أولًا!",
[708969363]="نهايتك محتومة.",
[709829152]="السادس والعشرون! هل ستبدأ بالقتل أم ماذا؟",
[709835742]="لن تنجو حيًا!",
[709977352]="أنارانيل بيلور!",
[710905071]="من يزعج تأملي؟!",
[710920740]="هل جئت لقتل داليا؟ هل يمكنني المشاهدة؟",
[711285801]="معرض سباركلايت للمركبات مفتوح للعمل!",
[711387189]="اتبعني وسأفتح لك باب الفناء.",
[711526501]="س-سيدتي... هل يمكنني ت-تمشيط جوادك القوي...؟",
[711944729]="بحث... تدمير الممثل الأساسي يُعتبر أول علامة تحذيرية لفشل كوكبي نظامي. وصول مراقب الجالون يتبعه تشخيص كوكبي يؤدي إلى إحدى إشارتي رد محتملتين. رمز الرد ألفا، يعني \"كل شيء على ما يرام\" ورمز الرد أوميغا، يعني إعادة أصل الكوكب.",
[712463033]="سأحضره فورًا، حبيبي...",
[712793481]="أهذه تسمى ضربة مطرقة؟ أي نوع من الهواة أعمل معهم هنا؟",
[712952013]="سيدتي! هل سيلتهمنا هيدلس هورسمن؟",
[714008588]="مثير جدًا، جدًا. وجدت هذا في دوروتار، $N؟",
[714902914]="ألقى البلود إلفز أسلحتهم أمام المدافعين عن المدينة؛ قائدهم، شيخ بلود إلف يُعرف باسم فورينثال، اقتحم تيراس أوف لايت وطالب بالتحدث إلى أدال.",
[715644001]="اسقط!",
[716376950]="أعطنا وقتًا... دع الرجل يموت... أنا لا أحد... أنا لا أحد... اخش الأنكورايت... اخش الأنكورايت... بارادا... بارادا.",
[716423642]="ها! جوريجيك أعظم هنتر على الإطلاق! جوريجيك يحصل على أكبر هاردنكل!",
[717023697]="وجبتك جاهزة. تعال وخذها...",
[717707712]="كانت إرادة راقناروس أن يُبنى أوبسيديان. أوبسيديان سيدمر أوركس بلاكروك في بلاكروك سباير، موحدًا إيانا مع إخواننا في الأعماق النارية.",
[717740714]="استيقظي، غال'ريسا.",
[717854745]="لم أعد أستطيع مقاومة نداء فروستمورن...",
[718465088]="رومولو، أنا قادم! أوه... هذا أشربه لك!",
[718610806]="برج بوينت تتعرض لهجوم! إذا تُركت دون مراقبة، سيدمرها الأليانس!",
[719220775]="لا زلت واقفًا؟ ليس لوقت طويل.",
[719372417]="آه، لقد وصلت أخيرًا برينس آرثاس. لقد جئت في الوقت المناسب تمامًا.",
[719737129]="لقد تم استدعائي للعودة إلى ويرمريست، أيها الحليف. وداعًا!",
[721185122]="أجبني! هل عضك أحدهم؟",
[721277268]="وراء هذه المناطق، يواصل الـسكورج عملهم، ويدمرون المزيد والمزيد مما بنيناه. المعركة يجب أن تكون هناك. يجب أن أكون هناك.",
[721713236]="أتريد منا المساعدة في شيء؟ بماذا نساعد؟ نحن جيدون في المساعدة.",
[721945097]="سأعود إلى مهد الحديد والحجر.",
[722631698]="ورشة حصار ويستسبارك تم الاستيلاء عليها من قبل الأليانس!",
[722725437]="اصعد على متنها، الآن! هذا الجبل بأكمله قد ينهار في أي لحظة.",
[723186830]="سنشق طريقًا من الدمار عبر هذا المكان الملعون ونجد طريقة لدخول هولز أوف ريفلكشن. إذا كان هناك أي شيء ذو قيمة ليجد هنا، فسيوجد في القاعات.",
[723223651]="الكثير سيسقطون مثلك.",
[723234179]="قد ترغب في التفكير بمغادرة هذا المكان. أعتقد أن التحول إلى ضفدع هو أحد أفضل الأشياء التي يمكن أن تحدث لأحدهم هنا.",
[723404795]="%s يطلق صرخة حادة عالية النبرة، طالبًا المساعدة!",
[723421688]="كيفر غير سعيد بهذا. ربما إذا جرب كيفر جرعة أكبر، قد يحل هذه المعضلة.",
[723583175]="طعمه مثل... الكرز! أوه! اعذرني!",
[724489066]="الـسكورج لا يمكن إيقافه...",
[725347436]="رائع! التالي، بعض التعاويذ الوقائية. أجل، الآن نحن نشتغل!",
[725894595]="محاولة شجاعة.",
[726057634]="هنا هنا!",
[726271811]="انظروا إلى اليد التي تقف وراء كل الشر الذي حل بـاولدوار، دمرت مملكتي، أفسدت أخي، وقتلت زوجتي.",
[726274075]="ألا يوجد بطل لإنقاذي؟",
[727899619]="$N سينضم إلينا في هجومنا. دعونا نجلب السلام لأجدادي!",
[728084960]="أوه، هذا لا يبدو جيدًا. قد يكون لدينا تعقيد أو اثنان...",
[728459334]="يجب أن نخرج من هنا. أحتاج للتجديد!",
[728469308]="%s يصل!",
[728695441]="%s يرسل أعداءه إلى قبورهم المائية!",
[729107141]="هذا الوحش الصغير النجس هو الإمب. إنه صغير وضعيف، مما يجعله عديم الفائدة تقريبًا كدرع بشري، وضرره متوسط في أحسن الأحوال. هذا المخلوق أفضل استخدامه لدعم مجموعة أكبر.",
[729269023]="كيف تجرؤ على استدعائي بدون قربان!",
[729564887]="مثير للاهتمام.",
[729579911]="%s يتفقد ساحة تدريب الحراس الصغيرة بابتسامة متعالية.",
[729633473]="أعتقد أننا أفلتنا منهم! كانت قريبة! حسنًا، كما وعدت، لودج العنبر سليم! ابقَ على الأرض يا صديق!",
[730209661]="هل ستستمر في فعل هذا لفترة أطول؟",
[730230268]="الساحر سيسقط!",
[730601966]="من هذا الضعيف $C الذي يتحدى قوتي؟ مت أيها الأحمق!",
[730903029]="جوبجوب؟ أين أنت يا جوبجوب؟ أوه لا! أين ذهبت هذه المرة!",
[731295215]="الأشياء الطائرة ليست قوية كما تبدو. أشياء الدبابير أشرس قليلاً.",
[731766431]="شكرًا لك، $N. أرجو العودة إلى إخوتي عند مذبح اللعنة، قرب يد غولدان، وأخبرهم أن وايلدا بأمان. لترعاك الأم الأرض...",
[731807043]="شاهد، أيها الدرويد. الأرض لا تزال تتنفس. إنها تتوق إلى التطهير.",
[731865167]="من يجرؤ على تدنيس تمثال حبيبنا؟",
[732614199]="هل سيفوز؟ هل يستطيع الفوز؟",
[732688423]="مت بشكل جيد، أيها الأحمق.",
[732964401]="غوراموش مشغول بطقوس الآن.",
[733097403]="مرحبًا بك في الـهورد، أيها الزعيم الأعلى. لوك تار أوغار!",
[733214928]="نعم... بما يكفي للعناصر الموجودة هنا، لكن الشيفرة معروفة لآخر... أرواح النار في اضطراب... إذا لم يتم إيقاف هذه القوة، فإن العالم الذي أتى منه هؤلاء البشر سيزول.",
[733705691]="لا، هذا مستحيل! لااا!",
[734127905]="لا تتوقع أن تمر تدنيساتك... دون عقاب.",
[734176038]="هذا الكتاب سيمنحني قوة غير محدودة على أعدائي... سأصبح... لا يُقهر!",
[734187835]="اسمعني، $N. يجب أن تقاوم سيطرة الـليتش كينغ. إنه وحش يريد رؤية هذا العالم - عالمنا - في خراب. لا تدعه يستخدمك لتحقيق أهدافه. لقد كنت بطلاً ويمكنك أن تكون كذلك مرة أخرى. قاتل، اللعنة عليك! قاوم سيطرته!",
[734423715]="لقد تعبت من الركض، لكن هذه النحلات لا تتركني وحدي!",
[734601045]="واو.",
[734643186]="قريبًا، حبيبتي. قريبًا ستستيقظين وكل أزيروث سيعرف الخوف!",
[735441610]="أيها الأخ الريح العظيم، امسح طريقنا!",
[735626165]="في الحياة كنا أعداءً مكروهين - هذا صحيح...",
[736445470]="ولم لا؟ فقط فكر كم ستبدو أفضل مع الصغار على كلا الجانبين --",
[736885779]="أي $R يجرؤ على إيذاء أفراد قطيعي؟",
[737233324]="انتبه، فيتز، إنهم قادمون نحونا!",
[737548491]="جوعي لا يعرف حدودًا!",
[737914137]="أيها الأحمق! أنت طفل يلعب في عالم يفوق فهمك. لا تتكلم بعد الآن!",
[737930371]="أنت هناك! تقدم!",
[738228548]="أوه لا! لقد خرج عن السيطرة! اهربوا!",
[738570307]="هذه المهزلة تنتهي هنا!",
[738867902]="لقد تجاوزتِ حدك في العبث بالسحر، ميديف. لقد جذبتِ انتباه قوى تفوق فهمك. يجب أن تغادري كرازان فورًا!",
[739052777]="ارتفع بإنجاز $N! ابتهج بهتاف $Gخاصته:خاصتها;!",
[739054191]="صلِّ لآلهتك أيها الشامان. ربما يأتون لنجدتك. أما الـهورد فلا يستطيع...",
[739142011]="انتظر... توقف! لا يمكنك استعادة القوة!!!",
[739944034]="حتى لا نشعر بأرجلنا!",
[740821304]="ثق بي - ستعجبك هذا!",
[741409150]="أوركس أورقريمار يهتفون لـ $N.",
[742199962]="إلى الحجم!!",
[742374018]="...ما تبقى منها!",
[742726062]="سأبقي هذا هنا حتى نحتاجه...",
[742862169]="أشبرينغر مات ولن يأتي مثله أبدًا. موغراين الأصغر ليس بوالده أبدًا. أنت تعلم هذا أيها القائد! ففي النهاية، قيادتك أنت هي المسؤولة عن موت الـسكارليت هايلورد موقرين.",
[742899639]="لا! نحن هنا أولًا!",
[743270884]="اصرخوا طلبًا للرحمة! حياتكم التافهة ستنتهي قريبًا!",
[743539301]="نعم، زيكسيل سيكون اسمًا معروفًا! سأحتكر السوق!",
[743665719]="نجاحهم يعتمد على ما نكتشفه داخل هذه القاعات الملعونة. رغم أن مهمتنا محفوفة بالمخاطر، يجب أن نثابر!",
[745808916]="استرح جيدًا أيها البطل.",
[746830491]="سيأخذ آخر مكانه. أنت تضيع وقتك.",
[746881933]="كما تقول يا سيدي. يبدو أن أحدًا نسي أن يخبرني أن الدرويدز في ثيكت السيناريون قد قُضِي عليهم!",
[746891544]="مخبأ آيسوينغ يتعرض لهجوم! إذا تُرك دون رد، سيدمره الـهورد!",
[747061471]="هذا قبيح بشكل خاص. مثالي ليكون غولاً...",
[747644361]="الـليتش كينغ هنا؟ إذن سيتحقق قدري اليوم!",
[747989891]="أوكي... كيف الآن؟",
[748281730]="باه! مورادين، تأمّن السطح وجهّز جنودنا لاقتحام القلعة العليا. سأرسل فوجًا آخر من ستورمويند.",
[748300388]="اسمع، $N، أعرف مستنقعًا صغيرًا ليس بعيدًا من هنا...",
[749168219]="لماذا رايحين من هذا الطريق؟",
[749178083]="اقتلوا هؤلاء المتسللين، يا دريغوود القذر! أعدكم بعذاب لا ينتهي إن عصيتموني!",
[749243125]="هذا صحيح في الأساس.",
[750209132]="يجب أن تطلق أسرع من ذلك! لدي 11 قتلة بالفعل!",
[750478947]="واو، لقد نسيت كم كنت عديم الخبرة.",
[751168330]="سفينة الأليانس الحربية! الكل على سطح السفينة!",
[751181850]="أنت بطل ومصدر إلهام للسيندوري، $N، رمز لصمودنا في وجه المأساة والخيانة.",
