[752435681]="تظهر خنافس الجثث من جثة كريبت غارد!",
[752975027]="اذهب بعيدًا، أيًا كنت! تلة ويتش ملكي... ملكي!",
[753144446]="بلورة أتامال ملكي!",
[753262599]="حسنًا، لنخرج من هنا بسرعة بسرعة! حاول مواكبتي. سأحاول الهرب.",
[753267578]="%s يأخذ رقائق الإندوريوم إلى منفاخه.",
[753690566]="ساعدنا، أيها الغريب. <تتحول الآثار إلى غبار. رؤية لثمانية أقزام من حديد الظلام يؤدون طقوسًا تملأ رأسك.>",
[753869104]="لن نسمح لك بمغادرة هذا الوادي!",
[754149768]="هجوم من $N!",
[754293366]="%s يصبح ظلاً من ماضيه، ويتقدم نحو والده.",
[755074796]="لو كانت أمي على قيد الحياة، لأخمدت الحرائق!",
[755544317]="%s يئن.",
[755735742]="سايروخ استيقظ!",
[755747320]="أول أبراج الـهورد سقط! دمروا الثلاثة وسنعجل بتراجعهم!",
[756299790]="لقد نجحنا يا صديقي. تذكر أن تجد تيرينثيس وتخبره أننا بأمان. شكراً مرة أخرى.",
[756407203]="لنخرج من هنا بسرعة",
[756617031]="دعني آخذ محور تعويذة من داخل منزلي هنا، ثم سنبدأ!",
[757086510]="هل أدركت بعد عبثية أفعالك؟",
[757098220]="راين، ريمبلات، ماذا عن قوة الطبيعة والعناصر؟",
[757609758]="سأقوم بتدريبك لمساعدة $N في مهمة مهمة جدًا. بعد ذلك، أعدك بأنك ستكون حرًا في العودة إلى المنزل.",
[757843679]="أرجوكم، أيها البشر - اهربوا! اهربوا قبل أن أفقد السيطرة! النار السوداء تشتعل في قلبي! لا بد أن أطلقها!",
[758125086]="هذه أولى الكثيرات! سنجتاح زولدراك مثل الريح...",
[758483274]="لقد أثبتما جدارتكما أنت ورفيقك في القتال وفي السعي وراء حجر الزاوية.",
[758831875]="دافع عن نفسك، رغم أن ذلك لن يجدي نفعًا!",
[759043768]="الرجاء إدخال 25 قطعة فضية والمحاولة مرة أخرى.",
[759081091]="من أجل... كويل...ثالاس!",
[759456851]="سيكون لديك حفل مناسب في ناقراند، بجانب محارق أمك وأجدادك.",
[760189971]="جيوش الـسكورج تقترب!",
[760323910]="...فقال \"طبعًا ما أشوفش اتنين! أنا عندي عين واحدة فقط!\"",
[760335246]="أنا... أستحق هذا....",
[760688624]="يجب إبقاء إله الدب ضعيفًا حتى يتمكن النبي من إنهاء الطقوس.",
[761168887]="نعم $Gسيدي:سيدتي;.",
[761353852]="المنطق البارد رأى أن عالمنا لا يستحق الإنقاذ. لكن المنطق البارد لا يأخذ في الاعتبار قوة الإرادة الحرة. الأمر متروك لكل منا لإثبات أن هذا عالم يستحق الإنقاذ.",
[761365699]="غزاة... هنا؟! دمرهم، كيلثوزاد! يجب ألا يسقط ناكسماراس!",
[761367209]="سأشقك من المقدمة إلى المؤخرة!",
[761600540]="ضيوف غير مدعوين! هل ظننتم أنكم ستمرون دون أن يلاحظكم أحد في مملكتي؟",
[761627522]="أطلقوا سراحي أيها الجبناء! سأريكم مما يصنع الدوارف!",
[761792412]="داخل هذه الجدران، سيتم اختبارك. ستواجه مهارتك في القتال أخطر الأخطار التي يقدمها نورثرند تحت أنظار قادتك.",
[761976625]="حسنًا، كانت تلك غفوة مريحة. كيف تسير رحلة الصيد هناك؟",
[762001102]="%s يقتلع بقية شجرة الفطر ويذهب بها.",
[762240690]="سوف يأكل مستر فلوبي! يجب أن تساعد مستر فلوبي! يجب عليك فقط!",
[762461292]="استسلم فورًا!",
[762632448]="لنرى إن كانت الأسماك تعض.",
[762888460]="لقد جاء كوراك، أيها الضعفاء! سنو فول ملك لوينتراكس! إرم، كوراك يعني أن المدرج ملك لوينتراكس!",
[763332936]="سأركل رأسك القبيح!",
[764428272]="كما تأمر، يا سيدي!",
[764432131]="المخادع ميج-لورد يوروم يحمي الحلقة الثالثة. سيظهر وحيدًا وأعزل، لكن لا تنخدع بالمظاهر! أوروم ساحر قوي يتحكم بمجموعة من المخلوقات الشبحية. ابحث عنه في الأعلى.",
[764705130]="هي فيزر، هل أخبرتك مرة أنني كنت أركب في القنوات وحاول بعض الجوبلنز ببدلات التقطيع نصب كمين لي؟",
[764884497]="تسعى لإصمائي؟ مثير للشفقة... انتظر... ما هذا الصوت؟",
[765652297]="هل سمعت عن المصارع الجديد لليوتنانت بلاك مور؟ البعض يقول أنه لا يُقهر.",
[765760226]="سنسير معًا، $N.",
[765860803]="لن توقظ الحالم أبدًا!",
[765930341]="هكذا يتم الأمر!",
[767076915]="حسنًا... فعلتها...",
[767330834]="أبعده عني!",
[767818430]="قريبًا، سترتفع عظام غالاكروند من سباتها الأبدي وتحدث الفوضى في هذا العالم!",
[768061754]="%s يتلعثم.",
[768382331]="%s يتوقف للحظة أمام الشجرة ثم يدخل إلى الداخل.",
[768615973]="يمكنني أن أجد طريقي من هنا. صديقي ميكيدا سيكافئك على أعمالك الطيبة.",
[770213282]="كانت هذه مجرد لمحة عما يخبئه المستقبل. من أجل الـهورد!",
[770819898]="%s يتنفس الصعداء.",
[771239677]="تم الهجوم على ورشة حصار الحلقة الغارقة من قبل الأليانس!",
[771256662]="أنا حر! شكراً لكم جميعاً!",
[771320836]="أحسنت، $N! لقد اجتزت المحنة الثانية!",
[771634715]="ولكن بأي ثمن؟ لقد أصبتم جميعاً بالعمى. لقد أصبنا جميعاً بالعمى.",
[771723471]="جمهور الأليانس يهتفون لـ$N.",
[772183400]="هذا ليس من شأنك، هيلكيولار، فأنت لست من كيرين تور ولا نيكرومانسر.",
