[774060035]="$N هو ضابط و$Gسيد:سيدة;.",
[774070459]="القوى العاملة هنا تتجاوز أي شيء يمكنك تخيله!",
[774181123]="سآخذ طاقتك ثم حياتك!",
[774662904]="لقد. فشلت.",
