[775836514]="لو سمحت، أخرجني من هنا!",
[776890035]="وقتي... نفد...",
[777029687]="الإمبراطور ثوريسان لا يريد أن يُزعج! ارجعوا الآن أو واجهوا هلاككم، أيها البشر الضعفاء!",
[777050744]="عمل رائع أيها الجنود! هذا آخرهم!",
[778193423]="أيها الصغير $N، لماذا تستدعيني؟ هل تعمل مع الترولز في هذه الأرض؟ هل جئت لتقتلني وتأخذ قوتي لنفسك؟",
