[778539243]="ماذا تسمي بوميرانج مكسور؟",
[778619160]="طويل جدًا... تخطيط لا ينتهي ولا يكل... لن ينتهي هكذا...",
[779558700]="إنه بطيء من صدأ العصور... كن سريعًا على قدميك ولن يغلبك. لديك تأييد الملك ستورمهارت - لا تخيب.",
[779786118]="بوك، بوك، بوك! هالوين سعيد، $N!",
[779930264]="ثرثرة مثالية. ارجع إلى غاباتك!",
[780867176]="هذا الملصق المطلوب يقول إنهم يعرضون الذهب لهؤلاء المغامرين المزعومين ليذهبوا ويقتلوا الأشياء. أليس هذا ما نفعله؟ لا أعتقد أنني أتقاضى أجرًا كافيًا!",
[781539550]="لن تكون هذه آخر مرة تسمع فيها عني. سأعود لأبصق على جثتك بعد أن تنزل عليك جيوش أوتجارد!",
[781813051]="أستسلم لك.",
[782328263]="لا تقلق كثيرًا. عندما انتهيت من ورديتي، لم نجد أي ذرة ملوثة هنا.",
[782417012]="هذه الأرض تحتاج حقًا إلى التطهير بالنور! دعنا نواصل السير نحو القبر. إنه ليس بعيدًا الآن.",
[782773295]="معركتك مع الريح كانت منذ مئات السنين، ستورمهوف. لقد أضعفتها كثيرًا لدرجة أنها ظلت صامتة كل هذه السنوات.",
[782775005]="زولجين... عندي مفاجأة لك....",
