[783470594]="%s يتدحرج على الأرض من الضحك.",
[783938032]="طريقك ثابت، $N، لأن عزيمة واشتي باون معك.",
[784148634]="المضخات تعمل بشكل رائع.",
[784190033]="قوتك من الجبل. رشاقتك من الرياح!",
[784341291]="ومع ذلك تعتقد أن استعادة آشبرينغر ستغير مجرى المعركة؟ دعني أخبرك بسر صغير أيها القائد: قوة آشبرينغر جاءت من الرجل الذي سيحملها... كنت هناك أيها القائد. شاهدته يحرق جحافل الأنديد بنار مقدسة قبل أن يسحب النصل. للأسف، فهمك للتاريخ... ناقص.",
[784953217]="ابق قريبًا مني، $N. لا أستطيع تحمل أن يصيبك أي أذى.",
[784993482]="أعفو عن حياتك التافهة كمكافأة لهذه الخيانة المسلية. قد يكون فيك بصيص من الإمكانات.",
[785098767]="قتل تافه.",
[785384280]="ما هذا! أمامنا! هل يمكن أن يكون؟ أيها الأبطال، إلى جانبي!",
[785578578]="رأسك سيكون كأسًا ثمينًا، $R.",
[785656305]="ليس... عادلًا...",
[785716066]="قل، بريند، لماذا أبدًا ما ترمو لي بعيونك؟",
[785944047]="لقد دنست مكان راحة أجدادنا. على هذه الجريمة، لا يمكن إلا عقاب واحد. من المناسب أنك أتيت إلى مكان الموتى... لأنك ستنضم إليهم قريبًا.",
[786137405]="هذه المنطقة ستدمر نفسها بعد عشر دقائق.",
[786259654]="لا تجرؤ على التحدث عن والدي، أيها الوحش. لقد كان ضعف الرجل الذي ستكون عليه أبدًا.",
[786506221]="أنتم يا رفاق، لا تترددوا في القفز في أي وقت.",
[786675842]="جئت بأخبار عن صراعنا مع الأنديد المارقين.",
[787070631]="سأرحمك، سارثاريون، هذه المرة فقط.",
[787084513]="شكرًا لمساعدتي. أعرف طريقي للعودة من هنا.",
[787432433]="مذهل! كيف تمكنت من السيطرة الدائمة؟",
[787565599]="لا فائدة... تحتاج إلى مزيد من العمل أولاً.",
[787785224]="سأحميك!",
[788050287]="سحق!",
[788156605]="تعال، يا سيد السحر، واستعد رفيقك الثمين...",
[788243730]="نعم! تغذَّ، يا عزيزي! أنت ملكي الآن!",
[788425516]="لقد فعلناها! ربحنا!",
[788530584]="أيها الحارس! لقد نفد رمل الزمن من أجلك.",
[788540493]="لا تؤذي مانح الحياة!",
[789157448]="اختنق بأنفاسك الأخيرة!",
[789319131]="رم مجاني؟ لماذا... هذا هو المفضل لدي!",
[789357612]="اغفر لي.",
[789422297]="كفى! هذا ينتهي الآن!",
[789804107]="أخلِ المنطقة!",
[789809516]="لست قوياً جداً الآن!!",
[790080703]="أبوك يدفع وارمول ويمكن ما نأكلك.",
[790144953]="أمبرسيد!",
[790344638]="جمجمتك ستزين مذابح طقوسنا!",
[790543893]="فهذا النوم يقول لتاورن إنه ذهب إلى مولتن كور.",
[790561662]="حاجز المانا الخاص بـ%s يتلألأ ويتلاشى!",
[790887173]="دخيل! لقد أُرسلت لتدميرنا!",
[790916281]="أنا معجب حقاً، جيرارد. ظننتك كلاماً فقط، لكني أرى أنني كنت مخطئاً.",
[791322442]="ماذا؟ هذه القوة...؟ كل الألم اختفى! أنت... يجب أن تنضم إلي في العناق الأبدي للموت!",
[791356153]="ماذا سنفعل بهم يا سيد؟ لم يعودوا ذوي فائدة لنا.",
[791792841]="هذه صخرة لامعة، سأضعها في دلوي. حسنًا، أحتاج فقط لبضع قطع أخرى...",
[792265618]="اخضعوا أيها البشر! عصر الظلام قد حان.",
[792345486]="واستعداداتك أنت؟ هل سيكون لسيد الصقيع طريق إلى البوابة؟",
[792644820]="جيدة كما أخبرتك أنها ستكون، أليس كذلك؟",
[793028455]="وكذلك تعلم أنها حقيقة!",
[793706305]="كم أشتاق لتلك الأيام التي لا تنتهي في لوردايرون...",
[793787602]="حسنًا. سأقضي على هذه المخلوقات. إنها مجرد إزعاج. استعد للموت!",
[793856289]="لقد فشلت... السلام مستحيل.",
[794030955]="لنهرب من هنا بحق الجحيم.",
[794541785]="حان وقت لعبة جديدة! ألعابي القديمة ستقاتل ألعابي الجديدة!",
[794974966]="تم الهجوم على ورشة حصار إيست سبارك من قبل الـهورد!",
[795021718]="دعني أعيش! سأفعل ما تقوله!",
[795210858]="لقد هزمتم مجلس الحديد وفتحتم الأركيفوم! أحسنتم يا رفاق!",
[795256657]="فظيع! حسنًا، ربما يحتاج فقط إلى بعض التنظيف؟",
[795258583]="إلون معنا! فلنسرع بالخروج من هذه القلعة الشريرة.",
[795533862]="أنا مجرد واحد من... عدد لا نهائي.",
[795557703]="سيُجبر الكفار على الرد. الأوركس، رجال الثور...",
[795635007]="هل يمكنني الحصول على تعزيز؟ أنا أموت هنا.",
[795936725]="لنهرب من هنا بسرعة.",
[796308436]="لما تخلص شغلك، نروح النزل. أنا بدفع جولة ونتذكر الأيام الخوالي.",
[796496931]="$N! استعد للقاء حتفك!",
[796971327]="آه، سمعت بهذا.",
[797039786]="بكل احترام، سيدتي، أنت لم تحاربي الـسكورج مثلي. ليدي عينني لمساعدتك في هزيمة دار'خان بسبب ذلك، وسيكون من الأفضل لك أن تأخذي بكلامي.",
[797539796]="قوة الهالة بدأت تتلاشى!",
[797653812]="لقد مضى وقت طويل، بيثور، يا صديقي.",
[797708772]="كورفاكس، ماذا يمكنك أن تخبرني عن هذا السارونايت؟",
[797751641]="هذا جنون! طفح بي الكيل! كفى!",
[798237662]="لا يمكنك الهروب من غضب السيد...",
[798245871]="عيّاط! عيّاط!",
[798548194]="اخترت الوقت الغلط تهزني اليوم يا صاح! استعد للخيبة.",
[799677393]="أهلاً بكم في صنويل. رغم الأجواء المعتدلة والمناظر الخلابة، لستم في إجازة أيها السيدات والسادة!",
[800005669]="لقد حاربت بشدة لاقتحام عالم الحاصد.",
[800459116]="هل تحمل كلمة من الخالق؟",
[801180343]="أخيراً، قربان يستحق!",
[802795794]="%s يلتفت إلى ادفايزر فالوين ويغمز لها بطريقة شهوانية.",
[802951442]="خيتريكس الـ دارك ماستر هُزم على يد $N وعصابة $Gخاصته:خاصتها; من الرفاق. ليُطسوف التحدي التالي!",
[803531453]="أنا آسف. سأعمل بجد أكثر.",
[803784685]="سأطهركم من هذا المكان!",
[803807134]="شاهد أدوات الخلق!",
[803874965]="أكره هذا الجزء من عملي. يا دسكوود، كن لطيفًا مع أنطونيو المسكين.",
[804200131]="أين خوذتي اللعينة؟ حسنًا، على الأقل تركوا سيفي هنا. أغبياء.",
[804371828]="أريد أن أكون على تلك السفينة الأخيرة! لا تتركونا!",
[804447011]="أسرع بهذا الفأس، أنت! أريده حادًا كفاية ليقطع الريح!",
[804531717]="فكر، $N. فكر بالماضي. حاول أن تتذكر جبال دن موروق المغطاة بالثلوج! لقد ولدت هناك، $Gفتى:فتاة;. تذكر روعة الحياة، $N! لقد كنت بطلًا للدوارف يومًا! هذا ليس أنت!",
[804537790]="لا أعرف مدى خططهم، أيها الأبطال، لكني أعرف هذا: لا يمكن السماح لهم بالنجاح!",
[805003688]="روحك ستبقى هنا إلى الأبد!",
[805270385]="هل تستمتعون؟",
[805809271]="ما الأمر، يا سيدي؟",
[805907242]="لقد غبت طويلاً. غيابي كلفنا حياة بعض أعظم أبطالنا. تراش مثلك وهذه الساحرة الشريرة تُركتم أحرارًا — دون رقابة.",
[806414284]="الوظيفة: شرطة سرية، محققون",
[806712176]="تُسمع أصوات زئير وهدير مروعة قادمة من كوخ ذلك الناسك العجوز!",
[806717377]="آه! لا مزيد من الأذى!",
[806792846]="وبدأ شعري يتشكل بسبب الخوذة. هذه كارثة!",
[806845329]="يبدو أن المرهم غير فعال. يا للأسف...",
[807033989]="لقد قلت إن بروق يمكنه البقاء هنا! لقد وعدت بروق أنك ستساعد في استعادة تل عشيرة ستونمول!",
[807241431]="في زمن ما قبل الزمن، عندما كان العالم لا يزال في مهده، دارت معركة بين تايتن وكائن من الشر والقوة الخياليين على هذه الأرض ذاتها. النبوءة غير واضحة حول ما إذا كان التايتن قد هُزم في هذه المعركة لكنها توضح أن تايتنًا سقط. كما سقط إله قديم — أو هكذا كان يُعتقد.",
[807663843]="لهبي مات، لم يبقَ شرار. سأرسلك بنفسي، إلى الظلام القاحل.",
[807776294]="أنوبريكان يبدأ في إطلاق سرب من الحشرات!",
[807800138]="فروستمور تتغذى على روح حليفك الساقط!",
[807946890]="لا نور. فقط ظلام!",
[808525275]="لست مهتمًا بالأعذار. ربما أعطوك اسمًا؟",
[808677772]="أنا تائه...",
[808775443]="المزيد من الأرواح... نعم، المزيد... سيكون من الصعب عليك التوقف، أيها الفاني.",
[809217693]="أعيدك من حيث أتيت!",
[809324693]="أخيرًا! ناراليكس يستيقظ من الكابوس.",
[809694928]="من الأفضل أن نفترق الآن، في حال أرسلوا المزيد وراءنا. آمل أن يصل أحدنا إلى قاروش. وداعًا أيها الغريب.",
[809723577]="كل محارب يسقط هو واحد إضافي لجيشنا العظيم. لا انتصار علينا.",
[810110935]="طائر $R قادم! أسقطوا $Gإياه:إياها;!",
[810584302]="استيقظ، يميرون، لقد حان وقت حكمك المستمر.",
[810602827]="الكولتيست يكاد يختنق.",
[810826897]="حتى الأقوياء... يمكن أن يسقطوا.",
[811140936]="أتذكر الوقت الذي حاولت فيه حفر تلك الحفرة في رأسك؟",
[811803928]="عد، $N. إذا بقيت خارج جسدك لفترة طويلة، فإنك تخاطر بعدم القدرة على العودة. لدينا الكثير لنناقشه.",
[812201191]="اللعنة عليك، هاليندور! لقد قدتنا إلى هلاكنا!",
[812425732]="لم يتبق لديك الكثير من الوقت. الـليتش كينغ يرى ما يراه السيف. سيأتي قريبًا.",
[812569987]="انظر إلى قتالك؛ لا عجب أنني تحولت إلى الشرب.",
[813155882]="شكرًا لك مرة أخرى على مساعدتك. أتمنى أن تكون الريح دائمًا في ظهرك خلال رحلاتك.",
[814685319]="أبعد نظرك عن بئر القمر، أيها المنفي. القوة التي بداخله ليست لك.",
[815217602]="الخزان يمتلئ بشكل جيد.",
[815247415]="أولوي غاغ إرهونغ واش.",
[815805386]="%s يقطف العشبة من الأرض.",
[816439317]="لا يمكنكم إيقافنا جميعًا!",
[817999533]="أترككم الآن أيها البشر. أحياءً ومع هذه الحلي. مالتريك! قدم لهم الحلي!",
[818091669]="لدي الكثير لأفكر فيه.",
[818098646]="اغفر لي وقاحتي!",
[818617570]="ساكرولاش يوجه شادو نوفا نحو $N.",
[818844562]="%s يبدأ العمل...",
[818862204]="هذا... لم ينته بعد!",
[818866773]="إذا كنت ستتبعني، إذن.",
[819054420]="سأقطع اللحم من عظامك!",
[819297291]="غيرت رأيي، اذهب وأحضر ذاك بدلاً من ذلك!",
[819493185]="إذا تجرأت حتى على البصق دون إذني، هذا المكان سيُغلق. بالقوة.",
[819607591]="حسنًا، سأذهب الآن. اعتنِ بنفسك، هارلان.",
[819737246]="لا! ماذا فعلت؟",
[819811064]="هذا أفضل مكافأة يمكننا تقديمها. نأمل أن يقبل أحدهم المهمة.",
[819859565]="عندما تقتل سيد الحفرة، ابصق على جثته من أجلي، هل تفعل؟",
[820037008]="لا تظهر متفاجئًا جدًا. صديقك الشامان لديه عيون حادة، أو بالأحرى، ضفادع حادة.",
[820332877]="عندما وصل إلى اللاجئين عند سور غريمان، شعر أنه من واجبه مساعدتهم، وأرسل امرأته إلى هيلزبراد.",
[820469365]="لقد تعودت على تنظيف فوضاك.",
[820617920]="لماذا أستدعيك؟",
[820930189]="$Gملك:ملكة; يعتقد... هناك حقًا... أوغريلا؟",
[821119968]="تم اجتياح آيل أوف كيلداناس من قبل قوات الأمير كايلثاس سنسترايدر. الاستخبارات قالت إنه ميت. الاستخبارات كانت مخطئة.",
[821138473]="تروك؟ لماذا تركض كإنسان خائف؟",
[821307992]="أرجوك، لا! ارحمني!",
[821678718]="لن... أُتجاهل!",
[821929175]="أضمن أنه بدون $N، لكان هذا الهجوم فشلًا كاملًا.",
[822031994]="لدي استخدام لك...",
[822407514]="بأعماق نازجاتار!",
[822623301]="باختصار، سيمر وقت طويل جدًا حتى نكون مستعدين للإطلاق. ربما عليك العودة إلى عائلتك.",
[823800437]="أحسنت! كن مستعدًا لأي شيء!",
[823900700]="المخلوق البشع اجتاح معسكر نايت ووتش! بسرعة، يجب أن نعترضه قبل أن يصل إلى البلدة!",
[823902678]="وقت المرح!",
[823988531]="تريد إظهار فخرك دون التخبط على أحد تلك الوحوش؟ أي مدينة تشجعها، لدي ما تحتاجه!",
[824258045]="أين منقذك؟ كم يمكنك الصمود أمام هجماتي؟",
[824861559]="أديت جيدًا. بالتأكيد مفاجأة لتروب... أبلغ جاي.",
[825298185]="لا شيء يعض...",
[825512167]="أنت تساعد رينسبيكر! رأيتك تساعد رينسبيكر! أيها الخائن!",
[825687000]="أعطيني دميتي!!",
[826133949]="لابد أن نعمل بسرعة أكبر.",
[826147844]="لنتقدم بخطى سريعة.",
[826430621]="تم تحييد دفعة الطاعون!",
[827156890]="حياة من اللاحياة... موت لكم.",
[827751279]="مرحباً يا صديق! أهلاً بك في أرض مهرجان الجعة!",
[828378415]="النجدة! أنا تحت الهجوم!",
[828383606]="الأسلاف تراقبك أيها الطيب...",
[828893398]="يقع على عاتقنا إعادة كويلديلار لصالح آل صانعي الشمس.",
[829061860]="أتظن أنك تستطيع استدعاءنا؟ نحن من يستدعي، وليس أنت! سنضربك جيداً على هذا ونمتص النخاع من عظامك!",
[829544098]="تحدث مع جوزيف ريدباث في وسط دارو شاير.",
[829725425]="هيا، افتحها. أعتقد أنها ستعجبك.",
[830026353]="%s يخرج من الظلام، مستدعىً بواسطة جهاز العرافة!",
[830337331]="أنت أيضًا ستخدم!",
[830460238]="ابتعدوا أيها الحشرات!",
[831178442]="أضف السائل الآن!!",
[831651724]="اهوني سيعاود الظهور قريبًا.",
[832163234]="مرة أخرى، سنُري هذا البيرنينغ ليجيون أن عالمنا ليس ملكًا لهم!",
[832175374]="اصطفوا واسحقوا هؤلاء الحمقى!",
[832189687]="سنصمد حتى يأتي الدعم. طالما أن رجالًا ذوي قلوب شجاعة يدافعون عن الأسوار والعرش، ستصمد ستورمويند.",
[832964472]="اغتسل بقوة الوارتشيف! اشرب من جبروته! حارب لمجد الـهورد!",
[833078687]="لقد كنت حليفًا ثابتًا للإيرذن.",
[833487718]="ثروم-كا، أيها البطل!",
[833694136]="لكن... هناك توازن في كل شيء، حتى الموت. أنا فقط أكره فكرة أن مثل هذا الدمار والظلام قد يكون ضروريًا.",
[834213919]="أجل، ستبقى معنا الآن...",
[834245139]="ما هذا بحق نيذر؟!",
[834565032]="جيد... المزيد من اللحم للحصاد...",
[834771339]="بسرعة، اصعد! لا يجب أن نبقى هنا! لا نعلم متى سينهار هذا الجبل بأكمله.",
[835116930]="احموا القناة! أوقفوا المتسللين!",
[835222942]="ليس لي مثيل!",
[835402701]="من هؤلاء ينسحب النور، حتى لا يبقى إلا الظلام.",
[835747293]="%s يشم ويجد الأثر.",
[836393216]="الطاعون لم يكن مميتًا تمامًا... لكن التقارير عن الآثار الضارة تشمل الغثيان، فقدان التوازن، وألم شديد في المعدة.",
[836521464]="هذا \"لوكين\" يبدو شخصية خبيثة. أنا سعيد أننا لم نعد نقلق بشأن أمثاله. إذًا... إذا فهمت كلامك بشكل صحيح، فقد استيقظ الأرثن الأصليون في النهاية من هذا السبات، وبحلول ذلك الوقت كان عدم الاستقرار أو ما شابه قد حوّلهم إلى دوارف حقيقيين. أو على الأقل... أسلاف دوارف.",
[836816528]="هل... هل يمكن أن يكون قد انتهى؟ هل تم تدميره؟",
[836856052]="مت أيها الضعيف!",
[837308246]="%s يصل.",
[837379828]="%s يفقد اتصاله!",
[837606808]="أنا حائر. ماذا يمكن لرجل بسيط أن يفعل في وجه الكارثة؟",
[837894357]="%s ينجذب إلى مغناطيس الشبح...",
[838049931]="$N، الترجمة انتهت!",
[839058746]="نزع الطاقة من أعدائنا، سواء كانوا يقاتلون أو ساقطين، يسمح لنا بالصمود حيث يسقط الأضعف منهكين.",
[839085341]="آه! يمكننا أن نقول له إن هاغاش تعثر بها وأطلقها بالخطأ!",
[839318510]="نعم يا سيدي.",
[839791532]="فكر، $N. فكر بالماضي. حاول أن تتذكر جبال أرجوس الشامخة، حيث وُلدت. تذكر روعة الحياة، $Gأخي:أختي;. لقد كنت بطلاً من الـدرايناي! هذا ليس أنت.",
[839894955]="ماروين، أنهِهم...",
[840050189]="استدعاء الدم ينتقل إلى برينس فالانار!",
[840277361]="أنت لست ضيفًا.",
[840667378]="شكرًا لك على ذلك... كان من المتواضع أن أُخدم بهذه الطريقة.",
[840939404]="لا... لا يمكن أن يكون هذا صحيحًا...",
[840950306]="%s ينظر إليك باستفسار. ربما يجب أن تتفقده؟",
[841156984]="لن تصمد أمام إبداعاتي!",
[841234156]="لن تهرب منا بهذه السهولة!",
[841534033]="اذهب إلى العدم!",
[841600668]="يكفي ثرثرة! وصل أبطالنا - ادعموهم بينما نشق طريقنا عبر القاعة!",
[841619037]="لا تفعل هذا، غولدان! العناصر لن تسامحنا أبدًا!",
[842062227]="ها! الخلود الأبدي لأجاماند الملعونين!",
[842493913]="أنت تحمل سيف والدي، $N. جنودي تحت سيطرتك، يا $Gلورد:سيدتي;. خذهم... قُدهم... يجب تطهير النجس. يجب تطهيرهم من دنسهم.",
[842571720]="الشحنات المتفجرة ستنفجر بعد 4 ثوانٍ...",
[842628958]="هذا سيبطئ انتشار العدوى قليلاً.",
[843507075]="أبقِ هذه المضخات تعمل.",
[843619722]="أتساءل كم من التعزيزات ستتعرض للإصابة قبل أن يسمحوا لنا بقطع هذه الأشجار الغبية. إنها تكلفنا ثروة من الخفافيش. ربما سأركب حزامًا أو اثنين...",
[844402017]="كما تشاء، يا سيدي.",
[844417275]="الآن نحن نحرز تقدمًا!",
[844671792]="سأوجه قواي إلى الكرات! كن مستعدًا!",
[844782548]="%s يبوق بالموافقة!",
[845194088]="أنا حر! سأطلب من روح النار أن تعود إلينا حتى يتحلى شعبي بالشجاعة لمحاربة أسيادهم! أشكرك، $R.",
[845706001]="قريبًا، أيها الفاني، سيكون لديك أيضًا نصل كسجن.",
[845796571]="هل فعلت شيئًا سيئًا؟ أنا آسف...",
[845847047]="آه، لقد بدأت العجلات بالدوران.",
[845968520]="4 8 15 16 23 42",
[846086398]="سألبس جلدك كجاكيت تدخين! السيجار؟ ستضطر إلى انتزاعه من يديّ الميتتين الباردتين... إيه... راوور!!!!",
[846132693]="الـدراكاري يدمرون أراضيهم! سيخسرونها... قريبًا، مون.",
[846477331]="جاهز لنقل القتال إلى زالازان.",
[846542376]="سأتغذى... على روحك.",
[846554509]="لا تنسى التضحيات اللي صارت اليوم، يا نايت إلف. كلنا عانينا كثيرًا على أيدي هالوحوش.",
[846738557]="%s مسلح.",
[847078234]="جناح خفاش ذابل!",
[847289869]="%s يتبع $N بطاعة.",
[847348831]="كايلثاس سنسترايدر انهزم على يد $N وحلفاء $Gخاصته:خاصتها;.",
[848254058]="هذه الفظائع الأنديد سوف تُدمر!",
[849135612]="كفى! لقد سئمت من هذه الألعاب!",
[849980971]="ألعاب جديدة؟ لي؟",
[850097500]="لقد تم اختياري!",
[850771934]="ما هذا؟ أعرفك من حين قتلت أكالي. لا بد أنك هذا $N الذي يخشاه الجميع.",
[851004580]="أنت لا شيء سوى تابع! لن أنتظر لحظة أطول! اصطحبني إلى غوراموش فورًا!",
[851050292]="مهرجان القمر هو أفضل وقت في السنة للألعاب النارية!",
[851624069]="أيها المتسللون، انتصاركم سيكون قصيرًا. أنا القائد فاروس كلاودسترايدر. تتحكم تنانيني في السماء وتحمي هذا الموصل. سأحرص شخصيًا على ألا تقع الأوكولس في أيديكم!",
[851841909]="آههه-يا-يا-يا!!!",
[852110252]="%s يحك رأسه.",
[852148324]="لقد أصبحت... الموت!",
[852192124]="هاد الترول سوف يقف لـ...",
[852651942]="هي، هاربينجر، كيف شغلك البحثي؟ يمكن يكون فيه وافل أيرون ألترا-كينيتيك لك إذا كنت سريع بالنتايج!",
[852826890]="أنا... أعتقد أني كسرته.",
[853220989]="أنتم أتباع سنريفر كلكم نفس الشيء.",
[853238134]="مجمدة ومدمّرة. هذا كل ما يصلح له جسدك اللحمي.",
[853816813]="سيكون عليك أن تشق طريقك عبر هذا المستنقع بنفسك.",
[853936207]="هذه الرسوم تحكي قصة. هذا الشكل في البداية، يشبه تقريبًا أحد المخلوقات التي واجهناها في أزور ووتش...",
[854045690]="آآآآآآه! أرجوك... نحن نعلم... أن لديك... جاسوسًا... متنكرًا... كواحد منا! هذا... هذا كل ما أعرفه. أرجوك... ارحم... توقف!",
[854288729]="بالطبع، عزيزي.",
[854811544]="الآن ستموت!",
[854989342]="ابقَ هنا!",
[855152848]="%s يغضب عندما يتحطم درعه.",
[855604444]="الأمور على وشك أن تزداد سوءًا. تعال، تذوق القوة التي منحني إياها الـليتش كينغ!",
[855683815]="فجأة، شيطان طوله 300 قدم أو شيء من هذا القبيل يأتي ويبدأ بتسلق الشجرة...",
[856084516]="لن تهزمونا أبدًا!",
[856275144]="آه... لا! نحن نعلم أنك كنت تسرق دروعنا وأسلحتنا وخيولنا!",
[856282701]="قتال رائع! اليوم لنا، لكن الحرب مستمرة!",
[856594534]="%s يبدأ بالتحول...",
[856934538]="متسللون اخترقوا المصنع! فعّل بروتوكول الدفاع الطارئ فورًا!",
[857302852]="شكرًا لك! شكرًا لك، $Gبريست:برايستس;. الآن أستطيع مواجهة هؤلاء المورلوكس والنور في جانبي!",
[857655672]="كان ذلك ابن ساورفانغ - الـهورد كومندر عند بوابة الغضب. نهاية مأساوية حقًا...",
[858422840]="لا تنم بعد الآن يا حبيبي. بقوة الـليتش كينغ خلفك، سيرتعد العالم.",
[858708316]="فيضان الأعماق، ليأخذك!",
[858788018]="عامل مزرعة، يا سيدي.",
[858835709]="المعلم تفقد مملكته ووجدها... ناقصة. كان حكمه سريعًا وبدون رحمة: الموت للجميع!",
[859289228]="ورشة حصار المعبد المكسور تم الاستيلاء عليها من قبل الـهورد!",
[859431880]="آه... هذا ما كنت أحتاجه بالضبط.",
[859561196]="شكرًا لك، $N. سأتذكرك دائمًا. يمكنك العثور على صندوقي في مخيمي، شمال ستونارد.",
[859623256]="من يجرؤ على قتل أحد قادة كرغاث؟ ستدفع ثمن هذا... بالجسد!",
[860239210]="آه، اشعروا بالسحر يتسرب إلى الكهف، يا أطفال الصغار... موهاهاها.",
[860250192]="ماذا حدث هنا؟ جثث في كل مكان... الرائحة... لا تُحتمل...",
[860939979]="ضباب. كثير من الضباب. هل يبدو ضبابيًا لك؟ ربما ليس كثيرًا.",
[861329752]="فلتبدأ الحصار!",
[861467044]="إلى أين تذهب بهذا؟",
[861797553]="هجوم الـفريكول!",
[862021428]="آه. لقد أخبروني أن تلك البلورات ستعمل بشكل صحيح!",
[862216883]="تعالوا، أيها الصغار. واجهوني!",
[862548303]="مسكين كريتيوس. لقد كان حارسًا جيدًا... أنا سعيد لأنه على الأقل تمكن من إكمال مهمته، أتخيل أن هذا كل ما يهمه حقًا.",
[862701976]="مرحبًا، أصدقائي. من الجيد رؤيتكم مرة أخرى. ما زلتم تحافظون على حدودنا خالية كما أرى. أنطونيو يقدر عملكم الجاد.",
[863121703]="الرمل يعلق في أصابع قدمي باستمرار.",
[863339384]="%s يترنح للخلف بينما يستقر السهم عميقًا في صدره.",
[863747594]="الـسكورج علينا! اهربوا! اهربوا بحياتكم!",
[863899505]="وداعًا! لقد كنت أفضل صديق لنيمو على الإطلاق!",
[863916833]="ستكون قربانًا مناسبًا!",
[863999164]="سألتهم، وأدمر، وأخرب، وأدمر! استسلم الآن لغضب البحر الهادر!",
[864029735]="كل شيء سيكون على ما يرام يا أطفال. النور سيهتم بذلك!",
[864139270]="أتمنى أن ينجح هذا!",
[864146871]="%s يأخذ رشفة كبيرة من الجعة.",
[864910169]="احصد الزوبعة!",
[865231308]="مرحبًا جوبجوب. لقد اشتقت إليك!",
[865522348]="لا أحد مرحب به هنا سوى تنانين الدرع الزرقاء. ربما هذا عمل ألكسترازا؟ حسنًا، إذن لقد أرسلتكم إلى موتكم!",
[865592658]="لن تصل إلى حافة الغابة، فوردرينغ.",
[866373030]="أليس هذا رائعًا، أيها الأطفال؟ كل من يدخل المدينة يجب أن يمشي تحت أعين أعظم أبطال أراضينا.",
[866430872]="أتذكر جيدًا لسعة الهزيمة في نهاية الحرب الثالثة. لقد انتظرت طويلًا جدًا لانتقامي. الآن ظل الـليجيون يخيم على هذا العالم. إنها مجرد مسألة وقت حتى يُلغى كل خلقكم الفاشل...",
[867432360]="شادرون! تعال إلي! كل شيء في خطر!",
[867581383]="هولكينق جورمونجار يتردد للحظة، ويفتح فمه واسعًا.",
[867594639]="لن نذهب بهدوء إلى الليل! لن نختفي دون قتال!",
[867688646]="جيد. إذن لقد حظيت باهتمامك، غودفري؟",
[868634628]="ها أنا ذا، في برج حجري خشن يقبع على أرض مستنقعية موحلة بينما تطير أسراب البعوض دون عائق عبر الأبواب المفتوحة، وأقف بين أشكال خضراء محدبة ذات نظافة مشكوك فيها وأخلاق خشنة. لم أكن أكثر سعادة من أي وقت مضى.",
[868738659]="يجب أن تنطق بالكلمات...",
[869206788]="انظر إليه، جون. إنه رائع!",
[869208849]="فجروها يا رفاق. يبدو أن أمامنا معركة.",
[870051187]="عناق حلو، حلو... خذني...",
[870450177]="عدم الامتثال سيؤدي إلى إجراء هجومي.",
[870587729]="%s تشحب بشدة حتى يختفي الدم من وجهها.",
[870885030]="... لكن لا تأتوا به قطرة واحدة!",
[871334414]="اشتقت لك أيضًا يا عزيزي. وأنا أخيرًا في البيت...",
[872428518]="الدراغونماو يجب أن يتوقفوا...",
[873456451]="أيتها الأم، اهربي! إنهم قساة...",
[873692969]="توقف! لا تذهب أبعد من ذلك أيها الفاني. أنت غير مستعد لمواجهة قوى إنفينيت دراغون فلايت. تعال، دعني أساعدك.",
[874148200]="كم عدد الجنود الذين يجب أن يموتوا قبل أن نبدأ بالانتباه هناك؟",
[874154422]="استمتع بالرحلة! إنها رحلة بلا عودة!",
[874338535]="لا يمكننا أن نسمح لك بالعودة إلى رفاقك ولا يمكننا أخذك معنا...",
[874519266]="صندوق؟ لم أرسل لك صندوقًا يا جوفان. أليس لديك أمور أكثر أهمية لتهتم بها؟ اذهب وانظر إليهم!",
[874684371]="برج آيسبلود دُمر بواسطة الأليانس!",
[874838092]="أعلم، أعلم. عد إلى الدلو...",
[874977331]="أرغ... لا!!",
[875080440]="أنت... تموت الآن!!",
[875649726]="الآن اصمت ولاحظ أين أنت، لئلا أُخبر اللورد فوردرينغ وفرسانه أنك لم تعد هنا بعلاقات ودية. أنا متأكد من أنه سيسعد كثيرًا برؤية 'تكفيرك'.",
[875652391]="انتظر! توقف! لا تقتلني، أرجوك! سأخبرك بكل شيء!",
[875760657]="لقد انتزعنا السيطرة على الأوكيولس من قوى ماليقوس. أنت لا تخف أبدًا أيها الصغير. أجنحتي تشتاق للسماء المفتوحة.",
[876673762]="يسعدني رؤيتك أيها البطل.",
[876747980]="لقد أفسدت هذه الدفعة! لماذا يجب أن أعمل معك أيها الـغانارغ التافه.",
[876974968]="سيدي، عملاؤنا يشتكون من وجود الكثير من ديثويد في مخدراتنا.",
[877001171]="كيلجايدن سوف... ينتصر!",
[877070460]="اقتلني... اقتلني الآن!",
[877365628]="%s يبدأ في عمل نسخة من نفسه!",
[877636250]="لدي قاعدة واحدة فقط. الكل يقاتل. لا أحد ينسحب.",
[877770120]="لقد قدمت قتالاً رهيبًا أيها الجديد. قتالاً رهيبًا...",
[877842389]="لن أسمح لك بقتل المزيد من نوعي! استعد للموت!",
[878002138]="أيها المخترع ضعيف العقل، هل تظن حقًا أن اختراعك التافه يستطيع إيقافي؟",
[878395394]="تريجر من أجل لافو! تريجر من أجل الضريح!",
[878923539]="عندما تقفز إلى نيرجيلد، يعود لحم البناء المتعفن إلى الحياة.",
[878976722]="اخرج إلى نقطة جانيرو. أنا في انتظارك يا سموتس...",
[879138935]="مذهل! أعتقد أنني وجدته، $N!",
[879233641]="قوة النور لا تعرف حدودًا يا سورفانغ. روحه تحت ضغط كبير، لكنه حي - في الوقت الحالي.",
[879637093]="دع الظلام يلتهمك!",
[879796841]="الوظيفة: بريستس، قساوسة عسكريون",
[880377497]="جموع الذئاب في الشرق، ومن كان يعيش في بستان مالدين قد رحل.",
[880536465]="لا مقبرة هنا لتلعب ألعابك الخبيثة على كوراك! مُت!",
[880721088]="بني نحفرك ونأكلك!",
[881129612]="لقد كذبت على رجالك وخنت المرتزقة الذين قاتلوا من أجلك. ما الذي يحدث لك، آرثاس؟ هل الانتقام هو كل ما يهمك؟",
[881700369]="لا تخف. سوف تطهر النايت ووتش هذه الأرض من هذا الدنس القذر قريبًا.",
[882033085]="كفى! انتهى وقت اللعب!",
[882252703]="دخلاء! أوقفوهم حتى أتمكن من إطلاق كلاب الحرب!",
[882294813]="أنت! لا كلمة واحدة لـغريك عن هذا! هل تسمعني؟",
[882992340]="يوم جيد لكما. أريد التحدث إلى اللورد ليسكوفار.",
[883552413]="...وداعًا يا أخي.",
[883694148]="لا تسرق البضائع!",
[883719371]="هذا ليس صحيحًا على الإطلاق، $N. في الحكاية التي رواها لي ويند تيمر باراه، كان ستورمهوف بطلاً، ليس شريرًا.",
[883808725]="فاشلون! ضعفاء!",
[884020763]="كما ينبغي أن يكون!",
[884153722]="آرر، يا قراصنتي! عندي بعض تريجر إضافية سأوزعها في ساحة قوروباشي! كل ما عليك فعله لجمعها هو فتح الصندوق الذي أتركه على أرض الساحة!",
[884157881]="بطل وينتراكس ترولز قد تحداك، $N! أتمنى أنك مستعد!",
[884476595]="اسألني كيف تحصل على مشروب مجاني في بلو ريكلوز!",
[884738043]="كان في السابق لا يمكنك الوثوق بجوبلن...",
[885451945]="هذا عمل شاق. أشعر أني بحاجة لعطلة. أنت هناك، اجتهد أكثر!",
[885534439]="أتساءل إن كان يمكنك حقًا سماع المحيط في هذه الأشياء.",
[885747740]="تك توك، تيك توك...",
[885989415]="الكون سيعاد تشكيله.",
[886242458]="انظروا من هنا. إنه $N، أفضل مقاتل لدينا.",
[886245815]="المنطاد إلى فينجينس لاندينغ وصل للتو! الكل على متن هاولينق فيورد!",
[887221015]="لا أحد يسرق أسرار الصنّاع!",
[887663584]="لذا عندما تشعر بهذا الإحساس بالوخز في أسفل عمودك الفقري وكنت على وشك أن تبلل سروالك، تقبله. دعه يغضبك. هذا الخوف هو الشيء الوحيد الذي سيبقيك على قيد الحياة.",
[888352329]="آمل أن ترى قيمة هذه الأحداث مع الوقت، قاروش. لا يمكننا الفوز ضد الـسكورج إذا استمررنا في الحرب ضد بعضنا البعض.",
[888698993]="لقد خيبت أملي، أكاماً. أردت أن أستجوب الدودة الخائنة بنفسي! بدأت أشك في ولائك، أيها المكسور.",
[888800408]="لا أوافق على لجوئك للكيمياء لحل بعض المشاكل، لكنني أوافق على النتائج. عمل جيد جداً.",
[888954809]="روح أخرى لإشباع المضيف.",
[889096928]="كم أنا أخرق للغاية.",
[889310363]="لاااا!!! سأخبرك! سأخبرك بكل شيء!",
[889395989]="%s ينحني.",
[889556516]="احرقهم حتى العظم!",
[889666842]="أنا لا أوافق بشدة. دار'خان لن يحصل على تعزيزات لأنه سيكون محاصرًا. ديثولم لديها مدخل ومخرج واحد فقط. خائنك كان أحمقًا ليحشر نفسه هناك، وأنا أنوي استغلال هذا الضعف!",
[889798061]="ماذا؟ شيء صغير وضعيف كهذا يستدعيني؟ هذا لن يمر دون عقاب!",
[889845547]="هل أنت متفاجئ حقًا؟ هل من الصعب تصديق أن قوة إله قديم يمكنها الوصول حتى داخل الحلم؟ إنها حقيقة - إيرانيكوس، تايرانت أوف الـ دريم، يشن حربًا ضدنا جميعًا. الـنايتماير يتبعه في درب الدمار.",
[889847159]="لا، ليست وحشية! ضمير. تجاوزات شعبنا ستدمرنا، وكل ما كافحنا لبنائه.",
[889941690]="أشعر بدوار قليل... أوووف...",
[890227186]="دوامة المحصودين تناديك!",
[890525336]="لا... يجب ألا... أتردد!",
[891002131]="من أجل زيري! من أجل الشاتار!",
[891142708]="أفنِهم.",
[891214661]="شكرًا لمساعدتي في العودة إلى المخيم. اذهب وأخبر والتر أنني بأمان الآن!",
[891267105]="%s ينظر حوله في مهبط كراسوس، يشعر بالملل.",
[891464654]="كويلديلار ليس محط تقدير السيندوري وحدهم. بل له مكان في قلوب جميع أبناء سيلفرمون.",
[891600879]="كرة أخرى جاهزة! أسرعوا!",
[892104080]="لا تمنحوهم أي رحمة! تشكلوا!",
[892490095]="لا شيء يضاهي السلام والهدوء... على عكس المنزل!",
[892907538]="لقد أحسنت صنعًا، دراكرورو.",
[893126552]="لكني... تائه. لا أستطيع إيجاد طريقي للعودة.",
[893194675]="جئنا لنشرب جعتكم!",
[893619005]="لا مكان للاختباء!",
[893664609]="هناك... شيء آخر يجب أن تعرفه عن الـليتش كينغ. يجب ألا نفقد السيطرة على الـسكورج أبدًا. حتى لو تمكنت من القضاء على الـليتش كينغ، يجب أن يأخذ آخر مكانه. لأنه بدون سيطرة سيده، سينتشر الـسكورج في جميع أنحاء العالم - مدمرًا كل الكائنات الحية.",
[893746155]="مرحى، $N!",
[893762519]="لقد ضللنا! تراجعوا!",
[894213300]="دفاع شجاع، لكن يجب تدمير هذه المدينة. سأحقق رغبات ماليقوس بنفسي!",
[894279997]="هذا لا يمكن أن يكون!!! ريند، تعامل مع هذه الحشرات.",
[894403146]="مرحبًا، هل قرأت المكافأة على ملصق المطلوب هذا؟",
[895263836]="لقد هاجمت أطفالي بوقاحة، إيليدان! العقد انكسر. العملاق لن ينحاز إلى الإلف أبدًا! أبدًا!",
[896623382]="تم نشر رون أوميغا. التنشيط ناجح.",
[896677283]="أرواح الغابة قلقة...",
[896879500]="يمكن المزيد من الحشرات اللامعة! نحب الحشرات!",
[897027109]="المزيد... المزيد من الأرواح!",
[897500040]="حسنًا، من المزاح الذي رمى كرة علي؟",
[898021863]="ماذا لدينا هنا؟",
[898324989]="%s يتفحص أصداف سناب جاو...",
[898438524]="نعم، لطالما حلمت أن أعلق في مكان ما.",
[899911392]="البرج الغربي فروست وولف يتعرض لهجوم! إذا تُرك دون رقابة، سيدمره الـهورد!",
[899926172]="أي شيء لكي فولجين!",
[900414459]="أخيرًا، شيء يخفف الملل!",
[900767437]="فلتبدأ سفك الدماء!",
[900769164]="%s يبدو على وشك التحطم!",
[901189194]="ماذا فعلت يا ماكورو؟! هذه ليست طرقنا!",
[901543814]="أنا لا أخاف!",
[902216761]="%s تُظهر أنيابها وتُصدر هسهسة تهديدية تجاه من حولها.",
[902258661]="يبدو %s جاهزًا للترويض.",
[902673877]="فكر يا $N. تذكر إلى الوراء. حاول أن تتذكر القاعات المهيبة لـ سيلفرمون سيتي، حيث وُلدت. تذكر روعة الحياة يا $Gأخي:أختي;. لقد كنت بطلًا من السيندوري يومًا! هذا ليس أنت.",
[902701434]="تاجر، ربما؟ لا تحتاج للبحث أبعد مني للحصول على الإمدادات. أسعاري عادلة جدًا يا صديقي. هذه العناصر كان من الصعب الحصول عليها، لكن ما أهمية المصدر، هاه؟ ستحصل على ما تحتاجه.",
[903853227]="دفء الشمس... ينتظر.",
[904323572]="اصغِ أيها الوغد! أنا من أتحداك! الآن اشعر... بالحرق!",
[904540946]="درعك جاهز يا $N.",
[904781026]="تظن أني لا أعلم ماذا تحاول فعله؟ تظن أني لم أكن أراقبك؟",
[904973257]="السيد سينتقم لي!!",
[905166628]="أيها $C الأحمق، لا يمكنك إيقاف الكفالدير!",
[905228565]="ما هذا؟! أنا... لا أستطيع الضرب...",
[905842643]="وكاد أن لا يتذكرك. $N قاتل بشجاعة ضد نورث ويند ليحمي قصتك.",
[905965556]="حسنًا، مارج، لقد كنت أبحث عن طريقة لأخبرك بهذا....",
[906033187]="آه، نعم... شاهدها تحترق!",
[906921100]="النسيان!",
[907447748]="موتوا أيها الكلاب!",
[907483331]="%s ينتحب.",
[907499980]="لكن ما الفرق. حان وقت إنهاء هذا.",
[907649611]="مهمتنا الآن واضحة: الـليتش كينغ سيدفع ثمن جرائمه وسننقذ هاي لورد بولفار فوردرقون!",
[907669874]="العدو بينكم!",
[908224312]="%s يستهلك روبوت خردة لإصلاح نفسه!",
[908243939]="أوه! لامعات!",
[908865391]="لا أحد يتحدى النقابة!",
[909240106]="أهلاً وسهلاً بكم في مهرجان داركمون، أعظم حدث في العالم كله! لدينا كل شيء... طعام لذيذ، شراب قوي، قطع أثرية غريبة، قراءة الطالع، جوائز مذهلة وإثارة لا تنتهي! لا تنسوا تسليم تذاكر جوائز مهرجان داركمون إلى قيلفاس قرايمقيت! كل ما تحتاجه هو خمس تذاكر أو أكثر وستكون في طريقك إلى أروع الجوائز في كل أزيروث. الجميع رابحون!",
[909867222]="مشروب الاختفاء جاهز لك، $N.",
[910084760]="دماء... دمار... مثير!",
[910208764]="آه، لا بد أن هذا هو الآن... لا؟ بح!",
[910341780]="انهض!",
[910482081]="استيقظوا أيها الخدم! دافعوا عن الأقراص!",
[910541138]="لا أحفورة غامضة هنا... آه، لكن نسختي من \"التلال الخضراء لسترانغلثورن\". يا له من كتاب رائع!",
[910678399]="مرحبا، مون! معركة الأندرسِتي بدأت بالفعل. ثرال يقاتل بالداخل، قد تتمكن من العثور عليه. يمكنك أيضًا انتظاره هنا، سيعود في أي وقت الآن.",
[911252279]="لا، لا. لا داعي لأن يزعج نفسه بتفلسف طالب بينما يسلي صديقًا.",
[911540215]="أراكسيس، تعال... هل أنت هناك أراكسيس؟ الرؤية معدومة. وارب ستورمز يعيقوننا.",
[911716374]="مقبرة سنوفول تم الاستيلاء عليها من قبل الأليانس!",
[911831376]="أريدك فقط أن تعلم أنه إذا نجونا من هذا، فسأحرص على أن نكون أفضل منك. لا تأخذ الأمر بشكل شخصي.",
[911848771]="ولكن، يا سيدي! لقد أسأت تقدير أفعالي... أنا أعرف شخصًا مقربًا منك يخطط لخيانتك. إنه ذلك الكلب، كايل'ثاس! لقد تحالف مع كيلجايدن وينوي استبدالك كسيد لأوتلاند!",
[912093853]="سيدي، أحتاج المساعدة!",
[912666292]="آه، عدت أخيرًا إلى دراك'ثارون!",
[912720754]="لوثيب. النتيجة البشعة لدمج الطاعون الحي للأراضي الموبوءة مع وحوش مستنقعات أزيروث، يُقال إن لوثيب يتحكم في قوة شفاء نفسه.",
[912850003]="أستطيع شم رائحة خوفك، $R.",
[912860857]="حقًا مذهل، جيرارد. كيف فعلتها؟",
[912970204]="أنا حر؟ أنا حر!",
[913080925]="وها أنت ذا! الملك سيكون مسرورًا جدًا، إذا جاز لي القول.",
[913281339]="كنت أفكر في نفس الشيء.",
[913518782]="موتك سيكون تكريمًا مناسبًا للملك!",
[914037701]="أحكم عليك بالموت!",
[914303455]="من هو السيد الآن؟",
[914571752]="لكن هل هذا يعني عبور التيارات؟ أليس هذا سيئًا جدًا؟",
[915344907]="لقد ولدنا في عصر خطير، حيث قوى الظلام مصممة على تدميرنا.",
[915863897]="عش في خوف، مت بإرادة كايل'ثاس... كل شيء سواء.",
[916344253]="أبحث عن لاعب فريق...",
[916481690]="أخشى أنك ستحتاج إلى المزيد من التدريب لهزيمتي.",
[916565176]="%s يضع الجراثيم داخل أدواته الكيميائية...",
[916831144]="حازوقة!",
[917165163]="هناك في الأعلى يسكن شارلقا ريزورفلانك. العجوز اللعينة.",
[917202269]="الشيطان هرب! بسرعة يجب أن نكبحه!",
[917519357]="بالطبع.",
[917962622]="%s يبدأ برفرفة جناحيه والصراخ بصوت عالٍ. لديك شعور بأنك ستكون وجبته التالية!",
[918906890]="المحرك انفجر! حلق بـفيكس فلاينق مشين عائدًا إلى ليكسايد لاندينغ!",
[919429584]="أنت هناك! تحقق من تلك الضوضاء!",
[919544995]="أوساخ ستورمبايك! في حصني؟! اقتلوهم جميعًا!",
[919654659]="هي! توقف عن العبث في قبو منزلي! اخرج!",
[919877387]="لنذهب إلى الآخرين، وابقَ عينك مفتوحة على أولئك الذئاب بالخارج...",
[920234308]="أنا أُسلم نفسي للسيد!",
[920448134]="أنا مراقبك يا فارانيل.",
[920942500]="مرحبًا بك في نزل لايونز برايد. اجعل نفسك في بيتك!",
[921639840]="أذني! لقد خدشت أذني!",
[922287909]="وبينما نحن، كدرويدز، حراس الطبيعة، أتساءل إن كنا أغفلنا جانبًا رئيسيًا من التوازن في كل شيء.",
[922487848]="إنه إسكالدر! بسرعة، استخدم قلادة الـ بون ويتش!",
[922776271]="ثرال! هنا؟",
[923440864]="حسنًا، أبوني. لدي ما يكفي في ذهني لأشاركه. هل تحدثتِ من قبل مع إلفز مونقليد؟",
[923442855]="سيفي أركيوس خدمني جيدًا في الحياة، ولكن أخيرًا قد تنتقل روحي من هذا الوجود التعيس، لم أعد بحاجة إليه.",
[924487043]="إلى المعركة، يا أطفالي! لا تظهروا أي رحمة للعدو!",
[925074674]="جارفروست مل من البشر الضعفاء. الآن ستتجمد عظامكم!",
[925104633]="ستعلقون على المشنقة قريبًا...",
[925233219]="شكرًا لك، يا صديق. لولا مساعدتك لكنت قد فنيت.",
[925419984]="جاينا؟",
[925816288]="من أعماق الأندرهولز يأتي كارنيج. $N الشجاع والأحمق قبل التحدي. مجموعة $Gهو:هي; و$Gخاصته:خاصتها; مستعدة لمواجهة الوحش.",
[926097661]="%s ليس معجبًا.",
[926257332]="الباقي بخير بدوننا.",
[927162759]="لنعد إلى البستان، أيها الفاني.",
[927179801]="رأيت عوالم تغمرها نيران الصنّاع، سكانها يتلاشون دون حتى أنين. أنظمة كوكبية كاملة تولد وتدمر في الوقت الذي تستغرقه قلوبكم الفانية لتنبض مرة واحدة. ورغم كل هذا، قلبي خالٍ من المشاعر... من التعاطف. أنا. لم. أشعر. بشيء. ملايين الملايين من الأرواح أُهدرت. هل كان في كل منهم عنادكم؟ هل أحبوا الحياة كما تحبونها؟",
[927183030]="عد إليه. عد إلى ميهلور وأخبره أنني سامحته وأنني أفهم لماذا يعتقد ما يعتقده.",
[927498206]="%s ينقر بقدمه بنفاد صبر.",
[927609606]="%s يفحص الصدفة.",
[928593046]="\"التدفقات السحرية وكيف تؤثر على العالم\"، بقلم ماجينور دوماس. هذا هو الكتاب الذي كنت أبحث عنه.",
[928674259]="الانتقام لي!",
[928702918]="قد يكون ربح في الحياة، لكنه لن يربح في الآخرة! نار!",
[928713927]="هيا قاتل أيها الجبان الصغير!",
[928760709]="إنها تكافئ من يستجيب لنداءاتها بالبركات، المرئية وغير المرئية.",
[929031698]="هم الهمس على الريح المرتعشة.",
[929051635]="رائحة الموت تغطي كل شبر من هذا المكان.",
[929073051]="هل أتيت طالبًا الخلاص؟ لقد جئت لأقدم الخلاص!",
[929198904]="مقبرة آيس بلود تم الاستيلاء عليها من قبل الأليانس!",
[929775027]="اخذلني وستعاني للأبد!",
[931570835]="قبل أن أتمركز هنا، كنت قد سمعت فقط عن التأثيرات المجددة التي يمكن أن يحدثها حمام الطين على البشرة. عندما تعثرت أول مرة بجذر شجرة، تعرضت للفوائد الكاملة! مذهل ما يمكن أن تفعله الطبيعة، حتى بدون القليل من السحر لمساعدتها.",
[931647997]="بالطبع يا صديقي. أنت مرحب بك للبقاء معنا للمدة التي تريدها.",
[931682564]="أنا مدين لك بليلة طويلة من الشرب، يا صديقي.",
[931733419]="تسلسل التدمير الذاتي اكتمل. أتمنى لك يومًا سعيدًا!",
[931799308]="ممتاز... يبدو أن الحشرات المتطفلة وصلت في الوقت المناسب لتغذية جيشي. مرحبًا أيها البشر!",
[932177361]="لقد انتهى الأمر! انتهى!",
[932536050]="سأدفع لك بكل سرور يوم الثلاثاء مقابل هامبرغر اليوم.",
[932565209]="%s يرمي موزة فاسدة على $N.",
[933141084]="$N هزم بطل الـوارمول، موقور! المجد لـ$N!",
[933159151]="التالي، ليدي بلومايوكس، يستدعي قوة الظلال، ساحبًا أرواح الأحياء إلى العناق النهم.",
[933932705]="ها قد جاءت الدموع...",
[934033072]="أهلاً، أيها $C الطيب! مرحبًا بك في احتفال بروفست السنوي لـآيرونفورج!",
[934034403]="من أين أتى كل هذا! أحد يساعد!",
[934338216]="لقد انتظرت طويلاً. الآن تواجه حاصد الأرواح.",
[934488438]="الـسكورج حاصرنا. يمكننا الصمود في القرية لبعض الوقت، لكن إن لم نهزمهم، سيجتاحوننا.",
[934490779]="هيا، لنجرب مكانًا آخر.",
[935243626]="أستطيع الاستمرار هكذا لوقت طويل جدًا، أيها الكلب القرمزي! أخبرني عن \"الفجر القرمزي!\"",
[935295563]="لقد انجذبوا إلى أنقاض شاتراث سيتي حيث كانت بقية صغيرة من كهنوت الـدرايناي تؤدي طقوسها داخل معبد مدمر في هذا المكان بالذات.",
[935433700]="انظر، $N، الساعة الرملية كشفت عن نوزدورمو!",
[935441727]="همم، ماذا كان ذلك؟ آسف يا عزيزتي، لا بد أنني كنت أحلم يقظة.",
[935488708]="أفضل العمل العملي...",
[935523126]="مت، أيها دافئ الدم!",
[935617901]="ظننت أنني انتهيت!",
[935739495]="سأبقى هنا لأحرّس الحطام. أسرع! آمل ألا يلاحظ أحد الدخان...",
[936291610]="ستهلك هنا. <يمتلئ ذهنك برؤى الفوضى والدمار.>",
[936432559]="%s يتحرر!",
[936438206]="فلتُنفَ هذه الهالة الشريرة من هذه القطعة الأثرية!",
[936556599]="لست متأكدًا. سمعت أنه يُدرّب كبالادن. يأمل تيريناس أن تعلمه اليد الفضية بعض الانضباط. إذا كان هناك من يستطيع تقويم آرثاس، فهو أوثر العجوز.",
[936584002]="لك مني أعمق الامتنان. أشكرك.",
[936698842]="احترم خصمك في الميدان، سواء كان أخاك أو عدوك اللدود. بغض النظر عن معتقداتك، هذا الاحترام هو اعتراف بوجود رابط...",
[936927897]="مخالبي ستمزق جسدك الضئيل، $R.",
[937463858]="إخوتي الترولز سوف يكون عندهم متعة حقيقية اليوم، مون!",
[937648718]="كم عدد تغييرات المجموعة؟ نفس المرة السابقة، أعتقد.",
[938002070]="لا تقلق، سأجد لك بيتًا جيدًا.",
[938449251]="لقد كنت شقيًا جدًا جدًا...",
[938536729]="بالادنز... سمعت أن لديكم حيوات كثيرة. أروني.",
[938766803]="هذه الرعاع الأنديد، وملكتهم الميتة-إلف، سيسقطون!",
[938789432]="كن بخير، $N.",
[938862149]="والنور! تلك الوحوش اللعينة! انظروا ماذا فعلوا بشعبنا!",
[938914758]="أشعر بالغباء الشديد. ربما يجب أن أحررك وأطلق سراحك؟",
[938963490]="مرحبًا، كوين. كيف حالك؟",
[939154407]="ياآآآآآآآآوووون...",
[939321930]="ولما الجعة كلها تضيع",
[939501476]="%s يبدو ضجرًا من النقاش كله.",
[939627544]="سأراهن على روحك بذلك.",
[939678648]="[فوربولق] بعيد جئت مكسيك تاك. انظر إلى نهر كيتشكال. اتبع. إيلوغ إلى يور.",
[939750665]="سباق كالواك فيشينق بدأ! أول شخص يحضر لي قرش أسود الطرف في دالاران سيفوز! القرش الأسود الطرف يمكن صيده في أي مكان تصطاد فيه سمكة بيجمي سوكرفيش.",
[939833491]="هذا هو! كل شيء انتهى، $N.",
[939852111]="رآآآآآآآآآآآآر!",
