[952763174]="أمعرهم! اخزقهم!",
[952932162]="أشكركم على مساعدتكم، يا إخوة. شعبنا سيفتدي!",
[953340823]="أوقفهم!",
[953346688]="توقّف! أوقفوه!!",
[953391198]="الحمد لله إيقان!",
[954070449]="أريد موت هؤلاء الخنازير من الأليانس والـهورد!",
