[956629242]="سندمركم.",
[956745419]="جبناء! أوغاد!",
[956826298]="الوصول مرفوض؟!",
[957591739]="إذا اضطررت للانتظار أكثر، سأضطر لإعادة النظر في الاتفاق المقتسوف بين الإيثيريوم والتنين الأزرق!",
