[974156286]="الفوضى تنادي.",
[975346035]="اسمعني، $Gيا أخي:يا أختي;. يجب أن تقاوم سيطرة الـليتش كينغ. إنه وحش يريد أن يرى هذا العالم - عالمنا - في خراب. لا تدعه يستخدمك لتحقيق أهدافه. كنت بطلًا يومًا، ويمكنك أن تكون بطلًا مرة أخرى! قاومه، مون!",
[976166119]="من الجيد أنك أتيت، يا حليف! كنا هالكين!",
[976512378]="أخشى أن الغضب سيهلكه، ثرال. ما زلت آمل أن يسود العقل، لكن يجب أن نستعد للأسوأ... للحرب.",
[976626020]="كنا نعتقد أن الحصن محصن جيدًا، لكننا لم نكن مستعدين لطبيعة هذا الهجوم.",
