[987703866]="الجسد... ضعيف!",
[988198832]="هذه الأيائل لا تشبه التالبوك.",
[988342023]="كن رمادًا في الضباب!",
[988772161]="يحيا ملكنا المجيد، يميرون!",
[988843748]="من الممتع مشاهدة صراعك. حسنًا، شاهد كيف يُفعل!",
