[995163697]="هذا هو المكان. لنشعله.",
[995328259]="آخر شيء أتذكره هو سقوط السفينة ودخولنا إلى الكبسولات. سأذهب لأرى كيف يمكنني المساعدة. شكرًا لك!",
[995689145]="هل تشعرون بها أيها المخلوقات الحقيرة؟ الكآبة التي تخيم على هذه الأرض هي مجرد مقدمة. قريبًا ستكون ممتلكاتكم الثمينة في قبضتنا! سوف تسقطون أمام قوة الـليتش كينغ!",
[995988077]="هاها! مثالي!",
[996218455]="%s يلوح لك ليتبعه.",
[996888133]="هل سأضطر للتعامل مع هذا التطفل بنفسي؟",
