[997168873]="العامل المعادل يفشل!",
[997469028]="كان هذا هراء! موقور يقدر يقدم قتال أحسن من هيك!",
[997484721]="ضحية أخرى من الحرب!",
[997491591]="انضم للقتال! أغراما-كا!",
[997856099]="ها نحن ذا. خلصنا!",
[998341548]="عائلتي المسكينة. كل شيء دُمّر.",
[998694486]="من... من أنت؟ وماذا تريد؟",
[998903168]="عبيدي! دمروا العدو!",
[999503670]="لم يعد في أوغر لطيف! لقد آذيت موقور!!",
