[1009170476]="...تمتمة تمتمة...",
[1009584153]="احرقوها، يا رفاق. احرقوها كلها.",
[1009932701]="لا أستطيع البقاء هنا. يجب أن أعود إلى ركامي حيث أنتمي، ولكن عندما أرى الأجداد مجددًا، أنا من سيروي قصتك.",
[1010322731]="كنت أقسم أن لدي المزيد من التفاح. قروك!",
[1010547124]="استعد للموت!",
[1011202647]="الحيوانات الأليفة اللطيفة لديها أسلحة. ليست لطيفة جدًا -- را-آك.",
[1011296825]="لا يجب أن يكتشفوا مصير البالادن الصغير. ليس بعد.",
[1011527784]="هذا $N هو تابع من كابوس ناراليكس بلا شك!",
[1011939716]="حياتكم القديمة، رغباتكم البشرية لا تعني شيئًا... أنتم الآن تلاميذ السيد، وستخدمون القضية دون سؤال! أعظم مجد هو الموت في خدمة السيد!",
[1012072174]="أطلقوا النار!",
[1012092347]="الآن أصبح الأمر مثيرًا للاهتمام.",
[1012512701]="إنهم يضعفوننا! قوتنا تتخفف بوجودهم! دمرهم جميعًا!",
[1012706170]="تذلل في اللعنة!",
[1015161896]="آه، جيد... المزيد من الأجزاء!",
[1015186535]="أتمنى أن يكون هذا كله يستحق العناء!",
[1015788243]="يستدير لمواجهة تولون، ويزدرئه %s بازدراء.",
[1015820414]="تأكد من كتابة اسمي بشكل صحيح على شاهد القبـ—",
[1016321265]="ها هي تنفجر!",
[1016382322]="%s محظور للأبد!",
[1016592236]="الخطر هناك، أليس كذلك؟ تعرف ماذا تحتاج؟ حماية. أستطيع مساعدتك على تحدي الموت نفسه! تلبس هذا المادستون حول رقبتك، ثم تستطيع العودة إن وجدت نفسك في عالم الأرواح! مجرد رحلة سريعة إلى جثتك وتعود، جديدًا ونظيفًا!",
[1016685435]="حمايتك قوية، يا طفل. واصل عملك.",
[1016694969]="يا $Gلورد:سيدتي;، اسمح لي أن أعيش طويلاً لأراك تطهر هذا العالم من الكفار.",
[1017448957]="ترولز سينجين فيلج يبدؤون ترنيمة للاحتفال بـ$N.",
[1017629852]="حتدفع ثمن هذه الإهانة، $C!",
[1017667663]="بركب جمجمتك على أعلى برج!",
[1017717057]="ليكن كذلك. أبطال، هاجموا!",
[1018932421]="لا أستطيع العمل تحت هذه الظروف! نحتاج إلى سلالة قابلة للحياة!",
[1019027055]="بقع النبيذ، بقع العشب، حتى بقع الحيوانات الأليفة لا تستطيع مقاومة ماسحة البقع الكهروستاتيكية!",
[1019526236]="لابد أن يكون هناك طريقة.",
[1019815075]="قواتي لا تستطيع التغلب على دفاعات كيراجي. لن نستطيع الاقتراب بما يكفي لكي نضع حاجزك الثمين، أيها التنين.",
[1020059859]="نعم، سيدي. وقت زوالهم النهائي يقترب... ما هذا؟",
[1020157805]="غونار، ابن ثورفارد، وصل! استعد للقاء حتفك!",
[1020202463]="اكسروا عظامهم!",
[1020231719]="من يجرؤ على انتهاك حرمة مملكتي؟ احذروا: كل من يتعدى هنا محكوم عليه!",
[1020272482]="هذا $R يبدو لذيذًا للأكل!",
[1020773829]="وووت!",
[1021542213]="لستُ على ما يرام...",
[1021792891]="من أين حصلت على ذلك؟ هل أرسلك هو؟",
[1021936914]="أود أن أقف من أجل...",
[1022024712]="آآآه!",
[1022037080]="هذا ينبغي أن يكفي...",
[1023257301]="أحسب معاملات القوة...",
[1023621407]="مارشال ماريس، سيدي. كوربورال كيشان من فوج الصابر الثاني عشر عادوا من المعركة ويقدمون تقاريرهم!",
[1024041004]="مت، يا صديق الصقيع!",
[1024305801]="هذا هجوم؟ رأيت هجمات أقوى من طوال القامة!",
[1024352650]="إذا لم تأكل سمكتك، لا يمكنك الحصول على البودينغ!",
[1025233029]="%s يأخذ نفسًا عميقًا...",
[1025793312]="دافعوا عن المخابئ!",
[1025816162]="لقد ابتعدت كثيرًا عن تربتك المريحة.",
[1026671733]="ابنتي!",
[1026698329]="المجد للخالق العظيم!",
[1026757330]="نيران الأليانس تشتعل بقوة وصدق!",
[1026774964]="%s يتجول بعيدًا في الأفق.",
[1027758750]="أيها الفاني الحقير، اونيكسيا لا يخضع لأحد!",
[1027866052]="ج-ج-ج... بارد.",
[1027956002]="%s يتراجع ألمًا بينما يغسله حكم العدالة!",
[1028351396]="فهمت. على الأقل لن نتعامل مع تلك المنصات المدارية.",
[1028735453]="سأسحقك إلى قطع صغيرة جدًا!",
[1029097194]="لا طعم لدي لهذه الألعاب، تيريون. ومع ذلك... أثق أنهم سيؤدون بشكل رائع.",
[1029288727]="عظيم. لسنا جبناء، نحن غير أكفاء.",
[1029900997]="أنت لست وحدك، أكاماً.",
[1030299993]="يجب أن تتذكر روعة الحياة، $Gأخي:أختي;. لقد كنت بطلًا للكالدوري يومًا! هذا ليس أنت!",
[1030909912]="اطمئن، كيكيك، هي ملكة التنانين. غالبًا ما نتخذ أشكال كائنات أصغر عندما نتعامل معهم.",
[1030941831]="أنا غير جدير، $Gسيدي:سيدتي;.",
[1031572796]="من يجرؤ على انتهاك حرمة مملكتي؟ احذروا، كل من يتعدى هنا محكوم عليه بالفناء.",
[1032385909]="تقول الأسطورة أن الوحش العظيم أومن ينام في مياه بحيرة إلونيارا في مونقليد، ولا يظهر إلا مرة في السنة. لكنها مجرد أسطورة.",
[1032666421]="لقد ربحنا وقتًا ثمينًا. الآن يجب أن ننسحب.",
[1033040783]="كما تشاء، ثرال، ابن دوروتان.",
[1033270544]="ربما يجب أن نؤجل الأمر الآن حتى يجهز طباخك وجبتك؟ تبدو منزعجًا بعض الشيء إذا سمحت لي بالقول. يمكننا استئناف حديثنا عندما تشعر بتحسن.",
[1033469709]="هل أنت راضٍ؟",
[1033490719]="ستحمينا من السيدة الشريرة، نعم!",
[1033491426]="فاردمايرا. تساءلت أين اختفيت. كيف حال إسكالدر؟",
[1033640551]="والآن تموت!",
[1033887694]="مقاتلي الأليانس والـهورد! أنتم مرحب بكم تحت راية الصليبية الفضية.",
[1033932046]="حطم!",
[1033997668]="لما تظن أنك شفت كل شيء! $N سيتواجه مع قريزلي هيلز فوربولغ مجنون أمام عيونكم هنا في حفرة الغزو! ضعوا رهاناتكم يا ناس!",
[1034036146]="شكرًا لك، أيها الروح الطيبة. لقد حررتني من سجن كويلسكار المائي لكن الكثيرين ما زالوا محتجزين بالقرب. هل ستساعدني في تحريرهم أيضًا؟",
[1034149105]="ماذا يحدث لما أفعل كذا؟!",
[1034371106]="يا سيدي!",
[1034380173]="لماذا تريد أن تكسر قلب ماك المسكين؟ عندما أعود، سأدعو أن تكون قد غيّرت رأيك....",
[1034500731]="كوربيت، عزيزي. هارلان يحتاج شحنة من القمصان والسراويل المحبوكة بأسرع ما نقدر.",
[1034579503]="لا تقلق، بنلاقيك.",
[1034675564]="كيل'ثوزاد نجا من محن كانت لتحطم أرواح حتى أعظم أعضاء النقابة. لقد ضحى بحياته عن طيب خاطر على يد آرثاس، ثم أُعيد إحياؤه - مولودًا من جديد بقوة بئر الشمس.",
[1035166583]="%s ينشط!",
[1035214465]="لن تدنس أرضنا المقدسة!",
[1035287475]="استمر في مباركة هذا، موطننا القديم، نرجوك.",
[1035786339]="لن يستسلموا حتى يجدوه. لا يمكننا السماح بحدوث ذلك، $N، وبران يعلم ذلك.",
[1035962396]="ظننت أنه لن يصمت أبدًا. أخيرًا، أسكت سيندراقوسا ذلك الأحمق الثرثار. إلى هولز أوف ريفلكشن، أيها الأبطال! هدفنا قريب... أشعر به.",
[1036113045]="سأطعمك للكلاب!",
[1036420693]="أيها الجبان الحقير! أنهِ الأمر...",
[1036583256]="إنهم يؤدون طقوسًا دنيئة في السراديب، وأنا على وشك أن أكون القربان!",
[1036644977]="عمل إخوتك في قمم العاصفة بلغ وتيرة محمومة. قريبًا، سيُحرر الأب.",
[1036863252]="هي تحتفظ بالمعرفة والكلام، وحتى الاكتفاء الذاتي لأداء المهام لك. ماذا فعلت بالضبط؟",
[1036925925]="سأجمّدكم جميعًا!",
[1037096641]="يجب أن نستمر مع أو بدون ماييف. إلى الداخل! بسرعة!",
[1037276462]="آخ! هذا أسوأ شيء تذوقته على الإطلاق! لن أترك كبشي يشرب ذلك!",
[1037705064]="سكايوينق، سأحررك من لعنتك على جثتي!",
[1038097005]="الآن أشعر بتحسن. لنعد إلى راتشت. تعال، $N.",
[1038473517]="هيا! هذه النكات رائعة!",
[1038514699]="أوه نعم، إنها مضحكة حقًا، أليس كذلك؟",
[1038612804]="بيضة نسر مخللة!",
[1038792716]="أبناء أروقال سينهضون ضد كل من يتحدى قوة موونريدج!",
[1038937934]="أسرار سونتارا لن تغادر هذه الأراضي.",
[1039449597]="كيف تجرؤ على مقاطعة عملنا المقدس؟!",
[1039637413]="أنا حامل المفتاح. هل أنت حارس البوابة؟",
[1039688862]="شكرًا لك، $N. ليباركك النور، $Gأخي:أختي;، ويهدي طريقك.",
[1039832716]="لنرى إن كنت لا أزال أستطيع إصدار ذلك الصوت...",
[1040908441]="سحق... تشويه... دمار!",
[1041060854]="برونتس يرى كل شيء.",
[1041871722]="غروول... سيسحقك.",
[1042186373]="فات الأوان بالنسبة لنا، أيها الحي. خذ نفسك وصديقك بعيدًا من هنا قبل أن يتم... الاستيلاء... عليكما.",
[1043161872]="إذن أنتم أعداء لسيدي إيليدان. أعداء إيليدان يُدمرون. هل عمالقتكم قادرون على الصمود أمام هجوم من قوات نقطة الكسوف؟",
[1043346193]="كم يريح هذا روحي!",
[1043426484]="تمهل! لن يتم تعقيم أحد ما دام لي رأي في الأمر!",
[1043442090]="روحك أصبحت مرتبطة بي الآن!",
[1043741648]="منذ وصوله من دراك'ثارون، السيد يتحدث عن الوقت الذي ستنضم إليه هنا.",
[1044280142]="شادوز يتجمعون ويحاصرون $N!",
[1045059212]="اركع، غارك.",
[1045331400]="انتظرت هذه اللحظة لسنوات. إيليدان وكلابه سيُدمرون!",
[1046600230]="حسنًا أيها الجنرال. إذا غيرت رأيك، شعبي سيكون مستعدًا لتقديم مساعدة عسكرية.",
[1046941577]="ذُق فساد عالمك!",
[1046955839]="مخطط غير شريف.",
[1047356647]="ماذا... فعلت؟ لا!",
[1047967858]="بيورن أوف ذا بلاك ستورم! شرفني الآن بحضورك!",
[1048028928]="ثاين باناهوق الموت سقط على $N و$Gخاصته:خاصتها; رفاق القتال. $Gهو:هي; لديه تحدٍ واحد أمام $Gإياه:إياها;. من سيكون؟",
[1048877722]="سمعت أنه لا يزال هناك أوركس مدفونون تحته.",
[1049559756]="كيف يمكنني تبرير المبارزة بينما يموت الناس دون حمايتي؟",
[1050230059]="ولكن لماذا؟",
[1050245272]="%s يصبح غاضبًا!",
[1050362781]="ذوق النصل، أيها الهجين!",
[1050438715]="سنرى ذلك، أيها الأمير الصغير.",
[1050505840]="آه، مقدر كثيرًا، كوربيت. سنضع هذه على الرفوف فورًا.",
[1050726390]="قريبًا سنزحف على هذا المكان الملعون ونطهره من شره!",
[1051030853]="من أجل كويل'ثالاس! من أجل صنويل!",
[1051100745]="لن أضيع هذه الفرصة. سأبحث عن قدري.",
[1051202675]="أنا قادم، يا سيدي!",
[1051238295]="احذر المخاطر التي تنتظرك... وحاول أن تبقى سليمًا.",
[1051664445]="مرة أخرى، أعترض بشدة على رؤيتك للوضع الاستراتيجي. خطتك ستبعثر قواتنا كثيرًا. ستتركنا بقوة صغيرة لنهاجم ديثولم. لا أستطيع بضمير حي تنفيذ مثل هذه الاستراتيجية.",
[1051783054]="إذا كنت تريد أن تكون صديقًا لأصحاب الألسنة الكبيرة، فأنت لست صديقًا لـفرينزي هارت! سأخبر القرية! لن نثق بك بعد الآن!",
[1051808580]="أبي. لقد خشيت على... على عقلك.",
[1052398243]="آآآآه! لقد أصبت! سيكون عليك إعادتنا! بسرعة، قبل أن تنفجر الطائرة!",
[1052496603]="كدت أن أفقد الأمل.",
[1053322095]="لما توقف الاهتزاز، ظهرت نواياه الحقيقية. كنا محاصرين، وكان يمتص قوانا ببطء.",
[1053444904]="%s يستدعي سكليتل واريورز!",
[1054247112]="ستظل هنا دائمًا، معي.",
[1054888464]="مت باسم راقناروس!",
[1054923206]="أنا مرتاح لأن هذا الممر السري لا يزال يعمل.",
[1054986650]="%s يعزز الحلفاء القريبين بقوة رونية!",
[1055088456]="لقد كسبت حريتي!",
[1056046350]="هل هذا أفضل ما لدى الـهورد؟",
[1056184657]="مخلصات وجذابات للغاية، تعيش هؤلاء البرايستس فقط لنشر قوة رؤية سارجيراس المخيفة.",
[1056193358]="نحن مدينون لك يا صديق. تحدث إلى ليساندر في فينجينس لاندينغ؛ سيرتب لك مكافأة مناسبة.",
[1056689609]="احذروا! المزيد من العُبّاد قادمون!",
[1057260765]="أرى الآن... الـسكورج لم يكن... عدونا الأعظم...",
[1057447791]="تم تفعيل الطاقة الطارئة! تشغيل المحرك المتحرك! كلاك!",
[1057562698]="ها... ها... ها...",
[1058597766]="تسعى لاستدراج جنرال ليجيون فروست وولف من حصنه؟ هذا سخيف!",
[1059392832]="من أجل الـدارك ستراند!",
[1059470320]="حسنًا... لنتوجه إلى النصب التذكاري لأبطال الحربين العظميين، وادي الأبطال. اتبعوني.",
[1059980849]="هذا يجب أن يكفي! فُواق!",
[1060093687]="تم تطهير الكهوف. إلى حجرة ناراليكس نذهب!",
[1060512491]="أ-مي جيدة. جيدة، أ-مي. اتبع... اتبع أ-مي. البيت. أ-مي تذهب للبيت.",
[1060719750]="انظروا إلى الوجه الحقيقي للموت، واعلموا أن نهايتكم قريبة!",
[1060879217]="كلنا سنموت!",
[1061679773]="سنتحدث مجددًا، لكن بعيدًا عن هنا.",
[1062364981]="شاتراث كانت عاصمة الـدرايناي في هذا العالم. اسمها يعني \"مسكن النور\".",
[1063172643]="تحركوا بسرعة! آل سانريفير لن يضيعوا وقتًا عندما يدركون أن لدينا المعلومات التي يبحثون عنها.",
[1063178707]="لن تمنعونا من كشف الحقيقة حول جبن جاينا!",
[1063196607]="هل لديك أي فكرة كم هو رائع أن تقفز لتلك المسافة؟",
[1063227166]="هل تعتقد أن هناك سمكة هنا؟",
[1063440754]="حسنًا، هنا يجب أن نكون على أهبة الاستعداد. كونوا جاهزين!",
[1064358481]="نعم، هم المخطئون، لكني عاجز عن إيقافهم. هل ستحذر أهل تونكا'لو، أيها الغريب، أن ماضيهم وأسلافهم في خطر؟",
[1064456623]="حسنًا، $N، جهاز الإرسال الخاص بك جاهز!",
[1064719321]="لور'ثيمار أعاد تشكيل سيلفرمون لشيء يمكننا أن نفتخر به حقًا.",
[1065274409]="شكرًا لك، أيها الغريب.",
[1065436741]="انزف!",
[1066075923]="كفى، آرثاس! لن تستهلك المزيد من الأرواح بكراهيتك!",
[1066159437]="ببساطة، يجب أن تخبر التوسكار أنهم لا يستطيعون الهرب. إذا فعلوا، ستُدمر أرواحهم بالشر الصاعد في نورثريند.",
[1066167377]="هذا اليوم طال انتظاره! ابتعد عن طريقي!",
[1066309176]="مرحبًا بك في شاتر بوينت، $N! أتمنى أن تنجو من التجربة!",
[1066626904]="حاول داجيك أن يُريني طرق الصيد، لكني أؤدي بشكل أفضل عندما أفعل الأمور بطريقتي.",
[1066849759]="%s يهز رأسه بخيبة أمل.",
[1066911927]="ليريسا!",
[1067032601]="موقور تحدّاك. عليك القبول! ادخل الحلبة إذا كنت مستعدًا للقتال.",
[1067332697]="وجد كشاف بقايا مذكراتك في ثور مودان. ونحن نبحث عنك منذ ذلك الحين.",
[1067553863]="غزاة في البرج!",
[1067976107]="أحسنت صنعًا، مون...",
[1067990024]="النور يمنحني القوة!",
[1068060631]="واصل هكذا. هناك الكثير من القتل للجميع!",
[1068191532]="هل... هل كان كل ذلك حلمًا؟ أزوريمست، بلودمست، زانقارمارش، شادومون... حتى زولأمان... جين! جين أين أنت!",
[1068602008]="لم نكن لننجح بدونك، $Gسيدي:سيدتي;.",
[1068713248]="لن أتحمل أكثر من ذلك!",
[1069012656]="أجل! أجل! لا ترحمهم! لا تتوقف عن الهجوم!",
[1069986595]="عندما عثرت على أحجار سونتارا في موقع حفر غرايمسيلت، اجتاحتني قوة راقناروس. كانت راقناروس هي التي أعطتني هدفًا.",
[1070263943]="تقول الحقيقة.",
[1070611135]="أنا سعيد برؤيتك أيضًا يا غريم! يبدو أن ليس كل الغرباء مخيفين بعد كل شيء، أليس كذلك يا غريم؟ تيرينثيس سيكافئ هذا المغامر جيدًا.",
