[1127499202]="انظر هنا، $C! عندي شيء لك. فقط ما تحتاجه. إنه صابون، صحيح... وهو على حبل! لا تأخذها بشكل شخصي، $Gرجل:عزيزتي;، لكن رائحتك قوية قليلاً، فهمت قصدي؟",
[1127559850]="نعم... ألقوا تعاويذكم الصغيرة الثمينة، أك-آ-أك!",
[1127698077]="%s يشير إلى توتيم اوف كو.",
[1127721748]="$R حي... قريبًا سيكون ميتًا مثلي.",
[1127788860]="نحن نغادر، إذن، تورلوك. لدي طلب واحد فقط...",
[1128270028]="لن يوقفنا شيء! ستموت!",
[1128995482]="أين فقست؟ اعمل على هذا البيض!",
[1129003964]="ابقَ في حقل مضاد السحر! اجعلهم يأتون إليك!",
[1129263643]="حان الوقت لأخذ الأمور بيدي. تعال. ادخل إلى مملكتي وتحدى قوة الـسكورج!",
[1129578122]="التوقعات إيجابية، لكني ما زلت سلبيًا.",
[1129894804]="الوظيفة: عملاء استخبارات، معذبون",
[1130110582]="هل حلقت فوق منصة الهبوط مؤخرًا، $N؟",
[1130145255]="إعلان جديد! أيها المغامرون والأبطال، تجمعوا حول لوحة الإعلانات!",
[1130921505]="أساليبها جبانة. تذكرني بالصيادلة الفورسيكن.",
[1132276031]="إنهم في كل مكان!",
[1132311348]="احفظ غضبك. سيطر على حنقك. سيكون لديكم جميعًا متنفس لإحباطاتكم قريبًا.",
[1132351580]="لورد مايور! كشافتنا أبلغوا عن نشاط غريب في الغرب.",
[1132521612]="لا يمكننا البقاء إلا لحظات قبل العودة إلى البرج. إذا أردتم التحدث إلينا أكثر، يمكنكم إيجادنا هناك.",
[1132703273]="فقط /استلقِ في أي مكان، $N. أعدك، هذا لن يؤلم أبدًا!",
[1133245064]="المحارب التالي، تقدم!",
[1133503537]="آآآه!! ثارون'جا سيريد المزيد!",
[1133548794]="انظر إليهم، أوغ. هل تعرف ما هؤلاء؟",
[1133859686]="كما تطلب يا سيدي.",
[1133961934]="أسرار شقية!",
[1134007633]="أنت بلا أمل أمامي!",
[1134453476]="فشلت!",
[1134786909]="%s يطلق ضحكة شريرة.",
[1134796122]="هل هو بخير؟",
[1134956374]="يتم تضليلك! الهجوم كله أكاذيب! الـسكورج والفورسيكن ليسوا أعداءنا! استيقظ!",
[1135060785]="ألكسترازا اختار حلفاء أقوياء.... يا للأسف أنني يجب أن أنهيكم!",
[1135680332]="الآن بدأت أتضايق.",
[1135775761]="لفتة عقيمة كهذه.",
[1135795471]="يا كراكلي المقدس! درجة الحرارة 428,000 درجة كراكلنهايت!",
[1136467032]="أنت نجس!",
[1136893529]="اعتادوا على ذلك يا فتيات. نحن هنا لبقية حياتنا البائسة على ما أعتقد. مرحباً بكم في هيلفاير بيننسولا، منزلكم الجديد.",
[1137098880]="لن أسمح لك أبدًا باستخدام هورن أوف إليمينتال فيوري ضدنا! مت أيها الضعيف!",
[1137166897]="كونوا حذرين، أيها الأصدقاء. الخائن يتأمل في القاعة التي تلي هذه.",
[1138828501]="غورتيش مات؟!؟!",
[1138907263]="التنافسات كثيرة في هذه الأيام. من السهل رؤية الاختلافات أينما تتجه.",
[1139071371]="إلى جانبي، أيها الإخوة! من أجل الصنّاع!",
[1139472356]="غبي! لا تطلق النار عليه! جيكجيك يريد الكأس قطعة واحدة!",
[1139887094]="حسنًا، أتمنى أن يرحلوا!",
[1140444439]="سأخبرك بالمزيد، كارنيك، لاحقًا. لكن أولاً، أرسل هذا المسافر إلى بيلغروم—هناك أعمال أخرى يجب الاهتمام بها.",
[1140782242]="لقد وجدت علاجًا! سوف نسحق أعداءنا!",
[1140909354]="حمقى.",
[1141001684]="هذه البطولة تساعد في تشكيل قوة موحدة وقوية، حتى لو لم يبدُ ذلك واضحًا. عندما نكون مستعدين، ستتجه أنظار الحملة وجميع أبطالها نحو آيس كراون.",
[1141071469]="أيها المخلوق الصغير المصنوع من اللحم، أمنيتك قد تحققت! الموت قادم إليك!",
[1141173285]="العظيم سيكون مسرورًا.",
[1141188898]="مجرد جسوف سطحي!",
[1141905348]="عد إلى رفيقك. أخبره أن يتقدم ويحصل على جائزته في فارون.",
[1141995406]="فوور اذهب الآن، $N. احضر الأرك، ثم عد.",
[1142129977]="سائلان لزجان، غرفة واحدة. احتمالات كثيرة ممتعة!",
[1142191835]="دم بالدم!",
[1142480126]="المزيد من العظام لأقضمها...",
[1142721715]="اقضِ عليه...",
[1143210044]="يا سيدي.",
[1143349243]="أحتاج... مساعدتك! لا أستطيع مقاومته أكثر!",
[1143438148]="أعتقد أنني سأجرب الميرلو هذه المرة.",
[1143789088]="مخبأ ستونهيرث يتعرض لهجوم! إذا تُرك دون رد، سيدمره الأليانس!",
[1143795841]="ما هذا؟ نوم حقير؟ سأفعل أفضل، أيها العظيم.",
[1143984848]="خسرنا الكثير. وسنخسر الكثيرين قبل أن تنتهي هذه المعركة.",
[1145101734]="إذن لنا مكان في الكون الجديد.",
[1145637530]="غورغيك يظن نفسه رئيس الجميع، لكنه يأكل كثيرًا ويصطاد قليلًا.",
[1145708677]="آه... أنا متألم. هل يمكنك مساعدتي؟",
[1147052799]="جنرال ستورمبايك مات!",
[1147178920]="أعرف، أعرف... لم أستسلم بعد. لكن لا ترفع آمالك، هذه التقنية تفوق قدراتي بكثير.",
[1147513643]="ريدباث! حياتك ستنتهي، هنا والآن!",
[1147552978]="%s يلقي اللعنة على الجميع!",
[1148005857]="الطقوس تسير ببطء شديد. نحتاج المزيد من الضحايا!",
[1148505760]="بعد كل ما مررنا به؟ حسنًا، لم أحبك على أي حال!!",
[1149439189]="واو... طبلة.",
[1149706928]="همم، قد يكون هذا المتطفل شاو. سأرى ما يمكنني اكتشافه. اذهب الآن. سأتصل بك قريبًا.",
[1149898204]="لن تنضم لأحد، ثورسن..",
[1150119925]="أعيرونا أصواتكم! الآن حان وقت العمل لإنقاذ شعبنا.",
[1150670453]="الـهورد يطالب بالعدالة! نتحدى الأليانس! اسمح لنا بالقتال بدلاً من فرسانك، أيها البالادن. سنري هذه الكلاب معنى إهانة الـهورد.",
[1151715416]="بيسي، أنت في البيت. الحمد للايت!",
[1151750816]="أخيرًا... الآن يمكنني الراحة.",
[1151835379]="الناغا ليسسس... عندهممم... هذا الشيفرة...",
[1152052354]="هذا القرار يؤلمني بشدة، لكن الدمار والخسائر الفادحة في الأرواح كان لا بد أن تنتهي. بغض النظر عن تجاوزات ماليقوس الأخيرة، سأحزن على رحيله. لقد كان يومًا حارسًا وحاميًا. في هذا اليوم، سقط أحد أقوى أبطال العالم.",
[1152258908]="آخرون سيأخذون مكاني!",
[1152299158]="عندما أشغل هذه الخردة، سأتمكن من السير في الطرق دون خوف من التعرض للهجوم من قطاع الطرق!",
[1152378786]="سامحني... ليس لدي خيار.",
[1152743858]="يجب أن نفعل شيئًا حيال هذا!",
[1152767343]="رويدًا أيها التنين الصغير.",
[1153021332]="كنت أحمقًا لتتحدى قوة الـليتش كينغ!",
[1153525446]="انتهى الوقت.",
[1153800465]="أخور شي-كي! كل يا حيواني الأليف! كل حتى تشبع!",
[1154913888]="والنور! هذا ليس جيدًا. هناك شيء لا تفهمه، $N.",
[1155076015]="كلاب إيليدان! ستدفعون ثمن سجني بحياتكم!",
[1155180834]="لم يسبق لي أن ندمت على إبقائك على قيد الحياة أيها الفاني. دائمًا تجد طرقًا لتسليني.",
[1155434436]="أجل... اهرب... اهرب لملاقاة مصيرك... إن عناقه المرير البارد ينتظرك.",
[1156070807]="تم الاستيلاء على حصن آيسوينغ من قبل الأليانس!",
[1156125607]="لا شيء يضاهي يومًا دافئًا ولا امرأة تصرخ في وجهك...",
[1156464754]="لماذا تهرب مني، فلافي؟!",
[1156592673]="دورة إراقة الدماء لا تنتهي... هل لا يوجد شيء يمكنني فعله؟",
[1156767746]="يجب أن تعود إلى وارسونغ هولد الآن يا صديقي. بالتأكيد هيلسكريم سيريد سماع ما حدث هنا للتو... عن ساورفانغ...",
[1157391922]="<تنهيدة>... هذه نهايتي.",
[1160123889]="صبرِي نفد!",
[1160427899]="فقدت الهدف.... استئناف أنماط البحث دلتا",
[1160618558]="%s يتفحص الحجر القديم المغطى بالطحلب.",
[1161243051]="%s ينظر إليك للحظة، ثم يشير لك بالاتباع.",
[1161377270]="النور تخلّى عنك!",
[1161591536]="خذني يا فال'كير! أنا مستعد للحكم عليّ!",
[1162021859]="لديه كل ما يحتاجه سكورشلينغ النامي!",
[1162575925]="لا تقتلني! لا تقتلني!",
[1163050173]="ما ينقطع شغلنا! إيك، اعتني بهم!",
[1164599461]="الآن، تحرروا وانضموا للمعركة! لننهي هذا معًا!",
[1164926361]="يو هو! أخيرًا نخرج من هنا. لكنها رحلتها صعبة. خلّي عيونك مفتوحة على المشاكل.",
[1165129449]="وصلنا! بس، إذا هذه شجرة العالم، لماذا انكسرت لما حاولوا يحطون العالم كله فيها؟",
[1165438155]="بستمتع برائحة الشحم من نخاعك وهو يتشقق على النار!",
[1165806072]="أي خداع هذا؟ أنا... آآآه...",
[1166071548]="المحلول جاهز في مرجلي. بس مسألة معالجة المفتاح غير المكتمل والجعران.",
[1166123419]="الريح استخدمت أتباعها لتحريف تاريخ هذا المكان، تغير القصص اللي قالها شعبك، تدمر أرواح الموتى المكرمين.",
[1166673673]="طيب طيب! لا داعي للعنف. سوف أتكلم. سوف أتكلم!",
[1166767463]="قوته تجري فيّ! أنا إله!",
[1166774054]="لك مني الامتنان.",
[1166886252]="آآآه، السم...",
[1167042028]="سأعطيك أي شيء تريده! فقط أبقني على قيد الحياة!",
[1167185961]="سأمزق اللحم من عظامك!",
[1167238782]="تمسك بقبعتك، $N! سنذهب إلى سكالاواغ!",
[1167439397]="قتلك سيكون سهلاً.",
[1167466654]="توقفوا! اركعوا أيها الحمقى، إنه الـليتش كينغ!",
[1168028344]="أرجوك، أشعل هذا بينما أنا أستحضر.",
[1168178857]="كولوسس أوف آشي يتحرر من شرنقته تحت هايف آشي.",
[1168315579]="ناغا كويلسكار قاسيون بشكل استثنائي مع سجنائهم. إنها معجزة أنني نجوت داخل ذلك السجن المائي طوال تلك المدة. فلتُحمد الأرض الأم.",
[1168612962]="%s يلقي تعويذة قوية، مما يقتل المدافعين ويصد الآخرين.",
[1169053418]="افعل كما علمتك!",
[1169993772]="%s يبدأ في إلقاء |cFFFF0000ميثاق التوأم!|r",
[1170362920]="أول شيء تحتاج تعلمه هو الانضباط السليم.",
[1171030103]="أنا ملعون! أولاً غرقت سفينتي، والآن... نفد الميد!",
[1171464740]="أنتم قطع غيار! نصنع المزيد من الـسكورج في النيكروبوليس.",
[1171600428]="أبنديس سيراك مطهّرًا!",
[1171720210]="أنت لست ملكي بعد يا فتى! ولا كنت لأطيع ذلك الأمر حتى لو كنت!",
[1172001014]="%s يأخذ نفسًا عميقًا...",
[1172024151]="ما هذا؟ هل طلب كيفر خروفًا؟ كيفر أراد سلاحًا ذا قوة عظيمة وكل ما حصل عليه هو هذا الخروف. كيفر محبط جدًا.",
[1172141396]="أرفض الاعتراف بالهزيمة! أنا أمير من الإيريدار! أنا...",
[1172279340]="أولاً، اسمعوا يا سيندوري. أنا أدير سفينة محكمة... هذا لن يكون مثل ما اعتدتم عليه مع سكريِرز. اعملوا جيدًا، أو عودوا إلى القارب!",
[1172357117]="أهلاً، جيزه! تم تقديم سبعة عشر طلبًا إضافيًا في قطاع هارا ساميد. أسواق الفيلداريت الثقيل انهارت تقريبًا، كما توقعت.",
[1173328199]="$N، يجب أن نسرع ونكتشف متى بدأ نورث ويند في تشويه الجدول الزمني. عندها فقط يمكننا هزيمته وتصحيحه.",
[1173650812]="كان يجب أن أعرف ألا أثق بأحد!",
[1174014704]="أمسكت بواحدة كبيرة الأسبوع الماضي، كان لها ثلاث عيون!",
[1174080391]="ها ها! لقد حصلت على بيتسي!",
[1174265525]="استكشف المنطقة وأبلغ عن أي شيء تراه!",
[1174510146]="تلك المجموعة التي وصلت مؤخرًا من هونور هولد — إنهم مرتزقة! بدأوا يثيرون المشاكل. ربما يجب أن أتحدث معهم؟",
[1174658449]="غرفتهم الاحتفالية، حيث كان من المقرر أن أُضحى...",
[1175005132]="جبناء! لن تجروني إلى الظلال أبدًا!",
[1175201643]="يبدو أن ساوثسي فريبوترز محصّنون بشدة على الساحل. قد تكون هذه مهمة صعبة.",
[1176422874]="%s تنظر إلى القلادة المهملة. في حزنها، تلقي السيدة تعويذة جمال تستدعي أرواح الهايبورن. تمتلئ الغرفة بأغنيتهم القديمة عن السيندوري...",
[1176619091]="...لا!",
[1176647344]="لعنة ذلك الضفدع! نعم، انضممت إلى طاقم ساوثسي - هل تريد أن تعمل شيئًا منها يا صاح؟ سأقطعك هنا والآن!",
[1176756539]="%s يهرب بينما تُستنزف القوة المسيطرة للكرة.",
[1177031632]="داريون، يا ابني.",
[1177163384]="ستعيش في العذاب إلى الأبد بسبب هذا، أيها الوارلوك الحقير.",
[1177193605]="%s يقبض قبضتيه بغضب.",
[1177562755]="هذا الباب هو كل ما يفصلنا عن الخائن. تنحوا جانبًا يا أصدقاء.",
[1178340879]="استمر في العمل الجيد. هذا الـسكورج سيتم تطهيره!",
[1178682287]="بارككم الله أيها البشر على هذا التحرير... هاكار لم يعد يتحكم بي!",
[1178875880]="شيفارا",
[1179374311]="اركب البرق أيها القذر!",
[1179815958]="الليلة نغوص في أعماق الروح البشرية بينما ننضم إلى فتاة ضائعة وحيدة تحاول جاهدة - بمساعدة رفاقها المخلصين - أن تجد طريقها إلى المنزل!",
[1179981939]="هل سنتمكن من العودة إلى المنزل يومًا ما؟",
[1180776430]="لا تقلق، أولد بلانشي، سنحضر لك شيئًا لتأكله قريبًا...",
[1180837397]="جيمس؟ جيمس... لا، أنت لست جيمس، لكنني أعرف من أنت...",
[1181120049]="غزاة! أطلقوا الإنذار!",
[1181439788]="ستالاق سيسحقك!",
[1181892360]="%s تبيض بيضة!",
[1181906743]="لنخلص من هذا.",
[1182083521]="%s تخفف قبضتها على اليومية التي كانت ممسكة بها.",
[1182328761]="من اللطيف جدًا منك التبرع بأعضائك!",
[1182431260]="استخدم العصا، قل لـريز ماذا تفعل! أرِ ريز الصياد! ريز يحطم!",
[1182716458]="تكلم عن نفسك، ثرال.",
[1182999321]="استعدوا للمسيرة!",
[1183003929]="اسمعوني يا سكان الفوهة! جئت لأحرق هذه الأرض من نجاستها!",
[1183621454]="%s يبدأ في |cFFFF0000إطلاق الأرواح!|r",
[1183843846]="%s يغرد وداعًا لـ$N.",
[1184097014]="واو، هذه عديمة الفائدة تمامًا. دعني أحاول مجددًا.",
[1184207731]="مجلس دسكوود يجب أن يتخذ إجراءً. الشر يخيم في الأجواء.",
[1184421961]="أحمق! هل تعلم ماذا فعلت؟ هذه أرض مقدسة!",
[1184740253]="كيان غير مصسوف به يحاول تحميل الدائرة. تفعيل إجراءات مضادة للأفراد.",
[1184746312]="أناديك باسمك الحقيقي، أزريثوك. أظهر لي وجهك!",
[1185279073]="هذه الوحدة تعمل حاليًا ضمن المعايير الطبيعية.",
[1185769738]="إلى الجحيم مع الأنديد! سنشق طريقنا عبر الغابة، يا رجال!",
[1186459402]="لتحترق روحك بالألم، إسيلين! أيها النور أعطني القوة لمحاربة هذا الشيطان.",
[1186599566]="انتهى وقت التمرين! أرني ما تعلمته!",
[1186629735]="أتتحدى نيدار، سيد التندرا!؟",
[1187179309]="ما تبقى إلا ظلال من الماضي. لا شيء لاسترداده!",
[1187197995]="الـديفياس سينجح! لا مغامر ضعيف سيوقفنا!",
[1187947683]="أكوانوس بالكاد يستطيع اللحاق!",
[1188068849]="أوه، حررته، أليس كذلك؟ لا يهم، موته وإعادة بنائه سيتأخران قليلاً فقط.",
[1188316230]="الآن تواجه أورابوس، أيها الأحمق!",
[1188331337]="متى سيفعل أحد شيئًا بشأن الأنديد؟",
[1188507243]="يحاولون إسقاط الطائرة! لا أستطيع الارتفاع أكثر... عليك إبعادهم عنا!",
[1188508356]="العامية... لغة فظة. باندال!",
[1188684273]="النور سيطهرنا جميعًا!",
[1189619715]="حان وقت النزيف!",
[1190227748]="في المزيد قادمون. دافع عن نفسك! لا تخرج من حقل مضاد السحر! بدون حمايته سيمزقونك إربًا!",
[1190601893]="سبب عدم مطاردة فريزيهارت للدجاج هو أن الخسارة أمام دجاجة تبدو غبية.",
[1191242065]="أين التعزيزات من ستورمويند؟ تم الإبلاغ عن نشاط كثيف لـبلاكروك في الشرق.",
[1191589898]="والآن، سأقطعك!",
[1191776325]="آه، الحياة جميلة.",
[1192007693]="حان وقت قتل الحقير أخيرًا.",
[1192075574]="انتباه!",
[1192312527]="جئنا من أجلك! استعد!",
[1192945481]="لقد هُزمت بسهولة!",
[1193404604]="عمل رائع!",
[1193558749]="لقد فشلت!",
[1193681015]="سأخبرك بهذا القدر...الترآك فالي سيكون لنا.",
[1195183468]="أخبار سيئة، يا أبي...",
[1195324531]="لا مكان لك هنا! أيها القدماء، انهضوا ضد هؤلاء الدخلاء!",
[1195463615]="أنت تقترب من برج فريا. إنه يحتوي على قوة تحول الأراضي القاحلة إلى غابات تعج بالحياة بين ليلة وضحاها.",
[1195556038]="$N، من فضلك ألق نظرة على عينة كرمة فايليستيم التي أخذتها من الكهوف، لتعرف ما الذي تبحث عنه...",
[1195610794]="أمتلك كلبًا، لكنني لن أعطيه سيفًا.",
[1195893261]="موا ها ها!",
[1196740193]="من أين تأتي كل تلك القبعات الشتوية الرائعة؟",
[1197484399]="كان ينبغي ألا نأتي أبدًا.",
[1198101121]="سنحاربك بكل ذرة في كياننا - حتى لا نكون سوى غبار وحطام. سنحارب حتى النهاية.",
[1198130230]="انتهيت! التعديلات ستعطينا دفعة صغيرة في السرعة، لكني لا أعتقد أنها ستتحمل الكثير من الصدمات.",
[1198802295]="%s يبدأ بإلقاء تعويذة على قريمكلو.",
[1198879793]="ماغني يومئ برأسه.",
[1199174478]="وكأن لدي كل الأبدية.",
[1199588653]="حالاً، أيها المدرب.",
[1199617176]="يورتراك يقتلك!",
[1199640736]="عندما يتحدث إليك الممثل، سيبدأ كل سطر باسمك. إذا لم تر اسمك، فهو لا يتحدث إليك.",
[1199861526]="مستحيل! خوذة رأس وحيد القرن بسعر منخفض جداً، ثلاثين رأس وحيد القرن؟ سآخذ اثنتين بهذا السعر!",
[1200045194]="والآن أين وضعت تلك البكرة الفضية...",
[1200138788]="عُد... إلى العمل...",
[1200181836]="موجة الأرواح لن تهدأ! أنت فقط تؤجل المحتوم.",
[1200494026]="الوظيفة: جنرالات، قادة أرضيين",
[1201316572]="هذا يؤكد شكوكنا. خيوط الزمن قُطعت وأُعيد نسجها بنمط خاطئ. لكن، كيف؟",
[1202189721]="تحدث معي، $N - إذا كنت مستعدًا، فإن دائرة السيناريون ستقبل بكل حماسة عرضك الكريم للمساعدة. التهديد الذي تشكله كرمة الفيلفين في إلدري'ثالاس خطير حقًا.",
[1202296221]="%s يركع مهزومًا أمام تيريون فوردرينق.",
[1202620839]="لقد هوجمنا مجددًا! دافع عن نفسك!",
[1202945373]="سامحني على خداعي، مون. كل هذا كان لمصلحتك.",
[1203492860]="سأحطمك!",
[1203929236]="تشعر بالكآبة؟ تعال إلى العنكبوت الأزرق لقضاء وقت ممتع!",
[1203933999]="اشفَ!",
[1204224460]="لنأكل شوك الظهر فقط، اتفقنا؟ خلصنا من المطاردة.",
[1204341744]="أورك وحيد في وجه الأليانس؟!",
[1204720275]="أيعجبك ما فعلناه هنا؟ ربما سنلقي هذه البلورات من السماء فوق أوتلاند بأكملها.",
[1205306229]="لقد أعدت ترتيب كود الرد - سيتم تجنيب كوكبك. لم أعد متأكدًا من حساباتي بعد الآن.",
[1205450634]="يجب أن تتذكر روعة الحياة، $Gأخي:أختي;. لقد كنت بطلًا من الكالدوري يومًا! هذا ليس أنت!",
[1207193038]="أمنيتي الوحيدة هي خدمتك، أيها العظيم، حتى أموت تحت قدمك!",
[1207873635]="لن أعود حتى يُسمع صوتي. الأمر خطير جدًا.",
[1207979378]="آه... المرض قوي. وهو يهاجم العقل...",
[1208128507]="كدت أنجح! فقط القليل من الوقت...",
[1208430244]="بالحظ، سنحصل اليوم على بعض الندوب الجيدة.",
[1208904109]="كما أن هذا اليوم يمثل نهاية، فهو أيضًا يبشر ببداية جديدة...",
[1209380103]="طاقة الفراغ تتجمع عند قاعدة %s!",
[1209735346]="ريبّيت! لا!! هذا لا يمكن... ريبّيت... أن يكون! لقد خدعتني... ريبّيت... بمكرك القذر! ريبّيت!",
[1210030087]="أقراصك جاهزة الآن! استخدم أقراص نورغانون مرة أخرى لاسترجاعها!",
[1210937513]="اقتلوا كل من يرانا! يجب ألا يصل الخبر إلى إيليدان.",
[1211261172]="ما هذا؟",
[1211522739]="نحتاج المزيد من اللحم!",
[1211710215]="سيدي، حكمتك لا يضاهيها إلا ضخامتك!",
[1211886464]="لكن... لكن... لقد كنت مثاليًا!",
[1212201001]="الآن، في شاتراث سيتي: زعماء التاورن! يعزفون في حانة نهاية العالم بعد قليل!",
[1212241510]="لقد سئمت من المجاملة مع أمثالك أيها الهيومن! ما هو \"الداون القرمزي\"؟",
[1212248062]="حراس، انتباه! لدينا زوار...",
[1212500041]="مستعد للدفاع عن شعبه مهما كان الثمن.",
[1212549437]="ما كان عليه أن يغضبني. يجب أن أذهب... لأستعيد قوتي الآن...",
[1212641664]="أعتقد ذلك.",
[1212645584]="أنا لا أخاف منك! هل تريد القتال؟ هاه، تريد؟ تعال! سأقاتلك وكلتا يديّ خلف ظهري!",
[1213001895]="الإذن بالتحليق فوق البرج!",
[1213765867]="ما تبحث عنه موجود في عرين السيد، لكن يجب أن تدمر تيرانوس لتدخل. الآن، داخل هولز أوف ريفلكشن ستجد فروستمورن. إنها... إنها تحمل الحقيقة.",
[1213856576]="سيترك غريت فاذر وينتر هدايا للجميع تحت الشجرة في أورقريمار. أتساءل ماذا سيجلب لي هذا العام.",
[1213924959]="لااااااااااااااااااا!",
[1214069796]="استسلم... لعناق الموت البارد...",
[1214422743]="اهوني، قوتك لم تعد تنمو!",
[1215090691]="انهض، أروقال! قوة الـليتش كينغ تأمرك!",
[1215288665]="العدو سيعاني كثيرًا، يا سيدي!",
[1215689175]="قوة %s تتضاءل مع تكسر قطع الصخر.",
[1216424234]="ابتعدوا، أيها البشر. لم آتِ لقتالكم.",
[1217280793]="%s ينهض، مشيرًا إليك لتركبه.",
[1217437499]="آآآآه! لا... تفرحوا! انتصاركم أجوف، فسأعود بقوى تفوق خيالكم!",
[1217552744]="شكرًا لك على هذه الشارات، $N. سأرسل أخبارًا لعائلات الموتى.",
[1217614090]="الـ%s يبدو مبتهجًا.",
[1217856494]="الـدراكاري سوف يقتل أي أحد يتعدى على هالأراضي!",
[1217983636]="مساعده، ايلكرود ماقثرول، عنده كتاب يمكن يدل على مكان باقي أحجار الروح.",
[1218733698]="قد يقول العجوز أمورًا أخرى، لكنك ستكون دائمًا عبدًا لغوريجيك.",
[1218885905]="أولًا تحتاج البهارات.",
[1219146099]="التطهير يبدو متقدمًا عن الجدول.",
[1219310054]="%s يتبع $N بسعادة كشتلة جديدة لـ$Gخاصته:خاصتها;.",
[1220349244]="هذه منارة لك، $N. يجب أن تبقى معك لكي تجد العناصر الملوثة التي سنحتاجها.",
[1220424169]="كول-ثاريش!",
[1220437316]="مبروك!",
[1220721680]="حان الوقت لأضع حدًا لجنون أخي.",
[1220932576]="اشعر بغضب الرمال!",
[1221128051]="و... لخدعتي التالية...",
[1221252061]="هذا ليس المكان المناسب لتربية أطفالك. الجو بارد، ولن يكون هناك من يربيهم.",
[1221782307]="لم يحن وقتي بعد، ليس بعد!",
[1222015526]="محطة إسعاف ستورمبايك تتعرض لهجوم! إذا تُركت دون رقابة، سيستولي عليها الأليانس!",
[1222023812]="أوبس! كان ذلك بعيدًا قليلاً. لم أصب الهدف حتى!",
[1222525624]="شكرًا لك، يا صديق.",
[1222843710]="لا تختبرني، أيها الكلب الجربان! أنا مدرب على طريق بلود نايتس!",
[1222852098]="%s يتناثر الدم في الهواء!",
[1222862153]="وداعًا، تاريثا. لن أنسى طيبتك أبدًا.",
[1223249468]="أنت منظر جميل... ليس لديك فكرة.",
[1223496171]="سأسحق جمجمتك تحت حذائي!",
[1223586550]="أنا... لم يكن مقدرًا لي النجاة من هذا الهجوم!",
[1224060133]="المصل سيأخذ بضع دقائق فقط لتحضيره، $N.",
[1224178929]="السرب سيتغلب عليك!",
[1224208694]="لا تقلق؛ سأستفيد منك جيدًا!",
[1224495419]="غير قابل للتدمير.",
[1224580093]="أجل، يا سيدي!",
[1224835836]="الـديفورر ينتظر...",
[1224985130]="والآن الأمر يعود لكم أيها الأبطال لتنتقموا لنا جميعًا. المهمة أمامكم عظيمة، لكنني سأمدكم بمساعدتي بقدر استطاعتي. يجب أن تنتصروا.",
[1225202913]="نيثروك؟! هذا الشيء سيسحقك أرضًا بخطوة واحدة من قدمه الضخمة! لا شكرًا!",
[1225281432]="ستموت بسبب غطرستك، $C!",
[1226220753]="ثاين باناهوق الـديثبلو سقط على يد $N و$Gرفاقه:رفيقاتها; في القتال. $Gأمامه:أمامها; تحدٍ واحد فقط. من سيكون خصم $Gه:ها;؟",
[1226248846]="%s يصنع |cFF00FF00إنفرنال فولكانو!|r",
[1226610157]="ماذا؟ أنا فقط أقول إن هكذا نفعل الأمور في قريزلي هيلز.",
[1226683109]="أي نوع من المرضى أنت؟",
[1226856604]="الأليانس دافع عن حصن وينترقراسب!",
[1227252177]="طائر $R قادم! أسقطوا $Gإياه:إياها;!",
[1227503359]="%s يبدأ بفرك دمعة الأقمار.",
[1227784093]="الصليبية الفضية لا تستسلم أبدًا!",
[1228008685]="%s يلقي |cFF00AACCتجميد عميق|r على $N.",
[1228141987]="سأتعامل مع هؤلاء الأوباش! اهجموا الآن يا أصدقاء! اهجموا على الخائن!",
[1228393969]="لماذا يستمر في إخباري أن أضع اللوشن في السلة؟ أنا لا أحب اللوشن!",
[1228597571]="بالادن! قتله سيسعد السيد. اهجموا!",
[1228834621]="اسمعوني أيها الأتباع! اسمعوا سيدكم أنتيوك! ضاعفوا جهودكم أو تحملوا عواقب الفشل!",
[1229959644]="خذ مثلاً هذه العجوز الهادئة التي تنتظر زيارة حفيدتها... بالتأكيد لا خوف من هذه السيدة العجوز ذات الشعر الرمادي اللطيفة!",
[1230613733]="شكرًا لكم، أيها الأرواح.",
[1230655161]="سننتقم... يومًا ما.",
[1230719342]="تخذلني وسيكون ذلك هلاكك...",
[1230983604]="قل لي، بريند، همس لي بشيء حلو، هاه؟",
[1231105028]="هذا الشر الذي أطلقته... في يد من تكمن الآن القوة التي منحتها لي إلهتي... وبيد من تُوجه؟",
[1231557307]="%s يقترب بحذر من واتشر إلائرا.",
[1231662248]="لا يمكنكم هزيمة اللهب الحي! تعالوا يا أتباع النار! تعالوا يا مخلوقات الكراهية! سيدكم ينادي!",
[1231678018]="هل ظننت أنني لا أستطيع رؤية تنكرك الواهي، $N؟",
[1231798658]="كان يجب أن أكون أنا!",
[1231959429]="الطفلة تريد دميتها!",
[1231989684]="$N، هل تشعر بالحاجة... الحاجة للسرعة؟",
[1232368689]="آخر عشر سلالات من أندرسِتي... كلها عديمة القيمة!",
[1232820885]="يبدو أننا على الهدف.",
[1233557857]="الشرف، الشجاعة، الرحمة والعدالة! هذه كانت الفضائل التي قاتلت من أجلها ككاهن في فجر الفضة، ثيلزان.",
[1233571046]="كيلثوزاد؟ إذا كنت تعرف هذا الاسم على الإطلاق، فربما قرأت الكتاب الذي أرسلتك لإحضاره.$B$Bللأسف، إجابتك خاطئة.",
[1233610336]="أكشف خدعتك. أنت بالادن بعد كل شيء. هوسك بالخلاص يتجاوز التفاهة.",
[1233683260]="أنت! أراك! واحد منكم، اقتلهم!",
[1233718517]="إليّ، يا خدمي!",
[1233882945]="%s يبدأ في إلقاء تعويذة بينما تأخذ العباءة منه.",
[1234322741]="النوع: إيريدار",
[1234387994]="إذا سمعت الهمس، فأنت تموت...",
[1234722744]="لم أبدأ بعد... في...",
[1234826083]="هؤلاء الدراكاري مجرد أخبار سيئة. يجب أن نغادر ونتوجه إلى حصن العدالة!",
[1235974096]="سكوت مرسر! جيف, وايت، جو، ترافيس، كريس، ستيفن! برازي!",
[1236473442]="%s يبدأ في استدعاء نايتماير اليقظة!",
[1236783707]="أستطيع رؤية زملائي الدرويدز من هنا. شكرًا لك، $N. أنا متأكد من أن يسيل ستكافئك على أفعالك!",
[1236887983]="أوه... هالان، ما كنت أعتقد أنك تملك هذا في داخلك...",
[1237450631]="وجه مبتسم من الأذن إلى الأذن...",
[1237750788]="بالتأكيد لن تدمر فرصة البشرية الوحيدة لاسترداد ابنها الضال. ستموت قبل ذلك!",
[1238254036]="من الجيد عودتك، فاروك، يا صديقي القديم. أنا آسف بخصوص ابنك.",
[1238370916]="%s يبدأ في إلقاء انفجار نوفا!",
[1239317281]="لقد تم الأمر. اخدِم النور جيدًا.",
[1239842029]="تم! تراجعوا! تراجعوا!",
[1240215152]="$N، كنت سأعرف هذا العفن في أي مكان... ماذا... ماذا فعلوا بك، $N؟",
[1240217956]="هيا نلعب! لا، احكِ لي قصة يا بابا! لا... هيا نلتقط الزهور! ونلعب وقت الشاي! لقد وجدت دميتي، هل أخبرتك؟",
[1240572509]="اسمح لي أن أحضر بعض الماء لمادة الحبر.",
[1240993389]="معتاد. فقط عندما كنت أستمتع...",
[1241240736]="امضِ قدماً بدوني! سأشق طريقي بنفسي إلى تارين ميل.",
[1241605808]="شكراً لك. ظننت أنني سأموت دون أن أرى أخواتي مرة أخرى!",
[1241815002]="ومع ذلك، سيتحمل بلود نايتس هذه الخسارة. ليس لدينا خيار آخر... يجب أن نجد مصدراً آخر.",
[1241854234]="...في قلق أبدي!",
[1242091240]="مئة صندوق من الشعير هناك لصنع الميد!",
[1242380622]="نقيق!",
[1242650059]="موت، أيها الغريب!",
[1242735635]="هذا الفساد المظلم سيء جدًا للأعمال.",
[1243809661]="لديه أسبابه، إيدونيس. يعتقد أن الفارسترايدرز اكتشفوا شيئًا.",
[1243841737]="مرحباً، $C.",
[1244407938]="الملك ستورمهارت يختبرك، هاه؟ لا بد أنه رأى شيئًا فيك، وإلا لما أظنه سيجعلك تخوض هذه الطقوس المقدسة.",
