[1298485481]="حسنًا، ها نحن ذا. سيستغرق الأمر حوالي خمس دقائق لإغلاق هذا الشيء من خلال الطقوس. بمجرد أن أبدأ، أبقِ الحشرات عني وإلا ستكون نهاية الجميع!",
[1298808341]="ماذا؟! لا يهم. حتى بدون كرتي، سأسحقك! تأمل هويتي الحقيقية وايأس!",
[1299036900]="ماذا كنت تفعل قبل أن تأتي إلى نورثريند؟",
[1299057912]="مصيرك محتوم، أزيروث! سأجد شظايا الأسبكت، وعندها لن تقف أمام قوتنا!",
[1299289963]="حرر أي هورد سليفز تصادفه. سنحتاج بالتأكيد لمساعدتهم في محاربة تيرانوس. سأجمع تعزيزات وأنضم إليك على الجانب الآخر من المحجر.",
[1299730635]="سأقتلك، $N!",
[1300737597]="ماذا؟! من يجرؤ على إزعاج البيرنينغ ليجيون؟",
[1300773051]="مع القليل من التحرير الإبداعي، هذه أصبحت أكثر فائدة...",
[1301182481]="أنت على حق، أيها الروح. شعبي هو من فعل بك هذا. اسمح لنا بتصحيح الأمر.",
[1301397269]="لا داعي لشكري، قاروش. والدك كان أخًا لي. سأفعل أي شيء من أجلك ومن أجل الماغهار. يجب أن أعود الآن إلى الأم العظيمة.",
[1301662411]="أنت ابق هنا. أنا أروح أقتل شخص ثاني!",
[1301917836]="رغم أننا نواجه صراعًا عظيمًا، فإن قوتنا مجتمعة ستمحو أولئك الذين يعارضوننا! المظالم الجسيمة التي ارتُكبت بحق الـهورد سيقابلها قوة لا تُقهر من الحساب!",
[1302006497]="كما يأمر أنوبراك!",
[1302216094]="تم التحقق من سلامة معبد الاختراع.",
[1302395438]="لا شيء يُهدر في هذه العملية. سترى...",
[1302458295]="أبعد هذه الأشياء عني!",
[1302581622]="يجب أن أودعك... إلى اللقاء.",
[1302715068]="هذا العالم سيحترق!",
[1303295210]="قف بجانبي، $N. سأحميك إذا حدث أي خطأ.",
[1303621923]="من أجزاء مجهولة: سكرّاقاث! هل يمكن لـ$N النجاة من هجوم طاقات الفراغ؟",
[1303844112]="معركة ملحمية، كم هذا مثير!",
[1303943607]="لذيذ جدًا...",
[1304418600]="سنأخذ رؤوسكم!",
[1305318996]="لقد شهدنا جميعًا مأساة مروعة. لقد أريقت دماء الرجال الطيبين على هذه الأرض! فرسان شرفاء قتلوا وهم يدافعون عن حياتهم - حياتنا!",
[1305995331]="أناخ كيري!",
[1306610138]="بشر صغار - أنا هنا! الموت ينتظركم!",
[1306727245]="لكن يكفي كلام... لقد قاتلتم بشدة وأتيتم من أقاصي هذا العالم لمواجهة دسك برينغر. لن أخيب ظنكم...",
[1307472019]="وها هي، سبيريت أوف نوميريغان!",
[1307601810]="تم التحقق من أن المراقب هودير لم يعد موجودًا. اكتمل التحليل.",
[1310305466]="مهلاً، بلانشي، لا يمكنك أكل أي تفاح اليوم. غدًا سنأخذك إلى ساوث شور، حيث ستستقل قاربًا عبر البحار.",
[1310455755]="أعتقد أنني وجدت التي سأستخدمها. الآن علي أن أبدأ في نحتها. لا أعتقد أن الأمر سيكون سهلاً. لا أعرف حتى كيف يبدو صوت نداء التزاوج لأنثى اليتي!",
[1310621182]="أرى ذلك يحدث في وقت ما بين الغد والعقد القادم. بالتأكيد.",
[1310872150]="سيصبح صولجاني كاملاً مرة أخرى!",
[1311830014]="يا إلهي، يا لها من مفاجأة! فشل آخر!؟ ولكن كيف، أيها العظيم؟؟",
[1311847727]="لدي بعض الإضافات معي؛ إذا رددت لي ما دفعته مقابلها، يمكنك الحصول على واحدة. لدي أيضًا بعض الطعم.",
[1312088496]="هل الطريق واضح؟ لنخرج بينما نستطيع، $N.",
[1312482856]="مخلوقات صغيرة، أنا أدوسكم!",
[1314718981]="أنا جائع.",
[1315536342]="هذه حرب، دام أوريفيروس، وفي أي حرب ستُفقد أرواح! المناطق الوحيدة التي نحتاج لتأمينها هي الزقوراتان. سنتحصن ونسيطر على برج الـ دامند وسيده بالقوة الغاشمة. عندها ستحصل على كويل'ثالاس الخاص بك.",
[1316118860]="أمسك بهم!",
[1316523027]="تخلوا عن الهجوم القرمزي! لا تستمعوا بعد الآن لأكاذيب الجنرال الأعلى والأميرال الأعظم!",
[1316780841]="اسمعوا، اسمعوا! سأتوقف لبيع بضاعتي لفترة قصيرة فقط هنا في ليكشاير. تعالوا إلى قاعة البلدة بسرعة!",
[1316784887]="الألم والمعاناة فقط في انتظاركم!",
[1317412198]="أنا أوغسطس، وأسعاري جنونية!",
[1317506677]="أنا مجيء النهاية!",
[1317518050]="كفى ثرثرة. أنا أتضور جوعًا! الآن، أدخل غوكعتك المغبرة إلى ذلك المحيط وأحضر لأمك بعض الطعام.",
[1317618891]="سأحرقك!",
[1318440586]="اخنق بمعاناتك!",
[1318685445]="أجل، هو القائد الثاني لعبادة التنين في كوفن بلاك وينق إلى الغرب.",
[1318701700]="قروبولوس، أول ما كان سيكون جيشًا من العمالقة اللحمية. حمل سائل الطاعون من ناكسماراس داخل جسده، محقنًا الوحل الحي في أجساد أعدائه. من يتلقى هذا الحقن النجس كان عادةً يهرب إلى حلفائه، مسقطًا إياهم معه.",
[1318867174]="أتعلم، هناك تمساحيات في القنوات. تم إحضارها من المستنقع كحيوانات أليفة، لكنها ألقيت في القنوات.",
[1318872979]="فجأة، كانوا في كل مكان.",
[1319176079]="أنت لا تتذكرني، أليس كذلك؟ الـسكورج الملعون... لقد حاولوا تجريدك من كل ما جعلك قوة صغيرة مرعبة. كل ذرة خير فيك... كل ما جعلك نومة!",
[1320701709]="تندفع بتهور نحو حرب شاملة دون تفكير في العواقب.",
[1320742865]="بيتسي! أعيدوا لي بيتسي!",
[1321127407]="ألقِ نظرة على هذا المقطع...",
[1321186711]="الآن، كل من في هذه الحانة سيخفض صوته أو جيسن العجوز سيخرج شوبكه وساطوره ويصير أورك عليكم! هل هذا واضح؟!!!",
[1321372272]="كان الأمر فظيعًا. كنت لزجًا بالكامل، وكنت ألعق عيني باستمرار!",
[1321817058]="ما كان ينبغي تاخذ القارب للشمال، مون!",
[1321924398]="لنجرب زراعتها في بعض تربتي الخاصة المحضرة...",
[1322332026]="ياعرررر... مت مرة أخرى!",
[1322485038]="كل لحم يجب أن يحترق.",
[1323277797]="هذه الجعبة - ذيلزانز فيلاكيري - هي مفتاح النصر!",
[1323470769]="ظننت أنك ستقف أمام جيوش الموت وتنجو؟",
[1323528810]="لن تكون لك حياة أبدية!",
[1323944362]="دوارف ستورمفورج يتدفقون من الجثة المحطمة!",
[1324302751]="لا أملك القوة لإرسال الإشارة. يجب أن... تسرع... تجد مكان قوة... قريب من السماء.",
[1324321613]="محتوى حمضي قوي موجود نظريًا داخل الكائن المعروف باسم يوق سارون قد يفسر تسييل السارونايت. الغمر في هذه المادة قد يكون كافيًا لإعادة ربط سبيكة من أصل تايتن.",
[1324427149]="لدي المكان المثالي لهذا القرن!",
[1324432362]="ماذا، بقبضاتي؟",
[1324637438]="عد إلى يوتنهايم وأخبرهم أن يبقوه نائمًا حتى أصل. سأحكم على هذا الفايكرول بعيني.",
[1324660643]="ستينكبيرد جايلكم، يا صغار!",
[1324973507]="ستسقط كما سقطت أراضيك ومدينتك من قبلك. سينتصر سيدي هنا نصرًا عظيمًا، ولن يتذكر أحد اسمك!",
[1325022491]="القدر لا ينتظر. يجب على حرفيّيك زيادة إنتاج الغولم الحربي قبل أن يصل زعيم العمالقة الحجرية وجيشه إلى اولدوار.",
[1325452767]="ريفينوس وورق يلتهم مستر فلوبي",
[1325490978]="لن تحصل على شيء حتى تتكلم، أيها الحقير!",
[1325980004]="مرحبًا، عشيرة ترياس! كرة من جبن الموزاريلا المدخن، لو سمحتم!",
[1325986458]="أيها الروح العظيم للهواء، اسمع ندائي مرة أخرى!",
[1326284212]="نحن بأمان... الآن. قوته تضاعفت عشرة أضعاف منذ معركتنا الأخيرة. سيتطلب الأمر جيشًا عظيمًا لتدمير الـليتش كينغ. جيشًا أعظم ملا تستطيع الـهورد حشده.",
[1326366940]="والآن للسباق التالي، ستكون السيارة أسرع من قبل!",
[1326997661]="%s يُجبر أحد أتباعه من فايرسورن على الانفجار!",
[1327079935]="%s يحصل على رائحة الدم من بلود بيستز!",
[1328371215]="مع مرور الوقت، وبالطاعة لتوجيه النور، يصبح المرء أكثر حساسية لصوته وقوته.",
[1328531901]="إنها محاولة إنقاذ! اقتلوهم جميعًا!",
[1328811609]="اليوم أود أن أتحدث عن الفضائل الثلاث للنور.",
[1331131570]="أنا لست مقبلات!",
[1331228300]="انظروا الآن، أيها البشر - إلى قلب مورو! نقي. مغسول بنور الخلق - كما كان عند الفجر.",
[1332230710]="كان سيستغرق الأمر سنوات للعثور على كتاب ريفن بدونك، أيها الصقر الصغير. عد إلى منزلك في ناقراند بامتناننا.",
[1332472286]="%s يضع حزمة الدمثيستل في ردائه.",
[1332848932]="الدوارف الحديديون تبعوك! استخدم الشبكة والانزلاق الجليدي للهروب!",
[1333289258]="لا! أنت مخطئ! الأصوات في رأسي جميلة!",
[1333501385]="إذا لقيت اللي تسببوا في التحطم...!",
[1333567146]="قوة النور تجبرك! ارجع لحفرتك!",
[1333692380]="عقبة أقل نتعامل معها.",
[1333724483]="أنا... لا أصدق! فروستمورن أمامنا - بدون حراسة - كما ادعى النوم. تعالوا، أيها الأبطال!",
[1334091092]="ارجعوهم إلينا، وسنساعدكم.",
[1334120932]="%s يفحص القلب الملفوف بالطحلب...",
[1334512851]="انتصار سطحي ومأساوي. نحن أضعف ككل بسبب الخسائر التي تكبدناها اليوم. من غير الـليتش كينغ يمكن أن يستفيد من هذه الحماقة؟ أبطال عظماء فقدوا أرواحهم. ولأي شيء؟ التهديد الحقيقي يلوح في الأفق - الـليتش كينغ ينتظرنا جميعًا في الموت.",
[1334541754]="أجل أنفينا! دع القدر يعانقك الآن!",
[1334969702]="%s يهز رأسه.",
[1335192411]="كابتن ريدباث ظهر في ساحة المعركة! احموه!",
[1335373475]="أيها الأحمق! لن تفلت بهذا أبدًا!",
[1335928945]="%s ورايدر كير تركا ذئابهما ترتاح قليلًا وتشرب...",
[1336020304]="لطالما تائهت في صورتي الملعونة. لقد حررتني... سأكافئ عملك الشاق.",
[1336938952]="إن ترددنا أكثر، فستكون هناك جحيم يدفع ثمنه!",
[1337714979]="...",
[1338196986]="...احصل على خصم 50 بالمئة على ملابس الهاربين الداخلية؟ ما هذه القمامة؟",
[1338438362]="هاي لورد تيرييون فورديرينق يقترب من المنصة ليخاطب المجتمعين في أرض البطولة! أفسحوا الطريق إلى منطقة المنصة لاستقباله!",
[1338464299]="الآن سأريك القوة الحقيقية للأونسلاوت!",
[1338757236]="الـليتش كينغ يعرف حدودك أيها الهاي لورد. يعرف أنك لن تطلق النار على رجالك. ألا تفهم؟ ليس لديه حدود. لا قواعد يتبعها.",
[1339202014]="آه! كل مرة أحمل شيئًا إلى العربة، يظهر هنا مجددًا في لحظات!",
[1339950480]="سنين... ضائعة...",
[1339954644]="البرج الغربي فروست وولف دمره الأليانس!",
[1340061233]="أرواح الماء، أحمدك وأتوسل إليك بمعروف. لقد سمعت تضرعات $N، وأنا أثق أن نية $Gخاصته:خاصتها; نبيلة. أرجوك، هل تساعدنا؟",
[1341146414]="بالطبع! أي شيء من أجلك، عزيزي!",
[1341343879]="لست متأكدًا أن هذا آمن، أيها الجيست الصغير.",
[1341790629]="عند مواجهة أي ساحر، هذا الوحش المتوحش سيكون أفضل صديق لك. الآن، دعنا نلقي نظرة على شيء مختلف قليلًا. هذا المخلوق التالي سيساعدك في رحلاتك ويجعل رحلاتك المستقبلية أسهل بكثير. دعنا نلقي نظرة على الفيلستيد.",
[1341875917]="واو! حقًا؟",
[1342031913]="توسل للرحمة!",
[1342129895]="تم الأمر، أيها التنين. قُد الطريق.",
[1342158032]="الشيء الميت هناك تعلم بالفعل درس العمود المكسور. اترك هذا الدرس للأشياء الميتة الغبية. سأعود للبيت الآن.",
[1342608796]="أعتذر، نوزاري. لقد كنت متوترًا بعض الشيء مؤخرًا. هذه المخلوقات تحاول تغيير مسارات الزمن.",
[1342839291]="%s ينظر باشمئزاز إلى مغازلة الديثستوكر.",
[1342966015]="تعامل مع هذا $N! أحتاج أن أستعد لإيقاظ ناراليكس!",
[1343348709]="عمل ممتاز!",
[1343403865]="حاضر؟",
[1343679767]="%s متجمد تمامًا!",
[1343762292]="تعال من أجل البيرة، وابقَ من أجل الأجواء!",
[1344033409]="جرب الخنزير! إنها وصفتي الجديدة!",
[1345302583]="%s يلتهم الطعام.",
[1345460314]="أُمرت قوات كيراجي بالانسحاب وإخفاء معظم أعدادها تحت رمال الصحراء. تم الأمر بهجوم صغير على قرية ساوث ويند بينما كانت الخطوط الأمامية لجيش ستيغهيلم مشغولة.",
[1345667635]="الـليتش كينغ قد تحدث إلى كل واحد منكم! دع كلماته تتردد بينكم مرة أخرى!",
[1346610180]="ديستركتيف وارد مشحون بالكامل!",
[1347686978]="ماذا جلبت لنا رياح النيذر؟",
[1349438525]="كدت أنتهي...",
[1349742380]="من أجل الأليانس! لحظة... من أجل الـهورد! لحظة... أي واحد كنت أنا؟",
[1349894890]="يا للوقاحة! يا للغرور! أتظن أنك تستطيع هزيمتي على عتبة داري!",
[1350098531]="أسحقكم أيها الصراصير!",
[1350170108]="هذا المكان تحت حمايتي. أسرار السحر ستبقى مصانة.",
[1350278951]="قد نكون قليلين، سوكرثار، لكن إيماننا قوي. شيء لن تفهمه أبدًا. والآن بعد أن تمت مراسم العرف، استعد للقاء نهايتك.",
[1350688944]="تفوقت عليك!",
[1350902459]="هل هناك شيء يحدث؟ أسمع أصواتًا غاضبة.",
[1350944776]="لا يمكنك الفوز. ليس هكذا...",
[1351012080]="هل زرت مزرعة جاجدسواين من قبل؟ عندما تبلغ الخنازير سن الذبح... ذلك الصوت. صوت الخنازير وهي تُذبح... يتردد بأعلى صوت. تلك أوقات صعبة لنا نحن المحاربين القدامى.",
[1351052195]="انظروا! شاهدوا الأرض تتحطم أمامنا! شاهدوا الطاقة تتدفق! ستغذي جيوشنا...",
[1351168916]="إخوتي استيقظوا. جهودكم تذهب سدى...",
[1351268024]="ما عندكم تحدي لي يا ضعاف! أنا الملك الآن، وسأبقى ملكًا إلى الأبد!!!",
[1351864927]="لقد... بذلت قصارى جهدي.",
[1352068010]="تعالوا يا سكان البر، واجهوا غضب الناب والشارب!",
[1352187589]="موتوا أيها المتسللون! لا أحد سيتدخل في خطط العبادة!",
[1352282016]="%s يرفع المزيد من الهياكل العظمية!",
[1352785310]="%s يمسك تفاحة من الشجرة.",
[1352861844]="لا أصدق أن الزرق سيهاجموننا. دعنا نرد لهم بعضًا منها!",
[1353233976]="مقبرة ستورمبايك تتعرض للهجوم! إذا تُركت دون رقابة، سيستولي عليها الـهورد!",
[1353534247]="القدر... ينتظر.",
[1353543575]="توقف! يجب أن تتوقف!",
[1354072200]="شكرًا لك وداعًا يا صديقي. يجب أن أعود إلى طليعة الأرجنت.",
[1354209830]="متوقع جدًا. كنت أعلم أنك ستأتي. وأرى أنك أحضرت هيلسكريم العظيم.",
[1354459967]="ابدأ بفعل شيء قبل أن أستبدل ذلك الهدف الوهمي بك وأبدأ جلسة إحماء خاصة بي!",
[1355033095]="اخضعوا لقوتنا! اهربوا! لن يكون هناك نصر للأحياء!",
[1355099096]="يمكنني الوصول من هنا. شكرًا، $N! وتحدث مع صاحب العمل عن المكافأة!",
[1355553971]="ما كان يجب أن نصل إلى هذا!",
[1355576850]="كلاب إيليدان المدللة! دمروهم جميعًا!",
[1355662063]="%s يرد الإشارة الوقحة إلى $N.",
[1355697192]="شيء ما يخبرني أن هذا $N يريد الأحفورة الغامضة أيضًا. النجدة!",
[1356195196]="ورشة حصار سانكن رينج تعرضت لهجوم من الـهورد!",
[1356264305]="أيها الجراء الوقحون، أنتم فقط تؤخرون المحتوم. حيث سقط واحد، سيقوم عشرة. هكذا هي إرادة كازاك...",
[1356912469]="هل ستتركوني هنا فقط؟ كيف سأعود إلى البيت؟",
[1356978812]="أوه... أشعر بالإغماء...",
[1357169413]="هذه الأراضي ستُطهر!",
[1357245792]="همم، المدمرات الأركانية قوية جدًا. أتساءل إذا كان بابا ويلر يعرف ما يطلبه؟",
[1357362523]="سيكون كما تقول، يا محارب الحرب. سؤال أخير، إن سمحت لي...",
[1357592582]="أهاهاهاهاها! لقد تم الأمر. عد إلى كهفي. لدينا الكثير لنناقشه!",
[1357878220]="حسنًا، اهدأوا. لدينا الكثير لنفعله ووقت قليل جدًا، يا ناس.",
[1358716229]="هذا...",
[1358837988]="%s يدخل في غضب ناثري!",
[1358901726]="أعتقد أنني رأيت مفتاحًا على أحد الفرايكول في جاليربرون بالأعلى.",
[1359786558]="الخلاص، أيها الصغير. إنه ينتظرنا جميعًا.",
[1359920115]="%s يشير إلى الشمال الشرقي.",
[1360374551]="أيها المغامر الشجاع، شكرًا لإنقاذي! أنا متأكد من أن مارشال ماريس سيكرم عملك الطيب.",
[1360418955]="س-سيدتي... هل يمكنني ت-تلميع درعك...؟",
[1360518849]="شكرًا لكم، أيها الأصدقاء! جهودكم أسفرت عن بيانات رائعة! الآن، أين وضعت-- أوه، ها هو.",
[1361046337]="المدرسة في انعقاد!",
[1361317762]="ليت والدنا كان على قيد الحياة ليرى هذا!",
[1361778500]="لن أنساك أبدًا، يا صديق.",
[1361979099]="كيف حصلت على جهاز الاتصال الخاص بي من رابطة المستكشفين؟",
[1362549087]="ستالاق اقتل!",
[1362770046]="كور'كرون، جهز أورقريمز هامر لرحلته الأخيرة! أيها الأبطال، سفينتنا الحربية ستجد نقطة للرسو على الأجزاء العليا من القلعة. قابلونا هناك!",
[1363213553]="لقد راهنت. وخسرت.",
[1363413155]="انهض، سيندراقوسا! انهض وقدم الـفروستبرود إلى الحرب!",
[1363446075]="الـغراند وارلوك ويلفريد فيزلبانغ سيستدعي تحديكم القادم. استعدوا لدخوله.",
[1363450597]="لا... بالطبع لا. بماذا كنت أفكر؟ لماذا قد يكون لديك ثلث شيفرة اللعنة؟",
[1363452840]="لاااا! هذا التعذيب لا إنساني! لديك ما تريد... لماذا لا تقتلني فقط؟",
[1363473118]="أنت لغز، هذا ما أنت عليه... ودعني أخبرك، أنا والألغاز لا نتفق...",
[1363697968]="لا تؤذي مشاعر مقّغوك، يا رجال الطيور!",
[1363977529]="هاكار لم يعد يقيدني! أخيرًا سلام!",
[1364000079]="قميص من جلد المحار، ها أنا قادم!",
[1364164457]="هذا لا يبدو جيدًا. مهما فعلت، لا تسقط. هناك الكثير من الأشياء المقرفة في الداخل!",
[1364730013]="لم يعد الفتى الذي في ذكرياتك بعد الآن، مورادين. لقد أصبح شيئًا آخر تمامًا.",
[1364733306]="$N سقط مثل كيس من جماجم الأوركس!",
[1364973317]="ثم رأيناها، الوحش المخيف!",
[1365597786]="أطفال الجنون - أطلقكم على هذا العالم!",
[1365935238]="نعم، هذا أصاب المكان المناسب. كعك للبيع! كعك طازج هنا!",
[1366061590]="شكرًا يا كشاف. استمر في الدوريات. لكن الآن، الراحة واجبة. انصرف.",
[1366339504]="أجل، لكني تمنيت ألا أضطر للإجابة على هذا أبدًا.",
[1366481448]="كيف ترك الجوبلن أدواته هناك إذن؟",
[1366723871]="قف! أستشعر سحرًا مظلمًا. سحر شياطين... استعدوا!",
[1367152632]="عمل ممتاز أيها الأبطال! سنقيم معسكرنا الأساسي في هذه الغرف. سيشغل السحرة خاصتي جهاز نقل الـسكورج قريبًا. ادخل عندما تكون مستعدًا لمهمتك التالية. سأقابلك على الجانب الآخر.",
[1368413310]="سأفصل روحك عن جسدك!",
[1368584739]="هذا يكفي... لا مزيد من الجروج لي!",
[1368606970]="ثريم... انت... انتقم لي...",
[1368811971]="تحيات! أنا حارس المدخل. من فضلك استخدم الأقراص المناسبة للوصول إلى أولدوم.",
[1369501306]="أنا سأسحق صديق التنانين الضعيف!",
[1370118648]="سنخرج من هنا حالما أصلح هذه العربة...",
[1370265625]="اهرب أيها السوفت ناكل الغبي! سنوخزك أكثر!",
[1371025940]="بضع ضربات أخرى وستكون جاهزة...",
[1371217372]="آه، $Gبريست:برايستس;، لقد جئت في الوقت المناسب. أقدر ذلك.",
[1371499462]="سلالة اونيكسيا!",
[1372253982]="كان سينجح لو لم أتعقب أنا و$N فساد نورث ويند التاريخي إلى مصدره: معركتك القديمة.",
[1372515932]="بكل احترام، يا سيدي، احشها!",
[1372594260]="دينغ!",
[1372610774]="فليكن قد تم!",
[1373060850]="مرحبًا بعودتك، $N.",
[1373235605]="كيف تجرؤ على إزعاج عشاء السيد!",
[1373787978]="هيا تعالوا، جميعًا. مرحبًا بكم في معرض داركمون! لا تخجلوا. تقدم إلى لهارا واشترِ لنفسك قطعة أثرية غريبة من أراضٍ بعيدة. إذا كنت من المحظوظين القلائل الذين وجدوا بطاقات داركمون، فتحدث مع البروفيسور باليو. جائع؟ عطشان؟ أنت محظوظ! المشروبات متاحة هنا من سيلانيا وستامب. أوصي بداركمون سبشال ريزيرف لتغسل بها بعض الأجنحة الحارة. وإذا كان المستقبل هو ما تبحث عنه، فاركض، لا تمشِ، لتتحدث مع سايج.",
[1373961898]="%s يصرخ بعواء عالٍ!",
[1374780445]="%s تتبع الرائحة إلى مصدرها داخل الكهف.",
[1374898240]="يدخل الحلبة زولتور النحيل والخطير، البطل الأعظم لسينجين!",
[1375644316]="دوامة ملتهبة تتشكل.",
[1375688273]="أنضم... إلى الليل.",
[1375853536]="%s ينظر إلى أصدقائه ثم يئن بألم.",
[1376126924]="طالما أننا نتبع خطة جديدة، قد ألتقط سلاحًا وبعض الدروع.",
[1376342319]="واجه الآن نهايتك المأساوية.",
[1376884894]="لا أصدق هذا! كنت ميتًا! كل التقارير قالت ذلك... ماذا حدث، مورادين. كيف وصلت إلى هنا؟",
[1376903278]="لا عودة الآن، $N. ابق قريبًا وراقب ظهري.",
[1377356516]="هذه جلودي يا هارولد. الآن أعطني المكافأة!",
[1378132898]="%s يحفر طريقه للخروج من الرمال لحماية بيضه.",
[1378511865]="5 ثوانٍ حتى الانفجار!!!!!",
[1379101834]="أنوب'يت'كان سينهيك.",
[1379300477]="هل نقتلهم لوقاحتهم بإزعاج نومنا؟",
[1379419193]="أعرف كيف أتكلم لغة القطط، وإف سي قال شكرًا.",
[1379782853]="حسنًا، لنرى كيف نستخدم الفطر الذي أحضرته لزراعة مصدر غذاء جديد لأسياد المستنقع.",
[1380168681]="نعم! لقد نجح الأمر!",
[1380304926]="دمّر العدوى الترابية.",
[1380410634]="لدي شيء لك...",
[1380598457]="مت $N، مت!",
[1381317866]="%s يندفع نحو الـليتش كينغ، حاملًا آشبرينغر، ويضرب الـليتش كينغ.",
[1381519297]="%s يبدأ في توجيه قوى النور.",
[1381635995]="لا ترغموني على ذلك، أيها الصغار! سأستخدم جلودكم لتبطين حذائي.",
[1381816489]="أتريد تعلم الحجر؟ اتبعني.",
[1381904815]="حيث رائحة الموت في الريح وكل شيء بني في الغالب.",
[1381946782]="بالزاوية والسرعة المناسبة...",
[1381984308]="حكمك المتجمد لن يتحقق!",
[1382332684]="الأدلة تشير إلى معركة كبيرة. خصم المراقب فريا يُقدر بحجم وقوة مماثلين للمراقب فريا.",
[1383164082]="ظننت أنني سأموت هناك!",
[1383494189]="لونغرانر، مؤونتك... إيه، شعبك سيكون موردًا قيمًا ضد الفرايكول. هل قلت مورد؟ قصدت 'حليف'.",
[1383981063]="يستمتعون بإحداث الألم والعذاب - واستجواباتهم القاتلة هي كوابيس مرعبة.",
[1384044748]="متأكد إننا رايحين الطريق الصحيح، مون؟",
[1384456705]="يا لها من مجموعة مجانين! هل تصدقون هذا الكلام حقًا؟",
[1385137874]="أوه أوه! يبدو أن كل هذه الضجة التي أحدثتها جذبت انتباهًا غير مرغوب فيه!",
[1385169496]="دافع عن نفسك، رغم أن ذلك لن يفيد...",
[1385355815]="ووو! شكرًا!",
[1385658559]="شكرًا لموافقتك على المساعدة. الآن، لنخرج من هنا، $N!",
[1386066006]="وسط الحثالة، تم العثور على بطل.",
[1386502107]="شيء كبير صنع الأعمدة والبلورات وكل شيء. فرينزي هارت لا يهتم كثيرًا لأنه لم يعد هنا الآن.",
[1386520063]="%s يشرب شرابه.",
[1386680672]="لا مستقبل لك.",
[1387046829]="غير معقول! البشر سيدمرون... كل شيء! أختي، ماذا فعلتِ...",
[1387176310]="لا تتركوا ناجين!",
[1387240436]="نات، سمعت قصة أو اثنتين في حياتي لكن هذه تفوق الجميع.",
[1387647569]="ما تتذكرني، صحيح؟ الـسكورج الملعون... حاولوا ينشفوك من كل شيء خلّاك قوة حقانية. كل ذرة خير... كل شيء خلّاك $Gابني:ابنتي; من آيرونفورج!",
[1387690358]="تريد شراب؟! عندنا شراب!",
[1387693337]="عيون %s تتوهج باللون الأحمر وهو يبدأ بالقهقهة بجنون!",
[1388035126]="لكن... اتبعت تعليماتك بدقة! آسف؟",
[1388041695]="'عد إلى اولدوار، المحتضن في أحضان العاصفة.'",
[1388163721]="يجب أن نحافظ على البوابة. هاجم! مزقهم إربًا إربًا!",
[1388265526]="ظلهم سيخنق الأرض إلى الأبد.",
[1388955127]="دمك سيكون المحفز لعودة الآلهة القديمة!",
[1388965056]="بنجامين، صديقي القديم، هل يمكنك توفير تفاحة لـ بيسي اليوم؟",
[1389232908]="حسنًا! الطيور هناك! مقّغوك سيجد أصدقاء جدد!",
[1389396502]="أعداء وينترسكورن، ستمزقون إربًا إربًا!",
[1389434971]="ما كنت أعرف أن النحل ما يحب النار!",
[1389774260]="بوابة الجمشت الأرجواني دمرت!",
[1389911404]="على الأقل ما سنكون موجودين لكي ننظفها.",
[1389986218]="آه، أن تُنتشل من الكابوس المرعب! أشكرك يا تلميذي المخلص، ورفاقك الشجعان.",
[1390080050]="اشرب دمك. كل لحمك.",
[1390352993]="تم زرع بليسد بانر أوف الـ كروسيد.$Bدافع عن الراية من كل المهاجمين!",
[1390638102]="حياتي من أجل يميرون!",
[1390973835]="أوه! داجيك عنده فكرة! سوّي أصوات دجاج ويمكن يجونك!",
[1391095830]="شفت تحديات أحق منك في حلبة الدم. أنت تضيع وقتنا، أيها البالادن.",
[1391978661]="الـسكورج اخترقوا! اهربوا! اهربوا!",
[1391989844]="سنجد هذه الكلمات. سنستدعي سيدك وسندمره.",
[1392121607]="وحوش حقيرة!",
[1392883257]="سأنهض مجددًا، أقوى... أكثر بكثير...",
[1392932318]="اغرس أسنانك في تفاحة طازجة ناضجة.",
[1393323715]="أخيرًا بعض الحديث عن الفعل من الرجل الكبير!",
[1393807599]="ها نحن مرة أخرى، سيداتي وسادتي. الصراع الملحمي بين الحياة والموت في مدرج العذاب! لهذه الجولة لدينا $N ضد الجورمونغار الضخم، يغ... يغد؟ يغدوز؟ من يأتي بهذه الأسماء؟! $N ضد الدودة الكبيرة!",
[1394042977]="عبد القوي مثل الثور!",
[1394415532]="يحتفظون بأدواتهم في صناديق تشبه هذه. ابحث عنها بالقرب من الأجنحة.",
[1394466841]="عمل ممتاز.",
[1394845542]="$R الغبي اللين. هذا السلاح ملكي الآن! أعط!",
[1395177752]="ح تموت قريب!",
[1395206834]="احموا الميكانار بأي ثمن!",
[1395480152]="لماذا استدعيتني بهذه السرعة؟ ما زال ما وصلت لقوتي الكاملة!",
[1395604744]="لن أخبرك بشيء، يا واعظ.",
[1395871461]="%s يقفز من الظلال!",
[1396604122]="المصمم الأول؟ من أين سمعت هالاسم؟ بلحية جدي، لوكين هو المصمم الأول لـأزيروث. موت لوكين هو اللي فعل هذا!",
[1396996837]="الدم القديم سوف يتدفق مرة ثانية مع مجيء الغراب، وعودة الظلام في السماوات. ليلة قرمزية، وصعود القديم.",
[1397139672]="قوانين المعرض سوف تُطبق بصرامة.",
[1397167891]="خلينا نكمل نقاشنا في مكان... أكثر خصوصية. اتبعني، $N.",
[1398315293]="بس هذرة. خلهم يجون. سوف نطحن عظامهم تراب.",
[1399037513]="أتشو!",
[1399477829]="انتهيت. درعك جاهز، $N.",
[1399631259]="شكرًا لك، جيسيكا.",
[1400008799]="البعث قادم، يا إخوتي... انهضوا... انهضوا وقاتلوا مجددًا.",
[1400134957]="مستحيل.... رايمفانغ.... حذّر....",
[1400422059]="انتبه!",
[1400609584]="جراء جاهلون!",
[1401340901]="لوك'تار إيلاداري!",
[1401494168]="روكدار يسحق $N الضعيف!",
[1402575288]="عشيرة ستورمبايك لا تنحني لأحد، خاصة الـهورد!",
[1402860946]="ألا تستطيع إحياءهم؟",
[1402923597]="حسبت احتمالية نجاحي، وطلعت منخفضة بشكل مزعج!",
[1403446597]="ولدي مات عند بوابة الغضب. أنا هنا فقط لاستلام جثته.",
[1403784155]="نعم، نعم يا سيدي. حالًا!",
[1403929675]="اعتذاري يا أصدقاء. خذوا هذا الآن. ينبغي أن يساعد على تغطية مصاريف إنقاذي.",
[1404756766]="شكرًا لإنقاذي، $N! والدي سيكون مسرورًا!",
[1405067422]="محطة إسعاف ستورمبايك احتلها الـهورد!",
[1405240897]="إذًا... هكذا تنتهي الأمور يا حبيبتي...",
[1405302101]="كنزي! ما تسرقش من تارتيك، أيها الخائن الغبي كبير اللسان.",
[1405851936]="لا تستطيع هزيمة عشيرة فروست وولف!",
[1405907046]="أولاً ستواجه ثلاثة من أبطال البطولة الكبار! هؤلاء المتنافسون الشرسون تغلبوا على الجميع ليصلوا لقمة المهارة في المبارزة.",
[1407475276]="فوضى!",
[1407536551]="ابتعدوا، و... احبسوا أنفاسكم. لم أفعل هذا منذ فترة.",
[1407661405]="ماناك شيك-ثريش!",
[1407806410]="أنت أورك سيء... سيء جداً... أو... آرغ!",
[1408101504]="الوقت مال يا صديقي. اذهب اذهب اذهب!",
[1408313015]="كف عن البكاء! توقف!",
[1408802491]="كان ذلك غير متوقع!",
[1409896525]="ستدمر موادنا الخام، أليس كذلك؟ حسناً، للسيد خطة خاصة لك...",
[1410310892]="باركنا بالتسامح تجاه زوارنا الإلف.",
[1410844014]="بدي أموت مثل الأورك...",
[1410933091]="كلاب جبانة! فاجأتونا!",
[1411101830]="هش جدًا وضعيف!",
[1411681423]="كم من الوقت ستقاومه؟",
[1411812152]="النجدة! النجدة! هذا $Gرجل:امرأة; سرق صورتي!",
[1412392657]="سأرسل خبرًا أنك اكتشفت الصلة بالـديفياس. كنت أحمقًا حين ظننتهم انكسروا بهزيمة إدوين فان كليف، والملك رين سيريد أن يجعل منهم عبرة لكل من بقي.",
[1412490977]="موت؟! بوسيلين يبكي!",
[1412562593]="هؤلاء الموارغ القصيرون أذكياء جدًا، وغالبًا ما يُستخدمون كمساعدين لإخوانهم الأكبر.",
[1412565899]="تشدد، $N، فالشيطان في هذه الكرة هو وحش فل.",
[1413138286]="الموت ليس سيئًا جدًا في الحقيقة.",
[1413344721]="إنه خطير هنا يا سيدي. لكنني سأساعد في الحراسة.",
[1413815829]="اكتمل التوجيه. العودة إلى وضع الاستعداد.",
[1414595264]="أيها الأحمق! سايروك سيد النار! عندما انقطع الرابط، استيقظ سايروك. إنها دموع سايروك التي تملأ هذه الأرض بالصخور المنصهرة.",
[1414625566]="بالكاد أستطيع الإحساس بـ غارديان أوف تايم! خطه الزمني يتلاشى بسرعة!",
[1414829120]="هل أنا واضح؟ هل تفهم ما أقوله؟ لا أريد إرسال المزيد من التوابيت أو الرسائل إلى المنزل.",
[1415441440]="ها هو! مفتوح على مصراعيه. حظاً موفقاً في غزو ما وراءه. يجب أن أعود إلى كيرين تور فوراً!",
[1415671291]="فايل حر؟ فايل يحب $N!",
[1416154489]="سوف يجتاح الـسكورج هذا العالم كسرب من الموت والدمار!",
[1416182853]="من الواضح أن ستيغهيلم وجيوشه غُمروا بالتدفق اللامتناهي لقوات راجاكس إلى سيليثوس. ويبدو أن ستيغهيلم كان أكثر من مجرد مصدر إزعاج للكيرايجي. تحت قيادة ستيغهيلم، اجتمعت جيوش النايت إلفز بأكملها للدفاع عن كاليمدور، مما أبطأ قوات الكيرايجي بشكل كبير.",
[1417264422]="أتيت لإنهاء المهمة، أليس كذلك؟",
[1418212516]="أخبار سيئة، يا جميعًا... لا أعتقد أنني سأنجو...",
[1418597358]="موتي... يبشر بنهاية هذا العالم.",
[1419242244]="بمجرد أن أصبحت الكراهية في قلبي مركزة، أصبح كل شيء واضحًا لي. شاتراث يجب تدميره ونارو معه.",
[1419242650]="أراك-ها!",
[1419263697]="لااااااااااا!",
[1419429596]="سأستمتع بهذا...",
[1419501338]="اجذبني إلى شبكتك يا سيدتي شادرا. أطلق سمك!",
[1419962805]="كيف... كيف استطعتِ؟!",
[1420344600]="وبينما مات غروم موتًا مجيدًا - محررًا إيانا جميعًا من لعنة الدم - لم يستطع محو الذكرى الرهيبة لماضينا.",
[1420470658]="أدمغة...",
[1420523181]="لقد اخترقنا الحرم الداخلي، أيها الأبطال! نستمر في التقدم!",
[1420586859]="أسرع طريق إلى مالقانيس خلف رف الكتب ذاك.",
[1421200399]="لا أصدق ذلك! لدينا بطل جديد للألم!!! فلادوف الـ بتشر هُزم على يد عصابة من المجهولين! نهاية لا تصدق!",
[1422206418]="لدي حيوانات أليفة -- كا-كاو! -- خاصة بي!",
[1422662658]="لا أصدق أنك فعلت شيئًا صحيحًا للمرة الأولى.",
[1423170431]="حان وقت استراحة سميثرز القديم...",
[1423279012]="استعد للعذاب الأبدي، أيها الفاني!",
[1424016359]="مهما حاولت، لا أستطيع أن أشربك جميلًا!",
[1424016479]="اشرب هذا، سيساعدك.",
[1424315777]="صبري ينفد! تعالوا، أيها البعوض، إلى موتكم!",
[1424436040]="لا تستمع لأكاذيب موغدورغ! أوغريلا مجرد أسطورة! نحن نصنع جنتنا هنا بدماء كل من يحاول تفريقنا وإخضاعنا!",
[1424565037]="سأذيب اللحم عن عظامك!",
[1424630272]="النجدة! أخرجوا هذا $N عني!",
[1424719725]="قريك حاول!",
[1425352206]="مرحباً، $C! أهلاً بك في كاتدرائية النور!",
[1425759450]="يجب التعامل مع المحتال. يجب استعادة قرص المخترع.",
[1425878247]="الأوركس أذكى من أولئك السعاة! أين هم بحق الجحيم؟",
[1426234596]="...أحتاج مشروبًا!",
[1427143980]="أحمق على وشك إنهائك، أيها النكرولورد. لن يبقى منك شيء ليعيده الـليتش كينغ للحياة!",
[1427442763]="اسمح لي بالتخلص من المتسللين، يا سيدي. سأطعم أحشاءهم للديدان.",
[1427638333]="فريق نخبة من بلو دراغون فلايت يظهر من البوابة!",
[1427961550]="ساعدونا من فضلكم! الأمير أصيب بالجنون!",
[1428234697]="نقدم لكم البطل الأعلى الشرس لـأورقريمار، موكرًا الـ سكل كروشر!",
[1428340723]="الآن أو أبداً أيها الجنود! لنفعلها! من أجل كاريش! من أجل البروتكتوريت!",
[1428342272]="احترقوا أيها البؤساء الحقيرون!",
[1428417412]="سأعطيكم أكثر ملا تستطيعون تحمله!",
[1428881570]="بلاك مور لديه الكثير ليجيب عنه!",
[1429786206]="لكن بريند، أنت دائمًا تشرب!",
[1430638386]="أشعر بالأحياء. كونوا مستعدين.",
[1431651519]="مصادري تقول \"لا\". قبل التعذيب طبعاً.",
[1431861544]="لقد فقدنا مهندسينا، هذا لن ينتهي بخير!",
[1432384641]="لم أركِ متحمسة جدًا لإيذاء أحد من قبل، أختي. تطور جميل... حسنًا، اذهبي!",
[1432749647]="إنه ملكي...",
[1433057883]="لا تشكلون أي تهديد، أيها الكائنات الدنيا! هاتوا أسوأ ما عندكم!",
[1433215905]="صوت الرعد يتلاشى.",
[1433316674]="ستندم على اليوم الذي تصديت لي فيه، $N.",
[1433975853]="تم اكتشاف حمل زائد في النواة. تم اكتشاف عطل في النظام...",
[1434236215]="أنت غير جدير.",
[1434445832]="لن أكرر نفس الخطأ مرة أخرى، سيلفاناس. هذه المرة لن يكون هناك هروب. ستخدمونني جميعًا في الموت!",
[1434463470]="أنا... أستطيع فهمك الآن! حسنًا، الآن بعد أن أصبحنا نستطيع التحدث، لديك ما تشرحه!",
[1434918354]="انظر! هناك!",
[1434950372]="حسنًا، هذا ابن آيرونفورج يريد...",
[1435106990]="لا تضرب قائد كويلسسسكار بعد الآن، أيها الأورك! سأخبرك! الشيفرة... مخبأة في أحد الصناديق في نقطة كويلسسكار... الناغا هناك يحملون المفاتيح...",
[1435193736]="مرحبًا. السيد فراس سيابي غير موجود حاليًا. يرجى العودة غدًا إلى تبغ فراس سيابي الفاخر! بيب!",
[1436396355]="لا يبدو أن أي علاج ينفع - المدينة بأكملها أصيبت بالمرض...",
[1436548279]="اشعر بقوة النقابة!",
[1436659935]="البشر... تحت أرض قرية وينترغارد بنيتم ضريحًا! لماذا تعتقدون أن ناكسماراس هاجم ذلك المكان؟ ثيلزان يختبئ في أعماق سردابكم ويرسل لكم آلاف الجثث! ستهلكون...",
[1437460693]="سلوكك يجعلني فخورًا.",
[1438363030]="كابتن ريدباث ظهر في ساحة المعركة! احموه!",
[1438372247]="%s يشير نحو المستوصف.",
[1438496564]="تجهزوا لهجوم جوي على القلعة يا الـ سكاي بريكر!",
[1438587002]="%s يمتص طاقة النار من الهجوم.",
[1438812855]="لقد دمرت المفتاح! أرشميجك العزيزة أصبحت ملكًا لـماليقوس!",
[1439126681]="ممممممممم... بسكويت ضخم معدل كيميائيًا...",
[1439252515]="ماذا؟",
[1439466374]="لا! لا يمكن أن يكون...",
[1439818990]="وعذابهم على يديك قد انتهى. باسمي، سأضع حدًا لحياتك.",
[1440139211]="أبدًا! أنا... لن أخدمك... أبدًا...",
[1440390301]="أجل. هذا فعلها.",
[1441391067]="%s ينفجر إلى قطع من الوحل الحمضي!",
[1441485850]="ملجأ ستونهيرث يتعرض لهجوم! إذا ترك دون رد، سيدمره الـهورد!",
[1441625688]="إنها دجاجة...",
[1442670602]="أجل، يا سيدي.",
[1442671901]="زوجي وأطفالي مرضى في الفراش بسبب السم الذي بعته لي!",
[1443440774]="دم والدك قوي فيك يا هيلسكريم. غير صبور كالعادة... غير صبور ومتهور.",
[1443640474]="أياً كان الإله الذي تؤمن به، فليرحمك. لأنني لن أرحمك.",
[1443812370]="%s يجمع دم مطارد الاعوجاج.",
[1443983438]="المزيد من المعرفة، المزيد من القوة!",
[1444143448]="لم أوقع على هذا!",
[1444223849]="قبيلة بلاكوود تعكر أرضنا المقدسة.",
[1444653655]="هذا كل شيء للتحدي الحقيقي. مت!",
[1445724399]="هكذا يتم الأمر، أيها العبد. ربما تتعلم يومًا ما.",
[1445947087]="أحدهم أوقف ذلك الغول!",
[1445995080]="مورتار فريق، إعادة تحميل!",
[1446530275]="هذه القوة! ألا تشعرون بها أيها البشر؟ توقفوا عن هذه الحماقة وانضموا إلي!",
[1446660636]="هيا بنا، $N. أنا مستعد للوصول إلى وايتريتش بوست.",
[1446779709]="لقد هلكنا! أنقذنا، كويمبي!",
[1447214447]="رينقو؟ استيقظ! لا تقلق، سأعتني بك.",
[1447278081]="الجرعة جاهزة. آمل فقط أن يغفر لنا كلينتار لمقاطعته في رحلته داخل الإيميرالد نايت مير.",
[1447610121]="ذلك الكودو حقًا جميل. انتظر لحظة، أين نظارتي؟ ربما يجب أن تتفقد الوحش بدلاً مني.",
[1448133049]="حان وقت تحضير كوكتيل كاليمدور! *زفرة*!",
[1448261700]="%s يشرب من معاناة الساقطين.",
[1448402608]="%s يضع يده على كتف قاروش.",
[1448544989]="النصر أو الموت! من أجل الـهورد!",
[1448920793]="أسرار هذا المكان ليست لأمثالك!",
[1448954690]="لكني ما زلت أفضل أن أكون هناك في الخطوط الأمامية أساعد في تحقيق ذلك بدلاً من محاولة تهدئة نفسي بالاعتقاد. لا يمكننا الجلوس والأمل فقط.",
[1449462419]="هذا لم يكن في عقدي!",
[1449741922]="آآه! أحسنت! الآن هذا يصبح... مثيرًا للاهتمام...",
[1449802144]="الوضع آمن!",
[1450264495]="أتمنى أن يشعر كيلثوزاد بانتقامنا يومًا ما.",
[1450864445]="القِ حتفك أيها الشيطان!",
[1451250356]="ثرال يُفزع الحصان بصيحة قوية!",
[1451262058]="أيها النوم التافه! غطرستك ستكون هلاكك!",
[1451402880]="باه! كان ذلك عرضًا للقوة يليق بقائد. ندمي الوحيد أنني لم أقتل ذلك الهيومن قبل أن يتدخل الميج.",
[1451411050]="يبدو أننا في ورطة. انتبهوا، ها هم قادمون!",
[1451416337]="ولكن كيف يا زعيم؟ ظننت أن اللعنة رُفعت...",
[1451496060]="آآآه! أطلقني! لا فائدة مني لكم. أقسم بذلك!",
[1451752019]="سعيد بأنك استطعت الحضور، أوثر.",
[1452220030]="من هو المتوقع أيها الوحش؟ بالتأكيد لم تظن أننا سنستدعيك فوق مالفوريون؟ خلاصك قادم يا إيرانيكوس. ستُطهر من هذا الجنون - هذا الفساد.",
[1452482205]="استعد للدفاع عن نفسك أيها الأحمق!",
[1453365088]="آآآه!",
[1453404952]="إن أردت المفتاح، فيجب أن تمسكني!",
[1453867200]="أيها الأطفال توقفوا! أنا جاد!",
[1453898233]="مرحبًا، يا أخي.",
[1454049970]="الغريب الذي لا اسم له، اعتبره والدي \"يورغ\"، اسم مخصص لأبطال الأساطير. بعد سنوات، يقف الآن أمامنا باسم يورق ستورمهارت، ملك الـفروستبورن.",
[1454199836]="الاحترام هو أول فضيلة تُعلَّم لمن يسلك طريق النور.",
[1454550182]="للأسف... نعم.",
[1455219322]="لا شيء يمكنك فعله يقارن بما يمكن أن يفعله بنا أروقال! سأمزقك إربًا بنفسي!",
[1456189047]="لا تدنس هذه الآثار، أيها الفاني. <تغمرك ومضة ضوء مبهرة. مخلوق مكون بالكامل من اللهب هو الشيء الوحيد الذي تتذكره.>",
[1456413538]="أنفينا، يجب أن تستيقظ! هذا العالم بحاجة إليك!",
[1456658626]="ثاين باناهوق الـديثبلو سقط على يد $N و$Gرفاقه:رفيقاتها; في القتال. $Gأمامه:أمامها; تحدٍ واحد فقط. من سيكون خصم $Gه:ها;؟",
[1456978425]="لا - ليس واحدًا آخر! سأقطع رؤوسكم على هذه الفظاعة!",
[1457629382]="كدت أن أكون طُعمًا للغول! شكرًا على الإنقاذ!",
[1457998109]="موتك هو مجرد البداية.",
[1458093603]="تم تدمير مخبأ دن بالدار الجنوبي بواسطة الـهورد!",
[1458660101]="بدء التسلل.",
[1458903149]="هم قساة بقدر ما هم أقوياء - ويبتهجون بتدمير كل ما هو موجود.",
[1459277309]="هل ظننتني ضعيفًا؟ ناعمًا؟ من هو الضعيف الآن؟",
[1459510377]="%s مفتون بانعكاس الشمس على سكين زيهغين.",
[1460094649]="افرحوا يا أصدقائي! $N أنقذنا من الظل المخيم الذي هدد حياتنا!",
[1460170834]="أجلب ريحًا قوية لدرجة أنها تستطيع إسقاط الأشجار! أيها الجنود، ساعدوني، لن يفعلوا ما يريدون!",
[1460392883]="%s يمتص الطاقة المقدسة للهجوم.",
[1460422029]="بيثيك، برايستسك تنادي بقوتك!",
[1460603282]="ها! لن تحصل على كنزي!",
[1461715463]="لا تدعهم يهربون! اقتل القوي أولاً!",
[1461750593]="أي أحمق يجرؤ على دخول مملكة جلالتها دون إذن؟",
[1462732341]="أمسكت سمكة إذا كنت جائعًا...",
[1462780656]="لأول مرة في تاريخ حلبة الدم، اختار موقور ممارسة حقه في القتال! في هذه الأرض التي مزقتها الحرب، سيواجه $N موقور، بطل الـوارمول!",
[1462853322]="في الوقت الحالي، نعم. لكن دع وجودي يكون حافزًا. الأمير كايل'ثاس كان غير راضٍ عن فشل تجربة البلورة على سلسلة جبال فالين سكاي. هذا أحد الأسباب التي جعلتنا نختار سيناريون درويدز كموقع اختبار للقنبلة.",
[1462967959]="الغنيمة لنا!",
[1463624249]="انحنِ أمام ملكك!",
[1463788391]="هذا، تم الأمر. تم تعزيز الكتاب...",
[1464263806]="أعتقد أن عموده الفقري مكسور. غول هو كذلك!",
[1464276026]="بما أن الصقور أثبتت نجاحها في صيد أحجار الغراب، فقد درب واتشر إلائرا صقرًا آخر لنقل صوتي لمسافات بعيدة. يمكنه مساعدتنا في التواصل بينما تتحرى أرواح الطيور التي ظهرت في اللوح!",
[1464375475]="مررفمرمرررر!",
[1464609447]="مرحى! نحن أحرار!",
[1464700643]="تحذير: تم اكتشاف قفل صاروخي. بدء مناورات مراوغة.",
[1464709865]="لا مفر. لا في هذه الحياة ولا في الآخرة.",
[1465023487]="%s يفتش أغراض كريستن ويأخذ حزمة الجلود الخاصة بها.",
[1465200705]="استعد لضربة قوية.",
[1465486751]="قولي إذا هذا يوجع.",
[1466000010]="وانطلقنا!",
[1466340750]="تريد سباقًا آخر؟ الأفضل اثنان من ثلاثة!",
[1466442602]="أبطال فالاهلاس الساقطون يخرجون من الأرض ليخوضوا المعركة مجددًا!",
[1466459939]="صحيح، نعم!",
[1466658648]="تمكنت من اكتشاف أن أجزاء معينة من الدماغ عند إزالتها أو تحفيزها تجعل الهدف أكثر طواعية.",
[1467544018]="خيانتك لن تبطئني، مون.",
[1467742776]="هزمتم أتباعي؟ واجهوني إذن، أيها الفانون!",
[1468016705]="هذه هدية صغيرة إضافية بما أنني سأكون غائبًا.",
[1468148317]="سأطهركم!",
[1468825225]="هيب هيب... أرررر...",
[1468888942]="اشعروا بقوة أوركس بلاكروك!",
[1469226468]="هذا غريب... للحظة، كنت أستطيع أن أقسم أنك ناديتني بقصير.",
[1469496164]="لن يعود لجنودك مهاجمة مخلوقات الحجر وحلفائهم.",
[1469540825]="مقبرة سنوفول تتعرض لهجوم! إذا تُركت دون مراقبة، سيستولي عليها الأليانس!",
[1469580359]="هل تعثرت يومًا بقدميك؟ نحن فعلنا. نوعًا ما مؤلم. لا تفعلها، ليست ممتعة. لا.",
[1469607737]="أنا رايح... أوغريلا.",
[1470235595]="ها أنت ذا، ريلارا. اشربي هذا...",
[1470265344]="أسنان قارقويل المطحونة!",
[1470292815]="[فوربولق] شكرًا لك، $N!",
[1470433410]="ثاين باناهوق الـديثبلو سقط على يد $N و$Gرفاقه:رفيقاتها; في القتال. $Gأمامه:أمامها; تحدٍ واحد فقط. من سيكون خصم $Gه:ها;؟",
[1470641054]="ابتعد عن بلوراتي!",
[1471182382]="بالإضافة إلى ذلك، تحليلي يربط كل شيءخ بزيادة في قدرات فريا السحرية أو الجسدية أو الاستدعائية.",
[1471640839]="ليمنحك روح ايشا أواك القوة، $N.",
[1471738141]="أين شيفرة اللعنة؟ أعرف أن ثلثها في هذه القرية.",
[1471805009]="%s يصاب بالجنون، ويطفئ كل حياة!",
[1472279453]="ربما قللت من شأنك. سيكون من الظلم أن تجعلني أقاتل جميع المستشارين الأربعة في وقت واحد، لكن... المعاملة العادلة لم تُظهر لشعبي أبدًا. أنا فقط أرد الجميل.",
[1472343793]="مُستَضعَف...",
[1472528576]="إذا كنت تبحث عن الموت، فقد وجدته!",
[1472557175]="ماذا؟ بريشياس؟ لااااااااا!!",
[1472573160]="روقز؟ توقفوا عن الاختباء وواجهوني!",
[1472995660]="موت... مشرف.",
[1474149045]="أريدك أن تكون معي... إلى الأبد.",
[1474165142]="لن تأكلني، صحيح؟",
[1474175536]="ما الفكرة الكبيرة؟ كدت تفضح أمري، أيها الأحمق! قلت لك ضع البوصلة وخرائط الملاحة في مكان آمن - ليس في العراء لأي أحمق يكتشفها.",
[1474367485]="دخلاء اقتحموا الحاضنة! أطلقوا الإنذار! احموا البيض بأي ثمن!",
[1474892837]="لم لا؟ العائلة يمكن أن تمنحك القوة.",
[1475142234]="إنهم... أقوياء جدًا! استهنت بقدرتهم على... التحمل.",
[1475163768]="أميل للقول إنهم جعلوا الأوغرز كبيرين جدًا! أرى أنني لن أقنعك بالتحرك الآن، لكن لا تظن أن هذا دائم!",
[1475994662]="عقاب مناسب.",
[1476075165]="المكان الوحيد في ستورمويند حيث يختلط السحر والأرواح، تعال إلى بلو ريكلوز!",
[1476176293]="توسل للرحمة!",
[1476333174]="مرحبًا أيتها الجميلة، لدى زيبوتان سجادتان هنا! لم لا تأتين وتدفئينه، ها؟",
[1476432986]="هل أنت مستعد للذهاب؟",
[1477377968]="لن يمر وقت طويل حتى يبدأ مهرجان الجعة! عد لاحقًا وتأكد إذا كنا انتهينا.",
[1477415062]="الأدميرال الأعلى يدرسك للحظة بعينين ضيقتين.",
[1477892209]="يا إلهي، أين \"مدونة الدفاع\"؟ ليدروس سيكون بالتأكيد غير راضٍ.",
[1477977097]="أيها الأطفال، ساعدوني!",
[1478618681]="كيوريتور لم يعد يعمل.",
[1478749534]="حسنًا، وقت الاستراحة انتهى. لنذهب!",
[1478841478]="أنت... لا شيء!",
[1479492760]="ديث نايتز من آكيرس، مسيرة الموت تبدأ!",
[1479918859]="مشيئتك ستتم، يا ملكي!",
[1480150257]="أحد كشافينا يبلغ أن مجموعة غامضة انتقلت إلى أطلال قرية غرانغولفار. آه، هذا التقرير عمره أكثر من أسبوع.",
[1480308800]="ربما هي عيوبك... التي تمنحك الإرادة الحرة... التي تسمح لك بالصمود أمام كل الاحتمالات الكونية المحسوبة. أنت تنتصر حيث فشلت إبداعات التايتنز المثالية.",
[1480546665]="لقد سمعت كفاية من ثرثرتك! اسكت قبل أن أسكتك أنا!",
[1481079162]="همم... دفاعات الجليد والنار والآركين تستجيب أسرع من الدفعة 7، لكن دفاعات الطبيعة تبقى سلبية.",
[1481164374]="مهمتي انتهت!",
[1481295342]="أوه، هل يمكن أن يكون؟ أنا... أنا حر من تلك اللعنة البشعة؟",
[1481360800]="متسللون محتملون، للأسف.",
[1482166721]="تبًا! الأسماك لا تعض هنا أيضًا. سأعود إلى حفرة الصيد القديمة الخاصة بي!",
[1482316718]="أنا ممتن لمساعدتكم، أيها الأبطال. الآن، هورد غولدان سيجتاح هذا العالم مثل سرب جراد، وكل تصاميمي، كل خططي الموضوعة بعناية ستقع أخيرًا في مكانها.",
[1482572632]="لسه... ما خلصت...",
[1482592496]="وكأنكم يا ضعفاء تشكلون أي تهديد لنا. سوف نلتهمكم.",
[1482673097]="سينتينل، أريد التحدث مع هاي بريستس خاصتك.",
[1482900368]="بكل سرور، يا سيدي.",
[1482963111]="النور سيتخلى عنك، أيها البطل، كما تخلى عني.",
[1483654938]="قاعات كرازان تهتز، مع رفع اللعنة التي تربط أبواب قاعة الألعاب.",
[1483759535]="إذا قدرت تصيد سمكة كبيرة تكفي لفمك، ما كنا نعاني من الجوع أبدًا.",
[1484987755]="هاهاها، لا ترفع آمالك كثيرًا...",
[1485202562]="اركع أمام الهاي لورد!",
[1486017507]="أبعد هذا $N عني!",
[1486256500]="عط-شا-ن جدًا.",
[1486330707]="آه... الأبطال. أنتم مثابرون، أليس كذلك؟ حاول حليفكم هنا أن يقارن قوته بقوتي - ودفع الثمن. الآن سيخدمني... بذبحكم. انهض أيها التنين الأحمر الصغير... ودمرهم!",
[1486406831]="جراحي خطيرة. سامحني على بطئي لكن إصاباتي تمنعني من المشي أسرع.",
[1486499446]="أيها الفاني الحقير!",
[1486686782]="لقد نجوت من سموم الفورسيكن، $N، وأعرف الآن ما يجب فعله.",
[1486884936]="%s ينفجر ويطلق عدة بايل سلايمز!",
[1487316899]="استعدوا! هذا لن يأخذ وقتًا طويلاً...",
[1487548384]="لترتفع أرواحكم! التجموا حول بطلكم، واستمتعوا بمجد $Gخاصته:خاصتها;! ابتهجوا بهتاف قاتل التنين!",
[1488082759]="أسطول العدو هناك! أطلقوا النار!",
[1488368095]="هل هذه مانجو؟ رائع!",
[1489253360]="ما... ما هذا؟ هل يمكن أن يكون هذا إجابة صلواتي؟ إلون منحتني سلاحًا—هذا المنجل—لهزيمة الشياطين.",
[1489415549]="أسمع ما تقوله، مافرين. ومع ذلك، القرار النهائي لي. أقدر مساعدتك، لكن أغلب الأرواح المعرضة للخطر هي من بلود إلفز. لن أسمح بإهدار تلك الأرواح بلا مبالاة!",
[1490466552]="لا مزيد من الفرص! الآن ستدفع للأوغر!",
[1490655445]="أفترض أنك جئت بأخبار جيدة؟",
[1490657904]="أنا لست في عجلة من أمري. يمكننا الراحة هنا قليلاً إذا أردت.",
[1490662699]="لوك'تار أوغار!",
[1490700525]="شكرًا لك، $R!",
[1491515663]="أعلم أنك هناك أيها الروق. اترك منزلي أو انضم إلى الآخرين في قاع شجرة العالم.",
[1491538044]="الـ%s ضعيف جدًا.",
[1492385833]="أيها الأبطال الشجعان، نحن مدينون لكم بحياتنا وحريتنا... ورغم أن هذه لفتة صغيرة أمام هذا الدين الكبير، فإنني أتعهد أنه من هذا اليوم فصاعدًا، سيعرف الجميع بأعمالكم، وبطريق النور المتوهج الذي شققتم به ظل هذه القلعة المظلمة.",
[1493051950]="هل تسخر مني؟",
[1493524356]="وداعًا أنفينا، يا حبي. قليلون سيتذكرون اسمك، لكنك اليوم غيرت مسار القدر. ما كان فاسدًا أصبح نقيًا الآن. أيها الأبطال، لا تجعلوا تضحيتها تذهب سدى.",
[1493535502]="شكرًا على الشفاء، $N!",
[1493843026]="دمي مثل السم!",
[1493917048]="%s يتقلب في نوم مضطرب.",
[1494107136]="آه، البطل. أصدقاؤك الصغار قالوا إنك ستأتي. هذا يوفر علي عناء مطاردتك بنفسي.",
[1494213132]="يواق ماق أوو؛ يواق ماق ساغغ. يواق ما شغفن.",
[1494613953]="تنفس أنفاسك الأخيرة!",
[1494661623]="مع انشغال الـليتش كينغ بالبوابة الأمامية، سنشق طريقنا من الجانب بحثًا عن معلومات تمكننا من هزيمته - مرة واحدة وإلى الأبد.",
[1495055296]="أخيرًا! حر من سجن نورثواتش! أحتاج لحظة لالتقاط أنفاسي...",
[1495068998]="لتكن كويلديلار علامة على أننا لن نستسلم أبدًا، وأننا سنواجه أي عدو دون خوف.",
[1495205211]="تم الاستلام. تقرير الحالة، أيها الجندي.",
[1495364542]="مقبرة ستونهيرث تم الاستيلاء عليها من قبل الأليانس!",
[1496071543]="%s يبدأ باستدعاء تعزيزات!",
[1496605990]="إنه لمن المؤسف حقًا أن تنين الأزرق اختار طريقًا قاسيًا بلا قلب. يؤلمني كثيرًا أن أحارب أبناء ماليقوس.",
[1496909653]="%s يستدعي المزيد من حلفائه من الظلال.",
[1497070988]="أين دعمي؟",
[1497171356]="إذن نحن أيضًا ملعونون؟",
[1497366002]="النوع: موآرج",
[1497610870]="شكرًا لإعادتي بيسي، $N. ما كنت لأعيش بدونها!",
[1497717420]="فورًا، يا سيدتي.",
[1498025354]="%s يتم استدعاؤه من خلال شق زمني!",
[1498033013]="أيها الحشرات الحقيرة المتطفلة! أطلقوا سراحي، وربما أمنحكم موتًا رحيمًا!",
[1498745065]="هؤلاء أعدائي. وأنت ستكون عدوي في المعركة! ملكك أعلن الحرب على نوعي!",
[1499140527]="اغتنم هذه الفرصة للتفكير في أفعالك السابقة.",
[1499354392]="تهانينا أيها الأبطال. عبر محاكمات مخطط لها وغير متوقعة، انتصرتم.",
[1499519885]="شكرًا! شكرًا، $Gبريست:برايستس;. الآن أستطيع مواجهة تلك النولز بقوتك التي تساندني!",
[1499533261]="إخوتك في الشمال أخضعوا العمالقة الحجرية ووجهوهم نحو اولدوار. قريبًا، ستصبح الدفاعات المتبقية للبانثيون محايدة.",
[1499565238]="جمهور الـهورد يهتف لـ$N.",
[1499931762]="اقتلوهم! لا تدعوا قذارة الـسكورج تدنس مدينتنا!",
[1500247769]="%s يطير عبر الأشجار، متحررًا من فساد تيروك.",
[1500475495]="درويدز وتحولاتكم السخيفة. خلينا نشوفها عمليًا!",
[1500788396]="الزوار ممنوعون!",
[1500900886]="%s يصبح غير مستقر ويبدأ في التفكك!",
[1501165640]="مخبأ آيسوينغ يتعرض لهجوم! إذا تُرك دون رد، سيدمره الأليانس!",
[1501557522]="لا أحد من نوعك يجب أن يكون هنا! لقد حكمتم على أنفسكم فقط!",
[1501818808]="آه... أكيد، جانكلي. فقط... <سعال>... انتظر هناك. <سعال> شباب؟",
[1502646007]="غير مستحق!",
[1503240293]="حتروح تخرب كل شيء!",
[1503516441]="أديت غرضك.",
[1503575354]="اركبوا الآن! اركبوا هناك وجيبوا لي بعض الرؤوس!",
[1503748813]="هذا هو عدائهم لدرجة أنهم يتنافسون على شرف إرسالهم لمساعدة نارو هناك. كل يوم، يتم اتخاذ هذا القرار هنا بواسطة أدال. تتجمع الجيوش هنا لتلقي بركة أدال قبل التوجه إلى شادومون.",
[1503883491]="وَالآنَ دَوْرُكُمْ أَيُّهَا الْحَشَرَاتُ! بِجُرْأَةٍ، طَلَبْتُمْ قُوَّةَ رَاغْنَارُوسَ. الْآنَ سَتَرَوْنَهَا عِيَانًا!",
[1503975930]="آيْيَايَايَا!",
[1504290745]="لا تقلق يا رجل. فقط اتركها لـروخان. هي جاية.",
[1504338934]="%s ينظر إلى ادفايزر فالوين بابتسامة على وجهه.",
[1504812283]="خيانتك فقط تسرع هلاكك. هذا العالم سيسقط في الظلام!",
[1506599684]="أنا... أنا لا أعرف، بران. لقد كنت هنا وقت طويل... كل ما أملكه من حياتي قبل هذا المكان هو ومضات وكوابيس.",
[1507422051]="اعلم أنه أينما وجدتهم في العالم، فهم يحمون شيئًا مهمًا، كما أوكل إليهم منذ زمن بعيد.",
[1507602206]="مهرجان القمر هو وقت مميز لنا. نبحث عن شيوخنا القدماء، الإيرذن، ونكرمهم.",
[1508334378]="لا! السيد... لن يكون... راضيًا.",
[1508571526]="آه، دعني أرى. نعم، ربما اقتربت من المرة المائة الآن، أراهن!",
[1509360665]="أرواح الهايبورن! كونوا بسلام! كريستال زين-مالور عاد كاملاً مرة أخرى!",
[1509459636]="$N؟ مون؟",
[1509469110]="أنت لي!",
[1509473584]="راقب ذلك النفق. يجب ألا نسمح لأي شخص بالمرور!",
[1509575352]="أطلقوا الكلاب!",
[1509625863]="بطل \"آخر\" يسقط.",
[1509700588]="ما أعتقد أن الإعجاب والأفكار الحزينة مخالفة للمعايير الاجتماعية.",
[1509779643]="لم يعد هو نفسه من بعد الحرب. كأنه كبر وصار عجوزًا بين ليلة وضحاها. لكن ابنه هذا - سيصير ملكًا عظيمًا يومًا ما.",
[1509963033]="وداعًا يا صديقي العزيز. سنلقاك في العالم الآخر عندما نؤدي واجباتنا في هذا العالم.",
[1510185938]="بوابة الشمس الحمراء تتعرض لهجوم!",
[1510234408]="رائع حقًا يا مالتريك. يبدو أن خطتي نجحت تمامًا. ألا توافقني أيها الفاني؟",
[1510275911]="انتبه!",
[1510400248]="تاريثا....",
[1510851180]="ليدي فاشج يتوقع أن ننهي عملنا قريبًا.",
[1511145200]="قطع أثرية، أسلحة حرب، دروع نادرة. من يدري ماذا سيحمل أنطونيو هذا الأسبوع إن لم تأتِ لترى.",
[1511173648]="$R الضعيف لا يقدر يرفع الرمح. غور يرفع الرمح!",
[1511388957]="إجراءاتك الأمنية فشلت! تعامل مع هذا الاقتحام فورًا!",
[1511402502]="إلدر هاركيك فرينزي هارت جيد جدًا. ساعدني كثيرًا عندما كنت صغيرًا وما كنت أحب داجيك.",
[1511523751]="لا! لا يمكنك أن تكون أقوى من فاول ويلد! لا!!",
[1511575008]="أيها الأدميرال، دعني أفكر في الأمر... آرر... بدأ يتضح لي.",
[1511712079]="كفى!",
[1512453415]="آه! ها هو مفتاحي! الآن لنعيد تركيب شظايا اللفافة هذه.",
[1512536628]="ستدفع الثمن بحياتك!",
[1512722511]="كويلسسكارر!",
[1512915497]="لو لم تكن دمائي قد تجلطت منذ زمن، لكانت تغلي غضبًا الآن...",
[1513131579]="روح أخرى لسيدي!",
[1513224165]="لاكوتاماني يزأر بداخلك، $N.",
[1513792840]="ماذا حدث لخنازيرنا؟",
[1515122749]="أنت متلهف جدًا لسفك دمي. لكن لتهزمني، عليك بقطع رأسي!",
[1515324630]="من هذه اللحظة حتى نهاية الأيام أحيا وأموت - من أجل الـهورد!",
[1515469588]="أشعر بالأرواح المعذبة، $N. إنها من هذا الطريق. تعال بسرعة!",
[1515978861]="لا أرى مانعًا، مع أنني لا أرى الكثير من الأشياء الآن.",
[1516485715]="بكل سرور يا حبيبتي. سأعود قريبًا...",
[1516587805]="رائع! نتائج إيجابية مذهلة! سلامة الهيكل بنسبة 98.9%! بالكاد خدش! نكمل.",
[1516827021]="من أجل آيس ميست! من أجل التاونكا!",
[1516933965]="لقد انتعشت!",
[1517180109]="فقط لا تسألني من أين حصلت عليه...",
[1517880497]="لا تعذبني أكثر! أطلق سراحي، أيها الفاني! الـسوَامب أوف سورووز... أيها الفاني... أرجوك...",
[1518419648]="هل وجدت شيئًا ممتعًا لتطارده، توينكل؟ أراهن أنك فعلت!",
[1518479948]="هذه القوة... يجب أن تكون لي!",
[1518795460]="لقد اقتحموا قاعة الأنوار! يجب أن نوقف المتسللين!",
[1519205849]="لكن حتى مهارة ثالوريان وسحر كويلديلار لم يستطيعا إنقاذ سيلفرمون من قوة الـسكورج.",
[1519351713]="اهدأوا جميعًا! تمالكوا أنفسكم! لا توجد مؤامرة هنا! الـوارلوك تصرف بمحض إرادته، دون تأثير من الأليانس. البطولة يجب أن تستمر!",
[1519762694]="الفائز في سباق السحب هو... فريق النومز! عمل رائع يا رفاق!",
[1519918328]="مقبرة ستونهيرث تتعرض لهجوم! إذا تُركت دون رقابة، سيسيطر عليها الأليانس!",
