[1525754198]="سهل جداً.",
[1526177820]="نحن هنا من أجلك أيها الأخ الضال. من العرف أن نمنحك فرصة للتوبة قبل أن تُدمر. نمنحك هذه الفرصة، كما يأمر قانون نارو.",
[1526230907]="أخي، لا!",
[1527062341]="هواة! لا تظنوا أنكم تستطيعون التغلب عليّ! أنا أقتل لأعيش.",
