[1536003705]="أخبره؟ أيتها الجدة الكبرى، والد ذلك الفتى مات كي نعيش كلنا أحرارًا من لعنة الدم. لن أخبره شيئًا. سأريه! سأريه هو وكل من يشك في عزيمة هيلسكريم ما الذي فعله غروم هيلسكريم من أجل كل الأوركس!",
