[1547036357]="سيناريوس يقاتل بجانبي. إيليدان يجلس على عرشه في أوتلاند - متأملاً. أخشى أن الخسارة أمام آرثاس كانت نقطة انهياره. الجنون احتضنه، يا ريمولوس. يعيد الأحداث في ذهنه ألف مرة في اليوم، لكن في عقله، هو المنتصر وآرثاس مهزوم تماماً. لقد ذهب بعيداً جداً، أيها الصديق القديم. أخشى أن الوقت قد يحين قريباً حيث ستُختبر روابطنا ولن تكون كما كانت عند البئر في زين-أزشاري.",
