[1549388373]="انهض، واقبل هديتي.",
[1549479465]="أسرع، وإلا ستتذوق كلو!",
[1549663737]="خلال مهرجان القمر، يجب أن نأخذ وقتًا للبحث عن شيوخنا والتفكير في حكمتهم.",
