[1579855324]="أنا آسف لأنني لم آتِ مبكرًا، أيها الهيلسكريم الصغير. هناك الكثير الذي يجب أن أخبرك به عن والدك، لكن أولاً يجب أن تخبرني أين يمكنني أن أجد الجدة الكبرى.",
