[1629614962]="السادة الحقيقيون يتعلمون جعل الدم يخدم أكثر من مجرد قوتهم في المعركة.",
[1629892085]="%s يختلف مع ما همس به فالفين في أذنها.",
[1629897423]="شيرفالا، املأني بغضبك!",
[1629956994]="بالفعل، حان الوقت لإنهاء هذه المهزلة.",
[1630194395]="خطة شفافة.",
[1630621901]="استريحي الآن يا ابنتي.",
[1630651904]="شجرة كبيرة مريحة. بيت جيد.",
[1630823619]="مرحبًا بك في هونر هولد، $N. من الجيد وجودك معنا.",
[1631532978]="وقتنا قد انتهى، $N. كنت لأتمنى لك الحظ، لو كان موجودًا.",
[1631802182]="%s يكاد ينهار وهو يتعثر باتجاهك.",
[1632467808]="درع الأثير الخاص بـ%s قد تحطم بواسطة $N!",
[1633019651]="أرجوك... هل كيلجايدن أحمر؟",
[1633361729]="لنرى، تعديل بسيط هنا وتعديل هناك...",
[1633960973]="إعلان!",
[1634489544]="دابو! سوف أكون حذر يا بابا!",
[1634645303]="بفا! أي نوع من النيكرومانسر يترك الموت يوقفه؟ كنت أعرف أنك لا قيمة لك!",
[1635007062]="...أشواك متشابكة...تمتم...أوتش!",
[1635035002]="إبادة.",
[1636186278]="إنه أمر غريب، لا يمكنك إنكار ذلك. طعام مشبوه؟ بهذا التعريف، يجب أن تعتقل بلفاست!",
[1636258031]="أقترح؟ أقتسوف أن نستعد. أن نستعد أحباءنا وعائلاتنا وأصدقائنا لاحتمال حدوث محرقة أنديد.",
[1636741616]="كنز سورلوف يسقط على الأرض.",
[1636836760]="ورشة حصار ويستسبارك تعرضت لهجوم من الأليانس!",
[1636869969]="جميل جدًا، جيرارد. بعدها ستبدأ بتربيتهم.",
[1637416265]="من يزعج هذا الملاذ؟",
[1637533211]="شيء يخرج من المرجل!",
[1637872648]="من يتطفل على طقسي؟",
[1637912155]="$Gسيدي:سيدتي;، $N، نحن محظوظون بوجودكم معنا هنا.",
[1637922298]="مرحبًا، أنطونيو. من الجيد رؤيتك وصلت بأمان إلى هنا مجددًا. أخبرني إن احتجت أي شيء.",
[1638261641]="كل ما تريده أيها الـ$R هو حشيشي.",
[1638569331]="لقد وُجدت ناقصًا وحوكمت وفقًا لذلك. انهض الآن، ثاين إلّسكار الـ دامند!",
[1638723163]="إنه طريق طويل للأسفل...",
[1638780734]="كما تشاء، يا سيدي.",
[1638939361]="تم تدمير مخبأ دون بالدار الشمالي بواسطة الـهورد!",
[1639164744]="هذه الذكرى عن آرثاس هي ما أختار الاحتفاظ به في قلبي.",
[1639356343]="كوخ الإغاثة فروست وولف يتعرض للهجوم! إذا تُرك دون رد، سيستولي عليه الـهورد!",
[1639529106]="آه، نيرزول. ليس اسمًا يُقال باستخفاف، لكنني طلبت منك إجابة.$B$Bونيرزول هو الصحيح.",
[1639825219]="مستحيل...",
[1639971474]="آه ها ها ها ها ها ها ها!",
[1640318414]="دائمًا سلبي جدًا. احتمالية حدوث ذلك بين صفر ولا شيء.",
[1640484647]="اصرخ بأنفاسك الأخيرة!",
[1641381971]="أخرجني من هذه البؤس!",
[1641397213]="الأمر متروك لك لتجده قبل أن يفعله الحديديون!",
[1642010688]="هذا الكيان الشيطاني يُعرف باسم فويد ووكر. قوته وقدرته على التحمل كبيرتان، مما يجعله مثاليًا للدفاع. أرسله لمهاجمة عدوك، ثم استخدمه كدرع بينما تستخدم تعويذاتك وقدراتك لاستنزاف حياة خصمك.",
[1642746020]="أنا مدين لك إلى الأبد، يا صديقي.",
[1642962794]="بلورة أنف خنزير!",
[1643461725]="بدء إجراء بديل...",
[1643693588]="الـهورد استولى على قلعة وينترقراسب!",
[1643989872]="مطلوب إعادة تشغيل النظام. تعطيل أنظمة الأسلحة.",
[1644035058]="آرثاس أنقذنا - نحن هالكون!",
[1645176514]="النور معك الآن وإلى الأبد.",
[1645703779]="جيب القتال إلي وادفعوا بحياتكم!",
[1645709163]="%s طُرد من على دريكه!",
[1646198458]="تم توقع خطة الكيان المعادي. إعادة توجيه وظيفة القتال. تغيير المسار.",
[1646618024]="هذا رقم 10! كم لديك؟",
[1646782522]="أنت لا تعرف حتى، أليس كذلك؟ الصيادون؟ ليسوا بشرًا... يجب أن نخرج من هنا! تعال، بسرعة!",
[1646793127]="حسنًا، حسنًا! أعتقد أنني أستطيع معرفة كيفية تشغيل هذا الشيء...",
[1646844558]="مشيئة السيد قد تمت.",
[1646853734]="برزت... نقرة... دوي...",
[1647450411]="دوه!",
[1647831966]="الدكتور أوكلني خطط نيرجيلد، كتلة اللحم العملاقة المصنوعة بالكامل من الفارغول! ستكون أقوى مخلوق من نوعه وسيتم إنشاء فيلق كامل منها لتدمير قواتك البائسة!",
[1647977073]="هل تدرك ماذا فعلت؟",
[1648065663]="جاينا، ما حدث عند بوابة الغضب. كانت خيانة من الداخل...",
[1648158399]="أنا سعيد لأنك رأيت تلك!",
[1648211122]="هذا... مميز.",
[1648678741]="أنا هنا يا بابا. كنت نايم طول اليوم. أكيد تعبان!",
[1648830774]="حسناً، لنذهب!",
[1649080824]="فجأة من العدم -- بام! ميت!",
[1649697702]="همم، أين الجامع التالي؟",
[1649710205]="اهربي يا صغيرة، اهربي!",
[1649764425]="يدوس المقاتلين تحت الأقدام، %s يدخل في غضب زبد!",
[1649927916]="أشعر بالقوة تتدفق في داخلي!",
[1649966386]="إذن هو الخيار الثاني.",
[1650749017]="%s يستحضر نيثر بورتال!",
[1650845760]="ماذا تريد مني؟ اتركني وشأني!",
[1651696565]="ما هذا!؟",
[1652336858]="هنا! داخل الغرفة. هل وجدت مفتاح قيودي؟ هيومان بوروين عنده.",
[1652542694]="لن أُعذب مرة أخرى!",
[1653444281]="%s يرفع عالياً العناصر التي أعطاه إياها $N...",
[1654139923]="هؤلاء...",
[1654466548]="نم الآن، أيها الصغير...",
[1654929036]="وداعاً لك، ولتكن النور معك دائماً.",
[1655223775]="إذاً، لأعضاء الأحياء الضعفاء بعض الأنياب بعد كل شيء. خذ هذا المكان، إذاً، في الوقت الحالي. سأعود، أقوى بمرتين، وقواتك التافهة ستسقط!",
[1655744968]="ارتعدوا أمام تالدارام، أيها البشر، لأن قوة الكرة تتدفق من خلالي!",
[1656506247]="تفعيل وضع الدفاع إي إل-2إس.",
[1656531359]="ابني! يا ولدي الجميل العزيز!",
[1656553714]="كفى!!",
[1656558335]="البلود إلف ما تبدو ماجستير، لكن يمكن عندها شيء هو مفتاح لعنة البرج.",
[1657459790]="برررررر!",
[1658222042]="$N تم طعنه!",
[1658301429]="انضم إلينا!",
[1658511411]="أوه، لا! لقد نفد وقتنا.",
[1658549749]="%s يفرقع مفاصله.",
[1658879593]="إنه يلسع...",
[1659127721]="%s ينادي على دابته.",
[1660362778]="أنت تحمل سيف والدي، $N. جنودي تحت سيطرتك، يا $Gلورد:سيدتي;. خذهم... قُدهم... النجس يجب تطهيره. يجب تنظيفهم من دنسهم.",
[1661480057]="وعندما وصل إلى هناك، ماذا رأت عيون الدوارف؟",
[1661991416]="النصر للـليجيون!",
[1664048930]="حان الوقت لتحطيم هذا الكون الميكانيكي إلى الأبد! دعونا لا نكون عبيدًا للساعة الرملية! أحذركم: أولئك الذين لا يتبنون هذا الطريق الأعظم سيصبحون ضحايا لمروره!",
[1664858016]="الجميع يريدون دائمًا أن يأخذوا منا. الآن سنبدأ باستعادة حقنا. أي أحد يقف في طريقنا... سيغرق في دمه! عادت إمبراطورية الأماني... طالبةً الثأر. وسنبدأ... بك!",
[1665258030]="سوف أطردها من مخبأها، $N! فقط كن مستعدًا لها لما تدخل!",
[1665666513]="أجل، أعتقد أني أتذكر الآن...",
[1666668716]="انتبه. هذا هو إنستركتر رازوفيوس، المدرب المعين من كيلثوزاد لجميع الديث نايتس. يُقال أن تقنيته قوية جدًا لدرجة أن تلميذه فقط يمكنه تحمل قوته.",
[1666697336]="عربة الخام تصر على القضبان بينما تُطلق.",
[1667307759]="غرر... نا سو كا ماغموث!",
[1667330149]="الآن أنا غاضب جدًا.",
[1667466648]="%s يهرب.",
[1667701659]="تموت! هذا اللي يبيه السيد.",
[1667814491]="رينجي يحتاج مساعدة!",
[1668007558]="اطبخ، يا سيدي.",
[1668588725]="حريق! حريق!",
[1668739804]="لا ترفع عينك عن هالـبروكن الوسخين. أنا ما أثق فيهم.",
[1668991707]="لا!!! يحط التانين في السلة، وإلا بياخذ المطرقة مرة ثانية!",
[1669611677]="جاهزين. استعدوا. انطلقوا!",
[1669618040]="فكر فيها يا منقب، لكن قرر بسرعة. يجب أن نتحرك قريبًا.",
[1669788601]="اشهد على وكيل زوالك!",
[1670095613]="لقد أنقذتني، أيها الجلدي! أمير سيعلم بهذا العمل النبيل.",
[1670104439]="الـسكورج ينزل كالجراد من الشمال.",
[1670347448]="واحد آخر سقط!",
[1670425044]="أي متسلل يجب القضاء عليه!",
[1670644604]="لقد أُمرت بالمجيء إلى هنا، وهنا سأبقى وأقاتل تحت راية ستورمويند. لكن كل ما أفعله هنا فارغ.",
[1670680557]="أسيادي، أتعهد لكم بهذا $R!",
[1670951731]="يبدو أنك خسرت.",
[1671576081]="أركونوس قريب. أشعر به. خذ الممر الشمالي الغربي. يجب أن يكون قريبًا عند الزاوية. كن مستعدًا للمعركة!",
[1671825417]="ذيلزانز فيلاكيري يسقط على الأرض تحت ايسستورم.",
[1673411926]="أيها الفاني المتغطرس! سيتم التهامك!",
[1673575711]="تراجع، أيها الجرو!",
[1673939993]="قل لي، مودورو. من أين حصلت على تلك... آه... الرداء \"الرائع\" الخاص بك، همم؟",
[1674274079]="كان لا بد من فعل ذلك...",
[1674324013]="هناك، $N. يمكنك الآن التحدث مع زعيم بلودسكالب وطبيبه الساحر.",
[1674750083]="أشتاق لكلبي كثيرًا!",
[1674772696]="أيها الأحمق عاشق اللسان الكبير! أنت لم تعد صديقًا لفرينزي هارت. فرينزي هارت سينتقم منك.",
[1674852607]="الوضع الحالي يبدو هكذا: نحن نصمد بما نستطيع بينما أولئك ذوو الخبرة الأكبر والمعدات الأفضل يتحركون ضد الأمير كيل'ثاس.",
[1675062479]="رايلوراز، من الجيد رؤيتك مرة أخرى.",
[1676189005]="أدمغة... أدمغة!",
[1676804197]="أنا قاروش هيلسكريم، ابن غروم، زعيم الماغهار! دع نداء هيلسكريم الحربي يمنحك الشجاعة والقوة! ارفعني بهتافاتي الحاشدة.",
[1676931645]="الحرس الليلي وحده لا يستطيع حمايتنا للأبد. نحتاج دعم جيش ستورمويند.",
[1676987660]="لا يمكن السماح لهذا الشر بدخول هذا العالم! تعالوا يا أطفالي!",
[1677013110]="فرقاطة هناك! إنها سفينة أورك بلا شك! أطلقوا النار!",
[1677051341]="ها هو بطل الطليعة!",
[1677907514]="لكن لم يمر وقت طويل حتى تعرضت المدينة للهجوم مرة أخرى. هذه المرة، جاء الهجوم من جيوش إيليدان. أرسل حليف إيليدان، كايلثاس سنسترايدر، فوجًا كبيرًا من بلود إلفز لتدمير المدينة.",
[1678457522]="سننهي هذا الآن، مالقانيس. أنا وأنت فقط.",
[1679310151]="لكن هذا ليس أسوأ لا يوجد الأمر. قبل أن أتمكن من سحبنا للخلف، رصدتنا مجموعة منهم وهاجمتنا.",
[1679397520]="في صراعنا ضد الظلام، أرسلنا أطفالنا.",
[1679398691]="%s يقدم لك شكره.",
[1679418529]="حسّان حر؟ انزل على بيغ أند ويسل لكي تبرد!",
[1680784299]="مارشالز... إخوة وأخوات السيف. أفضل القتال إلى جانبكم على أي جيش من آلاف. نحن أسود! تعرفون ما ينتظر عبر هؤلاء الشياطين وما وراء البوابة المظلمة؟ خلود! خذوه!",
[1680876683]="أبطال الأليانس، ملككم ينادي! تجمعوا ورائي عند مدخل المجاري!",
[1681095267]="تحذير: نمط شكل الحياة غير معروف. تم إنهاء المعالجة الأرشيفية. استمرار التدخل سيؤدي إلى رد موجه.",
[1681183163]="مأساوي. فوردرينغ الأكبر ما زال حياً... جئت متأخراً أيها العجوز. ارجع إلى كهفك أيها الناسك، إلا إذا كنت تريد الانضمام إلى ابنك في التوستينغ نيذر.",
[1682075621]="%s يبدو أنه ضعف.",
[1682655312]="شكراً، هايلورد. الآن أيها المتحدون، سأبدأ طقوس الاستدعاء. عندما أنتهي سيظهر دومغارد مخيف!",
[1682656493]="ليس مرة أخرى...",
[1682851203]="اكتمل جمع الطاقة.",
[1683262706]="مجرد طعم...",
[1684611474]="انحنوا لقوة الـسكورج!",
[1684932063]="ساعدوني! أرجوكم ساعدوني!",
[1684983100]="احذر أيها العبد، الـسوفتنكلز الكبير الشرير قد يأكلك! هاه!",
[1685418657]="لا يوجد لعب زيادة؟",
[1685885985]="اشتغلوا على هالبلورات!",
[1687108991]="دالاران سيسقط!",
[1687116967]="أولوم... صديق قديم. من الجيد رؤيتك بأمان.",
[1687120382]="حسنًا... الخبر السار أننا أرجعنا التعزيزات.",
[1687188641]="أوه لا، لقد كان مجرد أداة، حجر خطوة لخطة أكبر! كل شيء قاد إلى هذا... وهذه المرة لن تتدخلوا!",
[1687675601]="عدم ثقة...",
[1687676389]="لقد فات الأوان على يارل... قبضته قوية جدًا...",
[1687870966]="أنا لا يُقهر!",
[1687919532]="فالاهالاس ملك لك تربح أو تموت فيها، $N. لكن مهما فعلت، ابق داخل حدود الحلبة. الهروب يعني الخسارة والعار.",
[1688042333]="سيكون من العار أن تذهب هذه المنشورات سدى، أليس كذلك؟",
[1688254932]="لا تقل أني ما حذرتك، أيها الأوغاد! إلى الأمام، أيها الإخوة والأخوات!",
[1688450609]="هذه أخبار مزعجة حقًا. تأكد من التعامل معها فورًا!",
[1689250400]="إيريدار",
[1689610873]="أمسكتها!",
[1689905152]="وارلورد كاليثريش سيعلم بهذه الوقاحة!",
[1690132491]="إنه مجنون تمامًا! يجب أن يوقف أحدهم جنونه قبل أن يفوت الأوان للجميع!",
[1690153856]="تفعيل وضع الدفاع إي إل-7إم.",
[1690827188]="أخيرًا، حرٌّ أخيرًا... يجب أن أذهب الآن، شكرًا لمساعدتي في الهروب. يمكنني العودة إلى فري ويند بوست بنفسي.",
[1691479251]="ييب! أنا أقتل!",
[1691483531]="تتلاشى الهالة، مما يسمح بالشفاء مجددًا!",
[1691513924]="أوه، يا إلهي! يبدو أن وقتنا قد نفد، يا أصدقائي.",
[1691527488]="الجنود فونتين، ماكدوغال، ويلكوت...",
[1691683414]="أنتم يا رفاق تعرفون التعليمات. لا كحول للجنود في الخدمة. هل تريدون أن يقتلني الجنرال بنفسه؟",
[1691855265]="مثير جدًا للاهتمام!",
[1691951961]="بقوى هذه البلورة، أنا وفرقة الموت التابعة لي... سنكون لا يُقهرون! يمكننا تدمير إيليدان! يمكننا... أن نحل محله كأسياد أوتلاند!",
[1692028804]="انظروا! ربط المقدس بالفاسد؛ تشكيل شادوز إيدج، سلاح ذو إمكانيات لا تُحصى!",
[1693284449]="حسناً، حسناً! كفى قتالاً. لا داعي لإيذاء أحد آخر.",
[1693520109]="قوة العاصفة لا تزال حية.",
[1694478576]="أيها الأحمق! أتباع الأمير هم نفس الفورسيكن الذين تحالفنا معهم الآن، وقد خاننا!",
[1694752440]="%s يهمس بشيء لـبران.",
[1694886749]="جيفري كابلان! توم تشيلتون! روب باردو!",
[1695047459]="إنه محق. لا أشعر بشيء... أنا... لا شيء.",
[1695566577]="لا... يجب... أن أتراجع!",
[1695996021]="من أجل الـهورد!",
[1696425714]="كلب الصقيع عثر على مخبأ اللص. واجهه!",
[1696537117]="ها! 16! كم لديك؟ 10، ربما 11 إذا كنت محظوظاً؟",
[1696793139]="هل ترون الآن قوة الـداركفالن؟",
[1697173519]="هواة! أنتم بعيدون جدًا عن مستواكم!",
[1697674885]="علاوة على ذلك... بينما يمكن أن يكون الفأس أداة قيمة في الحرب، فإن للرماح استخداماتها أيضًا.",
[1697747356]="لاستعادة خاتم ميميرون، ابدأ تسلسل التدمير الذاتي واهزم ميميرون قبل اكتماله.",
[1698277451]="لكن تذكر، العامل الأساسي في كسب أي معركة هو التعزيز الإيجابي.",
[1698462600]="تفعيل وضع الدفاع إي إل-5آر.",
[1699307395]="مفاجأة، مفاجأة! غول آخر!",
[1699379127]="أوف! البوتيرانغ آلمني! أنا أعتقد أنها تعمل أفضل من البوتيرانغ!",
[1699445407]="ألم يبق أحد ليختبرني؟",
[1699773608]="هي هي هي! هذه ستكون بعض المتعة، مون!",
[1699788565]="يجب أن تتصالح مع بونسامدي، حارس الموتى، إذا كنت تأمل هزيمة زالازان. هذا هو الطريق الوحيد. قل لابن سينجين هذه الأمور.",
[1699822977]="أتتذكر كيف تخبرنا دائمًا أن نهدأ؟",
[1700324649]="انظر إلى نفسك أيها الطفل، الطامح لحمل الأرواح... لا تستطيع استيعاب القوة التي بين يدي!",
[1700332661]="لا أحد سيمنعنا من تحقيق مصيرنا!",
[1700642969]="إنهم قادمون لأجلك.",
[1700993207]="حتى الـفرينزي هارت يعرفون كل شيء عنك بعد أن جئت إلى شولازار. ربما تعلم كيكيك بعض حيلك؟",
[1701072780]="النار تلتهم! لقد حاولت وفشلت. لا شك أن العدالة انتصرت!",
[1701205265]="فيشينق سهل جداً. فقط خذ قصبة بخيط، حط عليها طعم، وارميها في الماء. وبالتأكيد، السمك بيبدأ يعض.",
[1701222731]="أخذونا واحداً تلو الآخر. أنا متأكد أن هناك ناجين آخرين.",
[1701468905]="أيها الأحمق $C! أنت لا تقارن بأتباع راقناروس!",
[1701534162]="%s تحاول أن تشغل نفسها بأمور أخرى.",
[1701617607]="$N! خائن راقناروس!",
[1701679099]="والآن، شاهد...",
[1701902758]="لم يكن من المفترض أن أكون هنا اليوم أصلاً!",
[1702285359]="ارتعدوا أيها البشر، قبل مجيء النهاية!",
[1702587175]="في ذلك اليوم، أُعطيت لنا الويلدكن. حراس أشداء، كلفتهم الإلهة بحماية جميع أماكنها المقدسة.",
[1702761124]="لقد فشلت. لقد تخلى عني النور.",
[1702768849]="فارون يمشي في الأراضي شمال ما تسمونه شلالات بايترتايد. ستجده وحيدًا، لكنك سترى أنه لا يحتاج إلى حماة.",
[1702987180]="مياو!",
[1703009089]="تحتاج أن تتعلم تقدير محيطك، سيرسي!",
[1703284464]="الموت للغرباء!",
[1704092700]="أخبار سيئة يا جميعًا. روت فيس مات، لكن أخبار رائعة يا جميعًا! لقد ترك وراءه الكثير من الوحل لأستخدمه! ماذا؟ أنا شاعر ولم أكن أعلم... مذهل!",
[1704700654]="شكرًا على الحلاقة والقص الرائعة يا صديقي.",
[1704799350]="بيرة الألم! بيرة الألم الباردة هنا!",
[1704840870]="سأعيد هذا إلى المدرسة القديمة. سأكون الأليانس وستكون أنت قرية فروست وولف. قنابل للأسفل!",
[1705220886]="حسنًا، ابقني محميًا بينما أزرع هذا المعطل. لن يستغرق هذا وقتًا طويلاً.",
[1705297474]="من أجل نبتولون! قوة العاصفة والبحر، اسحق أعدائي!",
[1705359715]="وكذلك سنفعل جميعًا.",
[1705662796]="ستعاني من جراء هذا التعدي!",
[1707685982]="تُعرف هذه المنطقة بأنها مليئة بالـسكورج النجس. قد ترغب في أخذ لحظة لتجهيز أي دفاعات لديك.",
[1707797195]="الأوركس في قلعتي سيشربون دمك ويلتهمونك!",
[1708191529]="قائدنا، فولجين، ابن سينجين، أطلق النداء لجميع داركسبير: استعيدوا جزر إيكو لقبيلتنا.",
[1708629506]="شكرًا لإنقاذي! لن يمر إنجازك دون أن يلاحظه أحد.",
[1708950176]="أبطال الأليانس، اهجموا!",
[1709279838]="بوابة الشمس الحمراء دُمرت!",
[1709568172]="%s يركض بسرعة بعيدًا عن اوميز ميكانيكل ييتي.",
[1711030374]="لا يجب أن تكونوا هنا! اقتلوهم!",
[1711577526]="آآآه!! ساعدوني قبل أن أفقد عقلي!",
[1711813974]="ويي! أنا فتاة مجددًا!",
[1712309532]="آه، ضيوفنا وصلوا، كما وعد السيد.",
[1712700623]="افسحوا الطريق! افسحوا الطريق!",
[1712835908]="من أجل سيدتي وسيدي!",
[1712921316]="هذا أصعب مما يبدو.",
[1713308202]="هذه هي الرياضة الحقيقية!",
[1713649261]="%s يهاجم برد فعل.",
[1714179164]="تعال وتحدث معي إذا كنت ستذهب إلى نوميريغان، يا $N!",
[1714224559]="أوه تيتو، يجب أن نجد طريقًا للعودة! الساحر العجوز قد يكون أملنا الوحيد! سترو مان، رور، تينهيد، هل ستساعدون... انتظروا، يا إلهي، لدينا زوار!",
[1714385766]="الأفضل لأمتلكك به!",
[1715001486]="انطلقوا يا حيواناتي الأليفة!",
[1715052762]="الموت يأتي لنا جميعًا في النهاية، لكنه أحيانًا يأتي أسرع مما نتوقع. اليوم نسمي ذلك البطولة العمياء... غدًا قد يسميه البعض غباءً.",
[1715226689]="متعب جدًا. سأرتاح للحظة!",
[1715399973]="غضب السيد يجري في عروقي!",
[1715440052]="لقد فتحت بوابة إلى الحلم. خلاصكم بداخلها، أيها الأبطال...",
[1715509184]="فات الأوان للهرب!",
[1716090197]="أيًا كان. قذارة الـهورد المقززين غير المرتبين...",
[1716116549]="هذا لأنني أنا من يعمل كل العمل الشاق!",
[1716338272]="سأعلمك أن تسرق كنوزنا! كنوزنا... لنا، حسنًا؟!",
[1716454345]="وقد تحققت العدالة!",
[1716513721]="أخدم بفخر.",
[1716970930]="أيها الإخوة والأخوات، لقد دعوتكم اليوم لمناقشة مصير لوردايرون.",
[1717091234]="يجب أن يستمر العمل. ضاعف جهودك.",
[1717436742]="انتظر وانظر ماذا سيحدث!",
[1717476710]="أنت مفضوح بشكل يائس، $R.",
[1717594704]="من يجرؤ على مهاجمة موقع سيلفر وينغ؟!",
[1717728760]="في هذا الحلم، كنت سيد الصيد في العالم. انتقلت إلى مكان اسمه كاليمدور...",
[1717900344]="لن يفعلوا.",
[1718272219]="سأنهي كيرين تور!",
[1719018414]="نحن على وشك الوصول إلى بر الأمان. من هنا، نركض. حاول ألا تتأخر كثيراً! انطلقوا!",
[1719666699]="أن أقاتل بني جنسي يحزنني بشدة.",
[1720863924]="السماء نفسها تتغذى على معاناة المهزومين!",
[1721181246]="لا أستطيع.",
[1721810628]="انظروا من هنا، إنه راليق الـ درنك... أمه سمينة لدرجة أن التنانين لا تأكلها...",
[1722137042]="قلوري ودماء للآلهة القديمة!",
[1722818452]="تحدث مع وينق كومندر براك، $N. سيزودك بواحدة من مدمرات الويفرن المدرعة لدينا. وحظًا موفقًا!",
[1722871876]="%s يلقي |cFFFF7F00تشوكينق قاز بومب!|r",
[1723112219]="بك أنا معًا، ستنتهي هذه المعركة في لمح البصر.",
[1723186524]="لا يزال النهار أمامنا، فلنرَ ذلك الفأس يقطع المزيد من الخشب.",
[1723387040]="لم أعد أسمع الصراخ. هل هذه هي النهاية؟",
[1724052915]="حر لـ--هم--الطيران الآن. را-آك... لن يجدونا--إخ-إخ! اهربوا!",
[1724291534]="مرحبًا كوربيت! هاأنت ذا! أتمنى أن تكون أعمال متجر الأقمشة جيدة...؟",
[1724635762]="لحظة... هل سمعت ذلك؟ شيء يقترب من الغرب!",
[1724643986]="إنهم لا يعرفون الخوف ومخلصون بلا تردد لإرادة سيدهم الشبيهة بالآلهة.",
[1726017406]="النجدة! يطاردني سوارم أوف بيز!",
[1726059930]="إنه كويلديلار! أنت تملك السيف!",
[1726153283]="جنود الـسكورج، استعدوا! جهزوا أنفسكم لإطلاق غضبكم على أرجنت داون!",
[1726583150]="تكلم بسرعة يا $N. ليس لدينا وقت كثير!",
[1727697191]="أطفال سول سيحمون سيدهم. انهض مرة أخرى يا سوليثوز!",
[1727967194]="الطقوس في كويلفانغ ستجلب اهوني بمجرد أن يصبح مستعدًا تمامًا، والصراع الناتج بين فايرلورد وفروستلورد سيمزق أسس هذا العالم. أهدافنا النهائية أصبحت في متناول اليد أخيرًا...",
[1727990758]="أهلاً بكم، أيها الأصدقاء!",
[1728101101]="تظن أنك ربحت أيها الفاني؟ واجه القوة الجامحة لأنتيوك!",
[1728253099]="هذه ليست معركة شريفة. أتوق لمواجهة أعدائي في القتال وفأسي في يدي!",
[1728712051]="اللعنة الأبدية هي مستقبلك.",
[1728759923]="لا أفهمك",
[1728767889]="أنتم مدافعون عن عالم محكوم عليه! اهربوا إلى هنا، وربما تطيلون حياتكم البائسة!",
[1729015395]="كنت سأضع بعض إيفرشاين في خزاني وأعود للبيت قبل أن يدركوا أنني ذهبت!",
[1729016809]="لقد سقط أحد المدافعين!",
[1729029213]="بصوت هامس... هنا، بجانب صندوق البريد. تعال بسرعة وتأكد أن لا أحد يتبعك.",
[1729437818]="سأهتم بالأمر، سيدي.",
[1730198924]="ارتباك...",
[1730412064]="أخبر حدادي الرون الخاص بك بمواصلة تحويل لا تستطيع من عمالقة الحجر. أولئك الذين لا يخضعون يجب تدميرهم.",
[1730668139]="يجب أن أذهب إلى مكان آخر كي أجد صيدًا أكثر. كنت أتمنى أن أكون فوق 48 الآن.",
[1731921104]="دمك سوف يغطي جدران كيلسورو!",
[1731959668]="لقد فشلت... فشلت في واجبي... خذلت شعبي... الـورجن ينتشرون بلا ضابط، ومِنجل إلهتي ضاع.",
[1732400991]="لماذا الـ بانشي كوين يترك حياتك الحقيرة؟",
[1732496333]="%s بدأ ينقر العلف.",
[1732975873]="%s يفحص الدم في القارورة.",
[1733191157]="أفعالك تخزينا كلنا يا $C. يؤلمني أن أضربك حتى تفقد الوعي!",
[1733480884]="هذه المرة ستموت للأبد يا هيكل عظمي!",
[1733762595]="إنه بالفعل كويلديلار. ما كنت أتوقع أن أعيش لأرى اليوم الذي يعود فيه سيف ثالورين داون سيكر الأسطوري إلينا.",
[1733800444]="بولفار كان مثل الأخ له. في غياب الملك، بولفار حافظ على وحدة الأليانس. وجد القوة لشعبنا في أحلك ساعاتنا. اعتنى بأندوين ورباه كأنه ابنه.",
[1734268337]="انتصار آخر للدرايناي!",
[1734307924]="حان الوقت لتصحيح الأمور. لتفكيك مملكتك الغادرة من القتلة واللصوص. كان بوترس الضربة الأولى. وسيأتي المزيد.",
[1734357446]="من أجل الأليانس واللورد فوردريغون!",
[1734834680]="تشجعوا أيها الصليبيون. أنتم لا تقاتلون وحدكم!",
[1734867595]="روح ابني لن تجد راحة في هذا النصر الأجوف، أيها التنين. سأستعيده. حتى لو استغرق الأمر ألف عام، سأستعيد ابني!",
[1735924400]="انمِ، أيها الصغير.",
[1737372093]="أنت لا تذكرني، أليس كذلك؟ الـسكورج الملعون... لقد حاولوا نزع كل ما جعلك قوة برايتوسنس. كل ذرة خير... كل ما جعلك أوركًا!",
[1738182991]="لا أدري. من المستحيل أن يتفوق على المرة التي حاول فيها إقناعنا بأننا جميعًا مجرد خيال في ذهن كائن ما وأنهم يستخدموننا فقط لتسلية أنفسهم. كان ذلك رائعًا أثناء العشاء مع العائلة.",
[1739201325]="إذن هذا ما يحدث عندما تقف قريبًا جدًا من قنبلة!",
[1740694574]="تراجعوا! ابتعدوا! يجب إعطاء الجهنمي مسافة واسعة!",
[1741146819]="إرادة السيد لا تزال مصانة...",
[1741245407]="ابحثوا عن ملاذ في هارثغلين! إنه أملنا الوحيد!",
[1741549163]="شرفنا قد لطخ! يطلقون ادعاءات كاذبة واتهامات باطلة ضدنا. أطالب بالعدالة! اسمح لأبطالي بالقتال بدلاً من فرسانك، تيريون. نحن نتحدى الـهورد!",
[1741606039]="اكوماي يطلب المزيد من التضحيات، الآن يجب أن تموت!",
[1741706876]="عد إلى التراب معك!",
[1742863579]="آه! إنه قادم نحونا!",
[1743353575]="إذا استمررت بهذا الهراء، سأعيدك إلى أمك في صندوق مع ملاحظة على صدرك تقول: فشل.",
[1743720234]="سأعود لمساعدة تحرير بقية العبيد. شكراً لك مرة أخرى، أيها البطل.",
[1743917870]="الـليجيون يسيطر!",
[1744568368]="يبدو أنني سأضطر للتعامل معك بنفسي. المحقق الأعلى يأتي من أجلك، أيها الـسكورج!",
[1744626976]="أيها الحمقى! أتسعون لطرد حضور والدي؟ الموت ينتظركم أيها البشر!",
[1744785239]="ألا تذكرني؟ كنا بشرًا ذات يوم - منذ زمن بعيد - حتى سقطت لوردايرون بيد الـسكورج. تحولك إلى سكورج زومبي جاء بعد تحولي بفترة قصيرة. بعد ذلك بفترة، تحررت عقولنا على يد الـدارك ليدي.",
[1744871482]="انتبه! نحن تحت الهجوم!",
[1744920336]="هناك... الآن لدينا ممر شحن.",
[1745183379]="لقد تم الأمر. $N، درعك جاهز.",
[1745190028]="%s يطحن اللآلئ التي أعطاه إياها $N...",
[1745275808]="لا أعرف كم سأبقى مفتوحًا اليوم مع كل هذه الفوضى بالخارج. إذا كان لديك شيء للإصلاح، سألقي نظرة سريعة.",
[1745601448]="تعزيزاتها ستصل قريبًا، يجب أن نُسقطها بسرعة!",
[1746442442]="لن تفسد الاحتفال!",
[1747102069]="الحلبة ستفيض بدماء المتطفلين! أولوف قد جاء!",
[1747244549]="آآآررررغغغغ!! يا لها من قوة!",
[1747448079]="كان آرثاس يستجمع قوة... من النوع نفسه... لعل طريقه هو الطريق الذي ستتبعه.",
[1747681554]="%s يبدأ في توجيه تعويذة انتقال هائلة.",
[1747733804]="أبصق على جثث هؤلاء الناغا القذرين.",
[1747773091]="تم الوصول إلى الوجهة - بدء مهمة الاستطلاع.",
[1748369137]="غررررر!",
[1748405511]="آه، $Gأيها البريست:أيتها البرايستس;، لقد جئت في الوقت المناسب. أقدّر ذلك.",
[1748431651]="لم تكن تستحق إنفاق الطاقة. <ناثانوس يبصق.>",
[1748976142]="حان وقت الحصول على بعض الإجابات! لنبدأ هذا الأمر!",
[1749148129]="إنه تاريخ... تاريخ سيليثوس... وآهنقيراج... والـتايتنز والآلهة القديمة... أقرأ من نبوءة كثون كما كتبها نبي القيراج سكيرام. نبوءة تنذر بكارثة...",
[1749376400]="حان وقت الموت، $C.",
[1750393317]="أنت عار على هذه العملية كلها! احزم أغراضك واخرج!",
[1750688230]="اعترف وسنطلق سراحك.",
[1750946560]="لا مفر!",
[1751041735]="كل ما حاربنا من أجله في هذا العالم ضاع. الآمال والأحلام التي حملها أبي وأمي... ودومر... ذهبت...",
[1751281246]="كما صُنع كويلسيرار على يد التنانين وأُعطي للكالدوري، فإن توأمه، كويلديلار، أُعطي لشعبي.",
[1751772859]="انظروا جميعًا، إنه $N!",
[1752182035]="هل تعتقد أنني بحاجة إلى المزيد من قطع فلير؟",
[1752244610]="فمن غير التايتنز أنفسهم يمكنهم إلقاء مثل هذه اللعنة؟ ما الذي يمكن أن يمتلك هذه القوة؟",
[1752475137]="%s يدخل في حالة غضب بعد رؤية صديق يسقط في المعركة!",
[1752936612]="أوه يا إلهي...",
[1752976430]="أنت تقرفني.",
[1753285342]="واجهوا حتفكم يا سكان السطح!",
[1753625550]="كسر هذا الشخص كان مرهقًا. الفظائع التي ارتكبتها في روحه. لقد قاوم طويلاً، لكنه سينحني قريبًا أمام ملكه.",
[1753647055]="السيد مورتوس سيغضب كثيرًا! سأعود إلى البيت الآن.",
[1753718558]="هل تشمون تلك الرائحة؟ لحم طازج اخترق قلعتنا بطريقة ما. احذروا من أي متسللين.",
[1754010639]="لكن الآن، بعد سنوات عديدة، أصبحت الويلدكين أكثر وحشية، وبدون توجيه الإلهة، هم مرتبكون...",
[1754139851]="العالم نسي ما هو السحر الحقيقي! ليكن هذا تذكيرًا!",
[1754397255]="اخفضوا أصواتكم. هناك غرباء حولنا...",
[1754502862]="أعتقد أنني رأيت مفتاحًا على أحد هؤلاء الـفريكول.",
[1754561137]="مصيرك محتوم.",
[1754655545]="احذر... المناطق العليا.",
[1754674011]="أدعو أن يكون المرض الذي أشعر به بسبب قسوف الإجهاد...",
[1755946254]="خذ هذه أيتها الهاربي الجرباء! هيا!",
[1756009668]="لقد عشت هنا وحافظت على هذا الضريح ببركة الألكسترازا لأطول مما أتذكر. في أحلك ساعاته، فشلت... سقطت عند أقدام ديث نايت الملعون ذلك... بلودبين.",
[1756639249]="ينكسر رمح كاو إلى نصفين ويسقط على الأرض!",
[1757591442]="حسنًا! دعني فقط أرى إن كان بإمكاني تشكيل هذه الأجزاء المقززة إلى شيء مفيد.",
[1757627056]="آه! هواء نقي أخيرًا! لم أكن أعتقد أنني سأرى هذا اليوم...",
[1758276249]="أنا... لقد مت... كنت في ألم شديد... مغمورًا بالظلام... هل تراني، $R؟",
[1758478046]="يطلق %s صرخة مرعبة.",
[1758697759]="يمكنك أن تختفي من أمامي، أيها التابع، قبل أن أقتلك. مرة ثانية.",
[1759505721]="هناك... هذا يكفي من الصخور لعمل عقد. ينبغي أن أعود إلى البيت الآن على أي حال.",
[1760058878]="ها أنذا: رعب مطلق!",
[1760828332]="تعال، $N. انظر ماذا يجلب نايتماير...",
[1761121430]="خذ دوكالز هورس، هو واحد منهم الآن!",
[1761929285]="ارجع!",
[1762419143]="ليس ما كان كييفر يأمله. يمكن كييفر زاد كمية جذر الأرض. خلينا نشوف إذا المصل الثاني سوف يعمل اللي كييفر محتاجه.",
[1762557256]="مسح إلدر آيرون برانش كشف عن آليات تثبيت نباتية.",
[1762804633]="ثورنلينق يبدأ بالنمو!",
[1762876875]="هذا هو الاختبار المطروح أمامك اليوم. ارجع لنا فقط بعد موت الـ آيرون وتشير، وستُبجّل كمحارب من فورستبورن.",
[1763133196]="ششش! أنت تخيف السمك.",
[1763196605]="عمل شاق تجميع هذه الأشياء معًا!",
[1764149009]="لا يُسمح لك بالتدخل!",
[1764325263]="اركع! اركع أمام آشبرينجر!",
[1764362266]="غريت فاذر وينتر على بعد رحلة وايفرن واحدة من أورقريمار.",
[1764530819]="أنا مدين لك، يا صديقي.",
[1764657137]="ماذا كان ذلك؟ سي جاينت؟ الأمان أفضل من الندم. أطلقوا النار!",
[1764974677]="وكل عدو يسقط، طاقته تُسلب وتُسرق، تزيد من قوة هجومنا.",
[1765048905]="همم، شكرًا لك أيها الغريب.",
[1765099817]="لكن نورث ويند لم يقبل الهزيمة بصمت. بدلًا من ذلك، جمع قوته وانتظر وقته، قرر أن أفضل انتقام هو تدمير ذاكرتك، ومعها قريتك.",
[1765304897]="%s يزأر بغضب.",
[1765650485]="افرغ كل الأكواب والبراميل!",
[1766010009]="لو كنت تصطاد كما تتكلم، لما بقي في المحيط سمكة.",
[1766449500]="أرني هذا الانضباط بتحية عسكرية مناسبة عندما أقول ذلك!",
[1767044901]="أيها المتنفس القذر!",
[1767120935]="أنت تختلق ذلك.",
[1767197321]="$N، سأحرص على أن يعرف كل أصدقائي في الكارتل أنك أنقذت حياتي اليوم. خذ هذا - سأحتاج للسفر بخفة، لذا تفضل من مخزوني من مستلزمات الخياطة والدباغة! شكرًا مرة أخرى - أراك لاحقًا!",
[1767479741]="ثاين باناهوق الموت القاضية سقطت على يد $N ورفاقه المقاتلين $Gخاصته:خاصتها;. $Gهو:هي; أمامه تحدٍ واحد فقط بعد $Gإياه:إياها;. من سيكون؟",
[1767505788]="اللعنة على الحملة! أعتقد أن أضلاعي مكسورة وقد أنزف داخليًا.",
[1768843717]="لكنها مطاردة... من عجوز شريرة خبيثة!",
[1769594598]="%s ضُرب بوضوح، يحاول الهرب.",
[1769697966]="النور يحميك!",
[1769766705]="لا! لن أُهزم!",
[1770260308]="تعال، $N. البحيرة قاب قوسين أو أدنى.",
[1770421628]="أبي، أريد الانضمام إليك في الحرب ضد الأنديد. أريد القتال! لا أستطيع الجلوس مكتوفي الأيدي بعد الآن!",
[1770940765]="السنة القادمة، سأرتدي زي قرصان أو قاتل.",
[1771467531]="شاهد عاجزًا آمالك وهي تنجرف بعيدًا!",
[1772071811]="هل أنا فقط، أم أن الـهورد أقبح عدو يمكننا إيجاده؟",
[1773223545]="سأمزق الأسرار من جسدك!",
[1773656551]="أهكذا تكافئ سيدك، أيها الكلب الأجرب؟ آررررغ!!",
[1773989190]="هذا خبر رائع! جهودك أنقذتنا حقًا، $N!",
[1774182678]="هل بقي لنا طريق طويل؟",
[1774274370]="انزل عن ذلك الحصان وقاتلني رجلًا لرجل!",
[1774783036]="أبعدهم عني!",
[1775036056]="[فوربولق] اتبعني إلى فارك.",
[1775257229]="ما كان يجب... أن أتراجع...",
[1775904060]="%s يكسر الختم على رسالة انتون ويبدأ في قراءتها.",
[1777148148]="ظننت... ظننت أنك... ميت.",
[1777294754]="هل كنت يومًا تشكل تهديدًا؟",
[1777331838]="يمكنني القتال إلى جانبك لبضع دقائق قبل أن أعود إلى خزينة شادو.",
[1777649536]="أيها الصيادلة! ضحوا بحياتكم من أجل التاج!",
[1777690904]="استريحوا لحظة ونظفوا رئاتكم، لكن يجب أن نتحرك مجددًا قريبًا.",
[1778304674]="ستدفع ثمن ذلك أيها العجوز. اقتلوهم جميعًا!",
[1778708472]="آمل فقط أن يعمل العلاج.",
[1778879788]="سنجد ما يبحث عنه السيد! الفشل ليس خيارًا!",
[1779213149]="أنت تحمل وصمة الـسكورج. استعد لدخول الـتويستينغ نيذر.",
[1779230468]="ماذا تسمي هذا؟ إذا كان هذا قتالًا فأنا لوثار نفسه!",
[1779408785]="سنشرب ونتشاجر ونتشاجر ونشرب،",
[1779484468]="احموا البرج!",
[1779621864]="هيا يا فتى، لا خطأ فيها - إنه أنت بالتأكيد. ألا تتعرف على أخيك الأصغر؟!",
[1780255561]="إذا كان قدرنا أن نموت اليوم، فلن نستسلم بسهولة! مارك لي، هؤلاء الشياطين سيسقطون كالقمح!",
[1780586862]="أعتقد أنني سأذهب لأخذ غفوة.",
[1780789276]="سلام جدًا...",
[1780882899]="انهضوا، جنود البوتقة الحديدية! لتكن مشيئة الصانع!",
[1781863198]="هذا الملصق المطلوب عليه مكافأة على قتلة العظام. هل تعتقد أنني يجب أن أفعل ذلك؟",
[1782007610]="رماد إلى رماد!",
[1782211853]="ينادونك بالوحش. لكنهم هم الوحوش، وليس أنت. وداعًا، ثرال.",
[1782457295]="أوه نعم، الانسلاخ - لا تفقده. هناك من أقاربي في بيرنينق ستبس من يصنعون أدوات لا يمكن تقويتها إلا بانسلاخ تنين الأسود.",
[1784221657]="أعدكم الآن، أيها الإخوة والأخوات: الـليتش كينغ سيهزم! في هذا اليوم، أدعو للاتحاد.",
[1784583839]="نهاية العالم!",
[1785022837]="أنا... أشعر... أشعر بلمسة إلون على كياني مرة أخرى... إنها تبتسم لي... نعم... أنا...",
[1785180661]="مع كل لحظة تمر، أرى شعب أزيروث يثبت مرة أخرى الأسباب التي جئنا من أجلها. بفخر مهيب أقاتل معكم، وإن مت اليوم، فأموت بين الأصدقاء.",
[1786368590]="تم اكتشاف تهديد جسدي! تحرك مراوغ! كاكا!",
[1786478912]="%s يندفع نحو أقرب دائرة رونية.",
[1786543075]="افعلها، $N! خلصني من بؤسي!",
[1786708925]="لم يضيع كل شيء! حاربوا هذه الوحوش دون خوف. جروحكم سأشفيها، وعظامكم سأجبرها. تجددوا أيها الأبطال!",
[1787325564]="شكرًا على التغطية!",
[1787329274]="فقاعة %s الواقية تتحطم!",
[1787350762]="%s يضرب صدره، طالبًا المساعدة!",
[1787423569]="ما كان ممكنًا أن تأتي في وقت أفضل! دعنا نخرج من هنا.",
[1787751477]="أرثاس! أقسمت أن أراك ميتًا وأن الـسكورج سيُفكك! سأكمل ما بدأته في لايتس هوب!",
[1788091640]="لا، بوبو. إنها تشبه الخنازير نوعًا ما. هل هي خنازير؟",
[1788414230]="أيها الأحمق ضعيف العقل!",
[1788792854]="انظر هناك، أيها اللحمي! موصلات صلحدار! إنه يبقى نفسه ممتلئًا...",
[1788904622]="%s يحرك صخرة.",
[1789261648]="يمكنك البدء!",
[1789540730]="بيتنا من هنا، عبر الغابة الكثيفة.",
[1789735248]="ثرال... لا يجب... أن يتحرر.",
[1789765395]="أتمنى أنك مستعد، $N. اتبعني.",
[1789818461]="كم حرارة يمكنك تحملها؟",
[1790140648]="أنا أقدم مما تتخيل. أظهر بعض الاحترام!",
[1790484630]="لماذا أنا!؟!",
[1791017740]="لا. ليس حقًا...",
[1791032243]="فيلومين أشال!",
[1791434115]="ها هو $Gبطل:بطلة; الخاص بنا هناك! كيف حالك، $N؟",
[1791764681]="قارك لوركرب، لقد تم اتهامك وإدانتك بالخيانة ضد الـهورد. كيف تدافع لا يهم. هاي إكزيقيوشنر نوزراك، تقدم.",
[1792002450]="يجب أن أذهب الآن. كن حذرًا!",
[1792040738]="هذه مجموعة مرعبة، مون، لا كلب جرب سيمشي بعد أن يضايق رجالي!",
[1792049137]="من وصفك، أنا متأكد أن الكتاب الذي أعطيته لزائرنا يمكن أن يسمح لك بتحديد السلاح بسهولة.",
[1792109498]="أنت قبيح جدًا ونحيف جدًا لتكون أنثى يتي! والآن أنت تغضبني...",
[1792371747]="أنا ريكسار، ابن الموك'ناثال، بطل الـهورد.",
[1792439591]="تغزون منزلي ثم تجرؤون على تحدّي؟ سأمزق قلوبكم من صدوركم وأقدمها هدايا لإله الموت! روالغ نجا غابور!",
[1792616587]="حسنًا إذن. ما هي تجارتك؟",
[1793067541]="أحسنتم أيها الـهورد!",
[1793068346]="ستتحقق العدالة.",
[1793696631]="الظلام ليدي يراقبك. أسرع!",
[1793736744]="وبسلطة، $N يهزم سيد الماغناتور! عشيرة ستينكبيرد ستفتقده في موطنه في دراغونبلايت!",
[1793933414]="التوتيم جاهز، $N.",
[1794927906]="الآن، لنرى...",
[1795040303]="هنا مخزوننا من بلورة الوباء، التي بدونها كان مشروعنا مستحيلًا.",
[1795169753]="لم أشعر بألم كهذا من قبل!",
[1795677617]="ليلادريس تنتظرني عند بوست مايسترا، فلنستعجل، $N.",
[1795950762]="لابد أن تخبر إخوتي أنني على قيد الحياة.",
[1797062986]="اجلس واشرب يا صاح! واجب لي واحدة أيضًا!",
[1797140409]="الهواء نفسه يتجمد مع دخول منافسنا التالي، آيسهاول! اقتل أو تُقتل، أيها الأبطال!",
[1797201987]="الـهورد سيسحقكم.",
[1797360271]="مع انشغال الـليتش كينغ بالبوابة الأمامية، سنتسلل من الجانب بحثًا عن معلومات تمكننا من هزيمة الـسكورج مرة وإلى الأبد.",
[1797371570]="كيف يكون هذا؟ ملك ليتش قال إن عنده خطط كبيرة لك، مون...",
[1797512411]="تذكر أيها البطل: أنا أيضًا سعيت يومًا للحصول على سلاح ذي قوة عظيمة...",
[1798117353]="ربما قاتلت بجانبي يومًا، كروك، لكنك الآن لست سوى خائن. تعال، موتك الثاني يقترب!",
[1798223496]="شكرًا، سيد كوالسكي! يمكنك العودة إلى موقعك للإشراف على الإرساء!",
[1798227895]="هذه الحرب - ولا تخطئ في اعتبارها أي شيء سوى حرب - لن تربح نفسها. إذا لم نقاتل، ونخدش، ونخالب، ونركل من أجل كل شبر من الأرض في هذا العالم المحطم، فسيضيع كل شيء.",
[1798705996]="لا بد أن العمل مزدهر في البازار. سأعيد تزويده بالمؤن فورًا!",
[1798752299]="قريبًا سيرتعد العالم.",
[1798754465]="$N لديه |cFFFF0000ليجن فليمز!|r",
[1798869868]="رأيت نومز يعملون بجد أكثر منك، أيها البيون! فتيات نومز صغيرات - بضفائر! تحرك، تحرك، تحرك!",
[1799204621]="عندما تصطدم الطاقات الموجبة الشحنة بالطاقات السالبة الشحنة، فإنها لا تلغي بعضها البعض.",
[1799284392]="الموت يطاردنا! دمره!",
[1799295552]="أنا جائع. الفاكهة تبدو لذيذة.",
[1799337399]="كانوا يومًا بشرًا... والآن؟ وحوش أنديد بشهية للحوم!",
[1800041491]="خلينا نخلصها يا ميز. حييجوا هنا بعد ثانية.",
[1800111882]="اهدأوا جميعًا! نحن نبذل ما بوسعنا للسيطرة على الوضع. أولئك الأوركس الملعونون لا يتوقفون!",
[1800418785]="%s يستعد للهجوم!",
[1801096191]="أرجوكم، تذكروا ما أظهرناه لكم...",
[1801567968]="أوه لا! ها هم جايين!",
[1801658884]="%s يطلق صرخة حادة.",
[1801906486]="عذاب عشرة آلاف سنة ينتظر أي أحمق يلبس درع كفالدر القديم. احذروا الضباب والغبار أيها البشر، فمعهم تأتي نهايتكم.",
[1802581623]="هاردكنكلز ما زالوا يمشون على أيديهم... يبدون أغبياء بالنسبة لغوريجيك.",
[1802933634]="وداعاً لكم، وليكن أجدادنا معكم دائماً!",
[1803151090]="%s ينفجر، ويغمر المنطقة ببقايا سحرية!",
[1803981923]="نعم يا ستي، التجارة ناشطة!",
[1804043679]="أثريكوس جاء إلينا. قال لنا إنه يقدر ينقذنا من الأذى. سحرنا لكي يحمينا من الأذى.",
[1804118668]="بأكل لحمك وأتسوك بعظامك!",
[1804134045]="لو كنت بشكل التنين، ما كان في مكان لأحد غيري، يا صغير.",
[1804224169]="«نحب الأشجار يا فينريك. توفر غطاء.» وما يخلوني أقطعها برضه.",
[1804273542]="حسنًا، قلها! ما الأخبار السيئة؟",
[1804595086]="يا رماة الفؤوس، ارموا أسرع!",
[1804831765]="يا جنرالي العزيز، جاء وقتك!",
[1805512424]="ممم، قليل من تزييت وكل شيء يضبط!",
[1806419772]="تلك اللي آلاف الناس كلهم يتفرجوا علينا من فوق في السما...",
[1806635661]="الأم الأرض تراقبنا؛ تحت غطاء الليل كما في النهار. لتُضِئ هذه النار أجسادنا وأرواحنا وتذكرنا بأسلافنا المكرمين، الذين هم حاضرون دائمًا ويوجهون طريقنا.",
[1806873778]="الموت لكل من يعارضنا!",
[1807058919]="اللعنة على الرجال! لا شيء سيمنعني من الانتقام، يا صديقي القديم. حتى أنت.",
[1807132943]="ماذا... تتحدث عنه، أيها الجلد الناعم؟",
[1807195773]="زانا! آه، يجب أن أصلح هذا الشيء!",
[1807587203]="أنا متشوق لسماع ما سيقوله أورك غاضب مثلك...",
[1807903136]="فوضى! هرج! أوه، أنت حكيم جدًا! نعم، أراها الآن، بالطبع!",
[1808393095]="عملنا لم يكتمل بعد.",
[1809003726]="شادرا، اجعلني صورتك المتجسدة!",
[1809078466]="أجل! ماغني سيسعد برؤيتك أيضًا! لم يتلق سوى الأخبار السيئة منذ فترة طويلة، لكن هذا يغير كل شيء!",
[1809383901]="فليكن كذلك.",
[1809700802]="سمعت قصة أو اثنتين عن حافظ معرفة في أولدامان يناسب وصفك. هل تخدم غرضًا مشابهًا؟",
[1810118360]="تبدو متعبًا...",
[1810308667]="%s يقهقه بجنون.",
[1810339822]="ها هي مستوطنة فارسترايدر الآن، $C. لم يبقَ بعيدًا... انتبه! كمين ترول!!",
[1810670729]="لو لم تأتِ لكنت مت بالتأكيد!",
[1810691616]="الكبرياء يبشر بنهاية عالمكم. تعالوا أيها البشر! واجهوا غضب سولفلاير!",
[1811283485]="إلدر مانا'لوا، التمثال هناك، يراك. هذه علامة جيدة!",
[1811864749]="أنا أعيش فقط لخدمة السيد، يا سيدتي.",
[1811901435]="ضربة قوية وُجهت إلى الـليتش كينغ! لقد أثبتم أنفسكم كأبطال أقوياء في الحملة الأرجنتية. معًا سنضرب آيس كراون سيتادل وندمر ما تبقى من الـسكورج! لا يوجد تحدٍ لا يمكننا مواجهته متحدين!",
[1812403725]="كم كوبولد يلزم لتغيير فتيل مصباح؟",
[1812551297]="سأريك الوصول، أيتها الآلة البائسة. ها هو مرة أخرى: مفتاح نورغانون!",
[1813663687]="أعداد رفاقي تتضاءل، يا إلهة، وقوتي ستصبح قريبًا غير كافية لصد شياطين فيلوود.",
[1813799788]="عملاء إس آي:7 التابعين للملك فاريان جمعوا معلومات عن محراب خاص للـليتش كينغ في أعماق مكان يُدعى هولز أوف ريفلكشن.",
[1813958011]="أنا ضجر، كلاودوينغ. اذهب، اذهب!",
[1814204539]="يجب أن أعود إلى دن نيفيليم. سنتحدث قريبًا مرة أخرى، يا ستورم لورد.",
[1815104700]="تخلَّ.",
[1815395945]="تحول مثير للأحداث.",
[1815396189]="هل جئت لتلعب؟ إذن فلنلعب!",
[1815410210]="دوم لورد كازاك سيكون مسرورًا. عليك زيادة وتيرة هجماتك. دمر معاقل الأوركس والدوارف بكل سرعة.",
[1815528306]="إنجوريد رينسبيكر أوراكل يقف على قدميه بشكل أخرق.",
[1815672566]="أنت من يجب أن— انتظر، لدينا زوار...",
[1816190255]="وشعرك يبدو رائعًا.",
[1816561578]="مفمم رفممم ررومغف؟",
[1816765889]="دخلاء في القلعة! إلى السلاح!",
[1816922806]="انتبه! يبدو أن هناك المزيد منهم!",
[1817019717]="مقبرة ستورمبايك تم الاستيلاء عليها من قبل الـهورد!",
[1817053195]="حسنًا، ليست فكرة جديدة تمامًا، أختي.",
[1817075037]="انظر في المرجل، $N. مارج تريد التحدث...",
[1817175114]="شكرًا لك، أيها الصغير.",
[1817232646]="%s يبدأ في الازدياد قوة.",
[1817762286]="جرعة $N فسدت. يجب صنع واحدة جديدة من الصفر.",
[1817821114]="غضبهم يتضاءل أمام غضبي، إيليدان. بيننا بعض الأمور العالقة.",
[1817853870]="أفعل ما يجب فعله!",
[1817960382]="يبدو أن عملي هنا انتهى. أبلغ الصورة المجسمة لأمير عند المرسل.",
[1818040029]="هل اكتشفت شيئًا؟",
[1818197153]="هذا بالضبط ما احتجته!",
[1818311582]="هذا ليس سيلفرمون سيتي! أين نحن؟ أوه، لقد التبس علي الأمر للحظة.",
[1818853103]="آه، البيض المرقط اللذيذ الحلو - ستكونون لي...",
[1818995560]="أصغر شرارة ستكون هلاكك.",
[1819186223]="يبدو أنك أفسدت هذه الدفعة من البلاء. ماذا لديك لتقوله لنفسك؟",
[1819426357]="أين ماما؟",
[1820052857]="إذاً... ظننت أنك ستخدعني، أليس كذلك؟ أعظم عبقري إجرامي عرفه أزيروث؟",
[1820195532]="واربرينغر، هذا سيتطلب استخدام كل الجحيميين في القلعة. قد يتركنا عرضة لهجوم مضاد.",
[1820489107]="سعيد برؤيتك مجدداً يا إيمي. كوني بأمان يا حبيبتي. أنا متوجه الآن إلى غولدشاير.",
[1821604428]="هناك ما يكفي للجميع. إذا احتجت بضائع أخرى، لا تتردد في السؤال!",
[1822201365]="ماذا سأفعل؟",
[1822373424]="أنت بحاجة إلى الذكاء السحري، لأن الإجابة واضحة! لا!",
[1822381313]="إنه يؤلم!",
[1823047914]="إذا تم كتم صوتك، أو كانت لديك أسئلة حول عملية الكتم/إلغاء الكتم، يرجى زيارة... ززززت!!",
[1823064652]="هزمنا وحش البحر!",
[1823093145]="يجب أن أكون ممتنًا... لكني فقدت القدرة على ذلك منذ زمن بعيد...",
[1823300883]="لا تقلق، ليريسا. سأعود إليك عندما أنتهي. لا شيء في العالم سيمنعني من العودة إلى المنزل، إلى العائلة الوحيدة التي تبقيت لي.",
[1823376466]="الحمد لله أنك جئت في الوقت المناسب. من فضلك، خذ واحدًا من صناديق الترول هذه لتتذكرني به.",
[1823812025]="لقد... انتهى... الأمر...",
[1823970359]="هي، $Gرجل:سيدتي;؟ عندك بعض المال؟ عندي خمسة عيال لأطعمهم!",
[1823983139]="ينبغي لأحد أن يصنع حلوى بحشوة نوم مقرمشة من الداخل.",
[1824539877]="بالضبط.",
[1824693128]="ممم، أنت تحارب إيكيس؟ آه-آك!",
[1824783371]="إغراء القوة عظيم. أخطاء حصلت.",
[1826013158]="لقد أدينا دورنا، وأحسنا فيه. الأمر الآن متروك للآخرين.",
[1826055211]="هذا... لا، احتفظ بمالك القذر! لن يساعد عائلتي!",
[1826817491]="ديل ما'اهن... أورينديل'و.",
[1826939666]="أنا أحترق!!!",
[1827207153]="سيتعين علينا شطب المارودينز من قائمتنا. من الصعب جدًا العمل معهم...",
[1827448391]="لا تضيع وقتك على ذاك، إنه ضعيف!",
[1827531772]="تحذير! بدأت عملية إيقاف الطوارئ %s بواسطة $N. سيتم الإيقاف خلال دقيقتين.",
[1827764007]="هذه أوقات مظلمة وصعبة لنا جميعًا. جيوش الـسكورج تتجمع في الجنوب. الرفاق يسقطون في ساحة المعركة وينهضون ليخدموا عدونا بعد لحظات.",
[1828682434]="نتيجة محسومة.",
[1829026026]="نعم، النتيجة المنطقية الوحيدة.",
[1829163924]="غالاكروند كان سلف التنين. من غالاكروند شكل التايتنز الأسبكت الخمسة.",
[1829240301]="ليستا، استدعِ أسرى أنديد.",
[1829583234]="ارتجف وموت!",
[1830842573]="العشائر متحدة تحت قيادة بلاك هاند في هذا الهجوم. سيقفون معًا حتى يسقط ستورمويند.",
[1830979626]="أنا أحتفظ بالخنزير كحيوان أليف!",
[1831169409]="%s يصدر صرخة تصم الآذان!",
[1831568213]="مواطنو الأليانس، لورد بلاك روك قُتل! تم إخضاع نيفاريان بقوة مشتركة من حلفاء $N و$Gخاصته:خاصتها;!",
[1832452074]="الممثل الكوميدي يقلد أنثى هيومن.",
[1832775189]="إصابة مباشرة على مبنى الرصيف! تم تنبيه المدافعين عن دراغون فلاير!",
[1832845207]="نعم... غولدان...",
[1833526736]="%s يشل حركة مورادين وحراسه.",
[1833942391]="إلى أين تظن أنك ذاهب؟ اقتلهم جميعًا!",
[1834111449]="لاااااااااااااااااااااا...!",
[1834148779]="لقد ارتكبت خطأً فظيعًا ومكلفًا. لم يحن وقتي بعد، أيها البشر.",
[1836022584]="جميع أنواع الخبز هنا! طازج اليوم. احصل عليه قبل نفاذه!",
[1837169174]="لا أريد أن أُضحى بي!",
[1837611994]="لقد جئت متأخرًا! تم التفاوض على الاتفاق. لم يتبق سوى التفاصيل. تفاصيل صغيرة... مثلك!",
[1838040151]="أتباعي...",
[1838130822]="قوة الدوارف ممثلة اليوم ببطل الـآيرونفورج العظيم، لانا ستاوثهامر!",
[1838497509]="إذا كنت تريد استعادتها، فسيتوجب عليك التوسل!",
[1838515624]="أنت لا تقاتل وحدك، $N! معًا، سنطرد هذا المخلوق الناري!",
[1839223491]="%s يبحث عن مصدر للطاقة الأركانية.",
[1839383385]="أتذكر كم كان الهدوء قبل أن يأتي الإلفز إلى هنا؟ أفتقد ذلك.",
[1839473126]="ستغادرون على شكل قطع!",
[1840301777]="في النهاية، ستخدموني جميعًا.",
[1840307377]="أرجوكم، أيها البرايستس، اغفروا لنا اقتحامنا. لا نريد إيذاء أحد هنا.",
[1840413370]="الداركويفر يخترقك بابتسامة شريرة وهو يتحول إلى شكل مختلف تمامًا.",
[1840858946]="هي! توقف عن ذلك!",
[1841206552]="لقد دربتهم جيدًا، فوردرينغ. لقد قدمت أعظم قوة قتالية عرفها هذا العالم... في يدي - تمامًا كما أردت! ستُكافأ على تضحيتك غير المقصودة.",
[1841292098]="حان وقت تأملي، اتركني.",
[1841370533]="لقد انتهيت... فقدت الكثير من الدم... انسَ أمري، أخبر كيلر... لا يزال هناك أحياء بالداخل...",
[1841721142]="نعم، أيها الضعيف... توسل إلى لوريد من أجل حياتك!",
[1842648930]="تشكلوا! لنتخلص منهم بسرعة!",
[1843360016]="ويأتي إلي الناس من جميع أنحاء العالم ليدفعوا لي الجزية... ويتعلموا الصيد.",
[1844199667]="سنقطع حناجركم وننزفكم حتى الموت!",
[1844413218]="عدت لأكون حطامًا صدئًا قديمًا.",
[1844886790]="الموت أرحم بكثير لأمثالك.",
[1844979379]="سالثي، هل تعتقد أننا نسمح لكثير من 'غير المرغوب فيهم' بالانضمام إلى الحفلة؟ أنا قلق بشأن ما قد يعتقده أصدقاؤنا عن كل هذا.",
[1845089627]="صادرات هيرازي في ازدياد، يا سيدي. لقد رشونا بالفعل مسؤولي الضرائب المختصين، وستبدأ البضائع المهربة في الوصول خلال أيام.",
[1845181710]="أنت من كان يعكر الأمور؟ هذا يجب أن يكون سهلاً.",
[1845916224]="يجب أن أجهز التحضيرات اللازمة قبل أن تبدأ طقوس اليقظة. يجب أن تحميني!",
[1847167375]="كل واحد عنده نقطة ضعف، بس المهم إنك تلاقيها.",
[1847677134]="حاضر يا سيدي.",
[1850586909]="ما أعتقد في سمك في هالقنوات.",
[1850701347]="%s يفتح فمه كأنه سيضيف شيئًا، ثم يبدو أنه يقرر أن الصمت أفضل.",
[1850999204]="نار الـهورد ما تنطفئ أبدًا!",
[1852054350]="اشهدوا على القوة اللي ما تنهزم لوارتشيفكم! انهضوا بهتاف حماة التنين!",
[1852435599]="كينق ماقني برونزبيرد أحمق ودجال!",
[1852449205]="أنا جاي بالألم!",
[1852635148]="قروك يحتاج مساعدة! لماذا ما أحد يساعد؟",
[1852700979]="أريد أن ينتهي هذا الكابوس!",
[1853353391]="اعرف... ألمي...",
[1854057057]="نيبتولون العزيز! كان ذلك... مشروبًا واحدًا... أكثر من اللازم!",
[1854061460]="من يتحدى ناياس؟ أيها $R الحقير، أنت أفضل قليلاً من أولئك الترولز الأغبياء الذين لعبت بهم ضد بعضهم مثل قطع على رقعة الشطرنج!",
[1854129405]="سيد بيريلي، إذا صادفت أي علامات على نشاط الـسكورج أو تعاملات مريبة في رحلاتك، أخبر أقرب لورديرون سولجر بذلك.",
[1855515212]="ننتظر المغامر التالي ليأتي ونخبره أن هذا هو الطريق... ثم بعد أن يفجر الألغام، ندخل ونأخذ الأدوات!",
[1855544309]="ثرال سيبقى عبدًا. تاريثا سيموت. لقد فشلت.",
[1855757959]="القليل من الوقت الذي كان لديك، أضعته!",
[1856619221]="لا تعود هذه المرة!",
[1857333908]="ربما... كنت على حق، كروك.",
[1857376142]="أييي!!",
[1858200580]="أعتقد أن أصوات أطفال الـدرايناي هي التي أربكت معظمهم... لا تنسى أبدًا...",
[1858296006]="%s يحترق بسحر مطلق!",
[1859251987]="%s يطلق غاز سبورز!",
[1859340040]="كم من الوقت ستستمر قواتك في الصمود؟",
[1859358265]="ما زلت تقاتل. ما زلت تتشبث بمبادئ مضللة. إذا نجوت، ستجدني في الحلقة المركزية.",
[1860321523]="تعزيزات في الطريق. يجب ألا تتوقف الوظيفة.",
[1860685323]="يا إلهي، السمك لا يبدو أنه يعض هنا. ربما يجب أن أذهب إلى بحيرة كريستال لأجرب حظي هناك!",
[1861049838]="نحن هنترز، أنا وأنت. لا رجال ذئاب هنا، لا سيدتي.",
[1861138013]="وكأنه ليس لدي ما هو أفضل لأفعله في شيخوختي من حمل دلاء الماء.",
[1861180173]="سوف نستعبد الكويلبور!",
[1861313884]="قد الطريق، أيها الظلام ليدي. سوف نتبعك.",
[1862322123]="واحد بائس سقط. تفضل، خذ واحدًا آخر!",
[1862576692]="هذا يبدو المكان المثالي لقيلولة...",
[1863627402]="أسمع أشياء... أشياء لا ينبغي أن تكون.",
[1863966873]="لماذا نتحالف مع ترولز قذرين نتنين؟ الترول الجيد هو الترول الميت.",
[1864376741]="اقتلوهم جميعًا!",
[1864419506]="بم تفكر يا سيدي؟",
[1865193223]="أحسنتم أيها الجنود! لم نكن لنسمح لحيوانات الـهورد القذرة أن تتفوق علينا!",
[1865727048]="سوف تعاني ببطء حتى نهاية الزمن بسبب هذه الإهانة!",
[1866318298]="أناخ كيري!",
[1866813446]="لهذا نسميكم كائنات أدنى!",
[1866970092]="مؤسف، لكنه ضروري.",
[1867367120]="متى يبدأ التدريب؟",
[1867767922]="السيطرة على الضرر! أطفئوا تلك النيران. لم تروا آخر الـهورد!",
[1868395292]="هذا أفضل قليلاً من السابق. لكنه لا يزال يعاني من نفس البنية العظمية الهشة مثل الآخرين. عندما تستدعي واحداً من هؤلاء، فأنت على الطريق الصحيح.",
[1868577860]="القتل رقم 26 وما زلت أحمي نفسي فقط.",
[1868591095]="بيرة ساوثشور، كيف أحبك؟ دعني أعد الطرق...",
[1868861900]="اهرب، أيها الجبان، اهرب!",
[1868973267]="تحليل إلدر ستون بارك يكشف عن دفاع صوتي يعطل استخدام السحر.",
[1869137327]="وجدتني، إيه؟ الآن يجب أن تموت!",
[1869382948]="كيف، حبيبتي؟ كيف سأجد القوة لمواجهة عصور العالم بدونك بجانبي...",
[1869545150]="ابقَ متيقظًا!",
[1869722186]="إذاً ظننت أنك ستجعل من مورغور أضحوكة، إيه؟ قبل أن تُسلم إلى اللورد إيليدان، ستشعر بألم لم تكن تعلم بوجوده. سأستمتع بانتقامي بنفسي.",
[1869874473]="ماذا أيضًا يمكنه أن يضعه في طريقي؟",
[1870035489]="شكرًا لك، $N. وحظًا موفقًا لك.",
[1870212940]="إذاً كيف أصبح فاذر إينيقو مونتوي، حصن الفضيلة للفجر الفضي، تجسيدًا لأكثر ما كان يكرهه؟",
[1870487662]="لم يكن خطأه. أخبره بذلك...",
[1870727730]="يبدو أن الـسكورج ضرب المنطقة الأمامية بشدة...",
[1871425244]="أخبرها... أن آخر أفكاري كانت عنها...",
[1871592381]="حان وقت إغلاق نيمو.",
[1872170570]="سنحرقها بالأرض قبل أن نعطيها لك!",
[1872184661]="مرحبًا، مرحبًا، إيمي. من الجيد العودة إلى ليكشاير ورؤيتك، يا سيدتي.",
[1872300927]="الألم... الحاجة... أنا جائع للمزيد...",
[1873215737]="هاه! قتلة غوريجيك!",
[1873394490]="تم التحقق من أن المراقب فريا لم يعد موجودًا. اكتمل التحليل.",
[1873439710]="ما الذي يمكنه أن يخلص هذا المكان النجس؟ شكرًا لك.",
[1873568276]="هذه الوحدة تعمل حاليًا بكفاءة تشغيلية تبلغ خمسة وتسعين بالمئة.",
[1874056471]="هذه الأرض كانت ملكي قبل وقت طويل من وضع أقدامكم الحقيرة هنا.",
[1874432221]="اسألني لاحقًا - أحاول حك أنفي ومن الصعب التركيز.",
[1874681181]="لقد وصل، أوقفوه!",
[1875503498]="تحدث إلى القائد في موقعك، $Gفتى:فتاة;، وأقنعه بالتخلي عن خطة فورتاك الحمقاء.",
[1875844208]="هل سمعت شيئًا؟",
[1875986656]="عندما يتجمد بلاك روك!",
[1876216780]="كادا نو باتيكا، أوهت!",
[1876281692]="الممثل الكوميدي يقلد بلود إلف.",
[1876654087]="مرحباً $N!",
[1876792731]="أوه، دارو شاير! سأضحي بألف حياة من أجلك!",
[1877465240]="$N قادم نحونا!",
[1877558509]="أنت لست أفضل منهم!",
[1877720053]="مطرقة الأبرار!",
[1877786146]="آه... أنا ليس حاسّ حالي زين.",
[1877932630]="ما تتذكرني، صحيح؟ الـسكورج الملعون... حاولوا يشفطوا منك كل شيء خلّاك قوة عدل. كل ذرة خير... كل شيء خلّاك $Gابني:ابنتي; من آيرونفورج!",
[1878000452]="قتلة... أنقذوا... الـماجيسترا...",
[1878829946]="عقلك الهش سيتحطم!",
[1879151879]="تأكد أن ما يتبعني أحد.",
[1879732361]="أعمال خادمك $R تخالف مكانة $Gخاصته:خاصتها; يا ستورم لورد. جهود $Gخاصته:خاصتها; نجحت في تليين قلوب شعبي.",
[1879769203]="هي! هي، $R! عندي الشي المناسب لك. شفت تيكبالانغ من قبل؟ مخلوقات مخيفة. تحب تخطفك. اللي تحتاجه هو أحد تمائم التيكبالانغ خاصتي. مضمونة لطرد كل التيكبالانغ!",
[1879792347]="نعم، نات؟",
[1879961694]="ميج-لورد يوروم هو هدفنا التالي. يفترض أنه يختبئ على إحدى المنصات العائمة في حزام التحويل، قرب قمة الأوكيولس. انتبه، يوروم ساحر قوي؛ قد لا يكون وحيدًا.",
[1880394998]="مزاج وسلوك المراقب هودير غير مستقرين للغاية. تدمير المخبأ محتمل جدًا أثناء القتال الطويل.",
[1880791089]="أنت ستموت مع كل هالـسكورج!",
[1880900014]="إذا كان عندك وقت، قريمكلو وسيده فولكور ممكن يحتاجون مساعدتك. إذا مهتم، تكلم معي أكثر...",
[1880985706]="قاروش، كفى!",
[1880999163]="الإغلاق الطارئ مكتمل.",
[1881485811]="%s ينظر إلى لوتويل بعصبية.",
[1881768669]="كم هذا مثير... الحجر يمتلك إمكانات سحرية عظيمة، لكن في شكل خام بحت...",
[1882525193]="إيري، $N جلب جلودك. أرجوك، خذيها قبل أن تسبب لي المرض.",
[1883209709]="هل أحتاج أن أخبرك ماذا سيحدث إذا فشلت قنبلة المانا في الساحة في إصابة هدفها قريبًا؟ منذ انتقالهم إلى الغابة، أصبحوا مصدر إزعاج متزايد لعملياتنا: هنا، وفي توريم، وفي الجنوب عند أطلال بونتشو.",
[1883252655]="لا أستطيع التصديق... كلهم... موتى.",
[1883736658]="تم النشر بنجاح. سيتم تحييد المتسللين.",
[1883757721]="النجوم تتحدث إلي. تهمس بأهوال تنتظر في الليل.",
[1884119445]="لا أمل لك!",
[1884172986]="أمثالك هم من يضعفون الأليانس ويدعون الـهورد يسلبون كل ما حاربنا من أجله!",
[1884698351]="هل أتيت لإنقاذ هذا العالم؟ لتطهيره؟",
[1884991803]="%s يصرخ من الألم ويلتف، ممسكًا بك بفمه!",
[1885573174]="أوه، يا له من عمل شنيع!",
[1886236121]="سيكون عليك شق طريقك عبر هذا المحجر بنفسك.",
[1886325135]="لقد تأخرت أيها الساعي. لا، لا أريد أي أعذار؛ هذه المهمة مهمة جدًا.",
[1888237599]="لقد تحملت الكثير من المشقة لإكمال أبحاثي وبمساعدتك، $N، لقد فعلتها أخيرًا. نخب مستقبل أكثر إشراقًا!",
[1889582876]="حسنًا، أعتقد أنني مدين لك بشيء صغير - خذ واحدة من هذه. لدي الكثير.",
[1889767358]="كان بإمكانك أن تكون أعظم بطل لي، فوردرينغ: قوة ظلام كانت ستغسل هذا العالم وتوصله إلى عصر جديد من الصراع.",
[1890785611]="مرحبًا، هارلان. إليك حمولة من القماش المحبوك.",
[1890843779]="استمتع بالموت، يا كب كيك!",
[1890943704]="مرحبًا، بلم! أعطني كوبًا من ثاندر إيل، وواحدًا لصديقي العزيز $N.",
[1891604945]="اشتقت لك كثيرًا، يا أبي!",
[1891771445]="إعادة تقييم التهديد. اكتمال تقييم الهدف. تغيير المسار.",
[1891911048]="لقد التهمني هورغوس! ما زلت أشعر بأنيابه علي!",
[1891989937]="الرهان الذكي على النومز ليفوزوا بالسباق التالي! ضع أموالك بينما لا تزال قادرًا!",
[1892199964]="أستسلم! هذا كل لا يوجد الأمر من عبقرية الجوبلن!",
[1892234104]="نطالب بإجابات!",
[1892513532]="\"حقير\"؟ لا يهمني من أنت يا صديق: لا أحد يصف الـميلهاوس مانستورم العظيم بـ\"حقير\"!",
[1892535670]="إذا كنا نريد نفس الشيء حقًا، أكاماً، فأطلق سراحي! إذا كان إيليدان سيموت، فسيكون بيدي أنا!",
[1892817778]="من أجل الـهورد الحقيقي!",
[1893213891]="الـسكورج اخترقوا جميع الأجنحة! ليُهزم هذه المخلوقات الشريرة النور! سنقاتل حتى النهاية!",
[1893590736]="سموها... تنتظر.",
[1893856210]="ريز اتبعوا $N! ريز حطّم الصيادين! حطّم حطّم حطّم! قل لـريز يحطّم باللعب بالعصا! حطّم!",
[1893920307]="كائن قديم يستيقظ في البعيد...",
[1894024239]="هذه ستحقق لي ربحًا جيدًا عندما أعود من البحار الجنوبية.",
[1894865518]="لا، يا دم من دمي، إنهم جنود الأليانس. أعداؤنا اللدودون.",
[1895495856]="ها قد انتهى درسنا عن الاستدعاء. سيبدأ درس جديد قريبًا، لذا إذا أردت المراجعة، فابقَ هنا.",
[1895670882]="أيوا يا مستر كوالسكي.",
[1895743192]="أنت تقترب من القرية الآن. ابقَ عينيك مفتوحتين.",
[1896038370]="ستخبرني أين هم!",
[1896183001]="%s ينظر إليك بارتياب.",
[1896596405]="مُجلّدو العظام في البراري ليسوا مزحة. سمعت أنهم يحملون أمراضًا!",
[1896700232]="اللعنة عليك! لن تعاملني كوحش!",
[1897477975]="لاااا! أمي! سننتقم لك!",
[1897648759]="علينا فقط أن نرحل هكذا؟",
[1897880096]="لست متأكدًا كيف يجد ناس العجوز طريقه دائمًا إلى هنا. لا بد أنه عن طريق الرائحة...",
[1897880534]="تتمنى مواجهة السيد؟ يجب أن تتحمل العاصفة أولاً!",
[1898504670]="طعام! سأأكلك!",
[1898533752]="لقد... فشلت...",
[1898905705]="...إنها هبة، تُمنح بحرية لكل الكائنات المولودة طبيعياً.",
[1899531800]="كنت أظن أن عددكم أكبر...",
[1899815939]="دم طازج دافئ... لقد مضى وقت طويل.",
[1899893880]="ها هو جسدي، لائق ونقي! الآن، أرواحكم السوداء سأشفي!",
[1900651253]="أريد المزيد من الجعة! أعطني المزيد من الجعة!",
[1901208846]="أوبس!",
[1901652111]="لا تتركوا ناجين في أثركم، أيها الإخوة والأخوات!",
[1902135933]="ممم، بري بلودمول!",
[1903092323]="من منكم يستطيع تحمل قوتي؟",
[1903314892]="بالتأكيد ستستثنوننا، إيه؟ قد لا نعود.",
[1903348753]="عائلتي كلها قُتلت! أين كان الجيش عندما كنا بحاجتهم؟",
[1903649761]="%s تأخذ حجر القمر ساوثفيوري وتهرب إلى النهر. اتبعها!",
[1903797628]="لا يجب أن يهربوا!",
[1904099026]="نحن على وشك الانتهاء!",
[1904486534]="مهاجمون من الشمال الغربي! أطلقوا النار!",
[1904643535]="إيليفر، سيدك يناديك!",
[1904675506]="أوه، جيد، بدأت أقلق.",
[1904719652]="نشاط الـسكورج في الـبلاجلاندز زاد عشرة أضعاف. نستقبل تقارير عن هجمات الـسكورج من أماكن بعيدة مثل كاليمدور! كيف تعتقد أن هذا حدث؟ كيف فعل الأنديد البائسون ما كان يُعتقد سابقًا أنه مستحيل؟ هل لا يوجد مكان آمن؟",
[1904891438]="أرى من خلال تنكرك، $R. نمبر تو! نمبر تو اقتل!",
[1905570630]="آآه... جيد جدًا. الآن انصرف!",
[1905832042]="القليل من التعذيب، وقليل من السحر، وكثير من الجراحة التوغلية. كانت واعية بالطبع.",
[1905874305]="لا تمانع إذا توقفت هنا للحظة، أليس كذلك؟",
[1906015926]="سألتهمكم جميعًا!",
[1906368579]="وجبات خفيفة للبيع!",
[1906368837]="وارلورد ناغا! يا للهول...",
[1906487055]="مرحبًا بكم أيها المجندون الجدد. أنا دريل سيرجنت باهدوم. للأيام القليلة القادمة، ستتلقون توجيهًا.",
[1907015845]="...الهاربون يسعون إلى ثيرامور حيث سيكون المواطنون أحرارًا في التلاعب بالكرات طوال ساعات اليوم؟ ما هذا الهراء؟",
[1907337254]="كل البشر سيهلكون!",
[1908133184]="خذ هذا! الـدراي ويسكرز سينتصرون!",
[1908261764]="لا أستطيع الصمود... عدم استقرار...",
[1908669054]="ها! أنا أكثر خوفًا من أن تلك الثقوب والجروح القديمة ستفجر ذلك الشيء وسأغمر بالشظايا!",
[1908886933]="أنا أعمل عليه، فقط لا أريد بيعه حتى أكون راضيًا عنه. لن يطول الأمر.",
[1908889186]="أكيلزون، الغزاة يقتربون!",
[1909231689]="%s يقذف صخرة سارونايت ضخمة عليك!",
[1909477737]="كلها جزء من خطة السيد... نهايتك حتمية...",
[1909525965]="هل أنت مستعد للضحك!",
[1909751713]="ستون كرو مغلق اليوم، آسف. هناك مخاوف صحية كثيرة، ولن أسمح لإد أن يتعرض للنيران بسبب جعل الناس مرضى.",
[1909808311]="...ابتكارنا!",
[1910613057]="هذه البطولة تساعد في تشكيل قوة متماسكة وقوية، رغم أنها قد لا تبدو واضحة. عندما نكون مستعدين، ستتجه أنظار الحملة وجميع أبطالها نحو آيس كراون.",
[1910614535]="هل ظننت أن خيانتك ستُنسى؟ ضائعة في التغطية المدبرة لموتي؟ دم من دمي، شعر النصل بقسوتك طويلاً بعد أن توقف قلبي عن الخفقان. وفي الموت، عرفت ما فعلته. لكن الآن، قيود كيلثوزاد لم تعد تقيدني. جئت لأحقق العدالة. أنا آشبرينجر.",
[1910904035]="أهلاً بك، بيسي. لقد جاء دورك للنزهة اليوم، أليس كذلك؟",
[1911238388]="لقد تم الأمر $N، وأعتقد أنك ستكون راضياً عن النتائج.",
[1911525247]="لقد كوّنا صديقاً جديداً!",
[1911680874]="جائع جداً...",
[1912189695]="من موتك تنبثق حياة جديدة!",
[1913133380]="سنمنحك موتاً سريعاً، آرثاس. أكثر مما يمكن قوله عن الآلاف الذين عذبتهم وقتلتهم.",
[1913567501]="%s يتلاشى بعد توقف طويل.",
[1913576677]="ضعف الألم ونصف المتعة.",
[1914356793]="الآن، أين هو؟",
[1914673154]="عالم الظلال ينتظر...",
[1914689173]="%s يحاول الانقسام إلى اثنين.",
[1914787212]="يستخدمون الرعب والخداع - غالبًا ما يقلبون الأخ على أخيه بينما تسقط عوالم بأكملها أمام تأثيرهم المظلم.",
[1916043413]="نعم... سيدي.",
[1916048493]="%s يبدأ بترديد تعويذة غريبة...",
[1917317701]="فاهتفوا بعباراتكم المبتذلة وتخبطوا حتى تنهكوا. في النهاية، ستكونون لي، وموربيدوس سيكون نذير موتكم!",
[1917360727]="$N هُزم!",
[1917398566]="أيها الحمقى العميان المساكين!",
[1917582201]="أنا... أنا محطم... الأورك الأعلى الجديد هو $N!",
[1917752609]="ها! أصابع السحر القديمة نجحت أخيرًا! الآن لننزل إلى--",
[1918047488]="باسم كيلجايدن!",
[1918848148]="أقتسوف استراتيجية جديدة: أنت تجذب هجماتهم بينما أجمع التعزيزات.",
[1918946090]="أراك أيضًا تجمع الأرواح لأغراضك الخاصة. هل نحن حقًا مختلفان كثيرًا، أيها البطل؟",
[1919275873]="ليكن... لقد حُذرت.",
[1919482863]="لا! لعنة هذا الجسد البشري الضعيف!",
[1919894964]="هل هذا صحيح؟! هل جاء أحد أخيرًا ليخرجني من هذا المكان؟",
[1920354003]="المعركة القادمة ستكون ضد أقوى فرسان الأرجنت كروسيد! فقط بهزيمتهم ستُعتبر جديرًا...",
[1920505995]="الظلام سيلتهم كل شيء... كل الأحياء...",
[1920513599]="%s يواصل البحث، واضعًا المزيد من الجماجم في صندوقه.",
[1920901204]="توقف! أيها الأحمق $C، لا يمكننا السماح لك باستدعاء المخلوق مايزريل!",
[1921714190]="محاولتك الهزيلة للهروب لن تطول، غوريفيند. اترك $Gولد:بنت; واستسلم! حتى بدروعك وأسلحتك، لا يمكنك هزيمة القدماء!",
[1921743228]="اقترب أكثر، وسأصرخ.",
[1922081798]="الطاعون أصبح غير مستقر!",
[1923140984]="ها أنت ذا.",
[1923633367]="لقد نجوت وأنا لحم مرة أخرى!",
[1924639278]="لا يمكنك الاختباء مني!",
[1925061109]="%s وقواته الغازية يظهرون وسط اضطراب ناري في الشمال الغربي من سيليثوس.",
[1925959303]="ابتعد عن ممتلكات الملازم!",
[1926065196]="النور يأخذك، أيها الوحش!",
[1926743565]="أنا... لم أتوقع ذلك....",
[1926839054]="مقبرة ستونهيرث تم الاستيلاء عليها من قبل الـهورد!",
[1927321163]="تنبيه: إجراءات الأمان معطلة. بدء مسح الذاكرة و...",
[1927514629]="كل هذه ممتازة. سيكون من الصعب اختيار واحدة فقط.",
[1927753554]="كان شرفًا عظيمًا أن أقاتل بجانبك في الدفاع عن أرضنا وشعبنا.",
[1928065013]="أخشى أن عليك أن تسأل الـ -- حسنًا، ربما كاليكوس يمكنه المساعدة.",
[1928689081]="نقف هنا!",
[1928776625]="وأسماك التاستي قد ذهبت لهذا الأسبوع! سأبقى لمدة ساعة أخرى للسماح لك بتسليم أسماكك!",
[1928826902]="لا تقل أنني لم أحذرك....",
[1929085668]="كنت أعرف أنه كان عليّ تأمين قفل العربة بشكل أفضل عندما كنت في أندورهول.",
[1929523516]="تورتة لا بد أنه قلق جدًا.",
[1929565919]="شكرًا لكم، أيها الغرباء. لقد منحتموني الأمل.",
[1929616945]="لصوص! أوقفوهم!",
[1929641295]="لا أعرف ماذا يرى بلاك مور فيك. بالنسبة لي، أنت مجرد متوحش جاهل آخر!",
[1929775342]="أعلم أنك جديد على جنسنا، لذا سأطلعك على الأمور قليلاً بينما نحن في طريقنا.",
[1929801763]="لا. سأغادر هذا العالم بالطريقة التي أختارها. وسأعود، بإرادة الأدميرال الأعلى!",
[1930393088]="أوخ! حسنًا، سأعود إلى العمل، $N!",
[1930492505]="كيفن جوردان وجونثان لى كرافت!",
[1931130292]="قد يبدو الأمر بلا جدوى، لكن حاول أن تجد فخرًا في القتال الجيد. سيأتي الوقت الذي ستُستخدم فيه كل هذه الممارسة والمنافسة بشكل جيد.",
[1931138547]="كان... محتومًا.",
[1931392531]="%s يتنقل ويبدأ في توجيه تعويذة!",
[1931452083]="هؤلاء اليابسة هنا من أجل الرنة! أعطهم الطعنة!",
[1931547128]="%s يحدق في الحراس.",
[1931622851]="استنزف... الحياة!",
[1931893411]="ويسكر! أين أنت؟! ساعدني!",
[1932520816]="آثار حوافر غامضة، دروع محترقة، شارات ضائعة... كيف نفهم كل هذا؟",
[1932815723]="هل تخاف الموت؟",
[1933454584]="هل ظننت حقًا أنك تستطيع هزيمتي؟ أصدقاؤك سيلحقون بك قريبًا، تايلان.",
[1933491873]="%s يلقي فروست تومب على $N.",
[1933515557]="خذ شمعة الاستدعاء من هذا الصندوق، $N.",
[1934018891]="قف منتصبًا! ضعفك يقرفني!",
