[1950203432]="تال أنومن نو سيندوراي!",
[1950253921]="لابد أن يومك سعيد. حسنًا، سأتحدث. فقط اتركني وشأني. انظر، لن تصدقني، لكنه كان... أوه، يا نور، يبدو أن الفتاة تستطيع الرماية...",
[1950891682]="بدا الدوارف تائهاً، لا يتذكر من أين أتى، ولا حتى اسمه. ولأنه ليس من النوع الذي يترك ابن عم دوارف يموت في الثلج، فقد استضافته مجموعة والدي وأكملوا طريقهم نحو فروستهولد.",
