[1996341850]="انحنوا! اركعوا أمام آشبرينغر! فجر جديد يقترب، أيها الإخوة والأخوات! رسالتنا ستُوصل إلى قذارة هذا العالم عبر المختار!",
[1996373396]="ألم تظن أنني سأدعك تدخل هنا وتأخذ قلب العاصفة، أليس كذلك؟",
[1996403442]="ماما!",
[1996472261]="عندما تحطم الـهورد، عاد الرجال إلى هنا وبدأوا في إعادة بناء المدينة العظيمة التي كانت يوماً كشهادة على بقائنا.",
[1996535176]="%s يفعل هوديرز فيوري.",
[1996537466]="أعرف الطريق، أيتها الحشرة. لا داعي لوخزي كما لو كنت ماشية.",
[1996563328]="%s يبدأ تعويذة استدعاء...",
[1996803753]="سافيرون. كان تنيناً أزرق نبيلاً في جبال نورثرند، قُتل سافيرون على يد آرثاس خلال حملته عبر الشمال المتجمد. أُعيد إحياؤه ليخدمه، سافيرون يحرس مخبأ كيل'ثوزاد أبدياً، منتظراً من يجرؤ على التعدي على سيده.",
[1997105776]="مستحيل! أيها اللورد ثوريم، سأجلب لأعدائك موتاً متجمداً!",
[1997507898]="افعل كما أقول لك، $N.",
[1997513574]="لكن بالتأكيد لا يمكنك أن تعتقد أن هؤلاء الأطفال وُلدوا أبرياء؟ لكانوا كبروا وحملوا السلاح ضدنا!",
[1997975328]="اكولايتز، قيدهم جميعًا! جهزهم للاستجواب!",
[1998036504]="انهضوا يا محاربيّ وقاتلوا من أجل سيدكم الجديد!",
[1998049140]="%s ينظر حوله بتوتر.",
[1998450557]="تجرؤ على تدنيس معقل فروستمان، $R. استعد للموت!",
[1998536820]="هل أنت صديقي، داني؟",
[2000410580]="مهرجان القمر كان دائمًا أكثر أهمية للكالدوري. المهرجان الكبير للدرويدز بالتأكيد في أوج نشاطه.",
[2000671886]="استمر في العمل. إذا كانت شكوكنا صحيحة وهذا ناقل، فقد يكون مفيدًا جدًا في هجومنا.",
[2000937217]="لا أكثر من بعوض!",
[2001420791]="%s يُسلّم.",
[2001614093]="قبضة الآلهة القديمة لا تتحرك. لقد استهلكته أفكارهم المظلمة... أنا... لا أستطيع... لا أستطيع الاستمرار أكثر... إلون أعني...",
[2001771991]="اخضعوا أمام إبداعاتي المرعبة!",
[2002098534]="أحسنت! يجب أن أكون بخير وحدي من هنا. تذكر التحدث مع ديلغرين عندما تعود إلى بوست مايسترا في أشنفال.",
[2002495442]="أخيرًا... تحرر من قبضته الملعونة!",
[2002511002]="أنت دائمًا جائع. لهذا نحن سمينان جدًا!",
[2003153795]="ألعاب جديدة؟ لي؟ أعدك أنني لن أكسرها هذه المرة!",
[2003443257]="احذر! أنا تحت الهجوم!",
[2003749616]="لدي مفن هنا. تعالوا!",
[2003831371]="نسله تعلموا درسهم قبل وقت طويل. ستتعلم درسك قريبًا!",
[2003874646]="آآآآه...",
[2003923075]="بقسم أورغريم! هذا الإندوريوم يقاوم حرارة هائلة!",
[2004236933]="%s يختفي بومضة!",
[2004348876]="هل انتهى الأمر حقًا؟",
[2004528775]="أيها المراقب، أخبر ألثيا أن تهديدًا خطيرًا يتجمع ضد بلدتنا. يجب أن نستعد!",
[2004626225]="يا للهول! الإكس-52 نيذر-روكيت يتعرض لهجوم! حراس! حراس!",
[2005110387]="ليس لدي الإمدادات الطبية اللازمة لعلاجكم جميعًا بشكل صحيح.",
[2005478300]="عندك تيكي مسحور؟ لقد قتلت عائلتي!",
[2005699063]="بلود إلفز سيلفرمون يهتفون لـ$N.",
[2006039456]="أشعر أن الجميع يريد تقبيلي تحت نبات الهدال.",
[2006280099]="ميسري...",
[2006318210]="لماذا تهتم، ثاساريان؟",
[2006393251]="إييع!",
[2006669577]="آه، فرصة لاستخدام هذا النصل المشحوذ حديثًا.",
[2006712363]="الدرع سقط! انهضوا يا أتالاي! انهضوا!",
[2007805520]="تعذيبك يزيد غضبي فقط!",
[2007935156]="تم تفعيل دورة الإصلاح التلقائي.",
[2009523400]="أنت على حق، بالطبع. استمر.",
[2009635190]="حافظ على التركيز.",
[2009965040]="بابا يقول إن في المحيط سمكة كبيرة لدرجة أنها تستطيع ابتلاع سفينة كاملة.",
[2010878000]="لن أخذلك يا سيدي!",
[2010912919]="انتهى نفيي! دع الدماء تتدفق!",
[2011149875]="%s يدفن نفسه في الأرض!",
[2011550239]="سأجعل الأمر سهلاً قدر الإمكان لك. فقط تعال إلى هنا ومت. هذا كل ما أطلبه مقابل تعدياتك الكثيرة. لتدنيسك هذا المكان المقدس للمعركة.",
[2011562121]="إنه لي!",
[2011728147]="شكراً لمجيئك هنا لذكراي. جهودك في استعادة ذلك الرمز، رغم أنها غير ضرورية، إلا أنها تمس قلب رجل عجوز.",
[2012052653]="نحتاج منك إرسال تعزيزات إلى مانافورج دورو، أردونيس. هذا ليس طلباً، بل أمر.",
[2012411184]="لقد نجحنا! اعتني بنفسك، $N، وشكراً مرة أخرى!",
[2012731353]="لقد آلمني!",
[2012788900]="لن أُهزم!",
[2012911017]="الأرجنت كروسيد قادمة من أجلك، آرثاس!",
[2014340026]="أوقفوا أسلحتكم! أنا أستسلم!",
[2014725789]="هذا رائع يا ريمبلات! حتى هذه الأرض الفاسدة المتصدعة ليست بعيدة عن الشفاء.",
[2014917502]="فكوك %s القوية تمزق الطعام.",
[2015463440]="ليتني أستطيع العودة إلى غابة الفطر. لم أرَ مجموعة ناضجة كهذه في حياتي!",
[2015965723]="أخيرًا انتهى الكابوس...",
[2016618849]="موت! موت!",
[2016664799]="الآن، $N، دعنا نطلق أرواحهم ونسمع ما لديهم ليقولوه.",
[2016760699]="استعدوا لعودة القدماء!",
[2016933411]="ستكون بخير.",
[2017026813]="بيجو يعرف أين تخبأ الكنوز.",
[2017189493]="تعالي، أختي! سيدك يناديك!",
[2017508876]="لقد سافرت طويلاً وخاطرت كثيراً لتكون هنا! إخلاصك سيكافأ.",
[2017783705]="سأحضر كيس السم إلى ريكيت... وبعدها... تعرف... أنهار. شكراً لمساعدتي!",
[2018046418]="لا أحد سيوقفنا!",
[2018139362]="سنشرب دمهم ونأكل عظامهم!",
[2018434499]="أنت أيها الكلب المدلل لـآرثاس؟ ستموت!",
[2018584155]="ارمي بعض البناطيل في الحوض!",
[2018763618]="لقد وصلت للتو من آيرونفورج و، بوي!، أجنحة دابتي متعبة!",
[2019320694]="إنها حية!",
[2019586372]="رفيقك يبحث عن شيخ الشاردهورن فارون، الذي يبقى منعزلاً عن إخوته.",
[2019650219]="هيه، أيها الأبله!",
[2020550523]="برافو، جيرارد، لقد تفوقت على نفسك، مرة أخرى.",
[2020901593]="هذا القتال لا ينتهي. لست متأكدًا كم سأتحمل منه.",
[2021233438]="فساد فيلوود حبس روحي هنا... قد لا أستريح أبدًا...",
[2021281331]="أوم نا-ل أك-ك-ك-ك، إشش.",
[2021809027]="ماذا بحق النور...؟",
[2022116513]="أزرق زائد أحمر... أتوقع...",
[2022170689]="أعدتك!",
[2022226085]="لا تنس إخراج جرسي من الصندوق هنا. وتذكر، إذا ضللت الطريق، فقط رنه وسأجدك مجددًا.",
[2022433850]="هم القلب النابض لـبيرنينغ كروسيد.",
[2022445899]="هاه؟ ما هذا؟",
[2022981532]="ألف موتة....",
[2023238928]="نعود إلى الموضوع... يجب أن نركّز على هذه المصانع السحرية. يجب أن نعرف ماذا يفعل العدو بها ولماذا.",
[2023251211]="يا أسيادي! جئت إليكم!",
[2023649267]="%s يسلم حقيبتها لـكواي.",
[2023729229]="ظننت أني هالك. شكرًا لتحريري.",
[2023923380]="روم وبنات للجميع!",
[2024389397]="%s يقلّب صفحات كتاب ضخم بجنون.",
[2024616257]="هذا المولّد يغذي نظرة ميميرون. بلحظات، يمكنه تحويل التراب لرماد، والحجر لحمم--لا يمكننا السماح له بالوصول للطاقة الكاملة!",
[2024840716]="قد تكون هذه النهاية لك يا داليا. يا لها من خسارة.",
[2024990665]="صحيح. صحيح. النور يساعده إن تحرر ذلك الوحش يومًا!",
[2025193271]="أشكرك، غاروش. لدينا الكثير لمناقشته عندما أعود من زيارتي للجراندموذر.",
[2025196928]="هذا موقفنا الأخير. ما يحدث هنا سيدوي عبر العصور. بغض النظر عن النتيجة، سيعلمون أننا قاتلنا بشرف. أننا قاتلنا من أجل حرية وسلامة شعبنا!",
[2025364330]="رينقو! أنت بخير!",
[2026161978]="أنا ملك الثعابين! أستطيع فعل أي شيء!",
[2026411675]="أفكار %s تغزو عقلك.",
[2027006246]="تبرعوا... بجسدي... للعلم...",
[2027214601]="موت! لا مكان لأمثالك في الترآك فالي!",
[2027748466]="دعني أقاتل بجانبك.",
[2027953940]="[شيطاني] كا كاليكس!",
[2028316169]="شكرًا مرة أخرى، $N. سأنتظر هنا الآن حتى يصبح الخروج آمنًا.",
[2028436853]="بعد اختبار الحركة هذا، سيبقى لنا فقط فحص الأسلحة النهائي.",
[2029132710]="كما يقولون: هذا الشبل من ذاك الأسد. أنت ضعيف الإرادة مثل تيريون... بل ربما أكثر. أتمنى فقط أن يكون قاتلي قد نجحوا أخيرًا في إنهاء حياته البائسة.",
[2029722090]="الـهورد. من شكل المعركة، هم هنا بقوة - في مكان ما.",
[2030063798]="$Gملك:ملكة; $N، أنا أموت الآن.",
[2030114078]="سيحضر لك الميد، سيحضر لك البيرة...",
[2030252018]="لم يتبق سوى نصف قوة ختم الباب! عليك القتال!",
[2030642890]="آه!!! ما هذا الشيء؟!",
[2030948294]="هل تخطط لمغادرة المنطقة قريبًا إذا كان لدينا المزيد من الأسئلة؟",
[2030951534]="قوتك تتلاشى، أيها القديم... قريبًا ستنضم إلى أصدقائك.",
[2030961640]="أرجوك لا تضربني!",
[2031106394]="الـهيلمزمان قادم إليك!",
[2031287762]="كويلديلار.",
[2031290192]="لنتقدم للأمام!",
[2031348355]="والآن عرفت كل ما يمكن معرفته، أيها الفاني...",
[2031350537]="روحك ستذبل للأبد.",
[2031875884]="لقد اكتفيت من هذا المكان. وداعًا.",
[2032131154]="%s يشير إلى إبريق الماء الموضوع على حافة البئر.",
[2032519425]="صحيح، نورثريند أرض قاسية، لكن شعبنا قوي، صلب، وقادر على المهمة!",
[2032650056]="موقع الحفر شمال هنا.",
[2032923587]="الخام المستخدم في هذه العينة نشأ من عمق قشرة أزيروث وتم اكتشافه مؤخرًا.",
[2032993150]="أنت أحمق لخوض معركة كورون اليائسة!",
[2033182660]="يارررررر! لن تحصل على منظاري أبدًا يا قذر!",
[2033307424]="آآآآآآإييييييييي!!!!",
[2033789301]="أشوف ناس موتى!",
[2034236222]="دفنت ابني اليوم، ثالڤوس... وزوجتي الأسبوع الماضي.",
[2034242641]="مصيرك محتوم!",
[2034252447]="$N، سأعرف هذه القرون في أي مكان... ماذا... ماذا فعلوا بك، $N؟",
[2034345792]="حسنًا، إذا جئت لتقتلني أنا أيضًا، فهل تستطيع الانتظار حتى أطعم قريزيلدا؟ البنت المسكينة لم تأكل منذ أيام.",
[2034651934]="آرثاس! لا يمكنك فقط—",
[2034804535]="هي... أنا ليس حاسس حالي زين.",
[2034915274]="حرروني، يا شياطين!",
[2034975110]="أين كنت أعيش قبل هذا؟ كنت أعرف. على الأقل ظننت أني أعرف...",
[2035114570]="كنت لأقول تعال بهدوء، لكن كلينا نعرف أن هذا ما سيصير. صديقي الصغير هنا سوف يسهل طريقك إلى الحياة الأخرى.",
[2035826867]="كانت معركة قوية. أنا أستسلم لك.",
[2035883787]="هنا ينتهي الأمر!",
[2036079888]="ميجز كيرين تور، بأمر بران، ارفعوا الدرع! دافعوا عن هذه المنصة وحلفاءكم بحياتكم! لأجل دالاران!",
[2036213739]="أظن أنه لا يوجد شيء آخر نفعله. اللعنة!",
[2036261442]="لا تقلق! بران العجوز يحمي ظهرك! أبقِ هذا الوحش المعدني مشغولًا، وسأرى إن كنت أستطيع إقناع هذه الآلة بمساعدتكم!",
[2036593923]="تلك التي أكون فيها في دورنهولد وذلك الأورك الذي يحتفظ به بلاك مور كعبد شخصي يهرب...",
[2036650802]="إيسير وفانير... حسنًا، فورج أو ويلز بدأ يصنع إيرذن جديدة... لكن ماذا حدث للقديمة؟",
[2036907896]="سيلاما أمورونور!",
[2037082692]="لا أستطيع أن أشكرك بما يكفي على كل مساعدتك في تجميع حجر الأساس. ستأتي أشياء عظيمة من هذا، أؤكد لك.",
[2037597182]="لن تنتهي هكذا! لقد عملت بجد! سنوات طويلة... سأستهلك المزيد من الطاقة!",
[2037693426]="%s يخلع القفاز من ذراعه اليمنى ويُظهر للجميع يده المشوهة.",
[2037709052]="أرِ ضيفنا أرجاء شاتراث، هل تفعل؟ راقب النشالين في المدينة السفلى.",
[2037728320]="ماقتور، شكرًا لك على السماح لي بالبقاء هنا معك. أنا متأكد من أن هناك الكثير الذي يمكننا تعلمه من بعضنا البعض. وأنا متشوق لتعلم كل ما يمكنني عن المفقودين في الشرق.",
[2038496917]="خيانتك لإمبراطورية دراكاري جلبت لي جيشًا جديدًا.",
[2038748013]="اهربوا! اهربوا نحو التلال!",
[2038770735]="هل هذا صحيح؟ كم هذا مثير للاهتمام. عزيزتي، لمَ لا تذهبي وتجملي أنفك؟ لدي الكثير لأفكر فيه.",
[2039460024]="كابوس أورسال انتهى! نحن أحرار!",
[2039636256]="بلحيتي! الـهورد يبحرون بسرعة وحرارة!",
[2039732316]="مطهر بالألم!",
[2040190241]="تراجع، مورادين. دع أبًا حزينًا يمر.",
[2040832640]="شاهدوا قوة الأليانس! السيدة المخيفة، اونيكسيا، معلقة من الأقواس! دعوا صيحة قاتل التنين ترفع معنوياتكم!",
[2041099355]="أنا لست وحدي.",
[2041142556]="هذا الأسبوع قد تكون عين سلمندر، أو ربما خريطة كنز. لن تعرف أبدًا ما لم تنظر. ماذا قد يكون عند أنطونيو؟",
[2041270889]="انهضوا... انهضوا وتغذوا على لحومهم!",
[2042255590]="عيب الفناء...",
[2042274932]="ارحل أيها الإلف التافه. أنا المسيطر الآن!",
[2042364699]="حقير صغير... آ-آك، كاو! اقتل! نعم، أقتلك!",
[2042411996]="لا شيء أفضل من أمسية للصيد!",
[2042576292]="ثلاث كلمات - \"أب - سو - لوتلي\"!",
[2042754013]="كوني بسلام، يا حبيبتي، يا لوهانا.",
[2042783783]="الآن، ابتعد عن حضرتي. من الحكمة ألا تقترب من ناظري مرة أخرى.",
[2043199794]="أحسنت، $N. إظهارك للاحترام قد لوحظ. الآن، لدي معلومات يجب أن تنقلها إلى الكالواك.",
[2043243713]="%s يبدأ في إلقاء ويلينق سولز!",
[2043361471]="انتبه! نحن تحت هجوم من $N!",
[2043505774]="ها، 54! في المرحلة الأخيرة الآن!",
[2043565385]="سافيرون يستأنف هجماته!",
[2043966067]="ما كان ينبغي لك المجيء إلى هنا!",
[2044044423]="سستعاني من هذا الاقتحام!",
[2044284001]="يبدو أن %s مشوش.",
[2044486314]="احصل على بيرة مجانية في حانة بيغ أند ويسل!",
[2044561741]="أنا... لقد تحررت من قبضته... أخيرًا.",
[2044673777]="تحدث...",
[2044736196]="يا له من قتال فاتك يا دوريان! كان من المعارك الخالدة!",
[2044972360]="من يجرؤ على المقاطعة--ما هذا؛ ماذا فعلت؟ ستدمر كل شيء!",
[2045041216]="إي-نوك كريول!",
[2046194779]="إنه يومك المحظوظ، زوتفيزل. $N أحضر لك المزيد من الصغار.",
[2046224780]="إنذار! تم وضع علامة عليك للإبادة.",
[2046543590]="أرجوك، لا مزيد! ابني... لقد أصيب بالجنون!",
[2046565411]="أعتذر عن التأخر في الوصول إلى هنا. أردت أن يكون ليدي براودمور حاضرًا أيضًا.",
[2046742344]="ما معنى 'حساسية' أصلاً؟ وما علاقتها بأي من قطيّ؟",
[2046879265]="%s يحيي خادمًا أنديدًا إلى الحياة!",
[2047193134]="عند رؤية رفيقه يهلك، يصبح %s غاضبًا!",
[2047200676]="أراك لاحقًا، يا صغير!",
[2047510956]="%s يجمع آلة غريبة بمهارة.",
[2047729437]="كنت سأقتله على أي حال!",
[2047827824]="يبدو أنني قللت من مهاراتك. أحسنت.",
[2047859399]="أظن لا. ستسقط مناعتك، أوقف طقوسك الآن وأطلق سراحهم!",
[2047978255]="اشربوا أيها البشر! تذوقوا دمي! تذوقوا موتكم!",
[2048247027]="بوم! هذا رائع جدًا! المزيد! المزيد!",
[2048572436]="لقد تجاوزت أعظم آمالي.",
[2048834014]="هذه هي الأعمدة...",
[2049109381]="لا أخاف شيئًا! وأنت أقلهم!",
[2049170333]="الإلفز يتحدثون عن إلهة القمر، هل تعلم؟ يضعون ثقة كبيرة في ضوء القمر.",
[2049176506]="كن يقظًا! الأوركس وحلفاؤهم قريبون!",
[2049356153]="شكرًا لك، سيدة تشامبرز.",
[2049590184]="استمروا في التحرك، يا ناس.",
[2049849720]="في هذه الأثناء، تمكن الملك من الهروب من آسريه، وعاد إلى ستورمويند ليتعامل مع اونيكسيا.",
[2050322648]="%s ينعق بحماس بينما يوجه نظره إلى السفينة الراسية.",
[2050669177]="أعتقد... أعتقد أنه يعمل!",
[2050810336]="هذا هو مصيرهم...",
[2051295061]="الشحنات المتفجرة ستنفجر بعد ثانيتين...",
[2051462723]="شكرًا لك، يا مرمم الأرض.",
[2051632422]="لا تواجه العدو دون استعداد، $N. يمكنني تزويدك بأشياء قوية جدًا... بشرط أن تثبت نفسك لنا.",
[2052186260]="كريبت غارد ينضم إلى القتال!",
[2052292140]="أجل، توقف عن مضايقتي الآن!",
[2052430689]="سأعود إلى الأركيفوم وأرى إن كنت أستطيع تعطيل إشارته. ربما أستطيع كسب بعض الوقت لنا بينما تتولى أمره.",
[2052600222]="يجب أن أجهز بعض الأمور أولًا. تقدموا أنتم وابدأوا. أنا بحاجة إلى استدعاء قليل من الماء...",
[2052739007]="أنا محظوظ إني على قيد الحياة!",
[2052781832]="قدامك الطريق المؤدي لتيلار. سنفترق عند المفرق لأنهم أكيد سوف يرسلون ورانا المزيد من موركبلود. نأمل أن أحدنا يوصل تيلار حيًا.",
[2053162388]="أخيرًا! خذ هذا الخشب وتحرك. الـهورد لن يظلوا يقاتلون هناك إلى الأبد، وهناك مال يجب كسبه!",
[2053258063]="ماذا؟ أتتحدث معي يا ولد؟",
[2053408431]="%s يلوح وداعًا للجميع.",
[2054145148]="تيريون سقط! دافعوا عنه بحياتكم!",
[2054589561]="حسنًا، $N، لقد فشلت في التصرف. النبوءة ليست لك لتتعلمها. لا تناديني مجددًا حتى تجد عمودك الفقري!",
[2054599006]="هذه ليست طريقة قتال الأوركس! واجبي تجاه الـوارتشيف يتعارض مع شرفي الشخصي. لا أؤمن بنورك، ولكن بما أنك تبدو مستشارًا، فأنا مستمع لكلامك.",
[2055327055]="%s يبدأ في تفعيل فيرال الدفاعر!",
[2055485292]="%s يتنفس بشكل غير منتظم.",
[2055698189]="فكر، $N. فكر بالماضي. حاول أن تتذكر دوروتار، $Gأخي:أختي;! تذكر التضحيات التي قدمها أبطالنا حتى نتحرر من لعنة الدم. ارجع إلى وادي التجارب، حيث وُلدنا من جديد في عالم خالٍ من تأثير الشياطين. وجدنا روعة الحياة، $N. معًا! هذا ليس أنت. لقد كنت بطلًا للهورد يومًا ما!",
[2055826626]="هل ستتوقف—",
[2055857358]="يجب ألا يكون لدى الشياطين أي شك في أننا أعداؤهم، ورغم أنهم يتمنون تدميرنا، إلا أننا من سنجلب لهم الخراب. سيتم إضعاف كازاك وقواته وهزيمتهم على يد هذا الائتلاف. ولتحقيق ذلك، يجب أن نرمي بأجسادنا وقلوبنا عليهم، لأنهم لا يسعون إلا إلى محو هذا العالم.",
[2055884937]="هذا آخرهم. لا تتهاون!",
[2056016614]="سيدي، الطالب يطلب منك ضربه لعدم فهمه!",
[2056317131]="%s يراقب دمه وهو يبدأ في التحرك، ودهاء الرابتور يتسلل من خلاله.",
[2056805237]="شعبك سيكون معك دائمًا!",
[2056855073]="%s يهز قبضته بإحباط.",
[2057320316]="وليمة الفساد انتهت! ماقثيريدون سقط ببراعة قتال $N وحلفاء $Gخاصته:خاصتها;! شاهدوا قوة الأليانس! قائد بيت لورد دُمّر!",
[2057600648]="هل البر حقًا ما يدفعك؟ أتساءل...",
[2057790777]="ناجمارا! هل بقي عندك لحم ضأن؟",
[2057893826]="جاهزون للتحرك، أبقوا هؤلاء الدوارف بعيدًا عن ظهورنا!",
[2057908315]="%s يبتسم.",
[2058562790]="جهزهم جيدًا، رايلوراز. قوة ماليقوس ليست مثل أي شيء رأوه. على الأرجح سنؤخر خططه فقط بهذا التحويل.",
[2059239435]="الآن عرفت. الآن يجب أن تموت!",
[2059325219]="لكن، لا يهم. على الرغم من 'مساهمة' مستر كليمنتاين... خطأ، يبدو أن هذه مذكرات رجل اسمه نولكاي. المدخلات في النهاية تصف معركة شرسة.",
[2059534296]="أنا مصاب، لكن لا يزال بإمكاني الركض. شكرًا لك، أيها الغريب.",
[2059962475]="لا أستطيع الانتظار حتى ننتهي من التجهيز. ثم أستلقي وأستمتع بالاحتفالات.",
[2061070078]="أرجوك، لا مزيد.",
[2061332722]="أكمل التعويذة يا ستاغهيلم! لا أستطيع الإمساك برموز الحماية لفترة أطول! استدعِ الجذور!",
[2061983555]="موق، ادخل إلى الداخل. ليس آمنًا بالخارج بينما والدك غائب.",
[2062477607]="آخر مرة خرج فيها أحدهم لمحاولة جمع الجائزة على نيثروك، كل ما عدنا به كان طبقة مضغوطة من مغامر متهور!",
[2062913317]="فورًا، يا جلالتك!",
[2063335694]="ألقِ نظرة حولك، $N. ربما تجد شيئًا فاتني.",
[2063528529]="كفى تشتيتًا!",
[2063540233]="أفيقي يا فتاة. يجب أن تدُمري الـليتش كينغ في المكان الذي اندمج فيه مع نيرزول - فوق القمة، في الـ فروزن ثرون. إنها الطريقة الوحيدة.",
[2064008204]="كفى! أضيع وقتي هنا. يجب أن أجمع قواي في العالم الأم.",
[2064016965]="الجو هادئ هنا...",
[2064149909]="من أعماق الأندر هولز يأتي كارنيج. $N الشجاع والأحمق قبل التحدي. مجموعة $Gهو:هي; و$Gخاصته:خاصتها; مستعدة لمواجهة الوحش.",
[2064700874]="حظ موفق هناك، $N.",
[2064830679]="لماذا لا تستسلم؟ لماذا تقاتل المحتوم؟",
[2064893295]="فلتبدأ التطهير!",
[2065027154]="آه، امينة الثمين! كم هو رائع رؤيتك مجددًا.",
[2065577615]="خائنون! يوم الحساب قادم ومعه نهايتكم! انظروا حينها إن كان ملككم ليتش سينقذكم من حكم القديم! الآن تموتون!",
[2065822804]="حسنًا.",
[2065849212]="غرفة الآثار تتعرض لهجوم!",
[2066391396]="هل تستطيع التعامل مع هذا؟",
[2066861262]="يا للأسف.",
[2067112935]="ما تقاتلون لأنفسكم بعد الآن يا ديدان! أنتم تقاتلون من أجل الملكة الآن، فأروني شيئًا يستحقها!",
[2067266442]="الـدومغارد مخلصون تمامًا لأسيادهم الـبيت لورد ويستمتعون بتدمير العوالم.",
[2067375215]="النور هو دليلي... هو غذائي!",
[2067493581]="ثريم يسحق!",
[2067579062]="إييع... هذه ليست سمكة!",
[2068291058]="أخذتها من أحد هؤلاء الترولز عندما كنت أسيرًا. ربما تجد طريقة لاستخدامها ضدهم.",
[2068452165]="شددوا عزيمتكم أيها الأبطال، فالإرهابان التوأمان، اسيدمو ودريدسكيل، يدخلان الحلبة!",
[2068575553]="لا وقت للنوم! انضموا للقتال!",
[2068714284]="وداعًا يا غولدشاير. سأعود قريبًا—ربما بعد أسبوع.",
[2068910639]="يحكي عن نهاية العالم القادمة. كيف ستحترق هذه الأرض وتولد من جديد من الموت.",
[2069158947]="هجماتك ضعيفة! اذهب تدرب على بعض الأرانب وارجع عندما تصبح أقوى.",
[2069229113]="زمن التنانين انتهى...",
[2069378728]="%s تنادي سيدها!",
[2069856440]="هم... جلالتك، هل ستتحول إلى تنين لأجلنا؟",
[2069955870]="%s يبدأ بإصدار أصوات شخير غريبة. تسقط دمعة الأقمار على الأرض وتتحطم.",
[2070149000]="...يوم استقلالنا!",
[2070217938]="عمل جيد! ابق عينيك مفتوحتين الآن.",
[2070450144]="أنا النور والظلام! ارتعدوا أيها البشر أمام رسول ديث وينغ!",
[2070544469]="لا أعلم، أيتها الملكة بانشي. أظن أن القطعة من آرثاس التي قد تبقى داخل الـليتش كينغ هي كل ما يمنع الـسكورج من إبادة أزيروث.",
[2070570106]="نعم، هذه هي البداية. لقد كنت في انتظارك أيها الأمير الصغير. أنا مالقانيس.",
[2070825219]="%s تطلق زمجرة عميقة بينما ينهار جسدها. يمكن سماع عواء مرعب يتردد في أروقة بلاكروك سباير. هناك شيء غاضب جدًا جدًا.",
[2071423733]="أوعية المويزيك جاهزة الآن، $N.",
[2071706749]="أوه، انظر! بيرة بلودمول! مممم...",
[2071896386]="متسللون آخرون؟ ستتعلمون قريبًا، لا أحد يعبث بشركة فينتشر!",
[2072077520]="اختنقوا بكراهيتكم!",
[2072118432]="مادريقوسا استحق مصيرًا أفضل بكثير. لقد فعلت ما يجب فعله، لكن هذه المعركة لم تنته بعد!",
[2072671573]="أيها الأطفال، تعالوا إلي!",
[2072765003]="صحيح... خطأي. أين كنت؟",
[2073363430]="تم التحقق من وفاة حراس المعبد. الرائحة الكبريتية تشير إلى أن الموت نتج عن كيان ناري.",
[2073411650]="هو يعمل ما يقال له!",
[2073703585]="حتى الآن، في أحلك ساعاتنا، يسخرون منا!",
[2074572459]="أنت حقًا شجاع لرغبتك في مواجهة الأهوال التي تكمن وراء هذا الباب.",
[2075021753]="الأليانس يتراجعون. تقدم إلى الـليتش كينغ!",
[2075163810]="قادمون! لا تدعهم يعبرون! فوكس فاير! الآن، الآن، الآن!",
[2075280366]="هل هذا أفضل ما يمكنك فعله؟ هل تتوقع حقًا أن تهزم شخصًا مذهلاً مثلي؟",
[2075539390]="حسنًا، ما الذي سيبحث عنه هذا ألجالون في تشخيصاته؟ ما هي فرصنا؟",
[2075554241]="أنت متعطش للدماء!",
[2075698395]="%s يبحث عن مكان للاختباء...",
[2076516111]="فريا! إنهم يأتون من أجلك.",
[2076699595]="براعتك، قوتك، ومكرك ستكون تحت المراقبة الدقيقة. هذه الألعاب ستحدد أفضل ما لدى أزيروث.",
[2076908579]="نحن أحرار! شكرًا لكم أيها الصغار الضعفاء.",
[2076999605]="نحن نقتل شخصًا آخر!",
[2077416353]="همم.",
[2077664902]="أتساءل إن كانت الخنازير جائعة...",
[2077699419]="%s يتنهد...",
[2077842727]="حسنًا... ربلا يوجد المرة القادمة.",
[2077862515]="ما كان ذلك؟ هل سمعتم شيئًا؟",
[2077869867]="كان من دواعي سروري، سيد أنفيلوارد. يجب أن أقول إن اهتمامك المتحمس بعملياتنا هو... غير متوقع.",
[2078265365]="ريجيك يشعر بالقوة! ريجيك يسحق جماجم ذوي الألسنة الكبيرة بين يديه!",
[2078355444]="باتشيز ينتقم من دوكتور سابنوك!",
[2078542131]="الشيء الوحيد الذي سيفعله ميتزن في وينتر فيل هذه المرة هو أن يُشوى على السفود!",
[2078977271]="آه، ها هو. اتبعني يا لحمي.",
[2079909254]="الدوارف يسعل، يتشنج، ويرتجف داخل القفص.",
[2080135570]="الهجمات على شاتراث استمرت، لكن المدينة لم تسقط، كما ترى. على العكس، نارو المعروف بـ زيري قاد غزوة ناجحة إلى شادومون فالي - على عتبة إيليدان.",
[2080400263]="%s يشير إلى أكوام الكتب.",
[2080555861]="%s يختفي في سحابة من الغبار.",
[2080827940]="ساعدني مون! فيهم كثير!",
[2080907607]="جنود! هجوم!",
[2080909666]="مقابر العظام! لا يهمني ما الجائزة المعروضة، لن أدخل مقابر العظام!",
[2081131334]="أفون يتجرأ ويعارضني؟! سأسحقه! عندما أفرغ من الـدرايناي، سيتمنون أنهم كانوا من الفاقدين!",
[2081218414]="في أحد الأيام سأخرج الكريستالاين دوم هامر وأصير أوركًا تمامًا على هذه المدينة. عندها سيندمون...",
[2082213990]="هذا التحدي لن يمر بلا عقاب. أنت وعالمك ستموتون!",
[2082233190]="دخلاء! اقتلوهم!",
[2083235912]="أين في نيذر هالـلاشرز الملعونين؟",
[2083246208]="رععععععععع! جينا لكم!",
[2083353596]="أبدًا... ما قدرت أوصل... للرف العلوي...",
[2083373635]="انتباه، الضابط $N على السطح!",
[2083520868]="ماذا ذاك، فوق عند الجوائز؟",
[2084141296]="والآن... الخطوة الأخيرة!",
[2084558593]="أعتقد كذا. ليس سخيف اللي قلته.",
[2084629830]="هل أخبرتكم أيها الجنود عن المرة التي دمرت فيها جسر ثاندول سبان؟ نعم، لم يكن الدارك آيرونز هم من دمروا الجسر! بل أنا من فعل ذلك!",
[2084934053]="استمر في تنظيم الصمام الرئيسي لضمان تدفق ثابت.",
[2085011223]="إنه لغز من الماضي بالفعل! لكنه مفتاح لمستقبلنا!",
[2085493506]="الأرض ح تبلعك!",
[2085623540]="ماذا لو استخدمنا ثلاث بؤر بنمط تايريان؟ هذا ح يحل المشكلة.",
[2085638673]="$N مصاب بطاعون الموت!",
[2086165805]="لامع!",
[2086290588]="%s يرفع تابوت سسليث بسهولة.",
[2086316634]="بنت طيبة، بيسي!",
[2086439920]="أظن أنه من الأفضل أن تغادر قبل أن تقرر قريزيلدا أنها في مزاج للحلوى.",
[2087004696]="مولود من جديد، سأصبح أداة للدمار...",
[2087243864]="كنت متأكدًا أنني سأموت هنا.",
[2087327124]="إذا جئت لتزعج السوفت ناكلز، فسوف يزعجك داجيك أيضًا. هذه عادة غوريجيك السيئة.",
[2087538364]="هل أنت متأكد أنك يجب أن تساعد هؤلاء البشر في سعيهم للحصول على السيف؟",
[2087682886]="لن أتفوق عليهم هواة!",
[2087688130]="لست ساذجًا لدرجة أن أصدق طلبك للرأفة، لكنني سأستمع.",
[2088082289]="النور يدين كل من يؤوي الشر. الآن ستموت!",
[2088472685]="أخيرًا، تحررت من قبضته الملعونة. أبي، أنا قادم...",
[2088652412]="أنت وحش ملعون، آرثاس!",
[2088851051]="صدقة للفقراء؟",
[2089002779]="كان من الحماقة أن تأتي.",
[2089060676]="تفضلوا! المنطاد إلى أورقريمار وصل! الكل على متن دوروتار!",
[2089477526]="راثغارد",
[2089523941]="لماذا...؟",
[2090222581]="%s يزحف بعصبية من الصندوق.",
[2090317485]="السم جاهز، $N.",
[2091248747]="لن تهرب منا بهذه السهولة!",
[2091259119]="كفى! إن كنت تنوي استعادة سحر أزيروث، فها هو ذا!",
[2091333999]="حاول ألا تخسر هذه، $N. من المهم أن نحافظ على المظاهر مع الأليانس على الأقل.",
[2092102577]="أوه لا، لا، لا... أنا رجل صواريخ.",
[2092218146]="لكن ما هذا؟",
[2092389268]="مممم، ذباب! أحلى حتى الآن وأنا أستطيع تذوقها.",
[2092820248]="الظلام وعد!",
[2092899557]="حدق في ظلمة روحك.",
[2093730446]="%s محبط ويهرب!",
[2093730858]="عندما ملأ الانفجار العظيم المنطقة، ألقى والدي رونًا على المطرقة العظيمة لئلا تقع بأيدي أعدائنا. كانت آخر أفعاله...",
[2093782716]="الملح يدخل في القدر...",
[2094431343]="اركع على ركبتيك وانحنِ... للناب والمخلب!",
[2094561654]="قلب الحارس النقي يجب تأمينه لإظهار التحدي والقوة. زيم'روك الغيور يحتفظ بمن يحمله.",
[2094701814]="هذا أكيد مثل الثآليل على ظهري!",
[2095079966]="ما تاخدش الشمعة!",
[2095550395]="أقسم، ما سرقت منك شيئًا! خذ بعض مؤني، فقط ارحل!",
[2096017504]="كل التقدير للطاهي!",
[2096317524]="توقف فورًا!",
[2096403021]="كنت تستحقها!",
[2096678339]="الآن ستنال ما تستحقه يا $N!",
[2096696460]="فروستوايرم رايمفانغ يحدق في $N ويستعد لهجوم جليدي!",
[2096721183]="المحقق الأعلى الخاص بكم ليس إلا كومة لحم، أيها الصليبيون! لا أحد خارج قبضة الـسكورج!",
[2097628740]="%s يحاول الهرب خوفًا!",
[2098452918]="لن تهرب منا، أيها الـدرويد!",
[2098571447]="بالتوفيق لك، $N. ولا تنسَ... احصل على تلك الوصفة قبل أن تجد غازين.",
[2098718924]="سكواك!! *سعال* *سعال* لازم أترك التدخين!",
[2098741678]="قل لنفسك مرة أخرى أن هؤلاء ليسوا أصدقاءك حقًا.",
[2098745797]="أنت تعرف أكثر من اللازم!",
[2098894751]="أيها الأبطال! سنصد الأنديد ما استطعنا، حتى آخر نفس فينا. تعاملوا مع سيد الـسكورج!",
[2099076215]="قاروش، كفى.",
[2099090626]="لا تغريني! هل تعرف حتى ماذا بداخل هذه الأشياء؟",
[2099218697]="أوه لحظة! من المفترض أن أبحث عن تلك الحفرية الغامضة!",
[2099718481]="لا!",
[2100127423]="كان أعظم شرف في حياتي أن أخدم معك، هامل.",
[2100383247]="باه! قوتي تسود هنا!",
[2100591642]="سجلني!",
[2100621407]="مباشرة من ثور مودان ومصنوع من معدن أصلي 100%... ها هو راستبلود، الغول الحديدي الذي يعمل بالبرق!",
[2100650024]="يمكنك الحصول على أي شيء ترغب فيه... مقابل ثمن.",
[2101053390]="ما بتتذكرني، مون؟ لعنة الـسكورج! خلّصوك من كل شيء كان يدعك سيد موجو. كل أونصة خير... كل شيء كان يدعك بطل ترول، مون!",
[2101073166]="بوس بنت المدفعي؟ لماذا أنا ما قابلت البنت قط...",
[2101158455]="لا! أنا... لن...",
[2101574645]="بدون ضغط في كلا العالمين، يبدأ %s في التجدد.",
[2101593926]="النجدة! النجدة!",
[2101639143]="فريسة سهلة كهذه...",
[2101865629]="%s تومئ برأسها موافقة على ما يقوله مستشارها.",
[2102556647]="موتك يقترب...",
[2102688485]="في انتظارك رحلة وعرة، $N. أتمنى أنك رتبت أمور جنازتك مسبقًا.",
[2102866239]="مرحبًا بك في مملكة الظلام!",
[2102916947]="مرحبًا سيداتي وسادتي، في عرض هذه الليلة!",
[2103129925]="ألم شديد في المعدة؟",
[2103142650]="تم تفعيل تسلسل التدمير الذاتي.",
[2103283378]="هذا رائع.",
[2103446491]="هذا هو! لقد نجح!",
[2103817139]="شاهد غضب الكون!",
[2104513647]="شفت شي دخل الحظيرة، أظن.",
[2104769500]="المقبرة على التلة تمتلئ أسرع ما نقدر نحفر القبور في بعض الأيام.",
[2105243218]="تم قياسك ووجدت ناقصًا.",
[2105345087]="شوريل'اران.",
[2105365877]="جنون، ليس كذا؟",
[2105616249]="انظر، باتش ورك. لما وصل خبر وجوده لآذان النقابة، ما صدق أحد حكايات الوحش الخارق بهذه السرعة والقوة. وقليلون صدقوا لما سقط أول مرة...",
[2106186287]="حلووو، مرحى هناك، يا جميل...",
[2106263150]="أنا أتذكر كل شيء...",
[2106274673]="أحس بفساد على هذا $N. ساعدني أدمره!",
[2106282141]="لك كلمتي بأني سأجد فائدة لجسمك بعد أن أقتلك، $R.",
[2106540090]="تعالوا، أيها الغرباء. روح التنين الصقر جائعة للأرواح المستحقة.",
[2106641848]="الموت للأليانس!",
[2107481938]="ربما تكون أفضل مجموعة مجندين رأيتها في حياتي! لنعد كل ذلك مرة أخرى!",
[2107525211]="الـنايتماير لا يمكن إيقافه!",
[2108177926]="%s يصدر صوتًا غريبًا.",
[2108428461]="%s يجمع قوته ويندفع للأمام!",
[2108769046]="للوصول إلى كروس رودز، $N، اتبع الطريق شرقًا ثم شمالًا.",
[2109366041]="ظننت أنني سأدعك تقتلني؟",
[2109675684]="الحوض يحتاج إلى مزيد من الماء!",
[2109783143]="أسمع وأطيع، يا سيدي...",
[2109865422]="انظر إلى الميدان، هايلورد. الـليتش كينغ أوقف تقدمك تمامًا وحصل على اليد العليا!",
[2109876432]="هذا ما نسميه اكتشافًا رائعًا!",
[2110340802]="هل... هل سيؤلم؟",
[2110986437]="لقد كانت العصور قاسية معي ومعك، يا حبيبي، لكن كن مطمئنًا، لقد حان الوقت، وأخيرًا نحن متحدان.",
[2111698161]="أنت بعيد عن وطنك، أيها الغريب.",
[2112044052]="أوقفهم! لا تتراجعوا!",
[2112167519]="غاكارا ما!",
[2112387524]="لا أستطيع تحمل الإبقاء عليك.",
[2112841815]="أنت تحمل دنس الـسكورج. استعد لدخول الـتويستينغ نيذر.",
[2112983523]="قلبك - قرعه المتواصل يقرفني. سأُسكته كما أسكتُ قلبي.",
[2113426178]="نيفاريان قُتل! يا شعب أورقريمار، انحنوا أمام قوة $N وحلفاء $Gخاصته:خاصتها;، فقد وجهوا ضربة لالبلاك دراغونفلايت ستوقظ الأسبكت من خمولهم! هذه الهزيمة سيشعر بها والد السرب الأسود: ديث وينغ يتلوى من الألم والحزن اليوم!",
[2113660825]="لم أكن لأحقق هذا النصر بدونك. سنتحدث لاحقًا في معقل ثاندرلورد.",
[2113722971]="كيف تجرؤ على العبث بألعابي، $N!",
[2113772151]="أجل، إلا إذا كان لي رأي آخر.",
[2113805475]="يجب أن أعترف... لم تكونوا غير متوقعين تمامًا. أتمنى أن تجدوا مثواكم الأخير... على ذوقكم.",
[2113886814]="بسرعة! سنكمينهم من الخلف!",
[2114522802]="مهرجان الجعة على الأبواب!",
[2114622009]="سيدي سيكون... نهايتكم جميعًا!",
[2114859892]="الفراغ... ينادي.",
[2114890261]="جوكوم، ابن أرنغريم، لطالما ندمت على أفعالي هنا. في حزني، جلبت أذى كبيرًا لأقرب الناس إليّ.",
[2115163225]="ماليقوس من الواضح أنه أصيب بالجنون.",
[2115203812]="أزاجا تشوغو زين!",
[2115518382]="جزر كل يوم لمدة سنة إذا توقفت!",
[2115841260]="$N، هذا هو! لقد اكتشفت الأمر أخيرًا!",
[2116074545]="أوه. أوه... فهمت. كم هذا لطيف!",
[2116313067]="عديم القيمة.",
[2116331903]="ليجيون، تماسكوا!",
[2116961742]="سأنهي هذا بسرعة....",
[2117463858]="حسنًا، لنبدأ. كلما طال بقاؤنا هنا، زاد الضرر الذي قد يسببه الأنديد في هيلزبراد.",
[2117558759]="احموا الحجاب!",
[2117761271]="أموت بسرور من أجل السيد...",
[2117973789]="هذا... لن ينتهي بخير لك!",
[2118133896]="سأجمّدك من الداخل حتى لا يبقى منك إلا قشرة جليدية.",
[2118574914]="النقابة ستنتصر!",
[2118965270]="ثورنلينق يستمر في النمو!",
[2118971281]="كل ما فعلته... كان من أجل أزيروث....",
[2119005792]="أنا في خدمتك، يا سيدي.",
[2119031142]="سأراك في آيس كراون، أيها الضعيف... إن عشت لهذا الوقت!",
[2119920520]="أسكت هذا الجوزة العفنة!",
[2120196251]="أنت لا تساوي الخردة التي صُنعت منها!",
[2120895378]="احتمالية الإصلاح الناجح بالوسائل العادية المتاحة في هذا العالم قريبة من الصفر. انتظر من فضلك بينما يتم تحليل الوسائل النظرية.",
[2121063498]="سيكون عليك قتلي أيها الوحش. لن أخبرك بشيء!",
[2121199712]="ابتعد عن طريق اللورد الوصي! أنا جاد!",
[2121293990]="أنا الموت! جهز بلدتك للإبادة!",
[2121356510]="تذكر، $N، هذه ليست سباقًا قصيرًا. الاختبار الحقيقي للهنتر يختبر قدرته على التحمل خلال رحلة طويلة.",
[2121510583]="الشامانية هي ما أوصلك إلى هنا... رائحتها تفوح في الهواء. *الـليتش كينغ يضحك* لقد كنت شامانًا يومًا ما.",
[2121536651]="الحلفاء الموجودون في ساحة المعركة من المحتمل أن يوفروا تكاملًا ويقللوا مدة القتال.",
[2121651504]="بريتا، اجعل من هذا $C الحقير وسادة دبابيس!",
[2121885253]="الإبادة ناجحة.",
[2122169172]="كسادة للدم، نحن سادة الحياة والموت أنفسهما. ضدنا، حتى الأمل يسقط منهكًا وبلا حياة.",
[2122368328]="غزو التروق! احموني وأنا أسد الفتحة!",
[2122953244]="أبناء الحديد، أقرضوني سيوفكم!",
[2123525072]="يحرق! إنه يحرق!",
[2123593915]="حسنًا، أي رؤية جميلة هذه؟",
[2124433741]="فلتبدأ العظة.",
[2124534495]="آه! يجب أن أستريح لحظة.",
[2124822453]="ينتهي به الأمر بتدمير القلعة كلها، وتحرير كل الأوركس الذين نحتجزهم في المخيمات، ويصعد إلى السلطة كملك الأوركس... وارتشيف أو شيء من هذا القبيل.",
[2124871127]="استعدوا لدخول النسيان، أيها المتطفلون. لقد أطلقتم العنان لإله!",
[2125137872]="هجوم الشمس المحطم محظوظ بوجود $N في صفنا.",
[2125423439]="لقد نجونا! لقد هرب الفلاحون من الـسكورج!",
[2125537908]="حرك مركبتك وإلا سنفجرها من السماء يا أورك! الـهورد ليس له عمل هنا.",
[2125695184]="دراكرورو يلقي نظره نحو دراكتارون كيب.",
[2125700494]="أخبرنا أكثر يا مارتيك. ما هو؟ كيف تشعر به؟",
[2126126324]="%s يشير إلى الرضيع.",
[2126521295]="طاقة مظلمة تجري فيّ... يا له من قوة! أنا متعطش للمزيد!",
[2127314502]="إندالا فينيل إندال!",
[2127937906]="أدنى فقدان للتركيز هو كل ما يتطلبه الأمر.",
[2128104004]="رينجي أصبح حراً!",
[2128371771]="دعنا ننهي ما بدأناه. سأقودك إلى مسكن إيليدان بعد أن تستعيد قوتك.",
[2128807670]="%s يبدو وكأنه يفضل أن يكون في أي مكان آخر غير هنا.",
[2129016109]="أجل... بالطبع.",
[2131428596]="$C، لقد أنقذتني! علي دين لن أستطيع سداده أبدًا. سأذهب لأرى إن كان بإمكاني مساعدة الآخرين.",
[2131496561]="استسلم لبرودة القبر.",
[2131718635]="ها! هذا هو الجزء الممتع!",
[2131807629]="...آرثاس.",
[2132119055]="فكر، $N. فكر رديًا، مون! نحن داركسبير، مون! إخوة وأخوات! تذكر عندما حاربنا زالازان وقطعنا رأسه وحررنا جزر إيكو؟ مون! فكر! كنت بطلًا لترولز داركسبير!",
[2132637871]="ابحث عن هدفك!",
[2133030549]="الكابتن لن يعجبه هذا.",
[2133070989]="ابتعد... اذهب...",
[2133477077]="من يريد رؤية خوذة ريجيك الجديدة؟",
[2133581574]="ثبّت المضخات.",
[2133811996]="ربما - ربلا يوجد يومٍ ما قد يتذكر ما كان عليه.",
[2133968201]="أرفع شرابي وأتمنى التخلص من أمثالك! في صحتك، أيها الوغد النذل، $N!",
[2134007455]="شليميل!",
[2134133768]="الوارتشيف وضع مكافأة على رأس أرازيوس! من الآن فصاعدًا، قطعة الرفض الشيطاني هذه هي العدو رقم واحد.",
[2134269433]="لا شيء أقل من الإبادة الكاملة سيكون كافيًا.",
[2134540500]="لقد فعلتها... لقد قتلت بارون ريفندار! الفجر الفضي سيسمع بأعمالك البطولية!",
[2134782228]="أشعر... بشيء غريب...",
[2134859879]="أي شيطان أنت، الذي تعذبني هكذا؟",
[2135011014]="%s يخلط الأعشاب مع ماء بئر القمر لصنع وردة اليقظة.",
[2135517064]="سباير فروستويرم تهبط قبل أورقريمز هامر مباشرة.",
[2135540282]="آه. كنت أمزح فقط...",
[2135748782]="أنت الأفضل الذي رأيته على الإطلاق. لا أصدق أنني أقول هذا ولكن قد تكون لديك فرصة ضد سكاي شاتر. ومهلاً، إذا لم يسر ذلك جيدًا، يمكنك أن تكون مساعدي...",
[2136213682]="وداعًا، $N. أبقنا على قيد الحياة واحصل على معدات أفضل!",
[2136997300]="%s يشحن تمبست مينون زيادة!",
[2137290637]="بالفعل. ما أفضل طريقة لترمز لرابطة الصداقة والأخوة بين تارين ميل وساوث شور من بناء هذا البرج في منتصف المسافة بين البلديّن. رائع!",
[2138347684]="لم أعد عبدًا بعد الآن!",
[2138726523]="التشخيص: سلبي!",
[2138805081]="أجل، حسنًا، يا زعيم. لا مشكلة.",
[2138994613]="عظامك ستكون وقودًا.",
[2139339752]="$N هزم بروكينتو!",
[2139377845]="أنا لست مجرد مهرج! أنا نيلاس آران!",
[2139386160]="كلنا سنموت!!!",
[2140068595]="هذا واحد كئيب جدًا... إذن ابن الملك، آرثاس... حسنًا، يخرج لمحاربة الشر، مع أوثر... *نات يمسح جبينه*",
[2140242467]="ثاين باناهوق الـديثبلو سقط على يد $N و$Gرفاقه:رفيقاتها; في القتال. $Gأمامه:أمامها; تحدٍ واحد فقط. من سيكون خصم $Gه:ها;؟",
[2140285477]="للأسف، هناك من يتجولون في الفناء متحدين النور.",
[2140532760]="نحن نقترب من فروست هولد. سأكون ممتنًا جدًا لو قدمتني إلى الملك ستورم هارت قبل أن تذهب. أعتقد أننا كلانا مدين له بالكثير.",
[2140561240]="ياررر! أيها البحار، ماذا فعلت؟! لقد جن! اربطوه في الحفر! ارفعوا الصاري! آررر! كل رجل لنفسه!",
[2141186070]="بوو هوو! أنا نوم صغير مسكين، وليس لدي عاصمة... أوه، انتظر.",
[2141532796]="ساعدوني! هذا $N لن يتركني!",
[2141562230]="أنا... أنا لا أستطيع فعلها. ارجع لسفينتك وسنحفظ حياتك.",
[2141605412]="نيلثاريون، همم؟ إجابة جيدة مثل أي إجابة، صحيح؟",
[2141879699]="لست متأكدًا أيهما أكثر جنونًا.",
[2141938292]="ياآآآآآآرررر! ها نحن يا صاح! نقطة سكالاواغ!",
[2142300065]="وهكذا تنتهي حرب النيكسس.",
[2142357114]="لكني أراه في عينيك، وأسمعه في نبضك. ستدمرني رغم عرضي بالخلود!",
[2142848521]="لااا! لم آتِ لهذا الحد... لأ...",
[2142961267]="أشعر بالمرض.",
[2143206882]="أين أنا؟ ما هذا المكان؟",
[2143336144]="يعتقد نفسه مهمًا جدًا. دائمًا يدفعني... سأريه. سأريهم جميعًا!",
[2143417169]="$Gسيد:سيدتي; $N، يا للمفاجأة السارة، $Gسيدي:سيدتي;.",
[2143457168]="أيها القذر من الـسكورج! بالنور تطهروا!",
[2143528780]="إنه في طريقه!",
[2144658697]="بفضلك، $N.",
[2144781601]="أرجوك، أيها الفاني، تحدث مع اركانست تايبالين في دالاران. قد يستطيع التفاوض مع الـسنريفيرز للوصول إلى الكتاب.",
[2145067498]="تريدني أوصل لمكان؟",
[2145114029]="وموضعًا بوحوش الـليتش كينغ، ماذا كان بإمكان داغان المسكين أن يفعل؟",
[2145228974]="المسيرة نحو أندرسِتي تبدأ الآن! تقوَّ بقوة ملكك! اتبعوني أيها الأبطال! لمجد الأليانس!",
[2145292295]="قد يساعدني لو أخبرتني كم واحدًا من هؤلاء سنقاتل. تستطيع تذكر هذا، صحيح يا جدي؟",
[2145337306]="أنا أقوى من أي وقت مضى!",
[2145718522]="آه، فارغة مجددًا!",
[2145880096]="لماذا لم يأتِ ستورمويند غاردز بعد؟",
[2146197316]="لقد كنت أنتظرك!",
[2146360382]="باسم النور!",
[2146458071]="%s يبتسم ويغمد بندقيته.",
[2146466903]="والآن لأختبر تصميمي!",
[2146496061]="لن يغادر أحد منكم هذا الوادي حيًا.",
[2146594710]="حسنًا، لقد تناولت طبق السمك أيها القائد. استمتع!",
[2146619791]="أنت لا تذكرني، أليس كذلك؟ الـسكورج الملعون... لقد حاولوا تجريدك من كل ما جعلك قوةً للحق. كل ذرة خير... كل ما جعلك تاورنًا!",
[2146735701]="أيها المتطفل $R القذر. مُت!",
[2146832100]="إلى أعماق النسيان معك!",
[2146853975]="%s يؤدي خدمة أخيرة لـراقناروس...",
[2146980354]="ستنفذ أوامري أيها الضعيف.",
[2147099566]="تعال هنا أيها الجميل. عندك ما أحتاجه!",
[2147447091]="هناك! هناك!",
[2147803831]="شكرًا لإنقاذ وجودي في هذا الجدول الزمني. الآن يجب أن أعود إلى رؤسائي. يجب أن يعرفوا فورًا ما مررت به.",
[2147860885]="%s يكز الخروف الصوفي مرارًا.",
[2147877808]="همم... إذا كنت تبحث عن إضعاف العقول يا $N، فسر الزومبي عند زانزيل قد يفي بالغرض!",
[2148090374]="أنا فقط متوتر. آسف.",
[2148408870]="احذر...",
[2148494815]="آرثاس! أنت متفوق عليك عددًا! ألقِ فروستمورن وسأمنحك موتًا عادلًا.",
[2148607381]="%s يستنشق خيوط الدخان الخفيفة المتصاعدة من الموقد.",
[2149227626]="تم تعديل نظام تقييم التهديد. مستوى التهديد الحالي للهدف: 0. جارٍ الحصول على هدف جديد.",
[2149320720]="أنت لا تذكرني، أليس كذلك؟ الـسكورج الملعون... لقد حاولوا تجريدك من كل ما جعلك قوة عادلة للانتقام. كل ذرة خير... كل ما جعلك بلود إلف!",
[2150493039]="أجل، رائع. هل يمكننا المغادرة الآن؟ هذه الصحراء تسبب لي حساسية.",
[2150524332]="روكيتيرز، أعد التحميل!",
[2151321112]="جاهز للقتال إلى جانب فولجين!",
[2151650307]="أتظن أننا سنرى السخامي العجوز اليوم؟",
[2152039999]="دعنا نحارب الحديديين معًا!",
[2152174876]="لا تستسلم! يجب أن ننتصر!",
[2152282948]="%s يدير عينيه.",
[2152684862]="كيلجايدن يبدأ بتوجيه طاقة مظلمة.",
[2152879531]="%s يصبح أكثر عدم استقرار!",
[2153012108]="%s يحيط نفسه بحاجز روني متصدع!",
[2153917222]="إذا كان هذا صحيحًا، فعندي الكثير من البحث لأقوم به.",
[2154155392]="كيف ظننت أنك ند للبطل الـدرايناي!",
[2154825176]="تتحدث عنها كصديقة؟ أنت أحمق. هذا \"ليدي المظلم\" ليس سيلفاناس.",
[2154952149]="بالطبع، تيريون. أعتذر عن اندفاعه. لن يتكرر هذا.",
[2155097366]="أراهن أنني تركته في الخيمة!",
[2155301512]="تريد قتالاً؟ ستحصل على قتال!",
[2155528744]="حط اللحم في البطن!",
[2155577861]="%s يستدير لمواجهتك.",
[2155692245]="أبعدهم عن التركيز!",
[2155852864]="لا أظن، لا أحتاج أن أنفجر مرة أخرى.",
[2155978827]="أعلم أن هذا لا يبدو الطريق الواضح لك، لكنه سيقربك من النور. قاتل جيدًا، يا أخي.",
[2156081590]="أنا أتألم... معاناة لا تطاق... أنهِ ألمي... أتوسل إليك!",
[2156106468]="ها ها، ناجا سهل الانسحاق!",
[2156200307]="في عملية ترجمة هذا، أعتقد أنني تعلمت عن مغامرات السكر لشخص يُدعى 'أندرو كليمنتين' أكثر مما تعلمت عن كاتب اليوميات.",
[2157063488]="لا مفر للأشرار!",
[2157722273]="تحركوا بخفة؛ السيد يعول علينا!",
[2157736310]="بشوفك راجع في وادي الأصداء. تحمل خيرًا، يا حليف.",
[2158192244]="%s يغلي بالغضب!",
[2158219153]="كدت أحصل عليها!",
[2158242880]="استخدام كافٍ للقوة سيؤدي إلى إعادة ضبط وظائف المراقب، وإزالة التأثير الخارجي.",
[2158255541]="إنه يؤلم كثيرًا... إيثاريوس، يا صديقي القديم... أرجوك ساعدني...",
[2158379517]="هل ترون أنفسكم؟ هذا أسوأ عذر لتأرجح السيوف رأيته في حياتي!",
[2158746510]="لن تحصل مني على شيء، أيها الوحش. أنا فوق قدرتك على التأثير.",
[2158816759]="آه، برج كرولمير. يُقال أن قوة ثوريم استُخدمت مرة واحدة فقط... وأنها حولت قارة بأكملها إلى غبار.",
[2159061851]="هي، ركنوت!",
[2159250047]="أبي!",
[2159510508]="لقد دُمّرت رونات الحماية! اطاردوا الكفار، يا إخوتي!",
[2159564013]="ماذا تريد، $Gسيدي:آنسة;؟",
[2159842385]="نادل، المزيد من النبيذ!",
[2159894852]="المزيد من العظام للقربان!",
[2160464782]="لا عودة لك!",
[2160540026]="لا، أيها الرقيب.",
[2160822164]="احترقوا أيها البشر! احترقوا لهذه المعصية!",
[2160955862]="التدخل في طقوس الإيقاظ يسبب موت الـفريكول.",
[2162177676]="%s يوقظ نفسه بالشخير.",
[2162333459]="سأجبرك على دفع الثمن!",
[2162768187]="قد تخدميني بعد.",
[2163385982]="الممثل الكوميدي يقلد تاورن.",
[2163390478]="الجنود ينشرون الذعر بشائعات الطعام الفاسد. الجيران يتهمون بعضهم بالتسمم. المدينة ستغرق في الفوضى!",
[2163569843]="ستسمح لي بسلاح ودرع، صحيح؟",
[2163760925]="النصر للأليانس!",
[2163891617]="المزيد من أتباع تيروك قادمون!",
[2164317207]="أشعلوا المحركات! لدينا موعد مع القدر، يا رفاق!",
[2164569691]="من الجيد رؤيتك رغم ذلك، يا أخي. أكثر ملا تستطيع الكلمات قوله.",
[2165372316]="$N ضابط و$Gسيد:سيدة;.",
[2165791796]="أيها القبطان، لماذا الحراس ليسوا في مواقعهم؟",
[2165878360]="%s يبدأ طقس الخلق...",
[2165918822]="كاقورو، أحتاج حضورك!",
[2166107403]="حسنًا يا فينغوس، أين أنت؟! تعال ونادني بمحب النول بينما أضربك بالمطرقة على رأسك!",
[2166543397]="فكر، $N. فكر بالورا. حاول تتذكر الجبال المغطاة بالثلوج في دن موروق! لقد ولدت هناك، $Gفتى:فتاة;. تذكر روعة الحياة، $N! لقد كنت بطل الدوارف يومًا! هذا ليس أنت!",
[2167454590]="بيليسا مينور!",
[2167684847]="طاقة حياة... لأستهلكها.",
[2167998679]="ممم! طعام!",
[2169244505]="$N، في يوم من الأيام أريد أن أشتري لك شرابًا.",
[2169480571]="لا أعرف إن كنت سأستطيع الوصول. أرجوك ساعدني...",
[2169528792]="%s يستعيد قوته ويكسر قيوده!",
[2170164420]="%s يتم التهامه!",
[2170210378]="اذهب إلى وسط المعبد واستخدم بوق العنصر فيوري!",
[2170488130]="مقيد بالعظام!",
[2170587084]="هيا... لننهي هذا!",
[2170926884]="أشعر بتحسن قليل الآن، شكرًا لك.",
[2171559725]="هناك. لقد انتهى الأمر.",
[2172280369]="سأتمسك بحب ابنتي وآمل أن أجد الغفران تحت النور لخطاياي.",
[2172359269]="هناك دائمًا... آشبرينغر.",
[2173031051]="%s يرمي رسالة انتون على الطاولة.",
[2173950905]="الأرواح تظهر ويحيط بالمذبح!",
[2174123505]="فلترحمك النور أيها الديث نايت.",
[2174697937]="وكذلك فرسان إيبون بليد. رغم أنه لا مكان لأمثالنا في عالمك، سنقاتل لإنهاء الـليتش كينغ. هذا عهدي!",
[2174922689]="التالي!",
[2175343800]="لوكين!!",
[2176312908]="%s مشوش...",
[2176313120]="أنت تواجه جاراكسوس، إيريدار لورد البيرنينغ ليجيون!",
[2176444192]="لقد استدعيتني أيها الأحمق! والآن مُت!",
[2176651457]="أين السيد؟",
[2176718900]="إندوريل أنومينور!",
[2176905492]="أحتاج أن أحضر له شيئًا صحيًا، فهو لم يتعافَ بعد من ذلك المرض الذي أصابه الأسبوع الماضي.",
[2177415777]="أبحث عن بعض الحراس الشخصيين الذين يرغبون في حماية قافلة غيزيلتون. نحن متوقفون على الطريق شرق كوخ كورميك، شمال قرية كولكار سنتور.",
[2177455873]="ألانا بيليندور!",
[2177611802]="وقت الانصراف لا يمكن أن يأتي قريبًا بما يكفي.",
[2177703868]="قتل رحيم!",
[2177882158]="ربما ستفكر مرتين قبل أن تسرق أحد خيول كيتريك في المرة القادمة، إيه؟",
[2178112480]="رأسك سيتدحرج!",
[2178559468]="يجب تحرير المزارع. ربما تخلى ستورمويند عن هؤلاء الناس، لكني سألعن نفسي إن فعلت.",
[2178596259]="سيكون هذا مصير كل أعداء الـهورد، أيها الـوارتشيف. الآن يجب أن نتعامل مع الحقير، بوترس.",
[2178837360]="ساوثشور كراير يمسك بمؤخرة رقبته وتتسع عيناه.",
[2179152508]="اهدأ يا فتى، إنها مجرد رصاصة طيور!",
[2179244135]="التهموا $N، يا جميلاتي!",
[2179383305]="إجابة مثيرة لسؤالي... لكنها خاطئة.",
[2179510301]="أختار الخيار الثالث: قتلك!",
[2179552538]="%s يستدعي بلاك هاند فيتران لمساعدته!",
[2179561404]="اشفني، بسرعة!",
[2179622490]="نحن محبوسون هنا... إلى الأبد. هذه إرادة غوريفايند.",
[2182006665]="%s يصدر أصواتًا طلبًا للمساعدة...",
[2182501217]="أعتقد أنني أرى شيئًا.",
[2182584083]="رأيت إناث النومز يضربون أقسى منك!",
[2182797197]="عِش، لعنك الله!",
[2183331291]="لا في حياتك!",
[2183446327]="احفر أسرع أيها الحقير! لا ترغمني على إظهار المعنى الحقيقي للألم لك!",
[2184587900]="لحسن الحظ، لم يصل قبضة الـليتش كينغ إلى دالاران بعد.",
[2185547221]="لا تضيع الوقت أيها الأحمق! استخدم قوتنا لقتل من يقف في طريقنا! دمر كارسيوس قبل أن تُقهَر!",
[2186402362]="يبدو أننا كشفنا هذا $N. ساعدني الآن في قتله!",
[2187443503]="من أجل الأليانس!",
[2187587121]="%s يضع اللفيفة على الطاولة، ويقرأ...",
[2187919327]="أفعال خادمك $R تتحدى مكانة $Gخاصته:خاصتها; يا ستورم لورد. جهود $Gخاصته:خاصتها; نجحت في تليين قلوب شعبي.",
[2187999521]="وللسيدات، خنزير صغير مشوي. استمتعوا!",
[2188273155]="حان وقت رحيلك.",
[2188286330]="أنا ملك الأوساخ، لا أحد أعلى مني! إلى عوني، أيها الأتباع - ساعدوا سيدكم!",
[2189239710]="%s يتحول إلى وضعية القتال!",
[2190552623]="ممم... أحب مشروب ساوث شور اللذيذ.",
[2190903399]="أعطيك فرصة واحدة. بايعني بالولاء، وربما لن أذبحك على وقاحتك.",
[2191063503]="الويل لمن يجرؤ على معارضة الـسكورج!",
[2191225733]="إذا اضطررنا إلى صراع، الـليتش كينغ سيدمر قواتنا المنقسمة في نورثريند.",
[2191659655]="تجرؤ على الوقوف ضدي؟",
[2192099669]="الآن شاهد، أيتها الفالكير. لاحظي بينما أضغط. هل ترين أنه لم ينضج بعد؟ شاهدي بينما ينفجر ويسقط ميتًا على الأرض.",
[2192432631]="ما قصة النساء؟ أعني، دائمًا ما يكونون مثل...",
[2193080972]="جروحي كبيرة جدًا. لن أنجو... مواطنونا محتجزون في أقفاص... طقوس...",
[2193205423]="هذه البطولة هي أكبر حدث منذ زمن! اشترِ شيئًا لتأخذه لعائلتك وتريه لأطفالك.",
[2193315723]="يجب أن نستمر مع مايف أو بدونها. إلى الداخل! بسرعة!",
[2193645237]="أونر غارد ابقَ في مكانك.",
[2194104079]="بوابة القمر الأصفر دُمّرت!",
[2194227701]="قلبك في المكان الصحيح، وأعلم أنك تسعى لخدمة النور. لكن هذه الضربات الصغيرة لا تؤثر كثيرًا على جيش الأنديد العظيم.",
[2194313293]="بلاك مور سينال... رأسك!",
[2194361015]="سيدي... لقد خذلتك...",
[2194513788]="سألتهم بقاياك!",
[2194780914]="نعم... سيناسب احتياجاتنا تمامًا. أرسله إلى قرية سولستايس عندما تكون مستعدًا. آرثاس لن يكون سعيدًا إذا تأخرنا عن الجدول.",
[2196305747]="لقد اتخذت قرارك.",
[2196688114]="هال...",
[2197208722]="أكاماً. نفاقك ليس مفاجئًا. كان يجب أن أذبحك أنت وإخوانك المشوهين منذ زمن.",
[2198132801]="انتبه لنفسك. هؤلاء الـدراكاري مجموعة خبيثة.",
[2201466456]="شكرًا لك، أيها الروح العظيم. شكرًا!",
[2201659055]="اربح أو اخسر، الملازم لا بد أنه مجنون ليحتفظ بأورك أليف كهذا. لا يمكن الوثوق بهم. إنهم حيوانات.",
[2202159072]="راقب الشياطين. نحن لسنا معنيين بقتل الـسكورج اليوم.",
[2202427681]="كنت سأخرج وأتخلص من بعض الـجنولز، لكن هذه الساق شهدت أيامًا أفضل وأخشى أنني سأموت.",
[2202493963]="لم أجرؤ على الوثوق بحواسي - لقد جعلني الـليتش كينغ أبدو أحمقًا مرات كثيرة.",
[2202601490]="بسبب وقاحتك تجاه الـليتش كينغ!",
[2203041903]="لقد حان وقت نهايتك.",
[2203045855]="%s يبدأ في استعادة قوته!",
[2203175492]="%s يخرج من التربة!",
[2203274829]="%s يراك تعبث بمخازن الفاكهة في المخيم ويهاجمك!",
[2203711636]="هذه ساعة أعظم انتصارنا!",
[2203731821]="حراس الميكانونوم المتبقين فسدوا بسبب مصدر مجهول.",
[2203902133]="أغمضوا أعينكم أيها السيدات والسادة! إنها مذبحة!",
[2203911323]="اهربوا! اهربوا!",
[2204357207]="شيطان الألف وجه.",
[2204615589]="...كهارب، ستستمتع بأنشطة مثل السباحة المقيدة وتنظيف الكلاب؟ كم هذا سخيف!",
[2204648745]="...بران؟",
[2205064067]="إخضاع هؤلاء الناس قد بدأ للتو... الكثير من الوقت للمسوف والألعاب.",
[2205094075]="لن تنجحوا إلا في إهلاك أنفسكم!",
[2205205594]="الكثير من الوقت الضائع... الذي لن تستعيدوه أبدًا!",
[2205416562]="لا شيء يضاهي صوت محرك بخاري مزدوج الكربوهيدرات وحلقة شوكة يحرق فايرستون نقيًا!",
[2205562576]="هدايا للجميع! الأب وينتر وضع الهدايا تحت الشجرة للكل.",
[2206283531]="لا أصدق أنك دمرت حزمتي... الآن واجه غضبي!",
[2206331015]="الأندرسِتي عادت للهورد مجددًا! لوك'تار!",
[2207267078]="هذا سيعلمك العبث مع صيدلي، يا كلاب الأليانس اللقطاء!",
[2207419065]="لم يستطع فعله محو الفظائع التي ارتكبناها.",
[2207578778]="شكرًا لك، تيرينثيس. سأبقى هنا طالما استطعت.",
[2207963172]="كنت لأعطي مدقتي مقابل بعض سدادات الأذن.",
[2207977554]="%s يستنشق الهواء، ملتقطًا رائحة شيء غير عادي.",
[2208568928]="جبان!",
[2208784829]="أصناف قوية تكفي للمساعدة في الرحلة عبر دسكوود، بضائع انتونيو بيريللي معروضة للبيع الآن هنا في ليكشاير.",
[2208849344]="حسنًا، لنكمل.",
[2209468784]="%s لا يبدو أنه حالفه الحظ في العثور على أحجار الغراب في الجوار.",
[2209646018]="ستاغهيلم سيتذلل ويتوسل من أجل حياته، تمامًا كما فعل ابنه الجبان! ألف عام من الظلم ستنتهي اليوم!",
