[2217955854]="والآن، يجب أن أعود لمياه البحيرة.",
[2218320232]="ضعيف!",
[2218641493]="حسنًا. لقد تم صنعه!",
[2218699969]="لن نسبب لك أي مشكلة. نحن نسعى فقط لمواصلة أبحاثنا بسلام.",
