[2220367266]="كل تلك السنوات من البحث... ولا شيء! ربما كانوا على حق، ربما هذا شيء يجب أن نتعلم العيش معه.",
[2220793366]="هنا لدينا ستورمويند كيب. مبني على أنقاض قلعة ستورمويند، التي دمرها الـهورد في الحرب العظمى الأولى.",
[2220814744]="كانت 54! قريبًا ستهنئني!",
