[2227999805]="مت!",
[2228161164]="سينتينلز، تعال للدفاع عني!",
[2228168091]="بعد الوحشية التي شهدها وشعر بها شعبي، تتوقع مني أن أتحمل عبئًا آخر أيها التنين؟ بالتأكيد أنت مجنون.",
