[2262929968]="كيراجي قوي يُعرف باسم جنرال راجاكس سيقود الاجتياح الأولي إلى سيليثوس. واحد فقط سيقف في طريقه: نايت إلف يُعرف باسم ستيغهيلم. يسمونه كارسيس أو 'يد الأرض' بلغة الكيراجي الأصلية.",
