[2264166052]="أين دعمنا؟ أريده هنا الآن!",
[2264635209]="سأثبت هنا وأشتري لكم أكبر قدر ممكن من الوقت. استغلوه جيدًا، واجعلوا أميرنا فخورًا.",
[2264839079]="هل أنت متأكد أنك مستعد؟ إذا لم يكن لدينا مجموعة من حلفائك لمساعدتنا، فسنفشل بالتأكيد.",
[2265868212]="هذه المعركة يجب أن تُرى لِتُصدق! كان مصارعنا التالي صياد توسكار مسالمًا، لكنه تحول إلى حياة المرتزق عديم الروح عندما قُتلت عائلته بأكملها على يد قطيع شرس من أسود البحر والبطاريق سيئة المزاج! الآن هو فقط من أجل الذهب! ليديز وسادتي، أورينوكو تاسك بريكر!!",
[2266414387]="هذه ستكون آخر مرة تنطق بها ذلك الاسم أيها البالادن! تنفس أنفاسك الأخيرة!",
[2266448622]="في الفراغ، لا أحد يستطيع سماع صراخك!",
[2266688387]="جئنا لإنهاء حكمك، إيليدان. شعبي وكل أوتلاند سيكونون أحرارًا!",
[2266761697]="إينغفار! فشلك الذريع سيكون عبرة للجميع... أنت ملعون! انهض ونفذ إرادة السيد!",
[2266996635]="لا ترحموهم، أبطال الـهورد! لوك تار أوغار!",
[2267093426]="سحر أفرّو تحطم! أنا حر مرة أخرى!",
[2267277489]="سبيريت، ارجع إلي!",
[2267420327]="أيتها الأرواح! أعرض جسدي عليك! تكلم من خلالي! هل حان الوقت لمهمة فولجين العظيمة؟",
[2267801487]="شكرًا لإيجاد مكوناتي. *يتثاءب* ذلك السم جعلني... متعبًا قليلًا...",
[2268964367]="انفجارات! المزيد من الانفجارات! لا بد أن أحصل على المزيد من الانفجارات!",
[2269353157]="المعركة على وشك البدء! مركبلوود توينز الذي لا يرحم ضد $N!",
[2270406395]="هؤلاء الثلاثة مرة أخرى؟",
[2270691220]="شكرًا لكم جميعًا. سأعود مرة أخرى بعد حوالي أسبوع.",
[2270930078]="تفتت وتعفن!",
[2271573598]="اضطررت للذهاب وطلب أبومينيشن... أبومينيشن!",
[2271808665]="تم إنهاء تسلسل التدمير الذاتي. رمز التجاوز أ-٩-٠-٥.",
[2272282524]="جارٍ تطبيق بروتوكولات أمنية جديدة...",
[2272309085]="$N، هذه البيرة... حسنًا، قد تكون الأفضل في مهرجان الجعة!",
[2272546564]="يبدو أنني استهنت بمهاراتك. أحسنت..",
[2272792035]="أشبال عنيدة! لن تصلوا إلى مدخل عرين سيدي! أيها الجنود، دمرّوهم!",
[2272821321]="ألم!",
[2273131716]="لا، كنت على صواب من البداية. ديثولم يجب أن تكون الأخيرة. يجب أن نؤمن كل الـقوست لاندز أولاً. لن ألتزم بقواتي هنا في معركة ضد دار'خان ومعنا أعداء على الأجنحة والخلف!",
[2273460433]="كثير من الفرينزي هارت الأقوياء هنا. داجيك درب معظمهم. أول مرة أدرس أحداً مثلك. أنت لست فرينزي هارت، تعرف.",
[2273611436]="أنقذت حياتي! شكراً!",
[2273652660]="أعتقد أنني سأتحول إلى الشرب بعد هذا.",
[2274368252]="تم اكتشاف تهديد محلي. الخروج من وضع توفير الطاقة.",
[2275623759]="إذا هربت الآن، قد تعيش.",
[2276385817]="العالم سيعاني من قسوات لا تُقاس تحت حكمي.",
[2276583888]="اذهب بسرعة... <سعال سعال> ابحث... <سعال> رايدول...",
[2276701853]="المزيد من صبيان الواردن المهمات!",
[2277228112]="بمساعدة هؤلاء البشر، تم تطهير هذه المنطقة من كل من يعارضنا.",
[2278020527]="أفضل الأسلحة في البارنز هنا!",
[2278686397]="كذاب!",
[2278834998]="لقد فعلوها! عدو سقط! عودوا إلى القاعدة!",
[2278940489]="درجة الحرارة 12 كراكلنهايت. كم هذا مثير.",
[2279362312]="الـقراند ويدو فايرلينا، عالم نبات في الحياة، مربي وراعي للعناكب في الموت، تشرف على جناح العناكب، وتطور أقوى السموم للـليتش كينغ.",
[2279825949]="أوه، ها أنت!",
[2279890897]="ها أنت يا داريون! كنت أتساءل متى ستزحف للخارج.",
[2280200725]="أيها الكروك الأحمق. لقد جلبت معك تعزيزاتي. انهض، ارجنت تشامبيونز، واخدم الـليتش كينغ في الموت!",
[2281124413]="سورفانغ هنا، ساقاي! سورفانغ! شقيق بروكسيغار نفسه، هنا لمساعدة جهودنا!",
[2281547069]="هيا، فلافي! أريد فقط أن أحممك!",
[2281642391]="أيها الدودة الحقيرة... أيام سيدك قد ولت!",
[2282022731]="النوع: ساياد",
[2282099807]="لا! أرجوك! هناك شيء آخر نسيت أن أذكره... ساعي قادم قريبًا... من هيرثغلين. إنه...",
[2282111768]="الكفار اقتحموا الملاذ! أيها الآفات الحقيرة... لم تتعلموا بعد المعنى الحقيقي للعذاب!",
[2282251606]="أحداث ذلك اليوم المظلم قد غُفرت من قبل شعبي. لن يتم التحدث عنها مرة أخرى.",
[2282430589]="حجر الأساس اكتمل! لقد فعلناها، $N!",
[2283530741]="وفقًا لحساباتي، إذا ضربنا الجرس معًا بما يكفي، سينكسر الختم على هذه الأبواب ويمكننا الدخول.",
[2283890850]="ماذا تريد مني أيها الشامان؟",
[2284317457]="أتمنى ألا تظن أني متلصص أو شيء من هذا القبيل، $N.$B$Bأعني، أعلم أنك مشهور جدًا في سكاي غارد الآن، و... أنا متأكد أنك لا تريد التسكع مع عامل وضيع مثلي.$B$Bلكن، إذا أردت يومًا أن نجتمع للتسكع، أو حتى لصيد بعض الأشعة، تفضل بالمرور في أي وقت! سأكون هنا.$B$Bأفتقدك...",
[2284393089]="أنت على حق، يوثير. سامحني. أنا... لا أعرف ما الذي تملكني. سنوصل هذه المعلومات إلى الملك والفرسان الذين يحاربون الـسكورج داخل آيس كراون سيتادل.",
[2284462150]="أود أن أرى الأليانس يحاولون سرقة لهبنا.",
[2284558775]="أنت لست وحدك! سيساعدك تنين الأزرق في هزيمة المخادع!",
[2284810878]="لم يكن ذلك مفيدًا جدًا. دعني أتفقد الآخر.",
[2285427345]="بضع دقائق أخرى وسأكون—",
[2285618614]="سأحولك إلى موجو!",
[2286358264]="أجل؟",
[2286577508]="%s يدافع عن نفسه بيأس.",
[2286918905]="سقطى باليا لن يرتاحوا، يا بني. ابحث عن برايستس الناغا!",
[2287239035]="بنارو، فليكن كذلك.",
[2288107646]="البروتو-درايك يشم الحرية ويطير نحو الوطن!",
[2288122598]="بالتاروس لا يترك ناجين!",
[2288183887]="بعد ذلك، سأتحدث عن جناح الوحوش الملوثة في ناكسماراس. هناك، يطور الـسكورج أقوى وأبشع المسوخ في جيوشهم.",
[2288745864]="من الأفضل لك ألا تعبث معي، أكاماً. إيليدان أعطاني أوامر محددة لأراقب الـواردن عن كثب. إذا اكتشفت أنك تخفي عني شيئًا، سأسحقك بيدي!",
[2289288789]="أنا... عندي جدة مريضة في البيت... أنا... أنا كل ما تملكه، $Gسيد:آنسة;.",
[2289330459]="حسنًا، يمكنك دائمًا العودة إلى المخيم ومساعدة ويسلكس في كل تروساته...",
[2289590348]="الـليتش كينغ عذبني بلا نهاية، داريون.",
[2289650901]="لا تقترب كثيرًا. لقد لمستها مرة... مرة واحدة فقط ولن أعيدها. ذكريات ذلك اليوم لا تزال حاضرة.",
[2289943292]="مهمة بسيطة لتحطيم حجر الروح هذا!",
[2290122625]="كيف الحال يا صديق؟ مرحبًا بك في أرض مهرجان الجعة! تفضل واشترِ بعض المشروبات!",
[2290136492]="روح أخرى لتقوية الجيش!",
[2290354372]="بيض سبايدر شوكي!",
[2290409886]="تنين الأحمر سيتحمل عبء إصلاح الدمار الذي حل بـ أزيروث. عد إلى قومك واسترح. الغد سيجلب لك تحديات جديدة، ويجب أن تكون مستعدًا لمواجهتها. الحياة... تستمر.",
[2290644788]="أنت لا تستحق ثوريم!",
[2290847156]="الآن بعد أن انتهى العرض، هل يمكن لأحد أن يرشدني إلى سكارليت موناستري؟",
[2291642029]="لا يوجد أبدًا ما يكفي من موجو للجميع...",
[2292116478]="مواطنو وحلفاء ستورمويند، في هذا اليوم، تم صنع التاريخ. $N دمر ما حاول اغتصاب حكم المملكة. تجمعوا وانضموا إلي لتكريم أبطالنا.",
[2292507723]="المحقق الأعلى قادم! كن مستعدًا، أيها الديث نايت! لا تدعه يخرجك من حدود حماية حقل مضاد السحر خاصتي! اقتله وخذ رأسه!",
[2292665482]="أليس هناك مكان آمن من هذه الوحوش؟",
[2292831681]="يجب تدمير كيلجايدن!",
[2293176388]="لا تتحرك إذا كنت تريد المشي مجددًا!",
[2294267096]="حسودون، هذا ما هم عليه. يخافون من تكريس أنفسهم للقوة الحقيقية.",
[2295195536]="أعرف رائحتك. أنت من تسلل بجانبي على ظهر ذلك النمر الثلجي الصغير!",
[2295811571]="لقد فهمت الأمر خطأ. أنا مُخضِع!",
[2296132276]="سآخذ تلك الجلود، أيها الصغير.",
[2296194272]="آه نعم، مون! هناك مجد عظيم ينتظرنا هنا!",
[2296316426]="حسنًا، لا أعرف. كنت هنا أعتني بالنار وأناقش عيوب التروس مع زوتفيزل. هذا أيضًا ملحمي بطريقته الخاصة.",
[2296351918]="ربما يجب أن أشرح...",
[2296367646]="هل جئت لزيارة العائلة؟ مت أيها الأحمق!",
[2296936716]="فكر، $N. فكر بالماضي. حاول أن تتذكر دوروتار، $Gأخي:أختي;! تذكر التضحيات التي قدمها أبطالنا لنكون أحرارًا من لعنة الدم. ارجع إلى وادي التجارب، حيث وُلدنا من جديد في عالم بلا تأثير شيطاني. وجدنا روعة الحياة، $N. معًا! هذا ليس أنت. لقد كنت بطلًا للهورد يومًا!",
[2297152009]="حسنًا... هذا كثير لاستيعابه. سأحتاج بعض الوقت لأفهم كل هذا. شكرًا لك.",
[2297157774]="%s يلفظ أنفاسه الأخيرة.",
[2297485268]="لماذا يسمح ثرال بحدوث هذا لمدينتنا؟",
[2297621290]="انتقام لـريجكلو!",
[2297895596]="سأدمر روحك!",
[2297964682]="بسرعة! استخدموا النيران واسندوا القوات البرية. سحره القديم يجب أن ينظف درع تيروك.",
[2297972172]="ساعدوني في سحق هؤلاء الضعفاء!",
[2298482967]="المزيد من الأرواح للـليتش كينغ! تعالوا أيها الصغار! تعالوا!",
[2298806485]="لدي أشياء رائعة لأريها لكم.",
[2298986629]="دخلاء مع السجين! اقتلوهم!!!",
[2299246881]="[فوربولق] ريتك كينتشيكس أزول أزور سامت...",
[2299440898]="ما كنا نقدر ننجح بدونك، $Gسيدي:سيدتي;.",
[2299640071]="المقبرة الغربية تم الاستيلاء عليها من قبل الأليانس!",
[2299678186]="%s يأكل غداءه.",
[2300657763]="حر مرة أخرى؟ عمل الحارس ميمير ينتظر.",
[2300718743]="كانت عندك فرصة؛ الآن فات الأوان!",
[2301270837]="البرج الجنوبي تضرر!",
[2302227639]="إلى الأمام! وكونوا على حذر هذه المرة! لن أتحمل المزيد من المعارك.",
[2302267560]="لم ينتهِ بعد...",
[2302348960]="بالتأكيد!",
[2303699802]="وقتك ينفد!",
[2304144532]="لنرى.",
[2304595601]="أشعر بغرابة فجأة. إيه؟!",
[2304664765]="جيوش الـسكورج، اسمعوا ندائي! بدأت نهاية القرمزية! مزقوا هذه الأرض واتركوا الموت فقط في أثركم!",
[2304717155]="دمك سيدهن دائرتي!",
[2304949061]="ماذا تريد مني؟",
[2305659496]="هؤلاء الأوركس حمقى! كل هذه القوة القريبة تنتظر من يأخذها، وكل ما يفعلونه هو الجلوس ومشاهدة الآخرين ينهبون الثروات!",
[2306415617]="الألدور هم أتباع النور، والتسامح والفداء قيم يفهمونها. لكنهم وجدوا صعوبة في نسيان أفعال الـبلود إلفز تحت قيادة كايل.",
[2306527272]="يجب أن تنقذه!",
[2307601666]="اقتل!!!",
[2307678149]="ما الذي تأمل تحقيقه؟ أن تقتحم منطقتي بوقاحة... أن تستخدم السحر... ضدي؟!",
[2307844660]="كان حادث. تم تلفيقي. لا تسقطني!",
[2308283982]="أنت تلعب، أنت تدفع.",
[2308383185]="%s ينتفخ صدره ويقف على أطراف أصابعه.",
[2308741931]="خذني معك، $Gسيدي:سيدتي;.",
[2308850820]="مكسورو قبيلة أشتونغ، زعيمكم يتكلم!",
[2308933119]="كنا نحقق تقدمًا بوبائنا في أندرسِتي. فجأة بدأت سلالاتنا تفشل!",
[2309148415]="كيكيكي!",
[2309347338]="يارل، لم تكن على طبيعتك منذ وصولي. ما الذي يحدث؟",
[2309444971]="نخب مر لـ راقناروس...",
[2309980839]="فوق الهضبة، هو وأصدقاؤه الشياطين يحاولون إعادة إشعال بئر الشمس وفتح صدع لإعادة رئيسهم، كيل'جادن، إلى العالم.",
[2310006643]="عساك تموت في صالح الـليتش كينغ!",
[2310196022]="أنت لا تعرف شيئًا عن القوة!",
[2310555629]="يقولون إنه سيكون هناك هجوم آخر... لن يبقى أحد على قيد الحياة...",
[2310863027]="أنا أحذف الرونات الخاصة بـ\"الشمال\" و\"الغرب\" لأنني لست متأكدًا من تأثيرها على العملاق. وأيضًا أضيف رونًا للحد من مدة تحكمك به.",
[2311446641]="لا! أيها الوحش!",
[2311504649]="أشجاري... ذبلت وماتت مثلي تمامًا.",
[2311624599]="آه...",
[2311745123]="لنرى كيف ستصمد أمام قوة فأسي!",
[2313115373]="سأطبخك، ثم سآكلك!",
[2313180695]="النصر! لأجاماغان!",
[2313554885]="%s يفحص المعلومات على ملصق المطلوب.",
[2313669781]="آوووووووووو!",
[2313843791]="كانت قيادتك هي التي تلاعبت بطفل حزين لمحاولة استعادة السيف. طفل كبر ليصبح رجلًا لا يحمل في قلبه سوى الانتقام والكراهية! ولأي سبب؟ أنت لست أقرب إلى السيف الآن مما كنت عليه قبل خمس سنوات.",
[2314000088]="أيها الحقير الحقير!",
[2314072427]="قالت أن أقابلها هنا بالضبط... ربما أنا في المكان الخطأ؟",
[2314388610]="فاريان، لا! توقف!",
[2314413836]="العمدة إيلو! كشافة المقبرة لدينا يعودون بتقارير مشؤومة...",
[2315139174]="والآن لنضع هذه التربة النادرة في أصيصي...",
[2315353720]="من الجيد أنك أتيت يا طفلي. حماية النور ضعفت عليك.",
[2315358570]="بدون سابق إنذار، يظهر برنس ساندوفال سحريًا داخل فالهالاس!",
[2315483050]="ألف ناب سيمزق لحمك!",
[2315587241]="عندما اقترب نارو منه، ركع فورينثال أمامه وقال الكلمات التالية: \"رأيتك في رؤيا، أيها نارو. أمل سباقي الوحيد للبقاء يكمن معك. أنا وأتباعي هنا لخدمتك.\"",
[2316618910]="خنزير توقف!",
[2316683902]="إذاً عدالة النور الممجدة وصلت أخيراً؟ هل أضع فروستمورن وأستسلم لرحمتك يا فوردرينغ؟",
[2316728543]="حان الوقت لأعرض بضاعتي مرة أخرى لكل من يسافر بالقرب من تلة سينتينل! تعالوا جميعاً!",
[2316869612]="سيخلق الإله القديم أفاتاراً من السيليثيد على صورته. هذه الأفاتار ستعرف باسم كيراجي. واعية وذات هدف، سيطلق الكيراجي على خالقهم اسماً: وُلد سيثون... لآلاف السنين عمل الكيراجي بحماس لبناء قوة قادرة على تدمير العالم الذي سيخون إلههم. مدينة القلعة العظيمة آهنقيراج بنيت لإيواء جيوشهم المتزائدة والاستعداد لمجيء سيثون.",
[2316975000]="تظن أنك تستطيع إيذائي؟ تظن أني خائف منك؟",
[2317020428]="%s يتصفح صفحات الكتاب.",
[2317177432]="كور دراكار مغمور بنار التوسكار!",
[2317259960]="%s يضحك بهدوء.",
[2317326762]="لم تعد تتعامل مع بعض المرؤوسين!",
[2318215178]="يجب حماية المعهد الموسيقي!",
[2319059776]="أنت ترد على ساورفانغ الآن!",
[2319423369]="كم بقي من المسافة؟",
[2319566694]="اهربوا، أيها الجبناء الملعونون!",
[2319574288]="استمتع بالرحلة! اتصل بي عندما تصل.",
[2320132405]="طعم... مجرد طعم صغير... من قوة التعويذة-ويفر!",
[2320638604]="أوصي بالتقطيع!",
[2320926787]="حسنًا، أيها الطاقم. ابدأوا العمل على تركيب هذه العظام.",
[2321152973]="ساراقوسا! ماذا حل بك؟",
[2321217966]="مصيرها مؤسف ولا مفر منه.",
[2321304540]="ألا تتفقدون بريدكم أبدًا؟",
[2321619936]="ما هذا بحق الجحيم؟ نوزدورمو هناك بالأعلى!",
[2321787154]="الآن ماذا لديك لتقوله؟",
[2322077671]="صحيح!",
[2322362011]="شكرًا لك، $Gفتى:فتاة;. شكرًا جزيلًا.",
[2322382719]="الوصي يتحدث بصدق، $N. تضحية ثالورين لم تمنع سقوط عين الشمس هذه.",
[2322616910]="المقبرة الجنوبية تم الاستيلاء عليها من قبل الأليانس!",
[2322750800]="انتهى العمل.",
[2322847172]="تأهبوا، فسنشن قريبًا هجومًا على من سموا أنفسهم \"الفورسيكن\".",
[2322876643]="%s يبدأ بالتلاعب بحجر ريلو فوق الأحفورتين.",
[2322911809]="قائد القوات هنا على الأرض هو وحش قاسٍ اسمه زاريثريان، لكني أخشى أن هناك قوى أعظم تعمل.",
[2323431536]="أوه، فقط مت!",
[2323489768]="قراري نهائي. لن أتراجع. كرست حياتي لخطتنا. تعريضها للخطر الآن يعني خيانة كل من ماتوا من أجل القبلي.",
[2323792624]="زاراث، أنا قادر تمامًا على صعود هذا الطريق إلى إكليبس بوينت. إذا لم نوصل الرسالة، سيقوم اللورد إيليدان بقطع رأسينا! أنت معفى!",
[2323926783]="هذا سيأخذ لحظة فقط، $N.",
[2324232947]="الإغلاق الطارئ للنارو سيعطل المانافورج بشكل دائم! يجب إيقافه!",
[2324460843]="سسسك-سارا ريث-نيالاك!",
[2324878891]="خذ صندوقًا من توابيت الاحتواء وترنيمة الظهور، $N. ستحتاجهم لمهمتك.",
[2325517465]="هذا الجهد التافه يملني. سأحرقكم جميعًا من الأعلى!",
[2325895211]="سأسحقك!",
[2325917298]="انهضوا أيها الجنود، قفوا وقاتلوا! أحضروا النصر أخيرًا لهذا الفارس الساقط!",
[2326283760]="انظروا إلى الفيريكول! عرق أتقن الحرب والدمار لدرجة جعلته فنًا. لقد انحازوا بالفعل إلى الـليتش كينغ! مساكنهم تحيط بكم وأعدادهم تفوق أعدادكم بخمس مرات.",
[2327068674]="أعتقد أن رجال الطيور الغريبة هؤلاء كانوا سيأكلوننا. مقرف!",
[2327486488]="من استدعى أمان؟",
[2327657607]="هراء! مت!",
[2328130063]="لم يفعلوا، يا جريتمذر. لقد قُتلوا بعد ولادتي بفترة قصيرة. لم أعرفهم أبدًا. تربيت كعبد. حتى هذا اليوم، أحمل اسم ثرال.",
[2328792567]="%s يبدأ في الصنع...",
[2329383460]="الـ... السيد؟ إنه حي؟",
[2329527979]="ستُحاكم على تدنيس هذه الأراضي المقدسة! قوانين القدماء لن تُتحدى! المتعدون سيفنون!",
[2329697348]="هو هناك، ومرحبًا بك في مهرجان الجعة!",
[2330158218]="زوغ زوغ! سعيد بالمساعدة!",
[2330542380]="أو هذا ما ستحصل عليه.",
[2330715976]="لقد اختبرت صبري، والآن ترى القوة الحقيقية للـبلو.",
[2331780469]="أسرع! أسرع! هذه الأسلحة يجب أن تُسلم إلى كوركرون فانغارد اليوم!",
[2332080565]="عندما حوّل الـبيرنينغ ليجيون الأوركس ضد الـدرايناي، دارت أعنف معركة هنا. قاتل الـدرايناي بشراسة، لكن في النهاية سقطت المدينة.",
[2332721252]="أوه، لا. لقد جئنا متأخرين. كل هؤلاء الناس قد أُصيبوا! قد يبدون بخير الآن، لكنها مجرد مسألة وقت قبل أن يتحولوا إلى أنديد!",
[2333807186]="آه، من الجيد أن أتحرر من قيودي! هل حررت توقثار بعد؟ لقد فرقنا الهيومانز بعد أسرنا.",
[2334058198]="عصابة من البلطجية واللصوص لن تجعلني أترك أرضي!",
[2334146080]="لقد كنت ملازمًا أولًا، مورغور. عملك في غريم باتول لا يُنسى بسهولة.",
[2334338278]="حسنًا الآن. بصرف النظر عن الإلهاء الواضح الذي ستوفره تابعة كهذه ضد أعدائك الأكثر ذكورة، فهي أيضًا قادرة على إلحاق قدر هائل من الضرر. لكن قدرتها على التحمل الهشة تجعلها عديمة الفائدة تقريبًا كدرع.",
[2334391308]="ثم إن النومز أسوأ! دائمًا يقولون أشياء مثل...",
[2334776588]="الثغرة التي أحدثتها تم إغلاقها بنسيج النيروبيان بنفس سرعة فتحها تقريبًا.",
[2335136475]="ساعدوني، أيها الحمقى، قبل فوات الأوان!",
[2335777805]="فساد يلوث غابتنا المقدسة.",
[2335888058]="%s يظهر!",
[2335920801]="ابق قريبًا، $N. سأحتاج كل المساعدة التي يمكنني الحصول عليها للهروب من هنا. هيا بنا!",
[2336039317]="تذكر، أحتاج مساعدتك لتوجيه الطاقة بشكل صحيح. سأطلب منك المساعدة عدة مرات في طريقنا، لذا كن مستعدًا.",
[2336117492]="الحفاظ على الخبيئة ضروري لاستعادة خاتم هودير.",
[2336307564]="أجل! أعني لا! أعني... أي إجابة ستخرجني من هنا؟",
[2336379498]="آه... الصوت الرائع للكودوز. أحب الطريقة التي تجعل الأرض تهتز... افحص الوحش من أجلي.",
[2337155485]="شكرًا لك على السماح لي بالزيارة، $N. لديك روح ملونة جدًا، لكنها أكثر إشراقًا مما أفضل... وإلا لكنت بقيت لفترة أطول!",
[2338053537]="السر يموت معك.",
[2338189410]="%s يقرأ النشرة.",
[2338488513]="%s يتحرر من قيوده الشبحية مع هدير رعد هائل!",
[2339593638]="عاني، أيها الحشرة الحقيرة!",
[2340202257]="$Gبابا:ماما;؟",
[2340324445]="كريستراز! أتمنى أن تسمح الظروف بترحيب أكثر ملاءمة. كان القدر لطيفًا بإعادتك إلينا.",
[2340347181]="مقاتل سقط!",
[2340917483]="أنا أتلاشى... عد إلى آرتور... عُد... إلى...",
[2342268431]="نشعر أنه من الأفضل وضعهم هنا، حيث قد يتقبلون مصيرهم المحتوم.",
[2342620774]="بالطبع، تفضل وخذ واحدة، هناك ما يكفي للجميع!",
[2343143905]="اهجموا الآن أيها الأبطال، بينما هو ضعيف! اهزموا المخادع!",
[2343635822]="بقوة الليتش كينغ!",
[2343928626]="لهب! موت! دمار! النار السوداء تشتعل في قلبي! يجب... أن أطلقها! هههه!",
[2344024735]="لقد فزت. حظ أفضل في مرة أخرى، يا صديق.",
[2344173539]="خوذة هودير!",
[2344398729]="مرحبًا، أيها العظيم. أنا خادمك المتواضع.",
[2344594270]="في حال كنت تتساءل، لدغة الدبور ليست لطيفة. لا داعي لتجربتها.",
[2346142228]="انتبهوا!",
[2346164437]="لا تستطيع الهرب من محارب الـهورد! خذ هذه! وهذه!",
[2346194378]="مخلوقات صغيرة متغطرسة، تتحدون قوى لا تفهمونها بعد.",
[2346381082]="مضيعة هائلة للوقت.",
[2347189671]="ماذا يحدث؟!",
[2347269555]="ها هو قادم الصغير لكن القاتل امبروز بولتسبارك، البطل الأعظم لـ نوميريغان!",
[2347403556]="الرجاء التحلي بالصبر، سننادي باسمك عندما يحين دورك. نحن نساعد الأشخاص حسب ترتيب ظهورهم على الشاشة.",
[2347468653]="لن توقف ظلنا المتعمق، $C. الآن... انضم إلينا! انضم إلى صفوف المختارين!",
[2347679036]="بعد ذلك بفترة قصيرة، بدأت تأتينا رؤى عن مخلوق... مخلوق بريش بومة، لكن بإرادة وقوة دب...",
[2347965843]="نجاح! تهاني! مصدر الطاقة أعاد القلادة!",
[2349165043]="ماذا؟ سترسلني إلى هناك مرة أخرى؟!",
[2349359603]="لا تتوقف! أعدك بألف موت إذا فكرت حتى في إلقاء هذا المعول!",
[2349676493]="إنه مجنون الآن. أصيب بالجنون أثناء التصدع. لا راحة للعناصر.",
[2350048738]="تم القضاء على هجوم الـسكورج على بلاطي. يمكنكم متابعة أعمالكم.",
[2351023076]="باه! سحرك ضعيف!",
[2351276256]="اقترب أيها الصغير. لا داعي للخوف مني أو من $N.",
[2351690680]="مستحيل! أوقفوا هجومكم أيها البشر... أنا أستسلم! أستسلم!",
[2352090948]="اللعنة على... الحظ.",
[2352093555]="قد تظنون أنكم ربحتم أيها الديدان، لكن ضد قوة الـليتش كينغ لا نصر للأحياء! لم ترون آخر ما لدي!",
[2352293654]="إذن ربما لا يزال هناك أمل...",
[2352838108]="موتي لا يعني... شيئًا.",
[2353019029]="انهضي، أيها التابع. انهضي وحلقي من أجل الـسكورج!",
[2353162591]="%s يزرع بذور الفاكهة.",
[2353463454]="أضعف من أن تنهي معاركك بنفسك؟ حسنًا إذن...",
[2353991406]="همم، زهور التنين الأزرق؟ من أين يأتون بهذه الأسماء؟ ديدال قد جن!",
[2354107849]="%s يسعل.",
[2354115464]="اسمع، يا صغير. أستطيع التعامل مع هذا الشيء. فقط راقب ظهري!",
[2354196982]="تحرك إلى الدرج ودافع!",
[2355051840]="ربما استسلم وارمي الكتاب على الحيوانات، لكن حاول.",
[2355235811]="ماذا في الصندوق؟",
[2355308781]="فيك نيلاش وفيك لور، المعروفان باسم الإمبراطورين التوأم لـآهنقيراج، شاهدا الحرب من ملاذ معبدهما. الأخوان الذكيان خططا لإضعاف معنويات قوات ستاغهيلم وتفريقها.",
[2355361908]="أصداف طرية وضعيفة. حيوات قصيرة وهشة. لا يمكنكم الهرب من لعنة اللحم!",
[2355470587]="ستتعلم ذلك بنفسك. عندما يكتمل عملي، ستتوسل طلبًا للرحمة -- وسأحرمك منها. صرخات عذابك ستكون شاهدًا على قوتي المطلقة...",
[2355864702]="تروغ قذر إن رأيت واحدًا من قبل. مت!",
[2355880698]="الرينجر-جنرال لسيلفرمون ستكون حليفة وفية!",
[2355919378]="وأيها الأبطال... لدي ما تبحثون عنه. عسى أن يرى الشر يذوب مرة أخرى. ريمولوس، تأكد أن بطلنا يستلم شظية الغرين فلايت.",
[2355960110]="أوووووغغغغغ....",
[2356140121]="آخر دفعة يا شباب! أروهم ما لديكم!",
[2356316831]="ماذا ...هِك؟!",
[2356425283]="إذن من حسن الحظ أنني استعدت شرارة نارو النبيلة من حيث سقطت! حيث يسكن الإيمان، لا يضيع الأمل أبدًا، يا بلود إلف الشاب.",
[2356796001]="يقول ماجينور إن لف التدفقات المتناوبة من الطاقة الإيجابية يصنع تدفقًا أكثر استقرارًا بكثير.",
[2356810635]="عطل في النظام بعد خمسة، أ-ر-ب-ع...",
[2356822478]="كم من البائس تعتقد أن $N أخرجهم من بؤسهم؟",
[2357330720]="تازاغا-تشو!",
[2357342711]="هذا خطؤك!",
[2357431477]="كانت أومي، أليس كذلك؟! دائمًا تمزح معي، والآن جعلتك تشاركها أيضًا!",
[2357675840]="أي نعم، طالما أننا سنذهب إلى الحلبة بعدها مباشرة!",
[2358127776]="جهلك عميق. ألا ترى إلى أين يؤدي هذا الطريق؟",
[2358219460]="إنهم يأتون من أجلك، أيها الأحمق!",
[2358772141]="ليتني أستطيع تشغيل هذه الآلة اللعينة!",
[2359053974]="سيعيش طالما أثبت فائدته. سأكون حذرًا لو كنت مكانك، أيها الدوارف.",
[2359138136]="أطفال ستراثولم قاتلوا بشراسة أكبر!",
[2359318242]="الزلزال العنيف نبه مورلوكس القريبين!",
[2359417328]="ممم، موجو أكثر.",
[2360102687]="%s يبصق على $N.",
[2360152301]="لا أعتقد أنها تستطيع التفوق على المرة التي قال فيها إنه سمع أن هيكلًا عظميًا \"لقريب\" آرثاس متجمد تحت نهر جليدي في وينتر سبرينغ. لن أسامحك أبدًا على هذه، ليتول. أعني بصراحة... قريب آرثاس؟",
[2360674309]="هي، $Gرجل:سيدتي;؟ عندك قليل من مال؟ عندي خمسة عيال لأطعمهم!",
[2360682213]="إنها تشتغل، دوراين! انظر! إنها تشتغل فعلاً...",
[2360795307]="وهكذا وقف الفرسان أمام الـهورد الزاحف وصمدوا بينما جاء ألف أورك متهور عبر الوادي.",
[2361857914]="فكر، $N. فكر بالماضي. حاول تتذكر تلال ووديان إلوين، حيث ولدت. تذكر روعة الحياة، $Gأخي:أختي;. كنت بطل الأليانس يومًا! هذا ليس أنت.",
[2362016893]="تنادي على الوحش، سوف تاخذ أكثر مما تتفاوض عليه!",
[2362705636]="بسرعة! تحرك مراوغ! تحرك مراوغ--",
[2363281965]="ليكن تدمير هذا المكان درسًا لكل من يجرؤ على معارضة الـسكورج!",
[2363296326]="تعال لمساعدتي! أطع سيدك الآن!",
[2363483007]="لا يمكن أن يبقى سوى ناجٍ واحد!",
[2363876787]="قف وكن مقاسًا! انهض، فسيدك ينتظر وصولك. اذهب الآن!",
[2364235965]="موربيدوس، أرهم ما يحدث لمن يتحدى إرادة ملكهم!",
[2364379095]="من... هناك...؟",
[2364888551]="تم الاستلام، أراكسيس. الدعم في الطريق. تمسك بموقعك. أكرر، تمسك بموقعك.",
[2365235068]="انطلق بأقصى سرعة.",
[2365378729]="لماذا؟ لماذا حدث هذا لي... لي؟ أين كنتِ تيراندي؟ أين كنتِ عندما سقطت من نعمة إلون؟",
[2365574959]="لا مكان للهرب... أنت ملكي الآن!",
[2366314608]="أنت -- أنت لست واحدًا منهم! لنختفي قبل أن يجدونا! أسرع!",
[2366750825]="موافق. الطابع الزمني لتدمير التصميم الأساسي لوكين يتزامن مع تفعيل الإشارة.",
[2366813040]="أقرب الآن. لقيمات لذيذة. لقد مضى وقت طويل بدون طعام، بدون دم لأشربه.",
[2367247490]="كلما أسرعتم في تقبل حالتكم كعيب، كلما أسرعتم في إيجاد أنفسكم في موقف يسمح لكم بتجاوزها.",
[2367336743]="عالم النبات الأعلى؟",
[2367499838]="أرني ما أنت مصنوع منه، $N!",
[2367502469]="صُنع فالانير بواسطة التايتنز أنفسهم، وأُعطي لأول ملك من التراب، يوريل ستونهارت. بالمطرقة كان عليه أن يخلق ويمنح الحياة لبقية إخوته.",
[2367629713]="لا!",
[2368267867]="المجد لـ$N، قاتل هاكار، وبطل أزيروث!",
[2368298774]="هذه المنطقة ستدمر نفسها بعد تسع دقائق.",
[2368332301]="مساعدة! أحدهم يساعدنا!",
[2368694984]="فقط بالعمل معًا ستتغلبون على التحدي الأخير. من أعماق آيس كراون يأتي اثنان من أقوى نواب الـسكورج: فال'كير المخيفة، رسل الـليتش كينغ المجنحة!",
[2369348820]="شيء يتحرك في بركة الموجو...",
[2369478655]="ستتكلم في النهاية. قد تفعلها الآن.",
[2369786443]="كان يجب أن أكون في يوتغارد كيب، أقاتل إلى جانب إنغفار! بدلاً من ذلك، أنا مكلف بحماية يرقات صغيرة مثلك.",
[2369888418]="لديك بعض القتال فيك. أنا معجب.",
[2370036299]="%s يغمى عليه ويسقط على الأرض.",
[2370074482]="ممتاز. طالما لا تشق طريقك بالقطع والذبح، فلن يعرفوا الفرق أبدًا.",
[2370828299]="وارلوكس، لا يجب أن تلعبوا بسحر لا تفهمونه. انظروا ماذا يحدث؟",
[2370845659]="استسلموا للحلم اللامتناهي، أيها الصغار. دعه يلتهمكم!",
[2371300207]="حسنًا، عدت إلى عملي. لكن كانت استراحة قصيرة لطيفة، ومن الجميل دائمًا شرب ثاندر إيل!",
[2371426630]="لن تحصل على بلورة أتا'مال مني أبدًا!",
[2371821098]="تشوغا-تشوغا، وو-وو! هالوين سعيد، $N!",
[2372108324]="أخيرًا تحررت. لقد مضى وقت طويل منذ أن تذوقت الحرية الحقيقية!",
[2372376308]="%s يلتهم جسد سيده.",
[2372386335]="كابرنيان ستتأكد من أن إقامتك هنا قصيرة.",
[2373095297]="أحتاج للتبول.",
[2373172419]="الحرية أخيرًا! يجب أن أعود إلى وارسونغ هولد فورًا!",
[2373494356]="أدال كان كريمًا جدًا في إيحاءاته لي، أنا الخادم المتواضع للنور.",
[2373633312]="شكرًا لك، يا ابن دوروتان.",
[2374079100]="وجدت شيئًا... أعتقد.",
[2374157094]="برافو! برافو! عرض رائع... هل يمكنني إقناعك بالعمل لدي؟ لا، أعتقد أن الذبح غير الضروري لموظفيّ قد يؤثر سلبًا على طلب توظيفك.",
[2374288324]="أخيرًا حان الوقت! انعوا واندبوا زوال كل ما عرفتموه، وكل ما كان يمكن أن يكون! هاش مين كوراي!",
[2374328285]="طعمك لذيذ مع القليل من الملح والفلفل.",
[2376406785]="شعرت بجزء منه لا يزال حيًا! محاصر... يكافح... أوه، آرثاس!",
[2376598854]="هذا استيقظ مبكرًا جدًا. لا يزال يحتفظ بالمشاعر والذاكرة...",
[2376764484]="لا تدعهم يؤذونا يا تيتو! أوه، لن تفعل، أليس كذلك؟",
[2376964911]="لقد احتفظت بهذا الشيء لمدة 10 سنوات. منذ بلاكروك سباير...",
[2377297753]="%s يزداد جنونًا!",
[2377385662]="كنت أظن أني لن أخرج من هنا حيًا.",
[2377478941]="الوظيفة: تينكرز، ميكانيكيون",
[2377840533]="هذا غريب. أحدهم أخذ حشراتنا. عندك؟",
[2378054917]="نحن نتلقى أضرارًا في الهيكل، أحضروا ساحرًا هنا ليوقف تلك المدافع!",
[2378059169]="ذكرياتي عن ثالوريان بردت وكذلك نصله.",
[2378074924]="ستفعل إذا أردت أن تبقى رأسك ملتصقًا بكتفيك.",
[2378102632]="تضحية ضرورية.",
[2378146608]="$N، لقد تغير شكلي الآن! القوة الحقيقية لروحي تعود إليّ الآن... قبضة الغابة الملعونة تغادرني.",
[2378448472]="الرماة، تشكلوا في صفوف! بإشارتي!",
[2378498439]="من يجرؤ على التدخل مع أبناء أروقال؟",
[2378597935]="اسجدوا أمام السانلاين!",
[2378931921]="اقفز ثلاث مرات وارقص لعشر دقائق وسيصير أكيد!",
[2379816693]="تطلب مني كثيرًا يا تيريون، أجلس وأتفرج وأنا واثق إن الهمج سوف يضبطون حالهم.",
[2380239768]="الـسكورج في كل مكان مون!",
[2380293839]="لماذا تهرب؟ سنحول جثتك إلى واحد من الـسكورج.",
[2381152160]="%s يقع على الأرض.",
[2381315833]="موت المحقق العالي لنيو أفالون لن يمر مرور الكرام. يجب أن تخرج من هنا حالًا! اذهب، قبل أن يظهر المزيد منهم. سأكون بخير وحدي.",
[2381531792]="كلوا يا أولادي! كلوا من لحم الأحياء!",
[2382813271]="تحليل تحسين إلدر برايتليف.... دفاعات منطقة ثابتة مدعومة بتضخيم شمسي.",
[2384261793]="شاهد القوة... الشيطان اللي جواي!",
[2384517396]="كيلثوزاد يضرب!",
[2384553191]="رينجي يرى الطريق الآن، $N. رينجي يعرف الطريق إلى البيت.",
[2384739582]="هذه المملكة ملك للسكورج. فقط الأموات قد يدخلون!",
[2384769434]="ماذا؟ هذا لا يمكن أن يكون!",
[2385151077]="البرق يجري في داخلي!",
[2385504389]="واجه غضب بريستليمب!",
[2385693701]="الشحنات المتفجرة ستنفجر بعد 5 ثوانٍ...",
[2385852415]="لقد ضقت ذرعًا بهذه الألعاب، آرثاس! جدرانك لا تستطيع إيقافي!",
[2386236816]="داركشاير...أنا جائع!!",
[2386569414]="تعال، زيلك، لا تطردهم. ليس قبل أن نمرح!",
[2387169571]="نهاية الأيام قد حلت! لتحتضن الأرض جسدي وعظامي.",
[2387208967]="ضحكة %s تتلاشى...",
[2387279649]="$N؟ سمعت أنك ميت.",
[2387681218]="انظر!",
[2387701792]="وهكذا، تقترب النهاية",
[2387782536]="البرج الشرقي فروست وولف يتعرض لهجوم! إذا تُرك دون رد، سيدمره الـهورد!",
[2387862157]="مأساوي... لقد قاتلوا بشجاعة، لكن وحوش نورثريند انتصرت. دعونا نقف دقيقة صمت لأبطالنا الساقطين.",
[2388525649]="ماذا... ماذا حدث لي؟",
[2388761307]="كنت آمل أن أنهي حياتكم بسرعة، لكنكم أثبتم أنكم أكثر... مرونة مما توقعت. مع ذلك، جهودكم تذهب سدى. أنتم أيها البشر المتهورون المهملون من تتحملون مسؤولية هذه الحرب. أنا أفعل ما يجب فعله، وإذا كان يعني انقراضكم... فليكن!!",
[2389040522]="هذا الحصار المثير للشفقة ينتهي الآن!",
[2389059662]="سيدي، لقد فشلت...",
[2389962856]="ربما هذا ليس-- لا، سنقاتل! تعالوا لمساعدتي!",
[2390019886]="انتبهوا... ها هم قادمون. سأساعد بقدر ما أستطيع. دعونا فقط نبعدهم عن الساعة الرملية!",
[2390033105]="كايل'ثاس والـليجيون... هذا ما كنا نفتقده!",
[2390153470]="إيفرسونق ودز، دالفورس. أنا أفكر كم كانت جميلة قبل أن يشق آرثاس طريق الموت عبرها...",
[2390834994]="ستختبر عذابي بنفسك!",
[2390906381]="سماد.",
[2391159130]="ما معنى هذا؟! توقف! سأضاعف ما يدفعونه لك!",
[2391639488]="بدون مساعدتك، كنت سأكون محكومًا بحياة الموت بين إبداعات الـليتش كينغ المرعبة.",
[2391764782]="موتك سيأتي قريبًا...",
[2392204563]="هل ستساعدني في العثور على كلبي؟",
[2392509866]="لقد أتيت متأخراً جداً!! أنا... يجب... أن أطيع!!",
[2393264318]="أحب نساء بلود إلف. خاصةً عندما يقلن أشياء كهذه...",
[2393383906]="سأحول مخلوقي المألوف، ساقان، إلى شيء رائع حقاً!",
[2395227225]="ما هذا؟ شيء يقترب من بعيد.",
[2395683154]="درجة الحرارة 122 درجة كراكلنهايت.",
[2395800571]="اخرجوا، يا خدمي! دافعوا عن سيدكم!",
[2396161924]="حكمود لا يستطيع العمل تحت هذه الظروف! وداعاً!",
[2397030146]="الكهنوت، المعروف باسم ألدور، استعاد قوته بسرعة مع انتشار خبر عودة نارو وسرعان ما بدأت إعادة البناء. المعبد المدمر يُستخدم الآن كمستوصف للاجئين الجرحى.",
[2397388393]="الأليانس يمتلك الممر الملاحي الآمن الوحيد في هذه المنطقة، وحتى هذا معرض لخطر الضياع بسبب تلك الضباب المخيفة.",
[2398363075]="أخيرًا حررت من تلك اللعنة الرهيبة! شكرًا لك! أرجو إبلاغ ريلاك الـ ريديمد أنني بخير. مهمتي تقع في سكيتيس. يجب هزيمة تيروك!",
[2398861888]="سيتم إيقاف المتطفلين، يا سيدي.",
[2399330192]="لا أريد العودة!",
[2399497414]="ماذا؟! لا يمكنك هزيمتي! سأعود!",
[2399923869]="آمل فقط أن يرى النور ويوجه طاقاته لاستعادة كويل'ثالاس الجميلة.",
[2400232397]="أنت تحطم قلبي - لدي حصص يجب تحقيقها، أتعلم؟ هل تستطيع حمل سيف؟ اذهب إلى الثكنات.",
[2400242231]="ها نحن ذا، $N! هذه الدهون ستفعل الحيلة بالتأكيد! والآن لبعض التنظيف الحقيقي!",
[2400910303]="هذا هو الكتاب الغامض الذي كنت أبحث عنه.",
[2401112234]="أعمل هؤلاء البائسين حتى العظم، يا إلليداري! إذا كان هناك أي شيء ذي قيمة في هذا المكان المهجور فسنجده!",
[2401306574]="عدالة كهربائية!",
[2401597429]="فريا يلقي |cFF00FF00سترينثند آيرون روتس!|r",
[2401740548]="أسمع قلوبًا صغيرة تنبض. نعم... تنبض أسرع الآن... قريبًا سيتوقف النبض.",
[2401992713]="شكرًا لكم جميعًا على حضوركم الليلة. الآن صفقوا بأيديكم لترحيب بأفضل شاتراث، بيري قاتنر!",
[2402033742]="نعلم أن الجوع لا يُروى أبدًا...",
[2402327259]="أوامري هي أن تنتظر هنا.",
[2402564079]="يا لها من طلقة دماغ!",
[2402956764]="الشحنات موضوعة. تراجعوا قبل أن تنفجر!",
[2403223436]="خذ $Gإياه:إياها; بعيدًا وجهز $Gإياه:إياها; لإعادة الإحياء.",
[2403351304]="هذه البلورات ستنجح. احصل عليها!",
[2403392458]="%s يجثو على ركبتيه، يملأ القارورة بماء من بئر القمر.",
[2403864448]="لأي شيء القنبلة؟",
[2403890884]="لن يطول الأمر، $N. فقط أبقهم بعيدًا عني بينما أعمل.",
[2404210206]="لن نقدم لكم البيرة!",
[2404287062]="لا يمكنك فعل هذا بي! كان بيننا اتفاق!",
[2404478076]="تعامل مع هذه المقاطعة، كيلدونس. بعد أن تنتهي، أحضر لي رأس من يسمونه $N. سأزين غرفتي بجمجمة $Gخاصته:خاصتها;.",
[2404732638]="شكرًا لك، $N. من أعماق قلبي. شكرًا لك.",
[2405004133]="يجب ألا تقتربوا من ملكة الصقيع. بسرعة، أوقفوهم!",
[2405985133]="الفراق حلو مر.",
[2406010163]="[فوربولق] اذهب... ابحث في قاع نهر يتيكس كيل. جنوبًا!",
[2406403717]="...ذلك الكلب الجربوع كان له ساقان خشبيتان، وخطاف ليده اليسرى، وعينان زجاجيتان، وأنف خشبي!",
[2406758485]="إذا كنت لطيفًا معي، سأدعك تعيش.",
[2406937822]="ارجع، فلافي!",
[2407124611]="...مع المزيج الصحيح، ربما...",
[2407643456]="مثل موشا.",
[2407908230]="هذه الحديد مجنونة! يستمرون في الحديث عن خدمة 'سيدهم لوكين' لكن مما أستطيع قوله، القليل فقط يتلقون أوامر منه.",
[2407953936]="الفوضى التي زرعتها هنا ليست إلا طعمًا....",
[2408458532]="ما الذي تحتاجه؟",
[2408494540]="مباشرة إلى القلب!",
[2409134982]="أنتم موتى!",
[2409191058]="لا يمكنك... أن تكون جادًا، أولوم. تضحيتك كانت بالفعل كبيرة جدًا.",
[2409541414]="اسمع. ما يفترض إني أقولك هذا، لكن في حفلة سوف تنعزم عليها. أي شي تسويه، لا تشرب الشراب!",
[2409561773]="أبي، أنت اللي أكلت صحن الفواكه؟ صح؟",
[2409837146]="تطقني؟! حسنًا، خلص يا ولد.",
[2409851923]="ورشة حصار الهيكل المكسور تعرضت لهجوم من الأليانس!",
[2410148777]="الصدع سوف ينفتح هناك، فوق بحيرة إلونارا. جهز نفسك، $N. دخول إيرانيكوس لعالمنا سوف يكون مليان فوضى وصراع.",
[2410688508]="متجاهلاً المعركة اللي تدور حوله، لاتيرييون خفف حراسته ليحتضن حبيبته في لحظاتها الأخيرة. لكن الشياطين ما أعطوه مهلة، وسرعان ما صرعوه.",
[2411061507]="أنت اللي تتبعت الأوغاد اللي سووا فينا كذا.",
[2411113714]="أتباع، خدم، جنود الظلام البارد! أطيعوا نداء كيلثوزاد!",
[2411233856]="مؤشر التهديد الحرج. تحليل الفراغ تم تحويله. بدء بروتوكول التعقيم.",
[2411489857]="لنروح قبل أن يكتشفون إني طليق!",
[2411664861]="الأنهار الجليدية تتسرب من آيس كراون... والأنديد في كل مكان! انتظر حتى يمسك الأستاذ بهذا!",
[2411883646]="%s يشكرك برقصة خاصة.",
[2411904108]="سأخبرك بكل شيء! توقف! أرجوك!",
[2412208903]="هذه النهاية وصلت إليها من قبل. أي مغامرة جديدة تنتظرني؟",
[2412563068]="حان الوقت أخيرًا! لوريد كان يشعر بالملل.",
[2413469516]="قد يأتي الوقت قريبًا عندما يحتاج الكالدوراي إلى المعرفة والمهارة التي لدينا.",
[2413503928]="حسنًا بن. لقد استعدنا بذور العنبر مرة أخرى. أنت تعرف الإجراء.",
[2414334750]="تفضل، أعطني أفضل ما عندك. أستطيع تحمله!",
[2414578420]="لقد جئت متأخرًا جدًا، $N. زائر آخر من دالاران جاء يسأل عن معلومات حول نفس السيوف التنين البريزمية.",
[2414912351]="مت أيها الحشرة!",
[2415205371]="أتريد محاربتنا جميعًا مرة واحدة؟ هذا سيكون مسليًا!",
[2415627571]="هراء يا موغراين! يجب تدميرها!",
[2416009337]="غارديان اوف آيس كراون يدخل المعركة!",
[2416309314]="المزيد من غريمتوتيم قادمون بهذا الاتجاه!",
[2416751067]="ستسعد الماجستريكس بمعرفة أنني أتقن الثالاسيان. لطفك لم يضع علي.",
[2416825509]="يارل؟",
[2417367060]="لا مفاجأة هناك.",
[2417417071]="مقبرة ستورمبايك تتعرض لهجوم! إذا تُركت دون رقابة، سيستولي الأليانس عليها!",
[2417440884]="خففوا الضجة يا رفاق. يجب أن نبقى في حالة تأهب!",
[2417554438]="وداعًا...",
[2417560784]="أجل يا سيدي، كل شيء يسير كما خُطط له.",
[2417630272]="والآن لنجربها...",
[2417743696]="يجب البحث عن ذاك المرقط. مصائرهما متشابكة.",
[2418128083]="حياتك ملك لي!",
[2418203676]="مقاومتك الضعيفة لم تعجل إلا بهلاكك.",
[2418261432]="على ركبتيك!",
[2418338556]="يوماً ما سأصبح فتىً حقيقياً.",
[2418637578]="سوف تحترق!",
[2418747845]="لا.",
[2418890861]="بادمون؟ تقصد بلودمون؟",
[2419066282]="لقد أنقذت وينترغارد! مع غسل قذارة ثيلزان، سينظف ليجيون السابع بسهولة ما تبقى من الـسكورج. عندما تنتهي هنا، أبلغ أنغراثار!",
[2420029869]="أنا أسحق! أنت تموت!",
[2420049304]="كما تشاء...",
[2420070134]="يا ملكتي، إنهم... يأتون.",
[2420150506]="لكن يا! على الأقل إنها بيرة!",
[2421077970]="مت، $N. إلون لن تسمح لك بإيذاء مخلوقاتها بعد الآن!",
[2421167487]="دمه لي، وكذلك جنسك اللقيط بأكمله.",
[2421357514]="صدقني عندما أقول لك هذا: ستتمنى أنك لم تولد، يا جبان!",
[2422009052]="هذا هو، يا فتى! يبدو آمنًا تمامًا. انطلق، سأكون خلفك مباشرة!",
[2422064506]="كل من يغامر هنا فهو ملكي، بلا يوجد ذلك أنت!",
[2422499267]="شيء ما أثار ذلك الحصان. لنذهب!",
[2422898618]="لا--كاو--تقف في طريقي--راك-راك--اهرب!",
[2422912538]="يا إلهي.",
[2423074434]="كوا! لا يمكنك قتلي، أنا خالد!",
[2423580169]="استمر في ذلك، $N، وسأعلمك بعض الأدب.",
[2423896876]="كم هذا مؤسف، هالفدان.",
[2423932982]="بجرأة، جئت لانتزاع أسرار ليفينق فليم! ستندم قريبًا على تهور مهمتك.",
[2423959268]="المنزل جيد، لكن لا نبقى طويلاً! مغامرات أكثر!",
[2424337554]="يدخل الحلبة البطل الأعظم لـ دارناسوس، الحارس الماهر جاليين إيفنسونق!",
[2424427100]="كور'كرون، تراجع!",
[2425788430]="الآن! أخيرًا! خططنا يمكن أن تنفذ!",
[2425844259]="تورميل، جاملور، شيفرد، كاوري...",
[2425938877]="عندي شيء واحد فقط لأتحقق منه...",
[2426305366]="هاها! $N، أنت شريك رائع!",
[2428079760]="ممتاز، دماء جديدة وصلت.",
[2428145724]="%s يرش خيوط العنكبوت في كل مكان!",
[2428664154]="أنا... عندي جدتي مريضة في البيت... أنا... كل ما تملكه، $Gسيد:آنسة;.",
[2428910979]="كما تشاء، $N.",
[2429930967]="هذا يكفي! لا مزيد من البيرة حتى يتم حل هذه الفوضى!",
[2430035215]="سيتم الأمر، إيرانيكوس. كن بخير، أيها القديم.",
[2430062773]="قف! أتسمون هذا قتالًا أيها اليرقات؟ هذا مثير للشفقة! الآن ضعوا قلوبكم فيه، فلستم بحاجتها بعد الآن على أي حال!",
[2430263667]="تجمّعوا!",
[2430281388]="الآن سنرى لماذا هذا الخام مهم جدًا للسكورج.",
[2430701289]="ذلك الترول الجبان خذلني للمرة الأخيرة. أنثيس! اكسر ساقيه!",
[2430849951]="قاتلوا جيدًا يا هورد! لوكتار أوغار!",
