[2432802133]="ما من مخرج.",
[2433869833]="والآن عرفت لِمَ أعيش في فوهة.",
[2434163268]="أرجوك... توقف. سأفعل... أي شيء....",
[2434378364]="يا للهدر....",
[2434786926]="حشرات!",
[2435038702]="سنشحذ فؤوسنا بعد هذا.",
[2435614442]="...أرجوك لا تقلل من شأني.",
[2435744536]="لا نعلم إن كانت كهوف الزمن متاحة دائمًا للبشر. حقًا، من المستحيل الجزم لأن الخالد في حركة دائمة، يغير مساراتنا الزمنية كما يشاء. ما تراه الآن قد لا يكون موجودًا غدًا. قد تستيقظ أمس ولا تتذكر هذا المكان.",
[2435913265]="أي، كن بأمان مورادين. كنت سأنضم إليك، لكنني على وشك اكتشاف أعظم اكتشاف شهده العالم. لا أستطيع تركه الآن.",
[2435957949]="موقدورق الـ ويزيند قل لـقروك اذهب للمدينة، احصل على مساعدة لـبلودمول. قروك اذهب.",
[2436123153]="حتى على النهر الجليدي نفسه، تمكن الشمس من التسلل عبر الظلام. لدي أمل، تاهو. أعتقد أننا سننجح في هذا، مهما بدا الأمر مروعًا.",
[2436423837]="كنت أعرف!",
[2437118777]="لماذا لا نستطيع فقط تحويل المصفوفة لتعويض التباين في التدفق؟",
[2437687546]="تعال، زيليك، لا تطردهم. ليس قبل أن نستمتع نحن.",
[2437750112]="يا معلم، متى سنرى برج الميج اللامع؟",
[2437952731]="بيجو ضاع! سكواك! *سعال*",
[2437989332]="وداعًا يا صديق. أتمنى أن نلتقي مجددًا في ظروف أفضل. لن أنسى أبدًا ما فعلته من أجلي!",
[2438186602]="لقد اكتفيت من هذا المكان. فلنرحل.",
[2438937857]="لو كنت أعلم أن الأمر سيكون هكذا، لارتديت بوتس الأعظم للضحك.",
[2439012601]="يجب أن يستمر العمل!",
[2439309662]="أنايا...؟ هل تخدعني عيناي؟ هل أنت حقًا؟",
[2440134121]="أوه، ها أنت، روكبايتر! أنا آسفة، أعرف أنه لا يُفترض بي أن أبتعد.",
[2440263192]="نحن القلة، نحن السعداء القلة، نحن عصابة الإخوة والأخوات. من يسفك دمه معي اليوم، سيكون من أهلي؛ مهما كان وضيعًا، هذا اليوم سيلطف حالهم.",
[2440856066]="أشياء لامعة! أشياء لامعة! ليست بلمعان بلورتي، لكنها لا تزال لامعة!",
[2440911920]="هذه المنطقة ستدمر نفسها بعد ثماني دقائق.",
[2440995389]="لا يمكنني أن أطلب يومًا أجمل من هذا!",
[2441451340]="يدك! لقد شُفيت!",
