[2441933096]="هل يمكن أن يكون حقًا؟ ابن دوروتان؟",
[2443379123]="حشرات! دعني أريك قوتي عن قرب!",
[2443411726]="أيها الأحمق الثرثار. أيها البلهاء غير المفهوم غير الكفؤ...",
[2443553391]="أعرض الزواج؟ سأريك ما أعرضه!",
[2443771609]="اعتني بنفسك، أنطونيو. سأراك بعد أسبوع آخر.",
[2443987611]="%s يتراجع من الألم بينما يغمره نور الحكم!",
[2444026434]="في الوقت المناسب، ماييف. لقد أمضيت سنوات في التحضير لتحركي - لا يمكنني المخاطرة بتعريض خططي للخطر بكشف يدي مبكرًا.",
[2444700955]="إنها تحتضر! الجزء الثاني من شفرة اللعنة لنا. أنا...",
[2444708804]="$N لديه |cFF00FFFFحرق اللحم!|r",
