[2448046276]="سوف نذيب هذه الخردة ونصنع أسلحة من السبائك! لنرى كيف سيعجب الـليجيون بطعم مفترس الفيل المصنوع على طريقة الأليانس!",
[2448096774]="أنا... لم أكن عند بوابة الغضب، لكن الجنود الذين نجوا أخبروني الكثير عما حدث. ابنك قاتل بشرف. مات موتة بطل. يستحق دفن بطل.",
