[2449441737]="هناك أربعة مولدات تزود الهياكل الدفاعية بالطاقة. إذا خربت المولدات، ستتوقف هجمات الصواريخ!",
[2449565775]="همم، يبدو أن كيفر بحاجة لموضوع جديد. إذا استمر ذلك الأحمق أبيرناثي بأخذ مواضيع كيفر، قد يضطر كيفر للتحدث معه.",
