[2451014591]="فعلت ما كان علي فعله يا أخي. لم تترك لي خيارًا آخر.",
[2451378997]="سيد بيريلي، أعلم أنك تسافر كثيرًا لبيع بضائعك. بالتأكيد سمعت شائعات أو معلومات عن الـسكورج؟",
[2451383714]="أوو!",
