[2451498544]="سأخرج من هنا!",
[2451679152]="%s يبدأ بالرقص.",
[2451746813]="سيأخذ آخرون مكاني.",
[2451838776]="لكن عقابك الحقيقي ينتظرك.",
[2451974346]="أسرعوا أيها الإخوة! يجب أن تذهبوا الآن! لا أعرف كم ستبقى الصدعة مفتوحة!",
[2452274763]="لا! لقد قتلت الملكة شيء! ماذا فعلت... انتظر، لا يهم. آسف، هذا جيد.",
[2452318060]="أريد من جميع متتبعيك البحث عن المجرم، ماتيس الـ كرويل. لقد أعطيت عملاء موثوقين من اليد مسدسات إشارة. إذا رأيت أنت أو أحد متتبعيك الإشارة، فهذا يعني أن عميلاً وجد ماتيس ويحتاج مساعدة. وتذكر أيها المتتبع، ماتيس يجب أن يُعاد إلي حياً.",
[2452380445]="الموجو الخاص بـسيراتوس أصبح لنا. الآن سيسحق الجميع تحت قوة الدراكاري!",
[2452997170]="أنت ملكي الآن.",
[2453227763]="أنت تعرف ماذا.",
[2453274837]="هوراي! أنا حر!",
[2453493376]="آآآآرغ...",
