[2481875851]="هذا سيخفف الألم.",
[2482083152]="اسمعني، $N. يجب أن تقاوم سيطرة الـليتش كينغ. إنه وحش يريد رؤية هذا العالم - عالمنا - في خراب. لا تدعه يستخدمك لتحقيق أهدافه. لقد كنت بطلاً ويمكنك أن تكون كذلك مرة أخرى. قاتل، بحقك! قاوم سيطرته!",
[2482376935]="فاندرال! حان وقتك! اذهب واختبئ في الإيميرالد دريم وصلِّ ألا نجدك أبدًا!",
[2482531161]="هيا يا فتاة. لدي وجبة أخيرة لك قبل أن يقتلنا قاتل ليمبي جو!",
[2482775628]="اهدموا القاعات! الآن!",
[2482828809]="ستتذوق نصال شفرة سيفي في عيد الشتاء هذا! يارغ!",
[2483268852]="يخططون لهجوم ضخم! يجب أن نحذر هايلورد فوردرينغ!",
[2483384391]="%s يتفرقع ويتدفق بالطاقة الخام!",
[2483852221]="يكفي كلام. عندما أنتهي منك، حتى الـوورغز لن ترغب في الاقتراب من جثتك.",
[2483852589]="مشروبات مجانية في البلو ريكلوز!",
[2484048399]="لا – ولا تحاول هزي مرة أخرى للحصول على إجابة أفضل!",
[2484201907]="%s يبكي بهدوء.",
[2484319573]="هل ترى الآن؟ هل ترى؟!",
[2484481033]="مناورة مراوغة! جهزوا المدافع!",
[2484539333]="%s يدخل في نشوة...",
[2484569215]="زاراث، يجب أن تعود إلى بلاك تمبل فورًا! أنا... يبدو أنني أضعت أوامر اللورد إيليدان. بسرعة!",
[2484576228]="وقت العشاء، يا حيواناتي الأليفة!",
[2485422594]="%s يضرب!",
[2485873082]="بيسي يصهل بسعادة.",
[2485985868]="باسم تيروك!",
[2486206260]="قلوري إلى كيلجايدن! الموت لكل من يعارض!",
[2486585779]="نعم، زانا، إنه أنا! إشارتك ضعيفة.",
[2486665637]="%s يبدأ باستدعاء الأشباح من الهواء البارد المتجمد!",
[2487341865]="شكرًا لك، أيها المبشر الطيب. كلماتك لطيفة جدًا.",
[2487549866]="حياتي من أجل أسيادي. افرحوا!",
[2487728475]="هم هنا لأنهم لا يريدون الدفاع عن بيوتهم... عائلاتهم...",
[2487731212]="أخبر الصوفي أن شعبه يجب أن يقف ويقاتل إلى جانب الـهورد والأليانس ضد قوى ماليقوس والـليتش كينغ.",
[2487939753]="لا أشعر بالكذب في صوتك، أكاماً. أن كايل'ثاس يخونني ليس مفاجأة كبيرة - أنا لست غافلاً كما يعتقد البعض. أن أحد أفرادك كان متورطاً معه يضع ولاءك موضع تساؤل.",
[2488017167]="كما كنت!",
[2488028283]="لا أريد أن أعرف المزيد. اجعلني أنسى!",
[2488618616]="سأستخدم قوة بلورة أتا'مال لسحقك!",
[2488703635]="دعوني أسألكم هذا، أيها الإخوة والأخوات: هل يمكن للخير أن يوجد بدون شر؟ هل يمكن أن يكون هناك نور بدون ظلام؟",
[2489255330]="ليس لدي وقت لهذا أيها الملازم. تأكد من أنك تتعامل معه.",
[2490078721]="إذا لم تروا واحدة من قبل، فهي منظر يستحق المشاهدة. مخلوق مثير للإعجاب سواء في ساحة المعركة أو خارجها. بعد ذلك، دعونا نلقي نظرة على ما أنا متأكد من أن جميع الطلاب الذكور ينتظرونه. السوكوبس.",
[2490311371]="لينيرني النور بالقوة لأقدم تحدياً جديراً.",
[2490315437]="واحد أزرق آخر سقط. نحن فريق رائع!",
[2490449219]="عرق القرصان المتعفن!",
[2490728043]="لا، هذا لا يمكن... تقول هذه الكتابة أن هذا المخلوق أصبح خادمًا لـ الـليجيون عن طيب خاطر. يتحول إلى ساتير ويتلقى \"بركة\" الـليجيون.",
[2490782012]="*وحدة ثريشواكوناتور الضابط الأول جاهزة للمتابعة*",
[2490953182]="أصدقائي، انضموا إلي في التضرع المتواضع إلى النور.",
[2491527351]="أعتقد أنني أكلت الكثير من الحلوى...",
[2491672971]="كل ما تفعله هو إضاعة وقتي!",
[2491830225]="ارحمهم يا ملكي! إنهم من لحمنا ودمنا!",
[2492145989]="قاروش، أتوقع منك أن تتحكم بنفسك هنا. لا أريد تكرار ما حدث في الـفيوليت سيتادل.",
[2492203565]="لن تفعل شيئًا كهذا. ببساطة ليس لدينا مساحة لإبقائك هنا. الآن، تفضل بالذهاب.",
[2492683427]="كلاكما ستعانيان كما يعاني والده...",
[2492908262]="من المؤسف أنهم لا يظلون لطيفين. لا بد أن هناك طقسًا في البارنز اسمه \"اصعد شجرة القبح واسقط منها\".",
[2493098507]="البرق يوجه غضبي!",
[2493238784]="سحابة من أبخرة السارونايت تتجمع بالقرب!",
[2493313776]="أووه... هذه الصخرة جميلة وملونة. دعني أرى إن كان بإمكاني إيجاد المزيد مثلها...",
[2493423398]="بعد ذلك، سأتحدث عن جناح العنكبوت الملعون في ناكسماراس. هناك يربي الـسكورج نسخًا أكثر سمًا وخطورة من أقاربهم.",
[2493562140]="من يظنون أنفسهم؟",
[2493628505]="%s يحمي نفسه ويحول قوته إلى الصدوع!",
[2494109993]="نعم، الحياة زائلة، راك-آ-كاك!",
[2494932407]="لا أستطيع صدها بعد الآن! أخبر الإكسارك أنني بذلت قصارى جهدي.",
[2495922610]="أين انيا؟",
[2496190214]="عنيد وعجوز. ما فرصتك؟ أنا أقوى وأكثر قوة مما كنت عليه.",
[2496934982]="من التالي؟",
[2496995209]="كفى! لا مزيد!",
[2497041508]="ها! ها! ها! شكرًا لتحريري أيها الحمقى. الآن دعوني أرد الجميل بحرق اللحم عن عظامكم.",
[2497590474]="قريبًا، سيسود الـسكورج العالم!",
[2497678387]="%s يخلق عاصفة دوارة من العظام!",
[2497713411]="شكرًا لكم. النور معكما.",
[2497848827]="سكار'ثيس أبلغنا جيدًا. لقد شقنا طريقنا إلى أقلام العبيد وننتظر سحرة الثلج لديكم.",
[2498315823]="يبدو أنني اخترت يومًا سيئًا لأتوقف عن الشرب.",
[2498467466]="مغامرون من كل مكان يبيعون الأشياء لأنطونيو-- تعالوا وانظروا بأنفسكم ما الكنوز الصغيرة التي لديه لكم هذا الأسبوع.",
[2498944273]="وداعًا، آرثاس... يا أخي.",
[2499056360]="ما بقي كثير، $N. المخرج قريب من هنا.",
[2500563242]="%s تغمض عينيها، تتذوق الحرية للحظة.",
[2500721996]="وصل خبر من جوتونهايم. يعتقد حراس النوم هناك أنهم وجدوا شخصًا مهمًا.",
[2500851197]="هل يمكن أن يكون؟",
[2501024408]="كنت فقط... أتبع الأوامر.",
[2501088723]="ستسقطون أمام قوة الـسكورج. كريبت ريدرز، اهجم!",
[2501208672]="أين تلك الشحنات في أوتلاند؟ لأيام يتركونني أنتظر!",
[2501256276]="هي! ليس عدلًا!",
[2502051633]="مجرد مزحة بريئة.",
[2502113056]="لكن المأساة أن آرثاس يلتهمه الشر ويصبح شريرًا هو نفسه...",
[2503335386]="لم يعد... لم يعد هناك وقت لي. لقد انتهيت. أنهِ أمري يا $N. افعلها وإلا سيقتلوننا كلينا. $N... تذكّر تيريسفال! هذا العالم يستحق الإنقاذ!",
[2503828803]="الإغلاق الطارئ سيكتمل خلال دقيقة واحدة.",
[2503944952]="%s تهز رأسها بعدم تصديق لما تسمعه من فم الفورسيكن.",
[2504282753]="استعد للفناء!",
[2504330570]="هل تعتقد أن تعاليمه خاطئة؟",
[2504485096]="إلى الأمام يا سكريِرز! أرِ أتباع إيليدان قوة فولاذنا!",
[2504504884]="إلى قاعة العرش!",
[2505090622]="سيتم إرجاع أقراصك إليك بمجرد وصولك إلى القاعدة.",
[2505577163]="%s يتثاءب.",
[2505760020]="$Gملك:ملكة; $N، أنا أموت الآن.",
[2506212205]="يبدو أن خاتم هودير موجود داخل مخبأ من القطع الأثرية.",
[2506762842]="الآن لندور على العشبة.",
[2507042358]="سأبدأ فورًا، $N.",
[2508127713]="كفى تكاسلًا وقاتل كأورك شيطاني حقيقي!",
[2508671033]="موتوا، يا كلاب الشياطين!",
[2508797372]="%s يكسر البيضة الفاسدة و- لرعب وفزع كل من حوله- يبدأ بالشرب من قلبها النتن.",
[2508833436]="ريميولوس، انظر كيف يسقطون أمامي بسهولة؟ يمكنك إيقاف هذا، أيها الأحمق. سلمني الدرويد وسينتهي كل شيء...",
[2509077798]="%s يزأر في وجه تيرينثيس لجذب انتباهه.",
[2509104165]="إنهم يحاولون قتلي! النجدة!",
[2509325173]="وجّه التدفق من المستنقع الغربي.",
[2509847581]="هذا لن يأخذ وقتًا طويلاً، أليس كذلك؟",
[2510085400]="لن أتوقف أبدًا. أبدًا...",
[2510087444]="هذا الوقت من العام مهم جدًا لحلفائنا الفورسيكن.",
[2510316503]="%s يسلم النظارات المتوهجة إلى دوكتور دركسليغوك.",
[2510677180]="القوة... تتلاشى...",
[2510758516]="أنا... أنا لا أفهم، بوبو.",
[2510906674]="إذا كان هذا صحيحًا، فليس لدينا وقت طويل! حسنًا.",
[2511068557]="%s أعيد تفعيله. استئناف وظائف القتال.",
[2511316334]="لا يمكن الوصول إلى معلومات إضافية إلا من الأرشيف داخل اولدوار، بأمر من الحارس لوكين.",
[2511869911]="الريكومبوبولاتور شكله حلو. باقي قليل من تعديلات!",
[2512401401]="أوه، كثير لذيذ. شكراً جزيلاً، سيدة تشامبرز.",
[2512658097]="%s يلاحظ زومبي ليلتهمه!",
[2512880763]="الـسكورج يناديك، أيها $R الأحمق.",
[2513045897]="هناك تغيير في الريح، ولا يمكننا تجاهله. لقد جئت من غبار وخراب الماضي للوصول إلى اتفاق.",
[2514255931]="لابد أن تينكرك صنعك من صفيح، أيها الأكوام الكسولة من الخبث!",
[2514406681]="$R الصغير يريد قتال أوفرلورد موك موروك؟ أنا أضربك! أنا الزعيم هنا!",
[2514763407]="لو قتلوا الآلهة القدماء، لكان أزيروث قد دُمّر...",
[2514965398]="بقايا كويلبور! هذه ستفي بالغرض. فيش يحب كويلبور.",
[2516264817]="جثث الذين يحاولون فقط تغذي جيشنا المتوسع!",
[2516271109]="اسحق الصغير!",
[2516580051]="عدت من القبر لأخذ انتقامي!",
[2516918222]="أتريد اختباري؟",
[2517267899]="هل أنت مستعد للمعركة، $C؟",
[2517436977]="كن بأمان، أنطونيو.",
[2517520606]="ارحمني، $Gسيدي:سيدتي;!",
[2518231898]="لماذا علينا تعلم هذه الأشياء على أي حال؟",
[2518532311]="%s يضرط.",
[2518851642]="الرعب المعروف بـ كارنيج لم يعد موجودًا. هل يمكن أن يكون $N جديرًا حقًا بالقتال في فالهالاس؟ سنرى.",
[2519513385]="كفى! لقد سئمت من هذه المشتتات!",
[2519643730]="روح الذئب في الغابة، اسمعني!",
[2519697027]="نذير الموت يولد من جديد...",
[2520230418]="جنود أزيروث، أنتم الآن تقاتلون ضد البيرنينغ كروسيد الحقيرة. وآمال وصلوات كل محبي النور تسير معكم. برفقة حلفائنا الشجعان وإخواننا في السلاح، ستصمدون وتكسرون هذا الهجوم الشيطاني. ستمنعون الطغيان المدمر الذي يعصف عبر عوالم كثيرة.",
[2520396991]="ماتوا بسهولة. لا يهم.",
[2520519726]="أرجنت داون! سنذهب لجلب المزيد من المساعدة! قاتلوا، أيها الإخوة والأخوات. واعلموا أنكم لن تقاتلوا وحدكم طويلاً!",
[2520581293]="%s يدخل في حالة هيجان!",
[2521290277]="هذا لا يمكن أن يكون! أنا السيد هنا! أنتم البشر لا شيء أمام جنسي! هل تسمعونني؟ لا شيء!",
[2521379716]="أسرعوا، أيها الأوباش! السيد لن يرضى إذا لم نجد بلورة أتامال التي يبحث عنها.",
[2521614689]="نحتاج تمثيلاً أفضل من ستورمويند. منازلنا تسقط بيد الأنديد.",
[2521731384]="يتقدم من الجنوب، ورائحة كارنيج تسبقه!",
[2522172800]="حسنًا، هذا يكفي. تعال الآن، نعود إلى المتجر لننهي أعمالنا!",
[2522346339]="أنت مجرد لعبة. لا تصلح حتى للتسلية.",
[2522878264]="القوة التي منحتني إياها منحتني تأثيرًا عقليًا كبيرًا على عقول البشر. أحمل هذه القرابين كدليل على تقدمي.",
[2523784193]="مهمتك اكتملت. استعد للقاء حتفك.",
[2524265835]="هل ما زلت معنا يا ريث؟",
[2524314008]="%s يزأر طلبًا لرفيقته!",
[2524423176]="آمرك أن تمطر نارًا على هؤلاء الغزاة!",
[2525752387]="أنكوريت نيندومن، لدي طلب منك.",
[2526186605]="أنت غير مرحب بك هنا. مت!",
[2526594016]="قلب %s الميكانيكي يبدأ بالخفقان بهدوء.",
[2526816837]="أين الوارتشيف؟",
[2526931207]="لقد حان الوقت! اللحظة قد اقتربت!",
[2527057940]="أي حماة؟",
[2527193316]="أحسنت. لقد أثبت نفسك اليوم-",
[2528282570]="موديل يو-9207 آيرون رون كونستركت لا يقدّر نبرة صوتك. بدء الإبادة الكاملة لسجادتك، ليبرونسكي.",
[2528733705]="أكلفك الآن بتطهير زولدراك، دراكرورو.",
[2528762913]="أتعلم... لماذا نحتفل بهذه العطلة؟",
[2529352083]="سنأخذ المعركة إلى آرثاس، وسنهدم أسوار آيس كراون!",
[2529589310]="خذ هذا، أيها الوحش!",
[2529627908]="آه، برايفيت هينديل. من دواعي سروري مقابلة أحد الرجال الذين سيخونون مملكتهم من أجل الكبرياء.",
[2530894201]="%s يضع عينيه على $N!",
[2531141884]="في يوم من الأيام سأغرقه في ذلك الرداء الأزرق. وكل مكانسه أيضًا.",
[2531308078]="يجب أن أجد طريقة لوضع حد للشر الذي يرتكبه سيرسي دسك سينقر ضد إخوتنا وأخواتنا المفقودين!",
[2531346389]="بالطبع أتحدث مع نفسي. الطريقة الوحيدة للحصول على محادثة لائقة في هذه المدينة.",
[2531509667]="هممف. شكرًا على أي حال، لكني لم أكن بحاجة إلى أي مساعدة.",
[2531692714]="سواء كنتم أعظم البعوض في العالم أو أعظم الأبطال، فأنتم لا تزالون مجرد بشر.",
[2532362415]="أسرع! لم يتبق الكثير مني!",
[2532486065]="يؤسفني إبلاغكم أننا أعدنا عشرة جنود آخرين إلى ديارهم اليوم - في أكياس الجثث.",
[2532865135]="أنزلوا تلك القطع إلى السفينة!",
[2533016558]="هل انتهى الأمر بالفعل؟ لقد كنتم رائعين. امشوا بسلام وليلة سعيدة.",
[2533299605]="كفار!",
[2533405903]="هذه الأرض المتجمدة تكفي للبداية. تعالوا إليّ أيها البشر - وسأمنحكم موتًا سريعًا ومؤلمًا.",
[2533426286]="لا مزيد!",
[2533620941]="غازٍ قادم!",
[2533622216]="فعلناها يا رفاق! وصلنا هنا قبل وصول ألغالون. ربما نستطيع التلاعب بالأنظمة لإفساد تحليله--",
[2533705452]="احترقوا! أيها الأوغاد! احترقوا!",
[2533992592]="دوارف الحديد الأسود، لا يكذبون،",
[2534248058]="ربما أنت نائم يا سيد العظيم؟ نحن نفهم. لا بد أن العمل شاق كونك العظيم، تجمع كل اللماعات التي نتركها لك.",
[2534476157]="أرجوك، $N. يجب أن تأخذ قلب فيوري إلى مكان آمن... يجب أن تأخذه إلى أدال!",
[2534871572]="عندما أحتاج شخصًا يتبختر مثل طاووس منتفخ، سأستدعيك.",
[2534881153]="خلص وقتك!",
[2535198512]="تم الحصول على الهدف. بدء بروتوكولات الأمن.",
[2535568507]="انحنوا، أيها الديدان الصغيرة! أبطالكم الضعفاء لا شيء! منقذوكم سيكونون أول وليمة لنا!",
[2536609799]="ما معنى هذا؟! لم أنهِ وليمتي بعد!",
[2536666643]="أظهرنا لذاك!",
[2536767868]="لا أعرف، بيلي... الأمر ليس سيئًا للغاية. يمكننا رمي حجر على الأدوات من هنا.",
[2537056475]="أنتم لا تعرفون ما تفعلون! يجب أن ندمركم لمصلحتكم.",
[2537219995]="الكابتن جوزيف ريدباث قد فسد! اقتلوه بسرعة!",
[2537225156]="أوووه. كيف تجرؤ!",
[2537448711]="ذلك الحقير بوتريس لن يفلت بهذا!",
[2538715649]="اشعر بغضبي، يا حثالة $R! لن تفلتوا بهذا!",
[2539158545]="%s يتجشأ بايل سلايم مقززًا!",
[2539578102]="هذا ما تقوله دائمًا. أحيانًا أعتقد أنك لن تنتهي من ذلك الشيء أبدًا.",
[2539983884]="ها أنت ذا، ريلارا. خذي هذا...",
[2540230376]="أيها الجنود، أمسكوا بهم. أحضروا جثثهم إلي.",
[2540394072]="من يجرؤ على إزعاج تأملي؟",
[2540400414]="%s يكتم ضحكة.",
[2541457022]="أتساءل ماذا سيعطيني نيسينغواري مقابل جلدك!",
[2541504461]="كل ما أحتاجه الآن هو لاسو ذهبي.",
[2541665665]="لقد ابتعدت كثيرًا. أضعت وقتًا طويلًا...",
[2542683259]="إنه... إنه... إنه جميل. ما شعرت به عندما لمسته... النور جرى فيّ وجريت فيه... شفى روحي.",
[2543022829]="يبدو أنني ارتكبت خطأً بسيطًا. سمحت لعقلي بأن يفسده الشيطان في السجن، متجاوزًا تعليماتي الأساسية. يبدو أن جميع الأنظمة تعمل الآن. واضح.",
[2543137379]="قوة مظلمة تسعى لاستخدامك، ميديف! إذا بقيت، ستأتي أيام مظلمة. يجب أن تتعجل، ليس لدينا وقت كثير!",
[2543250005]="شكرًا لك يا صديقي لجعل هذا ممكنًا. هذا يوم لن أنساه أبدًا! أعتقد أنني سأبقى لبعض الوقت. أرجو العودة إلى هاي بريستس ماكدونيل في المخيم. أعرف أنها ستكون مهتمة جدًا بمعرفة ما حدث هنا.",
[2543578230]="حان وقت انطلاق قافلة غيزلتون! سنعود قريبًا، لكن إذا لم تستطع الانتظار، اتجه شمالًا إلى كوخ كورميك. نفتح المحل بعد حوالي ساعة.",
[2543612195]="أو تلك المرة التي أخبرتنا فيها أنك اكتشفت علاج طاعون القرن العشرين. ما هذا حتى؟ القرن العشرين؟",
[2543907574]="صحيح، لكن إلى أي مدى يجب أن ندفع؟ عند أي نقطة نصبح لا أفضل من أعدائنا؟",
[2544059575]="أعتقد أنك تدعم حجتي، لكن نعم سيكون جميلًا لو كان لدينا المزيد من التعزيزات. سأرد بأنه سيكون أسرع سحب الفارسترايدرز من مناوشاتهم العبثية مع الترولز.",
[2544421586]="سَتَكُونِينَ لي.",
[2544463853]="كان لازم تثبت جدارتك...",
[2544496561]="كنت أحتفظ بهذا لك فقط، أيها الكبير!",
[2545172436]="بالنجوم! تم استدعاء روح!",
[2545232778]="كلكم ستفشلون!",
[2545472370]="الآن لأضع المرهم على جروحها.",
[2545665369]="ربما... قللنا... من شأنك...",
[2545724124]="نعم حالاً يا أمي!",
[2545868929]="%s يصدر صوتاً غريباً يترجم كضحك في عقلك.",
[2545968756]="أقترب من العالم!",
[2546051637]="بالنور ستغادر هذا القبر!",
[2546443482]="أتمنى أن يساعدك الأجداد دائماً، $C، كما ساعدتني.",
[2546567073]="احموا مانح الحياة!",
[2546840078]="اعتذاري، أيها السفير. أوامري كانت واضحة جدًا.",
[2546903832]="شكرًا لإنقاذ حياتي وإعادتي إلى بر الأمان، $N!",
[2547614532]="أعدك أنني لن أقتل طاقمك هذه المرة. هاه! لكن أخي قد يأكلهم!",
[2548346592]="أجنحة الدبور!",
[2549384049]="هذا هو الموقد، $N. أطفئه. فورشا وحش لا يستحق الثناء من أحد!",
[2549569907]="وبالفعل، عاد الكشاف راكضًا يتحدث عن بعض الأوركس على الطريق. لم يكونوا قد رأونا بعد، فقررنا أن نذهب ونتعرف عليهم.",
[2549698826]="بدء تحليل معبد النظام.",
[2550099720]="هي، $N، حاول أن تترك لنا بعض المجد، حسنًا؟",
[2550289223]="%s يرفع مطرقته بشكل تهديدي...",
[2551553662]="كما ترى، لدي العديد من الأسلحة في ترسانتي...",
[2551589681]="ألم تظن حقًا أنني سأتعامل معك مرة أخرى؟ أحيانًا، أفضل طريقة للعودة للربحية هي معرفة متى تقطع خسائرك.",
[2551652949]="لماذا... لماذا يا أختي؟ لماذا كان يجب أن نصل إلى هذا؟",
[2551693988]="الـليتش كينغ يجب أن يسقط!!",
[2551814826]="ستتكلم في النهاية. قد تفصح بها الآن.",
[2552372540]="هذه فارغة!!",
[2552429494]="شكرًا، كان يجب ألا أغادر سيلفرباين فورست أبدًا.",
[2552997403]="لن أُمنع! هذا العالم سيسقط!",
[2553057591]="أبواق الأليانس؟ كن على أهبة الاستعداد!",
[2553387292]="الجنرال فروست وولف مات!",
[2553411751]="البريست يركع في صلاة صامتة.",
[2553482582]="أخيرًا! سأكون سعيدًا بالخروج من هذا المكان.",
[2553842443]="حلفاؤنا الجدد سينتقمون لنا!",
[2554215043]="جيش النايت إلفز تم دفعه للخلف عبر أنغورو، إلى حدود صحراء تاناريس. شيء في أنغورو منع الكيراجي من السيطرة على الأرض. لا أفهم هذه الكلمة تمامًا لكن أعتقد أنها تعني 'أراضي الآلهة'. يُذكر أنهم لم يستطيعوا 'أخذ أراضي الآلهة'.",
[2554726855]="ستنفذ الأوامر. مينافورج دورو تعرض لهجوم عنيف من مخلوقات المانا والوضع خارج السيطرة. عدم الامتثال لن يُتسامح معه!",
[2555116656]="بالتأكيد.",
[2555128179]="هل نحن متحمسون للموت لهذه الدرجة؟",
[2555450717]="%s يطير بعيدًا.",
[2555990289]="يا إلهي، دعني أغير هذه الضمادات!",
[2556157069]="فتاة ذكية...",
[2556165221]="هي! أين تظن أنك ذاهب، تتسلل هكذا؟",
[2556229827]="تحذير! تحذير! إنذار دخيل! إنذار دخيل!",
[2556591570]="وحوش صغيرة قبيحة، صلوا ألا أخرج!",
[2556774118]="يبدو أن إبرة النبض الخاصة بك عملت بشكل مثالي. بالتأكيد لدى غوراموش الآن وقت للحديث أكثر عن الاتفاق المقترح؟",
[2557327724]="سأراقبك أنت وحلفاءك، $R.",
[2557338952]="قل مرحبا لصديقي الكبير!",
[2557410448]="الدخلاء ممنوعون!",
[2557453497]="موتي لا يخدم إلا تعجيل نهايتك.",
[2557793982]="ثم تضع الفلفل في القدر...",
[2557811053]="أيتها الأرواح، نحن مجتمعون هنا لنطلب إرشادك.",
[2558014232]="تحطم... أنت....",
[2558363793]="ليدي فاشج يجب أن تتحمل مسؤولية هذه الفظائع. يجب أن تُحاكم!",
[2559026220]="لا أستطيع فعل هذا وحدي...",
[2559072914]="نورث ويند؟ لا يزال يزعج شعبي؟",
[2559080584]="بالتأكيد، لكنك لن يعجبك الأمر.",
[2559667297]="من الحماقة إغضابي!",
[2559799037]="قطفت ناضجة من الكرمة.",
[2559926241]="بافال ريثي! وجدتك أخيرًا. وتتسكع مع الأوغرز الآن؟ لا تخف، حتى المنشقون والخونة يحصلون على بعض الرحمة.",
[2560137765]="أعرف ما تقصده... يهمسون عنا عندما يعتقدون أننا لا نسمعهم. سينالون جزاءهم.",
[2560494882]="سيتم تعزيز دورو! كانت أولتريس كارثة كاملة. لن أسمح بتكرار ذلك الخطأ!",
[2560630266]="إي دي - 210 متصل!",
[2560873866]="وا... أين أنا؟ ضعيف جدًا..",
[2561023005]="قادمًا من جبال بليدز إيدج يأتي روكدار الـساندرد لورد! $N على وشك خوض معركة $Gحياته:حياتها;.",
[2561322055]="دع لفائف الكره تنفرج!",
[2561443105]="هنا، على حدود مملكته بالضبط، ستختبر قوة لم تتخيلها أبدًا!",
[2561537443]="هذا الموقف برمته يبدو مريبًا بعض الشيء، ألا تظن؟",
[2561726594]="لا يمكنني الخروج بدون عباءتي. أتمنى أن تكون هنا...",
[2562282947]="%s يستدعي كريات مائية!",
[2562504137]="رماد إلى رماد، غبار إلى غبار!",
[2562519268]="النصير لي!",
[2562712652]="لا جدار يمكنه حبس الـ بانشي كوين. أبقوا الأنديد بعيدًا أيها الأبطال. سأهدم هذا الحاجز!",
[2563311749]="استيقظ أيها المخلوق الصغير. استيقظ من سباتك... أنت بأمان الآن.",
[2563382144]="حان وقت العمل. يجب أن نقرر كيف نتعامل مع الـسكورج قبل أن يلتهمنا.",
[2563502071]="جهودك تجبر %s على الخروج أكثر من العالم المادي!",
[2563579929]="شكرًا لك، $C. أتمنى أن توصلك الرياح والبحار بسلام دائمًا.",
[2563871668]="أتعلم، أعتقد أننا نستطيع ضرب هونر هولد من هنا.",
[2564276208]="هو ملكي الآن...",
[2564283076]="حاربوني وموتوا أيها الجبناء!",
[2564527328]="لا أمل. ستفشلون.",
[2564729545]="كمين!",
[2567018510]="لماذا لا نتعامل معك الآن، هيندل؟ ستتحدث إليك ليدي براودمور لاحقًا في البرج.",
[2567687621]="لور'ثيمار يجب أن يسمعنا! لن نسكت!",
[2568169446]="يذبحون السجناء! أسرع، ساعد الباقين.",
[2568339189]="كان مقدر لك تفشل.",
[2568521946]="لست... متأكد إنها فكرة زينة، 'موك. يمكن تتأذى...",
[2569219538]="أرواح الهواء سمعت ندائي. ستنزلنا السايكلونز بسلام. الآن نقفز!",
[2569379749]="هذه مفاجأة، ثاساريان. ما سمعت من موغراين أو الديث نايتس الآخرين من شهور. جئت ترجع للـسكورج، صح؟",
[2569821144]="سمعته، يا مسافر. كلمني مرة ثانية لما تكون جاهز تكلم بلغروم.",
[2570205544]="نعبر الكون، بعدد النجوم!",
[2570404423]="استمتع بصحبتهم، الـليتش كينغ يرسل تحياته!",
[2571198223]="هذه هي العلامات المميزة...",
[2571213499]="الكل يحيي $N، منقذ أزورمايست وبلودمايست. بطل يد أرغوس، بطل شعب الـدرايناي!",
[2571336943]="كفى! الآن ستشعرون أيها الحشرات بقوة ميراثي، غضب الأرض نفسها.",
[2571345459]="لم يعد هناك وقت لي. لقد انتهيت. أنهِ أمري، $N. افعلها وإلا سيقتلوننا كلينا. $N... تذكر مولقور. هذا العالم يستحق الإنقاذ.",
[2571699831]="عندما يدرس المرء ويحفر، يكشف الحقيقة.",
[2572119123]="أطعموني، يا إخوتي!",
[2572679362]="من يحتاج آلهة ونحن آلهة؟",
[2573018359]="أقدم حضنة تنانيننا لا تزال بعيدة عن النضج، لكن بالصبر والدراسة، نحن واثقون أن تنين الطيران سيكون جاهزًا قريبًا.",
[2573222638]="يتجلى كشعور، صغير في البداية ويسهل تجاهله، يؤكد الحقائق ويحث المرء بلطف على فعل الخير.",
[2573452303]="آرررر... حراس!",
[2574611210]="انهض، وابتهج بشكلك النقي!",
[2574656486]="$Gسيدي:سيدتي;، حياتي فداء للهورد!",
[2574809782]="كن في راحة.",
[2575138108]="سمعت أن نورثريند ضاع...",
[2575868031]="حان الوقت!",
[2575995135]="الأفكار النجسة تؤدي إلى أفعال دنيئة.",
[2576414484]="ابتعد عن... أنا!",
[2576511988]="إنه فقط...",
[2576570506]="استعد لشيء... أكبر... بكثير!",
[2576690571]="الملك منح النصل لصديقي، ثالورين داون سيكر.",
[2577093544]="أجل، أجل. همم، يبدو أنه يشير إلى كتاب آخر. أعتقد أن عليّ إيجاد ذلك أيضًا.",
[2577202879]="%s يتقيأ.",
[2577231867]="ماذا... ماذا فعلت للتو، $N؟! بران! براااان!",
[2577883794]="لقد خُدعت، أيها الأحمق.",
[2577939235]="هل أنتم جائعون أيها الخنازير؟ لدي بعض الطعام لكم...",
[2577984967]="هذا لم ينتهِ بعد...",
[2578156567]="لكن الآن، موتك سيكون كافيًا...",
[2578743124]="الجميع يموتون! ساعدونا!",
[2578858280]="حفيدي، هل... هل ستخبر قاروش بما أخبرتني به عن والده؟",
[2579125532]="تعزيزات من الفورسيكن؟ أندرسِتي مشغول بالـسكورج من كل الجهات. لا، هذه المسألة سيتعامل معها البلود إلفز بشكل كبير. نحن الفورسيكن هنا كدعم ومستشارين.",
[2579270921]="لن تأخذني دون قتال!",
[2579324105]="عندهم إمدادات محدودة في هذا المخيم. سيكون من المؤسف حقًا لو حدث لهم شيء.",
[2579559920]="وخمور شينديغر أيضًا! الحمد للايت! كنت عطشان!",
[2580275261]="انتبهوا، الـغريم توتيم علينا!",
[2580324092]="آه، \"استحضارات السحرية لأرشميجز دالاران.\" رائع.",
[2580663361]="هل انتهينا بعد؟",
[2580927628]="آه، شكرًا جزيلاً. سأتركك للمكتبة بينما أتولى هذا الأمر الصغير.",
[2581164073]="إنه الـهاي لورد!",
[2582034692]="لازم نعمل شي بحق قبيلة بلاك وود.",
[2582284067]="الآن سأعد لك حتى الرقم 3 لتخرج من هنا قبل أن أطلق الكلاب عليك.",
[2582537371]="لقد قتلتني والآن سأقتلك... مرارًا وتكرارًا!",
[2583128223]="أنا بالقاراس الـ فاول. وأنت، $N، على وشك أن تصبح لا شيء سوى رماد وغبار.",
[2583607298]="%s يملأ وعاءً بالسم.",
[2583934040]="أرى أنك أضعت ذلك الفصل الذي عملت بجد لتجميعه، $N. حسنًا، لقد تركته هنا!",
[2584169750]="الآن إذا انتقلت إلى الصفحة 34 في كتابك، سترى رسمًا توضيحيًا لدوارف يخضع للتشريح...",
[2584511264]="حسنًا، كما قلت؛ سيستغرق الأمر بعض الوقت قبل أن نجهز هذه السفينة للطيران. سنبقيك على اطلاع.",
[2584805743]="أوه، توقف عن الأنين!",
[2585815191]="هذا لا يمكن أن يكون!!",
[2586670408]="أنا متأكد من أن ثرال سيسيطر على شعبه...",
[2586875356]="راقناروس؟ أخبار سيئة بالفعل...",
[2586971129]="هذا كان نهاية سعيدة، أليس كذلك؟",
[2587147789]="توسل من أجل حياتك. استجدي. لن ينفعك ذلك!",
[2587460229]="النهاية قريبة! ذاك الذي لا يجب تسميته على وشك التحرر!",
[2587840667]="آيايا! يومًا ما سأحصل على ذاك البوميرانغ...",
[2587896434]="كما ترى، شعبك أصبح الآن ملكي. سأحول هذه المدينة بيتًا بيتًا، حتى ينطفئ شعلة الحياة... إلى الأبد.",
[2588383570]="أووووووووووووووووووووووو!",
[2588505615]="من أجل الثين! من أجل لوكين!",
[2588866064]="هل لاحظت يومًا أن كل أطفال الأوركس اللطيفين يبدون متشابهين؟",
[2589163758]="%s يلقي تعويذة على تيريون.",
[2589324051]="تم اختراق الحجرة! الأثر التايتنزي أصبح عرضة للخطر!",
[2589436252]="أحسنتم أيها الجنود! استريحوا!",
[2589470857]="سأكون سعيدًا بذبحهم باسمك! تعالوا يا أعداء الـسكورج! سأريكم قوة الـليتش كينغ!",
[2589637292]="%s يتوقف عن التظاهر بالموت ويندفع إلى الأمام!",
[2589781437]="رحلتك بدأت للتو أيها الأمير الشاب. اجمع قواتك والقني في أرض نورثرند الجليدية. هناك سنحسم الأمر بيننا. هناك سيتكشف مصيرك الحقيقي.",
[2589927677]="ما عندك شي!",
[2589971764]="أتذكر آخر مرة حدث فيها هذا، أليس كذلك؟ دعنا نأمل ألا يحتاج السيد للتدخل.",
[2590092501]="واو! زي ما كان بابا يقول، بس نوسع المكان لكي نضيف زيادة! هيه.",
[2590218434]="ماذا يا أورباز؟ إنه بلود إلف؟",
[2590237845]="ها هي ذي يا $N. بداية نهاية العالم. وأنت هنا لتشهدها...",
[2590464803]="لا تموت علي أيها الفنديكيتور!",
[2591464133]="حلمت لسنوات بالتجوال في قاعات التايتنز. ما توقعت أبدًا إني أكون ضد مخلوقاتهم.",
[2591774894]="كلنا المجتمعين هنا عندنا مفهوم القتال الشريف. التصرف بشرف ومعاملة خصمك كما تحب أن يعاملوك يظهر الاحترام.",
[2592046079]="انتزعته من بقايا ملازم أورك - ساحر ظلامي... إنه من عالمهم الأصلي.",
[2592326760]="بما إني سوف أكون سكورج على أي حال، يمكن أسكر!",
[2592337941]="الأقدار انقلبت ضدي!",
[2592712846]="استنى لين جوريجيك يجهز.",
[2592817996]="أسهل مخلوق يمكنك استدعاؤه هو الإمب. ينبغي أن تكون قادرًا بالفعل على إحضار هذا التابع، لكن من باب الاكتمال سأبدأ به.",
[2593413576]="عديم الفائدة...",
[2594011702]="يا معلم...",
[2594068783]="بدي أشوف هيكل التنين في المكتبة الكبيرة.",
[2594426004]="أكوانوس، توقف عن إرسال الملابس عاليًا جدًا! ما كان لازم تشوف ماذا صار في وجه أيثاس سنرايفر لما لقى بنطلونه في النافورة!",
[2595495493]="حسنًا! لقد هُزمت. أرشميجك الثمينة محتجزة في سجن مرتفع ومختوم. حتى لو تمكنت من الوصول إليها، سالراند نفسها تملك المفتاح. مهمتك حمقاء!",
[2596001611]="خيانة؟ هل فقدت عقلك، آرثاس؟",
[2596078801]="لا مزيد من التردد! مصائركم محتومة!",
[2596495541]="سأعلمكم جميعًا ما يعنيه أن تكونوا جنودًا حقيقيين!",
[2596703086]="أررررررررررررررررغ!!!!",
[2596823199]="بقايا %s تسقط على الأرض.",
[2597149418]="إذا كنت تنوي تحرير مايزريل، فستندم!",
[2597435451]="سيدي، أنقذني!!",
[2597731625]="كيف تسير مراقبة البراميل...؟",
[2597820647]="شكري لك أيها البطل!",
[2598647388]="لا يجب أن نخذل السيد.",
[2598820051]="الـلوش ملك لقبيلة ستونزبلينتر الآن، $N! والآن مت!",
[2599116674]="هم ببساطة يخافون مما لا يستطيعون فهمه.",
[2599221124]="عناق... أخير.",
[2599979221]="ثورنلينق نما إلى الحجم الكامل!",
[2600424062]="هاها! أمزح فقط. سنأكلك على أي حال!",
[2600763532]="ورشة حصار إيستسبارك تم الاستيلاء عليها من قبل الأليانس!",
[2600973667]="يجب أن تتذكر أنني لم أنضج بعد لثعبان عجوز. يجب أن آكل لأستعيد قوتي!",
[2600981097]="حسنًا، سأخرج لأتفقد. هناك شيء خطأ.",
[2601268500]="من يجرؤ على استفزاز رسول إدوين فان كليف؟ مت $R!",
[2602224657]="تعالوا! تعالوا إلى موتكم—إن كنتم تجرؤون!",
[2602502732]="تلك البحيرة القريبة مليئة فعلاً بمخلوقات بحرية. لست متأكداً كيف وصلت كلها إلى هنا... ربلا يوجد الفيضانات؟",
[2603104086]="الجيستس الملعونة! لقد التهمت هذا بالكامل تقريباً...",
[2603146053]="أشعر بوجود الشر يغادر...",
[2603275971]="المسافرون والمغامرون، أسرعوا إلى ساحة البلدة واستفيدوا من أسعار أنطونيو الرائعة! تعالوا جميعاً!",
[2603431718]="بالنظر إلى مستويات الطاقة هذه، كان شافار على وشك تحقيق ثروة!",
[2603436173]="خذوا رؤوسهم! من أجل الـهورد!",
[2603755886]="سآخذ هذه. لا يمكننا أن يكون الزعيم العظيم خائفاً من بضع جلود.",
[2603948160]="استعد السيف، $N، واحمله عبر تلك البوابة إلى دالاران. آرتشماج ايثاس صنريفر سيكون في انتظارك ليهنئك.",
[2604818990]="متأكد إنك جاهز؟ خذ لحظة.",
[2605023822]="%s ينفجر!",
[2605366380]="ما يبدو عليه الحال، بيلي.",
[2606106855]="حان وقت النهوض وضرب الأوركس الفيل المتبقين! افعل هذا من أجل وارتشيفك! افعل هذا من أجل الـهورد!",
[2606149978]="لكننا لسنا شيئًا إن لم نكن شعبًا يسعى للتوازن. محاربونا يقاتلون فقط عند الحاجة. هنترزا يأخذون فقط ما تحتاجه القبائل للعيش، ويستخدمون كل ما يمكنهم عندما يفعلون. الشامان يقفون كمرشدين ووسطاء لأرواح العناصر.",
[2606222727]="أنا لا أهرب منك مثل $C!",
[2606285896]="ذوق فولاذي، أيها $Gولد:بنت; الصغير!",
[2606354047]="لأنها تزرع في الربيع!",
[2606713315]="هجوم اثنان!",
[2607259378]="أيها الفورسيكن الحقير الضعيف. تريد رؤية سيدي؟ فليكن.",
[2607412072]="لقد تدخلت في أمور لا تعنيك. أنت لا شيء سوى غازٍ أجنبي. استعد للموت!",
[2608073185]="لم يعد تتنفس؟ جيد.",
[2608447356]="حسنًا... أعتقد أنني سأراقب الأبراج... أو شيء من هذا القبيل.",
[2609466790]="لماذا أتيت إلى هنا أيها الغريب؟ لن تجد سوى الألم! مصيرنا سيكون مصيرك...",
[2609548262]="أسطول القرمزي يتحطم على الساحل الممزق!",
[2610068824]="هذا مثال على ما لا يجب استدعاؤه. انظر، إنه ضعيف وهش. ضربة واحدة قوية من صولجان ستطير شظايا العظام.",
[2610592635]="الأمور غير مؤكدة الآن بعد أن أصبحت الحجرة السفلية فارغة...",
[2610614727]="ولا ترجع!",
[2611044471]="لقد عدت!",
[2611200679]="ليديز وسادتي... تجمعوا حول الحفرة!",
[2611739609]="الخيار لك يا أنسلم. ارجع إلى جيش الـليتش كينغ وقاتل بجانبهم أو ابقَ مخلصًا لملكتك المزعومة وواجه غضبهم وهم يطردونك من أراضيهم!",
[2612575494]="الطوق مشبع بقوة شيطانية يا $N. هذا نذير شؤم لشعبنا.",
[2612682274]="أعداؤنا سيسقطون!",
[2612883984]="لا أحد أفضل مني!",
[2613528769]="تحاول إبعادي عن حضنتي؟ ستدفع ثمن وقاحتك!",
[2614205876]="التاورن من ثندر بلف يهتفون لـ $N.",
[2614353824]="أيها الملازم، أريدك أن تجعل هذا أولويتك القصوى. أبلغ أي شخص تعتقد أنه يمكنه المساعدة.",
[2614958352]="مخلوقات صغيرة تحت الأقدام، تجلبون لغارفروست شيئًا لذيذًا ليأكله!",
[2615166515]="إذن هذه ملكة التنانين؟ همم... كنا نظنها أكبر. نعم، كنا نظن.",
[2615168875]="لذيذ جدًا! مليء بالطاقة!",
[2615323785]="زهقت من مشروبات الساحرات الضعيفة؟ جرب حاجة أقوى في بيغ أند ويسل!",
[2615370394]="ثقتك الزائدة ستكون سبب هلاكك! حراس، أعطوني قوتكم!",
[2616660865]="%s يضع الصدفة على أذنه.",
[2616694310]="رسالتي للوحدة موجهة لعشائر أوقر، ليس لك يا $R!",
[2616756476]="واحد من اشعاري كريستالز دُمّر! اقتلوا المتسللين!",
[2616911721]="ليتني قدرت أوقفك ذلك اليوم، كيف كانت الأمور ستختلف.",
[2616912360]="لا--كاو، كاو--اهربوا...",
[2617136377]="هاه... أين نحن؟ هذا ليس صحيحًا. لم أقل لك أن تعثر على هاردنكلز، أليس كذلك؟",
[2617603917]="موتكم يغذي قوتي!",
[2618005990]="%s يستمع لـ$N وهو يحكيله عن مغامرات $Gخاصته:خاصتها; في بادلاندز.",
[2618110880]="ساعدوني يا نسلِي!",
[2618589366]="أتسمع ذلك يا جيثان؟ لن تحصل على جائزة ستيلفيذر الآن بعدما عرفنا أنها أم.",
[2618966786]="أه، صحيح! من هنا الآن...",
[2619852385]="اشحنها!",
[2620902799]="%s يبدأ بتوجيه طاقته السحرية إلى تعويذة قوس قزح قوية.",
[2621087103]="مذهل، هذا يتوافق مع نظريات أن أونغورو كانت موطن التايتنز عندما سكنوا كاليمدور. ربما كان أمانثول نفسه يراقب 'أراضي الآلهة'.",
[2621133531]="نأمل أن تصل التعزيزات من ستورمويند قريبًا...",
[2621712057]="أوه لا! بعض الجراء-البشر تبعونا!",
[2622218649]="حيث سقط العاشقان، ستزهر شجرة. النايت إلفز يسمونها قلب الخشب. ستخدم أغراضك بالتأكيد.",
[2622522370]="أضف موز!",
[2623031986]="هورد مزيف يتجرأ على اقتحام حصني لهذه الدرجة؟ أحضروا سجناء ثرالمار واستدعوا الجلاد! سيدفعون بحياتهم ثمن هذا التعدي!",
[2623445958]="لا، ما زال مكسورًا. لا حظ لي على ما أظن.",
[2623819641]="قد يكون هناك خطر في كل زاوية هنا.",
[2624492858]="ثارون'جا لديه استخدام لقالبك البشري!",
[2625444487]="لقد ارتكبت خطأً فادحًا أيها الشرير!",
[2625736469]="سأجعل موتك سريعًا، $N.",
[2625977493]="لا أستطيع تقييم الرياضيات وراء شحن التوربوسترايدر بدقة مع الحفاظ على رمحي بالزاوية المطلوبة ودرعي في المكان المناسب لأقصى حماية في أي لحظة!",
[2626332498]="النجدة! قتلة جاءوا لقتلي!",
[2626571657]="هل تشعر بيد الموت الباردة على قلبك؟",
[2626572823]="هذه المنطقة ستدمر نفسها خلال دقيقتين.",
[2626754185]="إذاً، الأوراكل قررت مساعدتك أيها الغريب. حسنًا، سأقدم لك ما أعرفه.",
[2627415320]="إن التحكم بعقل الضعفاء أمر تافه... فأنا أبايع قوى لا تمسها الزمن ولا تحركها الأقدار. لا توجد قوة في هذا العالم أو خارجه تستطيع أن تجعلنا نركع... ولا حتى الـليجيون العظيم!",
[2627471118]="ما أريده من كل واحد منكم هو تفتيش دقيق لكل محطة وقود، مسكن، مستودع، مزرعة، حظيرة دجاج، مرحاض خارجي وبيت كلب في هذه المنطقة.",
[2627645812]="إلى الأمام! سننهي هذا الآن!",
[2627871620]="الموت للأحياء!",
[2628203874]="اقتل $N!",
[2628534561]="يجب أن نذهب إلى مونقليد لنرى مهرجان القمر العظيم للدرويدز.",
[2628604559]="كريبتا!",
[2629457617]="يجب أن ندافع عن صنويل من العدو بأي ثمن.",
[2629689690]="أيها الحثالة الملعونون!",
[2630144032]="دخيل!",
[2630298636]="دافيل لايت فاير استسلم لجروحه!",
[2630483152]="القوة تتدفق فيّ! أرى... كل شيء!",
[2630518079]="ظننت أن لديك فرصة؟",
[2631123528]="أعرف المكان المناسب. هل ستكون بخير؟",
[2631522792]="أنت رائع! سأتأكد من العناية بالشعاع جيدًا.",
[2631579089]="انظر ماذا فعلوا بابني.",
[2632022666]="هيا بنا يا فتى.",
[2632609899]="تأمل وجهي المخالب المجنون وايأس أيها الأزيروثي!",
[2632679601]="خذ هذه البركة وأرِ هؤلاء الدخلاء طعمًا من قوة السيد!",
[2632807134]="أوه حقًا؟ وما قد يكون ذلك؟",
[2632811899]="آسف جدًا لمغادرة الزبون ولكن لدينا أماكن نذهب إليها وأشخاص نخدعهم. سنعود في وقت لاحق اليوم. وداعًا!",
[2633549370]="آسف، لا أستطيع التحدث إلا بالشيطانية.",
[2633763266]="أرجوك! يجب أن أتغذى على شيء قريبًا... بلورة مانا... شظية... أي شيء! الألم لا يُطاق!",
[2633819630]="لنبدأ العمل، $N!",
[2633963036]="كم تعتقد أن سحرك الحقير يمكنه أن يمسكني؟",
[2634537700]="تسمع هديرًا منخفضًا من مكان قريب.",
[2634915113]="سندمرك أيها المخلوق الحقير!",
[2635069710]="لقد مللت منك. ارحل!",
[2635241881]="كدنا نعود إلى راتشت! لنحافظ على الوتيرة...",
[2635491362]="لن تدنس هذه الأسرار!",
[2635712974]="%s يرفع يده ثم يخفضها.",
[2635849882]="جاينا؟ لماذا تبكين؟",
[2635975473]="%s يحطم المخلب الميت المعوج.",
[2636023181]="التنين الأسود ظهر من العدم، وانقض علينا قبل أن نتمكن من الرد.",
[2636535520]="يتصفح %s أكوام الكتب واللفائف على الطاولة، ويبدأ في فحص إحداها باهتمام.",
[2637279461]="%s يحول العناصر التي أعطاه إياها $N إلى طوطم تطهير...",
[2637775869]="أيتها الأم! هل سيأكلنا ذلك الرجل الشرير؟",
[2638123257]="الـليتش كينغ يقول ليخبرك... مُت!",
[2638282196]="%s يرمي تفاحة فاسدة على $N.",
[2638494128]="نحن نحارب لمجد يميرون! نموت باسم الـليتش كينغ!",
[2639428876]="ديستركتيف وارد يزداد قوة.",
[2639860302]="مت باسم الظلام ليدي، $N.",
[2640438890]="سلوكك لن يُتسامح معه.",
[2640907866]="أيها السائق، سمعت أنك وحدك نقلت قرويينا جواً من هذا الجحيم. هل هذا صحيح؟",
[2641817341]="أخيراً! لقد جاء بطل!",
[2641843869]="صحيح، إنه بجانب السرير. هه، آسف على ذلك!",
[2641926435]="%s يقوم ببعض الإيماءات الغريبة.",
[2642133989]="خذ راحتك.",
[2642265224]="لا مزيد.",
[2642505008]="فالريك. ماروين. أحضر جثثهم إلى حجرتي عندما تنتهي.",
[2642603490]="الجواب سيكون نعم إذا أخرجتني من هنا.",
[2642616598]="أيها الحقير البائس!",
[2642620071]="أنت تعرف ما يقال عن الفضول...",
[2642804492]="سيدي، ضيفك وصل. إنه ينتظر حضورك.",
[2643131712]="اترك هذا المكان!",
[2643855847]="أخيرًا، انتهى نفيي!",
[2644245897]="شين دابيري، لي، أليكس تي، روب إف، جاي إيه بي، إيه مايبيري!",
[2644926448]="لقد انتهيت من الطلب بلطف، يا رجل السمك.",
[2645011874]="بصفتنا أوصياء على الزمن، نراقب ونعتني بعالم نوزدورمو. السيد غائب في الوقت الحالي، مما يعني أن هناك محاولات جارية لتغيير الزمن بشكل جذري. السيد لا يتدخل أبدًا في شؤون البشر، بل يصحح التعديلات التي يقوم بها الآخرون على الزمن. إنه رد فعل في هذا الصدد.",
[2645132101]="البرج الشرقي فروست وولف تم الاستيلاء عليه من قبل الـهورد!",
[2645388773]="ساميا، هل تعرفين من هو كولفيس داركسكيل؟",
[2645569163]="تحت سقفي، أيها السادة، أثق أنكم ستتصرفون بلباقة.",
[2645672516]="سعيد برؤيتك بخير يا هارلان. وآمل أن أراك قريبًا مجددًا...",
[2646619997]="%s يلبي نداء شاي روتام.",
[2647162753]="رداؤك اكتمل، $N.",
[2647397417]="ظننت ذلك!",
[2647958639]="احموا المدينة بأي ثمن!",
[2648088542]="عد إلى الظلام البارد!",
[2648450969]="على الأرجح ليقوم بالأعمال الشاقة.",
[2649185713]="رائع!",
[2649257613]="ما معنى هذا؟!",
[2649492250]="أجل، هذا سيساعد دراستي بشكل جيد...",
[2650010819]="تروك هل أنت جائع؟ أنا أحضر بعض الطعام لنا!",
[2650010836]="من هذا الذي يقرع طبلي؟",
[2650046572]="كيف تجرؤ على التدخل؟!",
[2650225936]="$Gبابا:ماما;؟",
[2651045909]="لقد مللت من محاولتك لشفاء الأرض وتهدئة الطاقات التي تستدعي وتجنن العمالقة. قولياثون، ملك العمالقة، الأمير كيل'ثاس وأنا نطلب منك الدفاع عن البلورة!",
[2651500682]="انفجار قادم بعد 10 ثوانٍ!",
[2651522473]="الآن هذا يبدو مألوفًا. إذا واصلنا التوجه شرقًا، أعتقد أننا نستطيع... آه! هجوم الويفرن!",
[2651657042]="هل يجب أن تتبعني في كل مكان؟ <تنهيدة>",
[2651771565]="اللعنة عليك!",
[2652586357]="يا إلهي! ما هذا؟ النجدة!",
[2652734790]="مع الظلام المقترب يأتي نهاية الـسكورج. ستقاتل مرة أخرى! من أجل الـسكورج! من أجل الـليتش كينغ!",
[2652908894]="إذا سقطت في الهاوية، سآخذكم جميعًا أيها البشر معي!",
[2653339775]="إلى أين أولًا؟",
[2653475052]="العرض يجب أن يستمر!",
[2653577844]="شكرًا لتحريرنا، أيها البشر. احذروا، الدرع الزرقاء علمت بوجودكم. حتى الآن، ماليقوس يرسل فاروس كلاودسترايدر وحراس خاتمه للدفاع عن الأوكيولس. ستحتاجون مساعدتنا لتكون لكم فرصة.",
[2653654140]="إذا سمحت لي بواحدة فقط...",
[2653666155]="موتك لن يذهب سدى، تايلان. نظام جديد يولد اليوم... نظام سيكرس نفسه لإطفاء الشر الذي يبتلي هذا العالم. شر لا يمكنه الاختباء وراء السياسة والمجاملات.",
[2653719464]="رغم أنك مضطر، إلا أن الخيار، والخطوة الأخيرة قبل القفز، هي لك. لديك عشرون ثانية إضافية لتقرر.",
[2653733040]="هذا يعني حربًا!",
[2655215061]="لن تذهب إلى أي مكان الآن، أيها الوسيم. ليس حتى تستعيد قوتك.",
[2655710768]="ربما سنكون حلفاء قريبًا.",
[2656063330]="سيتعفن لحمك أمام عينيك!",
[2656091549]="أوغلين أو بيجور!",
[2656182309]="حسنًا... كنت أفكر فقط... أنت أصغر قليلًا، لذا احتمال تفجيرك لأي من تلك الألغام أقل.",
[2656396557]="لن نظهر لأعدائنا أي رحمة!",
[2656655137]="هل سيضطر قوثيك الـ هارفيستر إلى خنق شبح؟",
[2656669388]="إذن، هل سترفع هذا الأمر إلى الشيخ؟",
[2658126298]="آفة عظيمة تنتشر في أرضنا! إنها تنمو كل يوم. حاجتنا للسحر تضعفنا، وستقودنا إلى الدمار، كما حدث من قبل!",
[2658995118]="ها ها ها.",
[2659152795]="إيلث فواه، أون'أغث فشش زا.",
[2659770107]="%s يبدأ في فتح بوابة الشفق!",
[2660144234]="سأنزل إلى هناك وأقتلك جيدًا، $R!",
[2660315310]="جيشك....",
[2660406072]="*إنذار* عطل في نظام الدفاع الثابت. تم تعطيل الدفاعات المدارية.",
[2660808074]="أنت على صواب؛ يجب أن نركز على الـسكورج. تجاهل الترولز والقرى، وركز اهتمامنا على ديثولم! بهزيمة دار'خان ستجد أن باقي 'جسد' الـسكورج سيسقط بسرعة، بفقدان 'رأسهم'.",
[2661814304]="أعتقد أن هذا كل شيء إذن. هيا بنا.",
[2662214345]="إلى السلاح، أيها الكسالى! لدينا زوار!",
[2662227300]="سوبريموس يضرب الأرض بغضب!",
[2662515054]="لقد أُطلق سسوف الموت المتجسد في العالم مرة أخرى! تيرون قورفييند قد عاد...",
[2663383092]="ثارون'جا يرى كل شيء! أعمال البشر لن تنهي السلالة الأبدية!",
[2664062520]="%s يبتسم لـسينتينل أمبرلاين عبر المخيم، ويهز حاجبيها الطويلين بشكل موحي.",
[2664405501]="مهلاً، مهلاً يا صديقي. لحظة واحدة...",
[2664593178]="ماذا يحدث هناك؟ لماذا يستغرق الأمر وقتاً طويلاً، $N؟",
[2664948386]="أنا غاضب. رااااه!",
[2665420711]="صصص. ناوهاين. لماذا لا يزال مودورو يرتدي تلك الرداءات السخيفة؟ يبدو مثل فلاح بين الأبعاد خرج من أمن فالي منذ أقل من ست ساعات.",
[2665465172]="احذر الظل!",
[2665598077]="يا أم أوروس المقدسة!",
[2665705144]="أوه، اللعنة...",
[2666282634]="لدي أمور أفضل لأفعلها...",
[2666330054]="هذا للأفضل.",
[2667302521]="لقد انتهى الأمر.",
[2668050783]="بلا نهاية، سعى لكسر إرادتي، لإجباري على خدمته، لربطي بنصله...",
[2668288785]="لا تدعهم يحولونني إلى واحدة من تلك المسوخ!",
[2668482990]="كنا بخير حتى أكلنا من حبوبك المسمومة هذه!",
[2668731691]="ليلحق آلأكير بأعدائي موتًا باردًا سريعًا!",
[2668800754]="سأدمر حملة الأرجنت الصليبية! سأسحق الـسكورج!",
[2669883671]="بدء التحليل...",
[2670071100]="تخلص منه...",
[2670176446]="خبز طازج للبيع!",
[2670876709]="لن أؤخذ بهذه السهولة! دع جدران هذا السجن ترتجف... وتسقط!",
[2670945739]="فولفين بول هرم أون!",
[2671006038]="لا يمكنني السماح لك بالتدخل!",
[2671351183]="أتمنى أن أكون على قيد الحياة لأرى آرثاس ينال ما يستحقه.",
[2671476971]="هذا للأفضل.",
[2671960191]="لقد أعطيتك المعلومات، $R! أنت تضيع وقتك...",
[2672382491]="أين ذهب السيد؟",
[2672616888]="الويل لكل واحد منكم، يا جميلاتي!",
[2672880128]="الحمد للنور على فرصة أخرى. وشكرًا لك، $N.",
[2673016355]="كمين. أعدهم إلى راحتهم!",
[2673057127]="فهمت.",
[2673277371]="العواصف تمنحني القوة!",
[2673662718]="%s يطلق عواءً قويًا.",
[2673932629]="زوجتي وأطفالي مرضى في الفراش بسبب السم الذي بعته لي!",
[2673955279]="لا، أيها الصديق القديم. لقد حررتنا جميعًا...",
[2674790189]="عامل منجم، يا سيدي.",
[2675111732]="السلام مجرد حلم عابر! دع الـنايت مير يحكم!",
[2675465756]="%s يستعد لإطلاق تمكين شادوز!",
[2675940126]="استفسار؟ بماذا تظنني جئت، للشاي والبسكويت؟ قل لي ما عندك فورًا!",
[2676598616]="ربما يومًا ما سيعلمنا $N بعض حيل $Gخاصته:خاصتها;؟",
[2677177324]="آيس بلود بانكر تتعرض لهجوم! إن تُركت دون رد، سيدمرها الـهورد!",
[2677592040]="أركبشوب لاندقرين يجب أن يعلم! آآآآآآآه.....!",
[2677639736]="النور الذي يهدينا. هذه الحركة بدأت قبل مجيئك... نحن... نحن نفعل ما يقال لنا. هذا ما يجب فعله.",
[2677830823]="صولجان السيطرة يتوهج بشدة! استخدمه الآن!",
[2678153612]="إلى بروففيست!",
[2678162509]="لنرمز لصداقتنا المتجددة، لدي شيء يخصك...",
[2678243533]="لنواصل التحرك. لا يعجبني هذا المكان.",
[2678448479]="سأفتقد العرض!",
[2678748906]="غدًا سنبدأ تدريب تنانيننا الواعدة، فلا تنسَ ألعاب المضغ الخاصة بك.",
[2678805783]="قد أضطر للذهاب لصيد ذلك الوحش الحقير الآن بعد أن وُضعت مكافأة على رأسه.",
[2679097963]="%s يبدأ شفاءً هائلًا!",
[2679171628]="الوقوف بهذا القرب من النصل الذي أنهى حياتي... الألم... يتجدد.",
[2679485788]="ياررر! أيها البحار، ماذا فعلت؟! لقد جن! أغلق الفتحات! ارفع الصاري! آررر! كل واحد لنفسه!",
[2679658287]="%s تستفيق من هذهانها.",
[2680319713]="من الضباب والغبار يقترب الكفالدر. اهرب بينما لا تزال تتنفس هواء الأحياء...",
[2680965514]="أيها الأحمق! جوهر الصقر لن يكون لك أبدًا!",
[2681722593]="لست متأكدًا كيف تساعد القراءة. كيكيك لا يستطيع القراءة على أي حال، لكن إذا قال هيمت نيسينقواري، سيحاول كيكيك.",
[2681790991]="قوتي تعود. استمروا، أيها الأبطال!",
[2682153896]="أشعر وكأنني أُسحب عبر الزمن. شكرًا على المساعدة...",
[2682346775]="لقد انتهى الأمر، انتهى بحثك. دع القدر يختار الآن، الشخص الصالح.",
[2683258310]="لي! لي! لي! جيزلوك هو حاكم هذه المملكة! لن تكشف وجودي أبدًا!",
[2683774844]="هذا لا يبشر بالخير. أرسلوا كشافة لجمع المزيد من المعلومات، وابقوا في حالة تأهب.",
[2684239076]="حسنًا، هذا يجب أن يكفي. أعتقد...*هيك*.",
[2684645043]="يحيا دراغونماو! موت أيها التافه!",
[2684792447]="نهايتك قد حانت، يا إلليداري!",
[2684987009]="إذا كنت هنا، فقد يكون هو قريبًا خلفك!",
[2685201077]="هذا ليس سهلاً.",
[2685206417]="آه، جيد. هذه الجراثيم نضجت بشكل جيد. شكرًا لك، $N.",
[2685371039]="دافيل لايت فاير انهزم! داروشاير ضاعت!",
[2686138211]="وقت النوم!",
[2686165108]="أنا مدين لك للأبد. بمجرد أن ننتصر على كيلجايدن، سيكون هذا العالم كله مدينًا لك أيضًا.",
[2686379671]="ضاعفوا جهودكم! كينق يميرون سيستيقظ ثم سيصعد!",
[2686630873]="اهدأ يا سينتينل. لا أسعى لاستخدامه. أنا فقط... أتذكر.",
[2686735043]="ليس بهذه السرعة!",
[2687012453]="%s يغمض عينيه، متذوقًا الحرية للحظة.",
[2687155217]="الـفريكول أشرار ويجب تدميرهم!",
[2687295919]="جوابي؟ ها هو جوابي أيها الرسول الصغير!",
[2687429368]="أي واحد؟",
[2687718163]="الآن، تقدم إلى جهاز النقل. معسكر فورج راث ينتظر وصولك!",
[2688533456]="هذه آخر واحدة أحتاجها لطقم سكاكين نيسينغواري!",
[2689115641]="الديث نايت... إنه مجنون!",
[2689255171]="جعة بلودمول؟ المفضلة عندي!",
[2690333634]="مت باسم إدوين فان كليف!",
[2690415329]="%s يرفع حاجبه النحيل نحو الحراس، وعبوس مستنكر على وجهه.",
[2690603685]="مقبرة فروست وولف تم الاستيلاء عليها من قبل الأليانس!",
[2690646782]="أنكورايت، نحن مشرفون بوجودك هنا، لكني أشعر بالفضول حول ما تعتقد حقًا أنك تستطيع تحقيقه؟",
[2690708003]="اللورد إيليدان سوف... يسحقك!",
[2691293766]="لا داعي لأن تفهم، آرثاس. كل ما عليك فعله هو الموت.",
[2691563553]="بأمر من ديوك لانكرال، قائد فرسان النصل الأبنوسي، قاهر الـسكورج وفاتح خزائن شادو، أُمرت بالانسحاب. ما ردك؟",
[2691914563]="رمال الزمن ستتوقف، لكن للحظة فقط! سأستحضر الحاجز الآن.",
[2692105355]="أفعال خادمك $R تتحدى مكانة $Gخاصته:خاصتها; يا ستورم لورد. جهود $Gخاصته:خاصتها; نجحت في تليين قلوب شعبي.",
[2692300914]="يا للإلهة. وكأن الطبيعة لا تستطيع لمسه!",
[2692379216]="لقد أعدتموني مبكرًا جدًا! ما زلت ضعيفًا... ما هذا! من... لا يهم! مُت!",
[2692937190]="لم تصدر قط مثل هذه الكلمات المتواضعة من ثوريم العظيم. سأبلغ كلماتك إلى دن نيفيليم.",
[2693165771]="ليتك كنت هنا الآن أيها الصديق القديم. كنت ستعرف ماذا تفعل.",
[2693251691]="هورغوس، كابوسك انتهى! الآن!",
[2694426220]="هذا هو الكودو الخاص بك يا تورب!",
[2694475575]="أكره هذا المكان وكل من فيه! سميذرز افعل هذا! سميذرز افعل ذاك! أوه، إذن أنا مزارع الآن، إيه؟ إذن سأضطر لحصد الأشياء، إيه؟ أتمنى يومًا ما أن يصبح هذا المكان كله مقبرة كبيرة وأن يُدفن كل ثرثارين هنا بحق الجحيم!",
[2694710655]="ما تتوقع إني أقول لك كل أسرارى، صح؟",
[2694881759]="%s تموت من إصاباتها.",
[2694893578]="لورد إيليدان، أنا...",
[2695538914]="ما... لم يعد لدي وقت. لقد انتهيت. اقضِ عليّ، $N. افعلها وإلا سيقتلوننا كلينا. $N... تذكر تيلدراسل، بيتنا الحبيب. هذا العالم يستحق الإنقاذ.",
[2695614204]="الرجاء الانتظار بينما أحاول ربط الشظايا معًا لتصبح كاملة مرة أخرى.",
[2697396339]="اسمع مارج، أنا قلت لك لا تزعجني وأنا أشرب...",
[2697496990]="جئت متأخر. لازم أبدأ من الأول من جديد...",
[2698224724]="جهز نفسك. لا تدع الطقوس تنقطع وإلا قد نخسر مريضنا...",
[2698365370]="جهزوا أنفسكم، الأجراس دقت! احموا ضعفاءكم وصغاركم وكباركم! كل واحد منكم سيدفع الثمن النهائي. اصرخوا طلبًا للرحمة، الحساب قد حان!",
[2699051642]="أجل! لا شيء يضاهي الهواء الدافئ والبركة الباردة...",
[2699061213]="حلفاؤنا في الصليبية الفضية وفرسان النصل الأبنوسي اخترقوا البوابة الأمامية لـآيس كراون ويحاولون تأسيس موطئ قدم داخل القلعة.",
[2699443776]="جارفروست يأمل أن يكون السروال الداخلي العملاق نظيفًا. ينقذ السيد من العار الكبير. لوقت لاحق.",
[2700157897]="اخترت الموت.",
[2700309435]="ستبقي الأشرار بعيدًا، أليس كذلك؟",
[2700325087]="هذا لا بد أنه آلم! مخ!",
[2700657668]="%s يرفع كأسه إلى عينه ويتجهّم.",
[2700786994]="%s يبدأ بقراءة الملصق المطلوب.",
[2701214444]="أيها الأحمق! لقد سمحت لهذه الحشرات بالعبث في القلب المقدس؟ والآن تقودهم إلى عريني؟ لقد خذلتني، إكسيكيوتس! العدالة ستقام، بالفعل!",
[2701298407]="أدعو لك الآن، أيتها الروح الضائعة. عسى أن يستقبلك النور برحابة.",
[2701433148]="لا أعرف إن كان بإمكاني المنافسة! الجميع أكبر بكثير!",
[2701964412]="إيليدان يبحث عني. لست بأمان هنا... ولا أحد منا.",
[2702287469]="ماذا؟ أوه لا. لا يهمني ما لديك لتقوله. أنا فقط أستمتع بإلحاق الألم.",
[2702321294]="يجب حماية البوابة بأي ثمن. مزقوهم إربًا!",
[2702409821]="$N، أحتاج مساعدتك مجددًا.",
[2702568602]="$N، كيف حال دابتك؟ الأمور صعبة هناك هذه الأيام؟",
[2702990159]="%s يبتسم بتقدير.",
[2703734721]="أرنا خدعة، رافاندوير!",
[2704613741]="جائع جدًا! لا بد أن أتغذى!",
[2704800565]="مزقوا هذه القرية البائسة!",
[2705468620]="رائع! لننتقل، أليس كذلك؟",
[2705487110]="ها! أنا أفضل صوت قذيفة من مدفع كريتر إكس تي على ذلك في أي يوم!",
[2705834720]="وفر نفسك يا رجل عجوز. قد تكون آخر نفس تتنفسه.",
[2705960059]="هل... هذا صحيح، ما سمعته؟ أن ملك الشمس نفسه هو من فعل ذلك؟",
[2706088232]="مجرد إزعاج بسيط، أؤكد لك! أخبر السيد أن سجينه لن يهرب بينما يراقبها أكاماً وفرق الموت التابعة له.",
[2706227978]="لا يمكنك حبسي رغماً عني! لقد تم غسل أدمغتكم جميعاً!",
[2706319304]="آه، هنا أخيراً! سيكون من الجيد جداً التخلص من هذه البراميل.",
[2706678870]="وليمة الأرواح تبدأ الآن...",
[2706781503]="%s يزداد غضباً وهو يرى حلفاءه يسقطون في المعركة!",
[2706880267]="من أجل دراك'ثارون!",
[2707356482]="هذا يكفي الآن!",
[2707677983]="السرب الثاني جاهز للقتال!",
[2707726737]="لكن يجب أن يحاولوا وإلا ضاع كل شيء. الـدراكاري سيكونون سبب موتهم وموت آلهتهم!",
[2707953942]="استيقظوا، نحن تحت الهجوم!",
[2708090933]="وليمة الفساد انتهت! ماقثيريدون سقط ببراعة قتال $N وحلفاء $Gخاصته:خاصتها;! شاهدوا قوة الأليانس! قائد بت لورد دُمّر!",
[2708556721]="لن يقربني قتلك من إثبات نفسي في فالاهالاس، لكنه سيكون مسليًا!",
[2708650024]="احترق! احترق بنار الصانع!",
[2708791255]="الدودة تذهب على الخطاف، والخطاف يذهب في الماء. فيش في الماء، سمكتنا.",
[2709812960]="كلهم... توسلوا... لأجل... حياتهم!",
[2710253694]="المنطاد إلى أورقريمار وصل للتو! كل من يريد الصعود إلى دوروتار!",
[2710396910]="%s يستمع بينما $N يخبره عن مغامرات $Gخاصته:خاصتها; في بادلاندز.",
[2710942538]="لي-غارديان إريقوس هو كل ما يقف الآن بيننا وبين السيطرة على الأوكيولس. إنه يحلق فوق حزام المحاذاة، في قمة الأوكيولس. إريغوس قوي بشكل لا يصدق؛ ابق على ظهري عندما نواجهه واترك القتال لي.",
[2711425929]="لاحظت بعض النار في تلك الجزيرة هناك. وأيضًا هيومن. دعنا نذهب لنتحقق منها، $N.",
[2711719431]="حجاب الشتاء سيحميكم، أيها الأبطال!",
[2712447913]="الشائعات كانت صحيحة! الأمير قد أصيب بالجنون!",
