[2712929500]="أنا لست هنا لأكون حارس فراخك يا دوريان. أنا أقوم بأبحاثي الخاصة أيضًا.",
[2713388119]="المرة القادمة، ربما يتركك غورغيك تحاول.",
[2713877997]="بران! $N قام بتفعيل نظام الدفاع المداري! إذا لم نغادر هنا قريبًا، سنتحمص!",
[2714027343]="الـهورد استولوا على منجم كولدتوث! إمداداته ستستخدم الآن للتعزيزات!",
[2714214416]="الموت للأوغرز!",
[2714736930]="آيسميست... ليس آيسميست... لا!!! تعال بسرعة أيها البطل! اتبعني!",
[2714744909]="را-آك! حلي، نعم. حلي جميلة! آك! قوة، قوة عظيمة. را-كاو! قوة في الحلي! آك-كاو!",
[2714754654]="زهرة المستنقع تنفجر، راشحة حبوب اللقاح بعنف.",
[2714840167]="أنتم المخلوقات الصغيرة تقززونني!",
[2715832494]="السماء ستظلم وكل شيء سيسكن. حينها فقط ستعرفون سكينة الموت الحلوة...",
[2715936542]="حتى في الموت لن يكون لكم مفر!",
[2716287029]="أتجرؤ على استدعائي؟",
[2716508269]="هذه المنطقة ستدمر نفسها بعد أربع دقائق.",
[2717229440]="حر... أخيرًا.",
[2718450537]="لنجرب هذه...",
[2718619800]="تعال هنا، $R. بالتأكيد لا تريد أن تخاطر بنفسك في دنجن، أليس كذلك؟ عمل قذر، ولأجل ماذا؟ تذكار تافه؟ لا، ما تحتاجه هو واحد من تمائمي. مضمونة العمل!",
[2718665747]="رفاتك حتتغذى عليها أسماك القرش في داغركاب!",
[2718901579]="لا! اتركونا! لازم ما نفشل في مهمتنا!",
[2718918790]="الـسكورج انهزموا! داروشاير انحررت!",
[2719386891]="طيب؟ مين اللي على طرف الإشارة؟ ماذا سيصير؟",
[2719670831]="%s يبدأ برفرفة أجنحته الضخمة أسرع. إنه يستعد للطيران.",
[2719773135]="يا سيدي، نحن مشرفون بوجودك. كيف أخدمك؟",
[2719890840]="أين... أين أنا؟",
[2720048246]="لا راحة... للموتى الغاضبين!",
[2720383774]="جيب حبل!",
[2720487166]="نتعرض لهجوم! اهربوا واختبئوا!",
[2720881145]="أيها البحار، أرِ هذه النملة قوة الكفالدر!",
[2720925607]="كما ترى، لم يبقَ معي سوى القليل بعد أن قبض عليّ هؤلاء المتوحشون، لكن مرحب بك في ما لدي. تعال، ألقِ نظرة.",
[2721825031]="ديريك... مانول.",
[2721963524]="لا أعرف ما الذي يراه بلاك مور فيك. بالنسبة لي، أنت مجرد متوحش جاهل آخر!",
[2721993913]="%s يحمرّ وجهه بشدة مما يسمع ردًا على سؤال سيدته.",
[2722335176]="بوي، لا تستطيع حتى تحضير ساندويتش دون أن يخبرك أحد كيف تفعل ذلك.",
[2722461003]="نعم، يا س... سيدتي...",
[2722797314]="العدو لن يتجاوزنا!",
[2722888614]="فقدت بعضًا من أفضل جنودي في ذلك اليوم...",
[2722935366]="لهبي... أرجوك، لا تأخذ لهبي...",
[2723114031]="مخلوقات بائسة! موتوا!",
[2723596752]="آآآآه...",
[2724443432]="عندي لعبتك! نيا نيا!",
[2725562250]="اصمت أيها البالادن!",
[2726344257]="أنا ممتلئ تمامًا؛ لا أستطيع أكل لقمة أخرى! حسنًا، ربما واحدة فقط...",
[2726962688]="ابق على الطرق. الغابة مليئة بالأنديد.",
[2727396189]="%s يجمع بعض الخضروات.",
[2727574947]="هذا التمثال الصغير يجب أن يحتوي على حجرة مخفية...",
[2727654959]="%s يتغذى على وارب تشيسر المذبوح حديثًا.",
[2727663796]="هذه هي الأوقات التي تجدون فيها أنفسكم متحدين مع النور.",
[2727754302]="مخبأ ستونهيرث تم الاستيلاء عليه من قبل الأليانس!",
[2727836745]="اهدموه أيها الجنود! نحن نشحن هذا الشيء إلى ستورمويند!",
[2727860379]="قبضتك تضعف!",
[2728261204]="...سامبسون، يوريك، تشاملي...",
[2728686063]="حان وقت الانضمام إلينا، $C.",
[2728759542]="أورك عديم الفائدة! فقط انتظر، يوماً ما سأضع شيئاً في شرابك لن تستيقظ منه أبداً...",
[2728782433]="عذاب! ألم! فوضى! انهضوا وتغذوا!",
[2728787451]="لم ننته بعد!",
[2728840839]="أيها الصغار الوقحون، تتجرؤون على تحدّي وأنا على قاعدتي؟ سأسحقكم بنفسي!",
[2728951072]="اذهب وأبلغ أن البؤرة الاستيطانية قد تم الاستيلاء عليها. سنبقى هنا.",
[2730805601]="لا تكن سخيفًا. إلى أين ستذهب حتى لو تركتك؟ لقد انتهينا لتونا من القضاء على حضارتك. أتذكر؟",
[2732038301]="لنخرج من هنا قبل أن تجدنا المزيد من الذئاب!",
[2732082201]="آآآه! إنها تحترق! أي سحر هذا!؟",
[2732706082]="آهآهآه! يجب أن أجد الأسرار!",
[2732868823]="لقد تم الأمر...",
[2732894700]="ابدأوا الطقوس، يا خدمي. يجب أن نعيد هارت أوف هاكار إلى الفراغ!",
[2732906912]="النور يريد ابنه الضائع، سوكرثار.",
[2733764376]="لكما شكري وشكر القرية، رغم أن الكثيرين لن يعرفوا أبدًا بأعمالكما.",
[2733803598]="حسنًا، اسمعوا! شكّلوا دائرة حولي وتحركوا!",
[2734224856]="وكان ذلك إيه! هل رأيت ذلك؟",
[2734368919]="إذن ما رأيك بلعبتي الجديدة؟",
[2734403296]="أنت مخطئ، أدين. ذهني لم يكن أصفى من هذا قط.",
[2734548245]="متعزز؟ ما هي الأخبار السارة؟",
[2734757078]="$C - سألتهم نورك!",
[2734844591]="%s يلقي نظرة على رفاقه.",
[2735080587]="%s يبتسم.",
[2735092675]="قد تأخذ حياتي، لكنك لن تأخذ حريتي!",
[2735853274]="آه، مينيثيل هاربور الجميلة، بأفضل ميد في هذه الناحية من آيرونفورج.",
[2735868053]="أعتقد أن الوقت قد حان لنرى ما وراء الباب قرب المدخل. سأتسلل هناك، بهدوء. قابلني عند الباب وسأدخلنا.",
[2735946625]="بالطبع يا صديقي. كيف أستطيع خدمتك؟",
[2736347669]="تفاديتها!",
[2736414002]="نادل، زجاجة أخرى، وبسرعة!",
[2737298415]="ماذا رأيك؟",
[2737703704]="استعد للتحقق من هوية الحارس ميمير.",
[2737853175]="ليس بهذه السرعة.",
[2738013441]="الألم لا يُطاق.",
[2738468516]="لقد تخطيت عتبة رهيبة، آرثاس.",
[2739116924]="سخرية القدر، أليس كذلك؟ أن تُقتل...",
[2739316468]="أنكرونوس، هذا التشتيت سوف يعطيك ويدرويد الصغير وقت كافٍ لإغلاق البوابة. لا تتردد. الآن، خلنا نشوف كيف يتعاملون مع السحر الفوضوي.",
[2739749689]="دعنا لا نذكر هذا اليوم أبدًا. أعداؤنا كثر. لا يحتاجون لمعرفة أننا نملك هذه القطع الأثرية.",
[2740309979]="أنا أعمى، أيتها الخنزيرة الغبية، لست أصم. لا تفكر حتى في الأمر.",
[2741259369]="لن تذكروني. لا أحد منكما!",
[2741397797]="لديك جرأة المجيء إلى تيلدراسل، أيها الهايبورن. نوعك غير مرحب به هنا. لم ننس حرب القدماء أو العقول التي تقف وراءها.",
[2741794063]="مايف... كيف هذا ممكن حتى؟",
[2742218796]="المزيد من السحر الخبيث! كونوا مستعدين لأي شيء!",
[2742287756]="ريجكلو حر! ترول يموت الآن!",
[2742329229]="استدعاء الدم ينتقل إلى برنس كيليسيث!",
[2743168661]="فكر بصغارنا، غولدان! ستدمرنا جميعًا!",
[2743364294]="%s يصرخ من الانسحاب، فاتحًا بوابات إلى العدم.",
[2743367828]="كل حياة يجب أن تفنى!",
[2743675533]="لذا خدمته... لولاي للم يعدت القلعة المهيبة المرعبة لـناكسماراس إلى نورثرند.",
[2744072070]="الفايكرول يمسك بحلقه بينما يبدأ في الاختناق والتخبط.",
[2744342430]="كان السيد محقًا... في قلقه.",
[2745394033]="المؤمنون سيرفعون، لكن هناك عمل أكثر. سنستمر حتى يقع كل أزيروث تحت ظله!",
[2745539157]="آه، فهمت...",
[2745659439]="جهز نفسك. خيتريكس سيدخل فالهالاس من الجنوب الشرقي. تذكر، لا تغادر الحلبة أو ستخسر المعركة.",
[2745834820]="أوه! رأسي لا يتوقف عن الدوران...",
[2745928014]="أنوبريكان، أحد أعظم أمراء سبايدر في أزجول-نيروب، تم إخضاعه من قبل الـسكورج عندما هُزم هو وقائده السابق أنوبراك على يد ملك ليتش منذ سنوات عديدة. يُقال إنه كان الأكثر ولاءً بين قادة أنوبراك.",
[2746050045]="استسلم أيها الوحش الصغير!",
[2747592160]="مارتنز، ريبلك، أديناي، نايكسون...",
[2747792857]="$N، أنت مصدر إلهام.",
[2747889624]="الوقت حان! لا تتركوا أحدًا واقفًا!",
[2748052465]="حكمك الإرهابي ينتهي الآن! واجهوا مصيركم أيها البشر!",
[2748287512]="قريبًا يا صغيري... قريبًا جدًا.",
[2748850748]="دراغونهوك قادم من الغرب! أسقطوا ذلك $C!",
[2749294456]="لن تهزموا تجمع الحديد بهذه السهولة أيها الغزاة!",
[2749805787]="عصا العاصفة فيوري مسروقة. لعنة على هذه الأرض! العواصف لن تتوقف أبدًا!",
[2750200640]="شخص ما ليقرأ هذا الملصق المطلوب لـقريك. قريك لا يستطيع القراءة!",
[2750405006]="لا مزيد من الأكاذيب يا كويمبي! نريد إجابات!",
[2750614306]="هل تعطلت تلك العربة عليك مرة أخرى يا صامويل؟",
[2750769535]="أخشى الأسوأ يا صديقي القديم. داخل الحلم نحارب عدوًا جديدًا، وُلد من شر قديم. نسل يسيرا النبيل وقع ضحية الهمسات القديمة. يبدو أن نايتماير قد اخترق العالم ويبحث عن مضيف جديد في أزيروث.",
[2750956826]="العينة تم تحديدها كسبيكة من السارونايت والحديد.",
[2751192317]="سأموت وفؤوسي في يديّ مغمورة بدماء أعدائنا!",
[2751242540]="حسنًا، نعود للعمل.",
[2751968374]="حكمة؟ شعبك هو من تسبب في غضب سايروك الذي لا يُحتمل.",
[2751978448]="هل تستطيع حفظ السر يا إد؟ آه، الموتى لا يروون الحكايات!",
[2752014096]="وقتك انتهى الآن!",
[2752015126]="حسنًا، إذن. لنبدأ.",
[2752225190]="المقطرة تحتاج حرارة! أشعل الموقد!",
[2752495278]="لا يمكنك مقاومة القوة!",
[2753235533]="ما يموتون، وما يعيشون. هم خارج الدورة.",
[2753261980]="صحيح، أود أن أذكر بعضًا من هذه 'الألعاب النارية'.",
[2753708719]="تنحى جانبًا لئلا أضيفك كزينة أخرى لدرعي. لقائدك وأنا أمور علينا...",
[2753903921]="انهضوا، جنودي! انهضوا وقاتلوا مرة أخرى!",
[2753966327]="نارو حبسوا بعضًا من أخطر الكائنات هنا في هذه الزنازين. دعني أقدمك لآخر...",
[2754111426]="ميست! خشيت أن لا أراك مجددًا! نعم، أنا بخير، لا تقلق عليّ. يجب أن ترتاح وتستعيد صحتك.",
[2754270968]="البرج الغربي دُمّر!",
[2754327441]="$N، لقد صنعت التوتيم المطهر.",
[2754740652]="%s يُحيي كوماندر أمير.",
[2754827587]="يومًا ما يمكنك أن تصبح سو-دراي سكين. مثل؟",
[2754838407]="أخ... ما هذا المكان؟ هل هذا كل ما تبقى من السفينة هناك؟",
[2755433545]="كابتن برايتصن، $N هنا حررني! $N، أنا متأكد أن الكابتن سيكافئ شجاعتك.",
[2755727441]="انتهيت. الرق جاهز. الآن، عد إلى غورزيكي...",
[2756375037]="%s يجلس ليقرأ ملخص ياجين...",
[2756536906]="المستقبل يحمل الكثير من الموت وعدم اليقين، ليس مختلفًا عن الماضي.",
[2756994435]="والآن كيف سأخرج تلك الوحوش الميكانيكية من حقولي؟",
[2757468087]="تعال، $N. اللورد ستورمريج ينتظر.",
[2757627543]="الماجستير سيقتلني...",
[2758505319]="القوة لـفيل هورد!",
[2758737467]="أي شيء لا تستطيع زبليناتنا نقله يجب إحضاره بالسفينة والسفر عبر طول نورثريند للوصول إلينا.",
[2758743696]="تتحداني في مسكني الخاص؟ غطرستك مذهلة، حتى بالنسبة لتنين!",
[2759174899]="تلك البلدة صغيرة جدًا، طلبت من طفل أن يرسم لي خريطة. رسمها على ظهر ملصق مطلوب من ديفاياس...",
[2759429916]="من فضلك عد إلى زورام'جار وأبلغ عن نجنحن إلى وارسونق رنر.",
[2759445124]="جهودك تدفع %s إلى الخروج من عالم الشفق!",
[2759446411]="هجوم!!!",
[2759491208]="الوورغ ينطلق بسرعة بحثًا عن أعداء.",
[2759643860]="لقد خدمنا جميعًا من عام لآخر...",
[2759745088]="غولدان سيحضر وارلوكسه بحلول الليل. حتى ذلك الحين، عشيرة بلاكروك ستحاول السيطرة على الجدار الشرقي.",
[2759849451]="بايع هاكار والألم الذي تعانيه سيكون ضئيلًا.",
[2759877654]="إحراق الـسكارليت إنكليف سيكون درسًا في التاريخ!",
[2760343967]="أمسكوهم لأطول فترة ممكنة!",
[2760472643]="%s يدخل في نوبة قتل!",
[2760834476]="إلون تباركك، أيها البطل.",
[2761256955]="هل عندك بالصدفة شوربة سلحفاة معلبة من هيلزبراد؟",
[2762467982]="فورًا، يا سيدي!",
[2762526229]="دعني أساعدك بهذه.",
[2762624986]="يجب أن نبقى مركزين على عملنا. بمجرد أن يبدأ الـسانكتوم بالإنتاج بكامل طاقته، سيُجبر سيلفرمون على إرسال المساعدة. الـسانكتومات القوسانية العاملة نادرة.",
[2762748977]="لقد... خنتني. خنتنا جميعًا، أيها الوحش! واجه قوة موغراين!",
[2763241993]="لقد جئت متأخرًا، يا بطل لوردايرون. الأموات سيكون لهم يومهم.",
[2763243015]="ثريسا، خذ هذا إلى فاذر لانكستر.",
[2763906716]="وذكرت كيانًا مسجونًا؟ ما هي طبيعة هذا الكيان وما وضعه؟",
[2764006893]="عند تحضير وجبة التنين، تأكد من تعذيب السجين أمام التنين. إنه يستجيب جيدًا للترفيه قبل الوجبة.",
[2764118395]="ما الأمر، $C؟ هل تظن نفسك أفضل من أن تقف في الطابور معنا؟",
[2764432438]="سأفعلها، يا سيدي!",
[2764444112]="بالكاد أستطيع الإحساس بـغارديان أوف تايم! خطه الزمني يتلاشى بسرعة!",
[2764732685]="رينجي سيخبرك سرًا الآن... $N يجب أن يذهب إلى منحدرات الإطلالة. رينجي أخفى شيئًا في الجزيرة هناك.",
[2764891874]="من أحلك ليل سيرتفع الغراب من جديد، سيحلق في الظلال، سيكشف طبيعة نوعه. استعد لمجيئه، فالمؤمنون سيرتفعون ليحلقوا مع الغراب، والباقون سيُنسون ليمشوا على الأرض، بأجنحة مقصوصة وخزي.",
[2765414208]="إذًا، كيف تنتهي الأمور في آيس كراون؟",
[2765478392]="ماذا فعلت، إسيلين؟ لقد قاتلت بشرف من أجل خير شعبنا... والآن... لقد قتلت ابني...",
[2765572839]="أنا... أستيقظ!",
[2765950101]="ثرال حبس نفسه في الكنيسة. لا يستطيع الهرب الآن.",
[2766235676]="هناك درنة بلو ليف في هذا الخندق! إنها مثل الذهب في انتظار من يستخرجه، أقول لك!",
[2766373519]="البوابة المركزية تفتح!",
[2766861511]="هل توقعت حقًا أن تنجز مهمة موغراين دون معارضة؟",
[2767099347]="تم رصد عدو! أطلقوا النار!",
[2767896132]="القليل من التعذيب الطقسي يمكن أن يقطع شوطًا طويلًا.",
[2768193700]="لابد أن أخرج من هنا!",
[2768593048]="حسنًا $N ها نحن ننطلق!",
[2768672037]="أبكي من أجلك، $N. أنت حقًا لا تدري ما الذي أوقعت نفسك فيه...",
[2769269481]="لا! المصل فسد!",
[2769617215]="يبدو أنني لست فاشلاً بعد كل شيء!",
[2769661583]="روحك لن تجد خلاصاً هنا!",
[2769852315]="أرواحكم الخبيثة ستغذي قوتي!",
[2770676732]="بحق المد والجزر!",
[2770835415]="شكراً لتخليصك من أولئك السيناتورات الحمقى. الآن استعد للقاء حتفك على يد أقوى خادم لـراقناروس.",
[2771397920]="هل بدا ذلك جيداً؟",
[2771450678]="إلى الجحيم بك، ثاساريان.",
[2771992236]="كان يجب أن أعرف أفضل من إعطاء سيلاينا ذلك الكتاب من التعاويذ الصغيرة.",
[2772009234]="بعد ذلك، سأتحدث عن جناح ديث نايت في ناكسماراس. داخل قاعاته الفاسدة، يتردد صدى المعركة ليلاً ونهاراً، حيث يتم إفساد وتشويه أفضل محاربينا ليصبحوا أعظم محاربي الـسكورج.",
[2772324037]="أنا... للأبد!",
[2772343305]="$C اسمه $N؟ ستكون فطورًا لذيذًا!",
[2772469677]="قف ساكنًا وانظر إلى النور!",
[2772545412]="وداعًا لك، ولعل الظل يحميك دائمًا!",
[2772992458]="%s بدأ يصدأ!",
[2773056106]="كفى حركة! قف ساكنًا بينما أفجرهم جميعًا!",
[2773318173]="أيها الأحمق الحقير! خادم ماليقوس يموت قبل أن يساعد عدوًا...",
[2773514513]="أنت فقط تدمر صورة، أيها الأحمق. سأطاردك حتى نهاية الأيام.",
[2773718129]="%s يستهدف $N بمطرقة الصالحين!",
[2773775511]="نعم، تمكنت من إعادة ختم الأثر، $N.",
[2774206517]="باه! هذا لا يثبت شيئًا!",
[2774333711]="يخرج من البوابة كولوسوس، البطل الأعظم لإكسودار!",
[2774727653]="كن يقظًا.",
[2775205202]="الحمد للايت على ذلك.",
[2775553900]="احفظ غضبك! سيطر على حنقك! سيكون لديكم جميعًا متنفس لإحباطاتكم قريبًا.",
[2775720155]="'يا أعظم أبناء الصانع، انهض واطلب حقك بالولادة.'",
[2776437619]="من أجل سباينبريكير!",
[2776578802]="لا بد أنك أكثر ضابط غير كفء قابلته على الإطلاق!",
[2776586429]="اهرول.",
[2776706645]="تبًا لك يا أوثر! بصفتي ملكك المستقبلي، آمرك بتطهير هذه المدينة!",
[2776871038]="تم الاستلام، برانبرونزان. انتهت الجلسة.",
[2777082427]="احموا البوتانيكا بأي ثمن!",
[2777130534]="هذا اليوم سيكون شاهدًا ليس فقط على شجاعتك، بل على حقيقة أنه لا عدو، ولا حتى الـليتش كينغ نفسه، يمكنه الصمود عندما يضع الأليانس والـهورد خلافاتهم جانبًا و---",
[2777131204]="سيتم مسامحتك، إيرانيكوس. إلون ستحبك دائمًا. تحرر من القيود التي تسيطر عليك!",
[2777135877]="أتجرؤ على النظر إلى حشد الأرواح؟ سألتهمك بالكامل!",
[2777164953]="خذنا إلى المعركة، $N!",
[2777364361]="سباق كالوآك فيشينق يبدأ بعد 5 دقائق!",
[2777569231]="يمكننا إزالة اللعنة عنك، لدينا التكنولوجيا.",
[2777961082]="مروع، أعرف.",
[2778456570]="يمكننا جعله أفضل، أقوى، أسرع. لدينا التكنولوجيا. لدينا السحر.",
[2778477237]="يو-هو-هو، وزجاجة من أرواح النومز!",
[2778610886]="ليس متأكد كيف وصل هذا الشيء هنا. ليس مهم لو ميت.",
[2778739105]="ماما، متى هنشوف بابا تاني؟",
[2778983191]="رقم 48. بدأت أبطأ شوي الآن.",
[2779085081]="سنطرد أعداءنا من سيلفربين، ثم نجلب أمواج الحرب إلى عاصمتهم ذاتها!",
[2779855086]="توقف عن نتف شعرها!",
[2780195003]="%s يبتسم، غير مدرك أنها تمازحه، مجيبًا بلغته العامة ذات اللهجة الثقيلة.",
[2780337493]="لا جرعات!",
[2780601161]="هناك شيء أعظم من السحر يعمل في سماء الليل. يومًا ما سيستمعون إليّ...",
[2781465278]="%s يحلم برؤية مروعة. شيء يتحرك تحت المياه العكرة.",
[2781695805]="إذا ما بدأت تلقي لكمات حقيقية، بتنظف إسطبلات الدرايك لمدة سنة!",
[2782237489]="نزل غولدشاير يعلن عن إطلالة على البحيرة...",
[2782344607]="المديح لن يوصلك إلى شيء.",
[2782355928]="%s تمسح النوم من عيونها.",
[2782537309]="فساد الفيل ما ترك أي مخلوق من فيلوود بدون تأثير، $N. أرجوك، كن على حذرك.",
[2782589955]="هذا تكرار، طبعًا.",
[2783565491]="ناديت؟",
[2783601571]="%s تتجاهلك.",
[2784592330]="قطيع من السناجب الميكانيكية يقدر يحفر أسرع منك!",
[2784908327]="بدء تحليل حالة المراقب هودير.",
[2785206780]="القالون الـ أوبزرفر، نذير التايتنز، هُزم على يد رفاقنا الشجعان في أعماق مدينة التايتنز اولدوار.",
[2785576738]="لا أحد يتحدث عن أمي بهذه الطريقة!",
[2785798049]="غطيني، لازم نعمل هذا بسرعة. بمجرد أن أفجر الدعم من هذه الناحية، سوف يعطل أشعة الطاقة وهي سوف تتحرر! أشك كثيرًا إنها ستكون مبسوطة بشوفتنا.",
[2786464593]="كان... مسليًا.",
[2786816204]="إذا بدوت مترنحًا، فاضربني. إذا فقدت الوعي، فاستخدم القربة. والآن، فلنتحرك!",
[2787322820]="%s يركز على $N.",
[2787602730]="سيصير ألم...",
[2787916360]="لقد هُزمت. قتال جيد!",
[2788057406]="فضفض شوي...",
[2788946610]="احرقه بالكامل!",
[2789308555]="حسنًا، أعتقد أنني أستطيع الاستمرار بمفردي من هنا. شكرًا جزيلًا لك على إخراجي من هناك!",
[2789599362]="أعلم أن هذه المرة ستنجح... محاولاتي الثلاثة عشر السابقة كانت مجرد تدريب!",
[2790664038]="اليوم يوم جيد يا صديقي. لقد مضى وقت طويل منذ أن غادرت معبد ويذرست، حرًا في الطيران عبر دراغونبلايت العظيم.",
[2791405464]="تم حساب غلاف نورغانون وتأمينه. سيكون متاحًا للنقل بمجرد التحقق من هوية المستخدم.",
[2791755764]="رابتر كلو!",
[2792063477]="بينما يختلط العامل المعادل بمياه البحيرة، يبدو أن الماء الذي تم تشعيعه بالبلورة أصبح صافيًا.",
[2792100285]="لا، هذا للضعفاء. اضربني بمطرقتك!",
[2793043547]="أفعالك تخزينا جميعًا، $C. أشعر بالألم في داخلي وأنا أضربك حتى تفقد الوعي.",
[2793125864]="بسس! لدي شيء قد يثير اهتمامك، $N. لقد سقط من بغل محمل في ناقراند!",
[2793244846]="أعراق العالم ستهلك. إنها مجرد مسألة وقت.",
[2793602350]="مطحنتي الجميلة. أنت! ستموت من أجل هذا!",
[2793885805]="ما يمكن أن يكون عليه عالمنا بدونك وبدون هوردك المنحرف... لقد انتهى الآن، أيها الوارتشيف.",
[2794170363]="إذا لم تخرج، فسنهدم هذا المكان!",
[2794180134]="كان عليهم أن يستمعوا لي. عندها كنت سأحصل على كل التكريم الذي أستحقه!",
[2794228674]="نعم، أنت متمرس في مجال عملك. توجه فورًا إلى مسؤول الاتصال المدني، نحتاج إلى المزيد مثلك!",
[2794599088]="الخوف للعدو! الخوف والموت!",
[2794683868]="ما هذا؟",
[2794751954]="أطيعيني أيها النصل!",
[2794916726]="سير زيليك، بالادن في حياته، قوي في إيمانه لدرجة أنه حتى بعد الموت، لا تزال قوة النور تستجيب لندائه، تضرب أعداءه في المعركة.",
[2795393245]="استمتع بلحظاتك الأخيرة.",
[2795587631]="وصلنا! شكرًا لإخراجي من تلك الحفرة الجهنمية. أخبر هيميت أن ينتظرني!",
[2795652073]="فلتجعلك قوة النور تنصاع!",
[2795777466]="الناس يظنون أني أحب الكورندوغ، لكن في الحقيقة، يسببون لي عسر هضم!!!",
[2797063043]="آه، يا للهدر... التالي!",
[2797166567]="لا يمكنك مقاومة القوة!",
[2797482063]="مساء الخير سيداتي سادتي، مرحبًا بكم في عرض هذه الليلة!",
[2797951282]="لوك'تار!",
[2798158100]="بريشياس حياة--را-آك--ضائعة!",
[2798400663]="أنا... طفح بي الكيل... منك!",
[2798581534]="أيتها الإلهة، امنحيني القوة للتغلب على أعدائي! اسمعي لي، رجاءً، حاجتي ماسة وقضيتي عادلة!",
[2798601436]="تجرؤ على تحديني؟ لم تكسب الحق بعد!",
[2798933939]="القصر... شخص آخر... سيلتهم قريبًا...",
[2798999846]="مؤثر...",
[2799497148]="حدث ما لا يُصدق... $N قتل برنس ساندوفال!",
[2800358147]="لم أر شيئًا كهذا من قبل. لا تركيز ولا فقدان للوعي بينما الموضوع مسيطر عليه. ماذا فعلت بها؟",
[2800892928]="كما كُتب!",
[2801155675]="لا أحد سينقذك.",
[2801178420]="لا تثقل على أدال بأسئلة دنيوية، $R. إرادة هذا الكائن هي كل ما يمنع أعداءنا من سحق هذه المدينة.",
[2801279311]="مغامرون، عليكم الإسراع! غارديان أوف تايم لن تصمد لفترة أطول!",
[2801605221]="فارفع كأسًا لكورين،",
[2801942089]="آلهة القدماء، نناشدكم. ماذا علينا أن نفعل؟ كيف يمكننا إنقاذ آلهة هذه الأرض؟",
[2802064903]="اقتلوهم، يا إخوتي! من أجل الـسكورج!",
[2802205500]="%s يزمجر.",
[2802861354]="اصمت! الانفجار وشيك!",
[2803049703]="ولكن يكفي ثرثرة! تريدون استعادة مدينتكم؟ تعالوا إذن، أيها الأبطال! أرواحكم ستغذي الجيش! ستعودون تملكون هذا المكان... قطعًا!",
[2803126931]="نورث ويند هو العدو القديم للتاونكا، حاكم بين العناصر، والقوة التي تمتص الحياة من هؤلاء القدماء.",
[2803650897]="هاه! فليكن. انفخ في بوق زعيم ماغناتور عند حلقة المشاعل جنوب مزار التنين الأزرق. اصنع السلام مع آلهتك... غرومثار سيأتي.",
[2803711123]="قربانك جاء متأخرًا جدًا، أيها الصغير. هل تشعر بالضباب يحيط بك؟ الكفالدر يعودون...",
[2804127498]="هل تسأل هذا السؤال لكل شيء محبوس في كرة؟",
[2804261590]="روحي تعذبت بقلق لا يطاق، أفكار مظلمة... تبعدني عن النور.",
[2804285514]="البوابة على مرمى البصر! سننجح! لكن أولاً، أحتاج لأخذ نفس.",
[2804312835]="حسناً، لقد فزت! أنا أستسلم! فقط لا تؤذني!",
[2804380340]="ف'وورون! كوشكوش لا تدفع شيئاً! موت!",
[2804521453]="أحسنت، لقد أثبت أنك جدير باختبار مهاراتك ضد مهندسي الرئيسي، تيلونيكوس.",
[2804734647]="استخدم الغضب الحارق لإلحاق الضرر بالأعداء والمناورات المراوغة إذا بدأت أتلقى ضرراً. تذكر أنني أحتاج لبناء شحنات مراوغة بتلقي الضرر لأداء المناورات المراوغة!",
[2805126574]="لقد حان وقت انتقامنا! ليحكم الظلام قلوب أعدائنا!",
[2805172246]="%s ينهي الطعام بسرعة ويتلفت حوله بحثاً عن المزيد.",
[2805254288]="ضعفه أدى إلى أسره.",
[2805329986]="حافظوا على تركيزكم، فأيام الحساب قريبة. قريباً، سيعيد مدمر العوالم تنفيذ وعده. قريباً سيبدأ دمار كل شيء!",
[2805630667]="يتحرك %s ويتألم من خدش الشوكة.",
[2805767694]="وهذا هو كومار فيلارد. متزوج منذ أسبوعين، اختفت زوجته من ميناء مينيثيل الآمن.",
[2806616849]="هذا ما يروحش هنا.",
[2806977941]="%s يرمق هاي إكزكيوتور مافرن وديثستوكر مالتندس بنظرات حادة.",
[2807102869]="%s يطلق زفيرًا طويلًا ممتدًا.",
[2807235458]="البرج الجنوبي دُمّر!",
[2807400263]="حتدفع ثمن تدخلك!",
[2807479607]="أرجوك، انفذ انتقامنا من سكورج لورد.",
[2808151583]="كلوا، يا أتباعي!",
[2808653825]="نيكرو ماذا بحق— تكلّم بالكومن بوضوح، يا رجل؟",
[2808736126]="آرثاس...",
[2809263408]="ظربان وأرنب وغزال صغير يسافرون معًا. هذا شيء لا تراه كل يوم. لا يهم، سأتناول لحم الغزال الليلة!",
[2810124997]="اسكت عن اللي تسمعه وتشوفه هنا، $R.",
[2810176952]="لم تكن مستعدًا!",
[2812094343]="كم بقي حتى تصل تعزيزات الفورسيكن؟ موقعنا هنا ضعيف. ليدي الخاص بك وعدنا بمزيد من الجنود. يجب أن نتمكن من التركيز فقط على ديثولم والـسكورج!",
[2814475575]="إنه كمين! دافع عن نفسك!",
[2815299709]="لا أبومينيشنز تحميك. لا سرية. لا تآمر في الظلام.",
[2815772034]="خذ $Gإياه:إياها; بعيدًا وجهز $Gإياه:إياها; لإعادة الإحياء.",
[2816547538]="سأقدم دمك قربانًا!",
[2817003799]="خذ هذه، يا بحري!",
[2817745917]="المشروع... سوف يستمر.",
[2818059759]="تم الأمر، يا سيدي.",
[2818069837]="أنت لا تخيفني، $Gولد:بنت;. بل العكس - أنا متشوق لقتلك. لا شيء سيقف بيني وبين زيم تورغا الآن!",
[2818121581]="يا لها من نهاية قاسية. تعالوا، أيها الأبطال. يجب أن نرى إن كانت قصة النوم صحيحة. إذا استطعنا فصل آرثاس عن فروستمورن، قد تتاح لنا فرصة لإيقافه.",
[2818354395]="سأبذل قصارى جهدي لترجمة ووصف ما أراه.",
[2818728592]="الآن يجب أن نجد المخرج.",
[2818785036]="أنا أعرف ما كان سيفعله.",
[2818922267]="عندما أدركنا أن الجوهرة بحاجة للحماية، توجهنا إلى الإلهة نفسها.",
[2819263836]="على راحتك، أيها الملازم. تابع.",
[2820091276]="آه، ها هو واحد!",
[2820393714]="غزوك ينتهي هنا! لن ينجو أحد!",
[2820565662]="أخيرًا، انتهى عملي.",
[2821568123]="الحواجز السحرية في تلك النقطة يجب أن تكون مدعومة بما يكفي من تدفق الطاقة لاحتواء الكيان.",
[2821734044]="أيها النادل! أحضر أقوى بيرة عندك. نحن متجهون إلى الجبهة.",
[2822153112]="خمس ثوانٍ. أنا لا أمزح!",
[2823000869]="ويي!!!",
[2823001224]="قلت لك... أنا لا أعرف... أي شيء... آخر!",
[2823031438]="واحدة حلوة، يا صغير.",
[2823600426]="أي، إنها جميلة بالفعل. وركنتها جنب فرقاطتي! *هيك*",
[2824104307]="%s يزمجر في اتجاهك قبل أن يأخذ وقتًا ليشمك.",
[2824196083]="أوه صحيح، لا تبذل أي جهد لتصنع ثروتك بنفسك!",
[2824468863]="اهدأ يا صديقي، وانظر إلى حقيقة الأمور!",
[2824568312]="لماذا هذه الطقوس تأخذ وقتًا طويلاً؟ سيدك وعد بأن مساعدتك ستسرع العملية!",
[2824648025]="اهرب، قبل فوات الأوان!",
[2824910792]="هو... هو احتفظ به؟ كل هذا الوقت، احتفظ به!؟",
[2825474301]="أرجوك، أنا مجرد رجل توصيل!",
[2825529087]="نادني في أي وقت، $N.",
[2826005098]="ما هو \"الفجر القرمزي\"؟ نحن نستحق معرفة الحقيقة، كويمبي!",
[2826772101]="لا أستطيع حتى تصديق هذه... هل تعرف هذهن المشاغبين صاحبي الصوت العالي، فورور وتيغول؟",
[2826827704]="لم يكن عليك فعل ذلك!",
[2826844358]="هذا $N قد أصيب بالجنون من الفساد!",
[2826862111]="الخنزير رائع!",
[2828537955]="ها نحن! تمسك جيدًا — هناك رياح قوية في المقدمة!",
[2828918004]="%s يبتسم ويشير إلى الشمال.",
[2829158919]="حسنًا، بيسي سيستمتع بهذه الوجبة الخفيفة.",
[2829742155]="لنرى ما يخبئه القدر...",
[2830311912]="أوه، لا...",
[2830955168]="احترقوا، أيها الشياطين الجهنمية!",
[2831387600]="%s تنسج شبكتها في شرنقة!",
[2831502043]="$N يُداس!",
[2831673661]="اسحقوا أطفال الحجر، يا إخوتي الحديديين!",
[2832273644]="ما هذا بحق السماء؟ أحضر لي المنظار يا بحار!",
[2832684647]="حسنًا، لنتحرك!",
[2832695924]="أرسلهم! أنا لا أخاف من بعض الوحوش النحيلة!",
[2832763459]="دوارف...",
[2833014049]="الواحد رقم وحيد.",
[2833116025]="مرحبًا!",
[2833462855]="هيا يا شباب، يجب أن نعيد بناء هذا الجسر.",
[2834161644]="دعني وإياك نتحدث عن بعض الأمور يا غودفري.",
[2834301589]="أجل، ما زال مكسورًا. لكن لا أستطيع شراء واحد جديد.",
[2834736672]="ألقوا أسلحتكم واستسلموا بأرواحكم!",
[2834766436]="مخازن الـفريكول مشتعلة! تم تنبيه حراس الدراغون فلاير!",
[2835097699]="يبدو أن سمعتي معكم عدائية.",
[2835108084]="شكرًا لك، سيد هيندرز.",
[2835783387]="التروقز... لا يتوقفون عن القدوم. موت أيها التروق! موت!",
[2835846996]="دع الكراهية والغضب يوجهان ضرباتك!",
[2836126512]="هناك خطوة أخرى على طريق النور: الرحمة.",
[2836162220]="%s يضحك وهو يشاهد الآفات تهرب.",
[2836341368]="اكتشاف مذهل قمت به. أحب أن أتاح لي فرصة النظر إلى كل التجارب الفاشلة.",
[2836374394]="سأسحقه وأسلخه وآكل لحمه وأكسر عظامه واحدة تلو الأخرى عندما أنتهي.",
[2836624036]="لقد حان الوقت! غولدان، اطلب من الوارلوكس مضاعفة جهودهم! بعد لحظات سيفتح البوابة وسيتم إطلاق هوردك على هذا العالم الناضج الغافل!",
[2836841567]="شادوز يلتهم.",
[2837001520]="يا سيدي. من فاذر لانكستر.",
[2837543446]="سو-ساي ما دقق في شيء لما ذكر الموروكرز طقس غريب، والآن كلهم ماتوا... هل يبدو لك هذا صحيحًا؟",
[2837694653]="تلك كانت أسوأ بيرة شربتها بحياتي.",
[2837929033]="تعال لمساعدة العرش!",
[2838166185]="الآن، لو أضفت الصفراء...",
[2838223727]="رامشتاين جائع للحم!",
[2838225880]="نعم، تتحرك مثل ابني. لديك أكتافه العريضة - آه، وعيون أمك الحادة.",
[2838411862]="صوب!",
[2839502928]="أنت محظوظ. عندي بالضبط ما تحتاجه في الحمولة اللي بشطفها.",
[2839544864]="المتحدي سقط!",
[2839690410]="استسلم يا تاونكا! إرادتك لن تصمد أمام الـسكورج!",
[2840707803]="تارتيك لا يقارن بك! أنت تملك المهارات. أجل!",
[2841216352]="الحياة لا معنى لها بدون معاناة!",
[2841948289]="حسنًا، لنذهب. أعرف المكان المثالي تمامًا!",
[2842121039]="هل تحتاجون مساعدة يا رفاق؟",
[2842173488]="ليديز وسادتي... حسنًا، دعنا نقول فقط إنكم لا تريدون تفويت هذه!",
[2842209096]="جهود رفاقك تجبر %s على الظهور أكثر في العالم المادي!",
[2842592605]="نحن نعلم أن لديك شيء التنين! لسنا خائفين! سنأخذك أنت وشيء التنين!",
[2843929746]="ماذا تفعل؟ هذه العينات حساسة جدًا!",
[2844245776]="أعتقد أن هذا الشيء هو التجسيد الحي للظلال... الظلام... إنه مظهر. إنه فراغ.",
[2844257060]="بهديته، سأدمر هذه الأرض وأعيد تشكيلها!",
[2844451079]="حسنًا، ها أنا ذا!",
[2844572579]="نعم! اطعن بضع مرات أخرى تحسبًا! اطعن جيدًا!",
[2844576769]="حتى أحلك الذكريات تتلاشى عند المواجهة!",
[2844713988]="إلى مواقعكم. دافعوا عن المدينة.",
[2844753422]="ستعاني في هذه الهزيمة، نيفاريان!",
[2844854082]="بدون هدف، يتجولون... لكن الكثيرين يجدون طريقهم عائدين إلى المناطق المقدسة التي أقسموا على حمايتها ذات يوم.",
[2844948834]="كان غرورنا لا يغتفر. لقد حكمنا على أحد أنبل الكائنات بالهلاك. قد لا نكفر عن هذه الخطيئة أبدًا.",
[2844957381]="%s يندفع نحو $N!",
[2844958932]="سأشاهدك تنزف!",
[2845789445]="لدي فكرة، بيلي...",
[2846115176]="السرب متعطش للتغذية.",
[2846413131]="يبدو أن هناك المزيد من الدبابير كللم يعد داجيك. لماذا لا تنفد؟",
[2847021946]="بسرعة، تقدم!",
[2847234473]="لا أستطيع أن أتفق أكثر.",
[2847243948]="لقد حررتني! الرياح تتحدث إلى شعبي مرة أخرى وتمنحنا قوتها. أشكرك، أيها الغريب.",
[2847483974]="اذهب الآن، $N. ابحث عن فولكور... وتذكر، السحر الذي يحميك سيفشل إذا تفاعلت مع أي شخص، باستثناء التحدث.",
[2847642093]="كل شيء كان يهتز في كل مكان. بالكاد استطعت تثبيت بندقيتي.",
[2847676936]="%s يتحول إلى الفراغ...",
[2847767871]="مممم... لذيذ.",
[2848701738]="الحفر بعمق في ماضيك قد ينهي مستقبلك فجأة.",
[2850376579]="هناك، حصلت عليه!",
[2850647741]="لن أفشل الـليتش كينغ. تعال وواجه نهايتك!",
[2851827009]="رأيت مورلوك يسبح بجانب نافذتي.",
[2851993245]="أجل، لا بد أن أمضي قدمًا.",
[2852363690]="شكرًا لك! لم أكن لأصمد أكثر من ذلك.... لقد حدث أمر فظيع هنا.",
[2852734586]="ثوريمز هامِر متصل. جارٍ تحديد الهدف.",
[2852861154]="%s يشير إلى السماء بالأعلى.",
[2853292958]="يييييييييييييييييهههههههههه!!!!",
[2853984920]="قل وداعًا!",
[2854527485]="آرثاس حطم قواتنا وأخذ أقوانا في خدمته كـسانلاين.",
[2855042475]="لا يمكنهم الخوف...",
[2855299382]="الآن رحت للأبد!",
[2855411071]="تراجع! المس ذلك النصل وستُوسم روحك للأبد! يجب أن أحاول التواصل مع الأرواح المحبوسة داخل فروستمورن. أعطني مساحة. تراجع، من فضلك.",
[2855728563]="فلادوف ينزل!",
[2856311806]="ستدفعون الثمن غاليًا عندما أعود من الأعماق!",
[2856890869]="تعبد الموت أيها الرجل الصغير؟ الموت هنا!",
[2857350886]="أخيرًا! عذر لسحقك!",
[2857401165]="إذا لم يساعد أحد، قروك يسحق!",
[2857463610]="في المقدمة المزيد - استمر!",
[2858246865]="الأنديد يزحفون في كل مكان. أين جيش ستورمويند؟",
[2859319121]="وفقًا لدعوتي الإلهية، يجب أن أشارك هذه الحقائق المكشوفة لكل من يريد أن يسمع.",
[2859348392]="فيرالاس: تاريخ... هممم... دعني أفحص هذا للحظة.",
[2859509021]="يا جماعة، ارفقوا بي... هذه أول مرة لي.",
[2860065747]="%s يختفي عائدًا إلى المستنقع.",
[2860631378]="%s يلتهم كل الزومبي القريبين!",
[2860795978]="ماذا؟ منجلي لم يخدشه حتى! هذا أقسى خام رأيته في حياتي!",
[2861112832]="الحملة الصليبية ستطهر جنسكم من هذا العالم!",
[2861242576]="لا ينبغي أبدًا التقليل من مهارتهم في القتال.",
[2861376504]="أرثاس!!!!",
[2861530786]="يمكن سماع شهقات في جميع أنحاء الغرفة.",
[2861547809]="كلمتان - مستحيل!",
[2861632036]="بسسست. لقد حصلنا للتو على بعض القمر المسكر...",
[2861885076]="قطعة قطعة سأمزق هذا المتحدي... قطعة قطعة!",
[2862001069]="اعرف سيدك، أيها الكلاب الحقيرة!",
[2862838024]="كن مستعدًا لأي شيء، $N.",
[2863600920]="وصلت تقارير من الاختبار على أسطول العدو، سيدي!",
[2863647096]="لا أحد يسرق خيول كيتريك!",
[2864637349]="اللحظة تقترب، أيها الفاني. ستعمل إلى الأبد في أزيروث جديد!",
[2864910856]="الآن ستنضم إلينا... للأبد!",
[2864998010]="أوه، هذه كبيرة!",
[2865986538]="يقع معبد ألدور الأقدس ومساكنه المحيطة على الشرفة أعلاه. كمكان مقدس، لا يُسمح بالدخول إلا للمبتدئين.",
[2866642509]="أتجرؤ على مهاجمتي؟!",
[2867008068]="تم تسجيل تجاهلك المتعمد للسيادة العليا لإمبراطورية قوروباشي. تم إبلاغ سكان زولقورب بوجودك.",
[2867025048]="كور'كرون، تحركوا! أيها الأبطال، احترسوا. الـسكورج كانوا...",
[2868146396]="%s يعوي ردًا على نداء مالوكاز.",
[2868407938]="لا بأس يا عزيزي. هذه على حسابي.",
[2868946444]="أي نوع من الأقزام تظنني؟",
[2868971588]="أشعر بفساد هذه الأرض فيك أيها الجندي. تقرير إلى الأسقف قبل بداية نوبتك التالية.",
[2869045276]="لقد تم الأمر. الجميع أعطى ما يجب أن يُعطى. الآن أختم روح التنين إلى الأبد.",
[2869125844]="شاهدوا العروض الكوميدية لـ بيري قاتنر بعد دقائق قليلة!",
[2869137976]="بالتأكيد لا تظن أنك ستنجو من هذا الاقتحام. سيأتون من أجلي وستدفع ثمن وقاحتك.",
[2869208894]="أريد عينة...",
[2869559229]="أبعد الأشرار عني!",
[2869560114]="أبصق عليك، أيها القذر السطحي!",
[2869597233]="اثنان وأربعون... اثنان وأربعون... اثنان وأربعون ماذا؟ يمكن أن يكون أي شيء! اثنان وأربعون... همم...",
[2869653105]="هناك! إنهم يتبعوننا!",
[2869683706]="أخشى أننا قد لا نستطيع تهدئتهم أبدًا...",
[2869780666]="لا، أرجوك! لا تفعل!",
[2869792921]="متسللون عند بوابة الخدمة! يجب تحذير اللورد ريفندير!",
[2869991813]="لا يمكنك الهروب من غضب السيد...",
[2870223882]="الموت هو المخرج الوحيد!",
[2870317030]="ضعيف!",
[2870474777]="تجرؤ! الآن اشعر بغضبي!",
[2870976771]="طويلاً جلست خاملاً، غارقاً في هذه الضبابية... هذا الخمول، نادماً على ما كان يمكن أن يكون... ما كان يجب أن يكون.",
[2871584573]="وصلنا! ابدأوا بالحفر!",
[2871607422]="جو صيد رائع!",
[2871654390]="هيا، أرني قتالاً حقيقياً!",
[2871879445]="اليأس... لذيذ جداً...",
[2872397170]="اشرب بؤسهم يا أخي!",
[2872428336]="على من أمزح؟ إذا تاجرت مع الجوبلنز لازم يكون في محفظتك بطانة حديد.",
[2872718068]="مرحبًا بك في عالم الأنديد.",
[2872934065]="خليهم حارين يا غبي الكبير!",
[2873861529]="قلائد مذهلة! تحف رائعة! صاغة الجواهر الجدد ما عندهم شي على الطرق الغامضة المجربة لـ قريفتة! طور حالك بهذه التمائم السحرية بسعر رخيص!",
[2874189648]="ما هذا؟ أبطال، يأتون لمساعدتي؟ أستشعر يد الظلام في هذا. حقًا هذا الحدث المقدس يحمل بركته؟",
[2874763428]="الكل يخدم السيد في الموت.",
[2874860705]="حتى نلتقي مرة أخرى....",
[2874929511]="عندي رسالة خاصة لـ $N. وتقول إنه لازم تموت!",
[2875297927]="حياتك ضائعة!",
[2876074456]="سأجذب روحك إلى الضباب!",
[2876292191]="%s يومئ برأسه على مضض.",
[2877105116]="إنه سلاح لا مثيل له. يجب أن يكون لا مثيل له.",
[2877124484]="%s يبدأ في التصدع والتحطم.",
[2877449936]="هذا كله... خطؤك!",
[2877461440]="لاحظ، هيقان الـ أنكلين. العقل المدبر وراء قدور الطاعون التي حولت برية أزيروث إلى أراضي الطاعون.",
[2877649420]="واو! هذا أكثر بكثير مما كنت أتوقع، أنت وحدك يا نحيف!",
[2878349526]="لا يمكن أن يكون...",
[2878841085]="برينس آرثاس؟ أرجوك. يقضي كل وقته في ملاحقة ابنة براودمور، على حد ما سمعت. بوي لديه ما يشغل باله أكثر من شؤون الدولة، أقول لك.",
[2879098257]="لو كنت ذكياً، لكنت أبيع هذا البحث مقابل مقعد على الصاروخ. لدي شعور بأننا سنحتاج لمغادرة هذا المكان قريباً!",
[2879322949]="قل مرحبا لبعض أصدقائي.",
[2879873319]="ممم... لا مزيد من الحياة. لا مزيد من الألم. آ-آك!",
[2879946827]="هل ظننت أنك ستنجو بحياتك؟",
[2880188921]="عاني!",
[2880345096]="عقولنا كانت حرة أخيرًا، أجل... حرة لتعيش كل الأفعال التي لا يمكن تصورها التي ارتكبناها تحت تأثير الـليجيون.",
[2881094262]="لن يحدث هذا أبدًا، نات.",
[2881125194]="سأطلب مغفرتك على المعاناة التي سببتها لك ولشعبك.",
[2881223196]="كان الملك سيسافر إلى هنا بالسفينة، في سرية. لكن السفينة لم تصل أبدًا، واختفى الملك راين.",
[2881525929]="يمكن أن أسقط... لكن إمبراطورية الأماني... لن تموت أبدًا.",
[2882081107]="لا، أيها التابع. هذا ليس جاهزًا.",
[2882490382]="لا تدع كاسكالا تنسى ما حدث هنا.",
[2882566082]="قلب فيوري... شهدت قوته منذ زمن بعيد، عندما استخدمه فيلين. أشعر بنفس القوة تجري فيه الآن!",
[2883738763]="ابتعد عني، إدواردز، وإلا سأقطع رأسك.",
[2884373558]="%s يداعب الأرنب الخائف.",
[2884404765]="كنا ننتظرك، $N. الآن لدينا اليد العليا.",
[2884420857]="قدمي تؤلمني.",
[2884571344]="أنا مدين لك بدين الحياة، أيها الغريب.",
[2884599266]="جارٍ الوصول... في المراحل المبكرة من دورة تطوره، أصيب أزيروث بعدوى من متكافلات نيكروفوتيك طفيلية.",
[2885190044]="أجل، اهرب! هذا يجعل الدم يضخ أسرع!",
[2885403687]="المجالات الدوارة تنبض بالطاقة المظلمة!",
[2885603732]="ما زلت ضعيفًا، لكن أعتقد أنني أستطيع رفع حاجز مضاد للسحر. ابقَ داخله وإلا ستدمرك تعويذاتهم.",
[2885923771]="سأدمر هذا الحاجز. يجب أن تمسك بالأنديد!",
[2886130021]="$N! آه، رائع رؤيتك وأنت تتنقل. مشغول كالعادة، هاه؟",
[2886311680]="عذرًا، هل تحاول التسلل بدون دعوة؟",
[2886816985]="لم أعتقد أبدًا أن اليوم سيأتي وأغادر وطني ويستفال...",
[2887253169]="ألست ماكرًا؟ لدي بعض الحيل الخاصة بي أيضًا...",
[2887433621]="تكلم، ليتش! الموت لن ينقذك مما سأفعل بك!",
[2887488456]="لا تحاول التهرب من هذا!",
[2887782163]="جئنا لشيء، صحيح؟ لا أستطيع التذكر.",
[2888092809]="لن تجد أسعارًا أفضل في أي مكان!",
[2888124982]="آه! شكرًا جزيلًا لك، $N! أنا حر! أخيرًا!",
[2888241853]="الآلهة القديمة ستُستعاد. لن يُسمح لك بالتدخل!",
[2888560795]="أفضل المشروبات في ستورمويند!",
[2888928267]="تم التحقق من أن معبد الحياة متضرر بشكل لا يمكن إصلاحه.",
[2889296396]="الأمر ميؤوس منه. قطع واحدة يؤدي إلى نمو اثنتين جديدتين.",
[2889451602]="يا له من حشد حسن المظهر. نساء الدوارف حتى حلقن.",
[2889598465]="هذه هي الـهورد الحقيقية! الـهورد الوحيدة!",
[2890111243]="لا نرغب في أن نُزعج!",
[2890344149]="تم تحييد التهديد.",
[2890345968]="الجنون سيلتهمك!",
[2890461811]="هل عُضِضت؟",
[2890681133]="هل رأيت الألعاب النارية؟ هذا أفضل وقت في السنة لشرائها.",
[2891418400]="كلاب إيليدان! دمروهم جميعًا!",
[2891620100]="لماذا نساعدكم؟ العالم دُمّر. خُرّب.",
[2891768506]="أنا أحترق!!! مجددًا!!",
[2892405275]="تم تحليل التهديد! تفعيل خطة القتال بيتا! كلاك!",
[2892440143]="أين أخلاقك يا أخي. دعنا نرحب بضيوفنا كما ينبغي.",
[2892546103]="ترولباين!",
[2892721134]="أنت لست جديرًا بمواجهة الـليتش كينغ!",
[2892852944]="الحراس!",
[2893268541]="صغير $C! أنت لا تقارن بعشيرة بلاكروك!",
[2894157423]="حسنًا، لنخرج من هنا الآن!",
[2894388995]="كويلديلار ينبض بالحياة بوجود فروستمورن!",
[2894434999]="همم، مثير للاهتمام...",
[2894534396]="يحق للفورسيكن الاحتفال بحريتهم.",
[2894828076]="...لتأسيس صندوق لشراء جل الشعر؟ أنا أحب شعري كما هو، شكرًا!",
[2894852237]="الأدميرال الأعظم نفسه جاء ليشهد تفانينا. إذا رأيتك تتكاسل في موقعك مرة أخرى، سأبقر بطنك بنفسي.",
[2894897318]="اختبار ناجح! $N، هذا الإندوريوم شيء مذهل.",
[2895411877]="همم... أعتقد أنني بحاجة لطعم أفضل. سأتفقد عربة والدي.",
[2895878496]="هناك، هذا يجب أن يكفي...",
[2896221017]="نحن نستطيع الرقص أيضًا!",
[2896429300]="استعدوا للمعركة، يا مخلوقاتي.",
[2896440144]="جوريجيك لم \"يتعثر\" أبدًا في كوخ الدجاج... جوريجيك دائمًا يضطر لإطعام بطنه الغبي. دائمًا دجاجة ناقصة عندما نمسكهم جميعًا.",
[2896884298]="لننهِ هذا الأمر...",
[2897241227]="أثريكوس يشير إليك بينما يزأر بكلمات تمزق داخل أذنيك. هي آخر شيء تسمعه.",
[2897989100]="%s يمسك الطعام بفمه ويبتلعه في جرعة واحدة.",
[2898163608]="تطهروا بالصلب!",
[2899183531]="سأجذب هجماتها. أعِد إخوتنا إلى قبورهم، ثم ساعدني في إسقاطها!",
[2900304216]="برج بوينت دُمّر على يد الأليانس!",
[2900508157]="داركنس ينتظر.",
[2900548295]="كانت تجربة غيرت حياتي... اعذروني لدقيقة.",
[2901344065]="أنا سأحطمك!",
[2902215956]="ما الذي تفعله أرانب لامعة هنا على أي حال؟",
[2902553765]="لكن هذا هو المبنى الوحيد الذي يتسع لـبروق! الجوبلنز يبنون مباني صغيرة جدًا!",
[2903644628]="مان'اري... لكن كيف... نحن لسنا إيريدار! يجب أن تعرف! إذا كان هناك آخرون مثلها، يجب أن نجدهم ونشرح...",
[2904341551]="من يجرؤ على تدنيس مذبح غورغروم الـ دراغون إيتر؟",
[2905618671]="حان الوقت للخطوة الأخيرة؛ يجب أن نفعل المذبح.",
[2905830645]="إذن أنت أحمق.",
[2906070617]="دعهم يأتون. سيدفعون ثمن ما فعلوه!",
[2906314154]="%s يبدأ في إلقاء فلاش فريز!",
[2906383702]="الأمور تبدو قاتمة...",
[2906413868]="ستندم!",
[2906666429]="لأنني سأكتفي بالمشاهدة والضحك وهم يلقون بك فيها.",
[2906916568]="لا! لا يمكننا السماح لك باستدعاء هاكار!",
[2907129538]="وجبات خفيفة!",
[2907346206]="سيدي، عملاؤنا يشتكون من عدم وجود كفاية من 'ألم العذراء' في سمومنا القاتلة.",
[2907522311]="أنتظر أوامر بشأن مهامكم المحددة. في هذه الأثناء، ابقوا هنا وكونوا مستعدين للتحرك في أي لحظة!",
[2907929771]="لم أسمع به أبدًا. يبدو شرًا خالصًا.",
[2907959935]="لا يجب أن نتأخر هنا... ابق قريبًا - سآخذنا إلى مكان آمن.",
[2907974402]="أشكرك على كرمك، مورغور. يجب أن أغادر الآن.",
[2908284010]="ما رأيك في القناع؟",
[2909135141]="همم، غريب... هذا ينتهي فجأة. في تاناريس تواجه وثيقة كيراجي تنينًا برونزيًا. هناك الكثير مفقود من هذا... يجب العثور على مزيد من المعلومات! بالتأكيد يخططون لغزو كاليمدور مرة أخرى!",
[2909248577]="%s تشتعل من حرارة كور هاوند أخرى!",
[2909420340]="القار الـ تشوزن موجود في ريلكويري أوف بين إلى الشمال الشرقي.$Bبرنس نافاريوس موجود على الجانب الآخر من ديد فيلدز إلى الشرق.",
[2909629119]="الصمت يخيم على شاتراث.",
[2909778452]="يا إلهي! انظر إلى هذا... كل هذه الشموع. أنا متأكد أنها تُستخدم لطقوس مروعة أو استدعاء شرير. الأفضل أن نسرع!",
[2909912924]="%s يغضب من طلبك ويهاجم!",
[2909925619]="أشم رائحة... $R. لذيذ!",
[2910038310]="هناك واحد! من أجل الـهورد!",
[2910591995]="أوووف! هذا سيحتاج إلى \"المكشطة\".",
[2910647608]="هذه المنطقة ستدمر نفسها خلال سبع دقائق.",
[2910651342]="كن على حذرك!",
[2910928906]="جاهز عندما تكون أنت، أيها الواريور.",
[2911335194]="نبض قلبك... موسيقى لأذني.",
[2911865221]="جارغن أولكت!",
[2911934527]="في الصندوق يا جميلاتي! هكذا. واحدة تلو الأخرى تذهبون.",
[2912358470]="غورغيك سيمسك الدجاجة جيدًا!",
[2912433658]="انتهينا هنا. أنا خارج.",
[2913231198]="بركات أرواح الأرض والهواء عليك.",
[2913552852]="سوف يقول لك: ثرال. قُد شعبك.",
[2913630204]="اللعنة عليك، $N! يومًا ما، سيكون الانتقام لي!",
[2914420858]="بالنور! هل يمكن أن يكون؟ هل يمكن أن يكون هذا هو؟",
[2914489300]="كل جهودكم ذهبت سدى، لأن استنزاف شجرة العالم قد بدأ بالفعل! قريبًا لن ينبض قلب عالمكم بعد الآن!",
[2914558410]="والآن أول مرسوم لي على الـفريكول! يجب تدمير جميع الأطفال المشوهين المولودين من أم وأب فريكول عند الولادة! يجب أن يبقى دمنا نقيًا دائمًا! أولئك الذين يخالفون مرسوم إميرون سيتم نقلهم إلى غياليربرون للإعدام!",
[2915377057]="أناريندال دراكون!",
[2915439752]="أي إزعاج هذا؟ ستموت!",
[2915574491]="%s يطلق ضحكة زاحفة... على الأقل تعتقد أنها ضحكة.",
[2915927482]="لا! ابتعد عني! النجدة!!",
[2915958011]="%s يشخر.",
[2916590843]="لقد وجهت كل ما لدي! القوة بين يديك!",
[2917011106]="مستحيل!",
[2918030964]="واو! $N، غبار الأحلام هذا شيء قوي!",
[2918123832]="غريب. غريب جدًا...",
[2918323863]="ارحل، أيها الوضيع الحقير! الأليانس سينتصر في الترآك فالي!",
[2918362330]="أنت... من هو المرض... وليس أنا...",
[2918416793]="يُقال أن هيغان قد زود جدران وأرضيات ناكسماراس نفسها بمجموعة هائلة من الفخاخ، يمكنه تفعيلها متى شاء.",
[2918606061]="الكثير من الطاقة غير المستقرة... لكنها تستحق المخاطرة لتدميرك!",
[2919152342]="أكاماً، يا صديقي! هل تم إبلاغك؟ لقد اكتشفني أتباع فاشج. سرنا في خطر!",
[2919569509]="وصل الغداء، يا أطفالي الجميلين. مزقوهم إربًا!",
[2919861573]="ارجع! أعيدك إلى الخلف... يا مفسد الإيمان! يا صانع الألم! لا تعد، أو تلقى نفس المصير الذي لقيته هنا اليوم!",
[2919887283]="ماذا يحدث هنا؟ بيزنيك! كنت أعرف أنه ما كان ينبغي لنا أن نتركك تتسكع!",
[2920608258]="نجاحك لم يدم طويلاً!",
[2920679108]="سأأكل قلبك!",
[2920879622]="خطأ! أنت من سيموت، تيلاثيون النجس!",
[2920887507]="أقسم، الناس رأوهم بالفعل. الباندارين موجودون حقاً!",
[2921128305]="الأمور تسير على ما يرام، وافل فراي. أليس لديك عرض منتج لتفعله أو شيء من هذا القبيل؟",
[2921393181]="لقد جاء المسخ! إلى الأمام!",
[2922038840]="أنت فقط تعجل بالحتمي. في النهاية، كل شيء سيلتهم!",
[2922076733]="لقد كسرته...",
[2922650974]="اختر كلماتك بحكمة، أيها الديث نايت. أنت تقف بين رفاق المخلصين.",
[2923264637]="آخر تقليد. صعب، لكن خلينا نشوف إذا بتعرف مين...",
[2923457414]="ماذا يفترض بي أن أفعل دون أدوات، جورج؟",
[2923691217]="أنا بوت. لدي كمية كبيرة من المعلومات. لكي تعرف ما لدي، اهمس لي.",
[2924200280]="أرواح المنافسة صارت قوية مرة ثانية.",
[2924376930]="المقبرة الشرقية تم أسرها من الـهورد!",
[2924815547]="يا سيدي، هالأوغاد البشر يخونونا. لازم يتعذبوا!",
[2925480628]="أيوة... أيوة بنتحرك هلا... أرجوك لا تؤذينا...",
[2925778848]="مجرد خدش!",
[2926245406]="أيوة... كل شيء حسب الخطة.",
[2926280493]="%s يتحول إلى وضع البرسيركر!",
[2926387635]="سيكون الجو أبرد بكثير في قبرك.",
[2926416059]="حياتك قد انتهت.",
[2926593603]="مثال رائع على $Gرجل:امرأة;، ذلك $N.",
[2927845978]="جنود لوردايرون، انهضوا لتلبية نداء سيدكم!",
[2928300436]="أتجرؤون على تحدي أبناء الحديد؟",
[2928345781]="%s يبدأ بالانجراف...",
[2928382166]="أنا... ناطركم في الناحية التانية....",
[2928829205]="مثلما كانت أمي تقول دائمًا: [شيطاني] \"رازكس خاج جاشكس زاشجكس.\"",
[2928925259]="أخيرًا! يمكن إيقاظ ناراليكس! تعالوا وساعدوني، أيها المغامرون الشجعان!",
[2928934833]="واجهوا بطلي، أيها البشر!",
[2929287541]="كل الأشياء الجيدة لا بد أن تنتهي.",
[2929553395]="آوخ!",
[2929760616]="آها! هذا هو!",
[2930185083]="الآن لنُسخّن هذه الرقائق...",
[2930321343]="ها هم قادمون! دافعوا عن أنفسكم!",
[2931137037]="صيد ثمين حقًا! لقد جلبت الشرف للهورد يا فتى، نحن نشكرك!",
[2931457185]="%s يسقط على الأرض. تتحرر روحه مع أنفاسه الأخيرة.",
[2931620360]="أنت تؤذيها!",
[2931782950]="تعال إلى نحاتي، أيها الضفدع القبيح! تعال وأرني من يجرؤ على عبور إخوتي!",
[2931938072]="أرى فجوة في الضباب أمامنا. نحن نقترب!",
[2932045389]="بوابة الإيميرالد الخضراء تتعرض لهجوم!",
[2932488360]="باه، الصيادون الحقيقيون يواجهون أقسى الأمطار!",
[2932634775]="%s يفتش في القمامة.",
[2932945601]="%s يهز كتفيه. من يعلم؟",
[2933161131]="كفى! أرى أنني يجب أن أتولى الأمور بنفسي!",
[2933327770]="انهض، يا بطلي!",
[2933334488]="اسم؟ أوه، نعم، الاسم! أعتقد أنه كان إسكالدر.",
[2933433772]="الشر المنبعث من الشظية البلورية استدرج أحد العمالقة. أردوه سريعًا!",
[2933999463]="لا يمكنك... قتل... روحي!",
[2934247703]="ماذا تظن أنك ستحقق من هذا، أيها الأحمق؟ حتى الآن، جيوش بلاكروك تستعد لتدمير عالمك.",
[2934879335]="سيغريد آيسبورن عادت إلى مرتفعات يوتنهايم لتثبت نفسها أمام $N. في آخر لقاء بينهما، تفوق $N عليها في قتال فردي. فلنرَ نتيجة هذه المواجهة.",
[2935411346]="أشعر بخطر أمامنا.",
[2935770325]="أوه، سننسجم معًا بشكل ممتاز، $N.",
[2935953801]="نحن محاصرون... أعداؤنا يضغطون علينا من كل جانب، يا هيلسكريم الشاب.",
[2936150981]="لا، ليس أكالي أيضًا!",
[2936347957]="$N، يجب أن نتسابق أنا وأنت في يوم ما.",
[2936403176]="روووووار!!",
[2937214901]="اهدئي، اهدئي يا بلانشي. لا تغاري، ستذهبين قريبًا في مغامرة كبيرة خاصة بك.",
[2937283117]="أنت ملاكي الحارس! مثل فارس أبيض هبطت من السماء ورفعتني من حفرة الهلاك!",
[2937713720]="$N، سأعرف لوامس وجهك في أي مكان... ماذا... ماذا فعلوا بك، $N؟",
[2938915519]="الـليتش كينغ لا يُقهر...",
[2939308675]="هل هناك سبب لبقائنا هنا؟ أحب أن أسمعه.",
[2940101580]="حياتنا كانت تساوي أكثر بكثير من ثأرك الدموي...",
[2940227800]="آه، لقد أغضبتني الآن! حان الوقت لترى القوة الحقيقية لحجر المد!",
[2941217473]="لا، هذا لا يمكن أن يكون! هذا المقوي... كان من المفترض أن يعكس إدماني، لا أن يعجل بسقوطي في صفوف البائسين!",
[2941522536]="أوه، رائع!",
[2941954963]="أهلاً.",
[2942645483]="يا خنجر السعادة! هذا غمدك؛ صدأ هنا، ودعني أموت!",
[2942775200]="الـليتش كينغ يطالب بإرسال المزيد من ثعابين الصقيع إلى أنغراثار! نفذ مطالبه أو واجه غضبي!",
[2942921851]="%s يبدأ بإطلاق لهيب!",
[2943084069]="لقد حسمت مصيرك، أكاماً. السيد سيعلم بخيانتك!",
[2944378578]="اتركونا وشأننا! دعونا نكون!",
[2944558999]="حر... أخيرًا...",
[2944661962]="ظننت أنك لن تسأل أبدًا!",
[2944962040]="سيدي، مهمتي اكتملت.",
[2946631643]="نار في الحفرة!",
[2947060962]="مهنتك؟",
[2947457801]="عاصفة العظام!",
[2947659439]="سمعت ذلك! لا مزيد من الجعة لك! ولا قطرة!",
[2948000151]="مرحبًا بعودتك، أيها البطل.",
[2948252593]="لازم أقلع عن التدخين! أعطني دقيقة لألتقط أنفاسي.",
[2948599708]="إذا كان كأسك ممتلئًا، فليكن ممتلئًا مرة أخرى!",
[2948775020]="من يجرؤ على التدخل في أعمال نقابة ديفياس؟ مت $C!",
[2949443667]="لقد جئت متأخرًا، الآن اشعر بغضب كلابي الحربية!",
[2949897680]="أقول لك الآن، عندما نعود إلى فارسترايدر إنكليف سيكون هناك حساب كامل لأفعالك، رينجر فالانا! أنت وحدك المسؤول عن خسائرنا وأنا متأكد أن القبطان سيرى الأمر مثلي.",
[2949951495]="لن تهزم يد غرول!",
[2949955667]="الغراب سيعود إلينا كما ورد في النبوءة وأنت عاجز عن إيقافه!",
[2950766086]="لن يكون هناك مهلة! عملي هنا أوشك على الانتهاء!",
[2950790691]="%s يسحب القوة إليه...",
[2951546534]="حشرات متطفلة! لقد جئتم متأخرين. الـ روبي سانكتوم ضاع!",
[2951624000]="يا ناجمارا! كيف حال كأس من بيرة دارك أيرون؟",
[2952380889]="لم أرغب في الانحدار لمخاطبة أمثالك، لكنك لم تترك لي خيارًا...",
[2952397028]="ماذا؟ أوه لا، لا يهمني ما تقوله. أنا فقط أستمتع بإلحاق الألم.",
[2952411556]="حان وقت الحفلة!",
[2952793479]="انتهى عذابي والآن يمكنني الانضمام إلى الإلهة. شكرًا جزيلاً لك!",
[2952836440]="لقد كذبت. طعامك البائس نتن، لكن ليس بقدر ما سينتن هذه البلدة!",
[2953414160]="كيف تجرؤ على وضع قدمك في مدينتنا!",
[2953438289]="رؤيتنا ستتحقق!",
[2953489000]="وقاحتك مروعة، أيها الأحمق! سألتهم روحك!",
[2953661549]="%s يبدأ بالترتيل...",
[2953906270]="لقد مللت من محاولتك لشفاء الأرض وتهدئة الطاقات التي تستدعي وتجنن العمالقة. قولياثون، ملك العمالقة، الأمير كايل'ثاس وأنا نطلب منك الدفاع عن البلورة!",
[2954440091]="النار امنحني الرؤية...",
[2954501386]="المزيد من التروقز! ابعدهم بينما أحضر المتفجرات!",
[2954519158]="سوبريموس يحصل على هدف جديد!",
[2954616421]="هل سينتهي الكابوس يومًا؟! لا أستطيع إجبار نفسي على الاستيقاظ!",
[2954710017]="$N، من الجيد جدًا رؤيتك مرة أخرى!",
[2954867092]="أنت تبحث عن زعيمهم... أيها الصغير، أنت تشن حربًا على عشائر قرومثار ثندربرينغر نفسه. لا تكن متحمسًا جدًا للاندفاع نحو موتك.",
[2955159293]="حراس المقدس يبلغون عن وصولهم!",
[2956419686]="لماذا لا تجرب مرة أخرى بدون حيلك الرخيصة، أيها الجبناء! أم أنكم جبناء جدًا؟؟؟",
[2956503816]="أيها الأحمق الوقح! سأقتلك بنفسي!",
[2956629251]="أجل، أنا سعيد أنني تمكنت من الوصول إليك قبل الطاعون.",
[2956655577]="أنا ما يعجبني هذا...",
[2956691892]="آه، جيد $N. الآن دعنا نرى ما تقوله هذه الرؤوس...",
[2956787688]="للأسف، حتى هذا يجب أن ينتهي... الروابط التي تربطني بهذا العالم تضعف وتسحبني بعيدًا...",
[2956870591]="%s يحاول إلقاء عقد الموت على خدمه!",
[2957529572]="اطبخ.",
[2957817920]="لقد هزمت أحد أفضلي، لكن جهودك تذهب سدى.",
[2957858331]="فيسبرون، الحضنة في خطر! ساعدني!",
[2958364131]="لي! لن تأخذ هذا المكان!",
[2958717128]="الأم العظيمة...",
[2958742436]="كنت سأرسم صورة لأفضل خطة هجوم... لكنك أخذت طبشورتي.",
[2958838355]="لكي يكون الأمر كما يجب، نعم.",
[2958840340]="ظهري يقتلني.",
[2958875701]="أنت وحش!",
[2959515956]="يجب أن نتحمل هذه الأوقات الصعبة بإيمان، ويوماً ما سنجد أنفسنا منتصرين.",
[2959969920]="نحن على جدول زمني صارم. لن تتدخل!",
[2960814475]="نحن حفارون سريعون! سريعون جداً! انظر... خلصنا! كان ذلك سريعاً، هاه؟",
[2960838128]="%s يصوب بعناية أكبر...",
[2961039355]="حسناً. لكن تذكر فقط، قوة النور المقدس ليست شيئاً يُستدعى باستخفاف، يا أخي.",
[2961180832]="اسمع، لقد وجدت هذه التميمة قبل أن يمسكوني. ربما تفيدك هنا...",
[2961372774]="هيا، أيها الترول... هدية!",
[2961691767]="يا رجل، لقد أصابك إصابة قوية!",
[2961991825]="سحلية صغيرة! الموت هو الجواب الوحيد الذي ستجده هنا!",
[2962184648]="أوبس!",
[2962187897]="أنت... غير مهم.",
[2962549607]="%s يشخر بصوت عالٍ ويحتضن إيه-مي 01.",
[2962567674]="لكن يوثَر، إذا كان هناك أي أمل في الوصول إلى آرثاس. أنا... يجب أن أحاول.",
[2962580790]="نحافظ؟ لماذا؟ لا حقيقة فيها. لا لا لا... فقط في الأخذ! أرى ذلك الآن!",
[2962618944]="امسح الرجل... هل لديك مشكلة مع ذلك؟",
[2963161698]="السيد سيكون معك بعد قليل.",
[2963239317]="هذه... العملية... كلها... تم اختراقها!",
[2963260483]="هل تعتقد أن هذا سيجلب بعض الإجابات؟",
[2963282435]="أخيرًا أظهروا رحمة! أعطونا شيئًا لنشربه!",
[2963444090]="ثلاثة هتافات لـ$N! هذه الأرض ستكون لنا مرة أخرى!",
[2963502208]="مهرجان نار منتصف الصيف هو وقت رائع للاحتفال بالصيف!",
[2964006552]="أوه، لقد أحدثت فوضى...",
[2964127310]="لن يكون هناك سجن لك هذه المرة!",
[2964512721]="لسنا بعيدين عن مركز حماية البروتكتورات، $N. من هنا!",
[2964633350]="%s يرسل قبلة في اتجاهك.",
[2964847411]="قريبًا، سيرتوي عطشك للتدمير.",
[2965120971]="شكرًا لإنقاذي!",
[2965220549]="أخيرًا، أنا في المنزل...",
[2965609133]="أنتِ حرة في الذهاب، آنستي.",
[2965686680]="أنا آمرك بالانسحاب إلى السانويل مباشرة للمساعدة في تجهيز الدفاعات.",
[2965780835]="هل جئت لمخاطبة الرجال، سيدي؟",
[2965872439]="منفي إلى نيذر!",
[2965921782]="حسنًا، نعود إلى العمل.",
[2965931193]="كيف تجرؤ على سكب نبيذ السيد!",
[2966589089]="قد يكون أسوأ، كان بإمكان زوجتك الهرب إلى ستورمويند مع تاجر جبن!",
[2966823152]="هذا التعدي على تنين الأزرق قد تم تسجيله. سأستمتع أكثر بفصل طاقة الحياة عن جسدك!",
[2966872556]="سباق كالواك فيشينق انتهى! إذا اصطدت سمكة قرش، أحضرها لي خلال ساعة.",
[2967665824]="هاهاها، أنت تمزح، صحيح؟",
[2967745137]="نستعد الآن لحصار المدينة وتقديم مرتكبي هذه الجريمة التي لا تغتفر للعدالة.",
[2968271756]="فك هذا!",
[2968516374]="أسمع \"لكن\" في صوتك...",
[2968690349]="ولكن احذر، فليست كل قصص الحب تنتهي بسعادة، كما قد تكتشف. أحيانًا، الحب يلسع كالشوكة!",
[2968702061]="لن نثنى عن مهمتنا!",
[2968736169]="ليدي براودمور، الوارتشيف يقول الحقيقة. هذه المؤامرة دبرها فاريماتراس وقراند ابوثيكاري بوتريس. لم تكن من فعل الـهورد.",
[2968776306]="اقتل...",
[2969071375]="بدم الهاي بورن!",
[2969403497]="استمر، هذا هو الطريق!",
[2969628724]="...وانظر أين أوصلنا هذا!",
[2970849375]="توقف! عرّف عن نفسك فورًا!",
[2970975574]="%s يبدأ بإشعاع الضوء. احمِ عينيك!",
[2971033323]="هذا لم ينته بعد!",
[2971375585]="عزز دفاعاتي! أسرع، لعنة الله عليك!",
[2972355212]="ماذا يفعل؟!",
[2973334345]="كيف تجرؤ على المجيء إلى هنا؟",
[2973760733]="أعتقد أن هذا قد ينجح، لو كان لدينا عشرون شخصًا لإلقائها.",
[2973966153]="%s يدمر كل اللحم القريب!",
[2973986816]="من مصلحة الكون إعادة خلق هذا الكوكب إذا وجد تحليلي فسادًا نظاميًا. لا تتدخل.",
[2974131738]="لا تزعج هدوء المدينة. يجب الحفاظ على السلام.",
[2974434203]="يقظتنا أبدية...",
[2975427856]="أغبياء! هذه البيض أغلى مما تظنون!",
[2977206542]="حسنًا، الوقت مال والوقت يضيع! لنأخذ ذلك المشروب...",
[2977373295]="يبدو أنه مضى وقت طويل منذ أن أراحني أحد من منصبي.",
[2977679053]="%s يصنع توتيمًا جديدًا...",
[2978390309]="أحسنت. ضربة لأروقال بلا شك!",
[2978588436]="تتحدى كاو، مدمر الماموث؟! واجهني إذن واشعر برعدي!",
[2978707355]="كنت تبحث عني، أيها الطفل؟ لماذا أتيت لقتلي، $N؟ أنا فقط أريد المساعدة.",
[2978782405]="قضيت حياتي كلها أعتني بهذه الأشجار. أقلمها وأرعاها... من المناسب أنها انضمت إلي في الموت.",
[2978784737]="سنفعل، سيلفاناس...",
[2978811157]="ما معنى هذا الاضطراب؟!",
[2979163794]="هذه ليست معركتك أيها الدوارف. تراجع أو سنضطر لتدمير سفينتك.",
[2979568521]="هذا سهل جداً!",
[2979992119]="حاول أن تعتني بنفسك أكثر، كوين. كنت محظوظاً هذه المرة.",
[2980394725]="سينتهي كل شيء قريباً. قريباً ستكون في أحضان ما لا يجب تسميته!",
[2980562551]="لن تتدخلوا!",
[2980609104]="وداعاً أيها الأبطال.",
[2980774860]="%s يمسك بقطعة ويضعها في جيبه...",
[2981825686]="ملكة التنانين... مانحة الحياة... احفظيني.",
[2982030418]="ثوريم، يا سيدي! وإلا لماذا جاء هؤلاء الغزاة إلى محرابك إلا لقتلك؟ يجب إيقافهم!",
[2982449931]="%s يندفع للهجوم مرة أخرى!",
[2982522947]="سأفعلها، يا سيدي.",
[2983185194]="شكرًا لمساعدتنا ومساعدة جيم. إذا رأيته، أخبره أن جيمي الصغيرة وأنا نحبه وننتظره.",
[2983770584]="السلالة لن تسقط!",
[2983974077]="استخدم لماعاتي... اجعل الطقس جيدًا مرة أخرى... اجعل الأنديد يذهبون.",
[2984153545]="ابني، سيأتي يوم تقود فيه آشبرينجر، وبه، تنشر العدالة في هذه الأرض. ليس لدي شك أنه عندما يأتي ذلك اليوم أخيرًا، ستجلب الفخر لشعبنا وستكون لوردايرون مكانًا أفضل بفضلك. لكن، يا ابني، ذلك اليوم ليس اليوم.",
[2984290432]="أتساءل ما ذلك المخلوق الأرجواني الصغير في القرية... إنه جميل بالتأكيد.",
[2984604191]="كان يبحث عن قطعة أثرية... بوق، أعتقد. غادر القرية في رحلة طويلة للبحث عنها.",
[2985149538]="انهضوا، خدم الـنايتماير! انهضوا ودمروا هذا العالم! لا تتركوا ناجين...",
[2985158469]="قذارة الـسكورج! موتوا!",
[2985729386]="نور... نور ساطع جدًا...",
[2986469043]="أغبياء! تظنون أنكم منتصرون؟ لقد اقتربتم خطوة واحدة فقط من الهاوية!",
[2986861099]="ادفنوا هذا المكان! سيدكم يأمر بذلك!",
[2988333260]="يبدو أنكم لا تزالون بحاجة لمزيد من التدريب. ربما مرة أخرى.",
[2988584435]="هل فعلت؟ يا لورد أوثر، بحق حقي في الخلافة وسيادة تاجي، أعفيك من قيادتك وأعلق خدمة بالادنزك.",
[2988711616]="أوه، يا إلهي. هل تشعر بالندم على الأقل؟",
[2988794608]="أين ذهب الخنزير؟!",
[2988938798]="%s يستخدم قربان $N في طقوس...",
[2989013178]="%s يطبخ دفعة من أجنحة الباز الصيّاد الحارة لـ $N.",
[2989467829]="كينق جوكم، هل استدعيتني؟",
[2989850588]="ليس لدي أي فكرة عما يحدث هنا، لكنني سأنضم بكل سرور إلى قتالك ضد هذا الأحمق الوقح!",
[2990529550]="البوابة القديمة للحُرّاس تُفتح!",
[2990626966]="صحيح، صحيح... أعرف أن الإيرذن صُنعوا من الحجر لتشكيل المناطق العميقة من العالم. لكن ماذا عن الشواذ؟ عدم استقرار المصفوفة وما إلى ذلك؟",
[2990940342]="سرعة أواتانكا معك، $N.",
[2991075100]="يا سيدي، هل تعتقد أننا نستطيع الانضمام إلى الحفلة قريبًا؟ أنا أشعر بالملل الشديد هنا.",
[2991645139]="إنغفار لديه خطط لك، أيها الصغير.",
[2992632697]="تكلّم، أيها اللاجئ القذر! ماذا كانت تفعل قافلتك في أراضي العظام؟",
[2992751703]="أجل، افعلها! اصنع سلاحك الجديد البشع. سوف يخدمني أيضًا عندما تصبح روحك ملكي.",
[2992854618]="لقد كلفتني الكثير من العمل!",
[2992972500]="هذا لا يبدو جيدًا، يا فتى.",
[2993378614]="عرف الأسلاف طريقة لإرباك حواس العدو. يمكننا استخدام هذه المعرفة لاكتشاف ضعف الـسكورج أو ضرب قادتهم. بدون قادتهم، سيسقط الـسكورج أمام محاربينا.",
[2993602994]="حسنًا. لنرى إن كان بإمكاننا إنهاء هذا الحجر الأساسي.",
[2993783610]="آآآه... نصر مجيد آخر للـهورد!",
[2993801652]="افشل، وستصبح روحك عبدًا له إلى الأبد.",
[2994095796]="كان والدي محقًا بشأنك، سارثاريون. أنت حقًا ضعيف.",
[2994220834]="حسنًا، أليس هذا مقيمنا $Gطيار:طيارة;، $N. كيف الأمور، يا بطل؟",
[2994826773]="إنه يغلي ويحترق...",
[2995522343]="لا تعد، أيها الـدرايناي الحقير. في المرة القادمة لن ننجي حياتك، سواء كنت مسلحًا أم لا!",
[2995540455]="متى سيعود بابا من المعارك في وارسونغ؟ لقد مضى وقت طويل...",
[2995947342]="هل يمكنني اللعب؟",
[2996507486]="كف عن التذمر!",
[2997027519]="الانفجار بعد 5...",
[2997124290]="اخترت الأسبوع الخطأ لأترك الشرب!",
[2997601597]="%s يبدأ في إلقاء ديفايل!",
[2998513090]="أترى أكوام الغسيل ودلو الماء؟ سأنادي بما أحتاج بعد ذلك، وأنت تضعه في الحوض. مستعد؟",
[2999151317]="هذا الاجتماع لمجمع الحديد قد انتهى!",
[2999786693]="كل ترول لنفسه، مون!",
[3000659095]="لن تمنعني من الهروب من هنا!",
[3000735442]="هل أعجبك خلق تابعي البشع؟ قوي، أليس كذلك؟",
[3001190809]="%s يركض إلى سنده!",
[3001709997]="أبصق عليك!",
[3002476980]="لا يمكنك إيقافنا!",
[3002584663]="أتبرز عليك أيها الترولز!",
[3002764979]="كم هذا مروع! هل كنت عاجزًا تمامًا؟ ضعيف؟ هبات ساخنة؟",
[3004363376]="اذهب يا خادمي. أرسل خبر ستونيتالون إلى أبوتيكاري زاماه.",
[3004816803]="كونوا على حذر! آلات الخلد ستظهر قريبًا ومعها أولئك الدوارف الحديديون الأشرار!",
[3004946590]="%s يطلب المساعدة!",
[3004953828]="لن تنجح ما دمت أتنفس!",
[3004998407]="لا تجعلني أتعامل معك بقسوة.",
[3005687874]="مات صانع الأسلحة! استعدوا يا رجال، لدينا سكورج لورد لنقتله.",
[3006576645]="لسوء الحظ، كان دفاع النايت إلف غير قابل للصمود وعلم راجاكس أنهم لا يستطيعون الصمود لفترة أطول. لكن مثابرتهم كانت تسبب إحباطًا كبيرًا لراجاكس وتسبب المزيد من الإحباط لملكه. لحظة، ملوك؟ لا يُصدق...",
[3006616356]="المفارقة الجميلة -- قوات ستورمويند تُذبح دفاعًا عن مدينتهم، فقط لتنهض وتقاتل إلى جانب النقابة كأدوات دمار.",
[3006665081]="ماذا لدينا هنا... أولئك الذين يتحدون سبيل-ويفر؟ أولئك الذين لا يملكون بصيرة أو فهم. كيف أجلكم ترون؟ ماليقوس ينقذ العالم من نفسه! به! لا تستحقون وقتي!",
[3006701921]="%s يصفّي حنجرته.",
[3006708385]="أيها البشر الحقيرون! ستدفعون الثمن غاليًا.",
[3006842498]="الأسلحة جاهزة!",
[3007029160]="مرحى! نحن نحبك! لقد أنقذتنا!",
[3007424246]="اسم هاربك هو ميكجينير ثيرمابلغ.",
[3007434769]="ميلورد، مع الأسف أن جزءًا كبيرًا من نبلاء السيندوري قد سُحق، هل يعني ذلك أنك على وشك الحصول على ترقية قريبًا؟ أنا متحمس جدًا لأجلك!",
[3007809539]="إرسال الحامية مكتمل.",
[3007837404]="لدي التعويذة المناسبة لفتح هذا الباب. من المؤسف أن أبواب الزنازين لم تكن مقفلة بهذا الإهمال.",
[3007980385]="قوة دمعة الأقمار ملكي! ملكي، أقول!",
[3008702474]="حسنًا، من دفعني؟ هل كنت أنت، $N؟ أحدكم يشغل الأضواء مرة أخرى. *فواق*!",
[3008764598]="بفضل صديقك الصغير، غادرت معبد العواصف، حيث كنت في أقوى حالاتك. بدلًا من ذلك، نقاتل بالقرب من قوة سيدي.",
[3008955311]="إذًا، لقد كنت متواجدًا كثيرًا، لكن يبدو أننا نفوت بعضنا البعض دائمًا للقاء بعد العمل.$B$Bهل أنا المشكلة؟$B$B<تحاول خاتي ابتهاج نفسها عمدًا.>$B$Bعلى أي حال، أردت فقط أن أقول أنني... نحن نقدر حقًا كل ما تفعله من أجل حرس السماء!",
[3009024517]="إنها فقط مسألة... وقت.",
[3009170294]="تجمعوا، أيها الإخوة والأخوات.",
[3009586062]="تشغيل تشخيص المستوى الثالث...",
[3009633317]="ما هذا في الأفق؟ سفينة عدو بلا شك! أطلقوا النار!",
[3009880133]="جستين ثافيرات! رومان كيني! فريقنا الرائع للفن والأنيميشن بأكمله!",
[3010266859]="لن تهرب مني بهذه السهولة، آرثاس! سأنتقم!",
[3010735484]="من أجل سيلفرمون! من أجل سنسترايدر!",
[3011046289]="هجين عديم الفائدة! سأقتلهم بنفسي!",
[3011230423]="ها! هذا كل ما عندك؟ أنا مندهش أنك وصلت إلى القلعة أصلاً.",
[3011270360]="%s يبدأ بإلقاء البرق نوفا!",
[3011700282]="سنصل إلى السعة القصوى قريبًا.",
[3012693403]="دقيقة واحدة أخرى! اصمدوا الآن، الطقوس على وشك أن تبدأ!",
[3012780839]="ظننت أنك سترى النور، جودفري... تكلم بسرعة الآن، أيها الشرير. ماذا يقول؟",
[3013137536]="[أوركيش] نو'كو كيل زيل'نوك ها تار.",
[3013176865]="تجرؤ على سفك الدماء في أرض محايدة؟ اخرج! اخرج، أقول!",
[3013311654]="قلت وداعاً!",
[3014324285]="دماء؟ وهؤلاء الأوركس، هؤلاء الأصدقاء المزيفون؟ سيساعدوننا؟",
[3014566603]="هل سيعطي أحدهم قطتي الصغيرة بيتاً جيداً؟",
[3014855126]="ماذا... فعلت...",
[3015330878]="شخص ما يقتل كل الطرائد من تحتي. رقم 48 الذي حصلت عليه بصعوبة، هنا.",
[3017451074]="هل أنت جائع؟ أنا جائع. لا أستطيع تحمل فكرة شريحة لحم الخنزير المقدد من ثلتاش مرة أخرى. لو تمكنا فقط من الحصول على بعض من ذلك السمان المشوي اللذيذ!",
[3017751821]="آه، لقد بدأت أشتاق لأصدقائي على أي حال - لن يصدقوا هذا! أوه، خذ هذا، وجدته وأنا ألعب الغميضة.",
[3017822964]="فريكول، ملكك يتوسل إليكم أن تستمعوا!",
[3018520413]="الـليتش كينغ سوف يطفئ... كل... واحد... منكم.",
[3018794572]="آه، اللعنة! فخ ذكي. من المؤسف أنك لن تعيش لتروي الحكاية...",
[3019786287]="أيها الكلب الخائن!",
[3020562059]="أنا فقط لا أريد أن أخيب ظن أحد.",
[3020573844]="سكورج!!! اهربوا!!!",
[3020674936]="%s يفعل فرياز وارد.",
[3020859413]="%s يبدأ في صب تعويذة شوك فورتاكس المقواة!",
[3021742885]="%s يبدأ في أداء طقوس الإيقاظ على ناراليكس.",
[3021853205]="هذه ليست النهاية... الموت فقط... يقويني...",
[3022020995]="%s يلقي أجزاء الحيوانات في المرجل الفقاعي.",
[3022135803]="شيء غبي صغير. أنا أسحق!",
[3022290213]="أشك كثيرًا أن يكون لديه ما يقوله، أيها الغريب...",
[3022296808]="انتبهي لهم يا فتاة! لا تدعيهم يمسكونا!",
[3023217049]="هي ناق، ما رأيك تقطع لي قطعة من هذا...",
[3023355485]="تم تعديل هدف المطاردة. تغيير المسار.",
[3023608653]="لا أحد يستطيع الوقوف في وجه الـليجيون!",
[3023846390]="%s يتأكد من أن جسده سليم.",
[3024172543]="يمكنك تحسين الطقس أيضًا؟",
[3024562257]="المجد لـ$N، $C ذي قيمة!",
[3024580756]="لكن إذا كان وجودي مطلوبًا في هذه الألعاب لكسب دعمكم في المعركة، فسأبقى. في الوقت الحالي.",
[3024832229]="كيف تجرؤ!",
[3025329287]="%s يشارك قوته مع إخوانه.",
[3025932927]="أحب رائحة النيثر في الصباح.",
[3026013544]="كان والدي يعتقد أنهم جميعًا هالكون... ولكن خلفه، دوى هدير غاضب عبر الثلج، فالتفت ليرى جبل الدوارف يكبر حجمًا، جلده يكتسب ملمسًا حجريًا، ويداه تشتعلان بالبرق.",
[3026935778]="تعامل مع هذه المقاطعة، كيلدونس. بعد أن تنتهي، أحضر لي رأس من يدعونه $N. سأزين غرفتي بجمجمة $Gخاصته:خاصتها;.",
[3027032027]="المعلومات التي تبحث عنها... لا أستطيع إعطاءها لك مجانًا. سيكون عليك أن تثبت أن أعداءك هم نفس أعدائي.",
[3027491903]="أرى... ظلامًا فقط.",
[3027511590]="بضائع للبيع! بضائع للبيع! تعالوا وتصفحوا بضائع أنطونيو قبل أن أرحل، يا مواطني غولدشاير.",
[3027892714]="صلبوا عقولكم واحرسوا أفكاركم. الأجنحة المظلمة ستغيم وتستهلك عقول الضعفاء، سرب من العبيد الذين لا تغادر أقدامهم الأرض أبدًا.",
[3027956848]="حسنًا، لنصنع هذه الكرة...",
[3028605754]="سأبدأ بسحب الطاقة من الحجر. وظيفتك، $N، هي الدفاع عني. هذا المكان ملعون... ثق بي.",
[3029162214]="الحياة لا معنى لها. في الموت نُختبر حقًا.",
[3029820856]="الساندفيوري يسودون!",
[3029953037]="كان شعورًا قويًا وأنا أستمع لخطبتك، وهو يدفعني للجنون!",
[3029993565]="روكيت الحزمة معطلة. اقترب من زافود بومبوكس لإعادة تفعيلها.",
[3030006359]="اترك معاركك أو مهامك، وتصفح بضاعتي الرائعة! فقط في داركشاير لفترة قصيرة... الحمد للنور على ذلك.",
[3030377795]="يجب أن آخذ الترام إلى آيرونفورج وأزور غريت فاذر وينتر.",
[3030430905]="ألا تذكرني؟ عندما كنت طفلاً كانت والدتك تتركك في رعايتي بينما كانت تخدم في معبد القمر. كنت أحملك بين ذراعي وأطعمك العسل وحليب الغنم لتهدئتك حتى تعود. كنت ملاكي الصغير. اللعنة على الـسكورج... ماذا فعلوا بك، $N؟",
[3030738981]="سكادي الـ روثليس في نطاق قاذفات الرماح!",
[3032884893]="اللورد إيليدان سيصل قريبًا.",
[3033049215]="كدنا نصل... لا تستسلم!",
[3033086545]="ليستا، استدعي... الوحش!",
[3033123854]="اهجموا عليهم!",
[3033125018]="إما طريقتي أو طريق الذهب. هل هذا واضح؟",
[3033492352]="سيدي سيغضب حين يعلم بهذا الكمين. لنأمل أن موتك سيرضيه.",
[3033968919]="لن تطردونا من المدينة أبدًا يا بلطجي سيلفر كوفينانت!",
[3035161283]="البرج الشرقي فروست وولف دمره الأليانس!",
[3035928669]="باسم النور! النور هو من يأمرك! النور هو من قذفك إلى أعماق الظلام!",
[3036879778]="حصار النيروبيان بالخارج مرعب، ساقاي. يبدو أنه لا نهاية لهم.",
[3037072239]="وقتك أوشك... على الانتهاء.",
[3037712512]="انظروا إلى إبداعي المثالي!",
[3037966545]="لنر كيف ستصمد عندما تنقلب حياتك رأسًا على عقب.",
[3038412619]="أنا فضولي جدًا لأرى ماذا ستفعل هذه العينة من الماء!",
[3039206533]="لدي فكرة. لنزرع هذه الشظية في الأرض ونرى ماذا سيحدث.",
[3039457793]="بسرعة! سممهم جميعًا بينما لا يزالون قريبين!",
[3039724123]="كابتن هيليوس، لقد تم إنقاذي من سراديب أماني. أبلغ عن الخدمة يا سيدي!",
[3039747302]="حان الوقت للعودة إلى المتجر...",
[3040260908]="همم... أعتقد أن أحد تلك الذئاب عاد...",
[3040460756]="أيها الفم البغيض، أيها الرحم الموت، أنا أجبر فكوكك الفاسدة على الانفتاح!",
[3041125050]="آه! النجدة! نوم مجنون يحاول قتلي!",
[3041134308]="أفترض أنني يجب أن أكون ممتنًا. من فضلك، خذ هذا. لا أريد شيئًا يذكرني بهذا المكان.",
[3041325347]="لقد كانت رحلة ممتعة حقًا.",
[3041762999]="لا أثر لشحنة المتفجرات النهائية إلى الغرب أيضًا. أين هؤلاء المتسكعون؟",
[3041973181]="اسمعني، $Gيا أخي:يا أختي;. يجب أن تقاوم سيطرة الـليتش كينغ. إنه وحش يريد أن يرى هذا العالم - عالمنا - مدمرًا. لا تدعه يستخدمك لتحقيق أهدافه. لقد كنت بطلًا وستكون بطلًا مرة أخرى! قاومه، مون! قاوم سيطرته!",
[3042286062]="سأحرق شوائبك!",
[3042595526]="أبقِ الجميع يعملون بكفاءة.",
[3043227608]="نحتاج بعض...",
[3043262286]="اهجمن، يا أخواتي! يجب ألا يهرب الترول!",
[3043302974]="اللعنة! يبدو أن مستخلص بلودثيستل هذا لا يريد أن يمتزج بشكل صحيح مع سمي. لن أتراجع - سيتم التعامل مع هؤلاء الترولز! ربما خليط مختلف؟",
[3043792953]="مرحبًا، $N، ماذا يمكنني أن أقدم لك اليوم؟",
[3043853388]="تفضل، $N.",
[3043914296]="سوف أوصلك إلى أمبرباين لودج بسرعة يا حليف! بس لازم نوقف وقفة صغيرة أول...",
[3044021363]="أما بالنسبة لعدم تعريض الأختام للخطر خلال هذه العملية، يمكنني تحليل حالة كل حارس وإتاحة تلك المعلومات لك عند اكتمال الحسابات.",
[3044031590]="هل أنا موضع بهواة؟ أريد تحليلاً كاملاً للسلالة الجديدة بحلول صباح الغد! تحرك يا رافين!",
[3044606142]="نعم، رأيته يقاتل. إنه أورك - ضخم للغاية. خسرت راتب أسبوع وأنا أراهن ضده. لن أكرر هذا الخطأ!",
[3044781614]="|TInterface\\Icons\\Spell_Fire_Flameshock.blp:20|t|cFFBC0000 ارتفاع الحرارة |r|TInterface\\Icons\\Spell_Fire_Flameshock.blp:20|t",
[3045683818]="ماذا فعلت بأختي، أيها الإلف الحقير اللي ما عنده أم!",
[3045716755]="دا أماني دي تشوكا!",
[3046543827]="بقيت خلية أخيرة. نعم، أيها العظيم، فوراً!",
[3046744307]="أوتش! هذا ليس صحيح.",
[3047395973]="الشكل لم يكن لي بالطبع. ولو لم تكن متهورًا هكذا، لكنت رأيت ما وراء وهمي. لكنك وقفت بجانبي، ولهذا... يجب أن أشكرك!",
[3047538474]="أيها السادة والسيدات، أقدم لكم $N، حامل كويلديلار.",
[3048051527]="احترق في لهيب السيد!",
[3048668092]="فليعلم الجميع أنه كان شرفًا وامتيازًا القتال إلى جانبكم جميعًا.",
[3048759043]="آه... لا بأس. لا يزال يؤلمني قليلاً من المرة السابقة.",
[3048883893]="وأنا لا أعرف شيئًا عن نارك هذه...",
[3048952935]="تشوهاتك لا تقارن بالأليانس، بوترس! نحن قادمون إليك!",
[3048974053]="سيدي، تسلل أتباعنا إلى هيكل سلطة الأليانس والسيطرة عليه يسير على ما يرام.",
[3049255282]="دعم! نحتاج دعمًا!",
[3049592665]="ألجالون أُرسل هنا ليحكم على مصير عالمنا.",
[3050526000]="افعلها، $N! خلصني من عذابي!",
[3050669593]="طبعًا، بيج. فقط كن لطيفًا.",
[3050708777]="يا ضعفاء ستورمبايك، واجهوني في حصني - إن كنتم تجرؤون!",
[3050907944]="حاولت، يا سيدي. حاولت.",
[3051205159]="%s غضب وهاجم!",
[3051633443]="هي! هي! هي! إنه راليق الـ درنك... أمه سمينة لدرجة أنها ما ظهرت بس على غلاف مجلة أوقر اليوم...",
[3051920699]="أنا مدين لك بحياتي. سأعود إلى رفاقي وأنشر خبر شجاعتك. حارب الـسكورج بكل قوتك، وسنكون إلى جانبك.",
[3052026943]="رغم أنني أمضي بسلام، فلكم جميعًا امتناني الأبدي. شكرًا لتحريري من لعنة حماقتي وجشعي.",
[3052093874]="من أو ماذا كان ذلك؟",
[3052135373]="وهكذا ينتهي الأمر.",
[3052641785]="شكرًا! شكرًا لك، $Gبريست:برايستس;. الآن أستطيع مواجهة هؤلاء الونديغو والنور في جانبي!",
[3053084795]="بدلاً من ذلك، نحتاج إلى قوة ضاربة صغيرة ومركزة لنجاح الهجوم. لهذا السبب، أنشأنا الأرجنت تورنمنت.",
[3053085789]="$Gسيدي:سيدتي;، $N، نحن محظوظون بوجودكم معنا هنا.",
[3053494405]="لقد فشلت!",
[3054233423]="كان الأمر بسيطًا بمجرد أن كسرت روحها.",
[3054749597]="هاهاها.. <سعال>..آرغ!",
[3054968934]="احتمال... غير متوقع.",
[3055002781]="%s يلهث بحثًا عن الهواء.",
[3055321207]="اندفع القزم إلى الأمام بصوت يشبه الرعد المتدحرج وألقى بمطرقة معدنية لامعة، والبرق يعلو سطحها، مباشرة في حلق الجورمونغار.",
[3055467629]="ثرال؟ لقد كنت عبدًا للماضي فقط، أيها الحفيد! ولكن لا مزيد! عندما رأيته آخر مرة، أخبرني دوروتان الاسم الذي سيعطيه لابنه الذي لم يولد بعد... كان... فخورًا جدًا...",
[3056018811]="مادي ماير ماقوت!",
[3056408389]="الآن لا يوجد سوى طريق واحد للخروج—أن تسلك الطريق الوحيد للملعونين.",
[3056657198]="سيدي... لقد... فشلت.",
[3056738092]="أنا لست مقاتلاً؟ لا أدري من تظن نفسك، يا سيد، لكن لدي حسابًا مع آرثاس ولن تقف في طريقي! أطلقوا كل المدافع! أطلقوا! أطلقوا!",
[3056811652]="قل من فضلك.",
[3058087381]="لا، ذاك! ذاك! أمسكوا بذاك!",
[3058279493]="هي! لا مزيد من البوميرانغ! أنا آسف! أنا أعمل!",
[3058637367]="الـليجيون سيلتهمكم جميعًا!",
[3058933776]="ستعرفون أعمالنا قريبًا. كور'كرون، افنِهم!",
[3059083812]="ماذا يحدث؟ انظروا!",
[3059322249]="أوتش! هذا يكفي، أنا أستقيل من تجارة الأهداف!",
[3059427224]="أوه، ما الأهوال التي تنتظر....",
[3059774820]="%s يطلب منك أن تتبعه.",
[3059795671]="هذا غير متوقع. الكيان الذي سحر هذا معروف لدي...",
[3059921384]="لقد انتهيت من التعلم! أجل! انتهيت تمامًا! داجيك سيتركك أنت والعمود الأحمر الشرير الآن.",
[3060053990]="عرقك مرض على العالم!",
[3060411245]="وليس هناك ما يمكنك أنت أو ذلك الأحمق، إيليدان، فعله لإيقافي! لقد خدمتماني كل بطريقته - دون قصد.",
[3060509023]="يمكنك أن تفعل أفضل من ذلك!",
[3061476731]="مرمرمرمرمرمرمر... مرمرمرمر؟!",
[3061807287]="أنا حر! روح الماء تعود إلى شعبي. ستمنحنا الحكمة التي نحتاجها للبقاء في هذه الأرض القاسية. أنا مدين لك، $N.",
[3061872288]="خلّي أسمع هدير المعركة!",
[3062147383]="%s يشم الإكسير ثم يبدأ بالأكل بنهم!",
[3062162386]="نيكرومانسي. اسمها نيكرومانسي. وأيوا، بقدرتي أن أباركك بهذه الهبة.",
[3062707138]="بان دور شوريل أران!",
[3062939542]="ماذا يحدث لي؟",
[3062995391]="أنت ميت، ليس مدفون. أرني أفضل ما عندك!",
[3063631337]="لقد أرجعت تدفق الزمن مرة أخرى. إذا فشلت في منع موت ثرال، فكل شيء ضاع.",
[3064600496]="صلِّ لأي آلهة تؤمن بها أنني لن أتحرر أبدًا!",
[3064659401]="ابقَ.",
[3065146315]="قذارة الأليانس! موت! موت!",
[3065204127]="أبي، لقد عدت!",
[3065388893]="هل أنت من قطع عشائي؟ هل أنت؟",
[3066851351]="حريتي لا تعني شيئًا إذا فشلنا في إنقاذ أورسوك. أسرع، $N.",
[3066935156]="أبير؟ هل هذا أنت...؟ أوه... أنا جائع جدًا، أبير! جائع جدًا!!",
[3067186155]="%s كاد أن يتحرر من قيوده!",
[3067205975]="حكمة العصور عليك، أيها $C النبيل.",
[3068360695]="هي! ابتعد عن ذلك!",
[3069046794]="مطر جهنمي يقترب! احتموا!",
[3069781930]="%s يتلألأ ويصبح غير ملموس!",
[3070407257]="ساعد في حمايتنا من هذه الرياح القاطعة، أيها الشتلة الصغيرة.",
[3070551937]="يبدو أنك لا تزال قادرًا على التغلب علي في قتال عادل، أيها الأخ الصغير.",
[3070656486]="صحيح، أعداؤنا لن يظهروا لنا أي رحمة.",
[3070990792]="%s يبتسم لكلمات الـهاي إكسكيوشنر.",
[3071444631]="تيتو! أوه تيتو، لا!",
[3071729987]="خططنا في خطر بالفعل. يبدو أن ماييف قررت أن تفعل الأمور بطريقتها الخاصة.",
[3072042283]="واو! عظيم حقيقي؟ نحن لا نعتقد حتى أن سو-ساي قد قابل عظيمًا حقيقيًا!",
[3072411266]="أنت بحاجة إلى بركة الأسقف. اذهب إليه قريبًا.",
[3072581017]="%s يبدأ في القناة من المقطر القريب...",
[3072988238]="مجول أورم أغن جيور!",
[3073102791]="امنحنا القدرة على معرفة الحقيقة. إذا كان قاتل يسير بيننا، أرشدنا في بحثنا عن العدالة.",
[3073973288]="هذا المسار الزمني انهار وتشكل من جديد. النتيجة كانت ستراثولم من الزمن الغابر. ما الذي يمكن أن يحدث بداخله؟",
[3074512782]="%s يفقد كل السيطرة على نفسه ويبدأ بمهاجمة الصديق والعدو على حد سواء!",
[3074644379]="حسنًا، يا صغير. ابقَ خلفي وستكون بخير.",
[3075476820]="سرب العناصر سيتغلب عليك!",
[3075704046]="دمرهم! دمرهم جميعًا!",
[3075735635]="إذا رأيت اليوميات، فأنت تعرف ما كنت أكتشفه. إبداعات التايتنز نفسها في حرب مع بعضها البعض!",
[3076108035]="شكرًا لك، $Gفتى:فتاة;. شكرًا جزيلًا.",
[3076689103]="هكذا تعرف أنها تعمل.",
[3077158804]="فكر، $N. فكر بالماضي. حاول أن تتذكر نوميريغان قبل تلك التروقز اللعينة! تذكر شعور مفتاح الأركلات، $Gأخي:أختي;. لقد كنت بطلًا من النومز يومًا! هذا ليس أنت.",
[3077314729]="خطوة أخرى نحو الدمار!",
[3077695171]="خذني معك، $Gسيدي:سيدتي;.",
[3077702807]="كنت أعرف أن لورييل سيرسل المساعدة! شكرًا لك يا صديقي، واشكر لورييل مني أيضًا!",
[3078370104]="أبقِه ضعيفًا!",
[3078665712]="همم... بعد توصيل هذا، أعتقد أني سأتوجه إلى متجر الجبن لتناول وجبة خفيفة.",
[3078996786]="فشار! بيناوتز! بيرة!",
[3079311029]="من الجيد أن أراك أخيرًا أيها الساعي. لقد أوكلت إلينا كراسوس واحدة من النسخ القليلة المتبقية من كتاب الشفرات القديمة المصنوعة بتقنية التنانين.",
[3079330497]="أيها الحمقى! سأضع حدًا سريعًا لمعاناتكم!",
[3079368966]="غولز، اقتل هذا الهاي إلف الحقير!",
[3079685081]="%s طعن $N!",
[3079737555]="سأنتظرك مون.",
[3079817376]="لقد خيبت أملي، أيها الطلاب!",
[3080404597]="أنا غاضب. سأضربك في وجهك!",
[3080795447]="تعاملنا أسوأ من الحيوانات!",
[3081239169]="العينات... يجب الحفاظ عليها.",
[3081800493]="تضحية دليل على طاعتك. أنت بالفعل جدير بهذه المهمة. انهض، وكن معروفًا إلى الأبد بـ سفالا سوروقراف!",
[3082081387]="الأمور تسير كما هو مخطط.",
[3082648415]="%s يشرب العلاج الذي أحضره $N.",
[3082660903]="هل سينتهي الألم يومًا؟",
[3083042780]="موووووووووو!",
[3083333619]="سيدي! لا!",
[3083402207]="أنت ضعيف، لا حول لك لمقاومة إرادتي!",
[3083938138]="لن تذهب... بعيدًا.",
[3084103635]="كم منكم أيها الجنود أحتاج أن أعيد إلى أمهاتكم وآبائكم في أكياس جثث قبل أن تكبر عقولكم وتدركوا أن التوجه مباشرة نحو فرقة قتل من الـليجيون هو انتحار؟ ولا تومئوا برؤوسكم الغليظة نحوي وكأنكم تفهمون ما أتحدث عنه!",
[3084760327]="معركتك هنا ليست سوى ذرة صغيرة من غزو عالمي أيها الصغير! حان الوقت لتتعلم القوى التي تواجهها!",
[3084917025]="الجلد يحترق!",
[3085334538]="أبناء هودير! أقدم لكم بتواضع....",
[3085482042]="دارو شاير، إلى السلاح! الـسكورج يقتربون!",
[3085872002]="إذن من هم هؤلاء الناس؟",
[3085957179]="اتبعني أيها الغريب. لن يستغرق هذا وقتًا طويلاً.",
[3086781579]="أنت من تحداني لمجرد نظرة. ما زلت أنتظر مقابلتي مع تيراندي.",
[3086884542]="ما شفت أحد منكم هنا من قبل.",
[3087178323]="قبيلة وينترسكورن ستنتصر!",
[3087229167]="كلام أحمق تقصد. الـهورد سيدمر الأنديد بدون مساعدتك يا هيومن، أو مساعدة ذلك الملك المغرور.",
[3087255651]="حياتنا ملك لك يا بلود نايت.",
[3087578596]="الموت يلتهمك...",
[3087652833]="دخلاء!!",
[3088247710]="ما تأخذ... أنا!",
[3088364720]="لكن يا سيدي...؟",
[3089422480]="...كان هذا رائعاً!",
[3089934214]="يمكن طردوا كل المزارعين الآخرين، لكن عائلة سالدين لن تغادر ويستفال أبداً.",
[3089958823]="لقد نهبت كنوزنا طويلاً. استعد للقاء قبرك المائي!",
[3090081739]="لنجد التالي.",
[3090776070]="وداعاً لك، ولتكن إيلون معك دائماً.",
[3090807277]="ما هذا... آه!",
[3090998676]="كفى هذا! الآن أستدعي غضب الكون نفسه.",
[3091305057]="سندفع ثمن خيانة الأليانس! لن ننسى أبداً، ولن نغفر أبداً!",
[3091595682]="قتل مجيد!",
[3092033877]="%s يصرخ طلباً للمساعدة.",
[3092064008]="%s تتثاءب بهدوء في كف يدها.",
[3092420151]="لن يتم إيقافنا!",
[3092432803]="الـريمينت أوف داليا سنتوتش يتلاشى...",
[3092479884]="هذا التايمواي في فوضى عارمة! لدينا عملاء في الداخل الآن يحاولون استعادة النظام. المعلومات القليلة التي لدي تشير إلى أن حرية ثرال في خطر. منظمة خبيثة تُعرف باسم إنفينيت دراغون فلايت تحاول منع هروبه. أخشى أنه بدون مساعدة خارجية، سيضيع كل شيء.",
[3092483579]="رائع! بفضل مساعدتك، أصبح لشعبي فرصة لاستعادة مدينتنا الحبيبة. ثلاث هتافات لك!",
[3092618000]="آآآإييييييييييييييييييييييي........................................",
[3092912100]="فقط استسلم ومت بالفعل!",
[3093463998]="لوكين لن يرتاح... حتى يتم استعادة الـفورج! أنت لا تغير... شيئًا!",
[3093601815]="إذن ضع ضعف الكمية في المرة القادمة!",
[3093749951]="هذا هو الجزء الذي أستمتع به أكثر...",
[3095071492]="مرحبًا، مرحبًا بكم في ملعب ستيم ويدل الذي تم الاستيلاء عليه مؤخرًا وإعادة تسميته بوقاحة!",
[3095096795]="هذا سيؤلم في الصباح.",
[3095118447]="شكرًا لك مرة أخرى، $N، على هذا البخور اللذيذ.",
[3095894319]="المجد لـ$N! حامي الشعب!",
[3096066198]="ستحصل على تحديك، فوردرينغ.",
[3096185224]="جائع جدًا...",
[3096193075]="%s يتلوى من الألم. يبدو أن التلميذ يخترق الحاجز.",
[3096195181]="...لإنشاء صندوق لشراء جل الشعر؟ أنا أحب شعري كما هو، شكرًا!",
[3096527318]="أفكر في إجازة. سمعت أن هيرثغلين جميلة.",
[3096610983]="%s يشتاق إلى...",
[3096841724]="هناك المزيد.",
[3096863115]="هذه قاعات مقدسة! اقتحامك سيقابله الموت!",
[3097043644]="حسنًا. فلتبدأ اللعبة.",
[3097713995]="الـهورد خسر أندرسِتي.",
[3098023040]="مقاومة متوسطة كهذه...",
[3098230075]="أعتقد أن أحد أسباب حبي لصيد كبار اللسان... أنهم ليسوا أغبياء مثل الصيدات الأخرى. يعطونك معركة حقيقية.",
[3098646372]="رأيت ذلك؟ إنها... ضخمة!",
[3098796477]="الأخبار من ستورمويند لا تبشر بالخير...",
[3098929523]="شكرًا لك، $N. يبدو أنهم سينسجمون جيدًا.",
[3099713120]="%s يضع رأس مارغ في المرجل.",
[3100018206]="كارنيج! هل لي أن أريق دمًا باسمه!",
[3100263008]="انتظر... أنت لست زوجي. لكنه لا بد أنه أرسلك. وأنت... تبدو... لذيذًا!",
[3101013951]="الـغراند كروسيدر كلفني بتدميرك وتدمير أصدقائك الجدد، تايلان، لكن اعلم أني أفعل هذا للمتعة، لا عن التزام أو واجب.",
[3102711438]="لا مكان لك هنا! مكانك... بين الراحلين!",
[3102878666]="هذا هو ثمن الفضول.",
[3102935198]="$Gسيد:سيدتي; $N، يا لها من مفاجأة سارة، $Gسيدي:سيدتي;.",
[3103010846]="هذا لا يبشر بالخير!",
[3103221286]="أبقهم منفصلين عن قوتهم الرئيسية!",
[3103620169]="كان موضعًا بالكوابيس، مالفوريون. ماذا يحدث في الحلم؟ ما الذي قد يسبب مثل هذه الفظائع؟",
[3104172677]="لقد هلك المستهلكون. فليكن! الآن سأنجح حيث فشل سارجيراس! سأنزف هذا العالم البائس وأؤمن مكاني كالسيد الحقيقي للـبيرنينغ ليجيون! لقد حانت النهاية! ليبدأ تفكك هذا العالم!",
[3104930842]="ليس لديك فكرة عن الأهوال التي تنتظرك. لم تر شيئًا! قلب ناكسماراس المتجمد ينتظرك!",
[3105014349]="%s يلتقط صدفة بحرية.",
[3105155000]="سيء، $N. $N، سيء!",
[3105287269]="الأليانس استولوا على منجم كولدتوث! إمداداته ستُستخدم الآن للتعزيزات!",
[3105443379]="الملك فاريان، ليدي جاينا. مرحبًا بك في البطولة. مكانك في الكولوسيوم بانتظارك.",
[3105974961]="ما هذه القوة التي تتدفق في داخلي؟ هل هذه هي قوة الشامانية التي تحدث عنها تورقان...؟",
[3106942837]="يا للروعة! دميتي!",
[3107178926]="هل أنت متأكد أنك تعرف كيف تطير بهذا الشيء؟ يبدو مهتزًا بعض الشيء.",
[3107460516]="لقد أريتني حقائق لم أكن لأعرفها أبدًا. أنت وحلفاؤك منحتموني شيئًا لا يمكن أن يحمل ثمنًا: الفداء. ثرال، مخلص الماغهار، لقد كرمتني كما لم يفعل أحد من قبل...",
[3107530216]="تقنية منخفضة، لكنها فعالة جدًا.",
[3107930390]="خاتم المراقب ميميرون مرتبط بآلية تدمير ذاتي متصلة بكامل ممرات البراعة.",
[3107981202]="لقد أنقذتنا! مرحى لك!",
[3108359611]="%s تم شفاؤه!",
[3108823249]="%s يبدأ في استدعاء ميثاق التوأم!",
[3108924104]="الآن يظهر المحسنون لديكم، لكنهم تأخروا! القوى الموجودة هنا كافية لتدمير العالم عشر مرات. ماذا تظنون أنهم سيفعلون بكم؟",
[3109179288]="أتباع الميزان، استجيبوا لندائي!",
[3109997647]="من يحتاج حُراسًا؟ $N هنا!",
[3110015565]="كل شيء يؤلم. أرجوكم، أوقفوا هذا...",
[3110067918]="جيش بلاكروك قادم، أيها الأقزام! سنحرق الأرض ونشعل النار في السماء. لن ينجو أحد...",
[3110468721]="أنا... مُحطم...",
[3111496285]="يجب أن نكون على أهبة الاستعداد. لقد واجهت الأنديد من قبل. إنهم آلات قتل لا ترحم، خالية من أي عاطفة أو شفقة.",
[3112727708]="%s غاضب!",
[3113061561]="راقب مؤخرتي! سأرى ما يمكنني إيجاده في هذه الخردة...",
[3113856068]="%s يغضب!",
[3113932395]="في الوقت المناسب. لننهِ هذا الشيء.",
[3114202833]="سأسحقك تحت قدمي!",
[3114253130]="آه... مرحبًا بك في صالوني.",
[3114449993]="انهض! لم تعانِ بما يكفي.",
[3114684563]="نوزاري، أنا لا أتحدث عن ساحر طماع يبحث عن تحسين مكانته في الحياة بإجراء تعديل صغير على الماضي.",
[3114848979]="أرواح الرياح، احملي إلى سورفانغ الأصغر أغنية الحرب! ليُثأر لكل إخوتنا الساقطين بهذه المعركة!",
[3115188855]="بقوة البوق، أربطك بإرادة حامله!",
[3115403604]="دخلاء! لا تدعوهم يدخلون إلى الحرم!",
[3115608798]="هذا؟ هذا أنا أتحكم بك. هذا أنا أحقق انتقامي الأخير!",
[3115998824]="حراس الملك سيأتون قريبًا لاستلام النصب التذكاري. في هذه الأثناء، تعال وانضم إليّ في الطابق العلوي ودعنا ننهي محادثتنا الصغيرة، $N.",
[3116069562]="مستر فلوبي، أنت بخير! شكرًا جزيلاً لإنقاذك مستر فلوبي!",
[3116257341]="شكرًا لك أيها الشامان. لقد ولدت من جديد وسأشتعل أكثر من أي وقت مضى!",
[3116942965]="الشامان فيكجيك يركض باتجاه تلة فرينزي هارت.",
[3117393696]="هذا ليس ممتعًا...",
[3117508094]="المقاتل التالي لا مثيل له في شغفه بالدفاع عن النور. أقدم لكم أرجنت كونفسور باليتريس!",
[3117584872]="هذه الأنفاق التي تراها تُسمى مسارات الزمن. إنها لا نهائية في العدد. تلك الموجودة حاليًا في واقعك هي ما اعتبره السيد 'نقاط مشكلة'. قد تختلف نقاط المشكلة هذه تمامًا في الموضوع لكنها دائمًا تشترك في سبب واحد. وهو أن وجودها ناتج عن نفس الاضطراب الزمني. تذكر ذلك إذا دخلت إلى أحدها...",
[3117629867]="الأرواح تغني لنا! إنها تغني أغنية المعركة!",
[3118952365]="كليمنس، بارثولوميو، إنديرمان، وايلز...",
[3119578440]="يومًا ما، سنحكم هذا المعبد المظلم.",
[3119673977]="لقد اختفى. لا أصدق أنه اختفى. من كان يظن أننا سنُخان بهذه الطريقة؟",
[3119731170]="أعرف، يا أختي. أعرف. سنعود للقتال يومًا ما. لكن الآن، ربما من الأفضل أن ننشر الكلمة للآخرين... نمنحهم الأمل الذي لديك.",
[3120471273]="تظن أنك ربحت بالفعل؟ ربما تحتاج درسًا آخر في الألم!",
[3120489848]="إزعاج بسيط.",
[3121071748]="ما إن يُقال حتى يُفعل، يا سيدي.",
[3121074411]="دمرّوهم، يا رعاياي!",
[3121532639]="شكرًا لك، $N. الآن، لأجري الاختبار...",
[3121585979]="آه، لكنك أنت من يتعدى على أراضي سيدنا. يمكنه أن يمحوك في لحظة لهذا التعدي وحده! آرثاس لا يملك الكثير من الحب أو الصبر لعبيده الهاربين.",
[3121729907]="شكرًا... لك...",
[3121900984]="ولا سلام لصديقك القديم، نارين؟ مين كنت تتوقع؟",
[3122057217]="الأليانس استولوا على قلعة وينترقراسب!",
[3122220235]="دخلاء دخلوا منطقة السيد. أطلقوا الإنذارات!",
[3122263878]="باتشيز لن يُقطع أو يُخاط بعد اليوم!",
[3123128129]="خلصت! والنتائج رائعة. لازم أوصلها لزملائي غريماند، ماثيل وكلوكمورت!",
[3123325844]="أستطيع إكمال بقية الطريق وحدي، $N. شكرًا!",
[3124074599]="%s يصرخ من الألم أثناء إزالة الحربة.",
[3125038150]="اتركني.",
[3125069464]="أيها الإنشاءات، دافعوا عن العاصمة بأي ثمن!",
[3125647102]="تفضلوا! أفضل تشكيلة أسلحة في هذه الناحية من أشنفال!",
[3125934569]="سأحتاج لتركيز طاقتي على هذه السكين. بذلك، سألتقط بعض الانطباعات النفسية الأقوى المرتبطة بها.",
[3126236634]="فقط جربها، وستفشل!",
[3126241150]="أعتقد أنني بدأت أتقن هذا.",
[3126555963]="قلوري للمعلم!",
[3126650672]="لقد نجحت! أحسنت يا $R. والآن اعذرني، يجب أن أدخل بقية فريقنا إلى الداخل.",
[3127316397]="لقد كانت... حياة بعد موت تستحق.",
[3128046559]="إذن يجب أن أعتبر هذا خيانة.",
[3128195058]="حريتك ستكون قصيرة الأمد يا آيسميست!",
[3128480176]="اثبتوا في مواقعكم!",
[3128507415]="ألا تتذكرني؟ كنا بشرًا ذات يوم - منذ زمن بعيد - حتى سقط لوردايرون بيد الـسكورج. تحولك إلى سكورج زومبي جاء بعد تحولي بفترة قصيرة. بعد ذلك بفترة، تحررت عقولنا على يد الدارك ليدي.",
[3128719846]="ريديان، تأكد من إخبار بران وآرتش ميج بنتاروس عن تلك الدفاعات فورًا.",
[3129544794]="%s ضعيف!",
[3129595375]="شكرًا، $N! كم مرة أنقذت حياتي الآن؟ ثلاث؟ هذا يجعلنا إخوة دم في كتابي!",
[3129970673]="جارٍ التحقق من مفتاح التشفير...",
[3130152407]="هل كلفوا أنفسهم إخبارك من أنا ولماذا أفعل هذا؟",
[3130184871]="لن أفشل!",
[3130540757]="كما تأمر، أيها المدرب!",
[3131112745]="دعني أقدم لك إخوتي الجدد: الناب والمخلب!",
[3131246942]="جهزوا محرقة جنائزية! $N تحدى سكاي شاتر!",
[3131655255]="...أم أنهم فقط يستغلونك مثلما يفعلون مع الجميع؟",
[3131752630]="ماذا تعرف عن الالتزام، يا شيت-سا؟",
[3132349588]="أختي! الرجال الأشرار كانوا بياخذوني لبادمون آيل. كانوا يبون يحولوني لواحد منهم.",
[3132927863]="باعترف، يا دوارف، فاجأتني بسرور بنجاح خطتك.",
[3133843016]="الرب الظلام يضحك عليك!",
[3134030383]="كيف فات هذا الشيء؟!",
[3134404770]="نعم، نعم، أنا رجل المافن. أتعرف لماذا؟ لأنني أبيع المافن، لهذا السبب!",
[3134426986]="%s يجلس.",
[3134649090]="الآن، لأضع المادة المعادلة عليها...",
[3135897108]="بورتال كيبر يخرج من البوابة!",
