[3196928243]="تور أوف ذا بروتال سيج، امنحني قوتك!",
[3197491877]="والآن لأجد هاربي غافلة!",
[3197568255]="يجب أن نكون يقظين للقضاء على هذا الوباء!",
[3197652697]="أوه، بالتأكيد يا إليسارا. لكن أرجوك، هل يمكنك إظهار القليل من الصبر؟",
[3197697983]="الآن ابق عينيك مفتوحتين! سأنهي هذا في غمضة عين--",
[3197953783]="كل هذا خطأهم، جيش الأليانس الغبي. كان عليهم بناء أبراجهم خلف مزرعتي مباشرة.",
[3198102198]="آخر قطعة قش...",
[3199834812]="في البلاجولاندز، هُزم كيل'ثوزاد مرة أخرى على يد عملاء الفجر الفضي. لكن تم تسليم فيلانكتيري إلى عميل مزيف للنقابة. لم نكتشف بعد من سرق فيلانكتيري أو لماذا.",
[3200303584]="بووم! هاهاهاها...",
[3200331269]="حان وقت سياج جديد!!",
[3200716044]="إذن كانت هذه هي المشكلة؟ الآن أنا أحرز تقدمًا...",
[3201196578]="الموت هو العلاج الوحيد!",
[3202071363]="الآن ارقصوا معًا!",
[3202153694]="المهمة أنجزت!",
[3202303537]="همم، هل يعبثون بالمسارات الزمنية؟",
[3202339047]="بحماقة سعيت إلى زوالك.",
[3202532407]="%s يستدير نحو الهدف الورقي...",
[3203034894]="مافرين، لا أريد أعذارًا، أريد نتائج! الفارسترايدرز غير متاحين وقد حصلنا على كل ما سنحصل عليه من سيلفرمون الآن. لا يمكنني تجاهل ترولز شادوباين وزولأمان... إنهم منتشرون على حدودنا الشرقية!",
[3203101835]="الرد ضبابي ورطب قليلاً. جففه جيدًا وحاول مرة أخرى.",
[3203371325]="مرحبًا هورنيز! لقد عدت! وهناك بعض الأشخاص خلفي ساعدوني في الخروج من مأزق.",
[3203470154]="لا شيء سيمنع هلاكك!",
[3203509247]="إيونار، خادمك يحتاج المساعدة!",
[3203723965]="لقد أمسكت برجل! الآن انصرف!",
[3204472694]="ماذا لديك في ذلك الغليون، نات؟",
[3204689463]="اهجموا واجعلوهم يدفعون الثمن غاليًا!",
[3205440137]="شكرًا، شكرًا! حان الوقت للابتعاد عن هؤلاء النساء الزرقاوات المجنونات!",
[3206149866]="انظر فوقك؛ ثارا دورميل دورا...",
[3206246195]="ما أحتاج لعظام لأهزمك!",
[3206327956]="ماذا يحدث هنا أيها الرقيب؟",
[3206598614]="غرااااه! شاهدوا غضب الحديد والفولاذ!",
[3206666928]="يبدو أنك قرب محطة إصلاح! قد مركبتك على المنصة، وستُصلح تلقائيًا.",
[3206789551]="%s يتحول إلى ماموث!",
[3206892812]="انتبه لخطوتك هناك. كثير من مغامرين لم يعودوا من المستنقع. هيك!",
[3207115537]="لا، يا فتاة. آرثاس ليس هنا. آرثاس مجرد حضور داخل عقل الـليتش كينغ. حضور يتلاشى...",
[3207177462]="ماذا تريد مني أن أفعل، داريون؟",
[3207406118]="اقتلوهم باسم السيد!",
[3207488565]="مت يا كلب الـسكورج! مُت!",
[3207606075]="هناك شيء أخير. أحتاج أن أعرف أين أرغال.",
[3207721364]="الأرواح امنحني القوة! خذ من روحي هذه الجروح القديمة واكشفها للجميع! دع هذا الطفل يعرف والده! دع هؤلاء الناس يعرفون منقذهم!",
[3208782398]="%s يعود إلى الغيبوبة.",
[3209904233]="هاهاها! ذلك الأحمق لن يكتشف أبدًا ما أخطط له! أو، إذا اكتشف، سيكون الأوان قد فات بالنسبة للدرايناي!",
[3210713677]="هل نبدأ يا صديقي؟",
[3211007817]="%s يهرب بعد رؤية كيلثوزاد يسقط!",
[3211176185]="تم تجنيدهم من عرق الموارغ، وهؤلاء المحاربون يخدمون كجنود الصف في الـليجيون.",
[3211409375]="لن تغادر هذا المكان حيًا أبدًا.",
[3211531667]="نومز نوميريغان يهتفون لـ$N.",
[3211754900]="أعتقد أنها تحتاج...",
[3211827482]="$N، لنذهب ونرى إن كانت هذه الخطة ستنجح. تعال معنا، بادي!",
[3211860458]="توقف عن العبث بمشاعري!",
[3211977587]="مخلوقات هذا المكان قوية، أيها المسافر. ستحتاج إلى ذخيرة وافرة إذا أردت البقاء. أنت محظوظ — فأنا مخزون جيدًا بالسهام والرصاص وأسلحة الرمي. السعر معقول بالنظر إلى الظروف.",
[3212149796]="كفى. لقد كنت بعيدًا عن هذا لقرون. قد يكون البئر داخل هذا المعبد شبحًا شاحبًا لبئر الأبدية، لكنه لا يزال يحمل نفس... الجمال. النقاء.",
[3212508112]="%s يرفض الموت بينما سيده في خطر!",
[3212553683]="بوابة القمر الأصفر تتعرض لهجوم!",
[3212591444]="أين أنا؟ من أنت؟ أوه لا! ماذا حدث للسفينة؟",
[3212668113]="هل تشعر بالحرق؟",
[3212771599]="ليتني أتذكر كم من تنين اللانهاية سيحاول إيقافك. هذه المعركة كانت منذ زمن بعيد.",
[3212893036]="أنا حقًا مدين لكم، أيها الغرباء.",
[3212894276]="بقي واحد سينتريفوج كونستركت. يجب أن نجده وندمره لتعطيل درع فاروس كلاودسترايدر الواقي. يجب أن يكون البناء في منتصف الأوكيولس تقريبًا، على حزام التسارع.",
[3213171250]="اقطعوهم يا إخوة!",
[3213197047]="أوه، أوه، أوه! أستطيع رؤية هذا بوضوح... لا، فقدته.",
[3213350279]="فيك'لور، أشعر بألمك!",
[3213523952]="حاولت جاهدًا أن أخبر جيم... أن أخبر أي أحد... من كان وراء هذا، لكنني لم أجد طريقة...",
[3213832367]="ألف مثله موجود. عشرة آلاف. إن سقط واحد، سيقوم آخر ليأخذ مقعد السلطة.",
[3213978047]="هذا الضوء الأزرق... غريب. بماذا تعتقد أنه يرمز؟",
[3214267987]="لهب! موت! دمار! اخضعوا أيها البشر لغضب السيد... لا - يجب أن أقاوم هذا! ألكسترازا ساعدني، يجب أن أقاومه!",
[3214672678]="أيها المدافعون، أظهروا لهؤلاء الكلاب غضب سكريِر!",
[3215589644]="تبدو متحمسًا للانضمام إلى سيف الحبيب، يا أخي.",
[3215624192]="منذ ألف عام، حارب الإلف الخالدون، وأنصاف آلهة الغابة، والتنين ضد الـليجيون على سفوح هايجال.",
[3215773621]="لا تقلق. هذا تحسين!",
[3215794067]="قذارة! قذارة في كل مكان! يجب تطهير الغابات!",
[3215884153]="نحن تحت الهجوم! استعدوا أيها القراصنة! اصدوا الغزاة!",
[3216026610]="تفعيل الإجراءات المضادة. صد المتسلل.",
[3216330997]="أنا... حسنًا، ربما أخذت شيئًا أو شيئين من النزل... لكن ما الذي يهم الأوغر بذلك؟",
[3216680459]="توسل من أجل حياتك...",
[3216698994]="ألثيا، هناك تقارير عن أحداث غريبة في المقبرة. إيلو تعتقد أنها تنذر بهجوم على داركشاير.",
[3216859223]="كيف يعجبك حيواني الأليف؟",
[3217050673]="سأضع عليك إكراهًا خفيفًا. اقفز إلى الأعماق أمامي لتضع نفسك في عنصري وبذلك تظهر خضوعك.",
[3217241836]="سنلتقي مجددًا... يومًا ما.",
[3217285126]="السفينة ليست جاهزة بعد. لا يزال علينا معايرة طول الفتيل للتأكد من أنه لا يحترق ويتركك وحدك هناك بالأعلى.",
[3217347860]="شكرًا لك، $R. سآخذ هذا الكلب البائس منك الآن.",
[3218498395]="أبخرة السارونايت تتجمع وتدور بعنف، وتندمج في شكل وحشي!",
[3218589366]="لا تقف هناك فقط! ساعد $Gإياه:إياها;!",
[3219123900]="اترك أراضي ستونمول الآن!",
[3219487988]="لن تمتلك أبدًا ما يلزم لقيادة أي شيء، أورباز، ولا حتى فيلقًا من الهياكل العظمية عديمة العقول.",
[3219578723]="أستطيع أن أشعر بهالة والدي. إنه بالتأكيد في هذا الاتجاه... تعال، $N.",
[3219769202]="كما ينبغي أن يكون...",
[3219785932]="رياح الشمال تلتهمك!",
[3220074747]="همم، أتساءل ماذا يوجد في هذا الاتجاه؟",
[3220161648]="%s تزمجر بانزعاج، وتحدق بسرعة في سينتينيل سويت سبرينق قبل أن تستدير بأنفها في الهواء.",
[3220933292]="لقد سئمت من هذا الهراء! استعد للموت!",
[3221003580]="%s يستمع إلى توسل $N.",
[3221553082]="%s يستدعي ازور رينق كابتن!",
[3221626028]="جارٍ تحليل حالة المراقب. انتظر من فضلك.",
[3221662587]="لم يتبق سوى القليل في العالم ممن يستطيعون تحضير وردة اليقظة، $N. من حسن حظنا أنني واحد منهم.",
[3222005727]="لقد انتهيت من فحص الجماجم، $N، وأنا مرتاح. يينيكو ليس بينهم...",
[3222041484]="ثم يصوب %s نحو الزجاجات...",
[3222180413]="%s، المصاب بجروح بالغة، يتخلى عن المطاردة.",
[3222224920]="الخائن لم يعد يسيطر علينا. سحره المظلم على روح أشتونغ تم تدميره!",
[3222573273]="مرحبًا بك في الفراغ...",
[3222679000]="أشكرك يا صديق دالاران.",
[3222829457]="كان هذا لعبة أطفال.",
[3223002296]="ماليغوس!!",
[3223394698]="لن ندع هذا العمل الجنوني يمر دون عقاب!",
[3224286206]="أرأيتم كم كان الأمر سهلاً عندما تعاون الجميع؟ خذوا ما تحتاجونه من الغسيل النظيف هنا، لكن لا تنسوا إعادته عندما تنتهون.",
[3224289130]="خسارة مأساوية...",
[3224921356]="لماذا لا يتحرك كايندريس ضد دار'خان بعد؟ ما الذي ننتظره؟",
[3224953192]="لقد قتلوا المئات! بالكاد نجونا بحياتنا! النجدة!",
[3225506311]="دع أسطورة ستالفان ترقد!",
[3225796766]="وقاحتك ستكون موتك!",
[3225980098]="هذه الأرض ملك لنقابة ديفياس الآن!",
[3226049248]="هذه الأسلحة لن تبني نفسها! أسرع!",
[3226565686]="ذراعي تؤلمني.",
[3226896925]="ستفعل كما آمر! أنا المسيطر هنا!",
[3227450325]="الوظيفة: جنود قياسيون",
[3227474670]="اخفض صوتك، هيلكيولار. هناك غرباء حولنا...",
[3228575405]="يبدو أن الخدم الميكانيكيين انقلبوا على بعضهم. عدة مرافقين تم تكديسهم معًا بطريقة غير منظمة.",
[3228587648]="[فوربولق] اشهد على الأعمال الوحشية لأعدائنا، $N. يسرقون صغارنا... ضعفاءنا... مسجونين هنا، تُركوا لأجهزة بريستليمب. أطلق سراحهم، أيها الموعود!",
[3229692334]="تدخل بيتي وتهددني؟ أعتقد لا!",
[3230062574]="انهضوا، أبطال النور!",
[3230334091]="%s يطلق صياحًا عاليًا!",
[3230572642]="ربما يجب أن نذهب إلى الجسر ونصطاد.",
[3231310991]="هذه الضرائب اللعينة تكسر ظهري. لا بد أن الملك تيريناس يفقد سيطرته إذا كان يعتقد أن كل هذا التعمير سينعش الاقتصاد.",
[3231590898]="لم أعتقد أبدًا أنها ستكون زيت مانا! سيكون هناك طلب كبير عليه، ناقص قريك بالطبع!",
[3231660150]="%s يصاب بسحر منفلت!",
[3232511213]="شكرًا لك على هذا التقرير، $N. أصبح من الواضح الآن أننا يجب أن نزيد دورياتنا بالقرب من ثيرامور.",
[3232775050]="لن أشرب دمًا قبل أوانه.",
[3232958876]="المحارة سلمت البضاعة!",
[3232993242]="أولئك جبناء.",
[3233064975]="مخاط سيربنت مبرد!",
[3233606962]="كيف يمكننا أن نرد لك هذا؟",
[3233960620]="ساعدوني! النجدة! قتلة في التلال! إلى السلاح! إلى السلاح!",
[3234157694]="الصقر مهزوم، محكوم عليه ألا ينهض أبدًا! مهمتك عقيمة!",
[3234216996]="فليكن كذلك. يجب أن أعود إلى شعبي، أيها الإخوة. عودوا إلي سالمين.",
[3234578706]="اطلب الغفران، إيرانيكوس. كل شيء سيُغفر...",
[3234736963]="سنقوم بتحليق سريع فوق كونكويست هولد لنرى ما يخطط له أولئك الـهورد القذرون. ابقوا أعينكم مفتوحة لراكبي الرياح لديهم. ليس أنهم سيستطيعون الإمساك بي!",
[3235590984]="اللطف البسيط، الأعمال الخيرية، خدمة المحتاجين. هذه كلها ثمار النور.",
[3235831298]="صدمة الصقيع!",
[3235848751]="تخلص من هذا التطفل بسرعة. ليس لدي وقت لهذا!",
[3236634761]="ماذا تفعلون؟ متسللون!!",
[3236779069]="سألتهمك بالكامل!",
[3236939603]="شكرًا لك أيها الفاني لتحريري من هذه اللعنة. أتوسل إليك، خذ هذا النصل.",
[3237026478]="ليس جيدًا بلا يوجد الكفاية...",
[3237330043]="أنظمة الدفاع الأمامية؟ هل هناك شيء يجب أن أخبر به بران قبل أن يحاول أي شخص دخول المجمع؟",
[3237972248]="يخرج أنين منخفض يائس من القفص الذي يحتوي على القزم.",
[3237994076]="نفد صبري! موت! موت!",
[3238086087]="هؤلاء الناس سيعرفون الأدميرال براودمور كالبطل الحقيقي الذي كان!",
[3238345626]="هذا الاكتشاف سيهز بلا شك أساس علم الآثار الحديث.",
[3238449238]="أنا أركض الآن!",
[3238627167]="عمل ممتاز أيها الأبطال! سنقيم معسكرنا الأساسي في هذه الغرف. سيجعل السحرة خاصتي جهاز نقل الـسكورج يعمل قريبًا. ادخل إليه عندما تكون مستعدًا لمهمتك التالية. سأقابلك في الجانب الآخر.",
[3239599432]="%s يبدأ بإلقاء بايروبلاست!",
[3239711042]="لقد انتهى حظك!",
[3239973780]="وقت المرح؟",
[3240783400]="ولكن ماذا الآن أيها البطل؟ ماذا عن أولئك الذين تحرروا من قبضته، لكنهم ما زالوا مقيدين بأغلالهم الفانية؟",
[3241004587]="أيها الأبطال، ساعدوني. أنا... لا أستطيع صدهم لفترة أطول. يجب أن تشفوا جروحي!",
[3241434690]="أوه، لقد بدأت الآن! ظننت أنني سأكون وحدي أيضًا، هاه؟!",
[3242157651]="آررغ!! لا يمكن أن يكون! كيف...",
[3242694440]="هذه التعويذة يجب أن تمسح ذكرياتهم عنا وعما حدث للتو. كل ما يجب أن يتذكروه الآن هو كيف سيكون الواقع دون التدخل الزمني المحاول. أحسنت. ثرال سيواصل رحلته ليجد مصيره، وتاريثا...",
[3242773517]="لابد أن هناك طريقة لجني المزيد من المال من هذه العطلة.",
[3242912615]="أنا متأكد، ماغني. سأكمل هذا، لا تقلق.",
[3242948937]="%s يستمع إلى تقرير $N...",
[3243195196]="كان ذلك نبيذ بوبيليفيربوس عمره 200 عام!",
[3243376832]="انظروا، مخلوق مرعب آخر ذو قوة لا تُصدق!",
[3243431758]="حان وقت نصيحة داجيك الذكية! إذا أطلق غوريجيك الدجاج مرة أخرى، اجعل غوريجيك يعيد الدجاج مرة أخرى.",
[3244009850]="جسر ثاندول سقط بيد راقناروس. هكذا سيسقط سد ستونرايت!",
[3244439757]="لقد جهزت بعض لوحات التحكم أسفل المنحدر. اذهب إلى واحدة بسرعة وتحكم في الفيل ريفر! سيكون لديك وقت محدود فقط.",
[3244487633]="ضاعف جهودك! الهجوم النهائي يقترب!",
[3244629147]="مهمة حمقاء $Gولد:بنت;... ستموت لمقاطعة عملي!",
[3244699401]="ها هي! هذه حقًا هي — كتاب الـريفن!",
[3244997962]="تصميم العصا بسيط. دارتول لم يستخدم معرفته السحرية في صنعها... إنها درويدية الطابع أكثر.",
[3245853989]="همم، ربما سأريح هذه العظام القديمة قليلاً.",
[3245977667]="ماكر ودقيق، الـراثغارد غالبًا ما يحمون أسياد الإيريدار التابعين للـليجيون.",
[3246530449]="اقترب أيها الشيطان! الموت ينتظرك!",
[3246547562]="أنت من يجب أن يعاني. اكتفِ بأن موتك سريع....",
[3247245738]="أعلم، كنا نظن أنه ميت أيضًا، لكن الأمر ليس كذلك. إنه يحاول استخدام بئر الشمس لجلب سيد الـبيرنينغ ليجيون، كيل'جادن، إلى هذا العالم.",
[3247279643]="هجوم! ساعدوني في إبعاد هذا الـ$N عني!",
[3247397791]="شكرًا لك! أنت طيب!",
[3247478495]="لم نكافح بشدة من أجل البقاء، فقط لنجلب الدمار الحقيقي.",
[3248155991]="هممم، حشو. حتى غير صالح للعمل في المحجر. استمتع بهذه اللحظات الأخيرة، فسرعان ما ستصبح مجرد أنديد بلا عقل.",
[3248214625]="حياتي فداء لك!",
[3248610406]="آها! ها هو ذا.",
[3249009728]="آآآه!!!",
[3249174417]="أشتاق لك كثيراً!",
[3249347770]="تعلمت بعض الحيل الجديدة... مثل أخي الدب...",
[3250032059]="يا نور، اهدِ الساقطين من الباطل إلى الحق، من الظلمة إلى النور، ومن الموت إلى الخلود.",
[3250421263]="أراكسيس! أرسل نجدة! أنا محاصر في المناجم. لست متأكداً أين أنا بالضبط لكنني تمكنت من ترك علامات على الأرض خلفي.",
[3250536152]="هل نزعزع استقرار الضريح أولاً أم نعطل العدو؟",
[3251047852]="أخشى أن شيئاً مظلماً قادم.",
[3251119760]="إنه لأمر محزن لأطفالكم المساكين.",
[3251715855]="كنت أنتظر سببًا لأمزقكم عظمًا عن عظم!",
[3252032507]="أعود! فرصة ثانية لأحفر جمجمتكم!",
[3252065460]="اتبعوني إلى الجبال لتنفيذ خطة السادة!",
[3252380946]="بيري قاتنر! يا له من عرض! الحانة مفتوحة طوال الليل، لذا تفضلوا واستمتعوا!",
[3252469850]="سيدي، أعتقد أننا كنا قريبين مع جذر الخمول في وصفة السم الأخيرة.",
[3252791127]="استخدم نفس التجميد، أيها الأحمق!",
[3253627764]="احتموا خلفي! بسرعة!",
[3253703330]="من؟ زعماء التاورن! ماذا؟ عرض حي! أين؟ حانة نهاية العالم! متى؟ على رأس الساعة! كونوا هناك!",
[3254037466]="الجميع يبدو مستعدًا. تذكروا، هؤلاء الناس جميعهم مصابون بالـسكورج وسيموتون قريبًا. يجب علينا تطهير ستراثولم لحماية بقية لوردايرون من الـسكورج. هيا بنا.",
[3254418301]="لا! كيف هذا ممكن؟",
[3254562914]="لن يأخذ هذا وقتًا طويلاً. فقط راقب ظهري بينما أفرغ هذه المجمعات الأثيرية.",
[3254761544]="ربما، لكن لو ضربتني على رأسي، سأعرف بالضبط أي مدفع سأستخدم لتفجيرها إلى أصغر القطع!",
[3254800865]="وهذا أيضًا...",
[3254856543]="سهل الرزق، سهل الذهاب.",
[3255324327]="سهل جدًا!",
[3255383689]="تريدنا أن نعيش مثل المتوحشين!",
[3255653806]="لن تغلق ماناتصني أيها الحقير!",
[3255813339]="أنت لست ضيفًا!",
[3255972611]="ألقوا أسلحتكم واخضعوا لقوة كيلجايدن!",
[3256283111]="إنها أنثى.",
[3256549668]="باستثناء بعض الصخور الشاردة من أولئك العمالقة، يجب أن نكون بأمان... لكن يبدو أن هناك فوضى بالأسفل.",
[3256586391]="تضرب كالفتاة. بصراحة. هل هذا أفضل ما يمكنك فعله؟",
[3256882680]="ها هو قادم...",
[3257277864]="مالتون، أيها الغبي!",
[3257296775]="وكأن ذكرياتي مغطاة بالضباب. لا أستطيع حتى تذكر ما حدث لأخي. هل هكذا تقصد أنه في خطر؟",
[3257506320]="سأسحق أوهامك بالعظمة!",
[3257536086]="أيها النادل، أين الـهاسنبفيفر؟",
[3257755180]="أراك، أيتها الحشرة! اقترب.",
[3258241954]="الأنديد سيتغذون على روحك، $N.",
[3258591488]="يميرون تعب. طويلاً جلست على عرشي وأمعنت التفكير في محنتنا. هناك إجابة واحدة فقط... سبب واحد...",
[3259178633]="دوائر %s الكهربائية تعطلت.",
[3259249679]="أوه لا! الملك مات! آه... تحيا للملك الجديد! أجل!",
[3259569585]="بيسي بنت جائعة اليوم، أليس كذلك؟ دعيني أجلب لك تفاحة.",
[3259669988]="لوك'تار أوغار! النصر أو الموت - هذه الكلمات هي التي تربطني بالـهورد! لأنها أقدس وأهم الحقائق لأي محارب من الـهورد.",
[3259928331]="هي، شكرًا.",
[3260314241]="سأرسلك على آلتِي الطائرة. ابق عينيك مفتوحتين بحثًا عن أدلة حول ما قد حدث لهيميت!",
[3260656033]="مسكين، هذا يفسر الكثير.",
[3260867129]="بلّغ سلامي لغريت فاذر وينتر، أيها الحقير...",
[3261135439]="اهرب!",
[3261211714]="إعادة",
[3261977973]="أيها الكذاب الحقير، آرثاس! لقد حكمت علينا جميعًا بالهلاك!",
[3262746986]="ليس من الضروري أن تنتهي هكذا، أتعلم؟",
[3262801736]="داركنس... يلتهم كل شيء.",
[3262973731]="سامحني، تاتجانا...",
[3263211432]="ماذا سيصير بنا عندما يسقط؟",
[3263569846]="سمعت أن بلاك مور يتصرف بغرابة.",
[3264106723]="$N هزم سيقريد آيس بورن للمرة الثانية. حسنًا، هذه المرة فعلها $Gهو:هي; بمساعدة أصدقاء $Gخاصته:خاصتها;، لكن النصر يبقى نصرًا!",
[3264234603]="ما زلت هنا؟ حماقتك مسلية! تلك الفتاة من فجر الفضة لا يجب أن تعاني عبثًا. اغرب فورًا وستنجو!",
[3264290755]="إلى الأمام!",
[3264290913]="الـآي أوف أشيروس تحت سيطرتك.",
[3264479374]="أديت جيدًا اليوم. أي شيء تركه مالقانيس هو لك. خذه كمكافأة لك. يجب أن أبدأ الآن في التخطيط لرحلة استكشافية إلى نورثريند.",
[3265708418]="قف وقاتلني، أيها الخائن الحقير!",
[3265715304]="تم اكتشاف كيانات معادية. تفعيل بروتوكول تقييم التهديد. الهدف الأساسي قيد الاشتباك. الوقت المتبقي 30 ثانية لإعادة التقييم.",
[3265808819]="هاراك فولن!",
[3266044370]="لا تنظر بهذه الثقة! أعرف ما تفكر فيه، لكن تيمبست كيب كان مجرد نكسة. هل صدقت حقًا أنني سأثق بالمستقبل لبعض الهجين الأعمى نصف نايت إلف؟",
[3266047038]="واو! أنت أنا، لكن من المستقبل! مهلاً، معداتي تطورت. رائع!",
[3266433984]="انتصارك هنا لا يعجل إلا بهلاكك!",
[3266493004]="كيف يمكنك أن تتركني هنا؟",
[3266681727]="ضع بابايا في المقطر!",
[3267334163]="انسى هذا! أنا ذاهب إلى المنزل!",
[3267825148]="يمكنني النوم للأبد، مون....",
[3268726779]="المعركة على وشك البدء! $N ضد الكليف هوف الشرس، بروكينتو!",
[3269111757]="أعتقد أن هذه هي النهاية، إذن؟ لن أستسلم بهدوء!",
[3269292137]="حدق في عيون الخائن!",
[3269813226]="تشعر بصدمة هائلة من الطاقة بينما يتحد جسدك مع جسد سو هولو.",
[3269921826]="أحسنت!",
[3270830124]="سأغادر الآن!",
[3270892598]="يمكنني تحقيق ذلك. فقط وقع أدنى الخط المنقط...",
[3271063002]="حلفاؤنا جاهزون. أسقط الدرع وافتح الطريق!",
[3271463769]="تعال، أيها الليل الهادئ؛ وأعد لي رومولو!",
[3271972351]="هجوم قارقويل! أمسكوا بنادقكم، يا رجال!",
[3272077452]="يكفي ثرثرة. دعوهم يأتون! سنطحن عظامهم حتى تصبح غبارًا.",
[3272700032]="ستعيده إلى هذا العالم، أيها البطل.",
[3274153868]="ربما...",
[3274235887]="لا أعرف ولا يهمني.",
[3274436701]="كور'كرون، جهز النقل إلى أندرسِتي.",
[3274577623]="لا تتردد! دمرهم!",
[3274847308]="هذه آخر مرة أُمسك فيها! أعدك! وداعًا!",
[3274897843]="تيسوران! أحتاج شخصًا--يفضل فالقران هستيل--للمتابعة في بصمات $N بالقرب من نزل شادي ريست.",
[3275201766]="%s يعود إلى الحجر.",
[3275311477]="حان وقت الأكل!؟",
[3275427848]="أنت صغير وضعيف جدًا... لن تكونوا خدمًا جيدين لـكورموك!",
[3275428625]="أخيرًا، يتوقف العذاب...",
[3276044037]="أرى أنك تحمل دومهامر. هل سقط كل أبطالنا العظماء، حفيدي؟",
[3276565496]="آه... أبي...؟ هل أنت هناك؟ أنا جائع... هل يمكنني الحصول على بعض الحساء؟",
[3277072668]="%s يزيل البذور من الفاكهة المتوهجة...",
[3277312134]="ألعاب جديدة!",
[3277374622]="آه، حلوة، حلوة بلودثيستل... ربما تركها أحد أولئك المدمنين القذرين في إكليبس بوينت.",
[3277608284]="سأضع حدًا لحياتك قبل أن تدرك الحقيقة المروعة!",
[3278414273]="كلوا يا أطفالي! كلوا من لحم الأحياء!",
[3278608686]="لقد كان خطأً بسيطًا. منعطفًا خاطئًا، أقول لكم!",
[3278666529]="شكرًا لكم! لا أحد يعلم ماذا كان سيفعل بي أولئك الأوغاد.",
[3278792290]="ماذا... يحدث... لي؟ أبعدوا هذه القطة عني!",
[3278829207]="سيف بيثود؟!! حسنًا، $R، أقبل تحديك. لكن أولاً، عليك أن تهزم أبطالي. فولقر! اسحق هذه الحشرة!",
[3278915301]="لا تتعب نفسك في أمور الماضي، $N!",
[3279071666]="لن تهزمونا جميعًا أبدًا!",
[3279729594]="قيود %s بدأت تضعف!",
[3279770213]="قد يكون هناك حل. تعال هنا، $N. سأشسوف لك ما أحتاجه.",
[3279798924]="لن تحبني عندما أكون غاضبًا...",
[3280260157]="أسمع خطوات. كن على حذرك.",
[3280434754]="تنكرك لا يخدعني يا جسدي! هزيمتك ستسعد دراكرورو!",
[3280689822]="قريبًا سنقضي على الأليانس والـهورد. ثم سيسقط باقي أزيروث أمام قوة جيشي.",
[3280737582]="دع مخاوفك تلتهمك!",
[3280915211]="كولوقارن يستخدم قبضة حجرية!",
[3281125531]="اتبعني يا $N. سآخذك إلى مخبأ ديفاياس. لكن الأفضل أن تحميني وإلا فأنا ميت لا محالة.",
[3281244395]="لو كانت أمي على قيد الحياة، لأطفأت الحرائق!",
[3281423490]="لا أريد الموت!",
[3281436622]="إذا لم تخدم سيدي بسيفك ومعرفتك بأعدائه...",
[3281954815]="أيها الأورك العجوز المثير للشفقة! تعالوا إذن أيها الأبطال. تعالوا وواجهوا قوة الـسكورج!",
[3282133652]="لنذهب إلى المدينة السفلى. سأحذرك أنها كواحدة من الملاذات الآمنة الوحيدة في أوتلاند، شاتراث جذبت حشودًا من اللاجئين من كل الحروب، الحالية والماضية.",
[3282290621]="فقط تمسك. سنتجاوز هذا.",
[3283098859]="ليس كثيرًا، ماغني. رأيت كوابيس عن إنسان... طويل... شعر فاتح... درع أسود كالموت. اسمه على طرف لساني، لكن...",
[3283710959]="لا أحد آمن!",
[3283796023]="أطلق العنان للغضب وليكن الأمر!",
[3284960399]="%s يتلاعب بلوحة التحكم بمهارة.",
[3284989816]="الحرارة... لا أستطيع تحملها...",
[3285432753]="أنت هناك، أحضر ماء بسرعة! أطفئ هذه النيران قبل أن تنتشر لبقية القلعة! أسرع، لعنك الله!",
[3285500234]="عالمك يتأرجح على حافة الفناء. كلكم ستشهدون قدوم عصر جديد من الدمار!",
[3286153973]="هل يسمعني أحد؟ أحتاج مساعدة! هذا المخلوق سيقتلني!",
[3286467694]="لقد أثبت نفسك كمستكشف وباحث عن المعرفة.",
[3286732189]="المجد لـ$N، بطل فالهالاس!",
[3287081523]="لن تجد سلامًا في الموت، أيها الثعابين!",
[3287347655]="عنده جيش كبير، وهو يخطط لشيء هناك بالأسفل.",
[3287446401]="قلت لك استدعني فقط إذا عاد ذلك الإلف الغبي! ما هذا؟ لا يهم، لن تحتجزني طويلاً.",
[3287623357]="يمكنك الذهاب وإخبار ستاوت مانتل أن عصابة ديفياس مختبئة هنا، $N.",
[3287638302]="بوقاحة تجاهلت قوى تفوق فهمك.",
[3287934451]="مثير للاهتمام... لم ألاحظ هذا من قبل...",
[3287963725]="$N قادم بسرعة! استعدوا للقتال!",
[3288140738]="%s يسحق الأحجار القمرية في كوب من الشاي.",
[3288376032]="الموت سيكون مجرد بداية عذابك.",
[3288564917]="بدونك كنا سنضيع. شكرًا على الرحلة!",
[3288582746]="يبدون لذيذين جدًا...",
[3288905776]="%s يبدأ في التحميل الزائد!",
[3289561988]="سأترك هذه الصورة معروضة لتتأملها. ادرس نقاط قوة خصومك، فقوة المخلوق قد تكون أيضًا نقطة ضعفه.",
[3289936252]="أنت لست $Gبابا:ماما;!",
[3290187749]="التاريخ على وشك أن يُعاد كتابته!",
[3290240029]="المزيد من المعاناة في انتظارك!",
[3290649233]="بوابة الجمشت الأرجواني تتعرض للهجوم!",
[3290801892]="داركفاير — انتقم لنا!",
[3291225921]="انظر لاقنوس، أنا أعتبرك رجلًا قديرًا، لكن صبري بدأ ينفد. أعلم أن مورادين هنا، هل تستطيع أن تدلني عليه أم لا؟!",
[3291301401]="أقلق عليك أحيانًا يا نات.",
[3291484800]="المحطة القادمة، ثندر بلف!",
[3292172107]="أعطني لحظة لأضبط جهاز الإرسال على طولك ووزنك، $N.",
[3292339980]="وضع اثني عشر مركز تركيز قد يسمح للطاقات السحرية بالتشكل بشكل أقوى، مضيفًا الاستقرار اللازم.",
[3292523027]="%s يغفو فجأة.",
[3293198567]="%s تتنهد بهدوء وتهز كتفيها.",
[3293687779]="من أجل الـليتش كينغ!",
[3293708238]="تحتاج إلى قوة أكبر. لا تُظهر لأعدائنا أي رحمة.",
[3294669081]="كنت لأذبح بغلك هذا! لماذا أحضرت هذا الوحش إلى هنا على أي حال؟",
[3295060143]="شادوفورج، بنقفز",
[3295288298]="كل الحقائق، كل الأبعاد مفتوحة أمامي!",
[3295690672]="كدنا نوصل!",
[3295818002]="لاااااااااااااااااا!",
[3295820507]="غوريجيك جوعان. اذهب وعلّق نفسك على النار يا عبد. أخبر غوريجيك عندما تنضج.",
[3295971339]="صبري خلص! روح خلّيهم يتمنوا إنهم ما انولدوا!",
[3296156560]="شكرًا لك، أدامانت. أعتقد أني أعرف الشخص المناسب للوظيفة.",
[3296303113]="الجدال المستمر لن يوصلنا إلى حل. يجب أن نتحرك.",
[3296307234]="شكرًا مرة ثانية!",
[3296700126]="أبلغ عن الحضور.",
[3296835364]="آه، هواء راتشيت المالح الجميل.",
[3297176939]="رائحة لحم... قريبة...",
[3297564456]="%s على وشك الوصول للقوة الكاملة!",
[3297922640]="التصنيف: الآلهة القدامى. الآلهة القدامى جعلت جميع الأنظمة، بلا يوجدا الإيرذن، عاجزة لتسهيل الاستيعاب. سُمي زعزعة المصفوفة هذه \"لعنة الجسد\". تأثيرات زعزعة الاستقرار زادت مع الوقت.",
[3297943509]="قل مرحباً لأصدقائي الصغار!",
[3298196962]="أونوزون سوف يقتلك ميت!",
[3298297805]="بنور إيلون! إيريدار! شياطين ملعونة، ماذا فعلت بي؟ لم آتِ وحدي، سنحاربكم كما حاربناكم في الماضي! أنا...",
[3298839932]="رجال البنادق، أسرعوا في الرماية!",
[3299428578]="صلوا لآلهتكم لتموتوا سريعاً.",
[3299717984]="تماسكوا يا رفاق. سنقوم بالغارة قريباً.",
[3299815933]="بات أحشاء مرة أخرى للنومز الليلة...",
[3300979807]="لي؟ حقًا، مون؟",
[3301401692]="54! بالتأكيد تقدم لا يُقهر!",
[3301927616]="لا يمكنك الاختباء منا، أيها البالادن الصغير!",
[3302048970]="حياتي من أجل الـدريد كينغ!",
[3302170033]="لقد تجددت! يسيرا امنحني النعمة لأريح هذه المخلوقات النجسة!",
[3302306983]="أوه، إخوتي! أتمنى أن تجدوا الراحة في قبوركم المائية!",
