[3324797346]="ريجيك يعجبني! إذا كانت الخوذة تخيف الجراء، ريجيك لا يستطيع الانتظار ليرى ماذا ستفعل بالجبناء ذوي الألسنة الكبيرة!",
[3324930446]="الآن تواجه البطل الحقيقي! أعطيك فرصة للهروب أيها الصغير. اهرب الآن قبل أن يقوم موقور بتدمير... تدمير... اهرب قبل أن موقور يقتل!",
