[3333411467]="مداك يتجاوز قدرتك.",
[3333592056]="لا يمكنك مقاومة القدر!",
[3333606229]="سميناه درانوش - ويعني \"قلب درينور\" بالأوركية. لم أترك الوارلوكس يأخذونه. كان ابني سيكون بأمان، مخبأ بعيدًا عند شيوخ غارادار.",
