[3337258190]="آغ!! لن أكون بعد الآن عبداً لـماليقوس! تحدني وسيتم تدميرك!",
[3338529109]="المدخل مخفي هنا في مونبروك. ابق عينيك مفتوحتين للصوص. يريدون موتي.",
[3338714805]="كلها يا كبار الألسنة!",
