[3354893889]="لقد غبت طويلاً يا مالفوريون. السلام بين أبناء أزيروث هش في أحسن الأحوال. ماذا عن والدي؟ عن أخيك؟ هل لديك أي أخبار؟",
[3355236197]="أين رايحين؟",
