[3360532823]="الأليانس يجرؤ على التسلل إلى هذا العمق في حصني؟ أحضروا سجناء هونر هولد واستدعوا الجلاد! سيدفعون بحياتهم ثمن هذا التعدي!",
[3360866754]="عذاب أبدي ينتظرك!",
[3361365193]="أنا الأذكى والأقوى والأكثر ثقافة بين الغورلوك هنا، ومع ذلك سو-ساي هو من يقرر كل شيء... هل يبدو هذا صحيحًا بالنسبة لك؟",
[3361549123]="لا تنسَ...",
