[3366892715]="بمجرد التعامل معهم، يمكننا تخصيص المزيد من الموارد للمجهود الحربي.",
[3367204471]="لقد وصلنا! شكرًا، $N. ما كنت لأصل إلى هنا بدونك.",
[3367527765]="اللحظة التي انتظرها سيثون بصبر قد حانت أخيرًا. أطفاله أمضوا آلاف السنين في بناء جيش قادر على الانتقام من كاليمدور بأكملها، والآن الجائزة في متناول أيديهم.",
[3368270670]="لا شيء يضاهي بعض المورنبرو الساخن في يوم دن موروق البارد لبدء الأمور بشكل صحيح!",
[3368306916]="%s يتراجع ألمًا مع اجتياح حكم البر له!",
[3369298231]="لست وقحًا الآن، أليس كذلك؟",
[3369432698]="حليفنا وصل! افسحوا الطريق إلى غرفة التجسيد!",
[3369485230]="سيد بيريلي، هل كانت هذه البضائع تحت إشرافك طوال الوقت؟",
[3369838279]="أحسنت! بدون مساعدتك، ما كنت لأتمكن من صد تلك الموجة من التروقز.",
[3370848478]="هذه النكتة تقتلني!",
[3371015378]="سموتس!",
[3371235922]="لقد تم الأمر. اركضوا عائدين إلى أسيادكم. اركضوا إلى هاركوا. أخبروها أنني قادم!",
[3371248285]="انظر إليهم وهم يعملون! بلا بقعة!",
[3371380194]="الأفضل ما تقف بطريق غوريجيك!",
[3372308221]="%s يستنزف مانا الخاص بك ويتحول إلى حجر.",
[3372395785]="أي شرف في التخبط بهذه العصي البليدة؟ مضيعة للوقت.",
[3372481327]="سامحني على قسوة أسلوبي، لكن الخائن لا يمكنه معرفة الحقيقة. سري يجب أن يظل مكتومًا بأي ثمن!",
[3372907763]="$N يقتل! $Gهو:هي; يقتلك الآن! اهرب! اهرب!",
[3373340453]="أوه، يا إلهي. ما هذه الرائحة - أوه، لحظة، هه، آسف! يبدو أن حواسي ستأخذ بعض الوقت لتتكيف.",
[3373498010]="تم الأمر. لدي سلاحك، $N.",
[3373839284]="سأجذب نيرانهم، أنت اهرب من خلفي.",
[3373877361]="إلى مذبحها يجب أن يرتحل هذا الفاني. ما يجب فعله لن يكون سهلاً. في النهاية قد يثبت أنه مستحيل.",
[3374153293]="آآآه! افعل أسوأ ما عندك، $C! لن أخبرك بشيء!",
[3374327973]="سيج إنجينز، ذخيرة، درع ثقيل... كيف تخطط لتحطيم أسوار آيس كراون بدونها؟",
[3374374940]="%s يجمع المواد ويبدأ العمل.",
[3374580218]="ظهر حلفاء الطبيعة!",
[3375345568]="انتهت المعركة!",
[3375566393]="عندما عبر فوج بلود إلفز هذا الجسر، اصطف إكساركس وفينديكاتورز الألدور للدفاع عن تيراس أوف لايت. ولكن حدث ما لم يكن متوقعًا.",
[3375640389]="أنت لست مناسبًا لهذا.",
[3375718027]="انعكست القطبية!",
[3375862324]="همم، أعتقد أن الوقت قد حان لـ...",
[3376393677]="%s يبدأ الاستدعاء!",
[3376513331]="حيكون فيك قدوة حسنة للباقين!",
[3376634650]="واحد آخر يسقط!",
[3376822291]="أي شيء ممكن يصير...",
[3377025055]="ابقَ. استمتع بلحظاتك الأخيرة.",
[3377332053]="لا تعبث بالبريد!",
[3377413512]="من يجرؤ على مقاطعة شغلي!؟ أظهر نفسك، أيها الجبان!",
[3377524161]="بابا سوف يصنع ألعاب جديدة منك!",
[3377723360]="%s يقبل الآثار من $N.",
[3378003223]="أرواح الأرض العظيمة، ساعدونا في ساعة حاجتنا!",
[3378321190]="بررر...",
[3378422931]="انتبه!",
[3378444233]="انظر، نوث الـ بليقبْرينقر. المسؤول عن ابتكار العملية التي تقطر أرواح الأحياء وتضعها في قبر البرد من الموت، لاحظنا أن نوث يصقل هذه العملية حتى الآن.",
[3378473372]="هذه المعدات رائعة، لكن ألم نستطع فعل شيء أفضل؟ هل أنت حتى في ريد؟",
[3378888315]="الكيان المحدد: يوق سارون. الأمن قد اخترق. حالة السجن التشغيلية غير معروفة. غير قادر على الاتصال بالمراقبين لأغراض الإخطار.",
[3379243411]="أنا أحبك أيضًا.:)",
[3379269565]="ليكن الأمر هكذا إذن!",
[3379549002]="إشنا-دال-ديب.",
[3379788911]="إذن علمني، كيلثوزاد. علمني كل ما تعرفه...",
[3379941636]="أخبرني... أخبرني بكل شيء!",
[3379962741]="كويلديلار لن يخدم أحدًا آخر!",
[3380199976]="اخرس أيها الوغد! لا تجرؤ على استخدام تلك النبرة مع كاهنة النور!",
[3380210329]="خبز طازج، خبز هذا الصباح.",
[3380776950]="يا لها من مضيعة دموية!",
[3380835908]="المنطاد إلى أندرسِتي وصل للتو! الكل على متن إلى تيريسفال قليدز!",
[3381104888]="حركة الغولم تبدو ضمن المواصفات.",
[3381116826]="حياتي لا تعني شيئًا! مهمتنا المقدسة هي كل شيء!",
[3381258374]="حتى النور لا يقوى أمام إرادة شعبنا التي لا تُقهر.",
[3382128624]="هذه المنطقة ستدمر نفسها في ثلاث دقائق.",
[3382137854]="لكنها مقيدة. يجب إيجاد طريقة لتحريرها.",
[3383156094]="لا تدعوا تلك الوحوش تعبر البوابة! اصمدوا أيها الجنود!",
[3383354980]="%s يتفحص الأرض بحثًا عن أحجار الغراب المدفونة.",
[3383844308]="إذا أضعنا وقتنا وقوتنا في القتال مع بعضنا البعض، فسيستخدم لوكين موارد اولدوار لتدمير كل من الـهورد والأليانس.",
[3384110874]="لا! أرجوك! أنا... لدي أطفال! أنا... أنا...",
[3384117037]="هي مورقوم، يبدو أن مارجي هنا تحتاج بعض الاهتمام. ما رأيك؟",
[3384121127]="في أي وقت يريد أي منكم أيها البيونز أخذ استراحة، المقبرة هناك.",
[3384325101]="أخيرًا، قتال يستحق المشاهدة.",
[3384732464]="ماذا تقصد بأن وقتي حان؟! سأقتلك في مكانك!",
[3384740670]="بينما تسقطون في المعركة، ننمو قوة. هناك نتيجة واحدة لا مفر منها. استعدوا لنهايتكم!",
[3385078891]="%s يفقد الوعي.",
[3385084796]="الـ فروزن ثرون...",
[3385095132]="أحتاج بعض الهواء النقي، مع أنه لا يوجد أي هواء في هذه المستنقعات! سأخرج قليلاً. رتب الأمور قليلاً وأنا غائب، هل تفعل؟",
[3386181506]="باميلا؟ هل أنتِ هنا يا عزيزتي؟",
[3386343118]="أظهر دعمك لبطلتك المفضلة! ارتدِ ألوانها في المباراة القادمة ودعهم يعرفون من تحب!",
[3386561443]="بنتاروس، لقد سمعت $Gرجل:امرأة;. اطلب من السحرة رفع الدرع ودع هؤلاء الشجعان يعبرون!",
[3386734223]="ما هذا؟! ألم يعلمك أبوك وأمك أي شيء؟!",
[3386796744]="مجرد بشر...",
[3386964682]="قاتلوا من أجل مجد الأليانس، أيها الأبطال! أكرموا ملككم وشعبكم!",
[3388473015]="لم يعد هناك وقت لي. لقد انتهيت. أنهِ أمري، $N. افعلها وإلا سيقتلوننا كلينا. $N... تذكر نوميريغان! هذا العالم يستحق الإنقاذ.",
[3388620689]="ماذا تفعل؟ اذهب!",
[3389255752]="احموا الوارتشيف بأي ثمن!",
[3389287268]="يبدو أن الوقت قد حان لإخراجك من هذا القفص.",
[3389307855]="%s يزأر!",
[3389658242]="اصمت أيها الخادم! الثأر سيكون لي! الموت لـستورمويند! الموت بالدجاجة!",
[3389831588]="قوتي تضعف أيها الفاني. لقد فعلت ما وعدت به، الطريق واضح. سأعود الآن من حيث أتيت.",
[3389911768]="اقترب... اقترب أكثر... وانظر ما يجلبه الفراغ!",
[3389933971]="هذا الشراب ضعيف، بلا قوة تذكر،",
[3389974503]="حراس... حراس!",
[3390312012]="أتذكرك... في الجبال... لكنك... ما هذا؟ أين أنا--",
[3390324208]="لا أعرف كيف، لكن النصل اختارك لتصبح حامله الجديد. خذه ببركتي، واستخدمه ضد الـسكورج كما فعلت أنا من قبل!",
[3390774406]="أين أنا؟ من أنت؟ ما هذا الشعور الغريب؟",
[3391520517]="أن افاتار اوف تيروك!! إلى السلاح!",
[3392023448]="تعالوا، يا إخوتي! التهموا لحومهم!",
[3392446222]="يمكننا استخدام هذه الأجزاء على الأرجح.",
[3392666002]="...هادئ جدًا.",
[3393316201]="لنرَ إن كان حقًا منيعًا.",
[3393328680]="ألم شديد في المعدة؟",
[3393856137]="يجب أن أتعمق أكثر تحت الأرض حيث هو. يجب أن أقفز!",
[3394222192]="لو لم تكن معدتي تهدد بفصل نفسها عن جسدي وتتركني للنفايات التي نعطيها للسجناء، لكنت شعرت بالإهانة من هذا... هذا الطعام.",
[3394908980]="يزمجر فروستوورغ، كاشفًا عن فريسته!",
[3395160002]="تمهلوا، أيها الأصدقاء! هناك معلومات يجب الحصول عليها قبل أن يلقى هذا الشيطان مصيره!",
[3396099385]="العب!",
[3396308487]="الأرواح تنادي... أنا ملتهب.",
[3396723182]="مسؤوليتي حراسة هذه البيض. سأحرقك قبل أن يصيبها أي أذى!",
[3397116932]="الأراكون مختبئون... في كل مكان!",
[3398768941]="هذا ليس مضحكًا!",
[3399688775]="أنت في وضع سيء جدًا.",
[3399698825]="التزم بالقانون!",
[3399881768]="عالمكم سيموت أيها البشر! هلاككم أصبح وشيكًا!",
[3399884994]="%s ينكز الضفدع الصغير.",
[3399979761]="اقترب أيها الشيطان! الموت ينتظرك!",
[3400322420]="أليس الأفضل أن تختبروا أنفسكم أمام خصم أقوى؟!",
[3401469455]="بلورات البازيليسق المسحوقة!",
[3402716605]="...النصر.",
[3403431219]="أنا، يعني، ما فهمتها...",
[3403508060]="أخدم حتى النهاية!",
[3403937892]="حيث لا نور، يزدهر اليأس والكراهية والغضب.",
[3403944639]="لا تتقدموا. سيتم القضاء عليكم.",
[3403945615]="لقد أضعتم وقتي بلا يوجد الكفاية... فلتنته هذه الألعاب!",
[3404322426]="ماء العرافين جاهز لاستهلاكك، $N.",
[3404427747]="متنمر!",
[3404652600]="من أجل صنويل!",
[3404699144]="سأطلق النار!",
[3405291507]="احترق يا ساكن الأرض! احترق!",
[3405311690]="حسنًا، أعتقد أنني فهمتها الآن. اتبعني، $N!",
[3405369713]="[فوربولق] فوربولغز ستيلباين لن ينسوا شجاعتك قريبًا!",
[3405605280]="أكرموا أبطالكم! في هذا اليوم، وجهوا ضربة قوية ضد أحد أعدائنا الأكثر كرهًا! الوارتشيف المزيف، ريند بلاكهاند، قد سقط!",
[3406097862]="ننطلق!",
[3406149583]="ثاين باناهوق الـديثبلو سقط على يد $N و$Gرفاقه:رفيقاتها; في القتال. $Gأمامه:أمامها; تحدٍ واحد فقط. من سيكون خصم $Gه:ها;؟",
[3406475447]="يا ملكتي، هل يعلمون؟",
[3407280058]="ثاين باناهوق الـديثبلو سقط على يد $N و$Gرفاقه:رفيقاتها; في القتال. $Gأمامه:أمامها; تحدٍ واحد فقط. من سيكون خصم $Gه:ها;؟",
[3407690667]="هجوم!",
[3408032215]="سأذهب الآن لاستدعاء السيد الذي هذا بيته. إذا أردتم مقابلته، فحياتكم التافهة ستكون ثمنًا لذلك! لكن ابحثوا عن عرينه إن كنتم تجرؤون!",
[3408303149]="ثوريم! تعال، أظهر نفسك!",
[3408736085]="هل سمعت أي شيء من وارساونغ؟ هل سنحصل على بعض الإمدادات قريبًا؟",
[3408773402]="ها! هذا سهل.",
[3409268829]="كانوا على بعد ثوانٍ من ربطي بأحد تلك المذابح وامتصاص روحي. فلنخرج من هنا!",
[3409290544]="حان وقت لعب علامة الترول، يا صاح!",
[3409355631]="أخي، ستورمهوف، كان محاربًا أعظم مني بكثير. بينما تدربت لأكون زعيم عشيرتنا، هو استعد لمهمة أكبر.",
[3409788701]="يقول لنذهب إلى زولدراك. يقول يمكننا الوصول إلى جذور هذه الفوضى...",
[3409977244]="هجوم ضخم بكل رجل قادر سينتهي بمذبحة لا داعي لها. كل جندي يُفقد سيقوم كعدو. أزيروث ستصبح بلا حماية ضد تهديد الأنديد.",
[3410311837]="%s يبدأ بالبحث في شارات سترومغارد ديفندرز الساقطين...",
[3410507878]="لقد قُتل هورغوس! تشجعوا يا مدافعي داروشر!",
[3411097934]="شكراً! شكراً لك، $Gبريست:برايستس;. الآن أستطيع مواجهة أولئك البشر بقوتك التي تسندني!",
[3411170853]="مع الوقت، النور والأمل الموجودان بداخله سيعيدان إحياء أكثر من مجرد مصدر قوة... ربما سيعيدان إحياء روح أمة.",
[3411258379]="لا يُصدق! $N هزم مركبلوود توينز!",
[3411854463]="ما هذا الذي لدينا هنا؟ ألم تقل أن المنطقة آمنة؟ هذا الهجوم الثالث الآن؟ إذا نجونا من هنا، سأخصم بالتأكيد من مكافأتك. لا تقفوا مكتوفي الأيدي، دمروهم حتى أتمكن من الوصول إلى ذلك الجامع.",
[3412174642]="تم التحقق من أن المراقب ميمير لم يعد موجوداً. اكتمل التحليل.",
[3412636960]="حسناً، لنلقي نظرة على هذا الشيء...",
[3412793157]="الدرع أوشك على الزوال! كل ما عملت من أجله في خطر!",
[3413198860]="%s يحفر في التراب...",
[3413527067]="شكرًا، تشاريس. تعالي يا بيج، حبيبتي.",
[3413987984]="أريد البقاء هنا والتأمل فيما رأيناه. من فضلك اذهب إلى إيريلاس وأخبره بما تعلمناه.",
[3414160922]="لا... تقاوم.",
[3414248814]="ليتك تفهم!",
[3414253478]="حسنًا، لنبدأ.",
[3414332707]="لنرى ماذا يمكنني أن أصنع منك!",
[3414460201]="بالتأكيد، حبيبي. ضعها على حساب هاري، حسنًا؟ إنه مدين لي بمشروب!",
[3414647901]="هيا، لا تتعطل الآن!",
[3415021214]="لا يهم.",
[3415246223]="الـ%s يصرخ طلبًا لأمه.",
[3415257166]="الـسكورج سيدمر هذا المكان!",
[3415506512]="سأخلط هذا بحذر - أوبس!...حسنًا، لقد سكبت القليل، لكنه جاهز!",
[3415782220]="أنظمة الطيران جاهزة! كلوك! تشغيل الصواريخ للنقل إلى بوتي باي!",
[3417159766]="%s ينظر إلى $N، ثم يبكي فرحًا.",
[3417504018]="مساعدتك مكنتنا من ربط الـديفياس بالعقل المدبر وراء الاختطاف، اونيكسيا، الذي كان يتظاهر بأنه عضو في البلاط الملكي.",
[3417885308]="ما هذا؟ موك-ثورين كا! اقتلهم!",
[3418316926]="أعتقد أنني أرى طريقة للخروج من هذه الفوضى الكبيرة من الشوك.",
[3419175205]="تحركوا أيها الحراس! حان وقت القتل!",
[3419588794]="سألتهم روحك!",
[3419771769]="لقد وصلت إلى الرتبة 2: ملازم أول",
[3420099767]="أرجوك، ليس خطأي! إذا... إذا أعطيتك استردادًا، ربما يمكنك التحدث إلى معالج؟ لا أعرف ماذا تتوقع مني أن أفعل!",
[3420937211]="واجه اندفاعة البرق!",
[3421038240]="آه! قضيت وقتًا طويلاً في تلك الغوكعة الضعيفة.",
[3421145740]="فشل كامل في الأنظمة. تم اختراق بروتوكولات الدفاع. ليفياثان وحدة يتم إيقاف تشغيلها.",
[3421194911]="سوف تعاني إلى الأبد!",
[3421276971]="ها! ثاندرسبايك ملكي. مت!",
[3421582249]="وصلت إلى 15. تفوق على ذلك!",
[3421805267]="أعطينا اللمعان للمزار... لسنا طماعين... لماذا يحدث هذا؟",
[3422248164]="أوه، هذه لزجة! أتساءل كيف يطلقون الشبكة؟",
[3422878093]="آه! أوه لا، لقد شبكت نفسي! إنها لزجة. شعري!",
[3422969438]="%s يمسح دمعة.",
[3423126968]="هذا، يا سيدي، بغل!",
[3423157738]="محاربي دراغونماو، تجمعوا! أحدكم قد نال رتبة هايلورد! احنوا رؤوسكم إجلالاً! أظهروا احترامكم وولاءكم للهايلورد $N!",
[3423411196]="بارون سابلماين. سيكون على شفتيك وأنت تلفظ أنفاسك الأخيرة.",
[3423673126]="لقد فزت. حظ أوفر في المرة القادمة يا صديق.",
[3423733805]="أتظننا حمقى! أنت مغطى بدماء الحيوانات!",
[3424415304]="بعوضة تافهة!",
[3424488607]="الجسد ضعيف. سنجعلك أفضل، أقوى... أسرع.",
[3424761200]="سيتم تسليح %s خلال 5 ثوانٍ!",
[3424925920]="لقد انتظرت طويلاً!",
[3425045073]="لما تيجي تطير لـدورنهولد، قلي وباخدك.",
[3425241397]="كم هذا متوقع! لكن، من يتوقع من صخرة تفكر بأي شيء غير ذلك؟",
[3425258351]="بدء تحليل حالة المراقب ميميرون.",
[3425953662]="%s ينقسم إلى اثنين من لافا سبونز الجدد!",
[3426003300]="نحن نعلم... أنك لا تعلم... لماذا نحن محصنون... ضد ما تسميه وباءك. قراند ادميرال ويستويند أعطى رئيس الدير تلك الصلاة بطريقة ما. أتوسل إليك... لا مزيد... أرجوك؟!",
[3426138738]="يسر الميثاق الفضي أن يقدم منافسيهم لهذا الحدث، هايلورد.",
[3426265778]="لم أنته بعد! لا، لدي بعض الحيل الأخرى في جعبتي...",
[3427056552]="رماة، تشكلوا وخذوا مواقعكم!",
[3427216434]="في وشك! قلت لك إن فيه شي هنا!",
[3427262788]="وسط المأساة والفوضى، هذا المكان يقف متحديًا ضد الـسكورج! من الجيد أن نكون هورد.",
[3427302144]="بالتأكيد لا نحتاج لجذب المزيد من الانتباه إلينا، أيها الغريب. ارجع إلى من أرسلك للبحث عن السيد المفقود وأخبرهم أنه لم يُعثر على شيء. عندما يتم هذا - وسأعرف متى يحدث - ارجع وسأكشف لك أسرار المتوفى.",
[3428017719]="انتصارك سيكون قصير الأمد. أيام الأليانس والـهورد على وشك الانتهاء! المرة القادمة التي نلتقي فيها ستكون الأخيرة.",
[3428104385]="لقد أنقذت حياتي!",
[3428267389]="لدي خمسة أطفال، $Gرجل:سيدتي;! سيموتون بدوني!",
[3428725962]="هي! حاول أن تتوقع المستقبل بينما أحدهم يهز منزلك!",
[3428779410]="هل يحتاج أحد إلى إمدادات لاصطياد الترولز؟ أي ترول سيفي بالغرض.",
[3428929317]="وضعية القتال! استعد لهجوم هجومي!",
[3429071232]="هنا لدينا كاتدرائية النور، مركز التنوير الروحي هنا في ستورمويند.",
[3429078463]="أنهِ الأمر! أنهِ الأمر! اقتلني، أو أقسم بملكة التنين أنك لن ترى ضوء النهار مجددًا!",
[3429398825]="سيدي... لديك ضيوف.",
[3429801216]="تحدث معي لتحصل على بيرة مجانية في بيغ أند ويستل!",
[3430443905]="عد إلى كوروس. سأوصله إلى بلود واتش.",
[3431117213]="إن كان بحياتي أو موتي أستطيع رد الجميل لك، سأفعل.",
[3431652722]="رائع!",
[3432465402]="دعنا نقلق بشأن كيف نقتل الوحش يا جودفري.",
[3432480820]="حدقوا في الهاوية وشاهدوا وهي تسود أرواحكم!",
[3432651270]="مرحبًا، وارتشيف ثرال. أوفرلورد هيلسكريم.",
[3432909706]="منذ سنوات، كان والدي والعديد من الفروستبورن عائدين من رحلة عبر دراغونبلايت. كانت هناك عاصفة ثلجية شديدة... أسوأ بكثير مما رأيناه منذ ذلك الحين.",
[3433002831]="...لكن ما يعلمه هامول هو ما يعرفه الإلفز. النايت إلفز. يضعون ثقتهم في إلهة القمر، كمخلوقات الليل.",
[3433236988]="لقد أكملت الأسلحة، $N.",
[3433861694]="أرى أسلافك، أيها الأنكورايت! يتلوى ويصرخ في الظلام... إنهم معنا!",
[3434555206]="أنت بيدق لقوى غير مرئية.",
[3436342285]="ياآآآآآررررغ!",
[3436785196]="هذا يكفي. يمكنني الاستمرار وحدي من هنا.",
[3436876255]="خذ هذا، اشربه.",
[3437013239]="شكرًا على صبرك، $N.",
[3437552922]="%s يبدو مذعورًا من نبرة الإكسكيوشنر!",
[3437777728]="موتك من أجل قضية أعظم...",
[3438108362]="أي نوع من الخدع هذه، $R؟ إذا كنت تسعى لنصب كمين لي، أحذرك أنني لن أسقط بهدوء!",
[3438300374]="العالم يعاني خسارة أخرى تافهة.",
[3438767775]="كريستلاين فراير يبدأ بالخروج من جرعته البذرية",
[3439306943]="أريك القوة... في الأعداد.",
[3439671549]="غطيني!",
[3439878371]="%s تهز رأسها.",
[3440197057]="لقد خسرت.",
[3440347893]="مت أيها الدخيل! أجهزتك التافهة لا تستطيع اختراق السحر المظلم لقلعة هيلفاير!",
[3441639111]="أليس هذا مبالغاً فيه قليلاً يا فتى؟",
[3442074923]="والآن ماذا أفعل بك؟ ببساطة لا أستطيع أن أقرر.",
[3442121053]="قد ترغب في الاحتماء.",
[3442266015]="كن ثابتاً أيها البطل. أعرف لماذا أنت هنا وأعرف ما الذي تبحث عنه. إيرانيكوس لن يتخلى عن الشظية بسهولة. لقد تم تحريفه... تحريفه بنفس القوة التي تسعى لتدميرها.",
[3442559615]="ممتاز! أجزاء جديدة!",
[3442731715]="دمارك سيبشر بعصر جديد من المعاناة!",
[3443088013]="هذه الأكوام من الخشب والقش قد ترحم، لكن الـليتش كينغ لن ترحم!",
[3443226468]="لم يتبق سوى واجب واحد...",
[3443303653]="من يدري ما الأسرار التي تختبئ في الظلام.",
[3443331349]="همم... لا أعتقد أن هذا الضوء الأحمر الوامض شيء جيد...",
[3443597342]="شادو لنجدة النار!",
[3444366980]="هاه! لم يكن ذلك سيئًا جدًا. ماذا قلت أنت وراين ستفعلان بهذا الشيء؟ إنه قوي!",
[3444966335]="هل ترغب في شيء آخر للأكل يا سيدي؟",
[3446310524]="سأستمتع بسلخ أحشائك!",
[3446346255]="شكرًا لك. لن أنسى هذا!",
[3446452135]="تحركوا بسرعة! لن تبقى على الأرض طويلًا!",
[3447060691]="الحمد لله! كنت قلقًا من أنهم سيجبرونني على الخدمة في حربهم ضد عمالقة الحجر!",
[3448239290]="ثاديوس، مبني من لحم النساء والأطفال، ويقال أن أرواحهم اندمجت معًا - مرتبطة إلى الأبد داخل ذلك السجن البشع من اللحم.",
[3448429161]="%s يقدم عين العقل والبلورات المغنية أمامه...",
[3449135053]="جاينا، اسمعي لي. يجب أن تدُمري الـليتش كينغ. لا يمكنك التفاهم معه. سيقتلك أنت وحلفاءك وسيرفعكم جميعًا كجنود أقوياء في الـسكورج.",
[3449186750]="هذه فرصتنا! اهربوا!",
[3449445464]="تذوق مقاس 600 من جيمر!",
[3450124744]="كارنيج قادم! تذكروا، مهما فعلتم، لا تخرجوا من حلبة القتال وإلا سأستبعدكم أنا ومجموعتكم.",
[3450228606]="$N هزم سيقريد آيس بورن للمرة الثانية. حسنًا، هذه المرة فعلها $Gهو:هي; بمساعدة أصدقاء $Gخاصته:خاصتها;، لكن الفوز فوز!",
[3450264686]="الوقت له معنى فقط للمخلوقات الفانية، أيتها الحشرة. ديمينسيوس لا نهائي!",
[3450557428]="بدء تحليل حالة المراقب فريا.",
[3450870757]="لن أقع في هذا أبدًا، أيها الأحمق! إذا كنت تريد معركة، فستكون بشروطي وفي عريني.",
[3451044891]="الأرض تتحمر بدمائك!",
[3451366471]="هذه الغابة تجعل أنيابي تحك...",
[3451753630]="ظننت أنني سأموت في هذه الحفرة. شكرًا لك!",
[3451898968]="ماذا فعلوا بمدينتي الجميلة!",
[3451947767]="كنت على حق، فوردرينغ. لقد أرسلتهم ليموتوا. حياتهم لا معنى لها، لكن حياتك...",
[3452112106]="هذا ينتهي الآن!",
[3452199785]="هذا... لا يغير شيئًا. اللعنة الأبدية تنتظرك!",
[3452302207]="إذا استمرينا بهذا المعدل، سيكون ليدي راضيًا.",
[3452347096]="كأننا ما عندنا مشاكل كفاية، تروح وتزيدها!",
[3452375447]="الآن وأنا بقوتي الكاملة، أستطيع أداء قمع الأحلام. يمكنك استخدامه لشفاء التنانين الأخرى، لكنه يستنزف صحتي، لذا تأكد من استخدام سم التسريب أيضًا!",
[3452486053]="ها! هذا لا يمل أبدًا.",
[3452519747]="هل أنت مستعد للانطلاق؟ إذن توجه إلى حانة نهاية العالم! فرقة زعماء التاورن تبدأ عرضهم عند رأس الساعة.",
[3452525016]="ألورغلغل.",
[3452813980]="لا يمكنك أن تقصد.... سأكتب تقريرًا عنك لهذا، $C!",
[3453310768]="تنين منكمو كلو!",
[3453747809]="سأظل مدينًا لك دائمًا، يا صديق.",
[3454152278]="البوق! استخدم البوق عليه وهو ضعيف!",
[3454548685]="من يعرف ما الأسرار التي تنتظر داخل أرشيف اولدوار؟ سأذهب لاكتشافها. شكرًا لك مرة أخرى على مساعدتك، $N. بدونها، كنت سأظل أبحث عن ذلك المفتاح.",
[3454799833]="لا يُصدق! أعرف من صاغ هذه السحر...",
[3455332845]="احذر! لا تدعه يخدشك مثل المرة السابقة.",
[3456169832]="عندما يتسنى الوقت، يجب أن نتحدث مطولاً. لدينا الكثير لنناقشه.",
[3457242250]="$Gسيد:سيدتي; $N، يا لها من مفاجأة سارة، $Gسيدي:سيدتي;.",
[3457515243]="يا $Gلورد:سيدتي;، اسمح لي أن أعيش طويلاً لأراك تطهر هذا العالم من الكفار.",
[3457732829]="تبدو متعبًا.",
[3458206720]="واو!",
[3458236849]="بالشمس الثانية من كاريش، انظر إلى هذا المكان! لا أستطيع إلا أن أتخيل ما يخطط له صالهدعار. هيا، لنواصل.",
[3458420828]="حان الوقت لإنقاذ الجنس النومي بأكمله. ها نحن ذا!",
[3458531792]="الفريق الثالث يبلغ عن وصوله!",
[3459220531]="%s يتفقد الطوق المحترق...",
[3459607769]="كل شيء هنا... كيف أتباع الغراب أمسكوا وأخضعوا أرواح المنافسين، وحبسوها للأبد داخل تماثيل حجرية! اللوح يذكر حتى اسم إله الغراب -- انزو. ظننت أنه ضاع من التاريخ!",
[3459723955]="هناك متسللون في الجوار. اقتلوهم قبل أن يدمروا كل شيء!",
[3460350425]="%s يحفر في الأرض!",
[3460438389]="أيها الحمقى! سيقتلنا جميعًا!",
[3461439626]="ستدفعون ثمن ما فعلتم! من أجل الأرجنت كروسيد!",
[3461967143]="أخيرًا، طغيان العاصفة المصنوعين قد انتهى!",
[3462245755]="لا أعتقد أن درازيت سيجد من يقتل هذا الرابتور. أعني، لقد رفع المكافأة مرتين بالفعل...",
[3462370725]="كيفر مسرور جدًا.",
[3462651567]="اعرف مكانك أيها الفاني!",
[3463148676]="سأنظف أسناني بعظامك!",
[3463449405]="الوحدة الآن جاهزة للعمل وتهاجم الأهداف.",
[3463640027]="تشجع! أصدقاؤك لن يندبوا موتك طويلاً!",
[3463786445]="مقبرة ستورمبايك تم الاستيلاء عليها من قبل الأليانس!",
[3464149388]="نحن نعرف قوة لا تُقهر أبدًا...",
[3464354054]="السيندوري يحكمون!",
[3464971519]="لكن ذلك الشرف لم يعد لك. قريبًا، سأحصل على بطل جديد.",
[3465169402]="لقد هزمت نفسك! هاه! أنت غبي جدًا أيها العبد.",
[3465352842]="هذه الجدران ستكون قبرك!",
[3465726724]="أوه، الألم...",
[3465805350]="هذه... هذه مزحة، صحيح؟",
[3466066811]="الفرقة الأولى جاهزة للمعركة!",
[3466333107]="أعرف مكانًا قريبًا حيث يمكننا التحدث على انفراد، يا طفلي. اتبعني.",
[3466375304]="ذاك الوحش هناك ملكك يا إد؟ آرر... إنها كبيرة!",
[3466564466]="أتجرؤ على سجني؟ ستموت!",
[3466880553]="بارك الله فيك، يا صديقي. كدت أموت...",
[3467107507]="الطبيعة المضطربة للممرات المائية العظيمة في أزيروث ودراينور هي نتيجة مباشرة لأرواح الماء المعذبة.",
[3467359347]="لكن ذلك الميد كان ملعونًا بطاعون الموت، والآن أصبح داغان العجوز كذلك.",
[3467905031]="أيها المغامرون، الباب بدأ يضعف!",
[3467905432]="قلوري إلى يوق سارون!",
[3467957833]="شيء مزعج جدًا جدًا. بدأنا نرى المزيد منهم عبر المسارات الزمنية.",
[3468417578]="أنت غير مرحب بك هنا، يا تابع الـليتش كينغ!",
[3468457890]="حسنًا. تارين ميل تقع غربًا من هنا. وبما أن الوقت مهم...",
[3468623271]="دعنا نغادر هذا المكان.",
[3469130606]="أنا فقط بدأت بالإحماء!",
[3469436220]="تيمي!",
[3469477832]="سيد النار؟ تم اكتشاف سيد عنصري؟ بالطبع... غولدان كنت أحمقًا ملعونًا!",
[3469520445]="النوع: ناثريزيم",
[3469909960]="%s يبدأ باستدعاء كابال ديثسورن!",
[3470042942]="عندما نلتقي مرة أخرى، سأحتاج إلى أكثر بكثير لتبرير حياتك.",
[3470431519]="أخبار سارة، جميعًا! أعتقد أنني أتقنت طاعونًا سيدمر كل أشكال الحياة في أزيروث!",
[3471549783]="أتجرأ على الصعود إلى سفينتي؟ موتك سيكون سريعًا.",
[3472110608]="أوقفوا الإغلاق الطارئ! كايل سيقطع رؤوسنا إذا سمع بهذا!",
[3472407852]="دعونا لا نضيع الوقت! خذوا أي شيء غير مثبت على الأرض وتيليبورتوا مباشرة إلى ستورمسباير! بسرعة بسرعة!",
[3472711968]="أخرج الأشياء من الجثة! داجيك يكره عندما يذهب لسلخ شيء وتكون هناك أشياء في الطريق. مزعج جدًا.",
[3473252023]="$Gسيدي:سيدتي;، حياتي فداء للهورد!",
[3473394699]="أيها الحمقى الفانون! الغيلان في ديثولم سيتغذون على رفاتكم!",
[3473409685]="نم الآن في الظلام البارد....",
[3473714398]="هل تكرهينني يا حبيبتي؟ لأنني أُجبرت على تدمير جسدك الحي، لتتحرر روحك من العبودية التعيسة.",
[3474094770]="إلى الجنوب يكمن هدفنا. سنسير نحو القلعة ونقطع قلب الـسكورج حيث يسكن.",
[3474503733]="نيفاريان قُتل! يا شعب أورقريمار، انحنوا أمام قوة حلفاء $N و$Gخاصته:خاصتها;، فقد وجهوا ضربة لالبلاك دراغونفلايت ستوقظ الأسبكتس من خمولهم! هذه الهزيمة سيشعر بها بالتأكيد والد السرب الأسود: ديث وينغ يتلوى من الألم والحسرة هذا اليوم!",
[3475141709]="لا أعلم كيف كان هذا ممكنًا، لكن لا بد أن تُحاكم يا إسكالدر. انتظر... ما هذا؟",
[3475688395]="سأعلمكم أيها الجهلاء الصغار كم أنكم لا تعرفون عن السحر.",
[3475774070]="شكرًا! شكرًا لك يا $Gبريست:برايستس;. الآن أستطيع مواجهة تلك الأخشاب الفاسدة بقوة إلون معي!",
[3476615994]="أستطيع الإحساس به الآن يا $N. أشنفال يقع في هذا الطريق.",
[3476755994]="سيكون عليك رفعه، وإلا لن تكون هذه منافسة حقيقية.",
[3476828457]="%s يجبر السائل على حلق الرجل المتعب.",
[3477779399]="ليس لديك أي فرصة!",
[3477835912]="%s ينهار.",
[3477865842]="أما عن حياتك أيها الفاني، فسأكون كريماً. بعد كل شيء... لماذا أدمر أكثر خدمي فائدة؟ لقد انتظرتك لأسابيع داخل ذلك المنجم في هايلدنير.",
[3478127694]="اطرد أفكارك الفاسدة.",
[3478329868]="أين نورك الآن أيها الصليبيون؟",
[3478599673]="لن أسقط بهذه السهولة!",
[3479279114]="جئني بالقتال!",
[3479554705]="الغرون هم القوة الحقيقية في أوتلاند!",
[3479725549]="تحلق حول فالهالاس، سيقريد آيس بورن تقترب لتأخذ ثأرها!",
[3479909253]="ذُق فولاذي أيها $Gولد:بنت; الصغير!",
[3480103169]="كيف فعلت ذلك؟ يا له من عالم قاسٍ قاسٍ...",
[3480380164]="ساعدني في تدمير هذه الأرواح المعذبة! معاً سنفك قبضة فروستمورن ونضعف الـليتش كينغ من الداخل!",
[3480526679]="لابد أن هناك واحدًا في مكان ما هنا...",
[3480580176]="آه! ليس مرة أخرى مع الرش!",
[3480604218]="لقد سمعت الجلدي! تحركوا!",
[3480894457]="لابد أن أحدًا كان يساعدهم.",
[3480907301]="%s يتمتم بكلمات غير مفهومة.",
[3481149889]="نحن... متفوقون! كيف يمكن أن يكون هذا؟",
[3481892436]="كم سنسمح لهذه الهمجية بالتجول بحرية في عالمنا؟",
[3482007039]="أخيرًا، أنا حر من سولفلاير!",
[3482711286]="هي! هي أنت! $R! أخرجني من هنا!",
[3482800769]="أوه، لا! أيها المغامرون، شيء فظيع حدث! أحد زملائي تم أسره من قبل تنين اللانهاية، وهم يفعلون به شيئًا مريعًا!$B$Bالحفاظ على آرثاس لا يزال أولويتك القصوى، لكن إذا تصرفت بسرعة يمكنك المساعدة في إنقاذ غارديان أوف تايم!",
[3483499266]="هذه ليست معركتك، أيها الغريب. احمِ نفسك من هجمات كريمسون ايليت. سأقاتل المحقق الكبير.",
[3483517338]="ابقَ خلفي، $R. سأبذل قصارى جهدي لحمايتك.",
[3483625217]="عندما يأتي الصغار، لن أتساهل معهم مثلك.",
[3484479704]="أأأأأأأأأأأررررررغ!!!!! اسكت!",
[3484874657]="سيدك يعرف ما يكمن تحت الكنيسة. لهذا لا يجرؤ على إظهار وجهه! لقد أرسلك أنت وديث نايتس خاصتك لملاقاة حتفكم، داريون.",
[3485674244]="عشيرة بليدسباير ما تلعب نزيه. عندهم غرون يساعدونهم. روح لـبليدز إدج ماونتنز. كلم موقدورق الـ ويزيند. اقتل الغرون.",
[3485866599]="هل هم خنازير جبناء يا بوبو؟",
[3486108458]="بتطيح تحت!",
[3486210065]="قطعت وعدًا لأمه قبل أن تموت؛ إني بعبر البوابة المظلمة وحدي - سواء عشت أو مت، ابني يكون بأمان. غير ملوث...",
[3487186853]="عبر الجوهرة، وجهت إلون حكمتها اللامتناهية...",
[3487264928]="لكن... يا سيدي، أنا لا أفهم. $N... إنه الأورك الذي لديه...",
[3488723124]="وداعًا يا صديقي.",
[3489163091]="مذهل! أشعر... بالتجدد. قوتي تعود!",
[3489677727]="لن يعرفوا أبدًا أننا مفقودون.",
[3489774806]="أفعل ما يجب علي فعله. أرجوك سامحني أيها الجنود النبلاء.",
[3490271333]="إيليدان يملك!",
[3490412417]="مرحبًا أيها المسافر!",
[3490586534]="لن تخرج حيًا!",
[3490812978]="جسدك لي! مصائرنا مرتبطة إلى الأبد.",
[3490997790]="براهاها! تلك النظرة على وجوههم عندما جاء مسدس ترولبلو القديم يدور لملاقاتهم! مناشيرهم لم تستطع حتى لمسي!",
[3491910692]="انظر، مون! نحن نصنع أعظم جيش من الـسكورج شهدته العيون!",
[3492632519]="لن أنساك أبدًا، يا حبيبي.",
[3492666947]="الطوطم صار جاهزًا. يمكن تطهير البئر الآن.",
[3492857167]="يبدو أن النور تخلى عنا.",
[3492959639]="سحر أفرّو... لسه مسيطر عليّ. لازم تحاربني، أيها الفاني. هذه هي الطريقة الوحيدة لكسر التعويذة!",
[3493461286]="أظننا بأمان الآن. لنرجع!",
[3493565314]="أخيرًا! رجعنا من ذاك الكهف المخيف.",
[3493590326]="المقبرة الجنوبية تم الاستيلاء عليها من قبل الـهورد!",
[3494597860]="سايدر سلايدر متبل!",
[3495082555]="هممم... أين صنارة الصيد حقتي؟ أوه، ها هي.",
[3495267761]="لعنة هذا التواء الليل. لكن الحلوى لذيذة.",
[3495760744]="آآآه!",
[3495830825]="الخيار واضح. يجب أن نهاجم. أعلم أن الاحتمالات ضدنا، لكن التاونكا لا يذهبون بهدوء إلى الذبح.",
[3495951164]="انهض، داريون، واستمع...",
[3495969797]="والآن لتلك الوجبة الخفيفة...",
[3496897826]="لنر كيف تصمد أعصابك أمام المظلم، ثالادرِد!",
[3497272383]="في الوقت المناسب.",
[3497695614]="%s يصفر!",
[3498351751]="ما يمكن أن يكون أفضل من خدمة روح الدب للأبد؟ اقترب الآن. أحضر أرواحك إلي!",
[3498386319]="لا يمكنك الاختباء مني، أيها الروق. أستطيع شم خوفك.",
[3498445957]="معجزة! الـ بيست سلخ نفسه!",
[3498477895]="لن تكون هناك رحمة!",
[3498814145]="تونكي!",
[3499128850]="لقد علقت أمعاء دودة على حذائي.",
[3499260377]="بالنور! ما هذا؟",
[3499289171]="كل الخلق سيلتهم.",
[3499463828]="قرص المخترع وقع في أيدي مستخدم غير مصسوف به. تفعيل بروتوكول الدفاع.",
[3501150091]="لنواصل التحرك. لسنا بأمان هنا!",
[3502033754]="كلي هذا يا ابنتي. سيساعدك على الشعور بتحسن.",
[3502555264]="اكتملت مرحلة الاختبار الأولي. الآن يأتي الاختبار الحقيقي!",
[3502825476]="بدء التقطير بعد 5 ثوانٍ.",
[3502874336]="ريز يجب أن يعود إلى البيت الآن. وداعًا، وداعًا، $R.",
[3502935127]="رجال، نساء، وأطفال... لم ينجُ أحد من غضب السيد. موتك لن يكون مختلفًا.",
[3503201907]="أسرار الأعماق ستبقى مخفية.",
[3503405127]="إذن لقد خسرت، هايلورد.",
[3503458669]="المنتصرون سيأخذون مكانهم المستحق في الهجوم على القلعة. سنقف معًا في وجه الشر، وآرثاس سيسقط!",
[3503494527]="الآن، اشعر بقوة سيدي اللامحدودة وايأس!",
[3503836823]="انتظر هنا، $N. سباي بوت سيخرج ليسكوفار بأسرع ما يمكن. كن مستعدًا! اهجم فقط بعد أن تسمع محادثتهما.",
[3504042108]="الـليتش كينغ سيكون مسرورًا بهذا المبتدئ.",
[3504426349]="والدي يقول إنها مجرد قصة.",
[3504448712]="أيها العبد العنصري الأحمق! أنت وسيدك ستدفعان الثمن لتدخلكما!",
[3505685508]="شكرًا لمحاولتكم، يا أصدقائي. سنكشف أسراره. نأمل قبل فوات الأوان.",
[3506464596]="تم اكتشاف عينة معدنية من أصل أجنبي.",
[3506782695]="حسنًا، يا زعيم. متأكد رغم ذلك؟ يبدو مجرد إهدار لممارسة جيدة.",
[3506864830]="مولغار هو الملك!",
[3506937599]="أين كل الجثث؟ ماذا فعلوا بشعبنا؟",
[3507036063]="سيدني تأخر. ظننت أنه سيعود إلى المنزل الآن.",
[3507340402]="%s يبدأ في استدعاء كابال أكولايت!",
[3507544983]="سيثون سيعيد السيطرة على هذا العالم!",
[3508343524]="شكرًا لك، أيها الروح الطيبة.",
[3508535843]="أنت تعمل لدي الآن!",
[3508536520]="أمسكت واحدًا! سأرى إن كان أي من الحراس جائعًا. تعال يا فانق!",
[3508657821]="طويل في سرج الكودو الخاص به، ها هو الجليل رونوك وايلدمان، البطل الأعظم لـ ثندر بلف!",
[3509399844]="أنت تتحدى الموت نفسه! تعال إذن، أيها \"الملك\". واجه قوة موغراين!",
[3510518324]="تعلم القراءة عمل يثير العطش. نخب، إيه؟",
[3510579792]="%s يبدأ بالتشقق والانفتاح...",
[3510691327]="لقد تحديت الموت نفسه!",
[3510754224]="لا مزيد من الخوف!",
[3511208241]="على الأقل اجعلني أتعب من أجلها المرة القادمة.",
[3511316083]="آه، يسيرا الحالم.",
[3511556972]="إينو ثورا سيرادور. هذا مكان مقدس.",
[3511622435]="دائمًا في سفر، تلك الفتاة.",
[3511769982]="18 درجة كراكلينهايت. الجو بارد شوي، صراحة...",
[3511790276]="الـليتش كينغ سيرى بطله الحقيقي في هذا اليوم!",
[3511801940]="تجمعوا يا حيواناتي الأليفة... فيه ما يكفي للجميع!",
[3511909058]="تبًا للأتباع! سوف أخلص عليكم بنفسي!",
[3512076549]="يا رجل، هذا لن يعمل أبدًا. الدوارف الحديدية لن يصدقوا هذه الخردة!",
[3512521910]="لقد سقط اشعاري كريستال! اثبتوا على ولائكم للـليتش كينغ يا إخوتي، وحاولوا استدعاءه مجددًا.",
[3513219342]="أخيرًا، ريدريدج. تغيير لطيف عن ضباب دسكوود المظلم البارد.",
[3513380678]="تحدقون بلا وعي في الهاوية!",
[3513448672]="اقتل!",
[3513499262]="البالادن ما زال حيًا؟ هل هذا ممكن، هايلورد؟ هل يمكن أن يكون نجا؟",
[3513606985]="مرمر فرمر فرمررر!",
[3513667447]="وأولئك في أزيروث الآن في فراشهم سيظنون أنفسهم ملعونين لأنهم لم يكونوا هنا، وسيستخفون بشجاعتهم كلما تحدث أحد عن الذين قاتلوا معنا في هذا اليوم المظلم.",
[3514106468]="يجب أن... أقاوم!",
[3514285518]="%s يشتعل بالكامل باللهب وتظهر نظرة مجنونة في عينيه!",
[3514320451]="أحيانًا، حتى عندما أكون مستيقظًا، أعتقد أنهم يراقبوننا. ربما يراقبوننا الآن...",
[3514691788]="أشعر وكأنني أستيقظ من كابوس، لكن الظلال في هذا المكان لا تزال باقية.",
[3514968606]="ورشة حصار إيستسبارك تعرضت لهجوم من الأليانس!",
[3514971063]="لن تعيش لتتحدث عن هذا!",
[3515027827]="%s يستدعي كابال ديثسورن لمساعدته!",
[3515523575]="تعال إلي أيها المدعي! أطعم نصلي!",
[3515597763]="اثبتوا أيها الإخوة والأخوات! النور سينتصر!",
[3515709604]="ماذا... ماذا أصبحت؟ آررغغه...",
[3516278956]="وأنا عازم على اكتشاف المزيد... لذا إذا احتجت مساعدتي مرة أخرى، فأنت تعلم أين سأكون.",
[3516327093]="مثير للشفقة...",
[3516400295]="لقد أعطيتك حجر قسم من تنين يسيرا، $N. عندما تكون مستعدًا وقادرًا على مساعدتنا، استخدمه، وعندها يمكننا البدء.",
[3517182622]="إنه ذكر غاضب!",
[3517184563]="احتضن النهاية!",
[3517219546]="أراك... قريبًا...",
[3517491131]="برينس آرثاس مينيثيل، في هذا اليوم، ظلام قوي استولى على روحك. الموت الذي ستنزله بالآخرين سيكون مصيرك اليوم.",
[3517516893]="لمجد لوكين!",
[3517858505]="شش... شكرًا. ظننت أنني سأموت.",
[3517924898]="ابعد أيديك القذرة الدراكارية عنهم!",
[3517992944]="إيكيس لن يموت -- راك راك --...",
[3518145096]="من مخبئه، يشرف على استعداداتهم للحرب بهدف إبادة عمالقة الحجر!",
[3518645815]="يا للأسف تركت ريشي الخفيف في البيت... السقوط البطيء سيكون مثاليًا هنا!",
[3519073848]="%s يتألم من الألم.",
[3519125298]="كدنا نصل إلى الملجأ! لنذهب.",
[3520050739]="أعداؤنا سيبادون!",
[3520811967]="لن يهم، ستكون ميتًا غدًا.",
[3521220766]="جهز حالك!",
[3521781927]="لا يمكن هزيمته. <تحترق الآثار وتتلاشى. الذكريات التي كانت بداخلها صارت لك. هذه المدينة دمّرها كائن ليس من هذا العالم.>",
[3521900749]="ابقَ قويًا. كايلثاس سوف - خطأ - لورثيمار سيقودك إلى القوة والمجد!",
[3522135724]="اخترت يوم سيء لكي أوقف الشرب!",
[3522223898]="هناك طريقة واحدة فقط لتطهير هذا السيف. أسرع إلى السانويل واغمر النصل في مياهه.",
[3522625104]="أتمنى إن محتوياته... تفيدك.",
[3522787044]="لا أعرف حقًا لماذا أنا هنا، لكنني مستمتع جدًا!",
[3523348751]="ما الذي يحدث هنا باسم برونزبيرد؟ انظر إلى هذا المكان! أعتقد...",
[3523781187]="هذا ليس عدلًا! يا عزيزي سولي! عد إليّ! لا، $N! لماذا جلبت لي هذا الخبر!",
[3523867336]="الشتاء بعد رفع اللعنة، مئات الأوركس المخضرمين مثلي ضاعوا في اليأس.",
[3523879302]="كما توقعت، الجواهر والعقد ليسا مهمين. الأمر كله يتعلق بمصدر الطاقة.",
[3524083937]="أنا يد الـليتش كينغ!",
[3524577791]="مذهل يا سيد. عدم كفاءتك مذهل.",
[3524825473]="أنا لست مجرد تنين. ستجد أنني أكثر بكثير.",
[3525202533]="$N هزم سيقريد آيس بورن للمرة الثانية. حسنًا، هذه المرة فعلها $Gهو:هي; بمساعدة أصدقاء $Gخاصته:خاصتها;، لكن الفوز فوز!",
[3525801992]="أحسنت. لننهِ هذا الأمر.",
[3526409063]="لم أشعر قط بهذه القوة تشع من أورك. هل هو... فانٍ...",
[3526558765]="فانكليف يدفع كثيرًا على رؤوسكم!",
[3527626191]="ليتني لم أكتشف ذلك النصل الملعون أبدًا...",
[3528297101]="عظامك ستلتهم!",
[3528380709]="بهزيمته، أثبت $Gهو:هي; و $Gخاصته:خاصتها; من الرفاق المقاتلين جدارتهم بالقتال في هذا المكان المقدس من شرف الفرايكول.",
[3528452792]="%s يبدأ باستدعاء بلاك هاند دريدويفر!",
[3528724710]="عيونك مضحكة.",
[3529020791]="إنه لأمر مخز، مخز جدًا، أن إخوتي لا يرون الفوائد التي تأتي من الانغماس الحقيقي في ثقافة ما.",
[3529055123]="أحب عرض الألعاب النارية في نهاية مهرجان النار في منتصف الصيف.",
[3529390817]="مقابل كل هورد سولجر قتلته — مقابل كل كلب من الأليانس سقط، نمت جيوش الـليتش كينغ. حتى الآن، تعمل الفالكير على إحياء سقطاك كسكورج.",
[3529392523]="انزف كما نزفت!",
[3529507492]="مغتصبون! نوميريغان لي!",
[3529771749]="بالكاد أصبت الهدف تلك المرة. همم،... ربما أحتاج للضبط لليمين.",
[3529919757]="تذكر يا فتى: أنت دائمًا أكثر خطأ مما تظن. ضاعفها!",
[3530158838]="لقد واجهت تحديات كثيرة... يا للأسف، كانت كلها عبثًا! قريبًا سيركع شعبك لسيدي!",
[3530748457]="%s يستدعي كابال أكولايت لمساعدته!",
[3530896970]="صدى الرعد يهز أرجاء الكهف.",
[3531103792]="المزيد، المزيد، المزيد! لا بد أن أتغذى قريبًا.",
[3531216133]="%s يبدو ضعيفًا بما يكفي للأسر!",
[3531286674]="الأعمال لي يا أخي! قريبًا ستزول من طريقي إلى الأبد!",
[3531370677]="رغم تعب أوصالكم ونزيف دمائكم من الجروح على هذه الأرض المبللة، أنتم تقاتلون من أجل أرواح عالمكم. لا قوة شريرة تستطيع الصمود أمامنا!",
[3531613885]="برج الحصن الشمالي الشرقي قد تضرر!",
[3531715618]="لا! طعم... قصير جدًا!",
[3531725807]="لا شك أن شيئًا ما شوّه التاريخ الحقيقي لـستورمهوف ومحاربي مخيم تونكالو. لكن، ما هو؟",
[3532248495]="لماذا؟",
[3532258561]="مذهل. ما هو، اندورمو؟",
[3532534352]="قبيلة ستونزبلينتر ستكون نهايتك!",
[3532849657]="الآن وقد بلغت قوتي الكاملة، يمكنني أداء مارتير. يمكنك استخدامه لحماية التنانين الأخرى، لكنني سأتلقى ضررًا كبيرًا، لذا تأكد من استخدامك أيضًا إيفاسيف مانيوفرز!",
[3533516676]="لا يمكنني الجدال في ذلك.",
[3533574968]="وقت الغزو يقترب بسرعة.",
[3533589313]="تم اكتشاف تأثير خارجي، تحت غطاء وهمي لرفيق ثوريم المتوفي، سيف.",
[3533754639]="من يجرؤ على وضع هذه الإهانة على مذبح غوك؟",
[3534010987]="هذه الكهوف كانت يومًا معبدًا للوعد بإعادة النمو في بارينز. الآن، هي قاعات الكوابيس.",
[3534205441]="أنت من بين تاونكا في معسكر أونيكوا، أيها الدوارف.",
[3534575397]="لتُستهلك من الضباب!",
[3534617733]="لا خطوة أقرب، أيها الأوغر!",
[3534637097]="أخيرًا سأنتقم!",
[3535048744]="أجل، لو كان كل يوم مثل اليوم فقط...",
[3535706780]="أنا أداة تدميرك، يا ملكي! مرني!",
[3535761789]="تقاتل بقدر ما تشاء...",
[3535788861]="أليكسترازا، مانحة الحياة. مخلوق رائع.",
[3535950532]="أوبسيديان انهض واخدم سيدك!",
[3536522233]="%s يبدأ في جعل الأرض تتزلزل.",
[3536574197]="هذا التحضير الخاص يمنحهم قوى فريدة أكبر بكثير مما كانوا سيعرفونه لولا ذلك.",
[3536978463]="لم يعد هناك وقت لي. لقد انتهيت. اقضِ عليّ، $N. افعلها وإلا سيقتلوننا كلينا. $N... من أجل الـهورد! هذا العالم يستحق الإنقاذ.",
[3537035632]="مهاجمون ناغا! دافع عن نفسك!",
[3537069064]="هاليون سيكون مسرورًا.",
[3537136669]="سيكون هناك وقت للشكر المناسب لاحقًا، لكن لا تزال هناك معركة نخوضها!",
[3537296187]="سأذهب معك. فقط أبقِ على رجالي. إنهم شباب طيبون ارتكبوا خطأً فقط...",
[3537573274]="أنا أغلق الباب. حظًا موفقًا، وشكرًا لك على فعل هذا.",
[3538204230]="الموت لـ$N! يحيا عشيرة بلاك روك!",
[3538682805]="في المقابل، 'أزال اللعنة' عنا، قائلاً إننا 'نُصلح' بإعادتنا إلى حالة كوننا كائنات ميكانيكية.",
[3538736328]="هل يشتكي من المواد الكيميائية مرة أخرى؟ هل يتذكر حتى كيف ترك كتب الاستدعاء آخر مرة؟",
[3538854595]="غيرت رأيي أيها الخدم المخلصون، لستم بحاجة لإحضار السجين إلى مكتبي، سأتعامل معه هنا والآن.",
[3539070661]="آفات بائسة. سأبيدكم من الجو!",
[3539241418]="لقد اقتربنا. ابحثوا لي عن بعض...",
[3539340648]="أتذكر خيانتك؟",
[3540566262]="أين تذكرتك؟",
[3541036749]="لا... لا لن يفعلوا. لكن يمكنني تصحيح هذا... لدي خطة. سألحق بالفتى. سأجعله يتحمل مسؤولية كل ما فعله.",
[3541198395]="بالتأكيد ترى عبثية كل هذا!",
[3541484952]="إنهم يطاردون البيرة!",
[3542645236]="ميتز؟",
[3543279296]="بإذنك يا سيدي.",
[3543628074]="لااااااااااااااا.......!",
[3543899830]="هذا صحيح، أوغ. النصر أو الموت!",
[3544567538]="متى كان الـدوارف أصدقاءنا أصلًا؟",
[3546524649]="سيدي، هدية لك!",
[3546832292]="يمسك مورادين برأسه ويتمايل للحظة بينما تعود الذكريات إليه دفعة واحدة.",
[3546876206]="هيه!",
[3546960969]="تتوهج عينا %s باللون الأحمر للحظة وجيزة.",
[3547038872]="رأيت سي جاينت مرة. ليس شيئًا أرغب في رؤيته مرة أخرى. تجشؤ!",
[3547453058]="أنا... أنا حر! كان الإيثيريوم يخططون لتعذيبي حتى أستسلم لطلباتهم. أخشى أنه لولا قدومك، لكنت رضخت لعذابهم بالتأكيد.",
[3547851796]="أؤكد لك أننا لن نفشل، يا سيدي. أنا أشرف شخصيًا على كل جانب من جوانب البناء، وأحتفظ بالرموز النهائية بنفسي. خلال يوم واحد، سأفجّر القنبلة في أولئك الآفات القريبين.",
[3547909622]="بالمناسبة، شكرًا لمراقبتك ظهري.",
[3548072252]="السيف ليس أداة، إنه امتداد لك. أتوقع أفضل!",
[3548082856]="الأحياء هنا!",
[3548506811]="بدء تحليل معبد الشتاء.",
[3548531109]="هاه! عبيدي جلبوا وجبة حقيقية هذه المرة!",
[3548733997]="تهانينا. لطالما أردت فعل ذلك لسنوات.",
[3548809472]="أندرسيتي تشامبيون يلوح لـ أرجنت كونفسور باليتريس ويعود إلى مقعده.",
[3549484969]="الليتش، كيلثوزاد. يخدم الـليتش كينغ دون سؤال، كان مستحضر أرواح عظيمًا في حياته، وتحول إلى سيد في تحضير الأرواح بعد موته. يُقال إنه أكثر رعايا الـليتش كينغ ولاءً.",
[3549933841]="هيميت؟ فيتز؟",
[3550522325]="نقاتل حتى الموت!",
[3550751560]="الأفضل ما تقولها بصوت عالي!",
[3551882854]="كوماندر! هذا اللحمي أنقذني!",
[3552205027]="نضالك لا معنى له. كلكم ستسقطون أمام الـسكورج الذي لا ينتهي!",
[3552480786]="مغيرون في الشمال! أطلقوا النار!",
[3552686024]="استعد قوتك. المكان الذي سقط فيه ستيلجو أمامنا.",
[3552836986]="اخرجوا من الظلال! عدت لأقودكم ضد عدونا الحقيقي! اخلعوا قيودكم وارفعوا أسلحتكم ضد أسيادكم الإلیداريين!",
[3552886849]="كن على حذرك، $N!",
[3553813199]="شكرًا لأنك أصبحت ضحيتي التالية!",
[3554079795]="لا أستطيع السيطرة... إنه يجذبني... الفراغ يكبر...",
[3554185026]="انتقم لأصدقائي الذين ضحوا بهم بالفعل!",
[3554604289]="من يجرؤ؟!",
[3555025242]="%s يستدعي رسولاً...",
[3555131554]="سباير فروستويرم يحط قبل الـ سكاي بريكر مباشرة.",
[3555178942]="قواي... قواي تضاءلت... ستدفع ثمن هذه الوقاحة!",
[3555789185]="يا مدافعي داروشر! تجمعوا! يجب أن ننتصر!",
[3555812943]="عدنا وأفضل من أي وقت مضى! إنه معرض داركمون، يا صديقي، وهذا يوم حظك! دون توفير في النفقات، جمعنا عجائب ومأكولات من جميع أنحاء العالم لإسعادك. سواء كنت صغيراً أو كبيراً، غنياً أو فقيراً، معرض داركمون لديه كل شيء! تأكد من تسليم تذاكر جوائز معرض داركمون إلى قيلفاس قرايمقيت، واختر من بين عدة جوائز غريبة ورائعة!",
[3556614380]="أيها الأبطال البشر - انتصاركم هنا اليوم كان متوقعاً منذ زمن بعيد. صرخة أخي المؤلمة بالهزيمة ستردد عبر الكون - مما يجلب أملاً متجدداً لكل من لا يزال يقف ضد البيرنينغ كروسيد.",
[3557418201]="بالتأكيد لن تحرم رجلاً عجوزاً من شراب منعش؟ لا، لا، ظننت ذلك.",
[3557796360]="الواقع... منحل.",
[3558275533]="فقلت: \"أجل، لكن ذلك سيكلفك إضافيًا.\"",
[3558380534]="كيف؟ الهيومنز أغبياء حقًا، صحيح؟ ذيلزانلـ دسك برينقر! ثيلزان الـليتش! الذي وُلد من لحم وعظم بشري، ضحى بكل شيء من أجل القوة، محمي بواسطة الـليتش كينغ!",
[3558735761]="ما أفهم كيف تعيش هذه الحيوانات القذرة في هذا المكان... يالها من رائحة!",
[3559551235]="بأمر ملكي، عليكم أيها الرجال العودة إلى لوردايرون فورًا. لورد أوثر أقنع الملك بإلغاء هذه الحملة.",
[3560945760]="حشرات صغيرة قابلة للاشتعال...",
[3561251669]="شكرًا وحظ سعيد!",
[3561731747]="آه، مسافر قوي آخر. نيذر يمكن أن يكون خطيرًا؛ ستحتاج أقوى التعاويذ تحت تصرفك. أحمل أفضل المواد، العادية والغريبة. تعال، اشتر - لن تندم!",
[3561800037]="هل أنت مستعد للتحدي؟ لن أتراجع.",
[3561891319]="أنت عديم الفائدة، كويمبي!",
[3562009854]="لن أموت مرة أخرى! ليس على يد أمثالك!!",
[3562259873]="لقد مضى وقت طويل منذ أن جاء مسافر إلى هنا حاملًا الزهور.",
[3563191526]="أنا بارد يا سيد. متى ستحقق وعدك؟",
[3563391162]="آه، لقد جاءت يد النصل الأسود لتأخذني أخيرًا. أنا أرتعش خوفًا.",
[3564497902]="سأنتظر.",
[3564660037]="اقتلهم جميعًا!",
[3564966294]="حسنًا، الآن أو أبدًا على ما أظن. تذكر، بمجرد أن نصل إلى الطريق بأمان، عد إلى تيرينثيس وأخبره أننا هربنا.",
[3565260734]="سآخذك إلى بعض الخيول الأخرى. ربما تفتقد التواجد مع خيول أخرى. يمكنهم أن يكونوا أصدقاء لك أيضًا.",
[3565336224]="اكتمل التحليل. هناك فساد جزئي في أنظمة دعم الحياة على الكوكب بالإضافة إلى فساد كامل في معظم آليات الدفاع على الكوكب.",
[3565543844]="أنا... أستسلم. طالما أن سيمر يوافق على التوقف عن غليان بركتي، فأنا أوافق على الهدنة.",
[3565703170]="لقد ناقشنا هذا من قبل. فقط هجوم مركز على ديثولم سينجح. هذه الأهداف الأخرى هي مشتتات لا يمكننا تحملها. أقتسوف أن تخبر كابتن هيليوس الخاص بك بأن يتوقف عن حملته ضد ترولز شادوباين ويركز فقط على الـسكورج.",
[3566027208]="شاهد العالم ينهار من حولك!",
[3566359173]="في الوقت المناسب، هيلكيولار... كل شيء في الوقت المناسب...",
[3566403760]="لقد رأيته... من هذه البلورة المباركة سنصنع سلاحًا. هذا السلاح سيحمل بداخله قطعة من كل منا... وعندما يُستخدم ضد الأنديد، سيلقيهم أرضًا. وفي أثره، لن يترك سوى رماد...",
[3566533317]="بحذر. بحذر! هل شعرت بارتجافة؟ ستسقط ذلك البرج أيها الأبله!",
[3567045658]="واو.",
[3567818020]="لقد واجهنا الكثير من النكسات على طول الطريق: هيلفاير سيتادل، فالين سكاي ريدج، فايروينغ بوينت... الأمير كيل'ثاس لن يتسامح مع أي تأخير آخر. أنا لن أتسامح مع أي شيء سوى النجاح الكامل!",
[3568244545]="قرولوك يستمتع كثيرًا!",
[3568522406]="فهمت. سأعود قريبًا.",
[3568619354]="هذا ينتمي إلى فايروينغ بوينت. لن تضع يديك القذرة عليه!",
[3569189155]="انهض، يا فولدون الصغير. لا تقلق نفسك بالمجاملات. لقد جئت بأمر من سيدنا، الأمير كيل'ثاس. يأمرني بالتحقق من تقدم قنبلة المانا.",
[3570116243]="موتي لا يحقق شيئًا! السيد سينالك! ستغرق في دمك! العالم سيحترق! آآآآه!",
[3570493431]="خلص عليه!",
[3570898217]="قوى المراقب تتعزز بوجود الخدم القدامى.",
[3572166456]="ألغوا المهمة! قواتنا البرية هُزمت.",
[3572246908]="سيدنا المظلم لاحظ تلاعبك، وأرسلني لأحمل رسالة... دمار!",
[3572589940]="ابتعد، $N، قد ينقض الوحش ويؤذيك.",
[3573157764]="انتبه لنفسك، أيها الهاي بورن.",
[3573959892]="<سعال> أوف...",
[3574003465]="لماذا تريد إيذائي!؟ تعال. يمكننا أن نكون أصدقاء!",
[3574766742]="كم هذا محرج! أحدهم ظنني واحدًا من قرياتفادر وينترز هيلبرز.",
[3575202986]="نهايتك تقترب!",
[3575535407]="ابتعدوا، أيها الطفيليات عديمة العقل! دمي ملكي!",
[3575755356]="هذا ريقر قيزيلتون يطلب المساعدة لمرافقة قافلتي بجانب مانوروك كوفن. أنا على الطريق شرق قرية شادوبري.",
[3576441337]="باسم سارجيراس!",
[3577118332]="%s تحول إلى أنقاض، لكنه لا يزال يواصل القتال.",
[3577272134]="لا شيء يمكنك قوله سيجعلني أدخل الحلبة ضد ذلك الوحش الآلي الذي تسميه دبابة بخارية!",
[3577318465]="كان قلقًا من أن قوته تضعف، وأنه قريبًا حتى آخر أحجار روحه الثمينة ستتلاشى وتموت.",
[3577747316]="سيدي... هل اكتملت... خدمتي؟",
[3578132854]="إنه عزاء صغير أن أرى أنهم لم يعيدوا أيًا منها كأنديد.",
[3578583012]="عبر هذه المساحة الشاسعة ترقد عظام أجدادي. أرواحهم صعدت إلى غرفة الأسبكت.",
[3578689887]="هجوم!!!",
[3578981433]="تم رفض الطلب. رموز الرد مدمجة في كيان مراقب ألجالون. هو الرسول والرسالة معًا.",
[3579088077]="%s تستعيد رباطة جأشها.",
[3579251811]="كان يمكن أن يكون أفضل. $N، تعالي هنا من فضلك. لدي شيء أريدك أن تتولى أمره من أجلي.",
[3579614351]="تطهير؟ لا لا لا لا لا.. أين وضعت-- آه، هذا يجب أن يفي بالغرض...",
[3579938165]="لن توقف صعودي، أيها $R الصغير. حان وقت الموت!",
[3580314615]="من أجل كارجاث! من أجل النصر!",
[3580366973]="لا، سيدي.",
[3580746465]="انتظر لحظة: هذا لا يبدو صحيحًا! بجانب هذا الضوء الوامض... ما هذه إشارة ألجالون؟",
[3580962199]="من الواضح أن هذا لا يوصلنا إلى شيء. نحتاج لإيصال هذا السارونايت إلى هايلورد فوردرينغ لمزيد من الدراسة.",
[3581017272]="هذه ليست أول ملكة تقتلها فرينزي هارت. يبدو أن هناك دائمًا المزيد.",
[3581623312]="دخلاء! بيدق آخر من فجر الأرجنت، بلا شك. لدي بالفعل واحد منهم بين أسيراي. انسحبوا من مملكتي قبل أن تُعدم!",
[3581750663]="مولاي! لقد فعلت كما طلبت، والآن أتوسل إليك من أجل بركتك!",
[3582048790]="دينغ! 428,000 درجة كراكلنهايت، بالضبط! حسنًا، تقريبًا. تقريبًا. في مكان ما هناك...",
[3582108690]="لا تلمس البوغ!",
[3582286988]="النجدة!! أخبرتك أن هذا المكان ملعون!",
[3582329968]="هل ظننت حقًا أنك ستغادر هنا حيًا؟",
[3582358327]="سايروك قادم إليك!",
[3582400143]="جئت تخلص الشغل، مون؟",
[3582713122]="ميست ذوو الألسنة الكبيرة أذكياء مع معبدهم أحيانًا... يغطون المنطقة كلها بالضباب ويصعب العثور على أي شيء.",
[3583051220]="فقط إذا لم نتبع إجراءات التهيئة الصحيحة.",
[3583264035]="الـ%s يبدو مشوشًا.",
[3583443629]="تحرك، $C!",
[3583705920]="إنه قادم نحونا!",
[3584803101]="اغفر لي، يا أبي! أرجوك...",
[3584882760]="هذا البرج يزود مطرقة هودير بالطاقة. يُقال إن لديه القدرة على تحويل جيوش كاملة إلى ثلج!",
[3584905294]="زيمبو لا يمكن إيقافه! يجب تحرير القلعة!",
[3585225599]="سأقوم بدورية في المنطقة لبعض الوقت لأتأكد من أن الأمور آمنة حقًا.",
[3585882282]="بالطبع، سيدي.",
[3586098748]="الموت للزاندالاري ودمىهم! لا شيء يمكن أن يوقفنا الآن!",
[3586462642]="واو! الضحكات لا تسقط كثيرًا هنا، أليس كذلك؟",
[3586593120]="طبول الحرب تدوي من بعيد.",
[3586605361]="للأسف، أحيانًا يجب على المرء أن يتولى الأمور بنفسه. بالامور شانال!",
[3586779840]="%s يئن لكنه يبدو غير متأثر بالآفة.",
[3587598046]="لا أستطيع مساعدتك إلا بموت نظيف.",
[3587782211]="الآن، خذ نظرة طويلة أخرى قبل أن نتوجه إلى الحي المقدس وكاتدرائية النور العظيمة.",
[3588102496]="يبدو جيدًا لك... وسيئًا لي.",
[3588270232]="مالقانيس سيرسل بعضًا من أتباعه من الـسكورج للتدخل معنا. من يملك أقوى الفولاذ والسحر منكم سيتقدم ليدمرهم. سأقود بقية قواتي لتطهير ستراثولم من المصابين.",
[3588333086]="لقد فعلتها! لقد سخّرت قوة الحجر في النظارات! لنخرج من هنا!",
[3588459863]="انفجار قادم بعد 5 ثوانٍ. اخلوا النفق! ابقوا بعيدًا!",
[3588499250]="فايلاستراز، عندما يصبح هذا العالم ملكًا لسرب الأسود، سيعرف سربك نهايته.",
[3588746381]="مخ...مخ!",
[3589121035]="أحسنت المجيء. حكمتي ستكون لك.",
[3589229095]="إلى السلاح!",
[3589229166]="الحراس الأربعة لـاولدوار: فريا، ثوريم، هودير، وميميرون. الأختام مرتبطة بسلامتهم الجسدية والعقلية. جميع الأختام الأربعة مطلوبة للوصول إلى القبة السماوية.",
[3589263540]="سواء بالشفرة أو التعويذة، الدم يغذي هجماتنا ويضعف أعداءنا.",
[3590173161]="السيد منغمس في الدراسة.",
[3590198973]="تينبرون يبدأ في تفقيس البيض في الشفق!",
[3590363939]="نحن نسيطر على السحر! لن يُستخدم ضدنا!",
[3590670819]="اس...تهلاك.",
[3590690411]="%s ينتقل إلى المعركة!",
