[3613444446]="أوه، هذه أكيدة.",
[3613445332]="أرجوك، أيها الفاني، ابحث عن ماجيستر هاثوريل في دالاران. قد يتمكن من التفاوض مع الميثاق الفضي للوصول إلى الكتاب.",
