[3616571378]="المدرج العظيم للألم ينتظرك، $N. تذكر، بمجرد أن تبدأ المعركة يجب أن تبقى في الحلبة. انتصر أو مت!",
[3617010704]="أنا لا آكل لحم الخنزير...",
[3617423328]="الناغا لا يحترمون الطبيعة. يلوونها ويفسدونها لتلبية احتياجاتهم. يعيشون لإثارة الأرواح.",
[3617661497]="بسرعة! $N يهاجم!",
[3617768403]="لقد تأخرت أيها المشرف.",
