[3620152420]="هي! هي أنت! $R! هناك!",
[3620959031]="لا أعرف أيهما أسوأ: أن يؤكل المرء على يد فيل أوركس، أم أن يعمل عند سيد العبيد رازيلكراز! على كل حال، شكرًا لك!",
