[3628170961]="لقد تم اكتشافنا! انتظروا. يجب أن نخرج من هنا!",
[3629071060]="بهزيمته، أثبت $Gهو:هي; ورفاقه المقاتلون $Gخاصته:خاصتها; أنهم يستحقون القتال في هذا المكان المقدس من شرف الفايكرول.",
[3629518891]="وما هذا الآن؟",
