[3629764536]="%s يصوّب نحو الزجاجات...",
[3629964240]="لنرَ إن كان هذا سينجح.",
[3630036809]="حسنًا، $N.",
[3630133073]="أنا... سأخفيه. سأخفيه حتى أجد له موطنًا بعيدًا عن هنا...",
