[3630825074]="أجل، سيدي!",
[3631067425]="ماغني! سامحني، الذكريات تعود ببطء يا أخي.",
[3631160926]="تظن أن يوماً ما، كيكيك سيقود الـفرينزي هارت للوطن، مثل رجال الدب يحاربون لاستعادة مدينة الشجرة؟ كيكيك يريدون وطنهم الخاص، ليس مدينة مع الرجال البنفسجيين، ولا غابة مع كبار الألسنة.",
[3631721836]="رانولف من الـسكریمینغ أبيس! أطفئ هؤلاء الديدان بأظلم ليل!",
[3631874823]="هي، من قرع الجرس؟",
[3632265780]="القلب... آخر بقايا إنسانيتك. كان علي أن أمنع تدميره. كان علي أن أرى بنفسي. وأخيراً أنا متأكد...",
[3632465396]="كل ما تبقى من $N هو بقعة حمراء على الأرض!",
