[3634526401]="ربما كان عليك البقاء... في الجبال!",
[3634944039]="فرست بايت تتبع الرائحة حتى مصدرها. افحص الكهف!",
[3635243243]="جلالته، كينق فاريان راين، وليدي جاينّا براودمور قد هبطوا في أرض البطولة! أفسحوا الطريق!",
[3635425356]="من يجرؤ؟! سأدمرك!",
[3635618033]="عبروا أثرًا من الثلج الملطخ بالدماء وتبعوه ليجدوا قزمًا يتجول ويتحدث بلهجة لم يستطيعوا فهمها... وليس قزمًا من جنسنا، بل قزم جبلي - شيء لم يره جنسنا من قبل.",
