[3636481273]="كم من الوقت يستغرق لقطف حفنة من الأعشاب؟",
[3636756622]="فات الأوان للهروب الآن. لا تترك الحلبة. مت بشجاعة، $N!",
[3637906576]="الأسبوع الماضي كنت في غولدشاير. هل ذهبت هناك؟",
[3638629723]="حر أخيرًا، مون.",
[3638762344]="استمتعت أكثر بتعذيب البيونز!",
[3639244143]="لقد غبت لوقت طويل... الأفضل أن أعود.",
[3639313372]="ربح!",
[3640120740]="جبان! أتظن أنك ستوقف وارتشيف الـهورد بالحصى؟ سأريك القوة الحقيقية للعناصر!",
[3640930352]="حسنًا، مون. أخبرني عندما نكون قريبين من إخوتي الترولز.",
[3641758159]="تطهر بالنور، أيها الهيومن! لا تدع الفساد الشيطاني يغمرك.",
[3641839646]="كنت أعمل على تعويذة صغيرة لمواجهة مشكلتي وكنت قريبًا جدًا من إيجاد <كرووواك>... يا إلهي!",
[3641885314]="لا تتراجعوا! دمروهم!",
[3641888881]="آه! أنت ميؤوس منه!",
