[3642613951]="بماذا كنت تفكر حين استفززتها هكذا؟",
[3643582167]="لا! لا يمكنك هزيمتي!",
[3643705770]="السماء مظلمة. النار تشتعل. تسعى عبثًا بينما تدور عجلة القدر.",
[3643788341]="أكاذيب! الألم الذي ستتحمله قريبًا سيتحدث عنه لسنوات قادمة!",
[3643823460]="نارو قبلوا المنشقين، الذين سيُعرفون باسم سكريِرز؛ مسكنهم يقع في المنصة أعلاه. فقط أولئك الذين بدأوا بـ سكريِرز مسموح لهم بالدخول.",
[3644003239]="القتلة الأولى من نصيبي! هل من أحد يريد المراهنة؟",
