[3644409593]="وصل المنطاد إلى ثندر بلف! الكل على متن لرحلة سلسة عبر البرينز!",
[3644920835]="غرزت أسلحتي في أجساد وعقول أعدائي.",
[3645039113]="يجب أن تشعر بالفخر لأنك تنفذ أوامر ليدي فاشج.",
[3645475776]="لقد فعلناها يا رفاق! لقد أخذنا القمة من الـسكورج! أبلغ فاذر قوستاف فورًا وأخبره بالأخبار السارة! سنبدأ في البناء والتجهيز! انطلقوا!",
[3645609208]="أيها الأوركس من الـهورد! هذه البوابة هي مدخلكم لمصيركم الجديد! أزيروث أمامكم، جاهزة للاستيلاء عليها!",
[3645644923]="بناء السفن.",
[3646544657]="تحركوا! هذه البلورات لن تجمع نفسها بنفسها.",
