[3660947116]="النوع: شيفارا",
[3661558504]="تقدمك في هذه المنطقة كان مثيرًا للإعجاب، أمير الدم. أنا مسرور.",
[3662131979]="إنه قوي جدًا. يجب أن نغادر هذا المكان فورًا! سحرتي يمكنها تثبيته لمدة قصيرة فقط. تعالوا بسرعة أيها الأبطال!",
