[3662520628]="اعملوا بجد أكثر أيها الكلاب!",
[3662583965]="واو! شكرًا لإعادته إلى هنا. لم يكن عليك فعل ذلك.",
[3663476948]="قلُث، كلب الطاعون النجس لـناكسماراس، قيل أن شهيته كانت نهمة لدرجة أن الأحياء لم تكن كافية لإشباع جوعه. قيل أن فيوجن كان يطعمه جيشًا من الزومبي يوميًا، معيدًا تدوير بقايا الأنديد الضعيفة جدًا لاستخدامها في القتال.",
