[3689105382]="عندما يحين الوقت المناسب، سيدتي. كل شيء سيتضح عندما يحين الوقت المناسب. السيد يتحرك حتى الآن. انظروا إلى السماء، فقد عاد برود أوف نوزدورمو.",
[3689908196]="هذه نصيبك.",
