[3706607957]="لكن هذا لا يمكن أن يكون صحيحًا. أين وضعت ذلك الكتاب الآخر؟",
[3706763563]="آه... الألم... الألم لا يطاق تقريبًا مثل الجلدات التي تلقيتها في المدرسة الابتدائية عندما كنت طفلاً.",
[3706763885]="من أجل دراغونماو!",
[3706949007]="مذهل! إذاً إندوريوم هو المفتاح!",
[3707040158]="الدرع سقط؛ فاروس ضعيف! هزيمته يجب أن تفرق أزور رينق غارديانز وتسمح لنا بالوصول إلى النطاقات العليا. فاروس على منصة طافية في منتصف الأوكيولس تقريباً، على نطاق التسارع.",
[3707693434]="جزء من هذه الأرض ملكي بالفعل، مون، لكنها مجرد البداية!",
[3707824914]="هذه الكائنات لا تعطي نفسها الأرقام الفائزة في يانصيب ستورمويند، عزيزي.",
[3708148080]="من يجرؤ على تعطيل قدسية إلدر'ثالاس؟ واجهوني، أيها الجبناء!",
[3708150066]="نعم، لا، ربما لا.",
[3708629693]="ستكون قرباناً مناسباً لـراقناروس.",
[3708967709]="إذاً... عمل أم متعة؟",
[3709729201]="أرواحنا لن تُحرر أبداً.",
[3709843659]="ورشة حصار المعبد المكسور تم الاستيلاء عليها من قبل الأليانس!",
[3710000444]="ستدفع الثمن الأقصى لهذه الوقاحة، أيها الحشرة الصغيرة. روحك لي!",
[3710159907]="بسست... $R، هنا! بجانب الحوت الميت.",
[3710597390]="جيد جدًا. أنت في راحة، أيها الجندي. استرح، لكن لا ترتاح كثيرًا. كورزن لن يتركنا وشأننا للأبد.",
[3711282735]="...تمتم...بتلات النار...تمتم...",
[3711294736]="هجوم! من أجل ستورم ويند! من أجل بولفار! من أجل الأليانس!",
[3711860894]="لدي الكثير من العجائب لأريك إياها.",
[3712116907]="هذه النكتة حارة.",
[3712601783]="أوفرلورد أقمار يطلب منا المزيد! يجب ألا نخيب!",
[3712814929]="داجيك ينسى ما يفعله، وأين هو... أحيانًا حتى ينسى اسمه. هذا يجعله معلمًا ليس جيدًا أحيانًا.",
[3713165147]="زهقت من هالروتين.",
[3714172253]="شو؟ هار'كوا؟!",
[3715482330]="لا تخف يا سيدي. سأمزق لحم عدوك!",
[3715697322]="انظر! هناك عند جدار النفق!",
[3715761175]="فشلت مهمتي في حراسة المعبد... روحي الفاسدة لا تعرف سلامًا...",
[3716204069]="تم اكتشاف استخدام قرص المخترع. تفعيل البروتوكول الطارئ غاما.",
[3716428592]="هذه الوقاحة... هذه الغطرسة... يجب أن تُعاقَب!",
[3716611610]="سبراغل! ما كنت أتوقع أن أعود!",
[3717436947]="أيها الحمقى البؤساء، لم تعرفوا أبدًا كيف تختارون جناح خفاش لائق.",
[3719367705]="هذا غير قابل للتصور حتى من بعيد!",
[3719374922]="أمعاء أكثر! دم أكثر! طعام أكثر!",
[3719468767]="فقط لحم وعظم. البشر فريسة سهلة...",
[3719897271]="%s يبدأ بدمج بلورات ملونة مختلفة معًا.",
[3719923228]="هذا لم يحدث حقًا!",
[3720044537]="قريمكلو?! رويدك يا صديقي... أين سيدك فولكور؟",
[3720648246]="وهذه هي وصفة أشهى شوربة بروكن!",
[3721034020]="لن تحصل... على أي شيء آخر... مني!",
[3721349140]="داركنس قادم إليك....",
[3721860735]="ظننت أنني سأموت بالتأكيد.",
[3721873429]="الفرسان، فلننطلق!",
[3721901948]="استمروا في جلب المشروبات؛ الليلة ستكون طويلة!",
[3721957143]="من... من أنت؟ من... ما أنا؟",
[3722143633]="آآآه! بومرنغ!",
[3722169931]="أطلق سراحي فورًا أو واجه غضبي!",
[3725659625]="سيكون هذا اختبارًا جيدًا، برينس آرثاس.",
[3725925277]="في هذا اليوم، رُفع عن صدري عبء كبير. قلبي يمتلئ فخرًا. ولأول مرة، أستطيع أن أعلن بكل فخر من أنا. أخيرًا يمكنني إطلاق العنان للغضب في قلبي.",
[3726338713]="تشخيصات ألغالون تقيّم خطر فساد الإله القديم في الوظائف الحيوية للكوكب. جارٍ حساب احتمالية رمز الرد أوميغا...",
[3726575974]="أقاتل بروح جامحة...",
[3728715954]="ابدأ!",
[3728865564]="هذان الأحمقان الشجاعان الجاهلان يكرهان بعضهما البعض، لكن بطريقة ما تحدث كلاهما عنك كبطل. ربما تفتقر فقط إلى الإرادة لاختيار جانب... دعوني أمنحك تلك الفرصة.",
[3729972289]="أجل، أيها المدرب.",
[3730071461]="تك بوت حساس وهذه الكلمات تؤذي أذني.:[ أرجوك كن لطيفًا معي. أنا فقط أريد المساعدة.",
[3730779697]="انيا!! أنت بخير!",
[3730974790]="هذا المكان سيكون مقبرتك.",
[3731144977]="لقد نجحنا! لقد نجحنا حقًا!",
[3731154460]="انتباه %s يتحول إلى صدع على طول الجدار الجنوبي للمعبد.",
[3731917768]="برج القلعة الشمالي الغربي قد دُمّر!",
[3732192866]="على ماذا تنظرون؟ اسكبوا لي شرابًا آخر!",
[3732369174]="اغفر لي ما أفعله! أنا... لا أستطيع... التوقف... فقط الكوابيس تبقى!",
[3732662427]="ذرق مرقط!",
[3732671137]="انظروا! العنكبوت الأزرق يقيم وليمة على شرف $Gخاصته:خاصتها;!",
[3733540798]="محل مركبات ريجسبارك مفتوح للعمل!",
[3733847146]="أتجرؤ على تحدي وينترسكورن؟! سأخوزقك بعلمك التافه!",
[3734057522]="بقوتك وإصرارك، لا يمكننا الفشل!",
[3734153636]="الجميع يمرضون - هذا وباء!",
[3734502944]="لن يتوقف حتى يصل إلى التجسيد الجسدي لمالفوريون. هذا لا يجب أن يحدث... يجب أن نشغل الوحش حتى وصول تيراندي.",
[3734697334]="تعال إلي الآن، $N. لا بد أن أتحدث معك.",
[3734802468]="اخترت الخصم الخطأ.",
[3734907359]="تروب سيريك يعرف كيف يطير مثل دراغونماو... وستريه كيف تموت مثل ضعيف.",
[3735028218]="وصلتنا رسالة بران، وبدأنا الاستعدادات.",
[3735390632]="هل تتحداني؟ لدي قوة عشرة رجال!",
[3735784305]="لا!!! لعنة عليكم أيها المتطفلون! جيوش الـليتش كينغ ستطاردكم. لن تفلتوا من مصيركم...",
[3736077996]="كن حذرًا، $N. تلك الذئاب تحب الاختباء بين الأشجار.",
[3736536852]="يحاول ثرال تهدئة الحصان.",
[3736613048]="حسنًا، يا فتى، يمكنك البدء بقراءة 'التلال الخضراء لسترانغلثورن'. ثم ربما تنضم إلي في إحدى رحلات الصيد. ما رأيك؟",
[3738105526]="في المرة القادمة، احضر معك أصدقاء أكثر!",
[3738106202]="لكن لم يكن مقدرًا لها ذلك. بينما كان أعداؤها يقتربون، اخترق نصل شيطان مسموم درع أناثيرا. في خضم المعركة، لم يكن هناك ما ينقذها.",
[3738149848]="وابقَ ميتًا!",
[3738686617]="انظر إلى عالمك من خلال عيني: كون شاسع لدرجة لا تُقاس - غير مفهوم حتى لأعظم عقولكم.",
[3739106273]="لا شك في مثابرتك... لكن هناك فضائل أخرى يجب أخذها بعين الاعتبار.",
[3740018713]="$N و $Gخاصته:خاصتها; رفاق السلاح اختاروا قبول القتال الشريف داخل حدود فالاهالاس المقدسة.",
[3740055356]="مجرد طعم... لما ينتظرك.",
[3740372062]="ظننت أن لدينا ما يكفي في مجالك، لكن يبدو أن لدينا بعض الشواغر. تقدم إلى مسؤول الاتصال المدني.",
[3740410864]="لا، لقد هربنا من تلك الوحوش! إنهم ليسوا مثلنا أبدًا، قريزيلدا.",
[3740417226]="الـسكارليت كروسيد عاجزون عن إيقافنا!",
[3740466771]="اختلف معي كما تشاء، أيها الـهاي إكسكيوشنر. سأزن رأيك، ثم سنتخذ الخطوات اللازمة لتحرير كويل'ثالاس كما أرى ضروريًا. سنواصل هذا النقاش لاحقًا.",
[3740509091]="العدالة الوحيدة هي الموت!",
[3740766340]="هذا دغدغة ليس كويسة!",
[3741044426]="المزيد من عملاء الـسنديكيت على ما أظن! لن تستعيدوا ألتراك أبدًا... أو ساوثشور!",
[3741116867]="مرحباً أيها المواطن.",
[3741218569]="$N و$Gخاصته:خاصتها; رفاق السلاح اختاروا القتال الشريف داخل حدود فالاهالاس المقدسة.",
[3741289218]="بماذا تعتقد أنك تفعل؟",
[3741425001]="لذيذ. أحب الـبليينسترايدر المشوي.",
[3741572584]="أنتم ملكي الآن، أيها الصغار. ستنشؤون لتكونوا جزءًا قويًا من الـهورد!",
[3741586650]="تطهير العالم من القذارة النجسة ليس عملًا سهلاً، يا نانسي. لا بد أن يقوم به أحد.",
[3741630569]="فاردمايرا؟! هل أرسلك الـليتش كينغ شخصيًا؟",
[3742293191]="الكلام في شبه الجزيرة هو نعم!",
[3742548434]="تجرؤ على استدعائي؟ ستُعاقب وقاحتك.",
[3743017240]="قف وقاتل!",
[3743079772]="نجدك غير مستحق للصعود، هالفدان. دع روحك تعرف الفناء!",
[3743224828]="أنا في خطر! ساعدني إن استطعت!",
[3743261218]="غير فعال تمامًا. مثل شخص آخر أعرفه.",
[3743318202]="ظننت أننا أصدقاء يا صديقي! ستترك حكمود عالقًا؟",
[3743320177]="حان وقت عملية قلب مفتوح صغيرة!",
[3743524476]="بوابة الزمرد الأخضر دُمّرت!",
[3744298577]="لأقطع حلقي بنفسي أسرع. ستدفع ثمن ما فعلته برجالك، آرثاس... وبما فعلته بي! أقسم بذلك.",
[3744356640]="لا بأس يا إد. كنزي مؤمن جيدًا في ذلك الصندوق. لن يجد أي أحمق كنز الكابتن ساندرز! لنذهب لنشرب مرة أخرى. المشروبات بدأت تنفد.",
[3745097500]="تفضل يا صديقي! آيسهامر داخل مبنى الفرايكول ذاك! ألقِ عليهم الجحيم!",
[3745414792]="كوخ الإغاثة فروست وولف استولى عليه الأليانس!",
[3745533143]="والآن، إن تفضلت وأبعدت مؤخرتك عن حدادي...",
[3745562399]="القوة ستكون لك!",
[3745861627]="هل أنت متلهف للموت؟ سأكون سعيدًا بتلبية طلبك...",
[3746074748]="ليستا، استدعِ الأسرى.",
[3746115951]="سأستخدم المسبك لصنع دفعات من الإيرذن لحراسة المكان... لكن التحدي الأكبر ما زال قائمًا: اعثر على لوكين وأوقفه!",
[3746756129]="من أجل سموها... من أجل... فاشج!",
[3747207494]="إيتو ماقموثريقار، تشا!",
[3748056391]="%s يطلق سربًا ممتصًا ليشفي نفسه!",
[3748326543]="لو أستطيع فقط إيجاد \"السحر وطرق القوة\". آه ها هو، ماذا كان يفعل هنا؟",
[3749471173]="إخوتي جاعوا. أرواحكم ستشبع شهيتهم.",
[3750054160]="يبدو أنكم تحتاجون درسًا آخر، أيها البشر!",
[3750620054]="أوه، لا! انظروا، ذئب آخر، وهو كبير جدددًا!",
[3751014486]="ما تحتاجش تنظر للسماء لكي تشوف التنين هوك!",
[3751234550]="فرينزي هارت الأقوى!",
[3751645557]="أوووه، ياه! تأملوا عضلاتي المتموجة. استمتعوا ببريق جسدي.",
[3751888537]="في حشرة.",
[3752353513]="لا تتحمس كثيرًا أيها البطل، هذا كان الجزء السهل. التحدي أمامنا! هيا بنا.",
[3752929248]="لن أستسلم لأحد!",
[3753106157]="كتلاميذ للدم، تسعون لإتقان قوة الحياة ذاتها لأعدائكم.",
[3753114840]="...على نار مكشوفة.....",
[3753918685]="رأيت عالم الـهورد. كنت داخل مدنهم. داخل عقولهم...",
[3754056293]="أيها الغزاة، أنتم على شفا الهاوية! الـبيرنينغ ليجيون قادم، ومعه نهايتكم.",
[3754086965]="ألكسترازا امنحني العزيمة لدفع أعدائنا للخلف!",
[3754305719]="تركى أيها الهنتر!",
[3754623901]="أسكت وجهك أيها الثرثار الأحمق!",
[3755039112]="المقاتل سينتصر! انظروا إليه فقط!",
[3755122159]="%s يبكي على جثة ابنه.",
[3755277378]="نحن، الأليانس، سننتصر!",
[3756463750]="ربما أجد لك فائدة...",
[3756730519]="ثرال... ضباب الدم قد انقشع.",
[3756786979]="هل يمكن أن يكون هذا حقًا كويلديلار؟",
[3756879786]="%s يطلق كرة متجمدة نحو $N!",
[3757361319]="%s يطلق أفظع تجشؤ سمع أو شم على الإطلاق.",
[3758058630]="من فضلك، انهض يا صديقي. احتفظ بالبركة كرمز لقوة النور وكيف يمكن للأبطال الذين رحلوا منذ زمن أن ينهضوا مرة أخرى في كل منا للإلهام.",
[3758807928]="قوة! قوة مجيدة!",
[3759442672]="لقد شهدت صعود وسقوط الإمبراطوريات... ولادة وانقراض أنواع بأكملها... عبر آلاف السنين، ظل حمق البشر هو الثابت الوحيد. وجودك هنا يؤكد هذا.",
[3759608377]="توقفوا! لقد دمروا المصعد!",
[3759618307]="الجورمونغار انهار فورًا، ورأسه بالكاد لا يزال ملتصقًا بجسده المتشنج. التفت والدي إلى القزم بذهول ورفع قبضته في الثناء...",
[3760031306]="النهاية قد حلت بك.",
[3762022428]="لعنة!",
[3762027318]="كم تعتقد أن هذا القفص سيحتجزني، أيها الشياطين!",
[3762136047]="تعالوا، يا أتباعي. خذوا قضبان التوجيه وأنشئوا دائرة الاستدعاء الكبرى.",
[3762432259]="لقد نجحنا! شكرًا مرة أخرى! سأركض للأمام!",
[3762714116]="آه نعم. لقد سمعت كل شيء عن تلك الأشياء الجديدة المفلطحة. تمت إزالة الدرع من الغلاف لتقليل الوزن. بارغ! هراء!",
[3762795315]="أشعر بالتردد فيك، ولا أثق به سواء كنت معهم أم لا. إذا كنت ترغب في قراءتي للـكالوآك، فسيتعين عليك إثبات نفسك أولاً.",
[3762860418]="اهرب أيها الناعم الأصابع! غوريغيك سيمسك بك!",
[3762896566]="أوه أوه....",
[3762925063]="لا تفكر حتى في الهروب، أيها البائسون المكسورون! أعدكم بمصير أسوأ من الموت إذا لم تقتلوا هؤلاء المتطفلين!",
[3763061231]="إنه لشرف لي أن أخدم معك، $N.",
[3763442425]="هذا فظيع!",
[3763913551]="الأسلحة هي مجرد وسيلة راحة لمحارب بمهارتي!",
[3763975051]="قليلون من ذاقوا الألم الذي سأسلطه عليك الآن!",
[3764415736]="معركة كرات ثلج رائعة!",
[3764881495]="لقد أحسنت صنعًا يا كيلدونس. السيد ماليقوس سيكون مسرورًا جدًا بتقدمك.",
[3764962144]="والآن ماذا أفعل؟",
[3765079098]="مختبئ داخل هذه المدينة المدنسة هو الوغد المسؤول عن قتل إخوتنا وأخواتنا عند بوابة الغضب! يجب أن ينال قصاصه!",
[3765312427]="طارد الصغار! طارد الصغار! سريعون جدًا!",
[3765362180]="إلا إذا كان شيئًا يمكنني أكله، لا أريده.",
[3765861782]="<ابحث بتكتم في جيوب القرصان عن دفعة تاروك.>",
[3765870575]="وداعًا أيها البشر. شجاعتكم تستحق الإعجاب، لمخلوقات معيبة كهذه.",
[3765986506]="لا يمكنك المغادرة... يجب ألا يجدنا!",
[3766374415]="برج دن بالدار الشمالي يتعرض لهجوم! إذا تُرك دون رقابة، سيدمره الأليانس!",
[3767056230]="بقرة الشعاب المرجانية وثورها الجديد يجدان الحب الحقيقي.",
[3767616289]="%s يومئ بفهم.",
[3767799083]="نجاستك يجب أن تُطهر.",
[3767836659]="آه... تجاربي لا تنجح أبدًا كما يجب. ربما يجب أن أعود إلى مجرى النهر.",
[3768260002]="هناك يواصل حربه ضد إيليدان بمساعدة آل دور وسكريِرز. لكن الفصيلين لم يتخليا عن عداواتهما القديمة.",
[3768431592]="لور هامر...",
[3769205693]="لا تقف هناك فقط؛ اقتله!",
[3769375991]="هل هناك أي نزل آخر يمكننا زيارته للحصول على مكافآت؟",
[3770019904]="لقد وصلت إلى الرتبة 1: عريف",
[3770625741]="$N ربما عثر على بقايا نصل قوس قزح، كاليكوس. هل ستقدم مساعدتك لزائرنا؟",
[3770725848]="أخيرًا، قد ترتاح روحي... يا سيريليان العزيزة...",
[3771025253]="لا ترحم تلك الحيوانات، $N!",
[3771428405]="%s يبدو ضعيفًا!",
[3771599612]="والآن... القضيب. لنرَ كيف نعيد تركيبه، أليس كذلك؟",
[3771807026]="لدينا معلومات قليلة جدًا عن هذا المسار الزمني. تم إرسال ساعت وهو بداخله حاليًا. البيانات التي جمعناها من مراسلاته تشير إلى أن تنين اللانهاية يحاول مرة أخرى تغيير الزمن. هل يمكن أن يكون فتح البوابة المظلمة هدفًا للتخريب؟ دعونا نأمل ألا يكون الأمر كذلك...",
[3772209684]="بالكاد أسمعك... <تشويش> استيقظ!",
[3772404975]="هذا هو الثمن... للفشل...",
[3772724369]="$N، سأتعرف على ذلك الوجه في أي مكان... ماذا... ماذا فعلوا بك، $Gفتى:فتاة;؟",
[3773332981]="لكنهم سقطوا في فخ شر سارجيراس - والآن أصبحوا أعداءنا الأكثر عنادًا.",
[3773550706]="على ماذا تنظر يا أيها الجرذ القذر؟ ها ها... أمزح معك يا صاح!",
[3774520893]="أنا الوارتشيف الوحيد!",
[3774683759]="الجو بارد جدًا، مظلم جدًا... أنا لا أمثل، صحيح؟",
[3774951353]="فوضى! هلاك! دمار! هذا سيدّعيها كلها!",
[3774996553]="لو كنت واحدًا من بلود إلفز الدونبليد، لكنت أسبح بعيدًا عن الجزيرة الآن بعد أن جاء $N.",
[3775102544]="أوقف الـهورد من استعادة الجمر، $N. لا يمكننا المخاطرة بأن تكون لهم الأفضلية عندما تستأنف المعركة!",
[3775156743]="أولئك الذين يعارضونه سيدمرون بالكامل، وأولئك الذين يخدمون - يخدمون كليًا، دون سؤال، بتفانٍ كامل للعقل والروح - سيرتفعون إلى مراتب تفوق فهمك.",
[3775501365]="آه... أنا... ميت.",
[3776116498]="سأقطعك الآن!",
[3776223776]="لا! لماذا حُرمت من الموت بالنار؟ يجب أن تحترقوا جميعًا!",
[3776364784]="تورتة، حبيبي! لقد عدت أخيرًا.",
[3776791417]="%s يرمي الديناميت في الهواء ويهبط بالقرب منك.",
[3777356785]="أنت لا شيء.",
[3777530400]="نايت إلفز من دارناسوس يهتفون لـ$N.",
[3777598055]="هذه الأرض ملك لدوارف دارك آيرن. استعد لرؤية الآخرة، $C!",
[3777714603]="يكسر قطعة من لحائه، ويسلمها لك %s قبل أن يرحل.",
[3777718082]="الفأس ضعيف. جارفروست يصنع أفضل ويسحقك.",
[3778160336]="حتى أنت يجب أن تعترف بأن معلوماتك من المنشقين قديمة وغير موثوقة. دعنا نشن هجمات محسوبة على هذه المانافورج ونجمع ما نستطيع من معلومات.",
[3778437955]="المهمة التي أمامك لن تكون سهلة، لكن لديك بركتنا.",
[3778454792]="الكل على متن سفينة المدافع! جهزوا المدافع!",
[3778475243]="خطر. خطر! $N يحاول إيذاء إيه-مي.",
[3778648530]="بالطبع أنا من اختير لاستدعاء شيطان للمتسابقين. أنا ويلفريد فيزلبانغ، سيد الاستدعاء! الشياطين ترتعد لمجرد التفكير في أن تكون تحت إرادتي!",
[3778749382]="أوقفوا هذا فورًا!",
[3778998199]="حسنًا، شيء واحد مؤكد، $N لم يعد ناغت بعد الآن!",
[3779015146]="كن على حذر... أرناك لديه قوة غريبة على غريمتوتيم... لن يسعدوا برؤيتي أهرب.",
[3779060981]="أونغ... أعتقد... أنني تبرزت...",
[3779194449]="آلاف من الـسكورج ينهضون بأمر الهاي لورد.",
[3779208546]="لم أعتقد أبدًا أنني سأركب إلى المعركة ومعي $R على ظهري.",
[3779728714]="الـدرايناي في إكسودار يهتفون لـ$N.",
[3779830490]="رمرمفم ممف هرمرم!",
[3780166315]="أين؟ أين الشظايا؟ لا يمكنك إخفاؤها عنا!",
[3780357440]="%s يصرخ من الألم.",
[3780441402]="ثم التقينا!",
[3780768938]="أخبرني كيف نشأ الدوارف، وابدأ من البداية!",
[3781142534]="سيأتي وقت ضرب رأس الوحش قريبًا! ركز غضبك وكراهيتك على أتباعه!",
[3781149319]="قريبًا سيعيدني السيد!",
[3781221340]="ستدفع الثمن لإجباري على فعل هذا!",
[3781231561]="الـ%s، بعد أن خاض المعركة بشجاعة، يتفتت إلى أشلاء.",
[3781266908]="بالقياس بـكراكلنهايت، تبلغ الحرارة 428,000 درجة! هذا كراكلني!",
[3781312611]="لن يكون هناك هروب!",
[3781516370]="سوف أفرغ أحشاك على الأرض، مون!",
[3781957566]="يمكن لـلوريد يعتاد... على العمل معك.",
[3782321906]="لقد اتخذت... قرارًا... غير حكيم.",
[3782771786]="كسادة للدم، نحن نعرف حربًا بلا نهاية...",
[3783191031]="أعتقد أنكم الأطفال هم مستقبلنا...",
[3783798176]="أسرع! أرجووووك أسرع!!",
[3784051061]="أتعلم، رائحته جميلة... مهلاً! توقف عن رش هذا الشيء علي!",
[3784599171]="توقف! أشعر بوجود شرير... أنديد!",
[3785456030]="%s تحتضن والدها.",
[3785920404]="النجدة! الـ بيست فوقي!",
[3785981405]="أيها المخلوقات القذرة، عليكم العمل أسرع!",
[3786189439]="الغزاة مستمرون! أوقفوهم!",
[3786805396]="أنقذوني...",
[3787124468]="هناك حاجة لتعزيزات في ساحة معركة وينترقراسب! لقد فتحت بوابة للسفر السريع إلى المعركة في ذا سيلفر إنكليف.",
[3787229151]="اقبل شكري، $N. مذكرات ياجين ستكون لك.",
[3788012731]="أخيرًا، يمكنني أن أرتاح...",
[3788055299]="شكرًا! شكرًا لك، $Gبريست:برايستس;. الآن أستطيع مواجهة هؤلاء الونديغو والنور في جانبي!",
[3788267561]="حرر أي ألاينس سليفز تصادفه. سنحتاج بالتأكيد لمساعدتهم في محاربة تيرانوس. سأجمع التعزيزات وأنضم إليك على الجانب الآخر من المحجر.",
[3788737288]="أنفينا أنا أحبك! ركز على صوتي! عد من أجلي الآن! أنت فقط من يستطيع تطهير صولجان الشمس!",
[3789174408]="مات المشرف! بسرعة، يا دريغودز! اهربوا!",
[3789481011]="حظ... موفق. سوف تحتاجه.",
[3789531387]="أتمنى أن تموتوا... بألم!",
[3790206889]="أغبياء! قضيتنا عادلة!",
[3790430605]="كم يجب أن تكون يائسًا لتستعين بماشيتك كحلفاء؟",
[3790756525]="جئت لأكمل مهمتي.",
[3791388601]="احذر السفينة! هاربي!...لحظة، هذا طائر آخر.",
[3791465587]="أيها النور الذي نعتنقه، نضرع إليك...",
[3791844396]="لن يُترك أي نوم خلفنا.",
[3791894954]="اعذروني ريثما أبدأ تجاربي...",
[3792034237]="نحن نقوى، بينما أعداؤنا موضعون بأعداء، ويضعفون بهجمات متواصلة.",
[3792075750]="من يصطاد من؟",
[3792304973]="حان الوقت لإنهاء هذا كله!",
[3792393908]="همم...",
[3792529775]="مقرف!",
[3792862216]="للأكل!!",
[3792901341]="السيد لديه أعمال في الغرف بالأعلى.",
[3792988675]="بوابات تفتح إلى عقل %s!",
[3793401691]="%s يرفع فأسه الضخم فوق غارك.",
[3793778625]="فكر، $N. فكر بالماضي. حاول أن تتذكر تلال ووديان إلوين، حيث وُلدت. تذكر روعة الحياة، $Gأخي:أختي;. لقد كنت بطلاً للأليانس يومًا! هذا ليس أنت.",
[3794077966]="هنا، بيسي، استمتع بهذه التفاحة بينما أجهزك.",
[3794219566]="بورتال غارديان يدافع عن البوابة الجديدة!",
[3794222796]="منفذ، هجومك المباشر سيكلفنا أرواحًا أكثر مما أرغب. هناك حاجة لاستراتيجية أكثر دقة؛ تتضمن استعادة الأراضي المحيطة، بدءًا من القرى لقطع جميع نقاط التعزيز عن ديثولم.",
[3795002634]="أجدك غير كافٍ.",
[3795045888]="لقد انتظرنا إلى الأبد لهذا اليوم!",
[3795333758]="دودة جبانة!",
[3795337223]="يبدو أنني لست صدئًا بعد كل شيء.",
[3795341307]="واسمح لي أن أضيف، هذا الفستان جميل! يجب أن تخبريني من أين حصلتِ عليه.",
[3795584635]="الترول يغضبني!",
[3795758336]="يجب أن أبقيك قريبًا.",
[3795774487]="بالتأكيد لم تظن أنك ستنتصر.",
[3796521124]="%s يبدأ بتوجيه الطاقة نحو ديمينسيوس.",
[3796528072]="عد إلى هالفورد بالمعلومات التي تفضل العمدة الطيب بتقديمها، $N. سأنهي ما تبقى هنا وأعصر ما تبقى من معرفة هذا الحقير عن ثيلزان. الآن، سأري غودفري \"الخيار الثالث\" النادر.",
[3796881954]="أرسل أشتونغ الخاص بك إلى تيمبست كيب واقتل أغلى ممتلكاته، العنقاء المعروفة باسم الار. يجب أن أعرف أنك لست في صفه. لا تفكر في خيانتي، أيها المكسور. كلانا يعرف من يملك روحك!",
[3797010834]="$Gسيد:سيدتي; $N، يا لها من مفاجأة سارة، $Gسيدي:سيدتي;.",
[3798691237]="5...",
[3798853752]="من... من أنا؟",
[3799906295]="سنكون أفضل أصدقاء. أراهن أنني وأندوين سنكون أيضًا أفضل أصدقاء. الأصدقاء مهمون.",
[3800040607]="آه، ها أنت. كنت آمل أن أنجز هذا ببعض التكتم، لكن أعتقد أن المواجهة المباشرة كانت حتمية. مستقبلك، ثرال، يجب ألا يتحقق، لذا... أنت وأصدقاؤك المزعجون يجب أن تموتوا!",
[3800575663]="ابتهج بالألم!",
[3800588303]="يمكنك أخذ ذلك، لم أعد بحاجة إليه!",
[3800751060]="دعني أؤكد لكم أيها الناس، إذا نجح، سيعاني هذا العالم أكثر مما عانى أوتلاند! لذا، دعونا نتأكد من أن ذلك لن يحدث.",
[3800753878]="لقد تم إسقاط اشعاري كريستال! أعد الزقورة قبل أن يصبح المسلخ عرضة للخطر!",
[3800934881]="هنا، الصليبيون المتعصبون يقفون في طريق هدفنا. سيسقطون!",
[3801610551]="ربما القليل من الشحم سيفي بالغرض.",
[3802021477]="إنها تثخن! بسرعة، أحضروا بعض...",
[3802096280]="فينسنت! أنت وحثالة أمثالك لن تنجحوا في إبعاد أبنائي وأنا أكثر من تلك البقايا البائسة من كيرين تور.",
[3802224712]="وماذا تظن أنك تفعل؟ تجرؤ على التدخل في تجربة سيدي؟",
[3802241917]="والآن نفترق.",
[3802252750]="هل هذا صحيح؟ هل حقاً هناك تمساحيات في القنوات؟",
[3802548104]="اهربوا في رعب.",
[3802588544]="آه، الترفيه وصل!",
[3802989971]="جرب أفضل ما لديك، ثم جرب الباقي! أوغر برو!!",
[3803313883]="الدم الأسود لـيوق سارون يجري في عروقي! أنا. لا. يُوقَف!",
[3803747475]="دفاعاتنا جاهزة!",
[3804016212]="سكارفالد، أيها البزاق العاجز! ارجع واجعل نفسك مفيدًا!",
[3804321282]="لا... لا... هذا ليس هو، أليس كذلك؟ ذلك الأحمق القاسي أرسلك على الأرجح وراء الأدوات، أليس كذلك؟",
[3804365675]="تعالوا أيها المتطفلون...",
[3805476200]="نظيف ومرتب!",
[3805528260]="هذا حار.",
[3805764170]="كيف أشعر؟ مبتل جدًا، شكرًا.",
[3805866443]="بانسي.",
[3805973589]="مقبرة فروست وولف تتعرض للهجوم! إذا تُركت دون مراقبة، سيستولي عليها الـهورد!",
[3805986658]="لم يكن يجب أن يكون الأمر هكذا...",
[3806371176]="عرض مخزي. الموت أفضل لك.",
[3806629993]="لا يمكنك إصلاح شيء معقد مثل دبابة بدون المعدات المناسبة، يا صاح!",
[3806949636]="شكرًا لك، $C. أنا مدين لك.",
[3807292970]="اسمعوا! اسمعوا! *لهث لهث* انذروا سكان ساوثشور: قتلة متوجهون إلى بلدتنا الجميلة!",
[3807920263]="دخول مرفوض. مستوى الصلاحية غير كافٍ.",
[3808209573]="لا، لا، لا! ارجع هنا!",
[3808216627]="حراس السجن، نحن نغادر! هؤلاء المغامرون يتولون المسؤولية! يلا يلا!",
[3808249788]="أضف برتقالة أخرى! بسرعة!",
[3808395179]="أنا جاهز. دعنا ندافع عن المعبد!",
[3808694914]="ساوثشور كراير يموت.",
[3808741068]="أنا جاهز عندما تكون مستعدًا، $N. قُد الطريق!",
[3809435162]="احذر، $N! انظر إلى الغرب!",
[3810123803]="أجل، فاندرال، تذكر هذه الكلمات: لا تدع حزنك يوجه إيمانك. هذه الأفكار التي تحملها... أماكن مظلمة تذهب إليها، يا نايت إلف. لا يمكن الحصول على الغفران من خلال انتقام مضلل.",
[3810534912]="أنا مليء بالمفاجآت!",
[3810565210]="دعني أخرج من هنا! يا رفاق... يا رفاق؟",
[3810940621]="لقد وعدتني بأخذي لقضاء ليلة في المدينة! هل سنقف هنا مرة أخرى الليلة؟",
[3811155428]="طاقة. قوة. شعبي مدمن عليها... اعتماد تجلى بعد تدمير الشمسية. مرحبًا بك في المستقبل. من المؤسف أنك متأخر جدًا لمنعه. لا يمكن لأحد أن يوقفني الآن! سيليما أشالانوري!",
[3812037465]="ربما أستطيع أن أعرض عليك شيئًا يثير اهتمامك؟ تعال، انظر إن كان هناك ما يعجبك.",
[3812243999]="أنارا'لاه بيلوري $N!",
[3812607877]="...جرعة قوية!",
[3812838883]="ما الذي تخاف منه؟",
[3813785268]="اسمع، إذا لم تخبرني عن الحريق--",
[3814491970]="من الذي عكر مذبح الإلهة؟",
[3815083834]="أنت فقط تؤجل المحتوم! القلعة المرعبة ترتفع في الشرق بينما جيوش الموتى تزحف من قلب آيس كراون!",
[3815427284]="أستطيع رؤية الضوء في نهاية النفق!",
[3816421680]="لماذا توقظ الشبح؟ أين بقية ستونمولز؟!",
[3816629895]="يجب أن توقف هذا الجنون قبل فوات الأوان!",
[3816744082]="سأكون خلف شاشة الاعتراف إذا أراد أحد التحدث معي. أي شكوك، أي مخاوف، أي تردد سأهدئها بكل سرور.",
[3816841137]="من أجل يميرون!",
[3816898092]="%s يمد يده ليلمس بلورة النور.",
[3817129482]="لقد استنتجت الطريق الذي يجب أن تسلكه. هل أنت مستعد؟",
[3817200531]="بنى النيروبيون إمبراطورية تحت الجليد المتجمد في نورثرند. إمبراطورية بنيتم عليها هياكم بحماقة. إمبراطوريتي.",
[3817739523]="قريبًا ستنتمي إلى الـسكورج.",
[3817911482]="سنأخذ من الأرض إذا رفضت العطاء!",
[3818214350]="انتبه من الأسفل!",
[3818367699]="تاورن تشيفتنز! يعزفون مباشر، في حانة نهاية العالم! كونوا هناك، في رأس الساعة! مطرود من شاتراث؟ تسللوا مجددًا!",
[3818375283]="هذا سيجلب لتيلار المساعدة التي تحتاجها!",
[3818659658]="أسمعك! لا أستطيع الحصول على لحظة سلام بدون سارة تشتكي من الأعمال المنزلية!",
[3819640728]="هذا صحيح. رجالي يبلغون أن الطرق من هنا إلى الشاطئ تحت سيطرة الأنديد. ستحتاج لإيجاد طريق بديل للعودة إلى سفنك.",
[3819947070]="لن تؤذي $Gولد:بنت; يا مورغور! بسرعة، $N، تسلق على ظهري!",
[3820014261]="تدمير الخدم القدامى سيؤدي إلى فقدان التحسينات على المراقب فريا. ومع ذلك، الضرر الدائم لشخص وممتلكات فريا، بلا يوجد ذلك ختم المراقب الخاص بها، محتمل جدًا.",
[3820258814]="التحدي... عيب في الفناء.",
[3820771323]="نفس المصير ينتظر كل من يسرق من السيد.",
[3821094037]="تقدموا، أيها الحالمون - واطلبوا انتقامكم!",
[3821276991]="الذين يتغذون على الأرواح الضائعة لا يعرفون إلا الجوع.",
[3821497022]="ثاين إيلسكار، لقد تم تحديك لقتال شريف وفشلت.",
[3821968198]="قل لي كيف، يوثير؟ كيف أدمر أميري؟ أميري...",
[3822101667]="يمكنك إعادة التفكير في أفعالك، أيها الأحمق.",
[3822520650]="جاك وجيل على مؤخرتي المتجعدة! أنا من يحمل الماء هنا.",
[3822801608]="كنت جنديًا في النور يومًا... انظر ماذا أصبحت...",
[3823014171]="أعدادهم لا تصدق... أنا سعيد لسماع أن الملك ستورمهارت جاء لمساعدتك. لا أسمع عنه إلا الخير - أعتقد أن الوقت قد حان للقائنا.",
[3823053539]="قد يكون لدي تسعة وتسعون مشكلة، لكن الرقص ليس واحدًا منها! هالوين سعيد، $N!",
[3823152285]="ليس بعد الآن! هاك سيفك. توجه إلى الثكنات للخدمة!",
[3823570574]="حسنًا، كما تشاء. عندما نرفض الآخرين، ستكون مسؤولًا عن معاناتهم. فكر في ذلك.",
[3824138577]="اتبعني، أيها البالادن الطيب. سأجهز درعك أسرع مما أشرب بيرة دوارف. ممم... بيرة.",
[3824505433]="يجب أن تنسحب ما دمت تستطيع.",
[3826142789]="يجب أن تموت! لكن انتظر: هذا لا-- لا، لا... يجب أن تموت!",
[3826286406]="يعتقد البلود إلفز أنهم على بعد خطوة واحدة من حكم العالم...",
[3826473613]="شعرت بذلك، مالفوريون. أيام مظلمة تنتظرنا.",
[3826482787]="برايفت ثورسون عائد من الدورية. لا جديد للإبلاغ - الجو هادئ جدًا هناك...",
[3826645903]="اسمك لا أهمية له بالنسبة لي مثل أسماء الآلاف الذين ماتوا تحت سطوة غوك. سأسحقك أنت و$N!",
[3826917786]="واو! هل كل هذا التصفيق لي؟ شكرًا لحضوركم!",
[3827300588]="كان الـتايتنز قد غادروا هذا العالم منذ زمن بعيد. فقط الـنايت إلفز الذين سكنوا هذه المنطقة كانوا هنا للدفاع. أوه! المقطع التالي رائع!",
[3827600506]="ستمضي الساعات بشكل أحلى بكثير.",
[3827696016]="حراس، التجمع! اقطعوا هؤلاء الغزاة!",
[3828066368]="كيبلر قيد التحقيق من قبل جي.إي.تي.إيه.",
[3828460725]="أنا المنتصر!",
[3828933284]="أنا متعب جدًا. ما كان يجب أن نسهر لهذه الدرجة الليلة الماضية... حسنًا، هذا الصباح. لكنها كانت ممتعة! أنت تقيم أفضل الحفلات يا سيدي.",
[3828991524]="لكن...!",
[3829622165]="أرواح العناصر قلقة...",
[3829778823]="هذه الأوامر يجب أن تصل إلى هاي جنرال ابيندس!",
[3829968436]="وجودك يخل بتوازن الأرض. يجب إزالتك!",
[3830183754]="آه! لن أخبرك بشيء، أيها $R القذر!",
[3830413362]="نعود إلى لوحة الرسم.",
[3830816802]="أجل، كان ذلك مُرضيًا للغاية.",
[3830889163]="لا تكن خجولًا يا إلفي. ألا تشعر بهذا الحب المشتعل بيننا؟",
[3831502546]="من هو؟ يبدو مألوفًا جدًا.",
[3831839931]="ثرال، لم أقابل هؤلاء الأشخاص من قبل في حياتي.",
[3832699476]="هي... ربما سنجد بعض الحشرات غير المفيدة.",
[3832783692]="يمكننا التعامل مع الأمر من هنا. أيها الراف رايدرز، أنتم منصرفون.",
[3833390557]="عشائر أوقر لن تُخضع. ليس من قبل الـغرون، ولا من قبل $R الحقير مثلك!",
[3833443787]="ماذا تفعل، ساندرز؟",
[3833473919]="الـ آيرون وتشير يفقد توازنه تحت الضربة القوية.",
[3833919614]="كيف يفعلها؟",
[3834149645]="في الزاوية لدينا... $N، حقًا $C من الطراز العالمي. قاتل الزواحف والثدييات والآليات الميكانيكية وحتى أقارب... التنين. لم ترَ $R مثل $Gإياه:إياها; من قبل.",
[3834788691]="لا مزيد من السيد وولفار اللطيف!",
[3834797378]="أنت صديق رائع، توينكل. لن تتركني أبدًا، أليس كذلك؟",
[3834840291]="نحن متأخرون عن الجدول! أدر هذا الحوض شرقًا! شَرْقًا!",
[3835380870]="عظامك ستتحطم تحت حذائي، $N",
[3835668704]="في هجومهم الأولي، لمحت قائدهم الحقيقي، تنين شفق بالغ ومخيف.",
[3836341626]="أتمنى أن يساعد هذا. هذه الوحوش الخبيثة يجب إيقافها!",
[3836696863]="حان وقت نصيحة داجيك الذكية! أشياء ميتة كثيرة تعني فرصة كبيرة لتصبح شيئًا ميتًا. داجيك يغادر الآن.",
[3836829113]="مخبأ آيسوينغ دُمّر على يد الـهورد!",
[3836852021]="أووه، قوي جدًا! هالوين سعيد، $N!",
[3837045912]="%s بالكاد يحافظ على شكله!",
[3837072072]="وداعًا، سيريليان، حتى نلتقي مجددًا...",
[3837102533]="النور يغمر الكنيسة؟ نور الفجر يُكشف.",
[3837124178]="ماذا يحدث؟",
[3837445120]="عانوا، أيها البشر، بينما يخونكم سحركم الحقير!",
[3837940443]="بلورات كيراجي الرنانة الضخمة تخترق القشرة الأرضية لكاليمدور. مخلوقات هائلة من حجر السبج تخترق الأرض المتشققة حديثًا.",
[3838040011]="توقف عن التذمر. لا زال حظك معك.",
[3838725499]="لاااا!!",
[3838913307]="نجاح!",
[3839595397]="بشر حقيرون ومتوقعون... أنتم لا تعلمون ماذا فعلتم! إرادة السيد تحققت. الـمونقليد سيدمر ومالفوريون معه!",
[3839661650]="واو! انظر إلى تلك الإصابة المباشرة!",
[3840074362]="تركى مذبحة!",
[3840093944]="لماذا تصرون؟ بالتأكيد ترون عبثية كل هذا. لم يفت الأوان بعد! لا يزال بإمكانكم المغادرة بأرواحكم...",
[3840401507]="انتظر، $N!!! يبدو أننا سنحتاج بعض المساعدة هنا...",
[3840450572]="سنشق طريقًا عبر هذا المكان البائس ونجد طريقة لدخول هولز أوف ريفلكشن. أشعر بسحر قوي مخبأ داخل تلك القاعات. سحر قد يكون المفتاح لتدمير الـسكورج!",
[3840644604]="أنا هو السحر-ويفر! قوتي لا نهائية!",
[3840724648]="شكرًا لك مرة أخرى، تيرينثيس. سأعود مرة أخرى إذا احتجت المزيد من المساعدة. حتى ذلك الحين، أرجو إرسال المزيد من المغامرين إلى أشنفال",
[3840809492]="كل هؤلاء الناس يشغلونني. خذ هذا الحصان إلى إسطبلاتك.",
[3841161305]="فكر، $N. فكر بالوراء. حاول أن تتذكر القاعات المهيبة لـسيلفرمون سيتي، حيث ولدت. تذكر روعة الحياة، $Gأخي:أختي;. كنت بطلًا من الـسيندوري يومًا! هذا ليس أنت.",
[3841206490]="ذكرني مرة أخرى لماذا لا أغادر فقط؟",
[3841326665]="هل حاربت تنينًا كبيرًا أو إلهًا أو أي شيء من قبل؟ زيبيك يحب سماع القصص.",
[3842022827]="%s يخفض رأسه ويتنهد، واضحًا أنه منهك.",
[3842210714]="برج الرمح جاهز للاستخدام!",
[3842453461]="يبدو أن %s ممتن جدًا لتحرره من تأثير روح الكوي-كوي.",
[3843617341]="حَطِّمْ!",
[3843640778]="كيف تجرؤ على التدخل في عملنا!",
[3843706939]="أعتقد أن هناك شيئًا مدفونًا هنا، تحت الرمال!",
[3843894308]="الأنديد يهاجموننا!",
[3844066401]="أووه. شيء ما لا يتوافق مع المعدة اليوم...",
[3845192767]="هذه... خسارة... لا تعوض.",
[3845345727]="ميشا تطلق زئيرًا عاليًا وهي تحك مخالبها على مذبح الغرون.",
[3845644455]="هل أقاطع؟",
[3846354930]="%s يضع الصدفة في حقيبته.",
[3846650641]="تم تدمير ملجأ ستونهيرث على يد الـهورد!",
[3848542127]="فقط استرخِ!",
[3848552971]="آه نعم، وتم التوصيل فورًا. كالعادة، من دواعي سروري التعامل معك، كوربيت.",
[3848564933]="النجدة! لدي يد واحدة فقط لأدافع بها عن نفسي.",
[3848630052]="اخرج من هنا، عددهم كبير جدًا! اهرب بينلا تستطيع!",
[3848990088]="يمكنني تقبيلك!",
[3849251084]="لكن هذا سيخل بتوازن التركيز السحري، ويسبب اهتزازًا عكسيًا في الأثير.",
[3849373449]="آمن أخيرًا! شكرًا لك أيها الغريب!",
[3849393604]="تراجعوا وتمسكوا بالخط! لا يمكننا الفشل وإلا ضاع كل شيء!",
[3849738960]="أوه، لا أستطيع الاستمرار...",
[3850501611]="لا تمنحوا هؤلاء الأوغاد لحظة راحة! إذا كان هناك كريستال أتامال هنا فسنجده!",
[3850572054]="البرج الغربي تعرض للضرر!",
[3850784343]="السمكة رائعة يا جيسيكا.",
[3850956602]="قتلة! حراس! حراس!",
[3851098010]="لقد أخبرني أنك ستأتي من أجلي. لكنني لن أموت على يدك. لقد رأيت ما فعلته برفاقي.",
[3851505570]="بسرعة! أنتم تتكاسلون بسرعة كبيرة!",
[3851728539]="حراس! النجدة!",
[3851749944]="خلاصي؟ أنت جريء أيها الصغير. خلاصي يأتي بإرادة إلهي.",
[3852128310]="كم... هذا مؤسف.",
[3852933231]="تم تنفيذ الحكم!",
[3854252493]="أسمع ما تسمعه يا أخي. انظر خلفك...",
[3854306230]="جيد... جيد، أ-مي. أ-مي جيدة. المنزل. ابحث عن المنزل.",
[3854783544]="في هذا العالم حيث الوقت عدوك، هو أعظم حليفي. هذه اللعبة الكبيرة للحياة التي تظن أنك تلعبها، في الحقيقة هي تلعبك. على ذلك أقول...",
[3855036252]="ألا تكره عندما يهزمك نوم؟!",
[3856086407]="ها! الآن موتك مضمون!",
[3856288252]="هم، هذه عظام جيدة حصلت عليها هذه المرة، بوزيك.",
[3856803688]="%s يئن.",
[3857614215]="أعرض نفسي بدلاً منه. ستحصل على ايشاناه، الـبريستس الأعلى من آلدور، كأسير لديك إذا أطلقت كايلان من قبضتك المظلمة.",
[3857631409]="الـهورد ينتصر!",
[3857698773]="أوه! الآن كيكيك يفهم. لا يريد أن يسحق من قبل سيدة التنين الكبيرة. ربما يعود مرة أخرى عندما لا يكون مزدحماً. سررت بلقائك، سيدة التنين.",
[3857709439]="الجنون أوصلك إليّ. سأكون نهايتك!",
[3857926365]="أنت الآن تقف على أرض الـسكورج المقدسة. النور لن يحميك هنا، أيها البالادن. لا شيء سيحميك...",
[3858050051]="الـليجيون... لن يسقط... أبدًا.",
[3858435588]="قوتك تقوينا جميعًا.",
[3858810141]="إنها... إنها جميلة!",
[3858881066]="أوه لا! ما هذا؟ بسرعة، دافع عنا بـسكراب ريفر إكس6000!!!",
[3858962719]="كل شيء سينتهي قريبًا!",
[3859036472]="كل هذا من أجل ماذا؟ حلي؟ لقد جئت متأخرًا جدًا. الاستعدادات بدأت بالفعل. قريبًا سيعود السيد.",
[3859314077]="حسنًا، يا وارتشيف. الحي الملكي من هنا. كن على حذرك. لا أحد يعرف ما يخبئه لنا فاريماتراس وبوتريس.",
[3860057181]="هؤلاء الغرباء ضعفاء وسهل سحقهم.",
[3860221751]="إنه قادم! اختبئوا!",
[3860831107]="أستسلم! أنا خاضع. عمل ممتاز. هل يمكنني الهرب الآن؟",
[3860880274]="انهض أيها القطعة الفاسدة من القمامة! انهض قبل أن أهلكك!",
[3861081294]="%s يأخذ نفسًا عميقًا!",
[3861137058]="الوظيفة: قوات الصدمة، المنفذون",
[3861419509]="تمسكوا بالخط! لا يجب أن يعبروا!",
[3862003456]="أؤكد لك هذا كثيرًا، كويمبي، لن تحصل على صوتي في الفترة القادمة!",
[3862345837]="من تثق!",
[3862483950]="اشعروا بالفودو العظيم الشرير!",
[3862704156]="%s يتذمر.",
[3863131000]="قد يؤلمك هذا قليلاً...",
[3863975791]="الإيريدار وارلوكس الماكرون الأقوياء كانوا يومًا أقرباءنا النبلاء.",
[3864063217]="هل أشم رائحة قرفة؟ أم أنها جوزة الطيب؟ مهما يكن، شيء واحد مؤكد - لا أحد يطبخ حمارًا مثلك يا كوكي.",
[3864152845]="تعال يا $N. دعنا نرى ثمار جهودنا.",
[3865144349]="من الشرير؟ من الشرير؟ صحيح: نحن الشريرون!",
[3865446116]="أعدك ألا أضع لك ثآليل...",
[3865690087]="قريبًا سيناديك صوت السيد.",
[3866449513]="حسنًا، ابق قريبًا. هؤلاء الشياطين سينقضون عليك من الظلال إذا خففت حذرك.",
[3866484398]="الوظيفة: أونر غارد",
[3866558287]="أخ... مقرف!",
[3867081142]="انظر! لا بد أن هذا هو كيكيك كمحارب عظيم! أرأيت؟ ماذا أخبرتك كيكيك؟",
[3869011125]="لا لا.",
[3869108876]="أخيرًا سأنتقم!",
[3869374290]="هذه المدمرات الضخمة تعمل كقادة عسكريين للـليجيون.",
[3870480771]="أراهن أن صديقي قروك سيعجب بهذه الصخرة للرمح الذي يصنعه! إنها حادة جدًا... أتمنى أن تعجبه.",
[3870782737]="متى يمكننا إعادة فتح متاجرنا؟ أنا أخسر ذهبًا هنا!",
[3871186235]="جسد %s يتحطم في غضب لا يشبه البشر!",
[3871969477]="بموز بران الهش! ما هذا؟! إنه... يبدو وكأنه طبل.",
[3871997313]="لم أتعرق حتى في هذه المرة!",
[3872331684]="لا! لا يمكنك! أتوسل إليك! إنه طفلنا!",
[3872398042]="أين أنا في بونزو براس باتونز؟ ومين أنتِ... ياآآخ، هذه أم الصداع!",
[3872764746]="أنا جوعان!",
[3872812272]="كلنا بننتهي نخدم الـليتش كينغ، يا صغير. هذه أحسن من أن نكون جثث متعفنة.",
[3872842770]="هذا... ليس النهاية بالنسبة لي!",
[3872939675]="هل ظننت أن خيانتك ستُنسى؟ ضائعة في التغطية المدبرة لموتي؟ دم من دمي، النصل شعر بقسوتك بعدما توقف قلبي عن الخفقان بزمن. وفي الموت، عرفت ما فعلت. لكن الآن، قيود كيلثوزاد لم تعد تمسكني. جئت لأخدم العدالة. أنا آشبرينغر.",
[3873038086]="كلاب مدللة، كلكم!",
[3873082335]="فكر، $N. فكر بالماضي. حاول أن تتذكر سهول مولقور المتموجة، حيث وُلدت. تذكر روعة الحياة، $Gأخي:أختي;. كنت بطلاً للتاورن يومًا! هذا ليس أنت.",
[3873272842]="قتال جيد...",
[3873456696]="هل هذا كل شيء، أيها الشيطان؟ أليس لديك شيء آخر ترميه علينا؟",
[3873513276]="لا! الصدع...",
[3873823878]="آه، ها نحن ذا. الآن، يجب على كيفر أن يجرب هذه القارورة ليرى إن كانت تعمل.",
[3874684571]="%s يتراجع ألمًا بينما يغسله حكم الحكمة!",
[3875304401]="كراهية...",
[3875728006]="نادل، جعة أخرى!",
[3875757841]="الصغار لا يجب أن يجوعوا...",
[3875917881]="لوروسا، أنا أوكل آثار أفايانا إلى $N، الذي سيأخذها إلى مورثيس ويسبروينق. يجب أن أعود بالكامل إلى الحلم الزمردي الآن. لا تدعي $N يفشل!",
[3876164378]="دافع عن نفسك أيها الصغير! سنرى إن كان فيك بلود نايت بعد.",
[3877085516]="إنهم قادمون إلينا! كن سريعًا بتلك الصواريخ!",
[3877308689]="$N قبل تحدي خيتريكس الـ دارك ماستر. لترحم الآلهة $Gإياه:إياها;، لأن خيتريكس بالتأكيد لن يرحم.",
[3877354283]="اعذريني من فضلك يا أمي الكبرى. سأعود قريبًا.",
[3877467226]="عائد من رحلة طويلة؟ استرح واسترخِ في حانة الخنزير والصفارة!",
[3878059514]="لا أستطيع تحمل الألم. يجب أن أجد مصدرًا جديدًا.",
[3878422105]="السلام عليك أكاماً!",
[3878688149]="معروفة في كل الأراضي، بضائع انتونيو بيريللي معروضة للبيع الآن بالقرب من تلة سينتينل! يجب أن أرحل قريبًا، فأسرع.",
[3878813253]="نحن على أهبة الاستعداد للدفاع عن العين!",
