[3886043699]="سيتعلم... لا ملك يحكم للأبد؛ فقط الموت أبدي!",
[3886071678]="فالستان، حريصًا على إرضاء والده، أقنع فاندرال بالسماح له بأخذ كتيبة صغيرة للدفاع عن ساوث ويند. بالتأكيد مع تحول مجرى المعركة لصالحهم، لا يمكن أن يصاب طفله الحبيب بأذى. الفخ لم يُلاحظ. تم أسر فالستان من قبل الكويراجي المختبئين وتم تدمير قرية ساوث ويند. راجاكس نفسه أخذ الأسير فالستان إلى خطوط المواجهة في المعركة حيث - أمام ستاغهيلم وقوات النايت إلف - أعدم الشاب النايت إلف بوحشية.",
