[3938771781]="سأجبرك على النزول! الريح تمنحني الطيران!",
[3939243595]="يقول التاورن: \"هذه حزمة من الهراء.\"",
[3939453374]="أنت ميت، يا بحري!",
[3939575330]="دريادلورد",
[3939578918]="لن تدعني أنام، أليس كذلك؟",
[3939644096]="سقطوا مثل كيس من جماجم الأوركس!",
[3939751617]="%s يحدق بصمت في شاهد القبر أمامه.",
[3940087813]="قلتها!",
[3940304784]="جيثان!",
[3940760738]="حان وقت الضرب. اقضِ على إيكاريوس.",
[3940830837]="أضحي بهذا الهيومين باسم سيدنا المظلم!",
[3940882224]="كيف تجرؤ على دخول محرابي!",
[3940941394]="العناصر نفسها ستثور على العالم المتحضر! فقط المؤمنون سينجون!",
[3941009406]="أنا مستعد للعب!",
[3941447942]="من الجيد رؤيتك تدافع عن ثيرامور بفخر، يا صديقي.",
[3942201490]="%s يثير عاصفة تجتاح الأرض، وصوت غضبه الأعمى يأتي من الشمال الغربي.",
[3942265641]="كارنيك، يا صديقي، أتمنى أن أراك بعينيَّ مجددًا، لكن يجب أن نتحدث عن راقناروس. نفوذه ينتشر.",
[3942333985]="بالمناسبة...",
[3942499046]="ف-لاك شير!",
[3942661424]="مُوغْرَيْن سقط! ستدفع ثمن هذه الخيانة! انهض، يا بطلي! انهض!",
[3942744678]="لقد نجحنا! كواي، لقد نجحنا!",
[3943123863]="الكل. يجب. أن. يموت.",
[3943182307]="ستواجه عالمًا من الألم!",
[3943206588]="%s موضع بحاجز مضاد للسحر.",
[3943357959]="شكرًا لإنقاذي. أنا أكره أن أكون ضفدعًا مقرفًا!",
[3943571813]="%s يظهر لحماية حجر الأعماق!",
[3943634203]="من كان يظن أننا سنواجه هذه المشكلة مجددًا؟ أوه، انتظروا، الجميع توقعوا ذلك!",
[3943975548]="كم كان من السهل التلاعب بك لاستعادة حجر سونتارا الأخير من أولئك الأغبياء من مطرقة الشفق.",
[3944210131]="أنت تستحق عناقًا قويًا من رجل.",
[3944444513]="نيسينغواري سوف يفلس إذا استمر بهذا الشكل! لين غالبًا لا يعرف ماذا يفعل!",
[3944507129]="هل حررت درول بعد؟ لا أعرف أين هو محتجز.",
[3944694369]="كل خططي أوصلت لهاللحظة!",
[3945180398]="هالجسر كان لازم يتدمر من زمان. كم بياخذ هالكسالى لكي يوصلوا من الهايلاندز؟",
[3945267577]="ماليغوس أكد لي شخصيًا أن قائدكم سيجعل تفاصيل هذا الاتفاق أولويته القصوى. والآن دعني أمر!",
[3945375199]="الآن وقتك يا ماييف! أطلقي غضبك!",
[3945472279]="بريزماتيك موجو!",
[3945577192]="لا شيء. هل تريد مساعدتي في طبخ شوربة رجل ضفدع؟",
[3945848076]="حلمت بهاللحظة طول حياتي يا الجدة. لحد الآن، كل ما كان عندي قصص أورغيم عن أهلي ومغامراتهم في دراينور. كان أعظم معلم لي وأعز صديق. مات بطلاً... كلهم ماتوا أبطالاً - ولكل واحد منهم، أغنية شرف باقية.",
[3945934008]="دوافعك نقية. أجزاء حجر الزاوية سوف تتجمع. اذهب إلى اولدوار وتعلم إجابات أسئلتك، يا بران برونزبيرد.",
[3946078023]="تم ضبط القوة. أطلق.",
[3946087739]="ثاين باناهوق يظهر على المطل من جهة الجنوب الشرقي!",
[3946112641]="اقتل، اقتل!",
[3946236992]="أوه، أحسنت. هل تشعر بالفخر بنفسك الآن بعد أن أطلقت هذا الخطأ الفظيع؟",
[3946258053]="حسناً، حسناً! لامب يستسلم!",
[3946408938]="مع مكافأة زي دي، كيف يقدرون يرفضوا، مون؟",
[3946449259]="العرض مخصص للضيوف فقط!",
[3946458121]="تنين السرب سوف... يلتهمك.",
[3947189578]="%s يستيقظ، مفزوعاً.",
[3947377903]="شكراً لكم جميعاً لحضور هذه العظة. من الرائع رؤية الكثير من الوجوه المألوفة!",
[3947573809]="ابقَ متيقظًا! موجة أخرى تقترب.",
[3947641338]="إنها تحظى بموافقتي! هذا سينبت لك شعرًا في صدرك مثل أي شيء آخر.",
[3948097072]="حسنًا إذن. لنذهب!",
[3948567435]="لا أحد يتحدى بدو ويستواندر — ولا حتى الدجاجات الآلية! هجوم!",
[3948605147]="%s يلهث.",
[3948735986]="حتى نلتقي مجددًا، أيها الشجاع.",
[3948817121]="هل سنسلك الطريق الخلاب؟",
[3948900801]="هذا غير مجدٍ، يا درايناي! أنت ومساعدك الصغير لا يمكنكما انتزاع السيطرة على هذا الإنسان الحقير. إنه ملكي!",
[3949056168]="شكرًا لكم جميعًا! واستمروا في التصفيق، هناك ذبابة هنا وأحدكم سيصيبها بالتأكيد! تصبحون على خير!",
[3949310642]="هذا كابوس ما بتصحى منه!",
[3949892930]="ما أوافق على تجاربك يا جيرارد، لكن لازم أعترف إن النتائج مبهرة. ماذا بالضبط سويت فيها؟",
[3950267524]="اشرب هذه، أيها الوحش الأزرق! عصياني وأعدك بموت بطيء ومؤلم!",
[3950358390]="قليل من المال لرجل أعمى مسكين؟... ماذا تقصد بأنني لست أعمى؟... أنا لست أعمى! أستطيع الرؤية!! إنها معجزة!",
[3950799548]="ارحل!",
[3951186319]="كيف نعيش بدون سحر؟",
[3951551005]="الظل... سوف يبتلعك.",
[3951730199]="%s يركز على $N!",
[3952022994]="الآن، يا أتباعي المخلصين... إيه، أصدقائي، انطلقوا واغزوا هذه الأرض لشعبنا!",
[3952076940]="يجب أن نتصرف بسرعة وإلا سيضيع كل شيء!",
[3952091296]="من يجرؤ على البحث عني؟!",
[3952193327]="آه! أوقف التعاويذ أيها الأنكورايت! أوقفها، وإلا سأريك من الألم ما لم يتخيله شعبك البائس!",
[3952625123]="اسمع الأصوات من تحت الأرض! إنها تنادي بدمك!",
[3952685501]="شكرًا مرة أخرى. سيسعد الرقيب دورين بسماع أنه لن يحتاج لاستبدال كشاف آخر هذا الأسبوع.",
[3952862324]="بوابة ميج من ستورمويند تظهر بين الاثنين، ويخرج منها فاريان رين وجاينا براودمور.",
[3953605348]="لقد صددنا الـسكورج. ما الفرصة التي تظن أن لديك؟",
[3954242435]="دع عقلك يغشى عليه.",
[3954435599]="سقط ثالوريان أمام بوابات صنويل، ليكسب الوقت للآخرين ليهربوا.",
[3954649588]="لا يمكن أن يكون هناك الكثير من هؤلاء الجامعين. فقط أبقني آمنًا بينما أؤدي عملي.",
[3954893018]="لن يطول الأمر الآن.",
[3955037594]="لقد هُزم الأفاتار اوف تيروك! الموت لـتيروك! الموت لسكيتس!",
[3955047255]="ما هذا المكان؟ سأدمرك!",
[3955082099]="ادخل إلى حلبة الدم، $N. القتال على وشك البدء!",
[3955134315]="لا تدعهم يمسكون بك!",
[3955206130]="أيها الطفل الأحمق، لن توقف ما بدأته! الآن، واجه مصيرك!",
[3955432947]="%s ترفع أنفها وتستنشق ردًا على رد المنفذ الأعلى.",
[3955502942]="أيها الأتباع، دمر هؤلاء المتطفلين!",
[3955606962]="لقد حانت النهاية!",
[3955801132]="الخليطة جاهزة، $N. الآن يجب أن ننقذ الطفل.",
[3956029242]="اسمعوا جيدًا، أيها المدنسون من الـسكورج! لن يصل أحد منكم إلى الشمس المقدسة ما دمت واقفًا!",
[3956560726]="نحن بأمان؛ لن يصل إلينا أبدًا هنا!",
[3956568058]="أمي كانت تصيد أسرع منك، $N.",
[3956881221]="يخرجون من الخشب اليوم. لنواصل التحرك وإلا قد نجد المزيد مما يريد موتي.",
[3957141483]="$N، لا تؤذي أ-مي. أ-مي، جيدة.",
[3957210118]="أيها الأحمق! هذا ما أفعله الآن!",
[3958628286]="%s يضع ضمادة على رأس ريلارا.",
[3958719667]="ماذا تفعلون؟ تبللون أنفسكم...",
[3959363681]="كان يجب أن تبقى في المنزل.",
[3959436889]="هذه أخبار قاتمة، وأخشى أنها مرتبطة بصفقات $N مع المحنط.",
[3959610578]="%s يخرج من الكوخ الخشبي ويلتقطك تعبث بمخازن الحبوب!",
[3959627763]="لقد سمعنا طلباتكم، ونوافق... إنها نبيلة في النية. سنطهر مياهكم. اذهبوا ببركتنا، أيها الشامان.",
[3959795144]="%s تصرخ بغضب وتسرع لمساعدة صغارها.",
[3959912854]="انتظر! بماذا أفكر! لدينا مهمة مع هذه الأشياء.",
[3959974112]="الثروة لي، أليكسي! نهايتك قريبة!",
[3960182469]="يجب تدمير ريفيندير!",
[3960333553]="أنا مكرم... $Gملك:ملكة; تقتلني.",
[3960483950]="أنت لا تستحق حتى أن تُطعم لـليفروث.",
[3960533540]="هذا كان لإحضارك لي إيكور العنكبوت الفاسد!",
[3960598909]="اسمعني، $N. يجب أن تقاوم سيطرة الـليتش كينغ. إنه وحش يريد رؤية هذا العالم - عالمنا - في خراب. لا تدعه يستخدمك لتحقيق أهدافه - مرة أخرى. لقد كنت بطلاً ويمكنك أن تكون كذلك مرة أخرى. قاتل، لعنك الله! قاوم سيطرته!",
[3961020018]="إذا رأيت أي بيون كسول هنا، سأحملهم في منجنيق وأطلقهم إلى بلاك تمبل!",
[3961448527]="تشجع. الحجم ليس ما يهم، بل كيف تستخدم المهارات التي لديك.",
[3961462931]="قريبًا، سيمنحهم السيد الهدية المظلمة، ليجعلهم لائقين لخدمة الـليتش كينغ إلى الأبد!",
[3961543366]="كاليك... كاليك؟",
[3961759428]="لماذا تهاجمه؟ الخطير هناك!",
[3962556431]="إذا أردت شيئًا يُنجز بشكل صحيح، افعله بنفسك!",
[3962713464]="أريد أن أريك جانبًا مختلفًا مني...",
[3962742557]="ما ينقصك في الحجم تعوضه بالطموح والتفاني، أيها الصغير. امضِ مع النور.",
[3962794089]="قريبًا سينتهي الأمر!",
[3962960910]="سأمزق الأسرار من روحك! أخبرني عن \"القرمزي الفجر\" وربما تنجو بحياتك!",
[3963344224]="اتخذ موقعك هنا، وسأقود قوة صغيرة داخل ستراثولم لبدء الإبادة. يجب أن نحتوي ونطهر المصابين من أجل لوردايرون كلها!",
[3963511765]="انظر! انظر! لقد اصطدت شيئًا! أوه... إنه مجرد حذاء قديم نتن.",
[3964194097]="ليريسا... أنت... أنت بخير!",
[3964508171]="وحش! أطعني! اقتلهم فورًا!",
[3964606685]="قم بدورك في الحفاظ على نظافة ديب ران ترام!",
[3964985736]="هذه ليست راحتنا الأخيرة.",
[3965577684]="هذه المهزلة طالت بما يكفي!",
[3965679004]="%s يبدأ في إلقاء تعويذة قوية.",
[3965927280]="اسمعوني أيها الإخوة والأخوات في السلاح! لقد حان وقت أعدائنا! يجب أن نضرب الأوركس النجسين الباقين! أبادوهم كالحشرات التي هم عليها! احملوا معكم بركة أبناء لوثار!",
[3966023891]="كل هذا خطأهم، الأوركس الأغبياء. أحرقوا مزرعتي بالأرض.",
[3966742246]="كم عمركِ، يا فتاة؟",
[3966768687]="حسنًا، لنفعلها!",
[3966978723]="<تنهيدة>... حسنًا، أعتقد أنه كان ممكن يكون أسوأ.",
[3967184150]="احترقوا بنار البر!",
[3967602357]="لنعرف القصة كاملة. هذا سيحتاج بعض السحر...",
[3968471640]="تخلصنا منه!",
[3968477427]="أشم رائحتكم، أيها الغرباء. لا تؤخروا مصيركم. تعالوا إلي الآن. سأجعل تضحيتكم سريعة.",
[3968662526]="هكذا تنتهي لعنتك.",
[3968786273]="$N، شكرًا لك مرة أخرى على مساعدتنا. ما كنا لنحقق أيًا من هذا بدونك.",
[3968825772]="%s يفتح الصندوق.",
[3968899559]="رافيج الأحياء، أيها الجنود!",
[3968906639]="ممم... حان وقت التحرك!",
[3968939419]="لكنه علم بانتصارك على الأسطول الشمالي لـستورمويند ويرى فيك إمكانية. إمكانية أن ترى العقل وتتخلى عن تمرد سيلفاناس الطفولي.",
[3969103059]="%s يمتص الطاقة الظلية للهجوم.",
[3969595587]="%s يبدأ بالدوران، موضعًا بدرع سحري!",
[3969920232]="%s يأخذ نفسًا عميقًا.",
[3970329089]="سأريق دمك، $C!",
[3970416550]="غير معقول!",
[3970839222]="غغغغغغ! سأكسر ركبتيك!",
[3971255880]="ما معنى هذا، مورغور؟",
[3972464255]="يا للأسف أنك نجوت من التحطم لتموت هنا.",
[3972624139]="غزاة اخترقوا الدفاعات!",
[3973116784]="ابتعد، $N. الأرواح قد تهاجم.",
[3973312706]="تاريثا ليس هنا. لنتجه إلى البلدة.",
[3974074192]="انتهيت من هنا.",
[3974403654]="ماذا أفعل؟ لماذا أنا...",
[3974550753]="بناءً على إشارتك، وضعناك... جنوب شرق الجزء الأكبر من الجزيرة التي تحطمنا عليها. اعبر نهر كريستالبروك للوصول... كشخخخ زززت. آسف، هناك الكثير من التشويش...",
[3974595023]="مرحباً.",
[3975520257]="لن تذهب إلى أي مكان، أيها الأحمق!",
[3976067822]="*تنهيدة* ربما أنت على حق، ريفن. سأعود للدورية...",
[3976093092]="حلفاؤك الحمر سيشتركون مصيرك!",
[3976751240]="لن تقتل التالي بسهولة.",
[3977162480]="%s عاد للحياة بصدمة!",
[3977712815]="أظن أنها لا تنحني بهذه الطريقة!",
[3977930259]="الكتاب هو خلاصك، نعم... لكنك لن تعرف شيئًا! لا شيء أقول! لا شيء!",
[3977954217]="فكر، $N. فكر بالوراء. حاول أن تتذكر نوميريغان قبل أولئك التروقز الملعونين! تذكر شعور مفتاح أركلايت، $Gأخي:أختي;. كنت بطلًا من النومز يومًا! هذا ليس أنت.",
[3978343862]="أحتاج حقًا لنظام أفضل لترتيب هذه الكتب. آه، هذا هو الذي أريده.",
[3978513367]="آخر ديث نايت، اللورد موغرين، كان أفضل محارب رآه الديث نايتس على الإطلاق. لكن بعد أحداث أزيروث، اختفى دون أثر. لم يُعرف بعد من عينه كيلثوزاد مكانه.",
[3978845178]="ومع ذلك نرى فقط الهلاك في مستقبلك. إنه قدرك أن تفعل هذا، $N، لكننا نخشى أن النبي قوي جدًا عليك وعلى أصدقائك. مع ذلك، يجب أن تحاول.",
[3978872724]="هل فات الأوان لأغير رأيي؟ ماذا لو تقتلني بدلًا من ذلك؟",
[3979468877]="انطلقنا! احترس من تلك الكروم!",
[3979475957]="الآن... نحتاج البيض الذي تسترده. بيض نيذر وينغ. فهي، بعد كل شيء، نتاج السيد. سندفع أي ثمن تطلبه.",
[3979487632]="%s يفتح كاوتيك ريفت!",
[3979975003]="الجمهور يهتف.",
[3981251676]="تذكروا، أيها الأبطال، الخوف هو أكبر أعدائكم في هذه القاعات النجسة. قوّوا قلوبكم وستشرق أرواحكم أشد ضياءً من ألف شمس. العدو سيترنح عند رؤيتكم. سيسقطون حين يغمرهم نور البر!",
[3982466370]="ظننت أننا تحدثنا عن هذا، بروق. لا يمكنك البقاء في هذا المبنى. صحيح أنه يمكنه إيواؤك، لكن لا يوجد مكان لأي شخص آخر!",
[3982566009]="ميت، ميت، ميت!",
[3983271740]="أجل، ولكن ليس بالطريقة التي تتخيلها.",
[3983722682]="%s يطلق صرخة، يستنجد بالمساعدة!",
[3983748631]="لاااا!",
[3983816116]="لم أنتهِ بعد، أيها الأحمق!",
[3983957821]="تجمعوا خلفي عند بوابات أندرسِتي! قريبًا سنزحف على مدينتنا الساقطة ونستعيدها - من أجل الـهورد!",
[3984189941]="هوو-واه! الفرسان وصلوا!",
[3984419031]="لا. ابتعد أيها الدودة.",
[3984712366]="انظروا! منجل أنتيوك!",
[3984858895]="كنت سأخطط للتخلص منه على أي حال، لكن أعتقد أننا نستطيع تسريع العملية قليلاً.",
[3986601384]="حر!!!",
[3987221974]="ترول جديد هنا!",
[3987431439]="اضربني مرة أخرى وستندم!",
[3988635227]="إنه زوجك يا امرأة. كيف لي أن أعرف أين هو؟",
