[4040612095]="فرسان النصل الأبنوس، استعدوا للمعركة!",
[4040760728]="استمع جيدًا، فسيد بلاكروك سيدمرك بالتأكيد إن لم تكن مستعدًا.",
[4041309945]="بشعورك وفهمك للتعاطف في العدو والحليف على حد سواء، تؤكد ارتباطك بالعالم.",
[4041724472]="وإذا مات واحد، سيقوم اثنان!",
[4042132439]="القلب المتجمد لإيسولدوف سيلتهم هذه الأرض حتى يُعاد. ويل لمن يمسك القلب إذ تلعنه لعنة الدم المتجمد...",
[4042171254]="أريد أن أكون مثل مقاتل الحفرة!",
[4042260442]="الحمم المحيطة بـ%s تغلي!",
[4043342828]="الموت للمتطفلين!",
[4043460266]="الـهورد دافع عن قلعة وينترقراسب!",
[4043463836]="مقبرة سنوفول سقطت بيد الـهورد!",
[4043501406]="نهايتك.",
[4043757035]="ذلك التوهج الرهيب... هل ينبغي أن يكون كذلك؟",
[4044048464]="بدأت أقلق. أين هذا البطل الذي من المفترض أن يقودنا للمعركة؟",
[4044197906]="الموت قادم. هل سيكون ضميرك مرتاحًا؟",
[4044784415]="هذا يموت بسهولة!",
[4045786710]="%s يبدأ باستحضار ألغام متفجرة بسرعة!",
[4045915390]="لا مفر من إرادة الـليتش كينغ. استعد لمواجهة متفجرة!",
[4046219803]="سأستغل الوقت بحكمة، يا سيدي. شكرًا لك.",
[4047068391]="حسنًا، آسف لسماع ذلك. سأمر لاحقًا إذا أردت مساعدة.",
[4047255097]="ولا أريد لأرضنا أن يكون فيها أي من تلك الذئاب الرهيبة، أو العمالقة، أو الكباش القبيحة!",
[4048233823]="تم الاستيلاء على مخزن دن بالدار الشمالي من قبل الأليانس!",
[4048299245]="جارٍ الوصول إلى بيانات ما قبل التاريخ... تم الاسترجاع. في البداية، تم إنشاء الإيرذن لـ--",
[4048395090]="الأرجنت كروسيد تدعوك لاختبار مهاراتك في قتال شريف ضد أبطال آخرين من أزيروث في الأرجنت تورنمنت.",
[4049015588]="بوابة الياقوت الأزرق دُمّرت!",
[4049514358]="%s يمسك بخنجره المسموم!",
[4049561729]="أنت محق! بماذا كنت أفكر؟ أحضروا الـسكورج!",
[4050261663]="أنا متأكد أن العجوز هيميت يمكنه فعل شيء بعظامك!",
[4050478445]="أطعني!",
[4050596519]="من الجيد رؤيتك مرة أخرى، مورادين. وما هذا الذي سمعته عن كونك ملكًا الآن؟ عائلة برونزبيرد كانت دائمًا مقدرًا لها العظمة.",
[4051665356]="لا أستطيع الانتظار لتجربة هذا النبيذ!",
[4051695992]="لا تتحدث معي عن العواقب، أيها العجوز.",
[4052017381]="داروشاير! أنت محكوم عليك!",
[4052385161]="ذلك اليوم ليس اليوم...",
[4052389247]="هذا لا يمكن أن يحدث!",
[4052431617]="انظر إلى عجائب هذه المدينة! هذا سحر.",
[4053171937]="لا تهتم بي، أو برائحتي... لأنني بالتأكيد لا أفعل!",
[4053197425]="كيف يمكنني أن أرد لك هذا الجميل، يا صديقي؟",
[4053640745]="أوه! ها هي قبعتي المحظوظة. كنت أبحث عنها في كل مكان.",
[4053804856]="على أجنحة الظلام يحلقون. استعدوا للقاء نهايتكم!",
[4053817168]="حسنًا بيسي، لنخرجك في نزهة هنا. هوت، هوت!",
[4053927083]="أيها المغامرون، عليكم الإسراع! غارديان أوف تايم لا يمكن أن يستمر لفترة أطول!",
[4054481434]="شكرًا لك!",
[4054547359]="لفترة طويلة، كنت ضائعًا... فساد نايتماير قد التهمني... والآن أنت... كلكم... لقد أنقذتموني. حررتموني من قبضته.",
[4055604438]="أو-أوه. لدينا زوار! تَمَسَّكوا جيدًا! سأحاول التخلص منهم!",
[4055620297]="أنت غير مرحب بك هنا!",
[4055889738]="نوت روت!",
[4055930107]="الانتقام يشتعل!",
[4056396258]="أحضرت لك هدية ترحيب، يارل.",
[4056469521]="أنت سيء... ألعاب... جدًا... سيء",
[4057766807]="انظر! هل هذا نحن؟ نعتقد أنه نحن. أكبر قليلاً، ربما؟",
[4057879493]="هاها! ترولبلو القوي العجوز لديه فقط بعض الندوب القتالية البسيطة!",
[4058321012]="هكذا انتهت قوة الطبيعة... موهاهاهاها.",
[4058629446]="مرحبًا بك في الشتاء اللا نهائي.",
[4058749861]="لوك'تار أوغار، بوبو!",
[4058985144]="أشعر بشر يختمر...",
[4059340648]="تشاغا... تشوكاجين.",
[4059848091]="تم الإبلاغ عن نشاط ديفياس في الأفق الساحلي. كل شيء واضح في تلة سينتينل.",
[4059866946]="أبطال، قابلوني في قاعة المدينة فورًا. يجب أن نأخذ المعركة إلى مالقانيس.",
[4059924309]="ها هو! كنت أقسم أنه لم يكن هنا آخر مرة تفقدت فيها...",
[4060051681]="الموت هو ثمن غطرستك.",
[4060243684]="هل أنت من دمر أطفالي؟ أنت... ستدفع... الثمن!",
[4060378715]="شكرًا جزيلًا!",
[4061192972]="كنت أعرف أنه ما كان يجب أن آتي إلى البطولة!",
[4061655358]="انظر إليها، لور'ثيمار. إنها بالتأكيد كويلديلار.",
[4062434434]="كل ما نعرفه عن هذا الممر الزمني هو أنه يؤدي إلى ماونت هايجال. لقد بذلت تنانين اللانهاية جهودًا كبيرة لمنع تدخلنا. لا نعرف شيئًا تقريبًا، أيها الفاني. سوريدورمي يحاول حاليًا اختراق دفاعات الممر الزمني لكنه لم ينجح حتى الآن. قد تكون أملنا الوحيد لاختراقه وحل النزاع.",
[4062694137]="لاااااا!",
[4063117671]="أطلقوا النار!",
[4063140094]="ليست مشكلتي! إذا كنت مستعجلًا جدًا لبناء منزل، افعله هنا في الحصن وتوقف عن التذمر!",
[4063360178]="وداعًا، رايلوراز.",
[4063502553]="أنا... حررت...",
[4063777351]="الملكة ومجلسها يتحدثون مؤخرًا عن كارثة في اولدوار. شيء ما حدث في ستورم بيكس!",
[4063963079]="انتهت أيامك!",
[4064086993]="حتى الموت هنا أفضل من قضاء يوم آخر في جمع المواد لذلك المجنون، فينكلستاين.",
[4064157096]="ماذا؟ أنا حتى لا أعرف عن ماذا تتحدث! هذا فظيع!",
[4064242825]="مطاردتي الطويلة انتهت أخيرًا. اليوم، سيتم تحقيق العدالة!",
[4064632696]="لا أريد أن أُنزل إلى السراديب!",
[4065640257]="استراتيجيتك كانت معيبة.",
[4066551253]="يشربون خوفك: إنه دم الحياة.",
[4066664870]="كم تساوي شرفك يا دورم؟ حياتك؟ حياتي؟ حياة العجوز الأعمى قرياتفادر ماهان الذي رباك منذ الطفولة؟",
[4067304147]="اذهب الآن إلى سيدي!",
[4067655688]="لا تقتلني!",
[4067800979]="أحضرهم أمام الكنيسة!",
[4068300929]="المقبرة الغربية تم الاستيلاء عليها من قبل الـهورد!",
[4068508555]="شكرًا لمجيئك لرؤيتي! أتمنى أن تكون مستعدًا لقضاء وقت ممتع، لأنني مستعد.",
[4068756476]="لم أكن سعيدًا بهذا القدر من قبل! أتمنى ألا تنتهي هذه الليلة أبدًا!",
[4068953171]="انهض!",
[4069497900]="أحب لحمي مقرمشًا جدًا!",
[4069658920]="فانكليف يرسل كلمة بأن الخطط جارية. لكنه سمع شائعات عن شخص يتجسس.",
[4069971092]="%s يرمي آشبرينغر الفاسد إلى تيريون، الذي يمسك به. يغمر تيريون بالنور، ويتم تطهير آشبرينغر.",
[4070155067]="الفناء لنا! تقدمًا إلى الحرم الداخلي!",
[4070277523]="%s يشم رائحة جثة طازجة قريبة.",
[4070606426]="سأفجر هؤلاء المقلدين النومز إلى كومة الخردة!",
[4070809731]="يفضلون الموت على الركوع أمام نورث ويند. هناك شيء مريب هنا.",
[4071467806]="ماذا كان ذلك!",
[4071635537]="لقد جئت من أجل خطط الطبيب! لن تجد إلا الموت!",
[4072086610]="يجب أن أعود قبل أن يبدأ ريما بالقلق...",
[4072430256]="أتجرؤ على الاعتقاد بأنك أحبطت إرادتي؟ بأنك كسرت خططي؟",
[4072491472]="فقط قليلاً من الوقت، لقد أوشكت على الحصول عليه!",
[4072611314]="للصيانة العادية للزمن، يكفي حراس الزمن كأوصياء. نحن قادرون على التعامل مع معظم الاضطرابات العادية. أتحدث عن أشياء صغيرة، مثل ميج مارق يغير شيئًا في الماضي لرفع مكانته أو ثروته في الحاضر.",
[4072959006]="تاريثا! أي سحر خبيث هذا؟",
[4073195575]="يا لورد هيريك، امنحني أجنحة الانتقام!",
[4073324888]="إنه لعار أن شراب كورين القوي لا يستطيع إرواء المزيد من الحناجر الظامئة! إنها كفر، أعلم، لكني أحسد أولئك الدوارف من الظلام الحديدي!",
[4074061688]="ركّز (على تحريري من هذا السجن الجهنمي) وحاول لاحقًا.",
[4074119456]="لا يمكنك إيقاف ثيلزان! إنه يحمل الهدية المظلمة التي منحها له الـليتش كينغ بنفسه!",
[4074123775]="ستخبر قائدك أنني لن أنتظر لحظة أطول! هل يريد هذا الأليانس أم لا؟!",
[4074717123]="عندما أعطي الإشارة، أطلق أعظم زئيرك!",
[4074825316]="كيف يمكنك أن تأكل البودينغ إذا لم تأكل سمكتك؟",
[4075678257]="أشكركم جميعًا. كان درويدز القدماء حكماء عندما هدموا فوردراسيل، لأن جذورها تتغلغل عميقًا في مسكن شر قديم.",
[4075689119]="كابتن بارتليت، أخرجنا من هنا! لقد تلقينا ضررًا كبيرًا لدرجة لا نستطيع معها البقاء طافيين!",
[4075851027]="%s يحاول فتح قدم ماوري المفلطحة...",
[4075884909]="أو. حار.",
[4075901485]="حسنًا، أيتها القطة. لا أرى داعيًا لتأخير حتمية موتك. أتطلع للتعامل معك حالما أنهي أمر هذا الأحمق!",
[4075978285]="آآآه! هذا ليس صحيحًا!",
[4076204477]="ولكن هل يمكن أن يكون؟ هل هذا حقًا --",
[4076505147]="الوحش في كوابيسك.",
[4076543730]="همم... تلك الصخرة جميلة، لكنها صغيرة جدًا.",
[4076761686]="احتضن العدم!",
[4076791642]="%s يقبل حبيبته.",
[4076928073]="دخلاء يدمرون بيضنا! توقفوا!!",
[4077128824]="أنا... أكره...ك.",
[4077168483]="يجب أن نحضر حرق الـويكرمان القادم.",
[4077282668]="أنت تتجاوز الحدود، $N.",
[4077310578]="تخلصنا منه.",
[4077512474]="حياتك فداء للـليتش كينغ!",
[4077534942]="ألن يتسبب ذلك في تفكك النسيج إذا لم يُثبت بشكل صحيح قبل بدء الاستدعاء؟",
[4077551875]="هووووب... هووووب... بلييييه!",
[4077621773]="أعمال خادمك $R تتحدى مكانة $Gخاصته:خاصتها; يا ستورم لورد. جهود $Gخاصته:خاصتها; نجحت في تليين قلوب شعبي.",
[4077749886]="هيا بنا يا عزيزي.",
[4077917145]="نار! نار! أسقطوها!",
[4077944175]="أيها الحمقى، لقد فرقتم قواكم كثيرًا. كونوا أحرارًا يا أتباعي!",
[4078322680]="اثبتوا في أماكنكم! اثبتوا! يا أبناء الأليانس! يا أبناء الـهورد! إخوتي وأخواتي! أرى في أعينكم نفس الخوف الذي قد يذيب قلبي. قد يأتي يوم تخوننا فيه شجاعتنا، ونتخلى فيه عن أصدقائنا ونكسر روابطنا... لكنه ليس هذا اليوم.",
[4078789938]="يقولون أن دوريل نايت إلف شرس. ستكون معركة جيدة!",
[4078832249]="غورغيك يروح يجيب شراب. انت قعد في الركن لحد ما غورغيك يجهز.",
[4078943668]="ماليفوس يستدير ويشير إلى كتالوجه على البرميل.",
[4080864414]="منتشرين في كل قوست لاندز، قواتنا ستكون قليلة الفائدة في هجوم على ديثولم. لا، يا سيدتي، أنا هنا لأقتل دار'خان وهذا ما أنوي فعله!",
[4080954285]="مباشرة من غابات إلوين الخضراء، احصل على فواكهك الطازجة هنا.",
[4081495840]="إيب!",
[4081707918]="لا تظن أنني سأسمح لك بالدخول إلى مقام سيدي بهذه السهولة. طاردني إن كنت تجرؤ.",
[4082202283]="لكن هذه نوع مختلف من القتال الشريف. قد يكون من الصعب التكيف معه، لكن ببراعتك أنا متأكد أنك ستظهر للجميع قوة شعبك.",
[4082657824]="%s يبدأ في التقطيع مع عطل في محركه.",
[4082864490]="آك! أحد يساعدني!",
[4082979497]="النور يدين كل من يؤوي الشر. الآن ستموت!",
[4083098387]="أشعر بشيء غريب فجأة. إيه؟!",
[4083530916]="مالفوريون!",
[4083760264]="العظيم سيسحقك!",
[4083834235]="أقوى ديث نايتس داخل ناكسماراس هم الفرسان الأربعة. يمثلون قمة حرس كيلثوزاد. الأول، ثين كورثآز، يمتلك قوة النار.",
[4084403972]="عندي الفودو القوي، مون!",
[4084859838]="كدت... أنجح...",
[4085301542]="كنت أفكر... لازم نأخذ رحلة جنوبًا إحدى هذه الليالي، يمكن نعمل نزهة مسائية نطل على القتال عند الحدود؟ ما رأيك يا سيدي؟ أليس هذا مثيرًا؟",
[4085373089]="أنتم من جلبتوا هذا على أنفسكم!",
[4085416392]="سأقضي عليك نهائيًا هذه المرة!",
[4085955903]="%s يعود إلى العمل، غافلًا عن كل ما حوله.",
[4085979035]="هل ظننت حقًا أنك بمواجهتي لديك أي أمل في إنقاذ أصدقائك؟",
[4086157523]="لآلاف السنين، كان هذا الكائن ساكنًا تحت العالم - ينتظر وقته. من سجنه، انتظر اللحظة المناسبة للرد على أولئك الذين يريدون إيذاءه.",
[4086635355]="رليق يعلمك درس الآن!",
[4086762497]="ما الذي قد يستغرق كل هذا الوقت؟",
[4087058951]="وداعًا، أيها الصديق القديم... وداعًا...",
[4087165114]="أهذا كل ما جئت لتقوله؟",
[4087397633]="يقولون إنه يستطيع التحول إلى غراب أحيانًا.",
[4087506713]="عائق واحد أقل في طريقنا!",
[4087937126]="توقف!",
[4088277179]="أعط الأمر، أيها الجنرال. سيكون لدي فوجان تحت تصرفك في غضون شهر.",
[4088349678]="أسلحتك لا تعني لي شيئًا! استسلم!",
[4089006242]="لا! الصوت الحقيقي للتاريخ سينتصر. سنعيد كل ما دمرته!",
[4089264605]="أيها البشر الحمقى. هل ظننتم أننا هُزمنا بهذه السهولة؟ السانلاين هم جنود الـليتش كينغ الخالدون! الآن ستواجهون قوتهم مجتمعة!",
[4089411978]="إذن لماذا أنت هنا؟ ماذا سنفعل إذا لم يكن هناك أمل؟",
[4089501773]="لا أصدق أن عربة الفورسيكن تعطلت. لا حظ لنا في هذه الأرض...",
[4090346882]="هنا، إلى الجنوب الشرقي. أرى أنهم أمسكوا بك أيضًا...",
[4090554877]="تلك السحابة تشبه الوارتشيف.",
[4090855255]="أنا جائع.",
[4091610757]="حقًا؟",
[4091864767]="دَمَار!",
[4092318111]="أبي...",
[4093202169]="%s يشعر بمصيره!",
[4093217569]="تقدموا، يا أتباعي! تقدموا! لا تدعوا أحدًا يقف في طريقنا!",
[4094323650]="لن تحرمني من هذا، آرثاس! يجب أن أعرف... يجب أن أكتشف...",
[4094667841]="سأضحي بآلاف الأرواح من أجلك، يا سيدي.",
[4094769534]="ألمك قد بدأ للتو!",
[4095256716]="مرحبًا، تشاريس. لدي قائمتي، هل يمكنك إحضار كل هذا، خاصة المكون الأخير.",
[4095612324]="ها، رائع!",
[4095711990]="ربما يمكننا تجربة هذا لاحقًا. تفضل بالتحدث معي مرة أخرى إذا كنت ترغب في ذلك.",
[4095769281]="لقد هُزم أنوبيتكان! خذ قطعة من هيكله كدليل على انتصارك!",
[4096482752]="يسعدني رؤيتك مرة أخرى، إيرلاند. ما هو تقريرك؟",
[4096623902]="أوه، فهمت كيف الأمر... ستتعامل معي هكذا، إيه؟",
