[4138996189]="أرض النجوم الأبدية، كاليمدور، كانت أمًا حنونًا لجميع مخلوقاتها. سحر بئر الأبدية تخلل الأرض وأعطى القوة للعديد من النباتات والحيوانات التي جعلت العالم موطنها. من هذا الأثير السحري وُلدت السيلثيد. من خلال السيلثيد حاول الإله القديم الكئيب الوصول ومحاولة تمزيق العالم الذي كان يومًا في قبضته القاسية.",
