[4158250162]="حواجزك لن تصمد أمامنا طويلاً أيها الوحش! سأحطمها كلها!",
[4158394044]="شكرًا لإنقاذي، لكن الآخرين ما زالوا محتجزين في الطبقات أعلاه!",
[4158416800]="إذاً يمكنك تعليمي هذا... هذا...",
[4158926197]="يوم آخر، معركة أخرى مجيدة!",
[4159431222]="حان وقت وقفتك الأخيرة، أيتها الحشرة.",
[4159506719]="هذا الكيوريتور مجهز لحماية المعرض.",
[4159828672]="لن توقف الفورسيكن أبدًا، $R. الـليدي المظلم سيجعلك تتألم.",
[4160607514]="هناك شيء آخر هنا أيضًا. بعد وصف معركة دموية وسقوط الغراب، هناك نبوءة. انزو سيطارد أحلام أعدائه، محرفًا إياهم لتحقيق عودة إلى هذا العالم...",
[4160652980]="لا أفهمك!",
[4161317950]="رغم أنهم يبدون وحشيين، إلا أن هؤلاء المرعبين المطرزين بالحديد هم مهندسون وحدادون بارعون للغاية.",
[4161606751]="مقبرة سنوفول تتعرض لهجوم! إذا تُركت دون رقابة، سيستولي عليها الـهورد!",
[4161750286]="لن تفلت بهذا، أتعلم؟ أنت مجرد طفل.",
[4162104134]="تحديك المثير للشفقة لم يمر دون أن يُلاحظ. سأستمتع باللعب معك قبل أن تموت.",
[4162122235]="ستورمهوف وأقرباؤه سيُمحون من التاريخ وستُعاد هذه الأراضي إلى مالكها الشرعي!",
[4162791167]="بالـصن ويل، يا لك من عنيد! لن ترغميني على الرحيل يا تاليريس. الآن، ابتعد عن ناظري!",
[4163360733]="أجل، قلنا لك يمكنك البقاء هنا، لكن هذا المبنى هو مقرنا الرئيسي! كل أدلتنا ومخططاتنا مخزنة هنا!",
[4163942024]="أوووووه...",
[4164567263]="إذا سمحت لي، أخشى أن لدي أعمال أخرى يجب أن أتفرغ لها. أرجو زيارتي مرة أخرى في المستقبل.",
[4164906601]="ثاساريان! أنت حي!",
[4165279784]="إذا سُمح لي بالانصراف، فأود أن أتفقد كوين...",
[4166057890]="قلت لك سأكون مستعدًا أفضل عندما نلتقي مجددًا. لقد خضت وفزت في هايلدسميت، وتدربت في فالكيريون، وها أنا ذا. تعال وخذ نصيبك!",
[4166095046]="لقد وصلت للتو إلى فينومسبايت. كيف يمكن أن أكون قد ظلمتك؟",
[4166152855]="لن يكون هناك ناجون، يا سيدي.",
[4166364286]="لقد بحثت في هذا الموقع بشكل مكثف ولن أسمح لأي صيادي كنوز أغبياء بالانقضاض وسرقة ما ينتمي إلى متحف. سأقود هذه الهجمة.",
[4166382291]="هذا... سيلفرمون؟ رأسي... المرة الجاية إذا بلودفالور يحتاج متطوع، بدله بدل ما أدله على طريقي. قدوة فضيلة بلود نايت، فعلاً!",
[4166480110]="أفعل ما يجب فعله من أجل لوردايرون، ولا كلماتك ولا أفعالك ستوقفني.",
[4168021940]="الجوبلنز يفوزون بسباق السحب! حظ أوفر في المرة القادمة، يا فريق النومز.",
[4169136905]="ماذا؟ هناك ضريح تحت القرية القديمة؟ يا لنا من حمقى لم نلاحظ! سنجد سيدك الآن يا غودفري ونضربه. سننهي هذا الكابوس.",
[4169214031]="أووه! انظروا، واحدة لامعة!",
[4169333836]="مرحباً جميعاً! كم من الوقت حتى تظهر النكات؟",
[4169484955]="معركة السيطرة على وينترقراسب ستبدأ بعد 5 دقائق! جهزوا أنفسكم للمعركة!",
[4170011939]="اتبع هذا الطريق، مون، وقريباً ستتذوق الخلود!",
[4170562284]="لك مني الشكر، أيها الغريب.",
[4170608629]="على عكسك، لدي مواهب كثيرة!",
[4171042404]="يحترق! الألم... لاذع...",
[4171127718]="حسنًا! كما ترى، كانت هدية من قراندماذر أولوبا. هي نسجتها يدويًا من أفضل حرير في دراينور! أنا فخور بها جدًا، نعم.",
[4171872382]="حسنًا، الآن بعد أن حصلت على خيط جيد، أعتقد أنني سأستمتع بقيلولة صغيرة.",
[4172601935]="%s يبدأ في إلقاء الانفجار العظيم!",
[4173544792]="مزيد من الأخطار... تنتظر...",
[4174204404]="%s يحدد موقع حجر غراب مدفون.",
[4174342948]="لن أستلقي هنا ببساطة وأسمح لك بقتلي! سيكون عليك أن تكسب حقك في التنفس مرة أخرى إذا أردت قتلي، أيها الفاني!",
[4174976121]="%s يقهقه، مداعبًا كاحلي سينتينيل سويت سبرينق.",
[4175452463]="كور'كرون، أخرجنا!",
[4175669828]="أتوسل إليك... لا مزيد.",
[4175745424]="هل دمرت الشياطين في الـديد سكار مؤخرًا، $N؟",
[4175822197]="حان وقت الهرب! شكرًا، يا صديق!",
[4176178318]="فم سيربنت يلتهمه نار التوسكار!",
[4176252712]="تقول هذا الآن، لكن على الأقل لديك عشاء دافئ ينتظرك...",
[4176653013]="أحمق آخر يقع في الفخ!",
[4177722197]="أفهم أنك تستحق الشكر على الجزء الأكبر من إمداداتنا.",
[4178178996]="ما تراه أمامك هو فيلهنتر. مواهب هذا المخلوق الطبيعية تشمل قفل التعويذة وقدرات أخرى تجعله لا يُضاهى عند مواجهة خصم متكيف مع السحر.",
[4178356602]="نعم، يا غالي، سنمزقهم إربًا! للملك الحقيقي الوحيد!",
[4178986199]="%s يتبدد في الأثير، ولا تزال رياحه العاتية ترن في أذنيك.",
[4179270325]="تم رفض الطلب. الوصول يتطلب التحقق اليدوي من أختام المراقبين الأربعة.",
[4179566307]="لا توجد مؤشرات على مقاومة. لا يوجد حراس.",
[4179575906]="تعالوا يا أتباعي. تعاملوا مع هذا الخائن كما يستحق!",
[4179824018]="هل جاء ليقودنا؟",
[4180382072]="المجد للأليانس!",
[4180391664]="لا يجب أن أخاف....",
[4181038105]="طرق الشحن... الإمدادات... لقد أملتموني حتى الموت! لا نحتاج سوى الروح الحربية للهورد، يا ساورفانغ! الآن وقد ترسخنا في هذه الأرض المتجمدة، لا شيء سيوقفنا!",
[4181249317]="جميع الخدمات والمتاجر ستبقى مغلقة حتى إشعار آخر! هذا كل شيء!",
[4181436383]="أتمنى أن تعمل هذه الآلة اللعينة. *أرايكس يضرب على جهاز الإرسال المحمول.*",
[4181829739]="قريباً سيعرف العالم كله اسم ويلفريد!",
[4182179878]="بناءً على طلبك، حضر الكوربورال سبليثوف، $N.",
[4182456140]="شكرًا $N. الآن لنخرج من هنا!",
[4182750888]="أنا... متجدد.",
[4182976639]="قبل أن أغادر هذا المكان، أقدم لك عرضًا أخيرًا، يا لورد ستيغهيلم. إذا جاء وقت تحتاج فيه لدخول هذه القلعة الملعونة، استخدم صولجان الرمال المتحركة على الجرس المقدس. السحر الذي يمسك الحاجز سيتلاشى وستُطلق أهوال آهنقيراج على العالم مرة أخرى.",
[4183522698]="لقد مرت سنوات عديدة...",
[4183906451]="دمر!",
[4184321721]="سامحوني، أيها الأبطال. كان يجب أن أستمع إلى أوثر. أنا... أنا فقط كان يجب أن أرى بنفسي. أن أنظر في عينيه لآخر مرة. أنا آسف.",
[4184486259]="رايمفانغ، احبسهم داخل النفق! ادفنهم أحياء!",
[4184553626]="فقط أخبرني بما تعرفه عن نزل شادي ريست، ولن أحطم جمجمتك.",
[4184729360]="%s يقرأ النص القديم الذي أحضره له $N...",
[4184737898]="لماذا دائمًا نذهب بنفس الطريق؟",
[4184970435]="أهلاً بإخوتي! استمتعوا بمجد قوتي!",
[4185403887]="أن تكون الأقدار قاسية لدرجة أنها لا تسمح لنا إلا بهذا بعد ألف عام من الفراق...",
[4185405124]="حسنًا، لن يعجبك ما سأخبرك به أيتها الصغيرة. هذا اللوح هو رسالة من الناغا. زعيمهم، وارلورد سريسّتيز، أمر الناغا بالاستيلاء على بقية الجزيرة بالقوة.",
[4185541613]="رياح غاضبة تحيط بـ فاكيز وهو يتلوى باتجاهك بشكل مهدد.",
[4185800373]="قطة صغيرة للبيع، تبحث عن منزل جيد.",
[4186559615]="لماذا يجب أن يكون الأمر هكذا؟",
[4186870879]="نحن نشرف بحضورك يا ابن دوروتان. الأم العظيمة تنتظرك في المستوصف.",
[4187044932]="أنا أمل.",
[4187144621]="%s يطلق آخر طاقاته في حجر الرون القريب، ويعيد تنشيطه بنجاح.",
[4187553130]="%s يبدأ في استدعاء كولابسنق ستارز!",
[4188144807]="لا أحد يستطيع الوقوف في وجه اللوردات سيربنت!",
[4188524224]="هذه مجرد راحة قصيرة...",
[4188820098]="أيها القذارة الأرضية!",
[4189137683]="يقولون إني غير جدير؟ سأريهم ما معنى عدم الجدارة!",
[4189152025]="أوووهههههههههههههههه......",
[4189156054]="سآكلك لاحقًا، مون.",
[4190499568]="أنا أعلم ما يكمن من شر في قلوب الأوركس.",
[4190514491]="بائع الفاكهة!!! عربتك لا تزال في طريقنا! سنعطيك ساعة إضافية لتنقلها من منطقتنا. لا تختبر صبرنا أكثر!",
[4190724827]="روح إتشياكي تتدفق فيك، $N.",
[4191069056]="انظروا حولكم، أيها الإخوة والأخوات. افتحوا أعينكم! انظروا ماذا فعلوا بمملكتنا!",
[4191104901]="أمفرم ممفور، موروفرو...",
[4191424439]="النجدة! عيناي!",
[4191563855]="شاهدوا الآن كيف أبعثهم من الموت ليصبحوا أسياد الـسكورج. سيكسو هذا العالم بالفوضى والدمار. سقوط أزيروث سيكون على أيديهم -- وستكون أنت أول من يموت.",
[4192423891]="انتبه لما تتمناه.",
[4192820044]="هل تثق بمهاراتك؟ فكر جيدًا، فالإجابة قد تفاجئك.",
[4193004144]="وشكرًا لك، $N. بدون مساعدتك، لما كنت لأجد طريقي إلى الـفورسيكن.",
[4193450753]="الهرب لن ينفعكم، أيها البشر!",
[4193635818]="احموا دافيل لايت فاير!",
[4193882024]="يحيا $N!",
[4194430507]="%s في سلام مرة أخرى.",
[4194528922]="فاريان، توقف! لن أساعدك في فعل هذا!",
[4194676008]="ما هذا الاضطراب؟ تتجرأ على التعدي على هذه الأرض المقدسة؟ ستكون هذه مثواك الأخير!",
[4194885528]="عندما أمسك بك، سأفك سحر مكوناتك، أقسم بذلك...",
[4195032960]="%s يبدأ بإلقاء تعويذة شفاء عظيمة!",
[4195314827]="ريلارا... هل استيقظتِ؟",
[4195981712]="ولو كان فرسترايدرز هنا لتعزيزنا، لربما وافقت. لكنهم مشغولون بدلاً من ذلك بترولز شادوباين على حدودك الشرقية. كلما طال انتظارنا لهم، أصبح الـسكورج أقوى.",
[4196168466]="شكرًا لمساعدتك، أيها البطل!",
[4196674421]="ما فعلته شنيع! كفّر عن جرائمك ضد النور!",
[4196776064]="توقف.",
[4197726432]="اخرس، هل تفهم؟ إذا انتبه أحد، سنموت كلانا.",
[4198866737]="ألم يكفِ ما فعلته من أذى؟ هل يجب أن تزعج نومي أيضًا؟",
[4198989986]="ليزاريك عنده سيوف. ليزاريك عنده صولجانات. ليزاريك عنده كل ما تحتاجه من أسلحة هنا!",
[4199130609]="تقدّم. سأرى أنك تُستقبل كما ينبغي!",
[4199208435]="الحرب... مستمرة.",
[4199316669]="أي حظ، صامويل؟",
[4199738011]="موتكم سيكون بطيئًا ومؤلمًا!",
[4200042785]="جسدك يخونك.",
[4200054103]="تم رصد أعداء! اهجموا بينما أحاول تفعيل حامي!",
[4200226306]="أضحي بحياتي... بكل سرور.",
[4200603553]="%s يكبر حجمًا عند رؤية $N!",
[4200917090]="هذه المنطقة ستدمر نفسها خلال دقيقة واحدة.",
[4200927868]="شكرًا لك، $R. سأنضم إلى نضالك ضد الـستورمفورجيد.",
[4201175164]="لا، لن نتركك تعيش.",
[4201250443]="الأرجنت داون ونظام الـسيلفر هاند سيتحدان معًا! سننجح حيث فشل الكثيرون قبلنا!",
[4202193843]="نحن هالكون!",
[4202452448]="تحتاج أن تفعل ماذا؟ كل هذا العلم، لا أفهم... انظر، هذه مجرد وظيفتي، خمسة أيام في الأسبوع.",
[4202465148]="با'انثالسو-دوري!",
[4202593703]="آرثاس هنا؟ ربما أنا...",
[4202876491]="هذا هو المكان، $R: الـكاولدرون! مارك على خريطة أو افعل شيئًا حتى لا تنسى. إذا حدث لي أي شيء، سيبقى فريقي عالقًا في ذلك المنجم إلى الأبد.",
[4202899996]="$N؟",
[4203523283]="هذه الجعة رائحتها قوية!",
[4204357608]="اذهب أيها الشيطان النجس!",
[4204611343]="لنتحرك.",
[4205146632]="خبز طازج للبيع!",
[4205465642]="مشاجراتكم التافهة لا تزيدني إلا قوة.",
[4206341425]="لكن... لم يحن وقت خدمتك لي بعد الـليتش كينغ. أجل، مصير أعظم ينتظرك. القوة... يجب أن تصبح أقوى قبل أن تخدميني.",
[4206384522]="آه... ها أنت ذا. السيد أخبرنا أنك ستصل قريبًا.",
[4206422212]="%s يبدأ بالصفير لحنًا، لكنه يتوقف فجأة ويئن.",
[4206515518]="لا نركب البغال هنا. علاوة على ذلك، الأمر يخص البعثة حاليًا.",
[4206669953]="ابقوا هادئين يا ناس. لا نريد كشف موقعنا.",
[4207800923]="أوه رأسي... أي... أين أنا؟",
[4207977190]="هذه الليلة، الأمور ليست كما تبدو... فهذه الليلة لا تثق بعينيك!",
[4208089639]="جاء فريزي هارت إلى هنا منذ وقت قصير بحثًا عن موطن جديد... بيوت ذوي الألسنة الكبيرة جميلة، وربما نأخذها أيضًا. فهم قبيحون على أي حال.",
[4208602551]="مجرد طعم صغير...",
[4208650612]="الـهايير أوفرلورد سورفانغ يلتقط جثة ابنه ويمشي نحو فيريان",
[4208732101]="أنا... أنا... لست... بخير...",
[4209517621]="لا وقت لنضيعه!",
[4209852920]="حسناً يا رفاق، لنفعلها!",
[4210033466]="اركع أمامي يا دودة!",
[4210162794]="هل بدأت تندم على اقتحامك؟",
[4210422029]="لن ألمسني رعاع مثلك!",
[4210674349]="لكن في النهاية، أنا و$N انتصرنا بفضل ذكائنا وعملنا الجماعي. والآن لدينا هذه الجائزة الرائعة كذكرى لانتصارنا.",
[4210953564]="تركى سيطرة!",
[4210981832]="إنه يحمل الـدوم هامر!",
[4211129279]="يجب أن تجيب للعناصر، أيها الشيطان!",
[4211356291]="أنت، أيها الغريب! أنت لست من جنودي! هل ستبقى وتقف معي لمواجهة العدو؟",
[4211770483]="لا يوجد شيء نشرب هنا، ماك. اروح من هنا!",
[4211951764]="%s يفعل ميميرونز إنفيرنو.",
[4212087050]="الـهورد الحقيقي... سينتصر.",
[4212767043]="هم... من الجيد أنك أحضرت هذا لي، $N.",
[4212914385]="وقاحتك لن تُحتمل!",
[4213064226]="مفضّلتي---رااك--! أوك أوك أوك! راا-كاا!",
[4213081952]="توقف! أتوسل إليك، توقف من فضلك. أرجوك....",
[4213159871]="هؤلاء الكفار الفانون، يا سيدي! لقد اقتحموا حرمك ويسعون لسرقة أسرارك!",
[4213269648]="فقط شاهد يا عبد، غوريجيك سيتولى أمر هؤلاء الأقوياء!",
[4213349566]="سأعود إلى مقدمة المحجر. اقتل بضعة إضافيين من أجلي.",
[4213777648]="%s يتنهد بإحباط واضح.",
[4213857339]="إذن، لقد بدأ....",
[4214431990]="لم أحتج إليك أبدًا، مون. يمكنني سحق زولدراك بدونك!",
[4214525128]="هل ناديتني؟",
[4215566801]="الظلام الأبدي ينتظرك!",
[4215663541]="أنا، ويلفريد فيزلبانغ، دُعيت إلى هذه البطولة الأنيقة لأستفيد من معرفتي الواسعة بفنون الاستدعاء. أي خيار أفضل من هذا؟",
[4216018563]="هل نستطيع أخذ استراحة؟ قدمي تؤلمني وتلك... تلك الأشياء هناك تقشعر لها أبداني.",
[4216203346]="من الجيد أنك تخدمني بإخلاص. قريبًا، سيخدم الجميع الـليتش كينغ وفي النهاية، ستكافأ... طالما أنك لا تتراجع.",
[4216324981]="مذهل. لقد تمكنت من السيطرة عليها، لكنها لا تزال تحتفظ بوعيها ووظائفها. كيف فعلت ذلك؟",
[4216328819]="أحسنتم جميعًا. أرجو أن توصلونا بأمان إلى مينائنا التالي.",
[4216454646]="قاتل!",
[4216836662]="%s يدرس المخطوطة من التوايلايت توم...",
[4216922027]="واصلوا القتال! لا تتراجعوا!",
[4217401389]="لا، ليس حقًا. أردت فقط أن أرى نظرة وجهك.",
[4217650801]="أضف الـ... غير القابلة للذكر، أقصد 'الحساسات'!",
[4217796025]="%s يتحرك صعودًا في النفق!",
[4217988132]="ها قد جاء اللانهائيون! يجب أن أحافظ على الساعة الرملية آمنة. هل يمكنك المساعدة؟",
[4218066568]="لا تصدر أي صوت خلال الطقوس. خطوة خاطئة واحدة قد تعني هلاكنا...",
[4218067066]="يبدو أن ما فعله تيريون قد أضر بـالـليتش كينغ. من المؤسف أننا لا نستطيع القضاء عليه...",
[4218134267]="شكرًا مرة أخرى، $N. الآن سأستخدم هذا الإندوريوم لتعزيز سيارتي!",
[4218358001]="تلك ربما لم تعد صالحة للأكل الآن. غارفروست الغبي! سيء! سيء!",
[4218979839]="مواهواهواه! ما هذا المشهد المثير للشفقة الذي أراه أمامي؟ حسنًا، على ماذا تنتظرون؟ أنا جائع، وأنتم تبدون كأنكم قد تكونون مقبلات مقبولة!",
[4219363781]="عيد الشتاء دائمًا كان شيئًا بشريًا. رؤية الجوبلنز والأوركس يحتفلون به أمر غريب نوعًا ما.",
[4219372762]="لقد جئتم لتموتوا!",
[4219621898]="إلى أين تتجه تلك السفن يا كويمبي! قل لنا الحقيقة!",
[4219897469]="إجابة خاطئة!",
[4220609476]="لديك تقريبًا خمس ثوانٍ لتعيش.",
[4220617971]="تعالوا، أيها الأرواح - احضروا سيدكم!",
[4221762694]="أيها النور، أعطني القوة!",
[4222804847]="تم اكتشافك. سيتم استيعابك أو إقصاؤك.",
[4222883673]="ماذا؟ كيف تجرؤ على قول ذلك لي؟!",
[4222924674]="لحمي المتعفن كان يعيق طريقي فقط!",
[4223387023]="وبالنسبة للحلوى، سيكون لدينا تشيز كيك، تم إحضاره طازجًا من ستورمويند على أجنحة الملائكة...",
[4223480029]="شكري لك، أيها الغريب.",
[4223551293]="تم التحقق من أن معبد وينتر سليم.",
[4223750413]="ليت قادة العشائر يستمعون. الوحدة هي الحل الوحيد. كل الطرق الأخرى تؤدي إلى دمارنا.",
[4224741717]="يا للرعب!",
[4224771508]="اهربوا إلى التلال! انتظروا! نحن بالفعل في التلال!",
[4224858570]="لا! أستطيع أن أفعل... أفضل! أستطيع...",
[4225115511]="أيها الطيبون من غولدشاير، تعالوا واستفيدوا من أسعاري المذهلة على البضائع النادرة. لن أعود لبعض الوقت!",
[4225278771]="الجنود يقومون بعمل مهم. سلامة الناس أهم، مال، إذا كنت مهتمًا بأن يعيش زبائنك ليروا يومًا آخر.",
[4225356866]="هذا من أجل نايشا!",
[4227120070]="%s متأثر بـ عناق الأرملة!",
[4227418947]="إر... 'موك؟",
[4227437366]="تعالوا، تعالوا جميعًا! بضائع أنطونيو معروضة للبيع. قد لا أعود لوقت طويل، فتعالوا، تعالوا جميعًا.",
[4227517637]="لكنك تثابر، كما يجب علينا جميعًا. في هذه الأوقات، لا أحد غريب عن فضيلة المثابرة. في وجه اليأس والكراهية، نظل أوفياء لمعتقداتنا ونواصل القتال.",
[4227728475]="حان وقت الاختباء يا رجال الجراء! نحن قادمون إليكم... من الأفضل أن تدخلوا في تلالكم!",
[4228259214]="وباء عليك!",
[4228549912]="صحيح. قام الخالقون بتحييد التهديد الطفيلي واحتوائه داخل المضيف. تم إنشاء صياغة الإرادات وأنظمة أخرى لصنع أرضيين جدد. تم تنفيذ ضمانات، وتعيين حماة.",
[4228643451]="كل شيء ضاع يا أنكورايت! تخلَّ عن أي أمل متبقٍ.",
[4229084378]="بينما يشكو الزوار من الرطوبة العالية، أجد أنها تفيد بشرتي! البشرة الجافة غير محببة.",
[4229107499]="لقد كرهته بسبب ما فعله. كرهته بسبب العبء الذي تركه لي. لكن الآن...",
[4230235982]="كلما زاد الألم الذي نستطيع إلحاقه، كلما أسرعنا في الحصول على إجاباتنا.",
[4230882361]="آه، ها هو ذا.",
[4231003799]="قتال رائع! تحديك القادم سيكون من صفوف الكروسيد نفسها. سيتم اختبارك ضد براعتهم الكبيرة.",
[4231061980]="حسناً، لنخرج من هنا!",
[4231436054]="سوف نريك...",
[4231858937]="كن على حذرك! العدو في كمين.",
[4232125680]="اقتلوا هؤلاء الغزاة الذين يجرؤون على تدنيس مذبحنا!",
[4232588275]="غرمبلة...",
[4232824759]="أي... أين أنا؟ ما... ما هذا المكان؟",
[4233870192]="الماجستير حكماء وسيخططون لمستقبل مزدهر لنا.",
[4234050389]="حسناً، حتى الآن، طعمه مثل شيء كانت زوجتي تشربه...",
[4234269411]="لقد وصلت أخيراً إلى ليكشاير— تعالوا، تعالوا جميعاً، واستفيدوا من عروض انتونيو بيريللي الرائعة.",
[4234376524]="الحي الملكي أمامنا مباشرة، أيها الـوارتشيف.",
[4234695810]="دعني أركب هذه التروس الجيروميكانيكية ومسننات إعادة الاستقرار وسنشغل جهاز إعادة التركيب.",
[4234731469]="ممتاز، خروف تضحية آخر.",
[4235368257]="%s يتمزق إربًا وهو يُنفى من هذا العالم.",
[4235575009]="موتوا أيها البشر!",
[4237458707]="أستطيع الشعور بكراهيتك.",
[4237548087]="احموني أيتها الأرواح الشجاعة بينما أغوص في الإيميرالد نايت مير لإنقاذ ناراليكس ووضع حد لهذا الفساد!",
[4237752497]="حتى الآن، قوتي تنمو. لقد انتظرت طويلاً اليوم الذي يكتمل فيه انتقامي.",
[4237859693]="مرحبًا بك في مستقبلك — ما تبقى منه قليل...",
[4237978357]="أنا... مُحرر.",
[4238065171]="لا يوجد فرصة ثانية!",
[4238389448]="تقاتل جيدًا أيها الصغير. لقد تغلبت علي الآن. سألقاك مرة أخرى، أؤكد لك. وعندها سأكون مستعدًا أفضل!",
[4238518138]="دمرهم أيها التابع! سيدك يأمر بذلك!",
[4238623015]="حاضر سيدي.",
[4238828722]="%s يهز قضبان القفص بضعف.",
[4238906665]="إذن، لقد تم الأمر.",
[4239084135]="آآآه! قوى بئر الشمس... تنقلب... ضدي! ماذا فعلت؟ ماذا فعلت؟؟؟",
[4239459946]="فيلغارد",
[4239552634]="انهضوا يا إخوة الأرض! شاهدوا إراتيوس وهو يدمر البشر!",
[4239554506]="حتى وهي محطمة إلى قطع لا تُحصى، تضعفني البلورات من حولي... ربما كان علي ألا أستهين بالتايتنز هكذا...",
[4239664892]="%s يدرس ملاحظة سارا بالو بعناية ويطلق زفيرًا طويلًا حزينًا.",
[4239774661]="لقمات لذيذة أتت للزيارة! هل أستخدم قنابلك لطهيك؟",
[4239860869]="%s يبدأ بالبحث في ممتلكات الصيدلي.",
[4240133501]="أنا ليدي سينسترا.",
[4241059759]="يدخل الحلبة، بالادن ليس غريبًا على ساحة المعركة أو حلبة البطولة، البطل الأعظم للصليبية الفضية، إيدريك الـ بيور!",
[4241486122]="لم أعتقد أنني سأتحرر من تلك التعويذة الرهيبة!",
[4241515162]="خااائف الآن؟",
[4241755148]="فلتبدأ المحاكمة! بلودراث، اهجم!",
[4241760223]="ليس لديك أي فرصة!",
[4241938770]="وماذا يفترض بجنودنا أن يفعلوا بتلك القطعة الرديئة؟",
[4242075134]="يا ملكي، العالم سيرتعد هيبة...",
[4242100845]="أوه لا! أنا أخسر هذه!",
[4242341272]="أرجوك أيها البطل، احمِ شعبنا.",
[4243337756]="لطالما تاقت نفسي لمغامرة جيدة!",
[4243356983]="مفاجأة، أيها الحقير! ستخبرني أين أختي أو سأضع حفنة من رصاص الترويسلفر في قلب زوجتك.",
[4243478889]="المنظر من هنا رائع!",
[4245199190]="انظر إلى الجنوب الشرقي وسترى الثين على المنصة قرب قونر الـ ميرسليس عندما يظهر. دعه ينزل. ابق داخل حلقة فالهالاس.",
[4245539694]="هذا هو دالين فورجرايت. لقد هرب من لوردايرون عندما ضرب الطاعون، آخذاً حبيبته معه.",
[4245679303]="%s يستدعي تعزيزات!",
[4246122014]="استخدم رمح الصدمة لإلحاق الضرر بالأعداء. إذا وقعنا في مشكلة، استخدم إيقاف الزمن لتجميد جميع الأعداء في مكانهم، ثم اضربهم برمح الصدمة لضرر هائل!",
[4246488299]="تعال إلي، $N.",
[4246535589]="كنت عونًا كبيرًا، $R! لنخرج من هنا قبل ظهور المزيد من تلك الأشياء! سأخبر دوارفويتز أنك أديت المهمة المطلوبة منك بإتقان.",
[4247228563]="%s يتحطم إلى شظايا.",
[4247269041]="أسكتوا أفواهكم! سأضرب هذه الطبلة وهذا كل شيء!",
[4247607096]="أعط هذه للأبطال الذين جعلوا هذا ممكنًا.",
[4248022872]="...أصوغك إلى سلاح قادر على تحمل متطلبات مصير عظيم.",
[4248488630]="المزيد... لا بد أن أحصل على المزيد.",
[4248912824]="أحتاج مزيدًا من الوقت... السيد قريب...",
[4249299294]="ديدان جائعة ستتغذى على لحمك المتعفن.",
[4249613979]="بعد ذلك، سنحتاج...",
[4249841398]="هذا عمل الـسكورج!",
[4250562816]="الكلمات لا تستطيع التعبير عن امتناني، $N. شكرًا لك على لطفك.",
[4250663860]="\"أمراض السحر\"، لا. \"مصفوفات السحر\"، لا. آه، ها نحن ذا \"أسرار السحر\".",
[4250786283]="أشك في أنك ستكون محظوظًا هكذا في المرة القادمة التي تلتقي فيها بإخواني.",
[4250842274]="أوه، انظروا، إنها عربة أخرى محملة بالمتفجرات! دعنا نساعدهم في التخلص منها.",
[4250938880]="اتركه، آرثاس. انسَ هذا الأمر وقُد رجالك إلى الوطن.",
[4251191908]="ها! لا يمكنك حتى أن تتخيل عبثية جهودك.",
[4251582226]="أنقذوني أحدكم!",
[4251768954]="هالدور أوف ذا روكي كليفس! امنحني قوتك!",
[4252635004]="سأدخرها لوجبة خفيفة. لوقت لاحق.",
[4252656335]="احذروا! إننا نتعرض لهجوم!",
[4253397650]="ستواجه غضب الأجداد الكامل على ما فعلته، أيها الوحش!",
[4253628704]="كيف يمكنني أن أتوقع إنجاز أي عمل مع ذلك الشيء الذي ينشر هرطقته؟",
[4254329294]="هذا لا يُحتمل! أنا أمثل أمير نيكسوس، ولا ينبغي أن يُجعلني أنتظر! غوراموش يجب أن ينتظرني!",
[4254519977]="اسأل كيبلر عن الكنز! سكواك!",
[4254726847]="كنت أعمل لدى قراند إنكويزيتور إيسيلين! فكرتك عن الألم هي فترة ما بعد الظهيرة العادية بالنسبة لي!",
[4254960785]="في الطرف الجنوبي من الجزيرة يوجد كهف — جوف مخفي. الأدميرال الأعظم حبس نفسه هناك، يستعد للمعركة النهائية ضد الـليتش كينغ.",
[4255053087]="%s يتلاعب بدروعه، ويبدو غير مرتاح من نبرة النقاش.",
[4255074429]="لقد تم مالونتك!",
[4255213441]="أعجبك ذلك؟ أكيد لا! أكيد لا لأنك ميت! هههه!",
[4255458254]="أوه... نقطة جيدة. ماذا عن هناك؟ تبدو نظيفة... نوعًا ما.",
[4256001619]="هاها! ظننت أنك انتهيت، أليس كذلك؟",
[4256043621]="أعظم تحدٍ لك ينتظرك. لي-غارديان إريقوس هو تنين أزرق ذو قوة هائلة. ستجده يحلق فوق أعلى حلقة.",
[4256186885]="<تنهد> يبدو أنني عالق في هذا إلى الأبد...",
[4256416616]="من السخرية أنني أكره المحيط لكني أحب الشاطئ.",
[4256722061]="آسف، هولدار... لكن يبدو أنني ضللتك.",
[4257197337]="لا... أنت لست موراي، لكني أشعر أنكما التقيتما. عندما تراها، أخبرها أنني نجوت من التحطم، فقط لأُقتل على يد المتسللين.",
[4257305284]="لن أذهب وحدي، تاليريس، وهذا نهائي. سأنتظر هنا المجموعة التالية من الحجاج وأنطلق معهم عندما يغادرون.",
[4257338615]="سأتدرب وأصبح محاربًا مثل والدي!",
[4257349845]="سندان بور يلتهمه نار التوسكار!",
[4257748718]="%s يهمس لـ$N بسر فتح صندوقه الحديدي.",
[4258126968]="خنزير نَشّاف!",
[4258141296]="مهمتك الأولى هي تدمير آلات الموت داخل هذه الآلة الخبيثة للأرواح وتمهيد الطريق لجنودنا.",
[4258500636]="أخبرنا! أين يختبئ زعيمك؟",
[4258529183]="%s يشير بهدوء إلى هدف الأورك...",
[4259669471]="الجيش يتقدم نحو كنيسة لايتس هوب.",
[4260076737]="اهتم بهذا، أردونيس!",
[4260338231]="دع النور يدخل، غودفري غودارد!",
[4260410090]="هل هذه هي النهاية؟ إذا أوقفنا هذا الوحش الآن، هل النصر مضمون عند راثغيت؟",
[4260641427]="مرحبًا، ماذا تريد؟",
[4261316502]="ثاين باناهوق يعود إلى فالهالاس لأول مرة منذ زمن ليثبت أن الفرايكول هم الوحيدون المستحقون للقتال داخل حلقتها المقدسة. هل سيثبت $N خطأه؟",
[4261477338]="آه، لقد جئت في الوقت المناسب. الطقوس على وشك البدء!",
[4261639632]="اصمتوا، أيها الحمقى. لو أردت قتلكم، لكنتم ميتين بالفعل.",
[4261949557]="مزقوه إربًا!",
[4262186398]="أحداث مأساوية وقعت في نورثريند. الـوارتشيف يفعل كل ما بوسعه لإبقائنا آمنين.",
[4262250638]="$N، سأتعرف على هذا الوجه في أي مكان... ماذا... ماذا فعلوا بك، $N؟",
[4262299521]="%s يستدعي جيوش الـسكورج الجبارة!",
[4262451890]="وإذا سمعت أنكم أيها الأغبياء اشتكيتم لـنازقريل مرة أخرى، فسيكون أحدكم هو التالي الذي أقدمه...",
[4262629842]="حداد.",
[4263231565]="إيونار، خادمك ينادي ببركتك!",
[4263272212]="باشر بالعمل فورًا، $N!",
[4263520233]="أبطال! لم أعد أستطيع كبحها أكثر.",
[4263704925]="أسهل مما توقعت... خاتم ثورادين أصبح كاملًا، مجددًا.",
[4263963014]="تواجه صعوبة في البقاء على الأرض؟",
[4264632517]="انظروا! ما الذي تفعله فروست ويرم هنا؟ إنها تتجه إلينا مباشرة.",
[4265209574]="أنت فقط تؤجل المحتوم!",
[4265316939]="أنا متأكد من أنني سأحصل على تكريم عند عودتنا. ربما تكبدنا بعض الخسائر، لكن بشكل عام أعتقد أننا قمنا بعمل جيد، ألا توافقينني يا فالانا؟",
[4265427139]="سنرى بخصوص ذلك.",
[4266727603]="وحش آخر مصاب تم تدميره!",
[4266952605]="لن تهرب.",
[4267038171]="يجب أن نوقف تقدمهم! خذوا مواقعكم!",
[4267088215]="إذا لم تتوقفوا عن هذه المهمة الحمقاء، فستموتون!",
[4267113750]="جراء وقحون! لقد اندفعتم بتهور نحو موتكم! انظروا الآن، السيد يتحرك!",
[4268016026]="أيها... نصف أحمق! لقد فعلتها حقًا هذه المرة. سأضطر لجعل الأمر يبدو وكأن ساقك مكسورة.",
[4268311797]="الآن، لنرى... إذا كنت صائبًا، إذن... همم...",
[4268688937]="سنشرب بيرةك القوية والخفيفة،",
[4269286198]="يجب أن تسأل \"هل ذلك الروق الذي خلفي سيقتلني؟\"",
[4270628054]="وأخيرًا، نضع كوركي!",
[4270972722]="في أوقات كهذه أتمنى لو كان لدي وقت إعادة شحن أطول.",
[4272042218]="أبي! أبي، لقد أنقذت!",
[4272145435]="شكرًا لك، $N. الآن روحي ستستقر أخيرًا.",
[4272335529]="توسل من أجل حياتك الحقيرة!",
[4272487294]="أحيانًا كبار اللسان يحاولون يجيبوا كريستالات. ليس هسا لأنهم ما يحبوا لما نقتلهم.",
[4272571943]="شكرًا لك.",
[4272698125]="أين ذاك الكلب؟",
[4272880826]="يا نور، أعطني قوة.",
[4273164865]="الـليتش كينغ يمد يده بعيدًا الآن... بلا خوف يدوس على أقدس أراضي كل الأسراب. ينوي إجبارنا على التحرك.",
[4273188980]="سأقلب عالمك... رأسًا... على عقب.",
[4273958251]="النور يطهرك!",
[4274317596]="أنت صرت هو هسا، يا أخ!",
[4274613134]="%s يفقس!",
[4274855673]="الـسكورج سينتصر!",
[4274902694]="هذه المنطقة ستدمر نفسها في ست دقائق.",
[4275340952]="صداقتنا انتهت!",
[4275884703]="أخي... نعم... لدي إخوة...",
[4275977156]="لنرى إذا كان بإمكاننا معرفة من أين تأتي هذه الـتروقز.... ونوقف الغزو!",
[4276481152]="%s يبدأ في الصناعة...",
[4277670328]="السيد سيعود من ستورمويند قريباً....",
[4278304014]="آه، المزيد من الجوهر للقبض...",
[4279558791]="%s يتراجع بينما يتلألأ جلده.",
[4279818126]="صحيح. شاهد هذا، $R.",
[4280679085]="أتمنى أن يخدمك جيدًا، $N.",
[4281045369]="رعب!",
[4281305017]="حسنًا، هذا غير صحيح. المخلوق صغير جدًا. دعنا نرى ماذا ستفعل الدفعة الثالثة من كيفر.",
[4281342886]="آه، أحب رائحة ستونارد! رائحتها مثل... مثل... عرق الأوركس. والعفن. ومع ذلك، مجتمعة، يمكن أن يكون التأثير لطيفًا جدًا! إنها رائحة مكتسبة.",
[4281395446]="في الواقع، من الأفضل أن تبقى هنا. ستكون فقط في طريقي...",
[4282053588]="أيامك انتهت.",
[4282066361]="%s يرفع رأسه في الهواء، وكأنه يستمع لشيء ما.",
[4282480263]="%s يشم الأرض...",
[4282859094]="%s تميل رأسها قليلاً نحو الحارسين ترحيباً بهما.",
[4282964180]="الغضب... الكراهية... هذه أدوات يمكنني استخدامها.",
[4283165241]="تم القضاء على الهدف.",
[4283440141]="لقد تم إنهاؤك.",
[4283747940]="لقد كانت خدمتك لا تستطيع بثمن في تحقيق خطة السيد. أتمنى أن تزداد قوتك إلى الأبد....",
[4284830011]="باه! هذا ليس ممتعًا!",
[4285239761]="مثير جدًا للاهتمام. لكن إذا كان الأمر كذلك، فإن نظريتي خاطئة. يجب أن أعيد قراءة الأقسام الأخرى لأرى ما فاتني.",
[4285435596]="أوبس يريد بعض ذهب كويرجو... مع دودة.",
[4285859356]="هاليون! أنا....",
[4286094324]="أستطيع الرؤية جيدًا من خلال هذا الضباب، لكنني أعرف تلك الرائحة في أي مكان! مت أيها الغول القذر!",
[4286258822]="أطع قوانين سيلفرمون. عدم الامتثال سيؤدي إلى الإنهاء.",
[4286588074]="كيف من المفترض أن أوصل كل هذه الرسائل؟",
[4286608245]="همم... عملات قديمة... مجوهرات قبيحة...",
[4286970510]="%s يومئ برأسه شاكرًا.",
[4287167153]="استمتع بالخريف!",
[4287423744]="%s يبدأ بالبحث في حقيبته...",
[4287837173]="صخرتي! اكسر الحجر! أسرع! أسرع!",
[4288079286]="مممممم...",
[4288445087]="هاهاها، حرأسكم لا يقارنون بالـسكورج!",
[4288548108]="أرواح أبطالك الساقطين ستكون لي يا فوردرينغ.",
[4288701438]="النصر للألدور! لقد هُزمت دراغونماو!",
[4288979288]="سيلفر وينغ ملكنا!",
[4289466757]="مساعدة! أعتقد أن هذا المخلوق قد يكون صعبًا جدًا عليّ وحدي.",
[4289870366]="ألست محظوظًا؟",
[4290298620]="كل جهودكم ذهبت سدى، فقد بدأ استنزاف شجرة العالم بالفعل! قريبًا، سيتوقف قلب عالمكم عن النبض!",
[4290786573]="لو كان والدي على قيد الحياة، لكان أطفأ النيران!",
[4291093097]="قلت لك إنها مهمة حمقاء!",
[4291364413]="اهدأ!",
[4291700326]="حسنًا! حسنًا! نحن نستسلم... فقط ضعوا أسلحتكم، سأتعاون!",
[4291708033]="أنا بذا أدمر هذه الأدوات الشريرة! من أجل الـهورد!",
[4291943152]="موجو التـرول هو أقوى موجو!",
[4292145098]="هل هذا أفضل ما يمكنك فعله؟",
[4292992490]="أيها الإخوة والأخوات، لقد ذهبت إلى الأرض الموعودة. لقد تذوقت الطاقة السامية. لقد شعرت بالنشوة - نشوة غامرة وشاملة جعلتني أتساءل إن كنت قد عثرت على أحلام الآلهة.",
[4294132158]="آشبرينغر...",
[4294359374]="أبي... لكن... كيف؟",
[4294709747]="لدينا تقارير من كشاف في الميدان أن أحد الـسيناريون درويدز قد أُسر في فايروينغ بوينت.",
[4294884919]="الموت والثناء للـليتش كينغ!",
[258782503] = "سيسمح لأنقياء القلب بالبقاء في نيو أفالون. أما من يجدهم المحققون محرومين من النور المقدس، فسيُطردون.",
}
